INSERT INTO `ardaccounts_templates` (`id`, `project_id`, `template_type`, `template_name`, `template_content`, `is_active`, `created`, `modified`) VALUES
(1, 22, 'voucher', 'Print voucher', '<!DOCTYPE html>\r\n<html lang=\"en\">\r\n<head>\r\n    <meta charset=\"UTF-8\">\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n    <title>{{company_name}} - Payment Voucher</title>\r\n    <script src=\"https://cdn.tailwindcss.com\"></script>\r\n    <style>\r\n        @import url(\'https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800;900&family=JetBrains+Mono:wght@500&display=swap\');\r\n        \r\n        :root {\r\n            --wv-black: #000000;\r\n        }\r\n\r\n        body {\r\n            font-family: \'Inter\', sans-serif;\r\n            background-color: #f0f2f5;\r\n            margin: 0;\r\n            padding: 20px;\r\n            display: flex;\r\n            flex-direction: column;\r\n            align-items: center;\r\n        }\r\n\r\n        .check-container {\r\n            background: white;\r\n            width: 1100px;\r\n            height: 520px;\r\n            padding: 40px 40px 40px 100px;\r\n            border: 1px solid #e5e7eb;\r\n            position: relative;\r\n            overflow: hidden;\r\n            display: flex;\r\n            flex-direction: column;\r\n            background-image: radial-gradient(#f3f4f6 1px, transparent 1px);\r\n            background-size: 20px 20px;\r\n        }\r\n\r\n        .punch-margin-guide {\r\n            position: absolute;\r\n            left: 0;\r\n            top: 0;\r\n            bottom: 0;\r\n            width: 80px;\r\n            border-right: 1px dashed #d1d5db;\r\n            background: #fafafa;\r\n            display: flex;\r\n            flex-direction: column;\r\n            justify-content: center;\r\n            align-items: center;\r\n            gap: 150px;\r\n        }\r\n\r\n        .punch-hole-target {\r\n            width: 12px;\r\n            height: 12px;\r\n            border: 1px solid #e5e7eb;\r\n            border-radius: 50%;\r\n        }\r\n\r\n        .input-line {\r\n            border-bottom: 1px solid #000;\r\n            flex-grow: 1;\r\n            margin-left: 10px;\r\n            padding-bottom: 2px;\r\n            font-weight: 600;\r\n            min-height: 28px;\r\n        }\r\n\r\n        .date-section {\r\n            display: flex;\r\n            flex-direction: column;\r\n            align-items: flex-end;\r\n        }\r\n\r\n        .date-box {\r\n            display: flex;\r\n            border-top: 1.5px solid #000;\r\n            border-bottom: 1.5px solid #000;\r\n            border-left: 1.5px solid #000;\r\n        }\r\n\r\n        .date-cell {\r\n            width: 32px;\r\n            height: 35px;\r\n            border-right: 1.5px solid #000;\r\n            display: flex;\r\n            align-items: center;\r\n            justify-content: center;\r\n            font-size: 18px;\r\n            font-weight: 800;\r\n            background: white;\r\n        }\r\n\r\n        .date-labels {\r\n            display: flex;\r\n            width: 100%;\r\n            justify-content: space-around;\r\n            padding-top: 4px;\r\n        }\r\n\r\n        .date-label-item {\r\n            width: 32px;\r\n            text-align: center;\r\n            font-size: 10px;\r\n            font-weight: 700;\r\n            color: #666;\r\n            text-transform: uppercase;\r\n        }\r\n\r\n        .amount-box {\r\n            border: 1.5px solid #000;\r\n            height: 50px;\r\n            width: 220px;\r\n            display: flex;\r\n            align-items: center;\r\n            padding: 0 15px;\r\n            font-weight: 900;\r\n            font-size: 1.3rem;\r\n            background: #fff;\r\n        }\r\n\r\n        .barcode-footer {\r\n            position: absolute;\r\n            bottom: 15px;\r\n            left: 100px;\r\n            right: 0;\r\n            display: flex;\r\n            flex-direction: column;\r\n            align-items: center;\r\n            justify-content: center;\r\n        }\r\n\r\n        @media print {\r\n            body { background: white; padding: 0; }\r\n            .check-container {\r\n                box-shadow: none;\r\n                border: 1px solid #ccc;\r\n                margin: 0;\r\n            }\r\n            .punch-margin-guide {\r\n                border-right: 1px solid #eee;\r\n            }\r\n            .no-print { display: none; }\r\n        }\r\n    </style>\r\n</head>\r\n<body>\r\n\r\n    <div class=\"w-[1100px] mb-4 flex justify-end no-print\">\r\n        <button onclick=\"window.print()\" class=\"bg-black text-white px-6 py-2 rounded-lg font-bold flex items-center gap-2 hover:bg-gray-800 transition-all shadow-lg\">\r\n            <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"6 9 6 2 18 2 18 9\"></polyline><path d=\"M6 18H4a2 2 0 0 1-2-2v-5a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2v5a2 2 0 0 1-2 2h-2\"></path><rect x=\"6\" y=\"14\" width=\"12\" height=\"8\"></rect></svg>\r\n            Print Voucher\r\n        </button>\r\n    </div>\r\n\r\n    <div class=\"check-container shadow-2xl\">\r\n        <div class=\"punch-margin-guide no-print\">\r\n            <div class=\"punch-hole-target\"></div>\r\n            <div class=\"punch-hole-target\"></div>\r\n        </div>\r\n\r\n        <div class=\"flex justify-between items-start mb-12\">\r\n            <div class=\"flex items-center gap-4 w-1/3\">\r\n                <div class=\"w-20 h-20 shrink-0\">\r\n                    <svg viewBox=\"0 0 500 500\" class=\"w-full h-full\">\r\n                        <circle cx=\"250\" cy=\"270\" r=\"120\" fill=\"none\" stroke=\"black\" stroke-width=\"2\"/>\r\n                        <path d=\"M250 100 V350 M210 160 V350 M290 160 V350 M170 220 V350 M330 220 V350\" stroke=\"black\" stroke-width=\"12\" stroke-linecap=\"round\"/>\r\n                        <rect x=\"230\" y=\"270\" width=\"40\" height=\"40\" fill=\"black\" />\r\n                        <text x=\"250\" y=\"440\" font-family=\"Inter\" font-weight=\"900\" font-size=\"64\" text-anchor=\"middle\" letter-spacing=\"2\">{{company_name}}</text>\r\n                    </svg>\r\n                </div>\r\n                <div class=\"border-l-2 border-black pl-4\">\r\n                    <h1 class=\"text-xl font-black uppercase leading-tight tracking-widest\">{{company_name}}</h1>\r\n                    <p class=\"text-[10px] text-gray-500 uppercase font-bold\">Estate Management & Dev.</p>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"flex-grow flex justify-center pt-2\">\r\n                <div class=\"px-8 py-1\">\r\n                    <h2 class=\"text-3xl font-black tracking-[0.4em] uppercase underline underline-offset-8\">{{voucher_type}}</h2>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"w-1/3 date-section\">\r\n                <div class=\"mb-2 flex items-center gap-2\">\r\n                    <span class=\"text-[10px] font-bold text-gray-400 uppercase tracking-widest\">Voucher No.</span>\r\n                    <span class=\"font-mono font-bold text-lg\">#{{voucher_no}}</span>\r\n                </div>\r\n                <div>\r\n                    <div class=\"date-box\">\r\n                        <div class=\"date-cell\">{{d1}}</div>\r\n                        <div class=\"date-cell\">{{d2}}</div>\r\n                        <div class=\"date-cell\">{{d3}}</div>\r\n                        <div class=\"date-cell\">{{d4}}</div>\r\n                        <div class=\"date-cell\">{{d5}}</div>\r\n                        <div class=\"date-cell\">{{d6}}</div>\r\n                        <div class=\"date-cell\">{{d7}}</div>\r\n                        <div class=\"date-cell\">{{d8}}</div>\r\n                    </div>\r\n                    <div class=\"date-labels\">\r\n                        <div class=\"date-label-item\">D</div>\r\n                        <div class=\"date-label-item\">D</div>\r\n                        <div class=\"date-label-item\">M</div>\r\n                        <div class=\"date-label-item\">M</div>\r\n                        <div class=\"date-label-item\">Y</div>\r\n                        <div class=\"date-label-item\">Y</div>\r\n                        <div class=\"date-label-item\">Y</div>\r\n                        <div class=\"date-label-item\">Y</div>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n\r\n        <div class=\"space-y-8\">\r\n            <div class=\"flex items-end\">\r\n                <span class=\"text-sm font-bold uppercase tracking-widest whitespace-nowrap\">Pay</span>\r\n                <div class=\"input-line text-xl uppercase px-4 font-black\">{{pay_to}}</div>\r\n                <span class=\"text-xs font-bold uppercase ml-2 text-gray-400 whitespace-nowrap\">Or Bearer</span>\r\n            </div>\r\n\r\n            <div class=\"flex items-start gap-4\">\r\n                <div class=\"flex-grow space-y-8\">\r\n                    <div class=\"flex items-end\">\r\n                        <span class=\"text-sm font-bold uppercase tracking-widest whitespace-nowrap\">Sum Of</span>\r\n                        <div class=\"input-line text-base italic px-4 font-medium\">{{amount_words}}</div>\r\n                    </div>\r\n                    <div class=\"flex items-end\">\r\n                        <span class=\"text-sm font-bold uppercase tracking-widest whitespace-nowrap\">Narration</span>\r\n                        <div class=\"input-line text-sm font-medium px-4 text-gray-600\">{{narration}}</div>\r\n                    </div>\r\n                </div>\r\n                <div class=\"amount-box mt-1\">\r\n                    <span class=\"text-sm mr-2 font-black\">{{currency_symbol}}</span>\r\n                    <span>{{amount_number}}</span>\r\n                </div>\r\n            </div>\r\n        </div>\r\n\r\n        <div class=\"mt-auto flex justify-between items-end pb-12\">\r\n            <div class=\"w-64 border-2 border-black p-2.5 h-20 flex flex-col justify-between bg-white\">\n                    <div class=\"flex justify-between items-center border-b border-gray-200 pb-0.5\">\n                        <span class=\"text-[9px] font-black uppercase text-gray-500 tracking-widest\">{{account_box_label}}</span>\n                        <span class=\"text-[10px] font-mono font-bold text-gray-700 tracking-wider\">A/C: <strong class=\"text-black font-extrabold\">{{account_code}}</strong></span>\n                    </div>\n                    <div class=\"flex flex-col justify-end\">\n                        <span class=\"font-mono font-bold tracking-[0.2em] text-lg text-black leading-tight\">{{account_display_no}}</span>\n                        <span class=\"text-[9px] font-bold text-gray-500 uppercase tracking-wider truncate mt-0.5\">{{account_head_name}}</span>\n                    </div>\n                </div>\r\n\r\n            <div class=\"flex gap-12\">\r\n                <div class=\"text-center\">\r\n                    <div class=\"w-52 border-b-2 border-black mb-2\"></div>\r\n                    <p class=\"text-[10px] font-black uppercase tracking-[0.2em]\">Authorized Signatory</p>\r\n                </div>\r\n                <div class=\"text-center\">\r\n                    <div class=\"w-52 border-b-2 border-black mb-2\"></div>\r\n                    <p class=\"text-[10px] font-black uppercase tracking-[0.2em]\">Chairman / Director</p>\r\n                </div>\r\n            </div>\r\n        </div>\r\n\r\n        <div class=\"barcode-footer\">\r\n            {{barcode_svg}}\r\n            <p class=\"mt-1 text-[9px] font-mono font-bold tracking-[0.25em] text-gray-700 uppercase font-extrabold\">{{barcode_text}}</p>\r\n        </div>\r\n    </div>\r\n\r\n</body>\r\n</html>\r\n', 0, '2026-03-27 14:43:36', '2026-11-23 16:39:52'),
(2, 22, 'salary', 'Salary Sli[p', '<!doctype html><html><head><meta charset=\"utf-8\"><title>Salary Slip</title><style>body{font-family:Arial,Helvetica,sans-serif;background:#f5f7fb;margin:0;padding:24px;color:#0f172a}.slip{max-width:900px;margin:0 auto;background:#fff;border:1px solid #dbe3ee;border-radius:14px;overflow:hidden}.top{padding:18px 22px;background:linear-gradient(135deg,#0f172a,#1e293b);color:#fff}.top h1{margin:0;font-size:24px}.top p{margin:4px 0 0;opacity:.9}.meta{display:grid;grid-template-columns:1fr 1fr;gap:12px;padding:16px 22px;border-bottom:1px solid #edf2f9}.box{background:#f8fbff;border:1px solid #dbe3ee;border-radius:10px;padding:10px}.box span{display:block;font-size:11px;color:#64748b;text-transform:uppercase;letter-spacing:.08em}.box strong{display:block;margin-top:6px;font-size:15px}.tbl{width:100%;border-collapse:collapse}.tbl th,.tbl td{border:1px solid #dbe3ee;padding:10px 12px;font-size:13px}.tbl th{background:#f8fbff;text-align:left}.right{text-align:right}.foot{padding:14px 22px;color:#64748b;font-size:12px}</style></head><body><div class=\"slip\"><div class=\"top\"><h1>{{company_name}}</h1><p>Salary Slip - {{payroll_month}}</p></div><div class=\"meta\"><div class=\"box\"><span>Employee</span><strong>{{employee_name}}</strong></div><div class=\"box\"><span>Code</span><strong>{{employee_code}}</strong></div><div class=\"box\"><span>Department / Designation</span><strong>{{department}} / {{designation}}</strong></div><div class=\"box\"><span>Payment Date</span><strong>{{payment_date}}</strong></div></div><table class=\"tbl\"><thead><tr><th>Earnings</th><th class=\"right\">Amount</th><th>Deductions</th><th class=\"right\">Amount</th></tr></thead><tbody><tr><td>Base Salary</td><td class=\"right\">{{base_salary}}</td><td>Deductions</td><td class=\"right\">{{deductions}}</td></tr><tr><td>Bonus</td><td class=\"right\">{{bonus}}</td><td>Paid Amount</td><td class=\"right\">{{paid_amount}}</td></tr><tr><td>Overtime ({{overtime_hours}} hrs)</td><td class=\"right\">{{overtime_amount}}</td><td>Due Amount</td><td class=\"right\">{{due_amount}}</td></tr><tr><th>Net Pay</th><th class=\"right\">{{net_pay}}</th><th>Status</th><th class=\"right\">{{status}}</th></tr></tbody></table><div class=\"meta\"><div class=\"box\"><span>Payment Method</span><strong>{{payment_method}}</strong></div><div class=\"box\"><span>Reference No</span><strong>{{reference_no}}</strong></div><div class=\"box\"><span>Debit Account</span><strong>{{debit_account}}</strong></div><div class=\"box\"><span>Generated</span><strong>{{generated_at}}</strong></div></div><div class=\"foot\">Payroll Month: {{payroll_month}} | Working Days: {{working_days}} | Present Days: {{present_days}}</div></div></body></html>', 1, '2026-03-27 14:44:20', '2026-03-28 02:11:21'),
(3, 22, 'stock_purchase', 'Stock Purchase', '<!doctype html>\r\n<html lang=\"en\">\r\n<head>\r\n  <meta charset=\"utf-8\">\r\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n  <title>{{company_name}} - Stock Purchase Invoice</title>\r\n  <style>\r\n    :root {\r\n      --ink: #0f172a;\r\n      --soft: #64748b;\r\n      --line: #d9e3f1;\r\n      --bg: #f8fbff;\r\n      --accent: #0f9d63;\r\n    }\r\n    * { box-sizing: border-box; }\r\n    body {\r\n      margin: 0;\r\n      padding: 20px;\r\n      background: #eef3fa;\r\n      font-family: Inter, \"Segoe UI\", Arial, sans-serif;\r\n      color: var(--ink);\r\n    }\r\n    .invoice {\r\n      max-width: 980px;\r\n      margin: 0 auto;\r\n      background: #fff;\r\n      border: 1px solid var(--line);\r\n      border-radius: 18px;\r\n      overflow: hidden;\r\n    }\r\n    .head {\r\n      display: flex;\r\n      justify-content: space-between;\r\n      gap: 20px;\r\n      padding: 20px 24px;\r\n      background: linear-gradient(135deg, #0f172a, #1e293b);\r\n      color: #fff;\r\n    }\r\n    .brand h1 {\r\n      margin: 0;\r\n      font-size: 28px;\r\n      letter-spacing: -0.02em;\r\n    }\r\n    .brand p {\r\n      margin: 5px 0 0;\r\n      font-size: 12px;\r\n      opacity: 0.9;\r\n      text-transform: uppercase;\r\n      letter-spacing: 0.08em;\r\n    }\r\n    .meta {\r\n      min-width: 280px;\r\n      background: rgba(255, 255, 255, 0.12);\r\n      border: 1px solid rgba(255, 255, 255, 0.22);\r\n      border-radius: 12px;\r\n      padding: 10px 12px;\r\n    }\r\n    .meta-row {\r\n      display: flex;\r\n      justify-content: space-between;\r\n      gap: 10px;\r\n      padding: 5px 0;\r\n      font-size: 12px;\r\n    }\r\n    .meta-row span { opacity: 0.85; }\r\n    .body {\r\n      padding: 20px 24px 16px;\r\n    }\r\n    .grid {\r\n      display: grid;\r\n      grid-template-columns: repeat(2, minmax(0, 1fr));\r\n      gap: 14px;\r\n      margin-bottom: 16px;\r\n    }\r\n    .card {\r\n      border: 1px solid var(--line);\r\n      border-radius: 12px;\r\n      padding: 12px 14px;\r\n      background: var(--bg);\r\n    }\r\n    .card h3 {\r\n      margin: 0 0 8px;\r\n      font-size: 11px;\r\n      text-transform: uppercase;\r\n      letter-spacing: 0.1em;\r\n      color: var(--soft);\r\n    }\r\n    .card p {\r\n      margin: 4px 0;\r\n      font-size: 14px;\r\n      font-weight: 600;\r\n    }\r\n    table {\r\n      width: 100%;\r\n      border-collapse: collapse;\r\n      margin-top: 6px;\r\n      border: 1px solid var(--line);\r\n    }\r\n    th, td {\r\n      border: 1px solid var(--line);\r\n      padding: 10px 12px;\r\n      text-align: left;\r\n      font-size: 13px;\r\n    }\r\n    th {\r\n      background: #f1f6ff;\r\n      font-size: 11px;\r\n      text-transform: uppercase;\r\n      letter-spacing: 0.08em;\r\n      color: #475569;\r\n    }\r\n    .right { text-align: right; }\r\n    .total-row th {\r\n      background: #ecfdf5;\r\n      color: #065f46;\r\n      font-size: 14px;\r\n    }\r\n    .note {\r\n      margin-top: 14px;\r\n      border: 1px solid var(--line);\r\n      border-radius: 12px;\r\n      padding: 12px 14px;\r\n      background: #fff;\r\n      font-size: 13px;\r\n      color: #334155;\r\n      min-height: 60px;\r\n    }\r\n    .foot {\r\n      margin-top: 16px;\r\n      padding: 14px 24px;\r\n      border-top: 1px solid var(--line);\r\n      color: var(--soft);\r\n      font-size: 12px;\r\n      display: flex;\r\n      justify-content: space-between;\r\n      gap: 10px;\r\n      flex-wrap: wrap;\r\n      background: #f8fafc;\r\n    }\r\n    .no-print {\r\n      max-width: 980px;\r\n      margin: 0 auto 12px;\r\n      display: flex;\r\n      justify-content: flex-end;\r\n    }\r\n    .btn {\r\n      border: 0;\r\n      border-radius: 10px;\r\n      padding: 10px 16px;\r\n      background: #0f172a;\r\n      color: #fff;\r\n      font-weight: 700;\r\n      cursor: pointer;\r\n    }\r\n    @media print {\r\n      @page { size: A4 portrait; margin: 8mm; }\r\n      body { background: #fff; padding: 0; }\r\n      .no-print { display: none; }\r\n      .invoice { max-width: none; margin: 0; border-radius: 0; }\r\n    }\r\n  </style>\r\n</head>\r\n<body>\r\n  <div class=\"no-print\">\r\n    <button class=\"btn\" onclick=\"window.print()\">Print Invoice</button>\r\n  </div>\r\n  <div class=\"invoice\">\r\n    <div class=\"head\">\r\n      <div class=\"brand\">\r\n        <h1>{{company_name}}</h1>\r\n        <p>Construction Stock Purchase Invoice</p>\r\n      </div>\r\n      <div class=\"meta\">\r\n        <div class=\"meta-row\"><span>Invoice No</span><strong>{{invoice_no}}</strong></div>\r\n        <div class=\"meta-row\"><span>Invoice Date</span><strong>{{entry_date}}</strong></div>\r\n        <div class=\"meta-row\"><span>Generated</span><strong>{{generated_at}}</strong></div>\r\n      </div>\r\n    </div>\r\n    <div class=\"body\">\r\n      <div class=\"grid\">\r\n        <div class=\"card\">\r\n          <h3>Vendor Information</h3>\r\n          <p>{{vendor_name}}</p>\r\n          <p>Phone: {{vendor_phone}}</p>\r\n          <p>Address: {{vendor_address}}</p>\r\n        </div>\r\n        <div class=\"card\">\r\n          <h3>Order / Site Details</h3>\r\n          <p>Material: {{material_type}}</p>\r\n          <p>Unit: {{unit_type}}</p>\r\n          <p>Site: {{site_name}}</p>\r\n          <p>Debit Account: {{debit_account}}</p>\r\n        </div>\r\n      </div>\r\n      <table>\r\n        <thead>\r\n          <tr>\r\n            <th>Description</th>\r\n            <th class=\"right\">Qty</th>\r\n            <th>Unit</th>\r\n            <th class=\"right\">Unit Cost</th>\r\n            <th class=\"right\">Line Total</th>\r\n          </tr>\r\n        </thead>\r\n        <tbody>\r\n          <tr>\r\n            <td>{{material_type}} Purchase</td>\r\n            <td class=\"right\">{{quantity}}</td>\r\n            <td>{{unit_type}}</td>\r\n            <td class=\"right\">{{unit_cost}}</td>\r\n            <td class=\"right\">{{total_cost}}</td>\r\n          </tr>\r\n        </tbody>\r\n        <tfoot>\r\n          <tr class=\"total-row\">\r\n            <th colspan=\"4\" class=\"right\">Invoice Total</th>\r\n            <th class=\"right\">{{total_cost}}</th>\r\n          </tr>\r\n        </tfoot>\r\n      </table>\r\n      <div class=\"note\">\r\n        <strong>Notes:</strong> {{notes}}\r\n      </div>\r\n    </div>\r\n    <div class=\"foot\">\r\n      <div>Authorized By: _____________________</div>\r\n      <div>{{company_name}} | {{total_cost}}</div>\r\n    </div>\r\n  </div>\r\n</body>\r\n</html>', 1, '2026-03-27 14:44:48', '2026-03-27 14:44:48'),
(4, 22, 'voucher', 'WhiteVillas', '<!DOCTYPE html>\r\n<html lang=\"en\">\r\n<head>\r\n    <meta charset=\"UTF-8\">\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n    <title>{{agency_name}} - Payment Voucher</title>\r\n    <script src=\"https://cdn.tailwindcss.com\"></script>\r\n    <style>\r\n        @import url(\'https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800;900&family=JetBrains+Mono:wght@500&display=swap\');\r\n        \r\n        :root {\r\n            --wv-black: #000000;\r\n        }\r\n\r\n        body {\r\n            font-family: \'Inter\', sans-serif;\r\n            background-color: #f0f2f5;\r\n            margin: 0;\r\n            padding: 20px;\r\n            display: flex;\r\n            flex-direction: column;\r\n            align-items: center;\r\n        }\r\n\r\n        .check-container {\r\n            background: white;\r\n            width: 1100px;\r\n            height: 520px;\r\n            padding: 40px 40px 40px 100px;\r\n            border: 1px solid #e5e7eb;\r\n            position: relative;\r\n            overflow: hidden;\r\n            display: flex;\r\n            flex-direction: column;\r\n            background-image: radial-gradient(#f3f4f6 1px, transparent 1px);\r\n            background-size: 20px 20px;\r\n        }\r\n\r\n        .punch-margin-guide {\r\n            position: absolute;\r\n            left: 0;\r\n            top: 0;\r\n            bottom: 0;\r\n            width: 80px;\r\n            border-right: 1px dashed #d1d5db;\r\n            background: #fafafa;\r\n            display: flex;\r\n            flex-direction: column;\r\n            justify-content: center;\r\n            align-items: center;\r\n            gap: 150px;\r\n        }\r\n\r\n        .punch-hole-target {\r\n            width: 12px;\r\n            height: 12px;\r\n            border: 1px solid #e5e7eb;\r\n            border-radius: 50%;\r\n        }\r\n\r\n        .input-line {\r\n            border-bottom: 1px solid #000;\r\n            flex-grow: 1;\r\n            margin-left: 10px;\r\n            padding-bottom: 2px;\r\n            font-weight: 600;\r\n            min-height: 28px;\r\n        }\r\n\r\n        .date-section {\r\n            display: flex;\r\n            flex-direction: column;\r\n            align-items: flex-end;\r\n        }\r\n\r\n        .date-box {\r\n            display: flex;\r\n            border-top: 1.5px solid #000;\r\n            border-bottom: 1.5px solid #000;\r\n            border-left: 1.5px solid #000;\r\n        }\r\n\r\n        .date-cell {\r\n            width: 32px;\r\n            height: 35px;\r\n            border-right: 1.5px solid #000;\r\n            display: flex;\r\n            align-items: center;\r\n            justify-content: center;\r\n            font-size: 18px;\r\n            font-weight: 800;\r\n            background: white;\r\n        }\r\n\r\n        .date-labels {\r\n            display: flex;\r\n            width: 100%;\r\n            justify-content: space-around;\r\n            padding-top: 4px;\r\n        }\r\n\r\n        .date-label-item {\r\n            width: 32px;\r\n            text-align: center;\r\n            font-size: 10px;\r\n            font-weight: 700;\r\n            color: #666;\r\n            text-transform: uppercase;\r\n        }\r\n\r\n        .amount-box {\r\n            border: 1.5px solid #000;\r\n            height: 50px;\r\n            width: 220px;\r\n            display: flex;\r\n            align-items: center;\r\n            padding: 0 15px;\r\n            font-weight: 900;\r\n            font-size: 1.3rem;\r\n            background: #fff;\r\n        }\r\n\r\n        .barcode-footer {\r\n            position: absolute;\r\n            bottom: 15px;\r\n            left: 100px;\r\n            right: 0;\r\n            display: flex;\r\n            flex-direction: column;\r\n            align-items: center;\r\n            justify-content: center;\r\n        }\r\n\r\n        @media print {\r\n            body { background: white; padding: 0; }\r\n            .check-container {\r\n                box-shadow: none;\r\n                border: 1px solid #ccc;\r\n                margin: 0;\r\n            }\r\n            .punch-margin-guide {\r\n                border-right: 1px solid #eee;\r\n            }\r\n            .no-print { display: none; }\r\n        }\r\n    </style>\r\n</head>\r\n<body>\r\n\r\n    <div class=\"w-[1100px] mb-4 flex justify-end no-print\">\r\n        <button onclick=\"window.print()\" class=\"bg-black text-white px-6 py-2 rounded-lg font-bold flex items-center gap-2 hover:bg-gray-800 transition-all shadow-lg\">\r\n            <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"6 9 6 2 18 2 18 9\"></polyline><path d=\"M6 18H4a2 2 0 0 1-2-2v-5a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2v5a2 2 0 0 1-2 2h-2\"></path><rect x=\"6\" y=\"14\" width=\"12\" height=\"8\"></rect></svg>\r\n            Print Voucher\r\n        </button>\r\n    </div>\r\n\r\n    <div class=\"check-container shadow-2xl\">\r\n        <div class=\"punch-margin-guide no-print\">\r\n            <div class=\"punch-hole-target\"></div>\r\n            <div class=\"punch-hole-target\"></div>\r\n        </div>\r\n\r\n        <div class=\"flex justify-between items-start mb-12\">\r\n            <div class=\"flex items-center gap-4 w-1/3\">\r\n                <div class=\"w-20 h-20 shrink-0\">\r\n                    <svg viewBox=\"0 0 500 500\" class=\"w-full h-full\">\r\n                        <circle cx=\"250\" cy=\"270\" r=\"120\" fill=\"none\" stroke=\"black\" stroke-width=\"2\"/>\r\n                        <path d=\"M250 100 V350 M210 160 V350 M290 160 V350 M170 220 V350 M330 220 V350\" stroke=\"black\" stroke-width=\"12\" stroke-linecap=\"round\"/>\r\n                        <rect x=\"230\" y=\"270\" width=\"40\" height=\"40\" fill=\"black\" />\r\n                        <text x=\"250\" y=\"440\" font-family=\"Inter\" font-weight=\"900\" font-size=\"64\" text-anchor=\"middle\" letter-spacing=\"2\">{{agency_name}}</text>\r\n                    </svg>\r\n                </div>\r\n                <div class=\"border-l-2 border-black pl-4\">\r\n                    <h1 class=\"text-xl font-black uppercase leading-tight tracking-widest\">{{agency_name}}</h1>\r\n                    <p class=\"text-[10px] text-gray-500 uppercase font-bold\">Estate Management & Dev.</p>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"flex-grow flex justify-center pt-2\">\r\n                <div class=\"px-8 py-1\">\r\n                    <h2 class=\"text-3xl font-black tracking-[0.4em] uppercase underline underline-offset-8\">{{voucher_type}}</h2>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"w-1/3 date-section\">\r\n                <div class=\"mb-2 flex items-center gap-2\">\r\n                    <span class=\"text-[10px] font-bold text-gray-400 uppercase tracking-widest\">Voucher No.</span>\r\n                    <span class=\"font-mono font-bold text-lg\">#{{voucher_no}}</span>\r\n                </div>\r\n                <div>\r\n                    <div class=\"date-box\">\r\n                        <div class=\"date-cell\">{{d1}}</div>\r\n                        <div class=\"date-cell\">{{d2}}</div>\r\n                        <div class=\"date-cell\">{{d3}}</div>\r\n                        <div class=\"date-cell\">{{d4}}</div>\r\n                        <div class=\"date-cell\">{{d5}}</div>\r\n                        <div class=\"date-cell\">{{d6}}</div>\r\n                        <div class=\"date-cell\">{{d7}}</div>\r\n                        <div class=\"date-cell\">{{d8}}</div>\r\n                    </div>\r\n                    <div class=\"date-labels\">\r\n                        <div class=\"date-label-item\">D</div>\r\n                        <div class=\"date-label-item\">D</div>\r\n                        <div class=\"date-label-item\">M</div>\r\n                        <div class=\"date-label-item\">M</div>\r\n                        <div class=\"date-label-item\">Y</div>\r\n                        <div class=\"date-label-item\">Y</div>\r\n                        <div class=\"date-label-item\">Y</div>\r\n                        <div class=\"date-label-item\">Y</div>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n\r\n        <div class=\"space-y-8\">\r\n            <div class=\"flex items-end\">\r\n                <span class=\"text-sm font-bold uppercase tracking-widest whitespace-nowrap\">Pay</span>\r\n                <div class=\"input-line text-xl uppercase px-4 font-black\">{{pay_to}}</div>\r\n                <span class=\"text-xs font-bold uppercase ml-2 text-gray-400 whitespace-nowrap\">Or Bearer</span>\r\n            </div>\r\n\r\n            <div class=\"flex items-start gap-4\">\r\n                <div class=\"flex-grow space-y-8\">\r\n                    <div class=\"flex items-end\">\r\n                        <span class=\"text-sm font-bold uppercase tracking-widest whitespace-nowrap\">Sum Of</span>\r\n                        <div class=\"input-line text-base italic px-4 font-medium\">{{amount_words}}</div>\r\n                    </div>\r\n                    <div class=\"flex items-end\">\r\n                        <span class=\"text-sm font-bold uppercase tracking-widest whitespace-nowrap\">Narration</span>\r\n                        <div class=\"input-line text-sm font-medium px-4 text-gray-600\">{{narration}}</div>\r\n                    </div>\r\n                </div>\r\n                <div class=\"amount-box mt-1\">\r\n                    <span class=\"text-sm mr-2 font-black\">{{currency_symbol}}</span>\r\n                    <span>{{amount_number}}</span>\r\n                </div>\r\n            </div>\r\n        </div>\r\n\r\n        <div class=\"mt-auto flex justify-between items-end pb-12\">\r\n            <div class=\"w-64 border-2 border-black p-2.5 h-20 flex flex-col justify-between bg-white\">\n                    <div class=\"flex justify-between items-center border-b border-gray-200 pb-0.5\">\n                        <span class=\"text-[9px] font-black uppercase text-gray-500 tracking-widest\">{{account_box_label}}</span>\n                        <span class=\"text-[10px] font-mono font-bold text-gray-700 tracking-wider\">A/C: <strong class=\"text-black font-extrabold\">{{account_code}}</strong></span>\n                    </div>\n                    <div class=\"flex flex-col justify-end\">\n                        <span class=\"font-mono font-bold tracking-[0.2em] text-lg text-black leading-tight\">{{account_display_no}}</span>\n                        <span class=\"text-[9px] font-bold text-gray-500 uppercase tracking-wider truncate mt-0.5\">{{account_head_name}}</span>\n                    </div>\n                </div>\r\n\r\n            <div class=\"flex gap-12\">\r\n                <div class=\"text-center\">\r\n                    <div class=\"w-52 border-b-2 border-black mb-2\"></div>\r\n                    <p class=\"text-[10px] font-black uppercase tracking-[0.2em]\">Authorized Signatory</p>\r\n                </div>\r\n                <div class=\"text-center\">\r\n                    <div class=\"w-52 border-b-2 border-black mb-2\"></div>\r\n                    <p class=\"text-[10px] font-black uppercase tracking-[0.2em]\">Chairman / Director</p>\r\n                </div>\r\n            </div>\r\n        </div>\r\n\r\n        <div class=\"barcode-footer\">\r\n            {{barcode_svg}}\r\n            <p class=\"mt-1 text-[9px] font-mono font-bold tracking-[0.25em] text-gray-700 uppercase font-extrabold\">{{barcode_text}}</p>\r\n        </div>\r\n    </div>\r\n\r\n</body>\r\n</html>', 0, '2026-03-28 01:46:59', '2026-11-23 16:39:52'),
(5, 22, 'voucher', 'WV', '<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>Payment Voucher Preview</title>\n    <script src=\"https://cdn.tailwindcss.com\"></script>\n    <style>\n        @import url(\'https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800;900&family=JetBrains+Mono:wght@500&display=swap\');\n        \n        :root {\n            --wv-black: #000000;\n        }\n\n        body {\n            font-family: \'Inter\', sans-serif;\n            background-color: #f0f2f5;\n            margin: 0;\n            padding: 20px;\n            display: flex;\n            flex-direction: column;\n            align-items: center;\n        }\n\n        /* Wrap the container to allow scaling on smaller screens without breaking the fixed 1100px width */\n        .preview-wrapper {\n            width: 100%;\n            overflow-x: auto;\n            display: flex;\n            justify-content: center;\n            padding-bottom: 20px;\n        }\n\n        .check-container {\n            background: white;\n            width: 1100px;\n            min-width: 1100px; /* Force width for horizontal scrolling on small screens */\n            height: 520px;\n            padding: 40px 40px 40px 100px;\n            border: 1px solid #e5e7eb;\n            position: relative;\n            overflow: hidden;\n            display: flex;\n            flex-direction: column;\n            background-image: radial-gradient(#f3f4f6 1px, transparent 1px);\n            background-size: 20px 20px;\n        }\n\n        .punch-margin-guide {\n            position: absolute;\n            left: 0;\n            top: 0;\n            bottom: 0;\n            width: 80px;\n            border-right: 1px dashed #d1d5db;\n            background: #fafafa;\n            display: flex;\n            flex-direction: column;\n            justify-content: center;\n            align-items: center;\n            gap: 150px;\n        }\n\n        .punch-hole-target {\n            width: 12px;\n            height: 12px;\n            border: 1px solid #e5e7eb;\n            border-radius: 50%;\n        }\n\n        .input-line {\n            border-bottom: 1px solid #000;\n            flex-grow: 1;\n            margin-left: 10px;\n            padding-bottom: 2px;\n            font-weight: 600;\n            min-height: 28px;\n        }\n\n        .date-section {\n            display: flex;\n            flex-direction: column;\n            align-items: flex-end;\n        }\n\n        .date-box {\n            display: flex;\n            border-top: 1.5px solid #000;\n            border-bottom: 1.5px solid #000;\n            border-left: 1.5px solid #000;\n        }\n\n        .date-cell {\n            width: 32px;\n            height: 35px;\n            border-right: 1.5px solid #000;\n            display: flex;\n            align-items: center;\n            justify-content: center;\n            font-size: 18px;\n            font-weight: 800;\n            background: white;\n        }\n\n        .date-labels {\n            display: flex;\n            width: 100%;\n            justify-content: space-around;\n            padding-top: 4px;\n        }\n\n        .date-label-item {\n            width: 32px;\n            text-align: center;\n            font-size: 10px;\n            font-weight: 700;\n            color: #666;\n            text-transform: uppercase;\n        }\n\n        .amount-box {\n            border: 1.5px solid #000;\n            height: 50px;\n            width: 220px;\n            display: flex;\n            align-items: center;\n            padding: 0 15px;\n            font-weight: 900;\n            font-size: 1.3rem;\n            background: #fff;\n        }\n\n        .barcode-footer {\n            position: absolute;\n            bottom: 15px;\n            left: 100px;\n            right: 0;\n            display: flex;\n            flex-direction: column;\n            align-items: center;\n            justify-content: center;\n        }\n\n        @media print {\n            body { background: white; padding: 0; display: block; }\n            .preview-wrapper { display: block; overflow: visible; }\n            .check-container {\n                box-shadow: none !important;\n                border: 1px solid #ccc;\n                margin: 0;\n            }\n            .punch-margin-guide {\n                border-right: 1px solid #eee;\n            }\n            .no-print { display: none !important; }\n        }\n    </style>\n</head>\n<body>\n\n    <div class=\"w-full max-w-[1100px] mb-4 flex justify-end no-print\">\n        <button onclick=\"window.print()\" class=\"bg-black text-white px-6 py-2 rounded-lg font-bold flex items-center gap-2 hover:bg-gray-800 transition-all shadow-lg\">\n            <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"6 9 6 2 18 2 18 9\"></polyline><path d=\"M6 18H4a2 2 0 0 1-2-2v-5a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2v5a2 2 0 0 1-2 2h-2\"></path><rect x=\"6\" y=\"14\" width=\"12\" height=\"8\"></rect></svg>\n            Print Voucher\n        </button>\n    </div>\n\n    <div class=\"preview-wrapper\">\n        <div class=\"check-container shadow-2xl\" id=\"voucher-template\">\n            <div class=\"punch-margin-guide no-print\">\n                <div class=\"punch-hole-target\"></div>\n                <div class=\"punch-hole-target\"></div>\n            </div>\n\n            <div class=\"flex justify-between items-start mb-12\">\n                <div class=\"flex items-center gap-4 w-1/3\">\n                    <div class=\"w-16 h-16 shrink-0 flex items-center justify-center\">\n                        <img src=\"{{agency_logo}}\" alt=\"Logo\" class=\"max-w-full max-h-full object-contain\" onerror=\"this.style.display=\'none\'\" />\n                    </div>\n                    <div class=\"border-l-2 border-black pl-4\">\n                        <h1 class=\"text-xl font-black uppercase leading-tight tracking-widest\">{{agency_name}}</h1>\n                        <p class=\"text-[10px] text-gray-600 font-medium leading-tight mt-1\">{{agency_address}}</p>\n                        <p class=\"text-[10px] text-gray-600 font-bold leading-tight mt-0.5\">Mobile: {{agency_phone}}</p>\n                    </div>\n                </div>\n\n                <div class=\"flex-grow flex justify-center pt-2\">\n                    <div class=\"px-8 py-1\">\n                        <h2 class=\"text-[15px] font-black tracking-[0.4em] uppercase underline underline-offset-4\">{{voucher_type}}</h2>\n                    </div>\n                </div>\n\n                <div class=\"w-1/3 date-section\">\n                    <div class=\"mb-2 flex items-center gap-2\">\n                        <span class=\"text-[10px] font-bold text-gray-400 uppercase tracking-widest\">Voucher No.</span>\n                        <span class=\"font-mono font-bold text-lg\">#{{voucher_no}}</span>\n                    </div>\n                    <div>\n                        <div class=\"date-box\">\n                            <div class=\"date-cell\">{{d1}}</div>\n                            <div class=\"date-cell\">{{d2}}</div>\n                            <div class=\"date-cell\">{{d3}}</div>\n                            <div class=\"date-cell\">{{d4}}</div>\n                            <div class=\"date-cell\">{{d5}}</div>\n                            <div class=\"date-cell\">{{d6}}</div>\n                            <div class=\"date-cell\">{{d7}}</div>\n                            <div class=\"date-cell\">{{d8}}</div>\n                        </div>\n                        <div class=\"date-labels\">\n                            <div class=\"date-label-item\">D</div>\n                            <div class=\"date-label-item\">D</div>\n                            <div class=\"date-label-item\">M</div>\n                            <div class=\"date-label-item\">M</div>\n                            <div class=\"date-label-item\">Y</div>\n                            <div class=\"date-label-item\">Y</div>\n                            <div class=\"date-label-item\">Y</div>\n                            <div class=\"date-label-item\">Y</div>\n                        </div>\n                    </div>\n                </div>\n            </div>\n\n            <div class=\"space-y-8\">\n                <div class=\"flex items-end\">\n                    <span class=\"text-base font-black uppercase tracking-widest whitespace-nowrap\">Pay</span>\n                    <div class=\"input-line text-lg font-bold px-4 text-black\">{{narration}}</div>\n                    <span class=\"text-xs font-bold uppercase ml-2 text-gray-400 whitespace-nowrap\">Or Bearer</span>\n                </div>\n\n                <div class=\"flex items-start gap-4\">\n                    <div class=\"flex-grow space-y-8\">\n                        <div class=\"flex items-end\">\n                            <span class=\"text-sm font-bold uppercase tracking-widest whitespace-nowrap\">Sum Of</span>\n                            <div class=\"input-line text-base italic px-4 font-medium\">{{amount_words}}</div>\n                        </div>\n                        <div class=\"flex items-end\">\n                            <span class=\"text-sm font-bold uppercase tracking-widest whitespace-nowrap\">Narration</span>\n                            <div class=\"input-line text-sm uppercase px-4 font-medium text-gray-700\">{{pay_to}}</div>\n                        </div>\n                    </div>\n                    <div class=\"amount-box mt-1\">\n                        <span class=\"text-sm mr-2 font-black\">{{currency_symbol}}</span>\n                        <span>{{amount_number}}</span>\n                    </div>\n                </div>\n            </div>\n\n            <div class=\"mt-auto flex justify-between items-end pb-12\">\n                <div class=\"w-64 border-2 border-black p-2.5 h-20 flex flex-col justify-between bg-white\">\n                    <div class=\"flex justify-between items-center border-b border-gray-200 pb-0.5\">\n                        <span class=\"text-[9px] font-black uppercase text-gray-500 tracking-widest\">{{account_box_label}}</span>\n                        <span class=\"text-[10px] font-mono font-bold text-gray-700 tracking-wider\">A/C: <strong class=\"text-black font-extrabold\">{{account_code}}</strong></span>\n                    </div>\n                    <div class=\"flex flex-col justify-end\">\n                        <span class=\"font-mono font-bold tracking-[0.2em] text-lg text-black leading-tight\">{{account_display_no}}</span>\n                        <span class=\"text-[9px] font-bold text-gray-500 uppercase tracking-wider truncate mt-0.5\">{{account_head_name}}</span>\n                    </div>\n                </div>\n\n                <div class=\"flex gap-12\">\n                    <div class=\"text-center\">\n                        <div class=\"w-52 border-b-2 border-black mb-2\"></div>\n                        <p class=\"text-[10px] font-black uppercase tracking-[0.2em]\">Authorized Signatory</p>\n                    </div>\n                    <div class=\"text-center\">\n                        <div class=\"w-52 border-b-2 border-black mb-2\"></div>\n                        <p class=\"text-[10px] font-black uppercase tracking-[0.2em]\">Chairman / Director</p>\n                    </div>\n                </div>\n            </div>\n\n            <div class=\"barcode-footer\">\n                {{barcode_svg}}\n                <p class=\"mt-1 text-[9px] font-mono font-bold tracking-[0.25em] text-gray-700 uppercase font-extrabold\">{{barcode_text}}</p>\n            </div>\n        </div>\n    </div>\n\n</body>\n</html>', 1, '2026-03-28 02:10:38', '2026-11-23 16:39:52');
