(8, 20, 'salary', 'Default Salary Slip', '<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>{{company_name}} - Salary Slip</title>\n    <style>\n        body{font-family:Arial,Helvetica,sans-serif;background:#f2f6fb;margin:0;padding:20px;color:#1b2f4a}\n        .no-print{max-width:920px;margin:0 auto 12px;text-align:right}\n        .no-print .btn{background:#1f4f82;color:#fff;border:none;border-radius:6px;padding:10px 14px;font-weight:700;cursor:pointer}\n        .wrap{max-width:920px;margin:0 auto;background:#fff;border:1px solid #d8e2f0;border-radius:12px;overflow:hidden}\n        .head{padding:18px 22px;border-bottom:1px solid #e8edf6}\n        .head h1{margin:0;font-size:28px;color:#163357}\n        .head p{margin:5px 0 0;color:#4a607f;font-size:12px}\n        .title{padding:12px 22px;background:#f7faff;border-bottom:1px solid #e8edf6;display:flex;justify-content:space-between;gap:10px;align-items:center}\n        .title h2{margin:0;font-size:22px;color:#112f55}\n        .title .meta{font-size:13px;color:#375071;font-weight:700}\n        .grid{padding:14px 22px;border-bottom:1px solid #edf2fa}\n        .row{display:flex;gap:12px;flex-wrap:wrap;margin-bottom:8px}\n        .row:last-child{margin-bottom:0}\n        .card{flex:1 1 30%;min-width:220px;border:1px solid #dbe5f3;border-radius:8px;padding:10px;background:#fbfdff}\n        .card .k{display:block;font-size:11px;color:#6a7f9a;text-transform:uppercase;letter-spacing:.08em}\n        .card .v{display:block;margin-top:6px;font-size:15px;font-weight:700;color:#203b60;word-break:break-word}\n        .tbl{padding:14px 22px}\n        table{width:100%;border-collapse:collapse}\n        th,td{border:1px solid #dbe5f3;padding:8px;text-align:left}\n        th{background:#f6f9ff;color:#29466a}\n        .tr{text-align:right}\n        .foot{padding:12px 22px;font-size:12px;color:#5d7392;display:flex;justify-content:space-between;gap:8px;flex-wrap:wrap;background:#f8fbff}\n        @media print{\n            @page { size: A4 portrait; margin: 8mm; }\n            body{background:#fff;padding:0}\n            .no-print{display:none}\n            .wrap{max-width:none;border:none;border-radius:0}\n        }\n    </style>\n</head>\n<body>\n    <div class=\"no-print\"><button class=\"btn\" onclick=\"window.print()\">Print Salary Slip</button></div>\n    <div class=\"wrap\">\n        <div class=\"head\">\n            <h1>{{company_name}}</h1>\n            <p>{{agency_name}} | {{agency_phone}} | {{agency_email}}</p>\n        </div>\n        <div class=\"title\">\n            <h2>Salary Slip</h2>\n            <div class=\"meta\">Month: {{payroll_month}} | Date: {{payment_date}}</div>\n        </div>\n        <div class=\"grid\">\n            <div class=\"row\">\n                <div class=\"card\"><span class=\"k\">Employee</span><span class=\"v\">{{employee_name}}</span></div>\n                <div class=\"card\"><span class=\"k\">Employee Code</span><span class=\"v\">{{employee_code}}</span></div>\n                <div class=\"card\"><span class=\"k\">Department / Designation</span><span class=\"v\">{{department}} / {{designation}}</span></div>\n            </div>\n            <div class=\"row\">\n                <div class=\"card\"><span class=\"k\">Working / Present Days</span><span class=\"v\">{{working_days}} / {{present_days}}</span></div>\n                <div class=\"card\"><span class=\"k\">Payment Method</span><span class=\"v\">{{payment_method}}</span></div>\n                <div class=\"card\"><span class=\"k\">Status</span><span class=\"v\">{{status}}</span></div>\n            </div>\n        </div>\n        <div class=\"tbl\">\n            <table>\n                <thead>\n                    <tr>\n                        <th>Details</th>\n                        <th class=\"tr\">Amount</th>\n                    </tr>\n                </thead>\n                <tbody>\n                    <tr><td>Base Salary</td><td class=\"tr\">{{base_salary}}</td></tr>\n                    <tr><td>Bonus</td><td class=\"tr\">{{bonus}}</td></tr>\n                    <tr><td>Overtime ({{overtime_hours}} hrs)</td><td class=\"tr\">{{overtime_amount}}</td></tr>\n                    <tr><td>Deductions</td><td class=\"tr\">{{deductions}}</td></tr>\n                    <tr><td><strong>Net Pay</strong></td><td class=\"tr\"><strong>{{net_pay}}</strong></td></tr>\n                    <tr><td>Paid Amount</td><td class=\"tr\">{{paid_amount}}</td></tr>\n                    <tr><td>Due Amount</td><td class=\"tr\">{{due_amount}}</td></tr>\n                </tbody>\n            </table>\n        </div>\n        <div class=\"foot\">\n            <span>Reference: {{reference_no}}</span>\n            <span>Generated: {{generated_at}}</span>\n        </div>\n    </div>\n</body>\n</html>', 1, '2026-04-01 11:46:38', '2026-04-01 11:46:38'),
(9, 20, 'stock_purchase', 'Default Stock Purchase', '<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>{{company_name}} - Stock Purchase</title>\n    <style>\n        body{font-family:Arial,Helvetica,sans-serif;background:#f2f6fb;margin:0;padding:20px;color:#1b2f4a}\n        .no-print{max-width:920px;margin:0 auto 12px;text-align:right}\n        .no-print .btn{background:#0e7a50;color:#fff;border:none;border-radius:6px;padding:10px 14px;font-weight:700;cursor:pointer}\n        .wrap{max-width:920px;margin:0 auto;background:#fff;border:1px solid #d8e2f0;border-radius:12px;overflow:hidden}\n        .head{padding:18px 22px;border-bottom:1px solid #e8edf6}\n        .head h1{margin:0;font-size:28px;color:#163357}\n        .head p{margin:5px 0 0;color:#4a607f;font-size:12px}\n        .title{padding:12px 22px;background:#f7faff;border-bottom:1px solid #e8edf6;display:flex;justify-content:space-between;gap:10px;align-items:center}\n        .title h2{margin:0;font-size:22px;color:#112f55}\n        .title .meta{font-size:13px;color:#375071;font-weight:700}\n        .grid{padding:14px 22px;border-bottom:1px solid #edf2fa}\n        .row{display:flex;gap:12px;flex-wrap:wrap;margin-bottom:8px}\n        .row:last-child{margin-bottom:0}\n        .card{flex:1 1 30%;min-width:220px;border:1px solid #dbe5f3;border-radius:8px;padding:10px;background:#fbfdff}\n        .card .k{display:block;font-size:11px;color:#6a7f9a;text-transform:uppercase;letter-spacing:.08em}\n        .card .v{display:block;margin-top:6px;font-size:15px;font-weight:700;color:#203b60;word-break:break-word}\n        .tbl{padding:14px 22px}\n        table{width:100%;border-collapse:collapse}\n        th,td{border:1px solid #dbe5f3;padding:8px;text-align:left}\n        th{background:#f6f9ff;color:#29466a}\n        .tr{text-align:right}\n        .notes{padding:0 22px 14px}\n        .notes p{margin:0;white-space:pre-wrap}\n        .foot{padding:12px 22px;font-size:12px;color:#5d7392;display:flex;justify-content:space-between;gap:8px;flex-wrap:wrap;background:#f8fbff}\n        @media print{\n            @page { size: A4 portrait; margin: 8mm; }\n            body{background:#fff;padding:0}\n            .no-print{display:none}\n            .wrap{max-width:none;border:none;border-radius:0}\n        }\n    </style>\n</head>\n<body>\n    <div class=\"no-print\"><button class=\"btn\" onclick=\"window.print()\">Print Purchase</button></div>\n    <div class=\"wrap\">\n        <div class=\"head\">\n            <h1>{{company_name}}</h1>\n            <p>{{agency_name}} | {{agency_phone}} | {{agency_email}}</p>\n        </div>\n        <div class=\"title\">\n            <h2>Stock Purchase</h2>\n            <div class=\"meta\">Invoice: {{invoice_no}} | Date: {{entry_date}}</div>\n        </div>\n        <div class=\"grid\">\n            <div class=\"row\">\n                <div class=\"card\"><span class=\"k\">Vendor</span><span class=\"v\">{{vendor_name}}</span></div>\n                <div class=\"card\"><span class=\"k\">Vendor Phone</span><span class=\"v\">{{vendor_phone}}</span></div>\n                <div class=\"card\"><span class=\"k\">Stock Store</span><span class=\"v\">{{site_name}}</span></div>\n            </div>\n            <div class=\"row\">\n                <div class=\"card\"><span class=\"k\">Material</span><span class=\"v\">{{material_type}}</span></div>\n                <div class=\"card\"><span class=\"k\">Quantity / Unit</span><span class=\"v\">{{quantity}} {{unit_type}}</span></div>\n                <div class=\"card\"><span class=\"k\">Debit Account</span><span class=\"v\">{{debit_account}}</span></div>\n            </div>\n        </div>\n        <div class=\"tbl\">\n            <table>\n                <thead>\n                    <tr>\n                        <th>Particular</th>\n                        <th class=\"tr\">Amount</th>\n                    </tr>\n                </thead>\n                <tbody>\n                    <tr><td>Unit Cost</td><td class=\"tr\">{{unit_cost}}</td></tr>\n                    <tr><td><strong>Total Cost</strong></td><td class=\"tr\"><strong>{{total_cost}}</strong></td></tr>\n                </tbody>\n            </table>\n        </div>\n        <div class=\"notes\">\n            <p><strong>Vendor Address:</strong> {{vendor_address}}</p>\n            <p><strong>Notes:</strong> {{notes}}</p>\n        </div>\n        <div class=\"foot\">\n            <span>Generated: {{generated_at}}</span>\n            <span>{{currency_symbol}}</span>\n        </div>\n    </div>\n</body>\n</html>', 1, '2026-04-01 11:46:39', '2026-04-01 11:46:39');
