n: relative;\\r\\n            overflow: visible;\\r\\n            display: flex;\\r\\n            flex-direction: column;\\r\\n            counter-increment: page;\\r\\n        }\\r\\n        .watermark {\\r\\n            position: absolute;\\r\\n            top: 50%;\\r\\n            left: 50%;\\r\\n            transform: translate(-50%, -50%) rotate(-30deg);\\r\\n            font-size: 72px;\\r\\n            font-weight: 900;\\r\\n            color: rgba(16,185,129,.035);\\r\\n            font-family: Arial, Helvetica, sans-serif;\\r\\n            pointer-events: none;\\r\\n            user-select: none;\\r\\n            z-index: 1;\\r\\n            white-space: nowrap;\\r\\n            border: 7px double rgba(16,185,129,.035);\\r\\n            padding: 5px 26px;\\r\\n            border-radius: 15px;\\r\\n        }\\r\\n        .page > *:not(.watermark) {\\r\\n            position: relative;\\r\\n            z-index: 2;\\r\\n        }\\r\\n        \\r\\n        \\/* dynamic header logic for multiple pages *\\/\\r\\n        .letterhead {\\r\\n            text-align: center;\\r\\n            border-bottom: 2px solid #0f172a;\\r\\n            padding-bottom: 5px;\\r\\n            margin-bottom: 8px;\\r\\n            display: block;\\r\\n        }\\r\\n        .page-counter-header {\\r\\n            display: none;\\r\\n            border-bottom: 2px solid #0f172a;\\r\\n            padding-bottom: 5px;\\r\\n            margin-bottom: 8px;\\r\\n            font-size: 14px;\\r\\n            font-weight: bold;\\r\\n            text-align: right;\\r\\n            color: #0f172a;\\r\\n        }\\r\\n        \\/* Hide full letterhead and show page number on subsequent pages *\\/\\r\\n        .page:not(:first-of-type) .letterhead {\\r\\n            display: none;\\r\\n        }\\r\\n        .page:not(:first-of-type) .page-counter-header {\\r\\n            display: block;\\r\\n        }\\r\\n        .page:not(:first-of-type) .page-counter-header::after {\\r\\n            content: \\\"\\u0635\\u0641\\u062d\\u06c1 \\u0646\\u0645\\u0628\\u0631: \\\" counter(page);\\r\\n        }\\r\\n\\r\\n        .head-row {\\r\\n            display: grid;\\r\\n            grid-template-columns: 64px minmax(0,1fr) 64px;\\r\\n            align-items: center;\\r\\n            gap: 10px;\\r\\n        }\\r\\n        .logo-box {\\r\\n            width: 56px;\\r\\n            height: 56px;\\r\\n            border: 1px solid #0f172a;\\r\\n            padding: 3px;\\r\\n            display: flex;\\r\\n            align-items: center;\\r\\n            justify-content: center;\\r\\n            overflow: hidden;\\r\\n            direction: ltr;\\r\\n        }\\r\\n        .agency-name {\\r\\n            font-size: 22px;\\r\\n            font-weight: 900;\\r\\n            line-height: 1.2;\\r\\n            color:#0f172a;\\r\\n            font-family: inherit;\\r\\n        }\\r\\n        .agency-sub {\\r\\n            font-size: 12px;\\r\\n            color: #475569;\\r\\n            margin-top: 1px;\\r\\n        }\\r\\n        .agency-contact {\\r\\n            font-size: 11px;\\r\\n            color: #334155;\\r\\n            margin-top: 2px;\\r\\n            direction: rtl;\\r\\n        }\\r\\n        .document-title {\\r\\n            text-align: center;\\r\\n            font-size: 24px;\\r\\n            font-weight: 900;\\r\\n            text-decoration: underline;\\r\\n            text-underline-offset: 5px;\\r\\n            margin: 5px 0 2px;\\r\\n            color: #0f172a;\\r\\n        }\\r\\n        .document-subtitle {\\r\\n            text-align: center;\\r\\n            font-size: 15px;\\r\\n            font-weight: 700;\\r\\n            color: #334155;\\r\\n            margin-bottom: 6px;\\r\\n        }\\r\\n        .meta-row {\\r\\n            display: flex;\\r\\n            justify-content: space-between;\\r\\n            align-items: center;\\r\\n            font-size: 13px;\\r\\n            font-weight: 800;\\r\\n            color: #1f2937;\\r\\n            margin-bottom: 6px;\\r\\n            background: #f8fafc;\\r\\n            padding: 3px 8px;\\r\\n            border: 1px solid #d7e0ea;\\r\\n            border-radius: 4px;\\r\\n        }\\r\\n        p {\\r\\n            margin: 0 0 5px;\\r\\n            text-align: justify;\\r\\n            line-height: 1.65;\\r\\n            font-size: 14.6px;\\r\\n        }\\r\\n        .section-title {\\r\\n            font-size: 16px;\\r\\n            font-weight: 900;\\r\\n            text-decoration: underline;\\r\\n            text-underline-offset: 4px;\\r\\n            margin: 6px 0 4px;\\r\\n            color: #0f4c3a;\\r\\n            text-align: center;\\r\\n            page-break-after: avoid;\\r\\n        }\\r\\n        .clause {\\r\\n            font-size: 13.8px;\\r\\n            line-height: 1.65;\\r\\n            margin-bottom: 4px;\\r\\n            text-align: justify;\\r\\n        }\\r\\n        .field {\\r\\n            border-bottom: 1px solid #000;\\r\\n            padding: 0 4px;\\r\\n            font-weight: 900;\\r\\n            color: #000;\\r\\n        }\\r\\n        .amount-box {\\r\\n            border: 1.5px solid #065f46;\\r\\n            background: #f9fafb;\\r\\n            padding: 6px 14px;\\r\\n            margin: 6px 0;\\r\\n            text-align: center;\\r\\n            font-size: 15.4px;\\r\\n            font-weight: 900;\\r\\n            line-height: 1.6;\\r\\n            border-radius: 6px;\\r\\n        }\\r\\n        .note-box {\\r\\n            border: 1px solid #cbd5e1;\\r\\n            border-right: 4px solid #059669;\\r\\n            background: #f8fafc;\\r\\n            padding: 6px 12px;\\r\\n            margin: 5px 0;\\r\\n            font-size: 13px;\\r\\n            line-height: 1.6;\\r\\n            border-radius: 0 6px 6px 0;\\r\\n        }\\r\\n        .sign-area, .witness-area {\\r\\n            display: grid;\\r\\n            grid-template-columns: 1fr 1fr;\\r\\n            gap: 10px;\\r\\n            margin-top: 8px;\\r\\n        }\\r\\n        .sign-box {\\r\\n            border: 1px solid #d7e0ea;\\r\\n            background: #f8fafc;\\r\\n            border-radius: 6px;\\r\\n            padding: 6px 12px;\\r\\n            min-height: 110px;\\r\\n            line-height: 1.6;\\r\\n            font-size: 13px;\\r\\n        }\\r\\n        .sign-title {\\r\\n            font-weight: 900;\\r\\n            color: #0f172a;\\r\\n            border-bottom: 1px solid #d7e0ea;\\r\\n            padding-bottom: 2px;\\r\\n            margin-bottom: 3px;\\r\\n            font-size: 12px;\\r\\n            text-align: center;\\r\\n        }\\r\\n        .sign-line {\\r\\n            border-bottom: 1px solid #94a3b8;\\r\\n            display: block;\\r\\n            min-height: 18px;\\r\\n            margin-top: 2px;\\r\\n            margin-bottom: 2px;\\r\\n        }\\r\\n        .thumb-box {\\r\\n            height: 35px;\\r\\n            border: 1px dashed #cbd5e1;\\r\\n            background: #fff;\\r\\n            border-radius: 4px;\\r\\n            margin-top: 5px;\\r\\n            display: flex;\\r\\n            align-items: center;\\r\\n            justify-content: center;\\r\\n            font-size: 11px;\\r\\n            color: #64748b;\\r\\n        }\\r\\n        .footer {\\r\\n            border-top: 1.5px solid #0f172a;\\r\\n            padding-top: 4px;\\r\\n            text-align: center;\\r\\n            font-size: 11px;\\r\\n            color: #475569;\\r\\n            margin-top: auto;\\r\\n            white-space: nowrap;\\r\\n            overflow: hidden;\\r\\n            text-overflow: ellipsis;\\r\\n        }\\r\\n        .page-body {\\r\\n            padding-bottom: 4mm;\\r\\n            flex: 1 1 auto;\\r\\n        }\\r\\n        @media print {\\r\\n            body {\\r\\n                background: #fff!important;\\r\\n                color: #000!important;\\r\\n                padding: 0!important;\\r\\n            }\\r\\n            .page {\\r\\n               