(30, 1, 'subm_bill_template', '<div style=\"border: 2px solid #000; padding: 20px;\">\r\n    <div style=\"text-align: center; border-bottom: 2px solid #000; padding-bottom: 10px; margin-bottom: 20px;\">\r\n        <h1 style=\"margin:0;\">{{society_name}}</h1>\r\n        <p>Electricity & Maintenance Bill</p>\r\n    </div>\r\n    <table style=\"width: 100%; margin-bottom: 20px;\">\r\n        <tr>\r\n            <td><strong>Consumer:</strong> {{client_name}}</td>\r\n            <td><strong>Bill No:</strong> {{bill_no}}</td>\r\n        </tr>\r\n        <tr>\r\n            <td><strong>Property Unit:</strong> {{property_id}}</td>\r\n            <td><strong>Month:</strong> {{billing_month}}</td>\r\n        </tr>\r\n        <tr>\r\n            <td><strong>Due Date:</strong> {{due_date}}</td>\r\n            <td></td>\r\n        </tr>\r\n    </table>\r\n\r\n    <table style=\"width: 100%; border-collapse: collapse; border: 1px solid #000; margin-bottom: 20px;\">\r\n        <tr style=\"background: #eee;\">\r\n            <th style=\"border: 1px solid #000; padding: 8px;\">Description</th>\r\n            <th style=\"border: 1px solid #000; padding: 8px;\">Amount</th>\r\n        </tr>\r\n        <tr>\r\n            <td style=\"border: 1px solid #000; padding: 8px;\">Electricity/Utility Charges ({{units}} Units)</td>\r\n            <td style=\"border: 1px solid #000; padding: 8px; text-align: right;\">Calculated</td>\r\n        </tr>\r\n        <tr>\r\n            <td style=\"border: 1px solid #000; padding: 8px;\">Maintenance Charges</td>\r\n            <td style=\"border: 1px solid #000; padding: 8px; text-align: right;\">{{maintenance_charges}}</td>\r\n        </tr>\r\n        <tr>\r\n            <td style=\"border: 1px solid #000; padding: 8px;\"><strong>Arrears (Previous Dues)</strong></td>\r\n            <td style=\"border: 1px solid #000; padding: 8px; text-align: right;\">{{arrears}}</td>\r\n        </tr>\r\n        <tr>\r\n            <td style=\"border: 1px solid #000; padding: 8px;\"><strong>Late Fee (If applicable)</strong></td>\r\n            <td style=\"border: 1px solid #000; padding: 8px; text-align: right;\">{{late_fee}}</td>\r\n        </tr>\r\n        <tr style=\"background: #ddd; font-weight: bold;\">\r\n            <td style=\"border: 1px solid #000; padding: 8px;\">TOTAL PAYABLE</td>\r\n            <td style=\"border: 1px solid #000; padding: 8px; text-align: right;\">{{total_amount}}</td>\r\n        </tr>\r\n    </table>\r\n    \r\n    <div style=\"text-align: center; margin-top: 40px; border-top: 1px dashed #000; padding-top: 10px;\">\r\n        <p>Payment Slip (Bank Copy)</p>\r\n        <p><strong>{{bill_no}}</strong> | <strong>{{total_amount}}</strong></p>\r\n    </div>\r\n</div>'),
