(82, 1, 'subm_notify_tpl_admin_paid_email_body', 'Admin Payment Alert\r\n\r\nBill: {{bill_no}}\r\nClient: {{client_name}}\r\nConsumer: {{consumer_id}}\r\nProperty: {{property}}\r\nStatus: {{payment_status}}\r\nPaid Now: {{currency}} {{paid_now}}\r\nTotal Paid: {{currency}} {{total_paid}}\r\nPending: {{currency}} {{pending_amount}}\r\nPayment Date: {{payment_date}}\r\nReference: {{payment_ref}}\r\nSource: {{source}}'),
(83, 1, 'subm_notify_tpl_admin_paid_email_subject', 'Admin Payment Alert - {{bill_no}}'),
(84, 1, 'subm_notify_tpl_admin_paid_sms', 'Admin Alert: Payment received for bill {{bill_no}}. Client {{client_name}} ({{consumer_id}}) status {{payment_status}}. Paid now {{currency}} {{paid_now}}, total paid {{currency}} {{total_paid}}, pending {{currency}} {{pending_amount}}, ref {{payment_ref}}.'),
(85, 1, 'subm_notify_tpl_bill_email_body', 'Utility Bill Notification\r\n    \r\n\r\n\r\n    \r\n        \r\n            \r\n                \r\n                    \r\n                    \r\n                    \r\n                        \r\n                            {{society_name}}\r\n                            Electricity Bill Notification\r\n                        \r\n                    \r\n\r\n                    \r\n                    \r\n                        \r\n                            Dear {{client_name}},\r\n                            \r\n                                Your bill #{{bill_no}} for the month of {{billing_month}} has been generated. Please find the summary of your consumption and charges below.\r\n                            \r\n\r\n                            \r\n                            \r\n                                \r\n                                    Consumed Units\r\n                                    {{consumed_units}} Units\r\n                                \r\n                                \r\n                                    Electricity Charges\r\n                                    {{currency}} {{energy_charges}}\r\n                                \r\n                                \r\n                                    Utility / Other Charges\r\n                                    {{currency}} {{other_charges}}\r\n                                \r\n                                \r\n                                    Total Bill\r\n                                    {{currency}} {{total_bill}}\r\n                                \r\n                            \r\n\r\n                            \r\n                            \r\n                                \r\n                                    Due Date: {{due_date}}\r\n                                \r\n                                \r\n                                    Late Fee: {{currency}} {{late_fee}} | Bill with Late Fee: {{currency}} {{late_fee_with_bill}}\r\n                                \r\n                            \r\n\r\n                            \r\n                            \r\n                                \r\n                                    \r\n                                        Download Your PDF Bill\r\n                                    \r\n                                \r\n                            \r\n                        \r\n                    \r\n\r\n                    \r\n                    \r\n                        \r\n                            For any query: 03286694001\r\n                            Regards,{{society_name}}\r\n                        \r\n                    \r\n                \r\n\r\n                \r\n                \r\n                    \r\n                        \r\n                            This is an automated message, please do not reply directly to this email.'),
(86, 1, 'subm_notify_tpl_bill_email_subject', 'New Bill Generated - {{bill_no}}'),
(87, 1, 'subm_notify_tpl_bill_sms', 'Dear {{client_name}}, yourbill #{{bill_no}} for {{billing_month}} generated. Consumed {{consumed_units}} units., Elactricty {{currency}} {{energy_charges}},  \r\nUtility  {{currency}} {{other_charges}}. \r\nTotal {{currency}} {{total_bill}}. Due: {{due_date}}.\r\n Late Fee: {{currency}} {{late_fee}}. Bill with Late Fee: {{currency}} {{late_fee_with_bill}}.\r\n\r\nFor any query 03391101165\r\nRegards {{society_name}}'),
(88, 1, 'subm_notify_tpl_bill_status_email_body', 'Dear {{client_name}},\r\n\r\nYour bill status is {{status}}.\r\nBill No: {{bill_no}}\r\nConsumer: {{consumer_id}}\r\nProperty: {{property}}\r\nTotal: {{currency}} {{total_amount}}\r\nPaid: {{currency}} {{total_paid}}\r\nPending: {{currency}} {{pending_amount}}\r\nDue Date: {{due_date}}\r\nPayment Date: {{payment_date}}\r\nReference: {{payment_ref}}\r\n\r\nRegards,\r\n{{society_name}}'),
(89, 1, 'subm_notify_tpl_bill_status_email_subject', 'Bill Status - {{bill_no}}'),
(90, 1, 'subm_notify_tpl_bill_status_sms', 'Dear {{client_name}}, bill {{bill_no}} status is {{status}}. Total {{currency}} {{total_amount}}, paid {{currency}} {{total_paid}}, pending {{currency}} {{pending_amount}}. Due date: {{due_date}}.'),
(91, 1, 'subm_notify_tpl_custom_due_email_body', 'Dear {{client_name}},\r\n\r\nYour custom bill is due.\r\nBill No: {{bill_no}}\r\nDue Date: {{due_date}}\r\nPending: {{currency}} {{pending_amount}}\r\nCustom Total: {{currency}} {{custom_bill_total}}\r\nView: {{notification_view_url}}\r\nDownload PDF: {{notification_download_pdf_url}}\r\n\r\nRegards,\r\n{{society_name}}'),
(92, 1, 'subm_notify_tpl_custom_due_email_subject', 'Custom Bill Due Reminder - {{bill_no}}'),
(93, 1, 'subm_notify_tpl_custom_due_sms', 'Dear {{client_name}}, your CUSTOM bill {{bill_no}} is due on {{due_date}}. Pending {{currency}} {{pending_amount}}. View: {{notification_view_url}}'),
(94, 1, 'subm_notify_tpl_custom_overdue_email_body', 'Dear {{client_name}},\r\n\r\nYour custom bill is overdue.\r\nBill No: {{bill_no}}\r\nOverdue Days: {{overdue_days}}\r\nPending: {{currency}} {{pending_amount}}\r\nCustom Total: {{currency}} {{custom_bill_total}}\r\nView: {{notification_view_url}}\r\nDownload PDF: {{notification_download_pdf_url}}\r\n\r\nRegards,\r\n{{society_name}}'),
(95, 1, 'subm_notify_tpl_custom_overdue_email_subject', 'Custom Bill Overdue Reminder - {{bill_no}}'),
(96, 1, 'subm_notify_tpl_custom_overdue_sms', 'Reminder: your CUSTOM bill {{bill_no}} is overdue by {{overdue_days}} day(s). Pending {{currency}} {{pending_amount}}. View: {{notification_view_url}}'),
(97, 1, 'subm_notify_tpl_custom_paid_email_body', 'Dear {{client_name}},\r\n\r\nPayment received for your custom bill {{bill_no}}.\r\nPaid now: {{currency}} {{paid_now}}\r\nTotal paid: {{currency}} {{total_paid}}\r\nPending: {{currency}} {{pending_amount}}\r\nCustom Total: {{currency}} {{custom_bill_total}}\r\nDate: {{payment_date}}\r\nRef: {{payment_ref}}\r\nStatus: {{payment_status}}\r\nView: {{notification_view_url}}\r\nDownload PDF: {{notification_download_pdf_url}}\r\n\r\nRegards,\r\n{{society_name}}'),
(98, 1, 'subm_notify_tpl_custom_paid_email_subject', 'Custom Bill Payment Received - {{bill_no}}'),
(99, 1, 'subm_notify_tpl_custom_paid_sms', 'Dear {{client_name}}, payment received for CUSTOM bill {{bill_no}}. Paid now {{currency}} {{paid_now}}. Total paid {{currency}} {{total_paid}}. Pending {{currency}} {{pending_amount}}. Ref: {{payment_ref}}. View: {{notification_view_url}} Download: {{notification_download_pdf_url}}'),
(100, 1, 'subm_notify_tpl_manual_email_body', 'Dear {{client_name}},\r\n\r\n{{custom_message}}\r\n\r\nRegards,\r\n{{society_name}}'),
