(119, 1, 'subm_print_header_html', '<!-- Modern Plugin Header -->\r\n<div style=\"align-items:center;justify-content:space-between;padding:18px 22px;margin:0 0 16px;background:#ffffff;border-radius:14px;font-family:Arial, sans-serif\">\r\n  \r\n  <!-- Left Section (Logo + Society Info) -->\r\n  <div style=\"align-items:center;gap:16px\">\r\n    \r\n    <!-- Logo -->\r\n    <div style=\"width:70px;height:70px;align-items:center;justify-content:center;background:#f1f5f9;border-radius:12px;overflow:hidden\">\r\n      {{society_logo}}\r\n    </div>\r\n\r\n    <!-- Society Details -->\r\n    <div>\r\n      <div style=\"font-size:20px;font-weight:700;color:#111827;line-height:1.3\">\r\n        {{society_name}}\r\n      </div>\r\n      <div style=\"font-size:13px;color:#4b5563;line-height:1.5\">\r\n        {{society_address}}\r\n      </div>\r\n      <div style=\"font-size:13px;color:#4b5563;line-height:1.5\">\r\n        Mobile: {{society_mobile}}\r\n      </div>\r\n    </div>\r\n\r\n  </div>\r\n\r\n  <!-- Right Section (Title + Date) -->\r\n  <div style=\"text-align:right\">\r\n    <div style=\"font-size:16px;font-weight:600;color:#1f2937\">\r\n      {{print_title}}\r\n    </div>\r\n    <div style=\"font-size:12px;color:#6b7280;margin-top:4px\">\r\n      {{print_date}}\r\n    </div>\r\n  </div>\r\n\r\n</div>\r\n'),
