INSERT INTO `billing_templates` (`id`, `society_id`, `name`, `slug`, `template_type`, `html_content`, `css_content`, `is_default`, `created_at`) VALUES
(1, 1, 'Default LESCO Style', 'default-lesco-style', 'print_bill', '<!DOCTYPE html>\r\n<html lang=\"en\">\r\n<head>\r\n    <meta charset=\"UTF-8\">\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n    <style>\r\n        @media print {\r\n            body { background: none; padding: 0; }\r\n            .no-print { display: none; }\r\n            .bill-container { box-shadow: none; border: none; margin: 0; width: 100%; }\r\n        }\r\n        body {\r\n            font-family: \'Segoe UI\', Roboto, Helvetica, Arial, sans-serif;\r\n            background-color: #e2e8f0;\r\n            display: flex;\r\n            flex-direction: column;\r\n            align-items: center;\r\n            padding: 20px;\r\n            margin: 0;\r\n            color: #1a202c;\r\n        }\r\n        .bill-container {\r\n            width: 210mm;\r\n            min-height: 297mm;\r\n            background: white;\r\n            padding: 15mm;\r\n            box-shadow: 0 10px 25px rgba(0,0,0,0.1);\r\n            box-sizing: border-box;\r\n            display: flex;\r\n            flex-direction: column;\r\n        }\r\n        .header {\r\n            background-color: #3730a3;\r\n            color: white;\r\n            padding: 20px;\r\n            display: flex;\r\n            justify-content: space-between;\r\n            align-items: center;\r\n            border-radius: 8px 8px 0 0;\r\n        }\r\n        .header-title h1 {\r\n            margin: 0;\r\n            font-size: 24px;\r\n            text-transform: uppercase;\r\n            letter-spacing: 1px;\r\n        }\r\n        .header-info {\r\n            text-align: right;\r\n            font-size: 11px;\r\n            font-weight: bold;\r\n            opacity: 0.9;\r\n        }\r\n        .ref-grid {\r\n            display: grid;\r\n            grid-template-columns: repeat(6, 1fr);\r\n            border: 1px solid #cbd5e1;\r\n            margin-top: 10px;\r\n            text-align: center;\r\n            font-size: 12px;\r\n        }\r\n        .ref-item {\r\n            border-right: 1px solid #cbd5e1;\r\n        }\r\n        .ref-item:last-child { border-right: none; }\r\n        .ref-label {\r\n            background: #f1f5f9;\r\n            padding: 5px;\r\n            font-weight: bold;\r\n            border-bottom: 1px solid #cbd5e1;\r\n        }\r\n        .ref-value {\r\n            padding: 8px;\r\n            font-weight: 500;\r\n        }\r\n        .main-content {\r\n            display: flex;\r\n            gap: 30px;\r\n            margin-top: 30px;\r\n            flex-grow: 1;\r\n        }\r\n        .left-col { flex: 7; border-right: 1px solid #e2e8f0; padding-right: 20px; }\r\n        .right-col { flex: 5; }\r\n\r\n        .section-title {\r\n            background: #eef2ff;\r\n            color: #312e81;\r\n            padding: 5px 10px;\r\n            font-size: 14px;\r\n            font-weight: bold;\r\n            border-bottom: 2px solid #312e81;\r\n            margin-bottom: 10px;\r\n        }\r\n        .info-box { padding: 5px 10px; margin-bottom: 20px; }\r\n        .consumer-name { font-size: 18px; font-weight: bold; margin: 0; }\r\n        .consumer-address { font-size: 12px; color: #4b5563; line-height: 1.5; }\r\n\r\n        table { width: 100%; border-collapse: collapse; font-size: 13px; }\r\n        .charge-table td { padding: 10px 8px; border-bottom: 1px solid #f1f5f9; }\r\n        .charge-table .total-row { background: #ecfdf5; font-weight: bold; font-size: 15px; }\r\n        .charge-table .arrears-row { color: #475569; font-style: italic; }\r\n        .charge-table .due-row { background: #fff1f2; color: #9f1239; font-weight: bold; }\r\n\r\n        .voucher-area {\r\n            margin-top: 40px;\r\n            border-top: 4px dotted #94a3b8;\r\n            padding-top: 20px;\r\n        }\r\n        .voucher-label {\r\n            text-align: center;\r\n            font-size: 10px;\r\n            font-weight: 900;\r\n            color: #94a3b8;\r\n            letter-spacing: 4px;\r\n            margin-bottom: 10px;\r\n        }\r\n        .voucher-card {\r\n            border: 2px solid #1e293b;\r\n            border-radius: 4px;\r\n        }\r\n        .voucher-header {\r\n            background: #1e293b;\r\n            color: white;\r\n            padding: 8px;\r\n            display: flex;\r\n            justify-content: space-between;\r\n            font-weight: bold;\r\n            font-size: 12px;\r\n        }\r\n        .voucher-body {\r\n            display: grid;\r\n            grid-template-columns: 1fr 1fr;\r\n            padding: 15px;\r\n            background: #fff;\r\n        }\r\n        .voucher-amounts {\r\n            display: grid;\r\n            grid-template-columns: 1fr 1fr;\r\n            border-top: 2px solid #1e293b;\r\n        }\r\n        .v-amt-box {\r\n            padding: 10px;\r\n            text-align: center;\r\n        }\r\n        .v-amt-label { font-size: 10px; font-weight: bold; display: block; margin-bottom: 5px; }\r\n        .v-amt-value { font-size: 24px; font-weight: 900; }\r\n        .bg-green { background: #f0fdf4; border-right: 1px solid #1e293b; }\r\n        .bg-red { background: #fff1f2; }\r\n        \r\n        .bank-footer {\r\n            display: flex;\r\n            justify-content: space-between;\r\n            margin-top: 20px;\r\n            font-size: 12px;\r\n        }\r\n    \n/* subm-template-print-consistency */\n@media print { body { -webkit-print-color-adjust: exact; print-color-adjust: exact; } }\n</style>\r\n</head>\r\n<body>\r\n\r\n    <div class=\"bill-container\">\r\n        <!-- Header -->\r\n        <div class=\"header\">\r\n            <div class=\"header-title\">\r\n                <h1>{{society_name}}</h1>\r\n                <div style=\"font-size: 10px; text-transform: uppercase; margin-top: 5px;\">Residential & Utility Billing Division</div>\r\n            </div>\r\n            <div class=\"header-info\">\r\n                Official Billing Document<br>\r\n                Generated on: {{billing_month}}\r\n            </div>\r\n        </div>\r\n\r\n        <!-- Reference Grid -->\r\n        <div class=\"ref-grid\">\r\n            <div class=\"ref-item\">\r\n                <div class=\"ref-label\">Bill No</div>\r\n                <div class=\"ref-value\" style=\"color:#3730a3; font-weight:bold;\">{{bill_no}}</div>\r\n            </div>\r\n            <div class=\"ref-item\">\r\n                <div class=\"ref-label\">Property ID</div>\r\n                <div class=\"ref-value\">{{property_id}}</div>\r\n            </div>\r\n            <div class=\"ref-item\">\r\n                <div class=\"ref-label\">Billing Month</div>\r\n                <div class=\"ref-value\">{{billing_month}}</div>\r\n            </div>\r\n            <div class=\"ref-item\">\r\n                <div class=\"ref-label\">Consumer Name</div>\r\n                <div class=\"ref-value\" style=\"font-size: 10px;\">{{client_name}}</div>\r\n            </div>\r\n            <div class=\"ref-item\">\r\n                <div class=\"ref-label\">Status</div>\r\n                <div class=\"ref-value\">Current</div>\r\n            </div>\r\n            <div class=\"ref-item\">\r\n                <div class=\"ref-label\">Due Date</div>\r\n                <div class=\"ref-value\" style=\"color:#b91c1c; font-weight:bold;\">TBA</div>\r\n            </div>\r\n        </div>\r\n\r\n        <div class=\"main-content\">\r\n            <!-- Left Side: Consumer Info & Metering -->\r\n            <div class=\"left-col\">\r\n                <div class=\"section-title\">Consumer Details</div>\r\n                <div class=\"info-box\">\r\n                    <p class=\"consumer-name\">{{client_name}}</p>\r\n                    <p class=\"consumer-address\">Property Ref: {{property_id}}<br>Billing address associated with your registration.</p>\r\n                </div>\r\n\r\n                <div class=\"section-title\">Billing Summary</div>\r\n                <div style=\"padding: 10px; font-size: 12px; line-height: 1.8;\">\r\n                    This invoice covers the utility and maintenance services provided for the period of <strong>{{billing_month}}</strong>. Please ensure payment is made via the authorized channels listed below.\r\n                </div>\r\n                \r\n                <div style=\"margin-top: 40px; text-align: center;\">\r\n                    <div style=\"font-size: 9px; color: #94a3b8; font-weight: bold; letter-spacing: 2px; margin-bottom: 10px;\">SCAN FOR DIGITAL PAYMENT</div>\r\n                    <div style=\"display: inline-block;\">{{qr_code}}</div>\r\n                </div>\r\n            </div>\r\n\r\n            <!-- Right Side: Charges & Totals -->\r\n            <div class=\"right-col\">\r\n                <div class=\"section-title\">Charges Breakdown</div>\r\n                <table class=\"charge-table\">\r\n                    <!-- Your plugin injects <tr><td>Desc</td><td>Amt</td></tr> here -->\r\n                    {{table_rows}}\r\n                    \r\n                    <tr class=\"arrears-row\">\r\n                        <td>Previous Arrears</td>\r\n                        <td align=\"right\">{{arrears}}</td>\r\n                    </tr>\r\n                    <tr class=\"arrears-row\" style=\"border-bottom: 2px solid #333;\">\r\n                        <td>Late Fee Surcharge</td>\r\n                        <td align=\"right\">{{late_fee}}</td>\r\n                    </tr>\r\n                    <tr class=\"total-row\">\r\n                        <td style=\"padding: 15px 8px;\">TOTAL PAYABLE</td>\r\n                        <td align=\"right\" style=\"padding: 15px 8px;\">{{total_amount}}</td>\r\n                    </tr>\r\n                </table>\r\n\r\n                <div style=\"margin-top: 30px;\">\r\n                    <div class=\"section-title\">Payment Instructions</div>\r\n                    <div style=\"font-size: 11px; padding: 10px; background: #f8fafc; border-radius: 4px;\">\r\n                        {{bank_details}}\r\n                    </div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n\r\n        <!-- Detachable Voucher -->\r\n        <div class=\"voucher-area\">\r\n            <div class=\"voucher-label\">DETACHABLE PAYMENT VOUCHER (BANK COPY)</div>\r\n            <div class=\"voucher-card\">\r\n                <div class=\"voucher-header\">\r\n                    <span>{{society_name}} - Utility Voucher</span>\r\n                    <span>Bill No: {{bill_no}}</span>\r\n                </div>\r\n                <div class=\"voucher-body\">\r\n                    <div>\r\n                        <div style=\"font-size: 9px; font-weight: bold; color: #64748b;\">CONSUMER NAME</div>\r\n                        <div style=\"font-size: 14px; font-weight: bold;\">{{client_name}}</div>\r\n                        <div style=\"font-size: 10px; margin-top: 5px;\">Property: {{property_id}}</div>\r\n                    </div>\r\n                    <div align=\"right\">\r\n                        <div style=\"font-size: 9px; font-weight: bold; color: #64748b;\">BILLING MONTH</div>\r\n                        <div style=\"font-size: 14px; font-weight: bold;\">{{billing_month}}</div>\r\n                    </div>\r\n                </div>\r\n                <div class=\"voucher-amounts\">\r\n                    <div class=\"v-amt-box bg-green\">\r\n                        <span class=\"v-amt-label\">TOTAL DUE AMOUNT</span>\r\n                        <span class=\"v-amt-value\">{{total_amount}}</span>\r\n                    </div>\r\n                    <div class=\"v-amt-box bg-red\">\r\n                        <span class=\"v-amt-label\">PAYABLE AFTER DUE DATE</span>\r\n                        <span class=\"v-amt-value\">--</span>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n            <div style=\"display: flex; justify-content: space-between; font-size: 9px; color: #94a3b8; font-weight: bold; margin-top: 5px; font-style: italic;\">\r\n                <span>* Valid only with Bank Stamp</span>\r\n                <span>Generated electronically by {{society_name}} Systems</span>\r\n            </div>\r\n        </div>\r\n    </div>\r\n\r\n</body>\r\n</html>', '', 0, '2026-08-30 21:27:47'),
(4, 1, 'VoltGrid Template', 'voltgrid-template', 'print_bill', '﻿<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>Utility Bill Template</title>\n    <!-- Tailwind CSS for the classes used in the template -->\n    <script src=\"https://cdn.tailwindcss.com\"></script>\n    <style>\n        @import url(\'https://fonts.googleapis.com/css2?family=Inter:wght@300;400;600;800;900&display=swap\');\n        \n        body {\n            font-family: \'Inter\', sans-serif;\n            background-color: #f3f4f6;\n            display: flex;\n            justify-content: center;\n            padding: 20px;\n        }\n\n        @page {\n            size: A4;\n            margin: 12.7mm; /* default-like printer margin (~0.5in) */\n        }\n\n        @media print {\n            body {\n                margin: 0;\n                padding: 0;\n                background-color: white;\n                -webkit-print-color-adjust: exact;\n                print-color-adjust: exact;\n            }\n            .page {\n                margin: 0 auto;\n                width: 184mm; /* fit within A4 printable area with default margins */\n                min-height: 271mm;\n                height: auto !important;\n                box-shadow: none;\n                overflow: visible !important;\n                border: 3px solid #0f172a !important;\n            }\n            .no-print {\n                display: none;\n            }\n        }\n\n        /* subm-modern-dark-print-lines */\n        .page table, .page th, .page td { border-color:#111827 !important; }\n        .page .border-gray-100, .page .border-gray-200, .page .border-gray-300, .page .border-slate-300, .page .border-slate-700 { border-color:#111827 !important; }\n        .page .divide-gray-200 > :not([hidden]) ~ :not([hidden]) { border-color:#111827 !important; }\n    \n/* subm-modern-a4-border-layout */\n@page { size:A4; margin:12.7mm; }\n.page { width:190mm !important; min-height:277mm !important; border:3px solid #0f172a !important; box-sizing:border-box !important; }\n@media print { .page { margin:0 auto !important; width:184mm !important; min-height:271mm !important; height:auto !important; box-shadow:none !important; overflow:visible !important; border:3px solid #0f172a !important; } }\n\n/* subm-modern-history-grid-fix */\n.subm-history-table{border-collapse:collapse !important;border-spacing:0 !important;table-layout:fixed !important;width:100% !important;}\n.subm-history-table th,.subm-history-table td{border-color:#111827 !important;}\n.subm-history-table th,.subm-history-table td{vertical-align:middle;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}\n.subm-history-table thead th{padding-top:2px !important;padding-bottom:2px !important;}\n.subm-history-table tbody td{padding-top:3px !important;padding-bottom:3px !important;line-height:1.15 !important;}\n.subm-history-table th:nth-child(1),.subm-history-table td:nth-child(1){width:22% !important;}\n.subm-history-table th:nth-child(2),.subm-history-table td:nth-child(2){width:13% !important;}\n.subm-history-table th:nth-child(3),.subm-history-table td:nth-child(3){width:17% !important;}\n.subm-history-table th:nth-child(4),.subm-history-table td:nth-child(4){width:17% !important;}\n.subm-history-table th:nth-child(5),.subm-history-table td:nth-child(5){width:13% !important;}\n.subm-history-table th:nth-child(6),.subm-history-table td:nth-child(6){width:18% !important;}\n.subm-history-table tbody td{border-right:1px solid #111827 !important;border-bottom:1px solid #111827 !important;}\n.subm-history-table tbody td:last-child{border-right:0 !important;}\n@media print{.subm-history-table th,.subm-history-table td{border-color:#000 !important;}.subm-history-table tbody td{border-right:1px solid #000 !important;border-bottom:1px solid #000 !important;}}\n\n/* subm-template-print-consistency */\n@media print { body { -webkit-print-color-adjust: exact; print-color-adjust: exact; } }\n</style>\n</head>\n<body>\n    {{paid_stamp}}\n\n    <!-- Print Button (Hidden in Print) -->\n    <button onclick=\"window.print()\" class=\"fixed top-6 right-6 bg-slate-900 text-white px-5 py-2.5 rounded-lg shadow-xl no-print z-50 hover:bg-slate-800 font-bold flex items-center gap-2 border-2 border-yellow-500 transition-all\">\n        <svg xmlns=\"http://www.w3.org/2003/svg\" width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"6 9 6 2 18 2 18 9\"></polyline><path d=\"M6 18H4a2 2 0 0 1-2-2v-5a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2v5a2 2 0 0 1-2 2h-2\"></path><rect x=\"6\" y=\"14\" width=\"12\" height=\"8\"></rect></svg>\n        Print Bill\n    </button>\n\n    <!-- A4 Page Container -->\n    <div class=\"page w-[190mm] min-h-[277mm] bg-white border-[3px] border-slate-900 flex flex-col font-sans relative shadow-2xl box-border text-slate-900 mx-auto\">\n        \n        <!-- Header -->\n        <div class=\"bg-slate-900 text-white p-5 flex items-center justify-between border-b-4 border-yellow-600\">\n            <div class=\"flex items-center gap-4\">\n                <!-- Logo Placeholder -->\n                <div class=\"h-14 w-14 bg-white rounded-full flex items-center justify-center text-slate-900 font-bold border-2 border-yellow-600 overflow-hidden\">\n                    <img src=\"{{society_logo}}\" alt=\"Logo\" class=\"object-cover h-full w-full\">\n                </div>\n                <div>\n                    <h1 class=\"text-2xl font-black uppercase tracking-widest text-white\">{{society_name}}</h1>\n                    <p class=\"text-[9px] font-medium mt-0.5 text-gray-300\">{{society_address}}</p>\n                    <p class=\"text-[9px] font-bold mt-0.5 text-yellow-500\">Mobile: {{society_mobile}}</p>\n                </div>\n            </div>\n            <div class=\"text-right\">\n                <span class=\"bg-yellow-600 text-black px-3 py-1 rounded-sm text-[10px] uppercase tracking-widest font-black shadow-lg\">Utility Invoice</span>\n                <p class=\"text-[9px] mt-1 text-gray-400\">NTN: 1234567-8</p>\n            </div>\n        </div>\n\n        <!-- Summary Grid -->\n        <div class=\"grid grid-cols-6 border-b border-gray-300 text-center text-[10px] divide-x divide-gray-300 mb-3 bg-white\">\n            <div class=\"flex flex-col\">\n                <div class=\"py-1.5 bg-slate-50 font-bold text-slate-500 uppercase border-b border-gray-200\">Bill No</div>\n                <div class=\"py-2 font-mono font-black text-slate-900\">{{bill_no}}</div>\n            </div>\n            <div class=\"flex flex-col\">\n                <div class=\"py-1.5 bg-slate-50 font-bold text-slate-500 uppercase border-b border-gray-200\">Consumer ID</div>\n                <div class=\"py-2 font-mono font-black text-slate-900\">{{consumer_id}}</div>\n            </div>\n            <div class=\"flex flex-col\">\n                <div class=\"py-1.5 bg-slate-50 font-bold text-slate-500 uppercase border-b border-gray-200\">Property</div>\n                <div class=\"py-2 font-mono font-black text-slate-900\">{{property_id}}</div>\n            </div>\n            <div class=\"flex flex-col\">\n                <div class=\"py-1.5 bg-slate-50 font-bold text-slate-500 uppercase border-b border-gray-200\">Billing Month</div>\n                <div class=\"py-2 font-mono font-black text-slate-900\">{{billing_month}}</div>\n            </div>\n            <div class=\"flex flex-col\">\n                <div class=\"py-1.5 bg-slate-50 font-bold text-slate-500 uppercase border-b border-gray-200\">Issue Date</div>\n                <div class=\"py-2 font-mono font-black text-slate-900\">{{issue_date}}</div>\n            </div>\n            <div class=\"flex flex-col bg-yellow-50\">\n                <div class=\"py-1.5 bg-yellow-100 font-bold text-yellow-900 uppercase border-b border-yellow-200\">Due Date</div>\n                <div class=\"py-2 text-red-600 font-black font-mono\">{{due_date}}</div>\n            </div>\n        </div>\n\n        <!-- Main Content Area -->\n        <div class=\"flex gap-4 px-6\">\n            \n            <!-- Left Column: Details -->\n            <div class=\"flex-[7] flex flex-col gap-2\">\n                \n                <!-- Consumer Info -->\n                <section>\n                    <h3 class=\"bg-slate-900 px-2 py-1 text-[10px] font-bold text-white uppercase tracking-wide flex justify-between items-center\">\n                        Consumer Information\n                        <span class=\"text-yellow-500\">RESIDENTIAL</span>\n                    </h3>\n                    <div class=\"p-2 border border-t-0 border-gray-300 bg-slate-50/50\">\n                        <p class=\"text-[10px] font-black text-slate-700 uppercase tracking-wide subm-modern-consumer-before-client\">Consumer ID: {{consumer_id}}</p>\n                        <p class=\"text-base font-black text-slate-900 uppercase\">{{client_name}}</p>\n                        <p class=\"text-[10px] font-semibold text-slate-500 mt-0.5 uppercase\">Resident / Owner</p>\n                        <p class=\"text-xs text-slate-700 mt-1 leading-relaxed\">{{client_address}}</p>\n                    </div>\n                </section>\n\n                <!-- Reading Details -->\n                <section>\n                    <h3 class=\"bg-gray-200 px-2 py-1 text-[10px] font-black text-slate-700 border-l-4 border-slate-900 uppercase tracking-wide\">Meter Reading Details</h3>\n                    <div class=\"border border-t-0 border-gray-300 overflow-hidden\">\n                        <table class=\"w-full text-[10px]\">\n                            <thead class=\"bg-gray-100 text-slate-600 border-b border-gray-300 uppercase font-bold\">\n                                <tr>\n                                    <th class=\"py-1.5 px-2 text-center border-r border-gray-300\">Previous</th>\n                                    <th class=\"py-1.5 px-2 text-center border-r border-gray-300\">Current</th>\n                                    <th class=\"py-1.5 px-2 text-center border-r border-gray-300\">Units</th>\n                                    <th class=\"py-1.5 px-2 text-center\">Rate</th>\n                                </tr>\n                            </thead>\n                            <tbody class=\"text-slate-900 font-medium text-center\">\n                                <tr>\n                                    <td class=\"py-2 border-r border-gray-300 text-gray-500\">{{prev_reading}}</td>\n                                    <td class=\"py-2 border-r border-gray-300 font-bold\">{{curr_reading}}</td>\n                                    <td class=\"py-2 border-r border-gray-300 font-black bg-yellow-50\">{{units_consumed}}</td>\n                                    <td class=\"py-2\">{{unit_price}}</td>\n                                </tr>\n                                <tr class=\"bg-slate-50 border-t border-gray-200\">\n                                    <td colspan=\"4\" class=\"py-1.5 text-[10px] font-bold text-slate-700\">\n                                        <span class=\"uppercase text-[9px] tracking-wide text-slate-500 mr-2\">Calculation:</span>\n                                        {{energy_calculation}}\n                                    </td>\n                                </tr>\n                            </tbody>\n                        </table>\n                    </div>\n                </section>\n\n                <!-- Meter Image & Small Advertisement -->\n                <div class=\"flex gap-2\">\n                    <!-- Meter Image -->\n                    <div class=\"flex-1\">\n                        <h3 class=\"bg-gray-200 px-2 py-1 text-[10px] font-black text-slate-700 border-l-4 border-slate-900 uppercase tracking-wide\">Ref. Meter Image</h3>\n                        <div class=\"border border-t-0 border-gray-300 bg-white h-24 overflow-hidden\">\n                            <div class=\"w-full h-full flex items-center justify-center overflow-hidden\">\n                                {{meter_image}}\n                            </div>\n                        </div>\n                    </div>\n                    \n                    <!-- Small Ad Area -->\n                    <div class=\"flex-1\">\n                        <h3 class=\"bg-gray-200 px-2 py-1 text-[10px] font-black text-slate-700 border-l-4 border-slate-900 uppercase tracking-wide\">Preview Caution</h3>\n                        <div class=\"mt-0.5 bg-slate-50 p-2 text-left h-24 overflow-auto\">\n                             {{bill_notice}}\n                        </div>\n                    </div>\n                </div>\n\n                <!-- History Table -->\n                <section>\n                    <h3 class=\"bg-gray-200 px-2 py-1 text-[10px] font-black text-slate-700 border-l-4 border-slate-900 uppercase tracking-wide\">Payment History (Last 12 Months)</h3>\n                    <div class=\"border border-t-0 border-gray-300 overflow-hidden\">\n                        <table class=\"w-full text-[8px] table-fixed subm-history-table\">\n                            <thead class=\"bg-gray-100 text-slate-600 border-b border-gray-300 uppercase font-bold\">\n                                <tr>\n                                    <th class=\"w-[22%] py-0.5 px-1.5 text-left border-r border-gray-300\">Month</th>\n                                    <th class=\"w-[13%] py-0.5 px-1 text-center border-r border-gray-300\">Units</th>\n                                    <th class=\"w-[17%] py-0.5 px-1 text-center border-r border-gray-300\">Bill AMT</th>\n                                    <th class=\"w-[17%] py-0.5 px-1 text-center border-r border-gray-300\">Paid AMT</th>\n                                    <th class=\"w-[13%] py-0.5 px-1 text-center border-r border-gray-300\">Adj.</th>\n                                    <th class=\"w-[18%] py-0.5 px-1 text-center\">Status</th>\n                                </tr>\n                            </thead>\n                            <tbody class=\"divide-y divide-gray-200 text-slate-800 font-medium leading-none\">\n                                {{history_rows}}\n                            </tbody>\n                        </table>\n                    </div>\n                </section>\n                \n            </div>\n\n            <!-- Right Column: Financials -->\n            <div class=\"flex-[5] flex flex-col\">\n                <h3 class=\"bg-slate-900 px-2 py-1 text-[10px] font-bold text-white uppercase tracking-wide text-center\">Current Charges</h3>\n                \n                <!-- Charges Table -->\n                <div class=\"border border-t-0 border-gray-300 mt-0 overflow-hidden shadow-sm\" data-total=\"{{total_amount}}\" data-late-percent=\"{{late_fee_percent}}\" data-due-date-iso=\"{{due_date_iso}}\" data-adjust-debit=\"{{adjustment_debit}}\" data-adjust-credit=\"{{adjustment_credit}}\">\n                    <table class=\"w-full text-[10px]\">\n                        <thead class=\"bg-gray-100 border-b border-gray-300\">\n                            <tr>\n                                <th class=\"p-1.5 text-left text-slate-600 font-bold uppercase border-r border-gray-300\">Description</th>\n                                <th class=\"p-1.5 text-right text-slate-600 font-bold uppercase\">Amount</th>\n                            </tr>\n                        </thead>\n                        <tbody class=\"divide-y divide-gray-200\">\n                            {{utility_rows}}\n                            {{maintenance_rows}}\n                            {{other_rows}}\n                            \n                            <!-- Static Footer Rows -->\n                            <tr class=\"bg-slate-50 text-slate-900 font-bold\">\n                                <td class=\"p-1.5 border-r border-gray-300\">Arrears / Previous</td>\n                                <td class=\"p-1.5 text-right\">{{arrears}}</td>\n                            </tr>\n                            \n                            <!-- Total Block -->\n                            <tr class=\"bg-slate-900 text-white font-black border-t-2 border-yellow-600\">\n                                <td class=\"p-2 text-xs border-r border-slate-700 uppercase tracking-wide\">Payable Within Due</td>\n                                <td class=\"p-2 text-right text-lg\">{{total_amount}}</td>\n                            </tr>\n                            \n                            <tr class=\"bg-white text-red-600 font-bold border-t border-gray-300\">\n                                <td class=\"p-1.5 text-[9px] border-r border-gray-300 text-right uppercase pt-2\">Late Fee ({{late_fee_percent}}%)</td>\n                                <td class=\"p-1.5 text-right text-xs pt-2\"><span id=\"late_fee_val\">{{late_fee}}</span></td>\n                            </tr>\n                            <tr class=\"bg-slate-50 text-slate-900 font-medium\">\n                                <td class=\"p-1.5 border-r border-gray-300\">Adjustment - Debit (Increase)</td>\n                                <td class=\"p-1.5 text-right\">{{adjustment_debit}}</td>\n                            </tr>\n                            <tr class=\"bg-slate-50 text-slate-900 font-medium\">\n                                <td class=\"p-1.5 border-r border-gray-300\">Adjustment - Credit (Decrease)</td>\n                                <td class=\"p-1.5 text-right\">{{adjustment_credit}}</td>\n                            </tr>\n                            <tr class=\"bg-slate-50 text-slate-700 text-[10px]\">\n                                <td class=\"p-1.5 border-r border-gray-300\" colspan=\"2\">Note: {{adjustment_note}}</td>\n                            </tr>\n                            <tr class=\"bg-red-50 text-slate-900 font-bold border-t border-gray-200\">\n                                <td class=\"p-1.5 text-[9px] border-r border-gray-300 text-right uppercase\">Payable After Due</td>\n                                <td class=\"p-1.5 text-right text-base font-black\"><span id=\"payable_after_val\">{{payable_after_due}}</span></td>\n                            </tr>\n                        </tbody>\n                    </table>\n                </div>\n\n                <!-- Combined Bank & Scan Section -->\n                <div class=\"mt-2 border border-gray-300 bg-white p-2 shadow-sm text-[9px] font-medium leading-tight text-slate-600\">\n                    {{bank_details}}\n                </div>\n\n                <!-- Vertical Fill Ad Space -->\n                <div class=\"mt-2\">\n                    <div class=\"h-40 border border-gray-300 bg-slate-50 flex flex-col items-center justify-center text-center overflow-hidden rounded-lg\">\n                        {{advertisement}}\n                    </div>\n                </div>\n\n            </div>\n        </div>\n\n        <!-- Separator -->\n        <div class=\"w-full py-4 relative px-6 mt-2\">\n            <div class=\"absolute top-1/2 left-0 w-full border-t-[2px] border-dashed border-slate-400\"></div>\n            <div class=\"absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 bg-white px-3 text-slate-500 text-[10px] font-bold flex items-center gap-2\">\n                <span class=\"text-base rotate-180\">✂</span> TEAR OFF HERE FOR RECORD <span class=\"text-base\">✂</span>\n            </div>\n        </div>\n\n        <!-- Duplicate Slip (Bank Copy) -->\n        <div class=\"bg-slate-50 border-t-4 border-slate-900 p-4 mx-6 mb-6 shadow-inner\">\n            <div class=\"flex justify-between items-start border-b border-gray-300 pb-2 mb-3\">\n                <div class=\"flex items-center gap-2\">\n                    <div class=\"h-8 w-1.5 bg-yellow-600\"></div>\n                    <div>\n                        <h2 class=\"text-sm font-black text-slate-900 uppercase tracking-wide\">Bank Copy / Office Copy</h2>\n                        <p class=\"text-[9px] text-slate-500 font-bold uppercase tracking-wider\">{{society_name}}</p>\n                    </div>\n                </div>\n                <div class=\"text-right\">\n                    <p class=\"text-[10px] font-black text-slate-900 uppercase\">{{billing_month}}</p>\n                    <p class=\"text-[9px] text-slate-500 font-bold\">Billing Month</p>\n                </div>\n            </div>\n\n            <div class=\"flex gap-4 items-end\">\n                <div class=\"flex-grow grid grid-cols-4 gap-y-2 gap-x-4 text-[10px]\">\n                    <div>\n                        <p class=\"text-slate-500 uppercase font-bold text-[8px]\">Bill No</p>\n                        <p class=\"font-black text-slate-900 text-xs border-b border-slate-300 pb-0.5\">{{bill_no}}</p>\n                    </div>\n                    <div class=\"col-span-2\">\n                        <p class=\"text-slate-500 uppercase font-bold text-[8px]\">Consumer Name</p>\n                        <p class=\"font-black text-slate-900 text-xs border-b border-slate-300 pb-0.5 truncate\">{{client_name}}</p>\n                    </div>\n                    <div>\n                        <p class=\"text-slate-500 uppercase font-bold text-[8px]\">House/Plot #</p>\n                        <p class=\"font-black text-slate-900 text-xs border-b border-slate-300 pb-0.5\">{{property_id}}</p>\n                    </div>\n                    <div>\n                        <p class=\"text-slate-500 uppercase font-bold text-[8px]\">Due Date</p>\n                        <p class=\"font-black text-red-600 text-xs border-b border-slate-300 pb-0.5\">{{due_date}}</p>\n                    </div>\n                    <div>\n                         <p class=\"text-slate-500 uppercase font-bold text-[8px]\">Payable (Within)</p>\n                         <p class=\"font-black text-slate-900 text-xs border-b border-slate-300 pb-0.5\">{{total_amount}}</p>\n                    </div>\n                    <div class=\"col-span-2\">\n                         <p class=\"text-slate-500 uppercase font-bold text-[8px]\">Payable (After)</p>\n                         <p class=\"font-black text-slate-900 text-xs border-b border-slate-300 pb-0.5\">{{payable_after_due}}</p>\n                    </div>\n                </div>\n            </div>\n        </div>\n        {{paid_slip_block}}\n\n    </div>\n\n    <script>\n        (function(){\n            function parseNum(s){ if(!s) return 0; s = String(s).replace(/[^0-9.\\-]/g,\'\'); s = s.replace(\',\',\'\'); var n = parseFloat(s); return isNaN(n)?0:n; }\n            try{\n                var container = document.querySelector(\'.border.border-t-0.border-gray-300.mt-0.overflow-hidden.shadow-sm\');\n                if(!container) container = document.querySelector(\'[data-total]\');\n                if(container){\n                    var total = parseNum(container.getAttribute(\'data-total\') || document.querySelector(\'[data-total]\')?.getAttribute(\'data-total\'));\n                    var debit = parseNum(container.getAttribute(\'data-adjust-debit\')) || 0;\n                    var credit = parseNum(container.getAttribute(\'data-adjust-credit\')) || 0;\n                    var lateEl = document.getElementById(\'late_fee_val\');\n                    var lateAmt = parseNum(lateEl ? lateEl.textContent : 0);\n                    var payableAfter = total + lateAmt + debit - credit;\n                    if(lateEl) lateEl.textContent = lateAmt.toFixed(2);\n                    var payEl = document.getElementById(\'payable_after_val\'); if(payEl) payEl.textContent = payableAfter.toFixed(2);\n                }\n            }catch(e){console && console.error && console.error(e);}\n        })();\n    </script>\n\n    </body>\n</html>\n', '', 0, '2026-08-30 21:27:47');
INSERT INTO `billing_templates` (`id`, `society_id`, `name`, `slug`, `template_type`, `html_content`, `css_content`, `is_default`, `created_at`) VALUES
(5, 1, 'My temp', 'my-temp', 'print_bill', '﻿<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>Utility Bill Template</title>\n    <!-- Tailwind CSS for the classes used in the template -->\n    <script src=\"https://cdn.tailwindcss.com\"></script>\n    <style>\n        @import url(\'https://fonts.googleapis.com/css2?family=Inter:wght@300;400;600;800;900&display=swap\');\n        \n        body {\n            font-family: \'Inter\', sans-serif;\n            background-color: #f3f4f6;\n            display: flex;\n            justify-content: center;\n            padding: 20px;\n        }\n\n        @page {\n            size: A4;\n            margin: 12.7mm; /* default-like printer margin (~0.5in) */\n        }\n\n        @media print {\n            body {\n                margin: 0;\n                padding: 0;\n                background-color: white;\n                -webkit-print-color-adjust: exact;\n                print-color-adjust: exact;\n            }\n            .page {\n                margin: 0 auto;\n                width: 184mm; /* fit within A4 printable area with default margins */\n                min-height: 271mm;\n                height: auto !important;\n                box-shadow: none;\n                overflow: visible !important;\n                border: 3px solid #0f172a !important;\n            }\n            .no-print {\n                display: none;\n            }\n        }\n\n        /* subm-modern-dark-print-lines */\n        .page table, .page th, .page td { border-color:#111827 !important; }\n        .page .border-gray-100, .page .border-gray-200, .page .border-gray-300, .page .border-slate-300, .page .border-slate-700 { border-color:#111827 !important; }\n        .page .divide-gray-200 > :not([hidden]) ~ :not([hidden]) { border-color:#111827 !important; }\n    \n/* subm-modern-a4-border-layout */\n@page { size:A4; margin:12.7mm; }\n.page { width:190mm !important; min-height:277mm !important; border:3px solid #0f172a !important; box-sizing:border-box !important; }\n@media print { .page { margin:0 auto !important; width:184mm !important; min-height:271mm !important; height:auto !important; box-shadow:none !important; overflow:visible !important; border:3px solid #0f172a !important; } }\n\n/* subm-modern-history-grid-fix */\n.subm-history-table{border-collapse:collapse !important;border-spacing:0 !important;table-layout:fixed !important;width:100% !important;}\n.subm-history-table th,.subm-history-table td{border-color:#111827 !important;}\n.subm-history-table th,.subm-history-table td{vertical-align:middle;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}\n.subm-history-table thead th{padding-top:2px !important;padding-bottom:2px !important;}\n.subm-history-table tbody td{padding-top:3px !important;padding-bottom:3px !important;line-height:1.15 !important;}\n.subm-history-table th:nth-child(1),.subm-history-table td:nth-child(1){width:22% !important;}\n.subm-history-table th:nth-child(2),.subm-history-table td:nth-child(2){width:13% !important;}\n.subm-history-table th:nth-child(3),.subm-history-table td:nth-child(3){width:17% !important;}\n.subm-history-table th:nth-child(4),.subm-history-table td:nth-child(4){width:17% !important;}\n.subm-history-table th:nth-child(5),.subm-history-table td:nth-child(5){width:13% !important;}\n.subm-history-table th:nth-child(6),.subm-history-table td:nth-child(6){width:18% !important;}\n.subm-history-table tbody td{border-right:1px solid #111827 !important;border-bottom:1px solid #111827 !important;}\n.subm-history-table tbody td:last-child{border-right:0 !important;}\n@media print{.subm-history-table th,.subm-history-table td{border-color:#000 !important;}.subm-history-table tbody td{border-right:1px solid #000 !important;border-bottom:1px solid #000 !important;}}\n\n/* subm-template-print-consistency */\n@media print { body { -webkit-print-color-adjust: exact; print-color-adjust: exact; } }\n</style>\n</head>\n<body>\n    {{paid_stamp}}\n\n    <!-- Print Button (Hidden in Print) -->\n    <button onclick=\"window.print()\" class=\"fixed top-6 right-6 bg-slate-900 text-white px-5 py-2.5 rounded-lg shadow-xl no-print z-50 hover:bg-slate-800 font-bold flex items-center gap-2 border-2 border-yellow-500 transition-all\">\n        <svg xmlns=\"http://www.w3.org/2003/svg\" width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"6 9 6 2 18 2 18 9\"></polyline><path d=\"M6 18H4a2 2 0 0 1-2-2v-5a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2v5a2 2 0 0 1-2 2h-2\"></path><rect x=\"6\" y=\"14\" width=\"12\" height=\"8\"></rect></svg>\n        Print Bill\n    </button>\n\n    <!-- A4 Page Container -->\n    <div class=\"page w-[190mm] min-h-[277mm] bg-white border-[3px] border-slate-900 flex flex-col font-sans relative shadow-2xl box-border text-slate-900 mx-auto\">\n        \n        <!-- Header -->\n        <div class=\"bg-slate-900 text-white p-5 flex items-center justify-between border-b-4 border-yellow-600\">\n            <div class=\"flex items-center gap-4\">\n                <!-- Logo Placeholder -->\n                <div class=\"h-14 w-14 bg-white rounded-full flex items-center justify-center text-slate-900 font-bold border-2 border-yellow-600 overflow-hidden\">\n                    <img src=\"{{society_logo}}\" alt=\"Logo\" class=\"object-cover h-full w-full\">\n                </div>\n                <div>\n                    <h1 class=\"text-2xl font-black uppercase tracking-widest text-white\">{{society_name}}</h1>\n                    <p class=\"text-[9px] font-medium mt-0.5 text-gray-300\">{{society_address}}</p>\n                    <p class=\"text-[9px] font-bold mt-0.5 text-yellow-500\">Mobile: {{society_mobile}}</p>\n                </div>\n            </div>\n            <div class=\"text-right\">\n                <span class=\"bg-yellow-600 text-black px-3 py-1 rounded-sm text-[10px] uppercase tracking-widest font-black shadow-lg\">Utility Invoice</span>\n                <p class=\"text-[9px] mt-1 text-gray-400\">NTN: 1234567-8</p>\n            </div>\n        </div>\n\n        <!-- Summary Grid -->\n        <div class=\"grid grid-cols-6 border-b border-gray-300 text-center text-[10px] divide-x divide-gray-300 mb-3 bg-white\">\n            <div class=\"flex flex-col\">\n                <div class=\"py-1.5 bg-slate-50 font-bold text-slate-500 uppercase border-b border-gray-200\">Bill No</div>\n                <div class=\"py-2 font-mono font-black text-slate-900\">{{bill_no}}</div>\n            </div>\n            <div class=\"flex flex-col\">\n                <div class=\"py-1.5 bg-slate-50 font-bold text-slate-500 uppercase border-b border-gray-200\">Consumer ID</div>\n                <div class=\"py-2 font-mono font-black text-slate-900\">{{consumer_id}}</div>\n            </div>\n            <div class=\"flex flex-col\">\n                <div class=\"py-1.5 bg-slate-50 font-bold text-slate-500 uppercase border-b border-gray-200\">Property</div>\n                <div class=\"py-2 font-mono font-black text-slate-900\">{{property_id}}</div>\n            </div>\n            <div class=\"flex flex-col\">\n                <div class=\"py-1.5 bg-slate-50 font-bold text-slate-500 uppercase border-b border-gray-200\">Billing Month</div>\n                <div class=\"py-2 font-mono font-black text-slate-900\">{{billing_month}}</div>\n            </div>\n            <div class=\"flex flex-col\">\n                <div class=\"py-1.5 bg-slate-50 font-bold text-slate-500 uppercase border-b border-gray-200\">Issue Date</div>\n                <div class=\"py-2 font-mono font-black text-slate-900\">{{issue_date}}</div>\n            </div>\n            <div class=\"flex flex-col bg-yellow-50\">\n                <div class=\"py-1.5 bg-yellow-100 font-bold text-yellow-900 uppercase border-b border-yellow-200\">Due Date</div>\n                <div class=\"py-2 text-red-600 font-black font-mono\">{{due_date}}</div>\n            </div>\n        </div>\n\n        <!-- Main Content Area -->\n        <div class=\"flex gap-4 px-6\">\n            \n            <!-- Left Column: Details -->\n            <div class=\"flex-[7] flex flex-col gap-2\">\n                \n                <!-- Consumer Info -->\n                <section>\n                    <h3 class=\"bg-slate-900 px-2 py-1 text-[10px] font-bold text-white uppercase tracking-wide flex justify-between items-center\">\n                        Consumer Information\n                        <span class=\"text-yellow-500\">RESIDENTIAL</span>\n                    </h3>\n                    <div class=\"p-2 border border-t-0 border-gray-300 bg-slate-50/50\">\n                        <p class=\"text-[10px] font-black text-slate-700 uppercase tracking-wide subm-modern-consumer-before-client\">Consumer ID: {{consumer_id}}</p>\n                        <p class=\"text-base font-black text-slate-900 uppercase\">{{client_name}}</p>\n                        <p class=\"text-[10px] font-semibold text-slate-500 mt-0.5 uppercase\">Resident / Owner</p>\n                        <p class=\"text-xs text-slate-700 mt-1 leading-relaxed\">{{client_address}}</p>\n                    </div>\n                </section>\n\n                <!-- Reading Details -->\n                <section>\n                    <h3 class=\"bg-gray-200 px-2 py-1 text-[10px] font-black text-slate-700 border-l-4 border-slate-900 uppercase tracking-wide\">Meter Reading Details</h3>\n                    <div class=\"border border-t-0 border-gray-300 overflow-hidden\">\n                        <table class=\"w-full text-[10px]\">\n                            <thead class=\"bg-gray-100 text-slate-600 border-b border-gray-300 uppercase font-bold\">\n                                <tr>\n                                    <th class=\"py-1.5 px-2 text-center border-r border-gray-300\">Previous</th>\n                                    <th class=\"py-1.5 px-2 text-center border-r border-gray-300\">Current</th>\n                                    <th class=\"py-1.5 px-2 text-center border-r border-gray-300\">Units</th>\n                                    <th class=\"py-1.5 px-2 text-center\">Rate</th>\n                                </tr>\n                            </thead>\n                            <tbody class=\"text-slate-900 font-medium text-center\">\n                                <tr>\n                                    <td class=\"py-2 border-r border-gray-300 text-gray-500\">{{prev_reading}}</td>\n                                    <td class=\"py-2 border-r border-gray-300 font-bold\">{{curr_reading}}</td>\n                                    <td class=\"py-2 border-r border-gray-300 font-black bg-yellow-50\">{{units_consumed}}</td>\n                                    <td class=\"py-2\">{{unit_price}}</td>\n                                </tr>\n                                <tr class=\"bg-slate-50 border-t border-gray-200\">\n                                    <td colspan=\"4\" class=\"py-1.5 text-[10px] font-bold text-slate-700\">\n                                        <span class=\"uppercase text-[9px] tracking-wide text-slate-500 mr-2\">Calculation:</span>\n                                        {{energy_calculation}}\n                                    </td>\n                                </tr>\n                            </tbody>\n                        </table>\n                    </div>\n                </section>\n\n                <!-- Meter Image & Small Advertisement -->\n                <div class=\"flex gap-2\">\n                    <!-- Meter Image -->\n                    <div class=\"flex-1\">\n                        <h3 class=\"bg-gray-200 px-2 py-1 text-[10px] font-black text-slate-700 border-l-4 border-slate-900 uppercase tracking-wide\">Ref. Meter Image</h3>\n                        <div class=\"border border-t-0 border-gray-300 bg-white h-24 overflow-hidden\">\n                            <div class=\"w-full h-full flex items-center justify-center overflow-hidden\">\n                                {{meter_image}}\n                            </div>\n                        </div>\n                    </div>\n                    \n                    <!-- Small Ad Area -->\n                    <div class=\"flex-1\">\n                        <h3 class=\"bg-gray-200 px-2 py-1 text-[10px] font-black text-slate-700 border-l-4 border-slate-900 uppercase tracking-wide\">Preview Caution</h3>\n                        <div class=\"mt-0.5 bg-slate-50 p-2 text-left h-24 overflow-auto\">\n                             {{bill_notice}}\n                        </div>\n                    </div>\n                </div>\n\n                <!-- History Table -->\n                <section>\n                    <h3 class=\"bg-gray-200 px-2 py-1 text-[10px] font-black text-slate-700 border-l-4 border-slate-900 uppercase tracking-wide\">Payment History (Last 12 Months)</h3>\n                    <div class=\"border border-t-0 border-gray-300 overflow-hidden\">\n                        <table class=\"w-full text-[8px] table-fixed subm-history-table\">\n                            <thead class=\"bg-gray-100 text-slate-600 border-b border-gray-300 uppercase font-bold\">\n                                <tr>\n                                    <th class=\"w-[22%] py-0.5 px-1.5 text-left border-r border-gray-300\">Month</th>\n                                    <th class=\"w-[13%] py-0.5 px-1 text-center border-r border-gray-300\">Units</th>\n                                    <th class=\"w-[17%] py-0.5 px-1 text-center border-r border-gray-300\">Bill AMT</th>\n                                    <th class=\"w-[17%] py-0.5 px-1 text-center border-r border-gray-300\">Paid AMT</th>\n                                    <th class=\"w-[13%] py-0.5 px-1 text-center border-r border-gray-300\">Adj.</th>\n                                    <th class=\"w-[18%] py-0.5 px-1 text-center\">Status</th>\n                                </tr>\n                            </thead>\n                            <tbody class=\"divide-y divide-gray-200 text-slate-800 font-medium leading-none\">\n                                {{history_rows}}\n                            </tbody>\n                        </table>\n                    </div>\n                </section>\n                \n            </div>\n\n            <!-- Right Column: Financials -->\n            <div class=\"flex-[5] flex flex-col\">\n                <h3 class=\"bg-slate-900 px-2 py-1 text-[10px] font-bold text-white uppercase tracking-wide text-center\">Current Charges</h3>\n                \n                <!-- Charges Table -->\n                <div class=\"border border-t-0 border-gray-300 mt-0 overflow-hidden shadow-sm\" data-total=\"{{total_amount}}\" data-late-percent=\"{{late_fee_percent}}\" data-due-date-iso=\"{{due_date_iso}}\" data-adjust-debit=\"{{adjustment_debit}}\" data-adjust-credit=\"{{adjustment_credit}}\">\n                    <table class=\"w-full text-[10px]\">\n                        <thead class=\"bg-gray-100 border-b border-gray-300\">\n                            <tr>\n                                <th class=\"p-1.5 text-left text-slate-600 font-bold uppercase border-r border-gray-300\">Description</th>\n                                <th class=\"p-1.5 text-right text-slate-600 font-bold uppercase\">Amount</th>\n                            </tr>\n                        </thead>\n                        <tbody class=\"divide-y divide-gray-200\">\n                            {{utility_rows}}\n                            {{maintenance_rows}}\n                            {{other_rows}}\n                            \n                            <!-- Static Footer Rows -->\n                            <tr class=\"bg-slate-50 text-slate-900 font-bold\">\n                                <td class=\"p-1.5 border-r border-gray-300\">Arrears / Previous</td>\n                                <td class=\"p-1.5 text-right\">{{arrears}}</td>\n                            </tr>\n                            \n                            <!-- Total Block -->\n                            <tr class=\"bg-slate-900 text-white font-black border-t-2 border-yellow-600\">\n                                <td class=\"p-2 text-xs border-r border-slate-700 uppercase tracking-wide\">Payable Within Due</td>\n                                <td class=\"p-2 text-right text-lg\">{{total_amount}}</td>\n                            </tr>\n                            \n                            <tr class=\"bg-white text-red-600 font-bold border-t border-gray-300\">\n                                <td class=\"p-1.5 text-[9px] border-r border-gray-300 text-right uppercase pt-2\">Late Fee ({{late_fee_percent}}%)</td>\n                                <td class=\"p-1.5 text-right text-xs pt-2\"><span id=\"late_fee_val\">{{late_fee}}</span></td>\n                            </tr>\n                            <tr class=\"bg-slate-50 text-slate-900 font-medium\">\n                                <td class=\"p-1.5 border-r border-gray-300\">Adjustment - Debit (Increase)</td>\n                                <td class=\"p-1.5 text-right\">{{adjustment_debit}}</td>\n                            </tr>\n                            <tr class=\"bg-slate-50 text-slate-900 font-medium\">\n                                <td class=\"p-1.5 border-r border-gray-300\">Adjustment - Credit (Decrease)</td>\n                                <td class=\"p-1.5 text-right\">{{adjustment_credit}}</td>\n                            </tr>\n                            <tr class=\"bg-slate-50 text-slate-700 text-[10px]\">\n                                <td class=\"p-1.5 border-r border-gray-300\" colspan=\"2\">Note: {{adjustment_note}}</td>\n                            </tr>\n                            <tr class=\"bg-red-50 text-slate-900 font-bold border-t border-gray-200\">\n                                <td class=\"p-1.5 text-[9px] border-r border-gray-300 text-right uppercase\">Payable After Due</td>\n                                <td class=\"p-1.5 text-right text-base font-black\"><span id=\"payable_after_val\">{{payable_after_due}}</span></td>\n                            </tr>\n                        </tbody>\n                    </table>\n                </div>\n\n                <!-- Combined Bank & Scan Section -->\n                <div class=\"mt-2 border border-gray-300 bg-white p-2 shadow-sm text-[9px] font-medium leading-tight text-slate-600\">\n                    {{bank_details}}\n                </div>\n\n                <!-- Vertical Fill Ad Space -->\n                <div class=\"mt-2\">\n                    <div class=\"h-40 border border-gray-300 bg-slate-50 flex flex-col items-center justify-center text-center overflow-hidden rounded-lg\">\n                        {{advertisement}}\n                    </div>\n                </div>\n\n            </div>\n        </div>\n\n        <!-- Separator -->\n        <div class=\"w-full py-4 relative px-6 mt-2\">\n            <div class=\"absolute top-1/2 left-0 w-full border-t-[2px] border-dashed border-slate-400\"></div>\n            <div class=\"absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 bg-white px-3 text-slate-500 text-[10px] font-bold flex items-center gap-2\">\n                <span class=\"text-base rotate-180\">✂</span> TEAR OFF HERE FOR RECORD <span class=\"text-base\">✂</span>\n            </div>\n        </div>\n\n        <!-- Duplicate Slip (Bank Copy) -->\n        <div class=\"bg-slate-50 border-t-4 border-slate-900 p-4 mx-6 mb-6 shadow-inner\">\n            <div class=\"flex justify-between items-start border-b border-gray-300 pb-2 mb-3\">\n                <div class=\"flex items-center gap-2\">\n                    <div class=\"h-8 w-1.5 bg-yellow-600\"></div>\n                    <div>\n                        <h2 class=\"text-sm font-black text-slate-900 uppercase tracking-wide\">Bank Copy / Office Copy</h2>\n                        <p class=\"text-[9px] text-slate-500 font-bold uppercase tracking-wider\">{{society_name}}</p>\n                    </div>\n                </div>\n                <div class=\"text-right\">\n                    <p class=\"text-[10px] font-black text-slate-900 uppercase\">{{billing_month}}</p>\n                    <p class=\"text-[9px] text-slate-500 font-bold\">Billing Month</p>\n                </div>\n            </div>\n\n            <div class=\"flex gap-4 items-end\">\n                <div class=\"flex-grow grid grid-cols-4 gap-y-2 gap-x-4 text-[10px]\">\n                    <div>\n                        <p class=\"text-slate-500 uppercase font-bold text-[8px]\">Bill No</p>\n                        <p class=\"font-black text-slate-900 text-xs border-b border-slate-300 pb-0.5\">{{bill_no}}</p>\n                    </div>\n                    <div class=\"col-span-2\">\n                        <p class=\"text-slate-500 uppercase font-bold text-[8px]\">Consumer Name</p>\n                        <p class=\"font-black text-slate-900 text-xs border-b border-slate-300 pb-0.5 truncate\">{{client_name}}</p>\n                    </div>\n                    <div>\n                        <p class=\"text-slate-500 uppercase font-bold text-[8px]\">House/Plot #</p>\n                        <p class=\"font-black text-slate-900 text-xs border-b border-slate-300 pb-0.5\">{{property_id}}</p>\n                    </div>\n                    <div>\n                        <p class=\"text-slate-500 uppercase font-bold text-[8px]\">Due Date</p>\n                        <p class=\"font-black text-red-600 text-xs border-b border-slate-300 pb-0.5\">{{due_date}}</p>\n                    </div>\n                    <div>\n                         <p class=\"text-slate-500 uppercase font-bold text-[8px]\">Payable (Within)</p>\n                         <p class=\"font-black text-slate-900 text-xs border-b border-slate-300 pb-0.5\">{{total_amount}}</p>\n                    </div>\n                    <div class=\"col-span-2\">\n                         <p class=\"text-slate-500 uppercase font-bold text-[8px]\">Payable (After)</p>\n                         <p class=\"font-black text-slate-900 text-xs border-b border-slate-300 pb-0.5\">{{payable_after_due}}</p>\n                    </div>\n                </div>\n            </div>\n        </div>\n        {{paid_slip_block}}\n\n    </div>\n\n    <script>\n        (function(){\n            function parseNum(s){ if(!s) return 0; s = String(s).replace(/[^0-9.\\-]/g,\'\'); s = s.replace(\',\',\'\'); var n = parseFloat(s); return isNaN(n)?0:n; }\n            try{\n                var container = document.querySelector(\'.border.border-t-0.border-gray-300.mt-0.overflow-hidden.shadow-sm\');\n                if(!container) container = document.querySelector(\'[data-total]\');\n                if(container){\n                    var total = parseNum(container.getAttribute(\'data-total\') || document.querySelector(\'[data-total]\')?.getAttribute(\'data-total\'));\n                    var debit = parseNum(container.getAttribute(\'data-adjust-debit\')) || 0;\n                    var credit = parseNum(container.getAttribute(\'data-adjust-credit\')) || 0;\n                    var lateEl = document.getElementById(\'late_fee_val\');\n                    var lateAmt = parseNum(lateEl ? lateEl.textContent : 0);\n                    var payableAfter = total + lateAmt + debit - credit;\n                    if(lateEl) lateEl.textContent = lateAmt.toFixed(2);\n                    var payEl = document.getElementById(\'payable_after_val\'); if(payEl) payEl.textContent = payableAfter.toFixed(2);\n                }\n            }catch(e){console && console.error && console.error(e);}\n        })();\n    </script>\n\n    </body>\n</html>\n', '', 0, '2026-08-30 21:27:47');
INSERT INTO `billing_templates` (`id`, `society_id`, `name`, `slug`, `template_type`, `html_content`, `css_content`, `is_default`, `created_at`) VALUES
(6, 1, 'Blue 1', 'blue-1', 'print_bill', '<!DOCTYPE html>\r\n<html lang=\"en\">\r\n<head>\r\n    <meta charset=\"UTF-8\">\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n    <title>{{society_name}} - {{document_type}}</title>\r\n    <script src=\"https://cdn.tailwindcss.com\"></script>\r\n    <link href=\"https://fonts.googleapis.com/css2?family=Roboto:wght@400;500;700;900&display=swap\" rel=\"stylesheet\">\r\n    <style>\r\n        body { \r\n            font-family: \'Roboto\', sans-serif; \r\n            -webkit-print-color-adjust: exact; \r\n            print-color-adjust: exact; \r\n        }\r\n        @media print { \r\n            body { margin: 0; padding: 0; background: white; } \r\n            .page { border: none; margin: 0; width: 210mm; height: 297mm; box-shadow: none; } \r\n            .print-hide { display: none !important; } \r\n        }\r\n    \n/* subm-modern-dark-print-lines */\n.page table, .page th, .page td { border-color:#111827 !important; }\n.page .border-gray-100, .page .border-gray-200, .page .border-gray-300, .page .border-slate-300, .page .border-slate-700 { border-color:#111827 !important; }\n.page .divide-gray-200 > :not([hidden]) ~ :not([hidden]) { border-color:#111827 !important; }\n@media print { .page table, .page th, .page td { border-color:#000 !important; } .page .divide-gray-200 > :not([hidden]) ~ :not([hidden]) { border-color:#000 !important; } }\n\n/* subm-modern-a4-border-layout */\n@page { size:A4; margin:12.7mm; }\n.page { width:190mm !important; min-height:277mm !important; border:3px solid #0f172a !important; box-sizing:border-box !important; }\n@media print { .page { margin:0 auto !important; width:184mm !important; min-height:271mm !important; height:auto !important; box-shadow:none !important; overflow:visible !important; border:3px solid #0f172a !important; } }\n\n/* subm-modern-history-grid-fix */\n.subm-history-table{border-collapse:collapse !important;border-spacing:0 !important;table-layout:fixed !important;width:100% !important;}\n.subm-history-table th,.subm-history-table td{border-color:#111827 !important;}\n.subm-history-table th,.subm-history-table td{vertical-align:middle;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}\n.subm-history-table thead th{padding-top:2px !important;padding-bottom:2px !important;}\n.subm-history-table tbody td{padding-top:3px !important;padding-bottom:3px !important;line-height:1.15 !important;}\n.subm-history-table th:nth-child(1),.subm-history-table td:nth-child(1){width:22% !important;}\n.subm-history-table th:nth-child(2),.subm-history-table td:nth-child(2){width:13% !important;}\n.subm-history-table th:nth-child(3),.subm-history-table td:nth-child(3){width:17% !important;}\n.subm-history-table th:nth-child(4),.subm-history-table td:nth-child(4){width:17% !important;}\n.subm-history-table th:nth-child(5),.subm-history-table td:nth-child(5){width:13% !important;}\n.subm-history-table th:nth-child(6),.subm-history-table td:nth-child(6){width:18% !important;}\n.subm-history-table tbody td{border-right:1px solid #111827 !important;border-bottom:1px solid #111827 !important;}\n.subm-history-table tbody td:last-child{border-right:0 !important;}\n@media print{.subm-history-table th,.subm-history-table td{border-color:#000 !important;}.subm-history-table tbody td{border-right:1px solid #000 !important;border-bottom:1px solid #000 !important;}}\n\n/* subm-template-print-consistency */\n@media print { body { -webkit-print-color-adjust: exact; print-color-adjust: exact; } }\n</style>\r\n</head>\r\n<body class=\"bg-gray-200 py-8 flex flex-col items-center\">\r\n\r\n    <!-- Print Bɔtin Pashɔn -->\r\n    <div class=\"print-hide w-[210mm] flex justify-between items-center mb-4 bg-white p-4 rounded-lg shadow-sm border border-gray-300\">\r\n        <p class=\"text-gray-600 font-medium text-sm\">Previewing A4 Format Bill</p>\r\n        <button onclick=\"window.print()\" class=\"bg-[#0e7490] hover:bg-[#085a73] text-white px-6 py-2 rounded shadow-md font-bold transition-colors flex items-center gap-2\">\r\n            <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\" xmlns=\"http://www.w3.org/2000/svg\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M17 17h2a2 2 0 002-2v-4a2 2 0 00-2-2H5a2 2 0 00-2 2v4a2 2 0 002 2h2m2 4h6a2 2 0 002-2v-4a2 2 0 00-2-2H9a2 2 0 00-2 2v4a2 2 0 002 2zm8-12V5a2 2 0 00-2-2H9a2 2 0 00-2 2v4h10z\"></path></svg>\r\n            Print Bill\r\n        </button>\r\n    </div>\r\n\r\n    <!-- Men A4 Pej Leawt -->\r\n    <div class=\"page w-[210mm] h-[297mm] bg-white border border-gray-400 p-0 flex flex-col relative shadow-2xl box-border text-slate-800 overflow-hidden\">\r\n        \r\n        <!-- ================= MEN BIL ================= -->\r\n        <div class=\"flex-grow flex flex-col\">\r\n            \r\n            <!-- 1. EDA (Teal Bakgrawn) -->\r\n            <div class=\"bg-[#0e7490] text-white p-4 flex justify-between items-start\">\r\n                <div class=\"flex items-center gap-4 w-full\">\r\n                    <div class=\"w-14 h-14 bg-white/10 rounded flex items-center justify-center overflow-hidden shrink-0\">\r\n                        <!-- Kɔmpin Logo -->\r\n                        <span class=\"text-xs text-white/50\">{{society_logo}}</span>\r\n                    </div>\r\n                    <div class=\"w-full\">\r\n                        <div class=\"flex justify-between items-center mb-0.5\">\r\n                            <h1 class=\"text-2xl font-black tracking-wide\">{{society_name}}</h1>\r\n                            <span class=\"bg-rose-400 text-white px-4 py-1 rounded-full text-[10px] font-bold uppercase tracking-wider shadow-sm\">{{payment_status}}</span>\r\n                        </div>\r\n                        <p class=\"text-[11px] font-medium opacity-90 border-t border-white/20 pt-1\">{{document_type}}</p>\r\n                        <div class=\"flex justify-between mt-1\">\r\n                            <p class=\"text-[9px] text-cyan-100\">{{society_address}} | Ph: {{society_mobile}}</p>\r\n                            <p class=\"text-[9px] text-cyan-100 italic\">Created: {{issue_date}}</p>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n            <!-- 2. SƆMARI LAYN -->\r\n            <div class=\"grid grid-cols-5 bg-gray-50 border-y border-gray-300 text-xs text-center\">\r\n                <div class=\"p-2 border-r border-gray-300 flex flex-col justify-center\">\r\n                    <p class=\"font-bold text-gray-500 uppercase text-[9px] tracking-wide\">Bill No</p>\r\n                    <p class=\"font-black text-slate-800 text-xs mt-0.5\">{{bill_no}}</p>\r\n                </div>\r\n                <div class=\"p-2 border-r border-gray-300 flex flex-col justify-center\">\r\n                    <p class=\"font-bold text-gray-500 uppercase text-[9px] tracking-wide\">Consumer ID</p>\r\n                    <p class=\"font-black text-slate-800 text-xs mt-0.5\">{{consumer_id}}</p>\r\n                </div>\r\n                <div class=\"p-2 border-r border-gray-300 flex flex-col justify-center\">\r\n                    <p class=\"font-bold text-gray-500 uppercase text-[9px] tracking-wide\">Property</p>\r\n                    <p class=\"font-black text-slate-800 text-xs mt-0.5\">{{property_id}}</p>\r\n                </div>\r\n                <div class=\"p-2 border-r border-gray-300 flex flex-col justify-center\">\r\n                    <p class=\"font-bold text-gray-500 uppercase text-[9px] tracking-wide\">Month</p>\r\n                    <p class=\"font-black text-slate-800 text-xs mt-0.5\">{{billing_month}}</p>\r\n                </div>\r\n                <div class=\"p-2 flex flex-col justify-center bg-[#e0f2fe]\">\r\n                    <p class=\"font-bold text-[#0369a1] uppercase text-[9px] tracking-wide\">Due Date</p>\r\n                    <p class=\"font-black text-red-600 text-xs mt-0.5\">{{due_date}}</p>\r\n                </div>\r\n            </div>\r\n\r\n            <!-- 3. INFƆ & MITA PASHƆN -->\r\n            <div class=\"px-5 py-4 grid grid-cols-2 gap-6\">\r\n                <!-- Lɛft: Rɛzidɛnt Infɔ -->\r\n                <div class=\"bg-gray-50 border border-gray-200 rounded-md p-3 relative overflow-hidden h-full flex flex-col justify-center shadow-sm\">\r\n                    <div class=\"absolute top-0 left-0 w-1.5 h-full bg-[#0e7490]\"></div>\r\n                    <h3 class=\"text-gray-500 font-bold text-[9px] mb-1 pl-1.5 uppercase tracking-wider\">Resident Information</h3>\r\n                    <div class=\"mb-2 pl-1.5\">\r\n                        <span class=\"font-black text-slate-900 text-xl tracking-tight leading-none block uppercase\">{{client_name}}</span>\r\n                    </div>\r\n                    <div class=\"text-[10px] space-y-1 bg-white p-2 border border-gray-100 rounded-sm\">\r\n                        <div class=\"grid grid-cols-[60px_1fr]\">\r\n                            <span class=\"text-gray-500 font-medium\">Address:</span>\r\n                            <span class=\"font-bold text-slate-900 leading-tight\">{{client_address}}</span>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n\r\n                <!-- Rayt: Mita Ditels -->\r\n                <div class=\"flex gap-4 items-stretch border border-gray-200 rounded-md p-2 bg-gray-50 h-full shadow-sm\">\r\n                    <div class=\"w-[45%] flex flex-col justify-center gap-2 pr-2\">\r\n                        <div class=\"text-center\">\r\n                            <p class=\"text-[8px] font-bold text-gray-500 uppercase tracking-wide\">Present</p>\r\n                            <p class=\"text-sm font-black text-slate-800 leading-none\">{{curr_reading}}</p>\r\n                        </div>\r\n                        <div class=\"text-center\">\r\n                            <p class=\"text-[8px] font-bold text-gray-500 uppercase tracking-wide\">Previous</p>\r\n                            <p class=\"text-sm font-black text-slate-800 leading-none\">{{prev_reading}}</p>\r\n                        </div>\r\n                        <div class=\"text-center bg-[#e0f2fe] p-1 rounded-sm border border-[#bae6fd]\">\r\n                            <p class=\"text-[8px] font-bold text-[#0369a1] uppercase tracking-wide\">Unit</p>\r\n                            <p class=\"text-base font-black text-[#0369a1] leading-none\">{{units_consumed}}</p>\r\n                        </div>\r\n                    </div>\r\n                    \r\n                    <div class=\"w-[55%] border-l border-gray-300 pl-2\">\r\n                        <!-- Mɔdɛn mita piktchɔ bɔks -->\r\n                        <div class=\"bg-white border border-gray-200 h-full min-h-[70px] rounded flex flex-col items-center justify-center text-gray-400 overflow-hidden relative shadow-inner\">\r\n                            <div class=\"absolute inset-0 flex items-center justify-center p-1\">\r\n                                {{meter_image}}\r\n                            </div>\r\n                            <span class=\"text-[8px] font-bold uppercase opacity-30 z-0 pointer-events-none\">Meter Image</span>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n            <!-- 4. CHAJIS BRƐKDAWN -->\r\n            <div class=\"px-5 grid grid-cols-2 gap-6\">\r\n                <!-- Lɛft Kɔlɔm: Lɛktrik & Totol -->\r\n                <div class=\"flex flex-col\">\r\n                    <h3 class=\"text-slate-800 font-bold text-xs mb-2\">Electricity Charges</h3>\r\n                    \r\n                    <table class=\"w-full text-[10px] mb-4 border-collapse border border-gray-300\">\r\n                        <tbody class=\"divide-y divide-gray-300\">\r\n                            <tr>\r\n                                <td class=\"border-r border-gray-300 p-1.5 font-bold text-gray-600 uppercase\">Unit Consumed</td>\r\n                                <td class=\"p-1.5 text-right font-black text-slate-900\">{{units_consumed}}</td>\r\n                            </tr>\r\n                            <tr>\r\n                                <td class=\"border-r border-gray-300 p-1.5 font-bold text-gray-600 uppercase\">Rate Per Unit</td>\r\n                                <td class=\"p-1.5 text-right font-black text-slate-900\">{{unit_price}}</td>\r\n                            </tr>\r\n                            <tr class=\"bg-gray-50\">\r\n                                <td class=\"border-r border-gray-300 p-1.5 font-black text-slate-800 uppercase\">Electricity Total</td>\r\n                                <td class=\"p-1.5 text-right font-black text-slate-900\">RS. {{energy_calculation}}</td>\r\n                            </tr>\r\n                        </tbody>\r\n                    </table>\r\n\r\n                    <!-- Adj/Dɛbit & Totol Bɔks -->\r\n                    <table class=\"w-full text-[10px] border-collapse border border-gray-300 shadow-sm mt-auto\">\r\n                        <tbody class=\"divide-y divide-gray-300\">\r\n                            <tr class=\"text-[9px]\">\r\n                                <td class=\"border-r border-gray-300 p-1 font-medium text-gray-500 uppercase\">Adj/Debit: <span class=\"text-slate-700\">{{adjustment_debit}}</span></td>\r\n                                <td class=\"p-1 text-right font-medium text-gray-500 uppercase\">Credit: <span class=\"text-slate-700\">{{adjustment_credit}}</span></td>\r\n                            </tr>\r\n                            <tr class=\"text-[8px] bg-gray-50\">\r\n                                <td colspan=\"2\" class=\"p-1 text-center text-gray-400 italic\">{{adjustment_note}}</td>\r\n                            </tr>\r\n                            <tr>\r\n                                <td class=\"border-r border-gray-300 p-2 font-bold text-gray-600 uppercase\">Previous Arrears</td>\r\n                                <td class=\"p-2 text-right font-black text-red-600\">RS. {{arrears}}</td>\r\n                            </tr>\r\n                            <tr class=\"bg-[#0e7490] text-white\">\r\n                                <td class=\"border-r border-[#085a73] p-2.5 font-black text-sm uppercase tracking-wide\">Total Bill</td>\r\n                                <td class=\"p-2.5 text-right font-black text-lg\">RS. {{total_amount}}</td>\r\n                            </tr>\r\n                            <tr class=\"bg-gray-50\">\r\n                                <td class=\"border-r border-gray-300 p-2 font-bold text-gray-600 uppercase\">Amount Paid</td>\r\n                                <td class=\"p-2 text-right font-bold text-green-600\">RS. {{paid_amount}}</td>\r\n                            </tr>\r\n                        </tbody>\r\n                    </table>\r\n                </div>\r\n\r\n                <!-- Rayt Kɔlɔm: Ɔda Chajis & Big Totol -->\r\n                <div class=\"flex flex-col\">\r\n                    <h3 class=\"text-slate-800 font-bold text-xs mb-2\">Other Charges</h3>\r\n                    \r\n                    <!-- Mɔdɛn Ɔda Chajis Tebu -->\r\n                    <table class=\"w-full text-[10px] mb-3 border-collapse border border-gray-300 bg-white [&_td]:p-1.5 [&_td:first-child]:border-r [&_td:first-child]:border-gray-300 [&_td:last-child]:text-right [&_td:last-child]:font-bold [&_td:last-child]:text-slate-900 shadow-sm\">\r\n                        <thead class=\"bg-gray-100 border-b border-gray-300\">\r\n                            <tr>\r\n                                <th class=\"border-r border-gray-300 p-1.5 text-left text-gray-600 font-bold uppercase tracking-wider\">Description</th>\r\n                                <th class=\"p-1.5 text-right text-gray-600 font-bold uppercase tracking-wider\">Amount</th>\r\n                            </tr>\r\n                        </thead>\r\n                        <tbody class=\"divide-y divide-gray-300 text-slate-700\">\r\n                            {{utility_rows}}\r\n                            {{maintenance_rows}}\r\n                            {{other_rows}}\r\n                            {{table_rows}}\r\n                        </tbody>\r\n                    </table>\r\n\r\n                    <div class=\"mt-auto space-y-2\">\r\n                        <!-- Let Fi -->\r\n                        <div class=\"flex justify-between items-center text-[10px] p-2 border border-red-200 rounded bg-red-50\">\r\n                            <span class=\"font-bold text-gray-700 uppercase\">Late Fee (Surcharge) {{late_fee_percent}}:</span>\r\n                            <span class=\"font-black text-red-600\">RS. {{late_fee}}</span>\r\n                        </div>\r\n                        \r\n                        <!-- Big Totol Afta Dyu -->\r\n                        <div class=\"bg-[#0e7490] text-white p-2.5 shadow-md flex justify-between items-center rounded border border-[#085a73]\">\r\n                            <div class=\"flex flex-col\">\r\n                                <span class=\"text-[9px] font-bold uppercase tracking-widest opacity-90\">Total After Due</span>\r\n                                <span class=\"text-[9px] font-bold uppercase tracking-widest opacity-90\">Date:</span>\r\n                            </div>\r\n                            <span class=\"text-xl font-black tracking-wide\">RS. {{payable_after_due}}</span>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n            <!-- 5. BƆTƆM SPLIT: Istri (Lɛft) & Bank/QR (Rayt) -->\r\n            <div class=\"px-5 mt-4 mb-2 grid grid-cols-[55%_45%] gap-5 flex-grow\">\r\n                \r\n                <!-- Lɛft: 6 Mɔnt Istri -->\r\n                <div class=\"flex flex-col\">\r\n                    <h3 class=\"font-bold text-slate-800 text-[11px] mb-2 border-b border-gray-300 pb-1\">Payment History (Last 6 Months)</h3>\r\n                    \r\n                    <!-- Mɔdɛn Istri Tebu -->\r\n                    <div class=\"rounded-md border border-gray-200 overflow-hidden shadow-sm\">\r\n                        <table  class=\"w-full text-[9px] text-center bg-white subm-history-table\">\r\n                            <thead class=\"bg-[#0e7490] text-white\">\r\n                                <tr class=\"uppercase tracking-wider\">\r\n                                    <th class=\"font-bold py-1.5 px-1\">Month</th>\r\n                                    <th class=\"font-bold py-1.5 px-1\">Units</th>\r\n                                    <th class=\"font-bold py-1.5 px-1\">Bill (RS)</th>\r\n                                    <th class=\"font-bold py-1.5 px-1\">Status</th>\r\n                                </tr>\r\n                            </thead>\r\n                            <tbody class=\"font-medium text-slate-700 divide-y divide-gray-100\">\r\n                                {{history_rows}}\r\n                            </tbody>\r\n                        </table>\r\n                    </div>\r\n                </div>\r\n\r\n                <!-- Rayt: Bank Ditels & Skan (Mɔdɛn ɛn shɔt ayt) -->\r\n                <!-- self-start lagaya hai taake height history table ke sath stretch na ho -->\r\n                <div class=\"flex flex-col self-start w-full\">\r\n                    <h3 class=\"font-bold text-slate-800 text-[11px] mb-1.5 border-b border-gray-300 pb-1\">Payment Methods & Banking</h3>\r\n                    \r\n                    <div class=\"bg-gradient-to-br from-white to-gray-50 border border-gray-200 rounded-md p-1.5 flex items-start justify-between gap-2 shadow-sm\">\r\n                        <div class=\"text-[8.5px] leading-snug text-slate-700 font-mono whitespace-pre-wrap flex-grow mt-0.5\">\r\n{{bank_accounts}}\r\n{{bank_details}}\r\n                        </div>\r\n                        \r\n                        <!-- Klin QR Bɔks -->\r\n                        \r\n                    </div>\r\n                </div>\r\n\r\n            </div>\r\n        </div>\r\n\r\n        <!-- ================= KUT LƐN ================= -->\r\n        <div class=\"w-full py-1.5 relative bg-white print-hide mt-auto\">\r\n            <div class=\"absolute top-1/2 left-0 w-full border-t border-dashed border-gray-400\"></div>\r\n            <div class=\"absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 bg-white px-2 text-gray-500 text-[9px] font-bold flex items-center gap-1 z-10\">\r\n                <span>✂</span> DETACH ALONG THIS LINE\r\n            </div>\r\n        </div>\r\n\r\n        <!-- ================= MƆDƐN PEIMENT SLIP ================= -->\r\n        <div class=\"bg-white border-t-2 border-dashed border-gray-400 p-4 shrink-0 flex flex-col relative w-full h-auto min-h-[160px]\">\r\n            \r\n            <!-- Slip Eda -->\r\n            <div class=\"flex justify-between items-start border-b border-gray-200 pb-2 mb-3\">\r\n                <div class=\"flex items-center gap-2\">\r\n                    <div class=\"h-6 w-1 bg-[#0e7490]\"></div>\r\n                    <div>\r\n                        <h2 class=\"text-xs font-black text-slate-800 uppercase leading-none\">Payment Slip</h2>\r\n                        <p class=\"text-[9px] text-gray-500 font-bold uppercase tracking-wider mt-0.5\">Society / Bank Copy</p>\r\n                    </div>\r\n                </div>\r\n                <div class=\"text-center absolute left-1/2 -translate-x-1/2 top-4\">\r\n                     <p class=\"text-[12px] font-black text-[#0e7490] uppercase leading-none\">{{society_name}}</p>\r\n                     <p class=\"text-[8px] font-bold text-slate-500 mt-0.5\">{{document_type}}</p>\r\n                </div>\r\n                <div class=\"text-right\">\r\n                    <p class=\"text-[10px] font-bold text-slate-800 uppercase bg-gray-100 px-2 py-0.5 border border-gray-200 rounded-sm\">{{billing_month}}</p>\r\n                </div>\r\n            </div>\r\n            \r\n            <!-- Slip Bɔdi -->\r\n            <div class=\"flex gap-4 items-stretch flex-grow\">\r\n                <!-- Infɔ Kɔlɔm -->\r\n                <div class=\"flex-grow flex flex-col justify-between\">\r\n                    <div class=\"grid grid-cols-3 gap-y-3 gap-x-3 text-[10px]\">\r\n                        <div>\r\n                            <p class=\"text-gray-400 uppercase font-bold text-[8px]\">Consumer ID</p>\r\n                            <p class=\"font-black text-slate-800 text-[11px] border-b border-gray-200 pb-0.5\">{{consumer_id}}</p>\r\n                        </div>\r\n                        <div class=\"col-span-2\">\r\n                            <p class=\"text-gray-400 uppercase font-bold text-[8px]\">Name & Property</p>\r\n                            <p class=\"font-black text-slate-800 text-[11px] border-b border-gray-200 pb-0.5 leading-tight\">{{client_name}} ({{property_id}})</p>\r\n                        </div>\r\n                        <div>\r\n                            <p class=\"text-gray-400 uppercase font-bold text-[8px]\">Bill No</p>\r\n                            <p class=\"font-black text-slate-800 text-[11px] border-b border-gray-200 pb-0.5\">{{bill_no}}</p>\r\n                        </div>\r\n                        <div>\r\n                            <p class=\"text-gray-400 uppercase font-bold text-[8px]\">Due Date</p>\r\n                            <p class=\"font-black text-red-600 text-[11px] border-b border-gray-200 pb-0.5\">{{due_date}}</p>\r\n                        </div>\r\n                        <div>\r\n                            <p class=\"text-gray-400 uppercase font-bold text-[8px]\">Total Pending</p>\r\n                            <p class=\"font-black text-slate-800 text-[11px] border-b border-gray-200 pb-0.5\">RS. {{pending_amount}}</p>\r\n                        </div>\r\n                    </div>\r\n                    \r\n                    <!-- Bank Yuz Bɔks -->\r\n                    <div class=\"w-full mt-3 bg-gray-50 border border-gray-200 p-2 flex gap-4 text-[9px] rounded-sm\">\r\n                        <div class=\"flex-1 flex flex-col justify-end\"><span class=\"text-gray-500 mb-0.5\">Paid Amt:</span> <span class=\"font-bold border-b border-black w-full inline-block min-h-[14px]\">{{paid_amount}}</span></div>\r\n                        <div class=\"flex-1 flex flex-col justify-end\"><span class=\"text-gray-500 mb-0.5\">Date:</span> <span class=\"font-bold border-b border-black w-full inline-block min-h-[14px]\">{{payment_date}}</span></div>\r\n                        <div class=\"flex-1 flex flex-col justify-end\"><span class=\"text-gray-500 mb-0.5\">Ref/Txn:</span> <span class=\"font-bold border-b border-black w-full inline-block min-h-[14px]\">{{payment_ref}}</span></div>\r\n                    </div>\r\n                </div>\r\n\r\n                <!-- Totol Kɔlɔm -->\r\n                <div class=\"flex flex-col justify-between w-[110px] shrink-0\">\r\n                    <div class=\"bg-[#0e7490] text-white p-2 text-center border border-[#085a73] rounded-sm shadow-sm\">\r\n                        <p class=\"text-[7px] font-bold uppercase opacity-90 mb-1\">Total Payable</p>\r\n                        <p class=\"text-[13px] font-black leading-none\">{{total_amount}}</p>\r\n                    </div>\r\n                    <div class=\"bg-gray-100 border border-gray-300 p-1.5 text-center rounded-sm\">\r\n                        <p class=\"text-[7px] font-bold text-gray-600 uppercase mb-0.5\">After Due Date</p>\r\n                        <p class=\"text-[11px] font-black text-slate-800 leading-none\">{{payable_after_due}}</p>\r\n                    </div>\r\n                </div>\r\n\r\n                <!-- Stamp Kɔlɔm -->\r\n                <div class=\"w-[120px] shrink-0 flex flex-col items-center justify-end pb-1 border border-dashed border-gray-300 bg-gray-50 rounded-sm relative overflow-hidden\">\r\n                    <div class=\"absolute inset-0 flex items-center justify-center opacity-30 text-xs font-bold rotate-[-15deg] text-green-700 pointer-events-none\">{{paid_slip_block}}</div>\r\n                    <div class=\"absolute inset-0 flex items-center justify-center pointer-events-none\">{{paid_stamp}}</div>\r\n                    \r\n                    <p class=\"text-[7px] text-gray-500 font-bold uppercase mt-auto bg-white/80 px-2 border-t border-gray-200 w-full text-center py-0.5\">Bank Stamp & Sign</p>\r\n                </div>\r\n            </div>\r\n        </div>\r\n        \r\n    </div>\r\n</body>\r\n</html>', '', 0, '2026-08-30 21:27:47');
INSERT INTO `billing_templates` (`id`, `society_id`, `name`, `slug`, `template_type`, `html_content`, `css_content`, `is_default`, `created_at`) VALUES
(7, 1, 'FINAL', 'final', 'print_bill', '﻿<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>Utility Bill Template</title>\n    <!-- Tailwind CSS for the classes used in the template -->\n    <script src=\"https://cdn.tailwindcss.com\"></script>\n    <style>\n        @import url(\'https://fonts.googleapis.com/css2?family=Inter:wght@300;400;600;800;900&display=swap\');\n        \n        body {\n            font-family: \'Inter\', sans-serif;\n            background-color: #f3f4f6;\n            display: flex;\n            justify-content: center;\n            padding: 20px;\n        }\n\n        @page {\n            size: A4;\n            margin: 12.7mm; /* default-like printer margin (~0.5in) */\n        }\n\n        @media print {\n            body {\n                margin: 0;\n                padding: 0;\n                background-color: white;\n                -webkit-print-color-adjust: exact;\n                print-color-adjust: exact;\n            }\n            .page {\n                margin: 0 auto;\n                width: 184mm; /* fit within A4 printable area with default margins */\n                min-height: 271mm;\n                height: auto !important;\n                box-shadow: none;\n                overflow: visible !important;\n                border: 3px solid #0f172a !important;\n            }\n            .no-print {\n                display: none;\n            }\n        }\n\n        /* subm-modern-dark-print-lines */\n        .page table, .page th, .page td { border-color:#111827 !important; }\n        .page .border-gray-100, .page .border-gray-200, .page .border-gray-300, .page .border-slate-300, .page .border-slate-700 { border-color:#111827 !important; }\n        .page .divide-gray-200 > :not([hidden]) ~ :not([hidden]) { border-color:#111827 !important; }\n    \n/* subm-modern-a4-border-layout */\n@page { size:A4; margin:12.7mm; }\n.page { width:190mm !important; min-height:277mm !important; border:3px solid #0f172a !important; box-sizing:border-box !important; }\n@media print { .page { margin:0 auto !important; width:184mm !important; min-height:271mm !important; height:auto !important; box-shadow:none !important; overflow:visible !important; border:3px solid #0f172a !important; } }\n\n/* subm-modern-history-grid-fix */\n.subm-history-table{border-collapse:collapse !important;border-spacing:0 !important;table-layout:fixed !important;width:100% !important;}\n.subm-history-table th,.subm-history-table td{border-color:#111827 !important;}\n.subm-history-table th,.subm-history-table td{vertical-align:middle;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}\n.subm-history-table thead th{padding-top:2px !important;padding-bottom:2px !important;}\n.subm-history-table tbody td{padding-top:3px !important;padding-bottom:3px !important;line-height:1.15 !important;}\n.subm-history-table th:nth-child(1),.subm-history-table td:nth-child(1){width:22% !important;}\n.subm-history-table th:nth-child(2),.subm-history-table td:nth-child(2){width:13% !important;}\n.subm-history-table th:nth-child(3),.subm-history-table td:nth-child(3){width:17% !important;}\n.subm-history-table th:nth-child(4),.subm-history-table td:nth-child(4){width:17% !important;}\n.subm-history-table th:nth-child(5),.subm-history-table td:nth-child(5){width:13% !important;}\n.subm-history-table th:nth-child(6),.subm-history-table td:nth-child(6){width:18% !important;}\n.subm-history-table tbody td{border-right:1px solid #111827 !important;border-bottom:1px solid #111827 !important;}\n.subm-history-table tbody td:last-child{border-right:0 !important;}\n@media print{.subm-history-table th,.subm-history-table td{border-color:#000 !important;}.subm-history-table tbody td{border-right:1px solid #000 !important;border-bottom:1px solid #000 !important;}}\n\n/* subm-template-print-consistency */\n@media print { body { -webkit-print-color-adjust: exact; print-color-adjust: exact; } }\n</style>\n</head>\n<body>\n    {{paid_stamp}}\n\n    <!-- Print Button (Hidden in Print) -->\n    <button onclick=\"window.print()\" class=\"fixed top-6 right-6 bg-slate-900 text-white px-5 py-2.5 rounded-lg shadow-xl no-print z-50 hover:bg-slate-800 font-bold flex items-center gap-2 border-2 border-yellow-500 transition-all\">\n        <svg xmlns=\"http://www.w3.org/2003/svg\" width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"6 9 6 2 18 2 18 9\"></polyline><path d=\"M6 18H4a2 2 0 0 1-2-2v-5a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2v5a2 2 0 0 1-2 2h-2\"></path><rect x=\"6\" y=\"14\" width=\"12\" height=\"8\"></rect></svg>\n        Print Bill\n    </button>\n\n    <!-- A4 Page Container -->\n    <div class=\"page w-[190mm] min-h-[277mm] bg-white border-[3px] border-slate-900 flex flex-col font-sans relative shadow-2xl box-border text-slate-900 mx-auto\">\n        \n        <!-- Header -->\n        <div class=\"bg-slate-900 text-white p-5 flex items-center justify-between border-b-4 border-yellow-600\">\n            <div class=\"flex items-center gap-4\">\n                <!-- Logo Placeholder -->\n                <div class=\"h-14 w-14 bg-white rounded-full flex items-center justify-center text-slate-900 font-bold border-2 border-yellow-600 overflow-hidden\">\n                    <img src=\"{{society_logo}}\" alt=\"Logo\" class=\"object-cover h-full w-full\">\n                </div>\n                <div>\n                    <h1 class=\"text-2xl font-black uppercase tracking-widest text-white\">{{society_name}}</h1>\n                    <p class=\"text-[9px] font-medium mt-0.5 text-gray-300\">{{society_address}}</p>\n                    <p class=\"text-[9px] font-bold mt-0.5 text-yellow-500\">Mobile: {{society_mobile}}</p>\n                </div>\n            </div>\n            <div class=\"text-right\">\n                <span class=\"bg-yellow-600 text-black px-3 py-1 rounded-sm text-[10px] uppercase tracking-widest font-black shadow-lg\">Utility Invoice</span>\n                <p class=\"text-[9px] mt-1 text-gray-400\">NTN: 1234567-8</p>\n            </div>\n        </div>\n\n        <!-- Summary Grid -->\n        <div class=\"grid grid-cols-6 border-b border-gray-300 text-center text-[10px] divide-x divide-gray-300 mb-3 bg-white\">\n            <div class=\"flex flex-col\">\n                <div class=\"py-1.5 bg-slate-50 font-bold text-slate-500 uppercase border-b border-gray-200\">Bill No</div>\n                <div class=\"py-2 font-mono font-black text-slate-900\">{{bill_no}}</div>\n            </div>\n            <div class=\"flex flex-col\">\n                <div class=\"py-1.5 bg-slate-50 font-bold text-slate-500 uppercase border-b border-gray-200\">Consumer ID</div>\n                <div class=\"py-2 font-mono font-black text-slate-900\">{{consumer_id}}</div>\n            </div>\n            <div class=\"flex flex-col\">\n                <div class=\"py-1.5 bg-slate-50 font-bold text-slate-500 uppercase border-b border-gray-200\">Property</div>\n                <div class=\"py-2 font-mono font-black text-slate-900\">{{property_id}}</div>\n            </div>\n            <div class=\"flex flex-col\">\n                <div class=\"py-1.5 bg-slate-50 font-bold text-slate-500 uppercase border-b border-gray-200\">Billing Month</div>\n                <div class=\"py-2 font-mono font-black text-slate-900\">{{billing_month}}</div>\n            </div>\n            <div class=\"flex flex-col\">\n                <div class=\"py-1.5 bg-slate-50 font-bold text-slate-500 uppercase border-b border-gray-200\">Issue Date</div>\n                <div class=\"py-2 font-mono font-black text-slate-900\">{{issue_date}}</div>\n            </div>\n            <div class=\"flex flex-col bg-yellow-50\">\n                <div class=\"py-1.5 bg-yellow-100 font-bold text-yellow-900 uppercase border-b border-yellow-200\">Due Date</div>\n                <div class=\"py-2 text-red-600 font-black font-mono\">{{due_date}}</div>\n            </div>\n        </div>\n\n        <!-- Main Content Area -->\n        <div class=\"flex gap-4 px-6\">\n            \n            <!-- Left Column: Details -->\n            <div class=\"flex-[7] flex flex-col gap-2\">\n                \n                <!-- Consumer Info -->\n                <section>\n                    <h3 class=\"bg-slate-900 px-2 py-1 text-[10px] font-bold text-white uppercase tracking-wide flex justify-between items-center\">\n                        Consumer Information\n                        <span class=\"text-yellow-500\">RESIDENTIAL</span>\n                    </h3>\n                    <div class=\"p-2 border border-t-0 border-gray-300 bg-slate-50/50\">\n                        <p class=\"text-[10px] font-black text-slate-700 uppercase tracking-wide subm-modern-consumer-before-client\">Consumer ID: {{consumer_id}}</p>\n                        <p class=\"text-base font-black text-slate-900 uppercase\">{{client_name}}</p>\n                        <p class=\"text-[10px] font-semibold text-slate-500 mt-0.5 uppercase\">Resident / Owner</p>\n                        <p class=\"text-xs text-slate-700 mt-1 leading-relaxed\">{{client_address}}</p>\n                    </div>\n                </section>\n\n                <!-- Reading Details -->\n                <section>\n                    <h3 class=\"bg-gray-200 px-2 py-1 text-[10px] font-black text-slate-700 border-l-4 border-slate-900 uppercase tracking-wide\">Meter Reading Details</h3>\n                    <div class=\"border border-t-0 border-gray-300 overflow-hidden\">\n                        <table class=\"w-full text-[10px]\">\n                            <thead class=\"bg-gray-100 text-slate-600 border-b border-gray-300 uppercase font-bold\">\n                                <tr>\n                                    <th class=\"py-1.5 px-2 text-center border-r border-gray-300\">Previous</th>\n                                    <th class=\"py-1.5 px-2 text-center border-r border-gray-300\">Current</th>\n                                    <th class=\"py-1.5 px-2 text-center border-r border-gray-300\">Units</th>\n                                    <th class=\"py-1.5 px-2 text-center\">Rate</th>\n                                </tr>\n                            </thead>\n                            <tbody class=\"text-slate-900 font-medium text-center\">\n                                <tr>\n                                    <td class=\"py-2 border-r border-gray-300 text-gray-500\">{{prev_reading}}</td>\n                                    <td class=\"py-2 border-r border-gray-300 font-bold\">{{curr_reading}}</td>\n                                    <td class=\"py-2 border-r border-gray-300 font-black bg-yellow-50\">{{units_consumed}}</td>\n                                    <td class=\"py-2\">{{unit_price}}</td>\n                                </tr>\n                                <tr class=\"bg-slate-50 border-t border-gray-200\">\n                                    <td colspan=\"4\" class=\"py-1.5 text-[10px] font-bold text-slate-700\">\n                                        <span class=\"uppercase text-[9px] tracking-wide text-slate-500 mr-2\">Calculation:</span>\n                                        {{energy_calculation}}\n                                    </td>\n                                </tr>\n                            </tbody>\n                        </table>\n                    </div>\n                </section>\n\n                <!-- Meter Image & Small Advertisement -->\n                <div class=\"flex gap-2\">\n                    <!-- Meter Image -->\n                    <div class=\"flex-1\">\n                        <h3 class=\"bg-gray-200 px-2 py-1 text-[10px] font-black text-slate-700 border-l-4 border-slate-900 uppercase tracking-wide\">Ref. Meter Image</h3>\n                        <div class=\"border border-t-0 border-gray-300 bg-white h-24 overflow-hidden\">\n                            <div class=\"w-full h-full flex items-center justify-center overflow-hidden\">\n                                {{meter_image}}\n                            </div>\n                        </div>\n                    </div>\n                    \n                    <!-- Small Ad Area -->\n                    <div class=\"flex-1\">\n                        <h3 class=\"bg-gray-200 px-2 py-1 text-[10px] font-black text-slate-700 border-l-4 border-slate-900 uppercase tracking-wide\">Preview Caution</h3>\n                        <div class=\"mt-0.5 bg-slate-50 p-2 text-left h-24 overflow-auto\">\n                             {{bill_notice}}\n                        </div>\n                    </div>\n                </div>\n\n                <!-- History Table -->\n                <section>\n                    <h3 class=\"bg-gray-200 px-2 py-1 text-[10px] font-black text-slate-700 border-l-4 border-slate-900 uppercase tracking-wide\">Payment History (Last 12 Months)</h3>\n                    <div class=\"border border-t-0 border-gray-300 overflow-hidden\">\n                        <table class=\"w-full text-[8px] table-fixed subm-history-table\">\n                            <thead class=\"bg-gray-100 text-slate-600 border-b border-gray-300 uppercase font-bold\">\n                                <tr>\n                                    <th class=\"w-[22%] py-0.5 px-1.5 text-left border-r border-gray-300\">Month</th>\n                                    <th class=\"w-[13%] py-0.5 px-1 text-center border-r border-gray-300\">Units</th>\n                                    <th class=\"w-[17%] py-0.5 px-1 text-center border-r border-gray-300\">Bill AMT</th>\n                                    <th class=\"w-[17%] py-0.5 px-1 text-center border-r border-gray-300\">Paid AMT</th>\n                                    <th class=\"w-[13%] py-0.5 px-1 text-center border-r border-gray-300\">Adj.</th>\n                                    <th class=\"w-[18%] py-0.5 px-1 text-center\">Status</th>\n                                </tr>\n                            </thead>\n                            <tbody class=\"divide-y divide-gray-200 text-slate-800 font-medium leading-none\">\n                                {{history_rows}}\n                            </tbody>\n                        </table>\n                    </div>\n                </section>\n                \n            </div>\n\n            <!-- Right Column: Financials -->\n            <div class=\"flex-[5] flex flex-col\">\n                <h3 class=\"bg-slate-900 px-2 py-1 text-[10px] font-bold text-white uppercase tracking-wide text-center\">Current Charges</h3>\n                \n                <!-- Charges Table -->\n                <div class=\"border border-t-0 border-gray-300 mt-0 overflow-hidden shadow-sm\" data-total=\"{{total_amount}}\" data-late-percent=\"{{late_fee_percent}}\" data-due-date-iso=\"{{due_date_iso}}\" data-adjust-debit=\"{{adjustment_debit}}\" data-adjust-credit=\"{{adjustment_credit}}\">\n                    <table class=\"w-full text-[10px]\">\n                        <thead class=\"bg-gray-100 border-b border-gray-300\">\n                            <tr>\n                                <th class=\"p-1.5 text-left text-slate-600 font-bold uppercase border-r border-gray-300\">Description</th>\n                                <th class=\"p-1.5 text-right text-slate-600 font-bold uppercase\">Amount</th>\n                            </tr>\n                        </thead>\n                        <tbody class=\"divide-y divide-gray-200\">\n                            {{utility_rows}}\n                            {{maintenance_rows}}\n                            {{other_rows}}\n                            \n                            <!-- Static Footer Rows -->\n                            <tr class=\"bg-slate-50 text-slate-900 font-bold\">\n                                <td class=\"p-1.5 border-r border-gray-300\">Arrears / Previous</td>\n                                <td class=\"p-1.5 text-right\">{{arrears}}</td>\n                            </tr>\n                            \n                            <!-- Total Block -->\n                            <tr class=\"bg-slate-900 text-white font-black border-t-2 border-yellow-600\">\n                                <td class=\"p-2 text-xs border-r border-slate-700 uppercase tracking-wide\">Payable Within Due</td>\n                                <td class=\"p-2 text-right text-lg\">{{total_amount}}</td>\n                            </tr>\n                            \n                            <tr class=\"bg-white text-red-600 font-bold border-t border-gray-300\">\n                                <td class=\"p-1.5 text-[9px] border-r border-gray-300 text-right uppercase pt-2\">Late Fee ({{late_fee_percent}}%)</td>\n                                <td class=\"p-1.5 text-right text-xs pt-2\"><span id=\"late_fee_val\">{{late_fee}}</span></td>\n                            </tr>\n                            <tr class=\"bg-slate-50 text-slate-900 font-medium\">\n                                <td class=\"p-1.5 border-r border-gray-300\">Adjustment - Debit (Increase)</td>\n                                <td class=\"p-1.5 text-right\">{{adjustment_debit}}</td>\n                            </tr>\n                            <tr class=\"bg-slate-50 text-slate-900 font-medium\">\n                                <td class=\"p-1.5 border-r border-gray-300\">Adjustment - Credit (Decrease)</td>\n                                <td class=\"p-1.5 text-right\">{{adjustment_credit}}</td>\n                            </tr>\n                            <tr class=\"bg-slate-50 text-slate-700 text-[10px]\">\n                                <td class=\"p-1.5 border-r border-gray-300\" colspan=\"2\">Note: {{adjustment_note}}</td>\n                            </tr>\n                            <tr class=\"bg-red-50 text-slate-900 font-bold border-t border-gray-200\">\n                                <td class=\"p-1.5 text-[9px] border-r border-gray-300 text-right uppercase\">Payable After Due</td>\n                                <td class=\"p-1.5 text-right text-base font-black\"><span id=\"payable_after_val\">{{payable_after_due}}</span></td>\n                            </tr>\n                        </tbody>\n                    </table>\n                </div>\n\n                <!-- Combined Bank & Scan Section -->\n                <div class=\"mt-2 border border-gray-300 bg-white p-2 shadow-sm text-[9px] font-medium leading-tight text-slate-600\">\n                    {{bank_details}}\n                </div>\n\n                <!-- Vertical Fill Ad Space -->\n                <div class=\"mt-2\">\n                    <div class=\"h-40 border border-gray-300 bg-slate-50 flex flex-col items-center justify-center text-center overflow-hidden rounded-lg\">\n                        {{advertisement}}\n                    </div>\n                </div>\n\n            </div>\n        </div>\n\n        <!-- Separator -->\n        <div class=\"w-full py-4 relative px-6 mt-2\">\n            <div class=\"absolute top-1/2 left-0 w-full border-t-[2px] border-dashed border-slate-400\"></div>\n            <div class=\"absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 bg-white px-3 text-slate-500 text-[10px] font-bold flex items-center gap-2\">\n                <span class=\"text-base rotate-180\">✂</span> TEAR OFF HERE FOR RECORD <span class=\"text-base\">✂</span>\n            </div>\n        </div>\n\n        <!-- Duplicate Slip (Bank Copy) -->\n        <div class=\"bg-slate-50 border-t-4 border-slate-900 p-4 mx-6 mb-6 shadow-inner\">\n            <div class=\"flex justify-between items-start border-b border-gray-300 pb-2 mb-3\">\n                <div class=\"flex items-center gap-2\">\n                    <div class=\"h-8 w-1.5 bg-yellow-600\"></div>\n                    <div>\n                        <h2 class=\"text-sm font-black text-slate-900 uppercase tracking-wide\">Bank Copy / Office Copy</h2>\n                        <p class=\"text-[9px] text-slate-500 font-bold uppercase tracking-wider\">{{society_name}}</p>\n                    </div>\n                </div>\n                <div class=\"text-right\">\n                    <p class=\"text-[10px] font-black text-slate-900 uppercase\">{{billing_month}}</p>\n                    <p class=\"text-[9px] text-slate-500 font-bold\">Billing Month</p>\n                </div>\n            </div>\n\n            <div class=\"flex gap-4 items-end\">\n                <div class=\"flex-grow grid grid-cols-4 gap-y-2 gap-x-4 text-[10px]\">\n                    <div>\n                        <p class=\"text-slate-500 uppercase font-bold text-[8px]\">Bill No</p>\n                        <p class=\"font-black text-slate-900 text-xs border-b border-slate-300 pb-0.5\">{{bill_no}}</p>\n                    </div>\n                    <div class=\"col-span-2\">\n                        <p class=\"text-slate-500 uppercase font-bold text-[8px]\">Consumer Name</p>\n                        <p class=\"font-black text-slate-900 text-xs border-b border-slate-300 pb-0.5 truncate\">{{client_name}}</p>\n                    </div>\n                    <div>\n                        <p class=\"text-slate-500 uppercase font-bold text-[8px]\">House/Plot #</p>\n                        <p class=\"font-black text-slate-900 text-xs border-b border-slate-300 pb-0.5\">{{property_id}}</p>\n                    </div>\n                    <div>\n                        <p class=\"text-slate-500 uppercase font-bold text-[8px]\">Due Date</p>\n                        <p class=\"font-black text-red-600 text-xs border-b border-slate-300 pb-0.5\">{{due_date}}</p>\n                    </div>\n                    <div>\n                         <p class=\"text-slate-500 uppercase font-bold text-[8px]\">Payable (Within)</p>\n                         <p class=\"font-black text-slate-900 text-xs border-b border-slate-300 pb-0.5\">{{total_amount}}</p>\n                    </div>\n                    <div class=\"col-span-2\">\n                         <p class=\"text-slate-500 uppercase font-bold text-[8px]\">Payable (After)</p>\n                         <p class=\"font-black text-slate-900 text-xs border-b border-slate-300 pb-0.5\">{{payable_after_due}}</p>\n                    </div>\n                </div>\n            </div>\n        </div>\n        {{paid_slip_block}}\n\n    </div>\n\n    <script>\n        (function(){\n            function parseNum(s){ if(!s) return 0; s = String(s).replace(/[^0-9.\\-]/g,\'\'); s = s.replace(\',\',\'\'); var n = parseFloat(s); return isNaN(n)?0:n; }\n            try{\n                var container = document.querySelector(\'.border.border-t-0.border-gray-300.mt-0.overflow-hidden.shadow-sm\');\n                if(!container) container = document.querySelector(\'[data-total]\');\n                if(container){\n                    var total = parseNum(container.getAttribute(\'data-total\') || document.querySelector(\'[data-total]\')?.getAttribute(\'data-total\'));\n                    var debit = parseNum(container.getAttribute(\'data-adjust-debit\')) || 0;\n                    var credit = parseNum(container.getAttribute(\'data-adjust-credit\')) || 0;\n                    var lateEl = document.getElementById(\'late_fee_val\');\n                    var lateAmt = parseNum(lateEl ? lateEl.textContent : 0);\n                    var payableAfter = total + lateAmt + debit - credit;\n                    if(lateEl) lateEl.textContent = lateAmt.toFixed(2);\n                    var payEl = document.getElementById(\'payable_after_val\'); if(payEl) payEl.textContent = payableAfter.toFixed(2);\n                }\n            }catch(e){console && console.error && console.error(e);}\n        })();\n    </script>\n\n    </body>\n</html>\n', '', 0, '2026-08-30 21:27:47'),
(8, 1, 'custom template', 'custom-template', 'print_bill', '﻿<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>Utility Bill Template</title>\n    <!-- Tailwind CSS for the classes used in the template -->\n    <script src=\"https://cdn.tailwindcss.com\"></script>\n    <style>\n        @import url(\'https://fonts.googleapis.com/css2?family=Inter:wght@300;400;600;800;900&display=swap\');\n        \n        body {\n            font-family: \'Inter\', sans-serif;\n            background-color: #f3f4f6;\n            display: flex;\n            justify-content: center;\n            padding: 20px;\n        }\n\n        @page {\n            size: A4;\n            margin: 12.7mm; /* default-like printer margin (~0.5in) */\n        }\n\n        @media print {\n            body {\n                margin: 0;\n                padding: 0;\n                background-color: white;\n                -webkit-print-color-adjust: exact;\n                print-color-adjust: exact;\n            }\n            .page {\n                margin: 0 auto;\n                width: 184mm; /* fit within A4 printable area with default margins */\n                min-height: 271mm;\n                height: auto !important;\n                box-shadow: none;\n                overflow: visible !important;\n                border: 3px solid #0f172a !important;\n            }\n            .no-print {\n                display: none;\n            }\n        }\n\n        /* subm-modern-dark-print-lines */\n        .page table, .page th, .page td { border-color:#111827 !important; }\n        .page .border-gray-100, .page .border-gray-200, .page .border-gray-300, .page .border-slate-300, .page .border-slate-700 { border-color:#111827 !important; }\n        .page .divide-gray-200 > :not([hidden]) ~ :not([hidden]) { border-color:#111827 !important; }\n    \n/* subm-modern-a4-border-layout */\n@page { size:A4; margin:12.7mm; }\n.page { width:190mm !important; min-height:277mm !important; border:3px solid #0f172a !important; box-sizing:border-box !important; }\n@media print { .page { margin:0 auto !important; width:184mm !important; min-height:271mm !important; height:auto !important; box-shadow:none !important; overflow:visible !important; border:3px solid #0f172a !important; } }\n\n/* subm-modern-history-grid-fix */\n.subm-history-table{border-collapse:collapse !important;border-spacing:0 !important;table-layout:fixed !important;width:100% !important;}\n.subm-history-table th,.subm-history-table td{border-color:#111827 !important;}\n.subm-history-table th,.subm-history-table td{vertical-align:middle;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}\n.subm-history-table thead th{padding-top:2px !important;padding-bottom:2px !important;}\n.subm-history-table tbody td{padding-top:3px !important;padding-bottom:3px !important;line-height:1.15 !important;}\n.subm-history-table th:nth-child(1),.subm-history-table td:nth-child(1){width:22% !important;}\n.subm-history-table th:nth-child(2),.subm-history-table td:nth-child(2){width:13% !important;}\n.subm-history-table th:nth-child(3),.subm-history-table td:nth-child(3){width:17% !important;}\n.subm-history-table th:nth-child(4),.subm-history-table td:nth-child(4){width:17% !important;}\n.subm-history-table th:nth-child(5),.subm-history-table td:nth-child(5){width:13% !important;}\n.subm-history-table th:nth-child(6),.subm-history-table td:nth-child(6){width:18% !important;}\n.subm-history-table tbody td{border-right:1px solid #111827 !important;border-bottom:1px solid #111827 !important;}\n.subm-history-table tbody td:last-child{border-right:0 !important;}\n@media print{.subm-history-table th,.subm-history-table td{border-color:#000 !important;}.subm-history-table tbody td{border-right:1px solid #000 !important;border-bottom:1px solid #000 !important;}}\n\n/* subm-template-print-consistency */\n@media print { body { -webkit-print-color-adjust: exact; print-color-adjust: exact; } }\n</style>\n</head>\n<body>\n    {{paid_stamp}}\n\n    <!-- Print Button (Hidden in Print) -->\n    <button onclick=\"window.print()\" class=\"fixed top-6 right-6 bg-slate-900 text-white px-5 py-2.5 rounded-lg shadow-xl no-print z-50 hover:bg-slate-800 font-bold flex items-center gap-2 border-2 border-yellow-500 transition-all\">\n        <svg xmlns=\"http://www.w3.org/2003/svg\" width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"6 9 6 2 18 2 18 9\"></polyline><path d=\"M6 18H4a2 2 0 0 1-2-2v-5a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2v5a2 2 0 0 1-2 2h-2\"></path><rect x=\"6\" y=\"14\" width=\"12\" height=\"8\"></rect></svg>\n        Print Bill\n    </button>\n\n    <!-- A4 Page Container -->\n    <div class=\"page w-[190mm] min-h-[277mm] bg-white border-[3px] border-slate-900 flex flex-col font-sans relative shadow-2xl box-border text-slate-900 mx-auto\">\n        \n        <!-- Header -->\n        <div class=\"bg-slate-900 text-white p-5 flex items-center justify-between border-b-4 border-yellow-600\">\n            <div class=\"flex items-center gap-4\">\n                <!-- Logo Placeholder -->\n                <div class=\"h-14 w-14 bg-white rounded-full flex items-center justify-center text-slate-900 font-bold border-2 border-yellow-600 overflow-hidden\">\n                    <img src=\"{{society_logo}}\" alt=\"Logo\" class=\"object-cover h-full w-full\">\n                </div>\n                <div>\n                    <h1 class=\"text-2xl font-black uppercase tracking-widest text-white\">{{society_name}}</h1>\n                    <p class=\"text-[9px] font-medium mt-0.5 text-gray-300\">{{society_address}}</p>\n                    <p class=\"text-[9px] font-bold mt-0.5 text-yellow-500\">Mobile: {{society_mobile}}</p>\n                </div>\n            </div>\n            <div class=\"text-right\">\n                <span class=\"bg-yellow-600 text-black px-3 py-1 rounded-sm text-[10px] uppercase tracking-widest font-black shadow-lg\">Utility Invoice</span>\n                <p class=\"text-[9px] mt-1 text-gray-400\">NTN: 1234567-8</p>\n            </div>\n        </div>\n\n        <!-- Summary Grid -->\n        <div class=\"grid grid-cols-6 border-b border-gray-300 text-center text-[10px] divide-x divide-gray-300 mb-3 bg-white\">\n            <div class=\"flex flex-col\">\n                <div class=\"py-1.5 bg-slate-50 font-bold text-slate-500 uppercase border-b border-gray-200\">Bill No</div>\n                <div class=\"py-2 font-mono font-black text-slate-900\">{{bill_no}}</div>\n            </div>\n            <div class=\"flex flex-col\">\n                <div class=\"py-1.5 bg-slate-50 font-bold text-slate-500 uppercase border-b border-gray-200\">Consumer ID</div>\n                <div class=\"py-2 font-mono font-black text-slate-900\">{{consumer_id}}</div>\n            </div>\n            <div class=\"flex flex-col\">\n                <div class=\"py-1.5 bg-slate-50 font-bold text-slate-500 uppercase border-b border-gray-200\">Property</div>\n                <div class=\"py-2 font-mono font-black text-slate-900\">{{property_id}}</div>\n            </div>\n            <div class=\"flex flex-col\">\n                <div class=\"py-1.5 bg-slate-50 font-bold text-slate-500 uppercase border-b border-gray-200\">Billing Month</div>\n                <div class=\"py-2 font-mono font-black text-slate-900\">{{billing_month}}</div>\n            </div>\n            <div class=\"flex flex-col\">\n                <div class=\"py-1.5 bg-slate-50 font-bold text-slate-500 uppercase border-b border-gray-200\">Issue Date</div>\n                <div class=\"py-2 font-mono font-black text-slate-900\">{{issue_date}}</div>\n            </div>\n            <div class=\"flex flex-col bg-yellow-50\">\n                <div class=\"py-1.5 bg-yellow-100 font-bold text-yellow-900 uppercase border-b border-yellow-200\">Due Date</div>\n                <div class=\"py-2 text-red-600 font-black font-mono\">{{due_date}}</div>\n            </div>\n        </div>\n\n        <!-- Main Content Area -->\n        <div class=\"flex gap-4 px-6\">\n            \n            <!-- Left Column: Details -->\n            <div class=\"flex-[7] flex flex-col gap-2\">\n                \n                <!-- Consumer Info -->\n                <section>\n                    <h3 class=\"bg-slate-900 px-2 py-1 text-[10px] font-bold text-white uppercase tracking-wide flex justify-between items-center\">\n                        Consumer Information\n                        <span class=\"text-yellow-500\">RESIDENTIAL</span>\n                    </h3>\n                    <div class=\"p-2 border border-t-0 border-gray-300 bg-slate-50/50\">\n                        <p class=\"text-[10px] font-black text-slate-700 uppercase tracking-wide subm-modern-consumer-before-client\">Consumer ID: {{consumer_id}}</p>\n                        <p class=\"text-base font-black text-slate-900 uppercase\">{{client_name}}</p>\n                        <p class=\"text-[10px] font-semibold text-slate-500 mt-0.5 uppercase\">Resident / Owner</p>\n                        <p class=\"text-xs text-slate-700 mt-1 leading-relaxed\">{{client_address}}</p>\n                    </div>\n                </section>\n\n                <!-- Reading Details -->\n                <section>\n                    <h3 class=\"bg-gray-200 px-2 py-1 text-[10px] font-black text-slate-700 border-l-4 border-slate-900 uppercase tracking-wide\">Meter Reading Details</h3>\n                    <div class=\"border border-t-0 border-gray-300 overflow-hidden\">\n                        <table class=\"w-full text-[10px]\">\n                            <thead class=\"bg-gray-100 text-slate-600 border-b border-gray-300 uppercase font-bold\">\n                                <tr>\n                                    <th class=\"py-1.5 px-2 text-center border-r border-gray-300\">Previous</th>\n                                    <th class=\"py-1.5 px-2 text-center border-r border-gray-300\">Current</th>\n                                    <th class=\"py-1.5 px-2 text-center border-r border-gray-300\">Units</th>\n                                    <th class=\"py-1.5 px-2 text-center\">Rate</th>\n                                </tr>\n                            </thead>\n                            <tbody class=\"text-slate-900 font-medium text-center\">\n                                <tr>\n                                    <td class=\"py-2 border-r border-gray-300 text-gray-500\">{{prev_reading}}</td>\n                                    <td class=\"py-2 border-r border-gray-300 font-bold\">{{curr_reading}}</td>\n                                    <td class=\"py-2 border-r border-gray-300 font-black bg-yellow-50\">{{units_consumed}}</td>\n                                    <td class=\"py-2\">{{unit_price}}</td>\n                                </tr>\n                                <tr class=\"bg-slate-50 border-t border-gray-200\">\n                                    <td colspan=\"4\" class=\"py-1.5 text-[10px] font-bold text-slate-700\">\n                                        <span class=\"uppercase text-[9px] tracking-wide text-slate-500 mr-2\">Calculation:</span>\n                                        {{energy_calculation}}\n                                    </td>\n                                </tr>\n                            </tbody>\n                        </table>\n                    </div>\n                </section>\n\n                <!-- Meter Image & Small Advertisement -->\n                <div class=\"flex gap-2\">\n                    <!-- Meter Image -->\n                    <div class=\"flex-1\">\n                        <h3 class=\"bg-gray-200 px-2 py-1 text-[10px] font-black text-slate-700 border-l-4 border-slate-900 uppercase tracking-wide\">Ref. Meter Image</h3>\n                        <div class=\"border border-t-0 border-gray-300 bg-white h-24 overflow-hidden\">\n                            <div class=\"w-full h-full flex items-center justify-center overflow-hidden\">\n                                {{meter_image}}\n                            </div>\n                        </div>\n                    </div>\n                    \n                    <!-- Small Ad Area -->\n                    <div class=\"flex-1\">\n                        <h3 class=\"bg-gray-200 px-2 py-1 text-[10px] font-black text-slate-700 border-l-4 border-slate-900 uppercase tracking-wide\">Preview Caution</h3>\n                        <div class=\"mt-0.5 bg-slate-50 p-2 text-left h-24 overflow-auto\">\n                             {{bill_notice}}\n                        </div>\n                    </div>\n                </div>\n\n                <!-- History Table -->\n                <section>\n                    <h3 class=\"bg-gray-200 px-2 py-1 text-[10px] font-black text-slate-700 border-l-4 border-slate-900 uppercase tracking-wide\">Payment History (Last 12 Months)</h3>\n                    <div class=\"border border-t-0 border-gray-300 overflow-hidden\">\n                        <table class=\"w-full text-[8px] table-fixed subm-history-table\">\n                            <thead class=\"bg-gray-100 text-slate-600 border-b border-gray-300 uppercase font-bold\">\n                                <tr>\n                                    <th class=\"w-[22%] py-0.5 px-1.5 text-left border-r border-gray-300\">Month</th>\n                                    <th class=\"w-[13%] py-0.5 px-1 text-center border-r border-gray-300\">Units</th>\n                                    <th class=\"w-[17%] py-0.5 px-1 text-center border-r border-gray-300\">Bill AMT</th>\n                                    <th class=\"w-[17%] py-0.5 px-1 text-center border-r border-gray-300\">Paid AMT</th>\n                                    <th class=\"w-[13%] py-0.5 px-1 text-center border-r border-gray-300\">Adj.</th>\n                                    <th class=\"w-[18%] py-0.5 px-1 text-center\">Status</th>\n                                </tr>\n                            </thead>\n                            <tbody class=\"divide-y divide-gray-200 text-slate-800 font-medium leading-none\">\n                                {{history_rows}}\n                            </tbody>\n                        </table>\n                    </div>\n                </section>\n                \n            </div>\n\n            <!-- Right Column: Financials -->\n            <div class=\"flex-[5] flex flex-col\">\n                <h3 class=\"bg-slate-900 px-2 py-1 text-[10px] font-bold text-white uppercase tracking-wide text-center\">Current Charges</h3>\n                \n                <!-- Charges Table -->\n                <div class=\"border border-t-0 border-gray-300 mt-0 overflow-hidden shadow-sm\" data-total=\"{{total_amount}}\" data-late-percent=\"{{late_fee_percent}}\" data-due-date-iso=\"{{due_date_iso}}\" data-adjust-debit=\"{{adjustment_debit}}\" data-adjust-credit=\"{{adjustment_credit}}\">\n                    <table class=\"w-full text-[10px]\">\n                        <thead class=\"bg-gray-100 border-b border-gray-300\">\n                            <tr>\n                                <th class=\"p-1.5 text-left text-slate-600 font-bold uppercase border-r border-gray-300\">Description</th>\n                                <th class=\"p-1.5 text-right text-slate-600 font-bold uppercase\">Amount</th>\n                            </tr>\n                        </thead>\n                        <tbody class=\"divide-y divide-gray-200\">\n                            {{utility_rows}}\n                            {{maintenance_rows}}\n                            {{other_rows}}\n                            \n                            <!-- Static Footer Rows -->\n                            <tr class=\"bg-slate-50 text-slate-900 font-bold\">\n                                <td class=\"p-1.5 border-r border-gray-300\">Arrears / Previous</td>\n                                <td class=\"p-1.5 text-right\">{{arrears}}</td>\n                            </tr>\n                            \n                            <!-- Total Block -->\n                            <tr class=\"bg-slate-900 text-white font-black border-t-2 border-yellow-600\">\n                                <td class=\"p-2 text-xs border-r border-slate-700 uppercase tracking-wide\">Payable Within Due</td>\n                                <td class=\"p-2 text-right text-lg\">{{total_amount}}</td>\n                            </tr>\n                            \n                            <tr class=\"bg-white text-red-600 font-bold border-t border-gray-300\">\n                                <td class=\"p-1.5 text-[9px] border-r border-gray-300 text-right uppercase pt-2\">Late Fee ({{late_fee_percent}}%)</td>\n                                <td class=\"p-1.5 text-right text-xs pt-2\"><span id=\"late_fee_val\">{{late_fee}}</span></td>\n                            </tr>\n                            <tr class=\"bg-slate-50 text-slate-900 font-medium\">\n                                <td class=\"p-1.5 border-r border-gray-300\">Adjustment - Debit (Increase)</td>\n                                <td class=\"p-1.5 text-right\">{{adjustment_debit}}</td>\n                            </tr>\n                            <tr class=\"bg-slate-50 text-slate-900 font-medium\">\n                                <td class=\"p-1.5 border-r border-gray-300\">Adjustment - Credit (Decrease)</td>\n                                <td class=\"p-1.5 text-right\">{{adjustment_credit}}</td>\n                            </tr>\n                            <tr class=\"bg-slate-50 text-slate-700 text-[10px]\">\n                                <td class=\"p-1.5 border-r border-gray-300\" colspan=\"2\">Note: {{adjustment_note}}</td>\n                            </tr>\n                            <tr class=\"bg-red-50 text-slate-900 font-bold border-t border-gray-200\">\n                                <td class=\"p-1.5 text-[9px] border-r border-gray-300 text-right uppercase\">Payable After Due</td>\n                                <td class=\"p-1.5 text-right text-base font-black\"><span id=\"payable_after_val\">{{payable_after_due}}</span></td>\n                            </tr>\n                        </tbody>\n                    </table>\n                </div>\n\n                <!-- Combined Bank & Scan Section -->\n                <div class=\"mt-2 border border-gray-300 bg-white p-2 shadow-sm text-[9px] font-medium leading-tight text-slate-600\">\n                    {{bank_details}}\n                </div>\n\n                <!-- Vertical Fill Ad Space -->\n                <div class=\"mt-2\">\n                    <div class=\"h-40 border border-gray-300 bg-slate-50 flex flex-col items-center justify-center text-center overflow-hidden rounded-lg\">\n                        {{advertisement}}\n                    </div>\n                </div>\n\n            </div>\n        </div>\n\n        <!-- Separator -->\n        <div class=\"w-full py-4 relative px-6 mt-2\">\n            <div class=\"absolute top-1/2 left-0 w-full border-t-[2px] border-dashed border-slate-400\"></div>\n            <div class=\"absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 bg-white px-3 text-slate-500 text-[10px] font-bold flex items-center gap-2\">\n                <span class=\"text-base rotate-180\">✂</span> TEAR OFF HERE FOR RECORD <span class=\"text-base\">✂</span>\n            </div>\n        </div>\n\n        <!-- Duplicate Slip (Bank Copy) -->\n        <div class=\"bg-slate-50 border-t-4 border-slate-900 p-4 mx-6 mb-6 shadow-inner\">\n            <div class=\"flex justify-between items-start border-b border-gray-300 pb-2 mb-3\">\n                <div class=\"flex items-center gap-2\">\n                    <div class=\"h-8 w-1.5 bg-yellow-600\"></div>\n                    <div>\n                        <h2 class=\"text-sm font-black text-slate-900 uppercase tracking-wide\">Bank Copy / Office Copy</h2>\n                        <p class=\"text-[9px] text-slate-500 font-bold uppercase tracking-wider\">{{society_name}}</p>\n                    </div>\n                </div>\n                <div class=\"text-right\">\n                    <p class=\"text-[10px] font-black text-slate-900 uppercase\">{{billing_month}}</p>\n                    <p class=\"text-[9px] text-slate-500 font-bold\">Billing Month</p>\n                </div>\n            </div>\n\n            <div class=\"flex gap-4 items-end\">\n                <div class=\"flex-grow grid grid-cols-4 gap-y-2 gap-x-4 text-[10px]\">\n                    <div>\n                        <p class=\"text-slate-500 uppercase font-bold text-[8px]\">Bill No</p>\n                        <p class=\"font-black text-slate-900 text-xs border-b border-slate-300 pb-0.5\">{{bill_no}}</p>\n                    </div>\n                    <div class=\"col-span-2\">\n                        <p class=\"text-slate-500 uppercase font-bold text-[8px]\">Consumer Name</p>\n                        <p class=\"font-black text-slate-900 text-xs border-b border-slate-300 pb-0.5 truncate\">{{client_name}}</p>\n                    </div>\n                    <div>\n                        <p class=\"text-slate-500 uppercase font-bold text-[8px]\">House/Plot #</p>\n                        <p class=\"font-black text-slate-900 text-xs border-b border-slate-300 pb-0.5\">{{property_id}}</p>\n                    </div>\n                    <div>\n                        <p class=\"text-slate-500 uppercase font-bold text-[8px]\">Due Date</p>\n                        <p class=\"font-black text-red-600 text-xs border-b border-slate-300 pb-0.5\">{{due_date}}</p>\n                    </div>\n                    <div>\n                         <p class=\"text-slate-500 uppercase font-bold text-[8px]\">Payable (Within)</p>\n                         <p class=\"font-black text-slate-900 text-xs border-b border-slate-300 pb-0.5\">{{total_amount}}</p>\n                    </div>\n                    <div class=\"col-span-2\">\n                         <p class=\"text-slate-500 uppercase font-bold text-[8px]\">Payable (After)</p>\n                         <p class=\"font-black text-slate-900 text-xs border-b border-slate-300 pb-0.5\">{{payable_after_due}}</p>\n                    </div>\n                </div>\n            </div>\n        </div>\n        {{paid_slip_block}}\n\n    </div>\n\n    <script>\n        (function(){\n            function parseNum(s){ if(!s) return 0; s = String(s).replace(/[^0-9.\\-]/g,\'\'); s = s.replace(\',\',\'\'); var n = parseFloat(s); return isNaN(n)?0:n; }\n            try{\n                var container = document.querySelector(\'.border.border-t-0.border-gray-300.mt-0.overflow-hidden.shadow-sm\');\n                if(!container) container = document.querySelector(\'[data-total]\');\n                if(container){\n                    var total = parseNum(container.getAttribute(\'data-total\') || document.querySelector(\'[data-total]\')?.getAttribute(\'data-total\'));\n                    var debit = parseNum(container.getAttribute(\'data-adjust-debit\')) || 0;\n                    var credit = parseNum(container.getAttribute(\'data-adjust-credit\')) || 0;\n                    var lateEl = document.getElementById(\'late_fee_val\');\n                    var lateAmt = parseNum(lateEl ? lateEl.textContent : 0);\n                    var payableAfter = total + lateAmt + debit - credit;\n                    if(lateEl) lateEl.textContent = lateAmt.toFixed(2);\n                    var payEl = document.getElementById(\'payable_after_val\'); if(payEl) payEl.textContent = payableAfter.toFixed(2);\n                }\n            }catch(e){console && console.error && console.error(e);}\n        })();\n    </script>\n\n    </body>\n</html>\n', '', 0, '2026-08-30 21:27:47');
INSERT INTO `billing_templates` (`id`, `society_id`, `name`, `slug`, `template_type`, `html_content`, `css_content`, `is_default`, `created_at`) VALUES
(9, 1, 'Modren Designe', 'modren-designe', 'print_bill', '<!DOCTYPE html>\r\n<html lang=\"en\">\r\n<head>\r\n    <meta charset=\"UTF-8\">\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n    <title>Utility Bill Template</title>\r\n    <!-- Tailwind CSS for the classes used in the template -->\r\n    <script src=\"https://cdn.tailwindcss.com\"></script>\r\n    <style>\r\n        @import url(\'https://fonts.googleapis.com/css2?family=Inter:wght@300;400;600;800;900&display=swap\');\r\n        \r\n        body {\r\n            font-family: \'Inter\', sans-serif;\r\n            background-color: #f3f4f6;\r\n            display: flex;\r\n            justify-content: center;\r\n            padding: 20px;\r\n        }\r\n\r\n        @media print {\r\n            body {\r\n                margin: 0;\r\n                padding: 0;\r\n                background-color: white;\r\n                -webkit-print-color-adjust: exact;\r\n                print-color-adjust: exact;\r\n            }\r\n            .page {\r\n                border: none;\r\n                margin: 0;\r\n                width: 210mm;\r\n                height: 297mm; /* Enforce exact A4 height */\r\n                min-height: 297mm;\r\n                box-shadow: none;\r\n                overflow: hidden; /* Prevent spillover */\r\n            }\r\n            .no-print {\r\n                display: none;\r\n            }\r\n        }\r\n    \r\n/* subm-modern-dark-print-lines */\r\n.page table, .page th, .page td { border-color:#111827 !important; }\r\n.page .border-gray-100, .page .border-gray-200, .page .border-gray-300, .page .border-slate-300, .page .border-slate-700 { border-color:#111827 !important; }\r\n.page .divide-gray-200 > :not([hidden]) ~ :not([hidden]) { border-color:#111827 !important; }\r\n@media print { .page table, .page th, .page td { border-color:#000 !important; } .page .divide-gray-200 > :not([hidden]) ~ :not([hidden]) { border-color:#000 !important; } }\r\n\r\n/* subm-modern-a4-border-layout */\r\n@page { size:A4; margin:12.7mm; }\r\n.page { width:190mm !important; min-height:277mm !important; border:3px solid #0f172a !important; box-sizing:border-box !important; }\r\n@media print { .page { margin:0 auto !important; width:184mm !important; min-height:271mm !important; height:auto !important; box-shadow:none !important; overflow:visible !important; border:3px solid #0f172a !important; } }\r\n\r\n/* subm-modern-history-grid-fix */\r\n.subm-history-table{border-collapse:collapse !important;border-spacing:0 !important;table-layout:fixed !important;width:100% !important;}\r\n.subm-history-table th,.subm-history-table td{border-color:#111827 !important;}\r\n.subm-history-table th,.subm-history-table td{vertical-align:middle;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}\r\n.subm-history-table thead th{padding-top:2px !important;padding-bottom:2px !important;}\r\n.subm-history-table tbody td{padding-top:3px !important;padding-bottom:3px !important;line-height:1.15 !important;}\r\n.subm-history-table th:nth-child(1),.subm-history-table td:nth-child(1){width:22% !important;}\r\n.subm-history-table th:nth-child(2),.subm-history-table td:nth-child(2){width:13% !important;}\r\n.subm-history-table th:nth-child(3),.subm-history-table td:nth-child(3){width:17% !important;}\r\n.subm-history-table th:nth-child(4),.subm-history-table td:nth-child(4){width:17% !important;}\r\n.subm-history-table th:nth-child(5),.subm-history-table td:nth-child(5){width:13% !important;}\r\n.subm-history-table th:nth-child(6),.subm-history-table td:nth-child(6){width:18% !important;}\r\n.subm-history-table tbody td{border-right:1px solid #111827 !important;border-bottom:1px solid #111827 !important;}\r\n.subm-history-table tbody td:last-child{border-right:0 !important;}\r\n@media print{.subm-history-table th,.subm-history-table td{border-color:#000 !important;}.subm-history-table tbody td{border-right:1px solid #000 !important;border-bottom:1px solid #000 !important;}}\r\n\r\n/* subm-template-print-consistency */\r\n@media print { body { -webkit-print-color-adjust: exact; print-color-adjust: exact; } }\r\n</style>\r\n</head>\r\n<body>\r\n\r\n    <!-- Print Button (Hidden in Print) -->\r\n    <button onclick=\"window.print()\" class=\"fixed top-6 right-6 bg-slate-900 text-white px-5 py-2.5 rounded-lg shadow-xl no-print z-50 hover:bg-slate-800 font-bold flex items-center gap-2 border-2 border-yellow-500 transition-all\">\r\n        <svg xmlns=\"http://www.w3.org/2003/svg\" width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"6 9 6 2 18 2 18 9\"></polyline><path d=\"M6 18H4a2 2 0 0 1-2-2v-5a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2v5a2 2 0 0 1-2 2h-2\"></path><rect x=\"6\" y=\"14\" width=\"12\" height=\"8\"></rect></svg>\r\n        Print Bill\r\n    </button>\r\n\r\n    <!-- A4 Page Container -->\r\n    <div class=\"page w-[210mm] min-h-[297mm] bg-white border border-gray-300 flex flex-col font-sans relative shadow-2xl box-border text-slate-900 mx-auto\">\r\n        \r\n        <!-- Header -->\r\n        <div class=\"bg-slate-900/60 text-white p-5 flex items-center justify-between border-b-4 border-yellow-600\">\r\n            <div class=\"flex items-center gap-4\">\r\n                <!-- Non-Circular Fixed Logo -->\r\n                <img src=\"{{society_logo}}\" alt=\"Logo\" class=\"h-16 w-auto max-w-[120px] object-contain\">\r\n                <div>\r\n                    <h1 class=\"text-2xl font-black uppercase tracking-widest text-white\">{{society_name}}</h1>\r\n                    <p class=\"text-[9px] font-medium mt-0.5 text-gray-100\">{{society_address}}</p>\r\n                    <p class=\"text-[9px] font-bold mt-0.5 text-yellow-400\">Mobile: {{society_mobile}}</p>\r\n                </div>\r\n            </div>\r\n            <div class=\"text-right\">\r\n                <span class=\"bg-yellow-600 text-black px-3 py-1 rounded-sm text-[10px] uppercase tracking-widest font-black shadow-lg\">Utility Invoice</span>\r\n                <!-- NTN removed as requested -->\r\n            </div>\r\n        </div>\r\n\r\n        <!-- Summary Grid -->\r\n        <div class=\"grid grid-cols-6 border-b border-gray-300 text-center text-[10px] divide-x divide-gray-300 mb-3 bg-white\">\r\n            <div class=\"flex flex-col\">\r\n                <div class=\"py-1.5 bg-slate-50 font-bold text-slate-500 uppercase border-b border-gray-200\">Bill No</div>\r\n                <div class=\"py-2 font-mono font-black text-slate-900\">{{bill_no}}</div>\r\n            </div>\r\n            <div class=\"flex flex-col\">\r\n                <div class=\"py-1.5 bg-slate-50 font-bold text-slate-500 uppercase border-b border-gray-200\">Consumer ID</div>\r\n                <div class=\"py-2 font-mono font-black text-slate-900\">{{consumer_id}}</div>\r\n            </div>\r\n            <div class=\"flex flex-col\">\r\n                <div class=\"py-1.5 bg-slate-50 font-bold text-slate-500 uppercase border-b border-gray-200\">Property</div>\r\n                <div class=\"py-2 font-mono font-black text-slate-900\">{{property_id}}</div>\r\n            </div>\r\n            <div class=\"flex flex-col\">\r\n                <div class=\"py-1.5 bg-slate-50 font-bold text-slate-500 uppercase border-b border-gray-200\">Billing Month</div>\r\n                <div class=\"py-2 font-mono font-black text-slate-900\">{{billing_month}}</div>\r\n            </div>\r\n            <div class=\"flex flex-col\">\r\n                <div class=\"py-1.5 bg-slate-50 font-bold text-slate-500 uppercase border-b border-gray-200\">Issue Date</div>\r\n                <div class=\"py-2 font-mono font-black text-slate-900\">{{issue_date}}</div>\r\n            </div>\r\n            <div class=\"flex flex-col bg-yellow-50\">\r\n                <div class=\"py-1.5 bg-yellow-100 font-bold text-yellow-900 uppercase border-b border-yellow-200\">Due Date</div>\r\n                <div class=\"py-2 text-red-600 font-black font-mono\">{{due_date}}</div>\r\n            </div>\r\n        </div>\r\n\r\n        <!-- Main Content Area -->\r\n        <div class=\"flex gap-4 px-6\">\r\n            \r\n            <!-- Left Column: Details -->\r\n            <div class=\"flex-[7] flex flex-col gap-2\">\r\n                \r\n                <!-- Consumer Info -->\r\n                <section>\r\n                    <h3 class=\"bg-slate-900 px-2 py-1 text-[10px] font-bold text-white uppercase tracking-wide flex justify-between items-center\">\r\n                        Consumer Information\r\n                        <span class=\"text-yellow-500\">RESIDENTIAL</span>\r\n                    </h3>\r\n                    <div class=\"p-2 border border-t-0 border-gray-300 bg-slate-50/50\">\r\n                        <p class=\"text-[10px] font-black text-slate-700 uppercase tracking-wide subm-modern-consumer-before-client\">Consumer ID: {{consumer_id}}</p><p class=\"text-base font-black text-slate-900 uppercase\">{{client_name}}</p>\r\n                        <p class=\"text-[10px] font-semibold text-slate-500 mt-0.5 uppercase\">Resident / Owner</p>\r\n                        <p class=\"text-xs text-slate-700 mt-1 leading-relaxed\">{{client_address}}</p>\r\n                    </div>\r\n                </section>\r\n\r\n                <!-- Reading Details -->\r\n                <section>\r\n                    <h3 class=\"bg-gray-200 px-2 py-1 text-[10px] font-black text-slate-700 border-l-4 border-slate-900 uppercase tracking-wide\">Meter Reading Details</h3>\r\n                    <div class=\"border border-t-0 border-gray-300 overflow-hidden\">\r\n                        <table class=\"w-full text-[10px]\">\r\n                            <thead class=\"bg-gray-100 text-slate-600 border-b border-gray-300 uppercase font-bold\">\r\n                                <tr>\r\n                                    <th class=\"py-1.5 px-2 text-center border-r border-gray-300\">Previous</th>\r\n                                    <th class=\"py-1.5 px-2 text-center border-r border-gray-300\">Current</th>\r\n                                    <th class=\"py-1.5 px-2 text-center border-r border-gray-300\">Units</th>\r\n                                    <th class=\"py-1.5 px-2 text-center\">Rate</th>\r\n                                </tr>\r\n                            </thead>\r\n                            <tbody class=\"text-slate-900 font-medium text-center\">\r\n                                <tr>\r\n                                    <td class=\"py-2 border-r border-gray-300 text-gray-500\">{{prev_reading}}</td>\r\n                                    <td class=\"py-2 border-r border-gray-300 font-bold\">{{curr_reading}}</td>\r\n                                    <td class=\"py-2 border-r border-gray-300 font-black bg-yellow-50\">{{units_consumed}}</td>\r\n                                    <td class=\"py-2\">{{unit_price}}</td>\r\n                                </tr>\r\n                                <tr class=\"bg-slate-50 border-t border-gray-200\">\r\n                                    <td colspan=\"4\" class=\"py-1.5 text-[10px] font-bold text-slate-700\">\r\n                                        <span class=\"uppercase text-[9px] tracking-wide text-slate-500 mr-2\">Calculation:</span>\r\n                                        {{energy_calculation}}\r\n                                    </td>\r\n                                </tr>\r\n                            </tbody>\r\n                        </table>\r\n                    </div>\r\n                </section>\r\n\r\n                <!-- Meter Image & Small نوٹس -->\r\n                <div class=\"flex gap-2\">\r\n                    <!-- Meter Image (Bigger Section) -->\r\n                    <div class=\"flex-[3]\">\r\n                        <h3 class=\"bg-gray-200 px-2 py-1 text-[10px] font-black text-slate-700 border-l-4 border-slate-900 uppercase tracking-wide\">Ref. Meter Image</h3>\r\n                        <div class=\"border border-t-0 border-gray-300 bg-white h-24 overflow-hidden\">\r\n                            <div class=\"w-full h-full flex items-center justify-center overflow-hidden\">\r\n                                {{meter_image}}\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                    \r\n                    <!-- Small Ad Area -->\r\n                    <div class=\"flex-[2]\">\r\n                        <h3 class=\"bg-gray-200 px-2 py-1 text-[10px] font-black text-slate-700 border-l-4 border-slate-900 uppercase tracking-wide\">نوٹس</h3>\r\n                        <div class=\"mt-0.5 bg-slate-50 flex flex-col items-center justify-center text-center h-32 overflow-hidden\">\r\n                             {{advertisement_mini}}\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n\r\n                <!-- History Table (Replaced with 12 Blank Rows) -->\r\n                <section>\r\n                    <h3 class=\"bg-gray-200 px-2 py-1 text-[10px] font-black text-slate-700 border-l-4 border-slate-900 uppercase tracking-wide\">Payment History (Last 12 Months)</h3>\r\n                    <div class=\"border border-t-0 border-gray-300 overflow-hidden\">\r\n                        <table  class=\"w-full text-[9px] border-collapse subm-history-table\">\r\n                            <thead class=\"bg-gray-100 text-slate-600 border-b border-gray-300 uppercase font-bold\">\r\n                                <tr>\r\n                                    <th class=\"py-1 px-1 text-center border-r border-gray-300\">Month</th>\r\n                                    <th class=\"py-1 px-1 text-center border-r border-gray-300\">Units</th>\r\n                                    <th class=\"py-1 px-1 text-center border-r border-gray-300\">Bill AMT</th>\r\n                                    <th class=\"py-1 px-1 text-center border-r border-gray-300\">Paid AMT</th>\r\n                                    <th class=\"py-1 px-1 text-center border-r border-gray-300\">Adj.</th>\r\n                                    <th class=\"py-1 px-1 text-center\">Status</th>\r\n                                </tr>\r\n                            </thead>\r\n                            <!-- 12 Empty Rows with Borders -->\r\n                            <tbody class=\"text-slate-800 font-medium leading-none\">{{history_rows}}</tbody>\r\n                        </table>\r\n                    </div>\r\n                </section>\r\n                \r\n            </div>\r\n\r\n            <!-- Right Column: Financials -->\r\n            <div class=\"flex-[5] flex flex-col\">\r\n                <h3 class=\"bg-slate-900 px-2 py-1 text-[10px] font-bold text-white uppercase tracking-wide text-center\">Current Charges</h3>\r\n                \r\n                <!-- Charges Table -->\r\n                <div class=\"border border-t-0 border-gray-300 mt-0 overflow-hidden shadow-sm\">\r\n                    <table class=\"w-full text-[10px]\">\r\n                        <thead class=\"bg-gray-100 border-b border-gray-300\">\r\n                            <tr>\r\n                                <th class=\"p-1.5 text-left text-slate-600 font-bold uppercase border-r border-gray-300\">Description</th>\r\n                                <th class=\"p-1.5 text-right text-slate-600 font-bold uppercase\">Amount</th>\r\n                            </tr>\r\n                        </thead>\r\n                        <tbody class=\"divide-y divide-gray-200\">\r\n                            {{utility_rows}}\r\n                           {{maintenance_rows}}\r\n                            {{other_rows}}                            \r\n                            <!-- Static Footer Rows -->\r\n                            <tr class=\"bg-slate-50 text-slate-900 font-bold\">\r\n                                <td class=\"p-1.5 border-r border-gray-300\">Arrears / Previous</td>\r\n                                <td class=\"p-1.5 text-right\">{{arrears}}</td>\r\n                            </tr>\r\n                            \r\n                            <!-- Total Block -->\r\n                            <tr class=\"bg-slate-900 text-white font-black border-t-2 border-yellow-600\">\r\n                                <td class=\"p-2 text-xs border-r border-slate-700 uppercase tracking-wide\">Payable Within Due</td>\r\n                                <td class=\"p-2 text-right text-lg\">{{total_amount}}</td>\r\n                            </tr>\r\n                            \r\n                            <tr class=\"bg-white text-red-600 font-bold border-t border-gray-300\">\r\n                                <td class=\"p-1.5 text-[9px] border-r border-gray-300 text-right uppercase pt-2\">Late Fee</td>\r\n                                <td class=\"p-1.5 text-right text-xs pt-2\">{{late_fee}}</td>\r\n                            </tr>\r\n                            <tr class=\"bg-red-50 text-slate-900 font-bold border-t border-gray-200\">\r\n                                <td class=\"p-1.5 text-[9px] border-r border-gray-300 text-right uppercase\">Payable After Due</td>\r\n                                <td class=\"p-1.5 text-right text-base font-black\">{{payable_after_due}}</td>\r\n                            </tr>\r\n                        </tbody>\r\n                    </table>\r\n                </div>\r\n\r\n                <!-- Combined Bank & Scan Section (Compact, No Gap) -->\r\n                <div class=\"flex gap-2 mt-2\">\r\n                    <!-- Bank Details -->\r\n                    <div class=\"flex-[2] border border-gray-300 bg-white p-2 shadow-sm text-[9px] font-medium leading-tight text-slate-600\">\r\n                        {{bank_details}}\r\n                    </div>\r\n\r\n                    <!-- QR Code -->\r\n                    \r\n                </div>\r\n\r\n                <!-- Vertical Fill Ad Space -->\r\n                <div class=\"mt-2\">\r\n                    <div class=\"h-40 border border-gray-300 bg-slate-50 flex flex-col items-center justify-center text-center overflow-hidden rounded-lg\">\r\n                        {{advertisement}}\r\n                    </div>\r\n                </div>\r\n\r\n            </div>\r\n        </div>\r\n\r\n        <!-- Separator -->\r\n        <div class=\"w-full py-4 relative px-6 mt-2\">\r\n            <div class=\"absolute top-1/2 left-0 w-full border-t-[2px] border-dashed border-slate-400\"></div>\r\n            <div class=\"absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 bg-white px-3 text-slate-500 text-[10px] font-bold flex items-center gap-2\">\r\n                <span class=\"text-base rotate-180\">✂</span> TEAR OFF HERE FOR RECORD <span class=\"text-base\">✂</span>\r\n            </div>\r\n        </div>\r\n\r\n        <!-- Duplicate Slip (Bank Copy) -->\r\n        <div class=\"bg-slate-50 border-t-4 border-slate-900 p-4 mx-6 mb-6 shadow-inner\">\r\n            <div class=\"flex justify-between items-start border-b border-gray-300 pb-2 mb-3\">\r\n                <div class=\"flex items-center gap-2\">\r\n                    <div class=\"h-8 w-1.5 bg-yellow-600\"></div>\r\n                    <div>\r\n                        <h2 class=\"text-sm font-black text-slate-900 uppercase tracking-wide\">Bank Copy / Office Copy</h2>\r\n                        <p class=\"text-[9px] text-slate-500 font-bold uppercase tracking-wider\">{{society_name}}</p>\r\n                    </div>\r\n                </div>\r\n                <div class=\"text-right\">\r\n                    <p class=\"text-[10px] font-black text-slate-900 uppercase\">{{billing_month}}</p>\r\n                    <p class=\"text-[9px] text-slate-500 font-bold\">Billing Month</p>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"flex flex-col gap-3\">\r\n                <!-- Top row of consumer info -->\r\n                <div class=\"grid grid-cols-4 gap-4 text-[10px]\">\r\n                    <div>\r\n                        <p class=\"text-slate-500 uppercase font-bold text-[8px]\">Bill No</p>\r\n                        <p class=\"font-black text-slate-900 text-xs border-b border-slate-300 pb-0.5\">{{bill_no}}</p>\r\n                    </div>\r\n                    <div class=\"col-span-2\">\r\n                        <p class=\"text-slate-500 uppercase font-bold text-[8px]\">Consumer Name</p>\r\n                        <p class=\"font-black text-slate-900 text-xs border-b border-slate-300 pb-0.5 truncate\">{{client_name}}</p>\r\n                    </div>\r\n                    <div>\r\n                        <p class=\"text-slate-500 uppercase font-bold text-[8px]\">Unit/Property</p>\r\n                        <p class=\"font-black text-slate-900 text-xs border-b border-slate-300 pb-0.5\">{{property_id}}</p>\r\n                    </div>\r\n                </div>\r\n\r\n                <!-- Bottom row aligned in a single line (4 inputs) -->\r\n                <div class=\"grid grid-cols-4 gap-4 text-[10px]\">\r\n                    <div>\r\n                         <p class=\"text-slate-500 uppercase font-bold text-[8px]\">Payable (Within)</p>\r\n                         <p class=\"font-black text-slate-900 text-xs border-b border-slate-300 pb-0.5\">{{total_amount}}</p>\r\n                    </div>\r\n                    <div>\r\n                        <p class=\"text-slate-500 uppercase font-bold text-[8px]\">Due Date</p>\r\n                        <p class=\"font-black text-red-600 text-xs border-b border-slate-300 pb-0.5\">{{due_date}}</p>\r\n                    </div>\r\n                    <div>\r\n                         <p class=\"text-slate-500 uppercase font-bold text-[8px]\">Late Fee</p>\r\n                         <p class=\"font-black text-slate-900 text-xs border-b border-slate-300 pb-0.5\">{{late_fee}}</p>\r\n                    </div>\r\n                    <div>\r\n                        <p class=\"text-slate-500 uppercase font-bold text-[8px]\">Payable (After)</p>\r\n                         <p class=\"font-black text-slate-900 text-xs border-b border-slate-300 pb-0.5\">{{payable_after_due}}</p>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n\r\n    </div>\r\n\r\n</body>\r\n</html>', '', 0, '2026-08-30 21:27:47'),
(11, 1, 'White VillasBill', 'white-villasbill', 'print_bill', '<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>Utility Bill - Letter Size Seamless</title>\n    <!-- Tailwind CSS -->\n    <script src=\"https://cdn.tailwindcss.com\"></script>\n    <style>\n        @import url(\'https://fonts.googleapis.com/css2?family=Inter:wght@300;400;600;800;900&display=swap\');\n        @import url(\'https://fonts.googleapis.com/css2?family=Noto+Nastaliq+Urdu:wght@400;700&display=swap\');\n        \n        * {\n            box-sizing: border-box;\n            -webkit-print-color-adjust: exact !important;\n            print-color-adjust: exact !important;\n            color-adjust: exact !important;\n        }\n\n        body {\n            font-family: \'Inter\', sans-serif;\n            background-color: #f3f4f6;\n            display: flex;\n            justify-content: center;\n            padding: 0; \n            margin: 0;\n        }\n\n        .urdu-font {\n            font-family: \'Jameel Noori Nastaleeq\', \'Noto Nastaliq Urdu\', serif;\n        }\n\n        .charges-table td:nth-child(2) {\n            font-weight: 800;\n        }\n\n        /* STRICT LETTER DIMENSIONS WITH 5MM HORIZONTAL MARGINS */\n        .page {\n            width: 205.9mm;\n            height: 275mm; \n            min-width: 205.9mm;\n            min-height: 275mm;\n            max-width: 205.9mm;\n            /* max-height removed */\n            background-color: white;\n            border: 3px solid #1e3a8a;\n            display: flex;\n            flex-direction: column;\n            overflow: visible;\n            position: relative;\n            box-shadow: 0 0 20px rgba(0,0,0,0.2);\n            margin: 2mm auto; \n            padding: 0;\n        }\n\n        @media print {\n            @page {\n                size: Letter;\n                margin: 0; \n            }\n            html, body {\n                height: 100%;\n                overflow: visible;\n                background-color: white;\n            }\n            .page {\n                margin-top: 2mm !important;\n                margin-bottom: 2mm !important;\n                margin-left: 5mm !important;\n                margin-right: 5mm !important;\n                border: 3px solid #1e3a8a !important;\n                box-shadow: none !important;\n                width: 205.9mm !important;\n                height: 275mm !important;\n                page-break-after: avoid !important;\n                page-break-inside: avoid !important;\n            }\n            .no-print {\n                display: none !important;\n            }\n            /* Explicit colors for print */\n            .late-fee-highlight { background-color: #dc2626 !important; color: white !important; }\n            .section-header-blue { background-color: #1e3a8a !important; color: white !important; }\n        }\n    \n        .page table, .page th, .page td { border-color:#111827 !important; }\n        .page .divide-gray-200 > :not([hidden]) ~ :not([hidden]) { border-color:#111827 !important; }\n\n        .subm-history-table {\n            border-collapse: collapse !important;\n            border-spacing: 0 !important;\n            table-layout: fixed !important;\n            width: 100% !important;\n            height: auto !important;\n            font-size: 8.5px !important;\n        }\n        .subm-history-table th {\n            background-color: #eff6ff !important;\n            color: #1d4ed8 !important;\n            font-weight: 800 !important;\n            text-transform: uppercase !important;\n            border: 1px solid #111827 !important;\n            vertical-align: middle;\n            text-align: center !important;\n            padding: 2px 3px !important;\n            font-size: 8px !important;\n            line-height: 1.1 !important;\n        }\n        .subm-history-table td {\n            border: 1px solid #111827 !important;\n            vertical-align: middle;\n            text-align: center !important;\n            overflow: visible;\n            text-overflow: ellipsis;\n            white-space: nowrap;\n            padding: 1.5px 3px !important;\n            font-size: 8.5px !important;\n            line-height: 1.15 !important;\n        }\n\n        .meter-img-container img {\n            max-width: 100%;\n            max-height: 100%;\n            width: auto;\n            height: auto;\n            object-fit: contain;\n            display: block;\n        }\n\n        .thick-section-border {\n            border: 2px solid #1e3a8a !important;\n        }\n\n    \n/* subm-template-print-consistency */\n@media print { body { -webkit-print-color-adjust: exact; print-color-adjust: exact; } }\n</style>\n</head>\n<body>\n\n    <!-- Page Container -->\n    <div class=\"page\">\n        \n        <!-- Header Section -->\n        <div class=\"bg-white py-1 px-4 flex items-center relative justify-between\">\n            <div class=\"w-1/5 flex-shrink-0\">\n                <img src=\"{{society_logo}}\" alt=\"Logo\" class=\"h-20 w-auto max-w-[180px] object-contain drop-shadow-sm\" style=\"max-height:78px;\">\n            </div>\n            \n            <div class=\"flex-1 text-center px-2\">\n                <h1 class=\"text-[21px] font-black uppercase tracking-wide text-blue-950 leading-tight whitespace-nowrap\" style=\"white-space:nowrap;letter-spacing:0.5px;\">{{society_name}}</h1>\n                <p class=\"text-[11px] font-bold text-slate-800 mt-0.5 leading-tight\">{{society_address}}</p>\n                <p class=\"text-[11px] font-extrabold text-green-800 tracking-wide mt-0.5\">Mobile: {{society_mobile}}</p>\n            </div>\n            \n            <div class=\"w-1/5 flex-shrink-0 flex justify-end items-center\">\n                <span class=\"bg-blue-600 text-white px-3.5 py-1.5 rounded-sm text-[10.5px] uppercase tracking-widest font-black shadow-md border border-blue-700 whitespace-nowrap\" style=\"white-space:nowrap;\">Utility Invoice</span>\n            </div>\n        </div>\n\n        <!-- Summary Grid -->\n        <div class=\"grid grid-cols-6 thick-section-border text-center text-[9px] divide-x-2 divide-blue-300 bg-white\">\n            <div class=\"flex flex-col\">\n                <div class=\"py-1 bg-blue-50 font-bold text-blue-700 uppercase border-b border-blue-200\">Bill No</div>\n                <div class=\"py-1 font-mono font-black text-slate-900 text-[10px] leading-tight\">{{bill_no}}</div>\n            </div>\n            <div class=\"flex flex-col\">\n                <div class=\"py-1 bg-blue-50 font-bold text-blue-700 uppercase border-b border-blue-200\">Consumer ID</div>\n                <div class=\"py-1 font-mono font-black text-slate-900 text-[10px] leading-tight\">{{consumer_id}}</div>\n            </div>\n            <div class=\"flex flex-col\">\n                <div class=\"py-1 bg-blue-50 font-bold text-blue-700 uppercase border-b border-blue-200\">Property</div>\n                <div class=\"py-1 font-mono font-black text-slate-900 text-[10px] leading-tight\">{{property_id}}</div>\n            </div>\n            <div class=\"flex flex-col\">\n                <div class=\"py-1 bg-blue-50 font-bold text-blue-700 uppercase border-b border-blue-200\">Billing Month</div>\n                <div class=\"py-1 font-mono font-black text-slate-900 text-[10px] leading-tight\">{{billing_month}}</div>\n            </div>\n            <div class=\"flex flex-col\">\n                <div class=\"py-1 bg-blue-50 font-bold text-blue-700 uppercase border-b border-blue-200\">Issue Date</div>\n                <div class=\"py-1 font-mono font-black text-slate-900 text-[10px] leading-tight\">{{issue_date}}</div>\n            </div>\n            <div class=\"flex flex-col bg-blue-50/50\">\n                <div class=\"py-1 bg-blue-100 font-bold text-blue-900 uppercase border-b border-blue-200\">Due Date</div>\n                <div class=\"py-1 text-red-600 font-black font-mono text-[10px] leading-tight\">{{due_date}}</div>\n            </div>\n        </div>\n\n        <!-- Main Content Area -->\n        <div class=\"flex flex-grow overflow-hidden\">\n            \n            <!-- Left Column -->\n            <div class=\"flex-[7] flex flex-col border-r-2 border-blue-300\">\n                <!-- Consumer Information -->\n                <section class=\"thick-section-border border-b-0\">\n                    <h3 class=\"bg-blue-900 px-3 py-1 text-[9px] font-bold text-white uppercase tracking-wide flex justify-between items-center text-center\">\n                        Consumer Information\n                        <span class=\"text-blue-300\">RESIDENTIAL</span>\n                    </h3>\n                    <div class=\"p-1.5 bg-blue-50/10\">\n                        <p class=\"text-[8px] font-semibold text-blue-600 uppercase\">Resident / Owner</p>\n                        <p class=\"text-[10px] font-black text-slate-900 uppercase leading-none\">{{client_name}}</p>\n                        <p class=\"text-[9px] font-black text-slate-700 uppercase tracking-wide mt-0.5\">{{property_id}}</p>\n                        <p class=\"text-[9.5px] text-slate-700 leading-tight\">{{client_address}}</p>\n                    </div>\n                </section>\n\n                <!-- Meter Reading Details -->\n                <section class=\"thick-section-border border-b-0\">\n                    <h3 class=\"bg-blue-100 px-3 py-1 text-[9px] font-black text-blue-800 border-b border-blue-900 uppercase tracking-wide\">Meter Reading Details</h3>\n                    <div class=\"overflow-hidden\">\n                        <table class=\"w-full text-[10px]\">\n                            <thead class=\"bg-blue-50 text-blue-700 border-b border-blue-300 uppercase font-bold text-[9px]\">\n                                <tr>\n                                    <th class=\"py-0.5 px-2 text-center border-r border-blue-300\">Previous</th>\n                                    <th class=\"py-0.5 px-2 text-center border-r border-blue-300\">Current</th>\n                                    <th class=\"py-0.5 px-2 text-center border-r border-blue-300\">Units</th>\n                                    <th class=\"py-0.5 px-2 text-center\">Rate</th>\n                                </tr>\n                            </thead>\n                            <tbody class=\"text-slate-900 font-medium text-center divide-y divide-blue-100 font-bold\">\n                                <tr>\n                                    <td class=\"py-1 border-r-2 border-blue-300\">{{prev_reading}}</td>\n                                    <td class=\"py-1 border-r-2 border-blue-300 font-black\">{{curr_reading}}</td>\n                                    <td class=\"py-1 border-r-2 border-blue-300 font-black bg-blue-50/30\">{{units_consumed}}</td>\n                                    <td class=\"py-1 font-black\">{{unit_price}}</td>\n                                </tr>\n                                <tr class=\"bg-blue-50/20\">\n                                    <td colspan=\"4\" class=\"py-0.5 font-bold text-blue-800 text-[10px]\">\n                                        <span class=\"uppercase text-[8px] tracking-wide text-blue-600 mr-2 font-black\">Calc:</span>\n                                        {{energy_calculation}}\n                                    </td>\n                                </tr>\n                            </tbody>\n                        </table>\n                    </div>\n                </section>\n\n                <!-- Meter Image & Notes -->\n                <div class=\"flex thick-section-border border-b-0\">\n                    <div class=\"flex-[3] border-r-2 border-blue-900\">\n                        <h3 class=\"bg-blue-100 px-3 py-1 text-[9px] font-black text-blue-800 border-b border-blue-900 uppercase tracking-wide text-center\">Ref. Meter Image</h3>\n                        <div class=\"p-1 bg-white flex justify-center h-48\">\n                            <div class=\"w-full bg-blue-50 flex items-center justify-center relative overflow-hidden h-full meter-img-container\">\n                                {{meter_image}}\n                            </div>\n                        </div>\n                    </div>\n                    <div class=\"flex-[2]\">\n                        <h3 class=\"bg-red-600 px-3 py-1 text-[13px] font-bold text-white text-center urdu-font border-b border-red-400 uppercase leading-none\">نوٹس</h3>\n                        <div class=\"bg-red-50/10 flex flex-col items-center justify-center text-center p-1.5 h-48 overflow-hidden text-[11px] urdu-font leading-tight\">\n                             {{bill_notice}}\n                        </div>\n                    </div>\n                </div>\n\n                <!-- Payment History & Late Fee Warning Section -->\n                <section class=\"flex-grow flex flex-col overflow-hidden bg-white thick-section-border\">\n                    <h3 class=\"bg-blue-900 px-3 py-1 text-[9px] font-bold text-white uppercase tracking-wide text-center\">Payment History (Last 12 Months)</h3>\n                    <div class=\"flex-grow overflow-auto bg-white\">\n                        <table class=\"subm-history-table text-[10px]\">\n                            <thead class=\"bg-blue-50 text-blue-700 uppercase font-bold text-[9px]\">\n                                <tr>\n                                    <th>Month</th>\n                                    <th>Units</th>\n                                    <th>Bill AMT</th>\n                                    <th>Paid AMT</th>\n                                    <th>Adj.</th>\n                                    <th>Status</th>\n                                </tr>\n                            </thead>\n                            <tbody class=\"text-slate-800 font-medium leading-none\">\n                                {{history_rows}}\n                            </tbody>\n                        </table>\n                    </div>\n                    <!-- MOVED HERE: Late Fee Warning under History Table -->\n                    <div class=\"bg-red-600 late-fee-highlight text-white py-1.5 px-3 border-t border-red-800 urdu-font\">\n                        <p class=\"font-black text-[12px] leading-none text-center\">لیٹ پیمنٹ کی صورت میں جرمانہ عائد کیا جائے گا۔</p>\n                    </div>\n                </section>\n            </div>\n\n            <!-- Right Column -->\n            <div class=\"flex-[5] flex flex-col\">\n                <div class=\"thick-section-border overflow-hidden border-b-0\">\n                    <h3 class=\"bg-blue-900 px-3 py-1 text-[9px] font-bold text-white uppercase tracking-wide text-center\">Current Charges</h3>\n                    <div class=\"bg-white\">\n                        <table class=\"w-full text-[10px] border-collapse charges-table\">\n                            <thead class=\"bg-blue-50 border-b-2 border-blue-300\">\n                                <tr>\n                                    <th class=\"p-1 px-3 text-left text-blue-700 font-bold uppercase border-r border-blue-300 text-[9px]\">Description</th>\n                                    <th class=\"p-1 px-3 text-right text-blue-700 font-bold uppercase text-[9px]\">Amount</th>\n                                </tr>\n                            </thead>\n                            <tbody class=\"divide-y divide-blue-200\">\n                                {{utility_rows}}\n                                {{maintenance_rows}}\n                                {{other_rows}}  \n                                \n                                <tr class=\"bg-blue-50/50 text-slate-800 border-t-2 border-blue-900\">\n                                    <td class=\"p-1 px-3 border-r border-blue-300 font-bold uppercase text-[9px]\">Adjustments</td>\n                                    <td class=\"p-1 px-3 text-right text-[10px] font-bold\">\n                                        {{adjustment_note}} <span class=\"text-blue-700\">+{{adjustment_debit}}</span>/<span class=\"text-red-600\">-{{adjustment_credit}}</span>\n                                    </td>\n                                </tr>\n\n                                <tr class=\"bg-blue-50 text-slate-900 font-bold border-t-2 border-blue-900\">\n                                    <td class=\"p-1 px-3 border-r border-blue-300 font-bold uppercase text-[9px]\">Arrears / Previous</td>\n                                    <td class=\"p-1 px-3 text-right text-[10px] font-black\">{{arrears}}</td>\n                                </tr>\n                                \n                                <tr class=\"bg-blue-900 section-header-blue text-white font-black border-t-2 border-blue-500\">\n                                    <td class=\"p-1.5 px-3 text-[11px] border-r border-blue-700 uppercase tracking-wide font-black\">Payable Within Due</td>\n                                    <td class=\"p-1.5 px-3 text-right text-[10px] leading-none\">{{total_amount}}</td>\n                                </tr>\n                                <tr class=\"bg-white text-red-600 font-bold border-t border-blue-200\">\n                                    <td class=\"p-1 px-3 text-[9px] border-r border-blue-300 text-right uppercase font-bold\">Late Fee</td>\n                                    <td class=\"p-1 px-3 text-right text-[10px] font-black\">{{late_fee}}</td>\n                                </tr>\n                                <tr class=\"bg-red-600 late-fee-highlight text-white font-bold border-t border-blue-200\">\n                                    <td class=\"p-1 px-3 text-[9px] border-r border-blue-300 text-right uppercase font-black\">Payable After Due</td>\n                                    <td class=\"p-1 px-3 text-right text-[10px] font-black leading-none\">{{payable_after_due}}</td>\n                                </tr>\n                            </tbody>\n                        </table>\n                    </div>\n                </div>\n\n                <!-- Unified Payment & Instructions Container -->\n                <div class=\"thick-section-border flex flex-col flex-grow bg-white\">\n                    <div class=\"border-b border-blue-900 p-1.5 px-3 bg-white text-[9px] text-slate-600 leading-tight\">\n                        {{bank_details}}\n                    </div>\n                    \n                    <div class=\"bg-blue-900 section-header-blue py-1 px-3 border-b border-blue-900 flex-shrink-0\">\n                        <p class=\"urdu-font text-[12px] font-bold text-white text-center\">آن لائن بل کی ادائیگی و ہدایات</p>\n                    </div>\n\n                    <!-- Single Integrated Section Container -->\n                    <div class=\"p-2 urdu-font text-blue-900 flex-grow overflow-hidden flex flex-col justify-between\" dir=\"rtl\">\n                        \n                        <!-- 1. Payment Rules & Proof Requirements -->\n                        <ul class=\"text-[9px] font-black leading-tight space-y-1 text-right mb-2\">\n                            <li>● ادائیگی صرف بل پر درج بینک اکاؤنٹ یا کیو آر کوڈ کے ذریعے کریں۔</li>\n                            <li>● ادائیگی کے بعد اسکرین شاٹ یا بینک رسید لازمی ارسال کریں۔ ریفرنس نمبر واضح طور پر درج کریں۔</li>\n                            <li>● ادائیگی کی تصدیق عموماً 24 گھنٹوں کے اندر مکمل کر دی جاتی ہے۔</li>\n                            <li>● اگر 24 گھنٹوں میں بل اپڈیٹ نہ ہو تو براہِ کرم وائٹ ولاز انتظامیہ سے رابطہ کریں۔</li>\n                        </ul>\n\n                        <!-- 2. Portal Upload Instructions & QR -->\n                        <div class=\"p-1.5 bg-blue-50/50 rounded-lg border-2 border-blue-600 flex flex-row-reverse items-center gap-2 mb-2\">\n                            <div class=\"flex-shrink-0 bg-white p-0.5 border border-slate-200 shadow-sm rounded-md w-12 h-12 flex items-center justify-center\">\n                                <img src=\"https://whitevillas.com.pk/wp-content/uploads/2026/02/qr-code.png\" alt=\"Online Bill QR\" class=\"w-full h-full object-contain\">\n                            </div>\n                            <div class=\"text-right flex-grow\">\n                                <p class=\"urdu-font text-[9.5px] font-black leading-none text-blue-900 mb-1\">اپنی ادائیگی کی رسید پورٹل پر اپ لوڈ کریں:</p>\n                                <p dir=\"ltr\" class=\"text-[9px] text-blue-600 underline font-black leading-none mb-1\">https://whitevillas.com.pk/billing</p>\n                                <p class=\"urdu-font text-[8.5px] font-black text-slate-800 leading-none italic\">آئی ڈی سے بل چیک کریں، پھر \'Pay Bill\' منتخب کر کے تفصیلات پُر کریں۔</p>\n                            </div>\n                        </div>\n\n                        <!-- 3. Safety Advice (Late Fee Warning moved out to history table) -->\n                        <div class=\"space-y-1 border-t border-blue-200 pt-1.5\">\n                            <p class=\"font-black text-[9px] leading-tight text-right\">گھر سے باہر جاتے وقت دروازے اور کھڑکیاں اچھی طرح بند کریں، اور حفاظتی اقدامات ضرور اختیار کریں۔ قیمتی اشیاء جیسے زیورات و نقدی کو محفوظ لاکر یا محفوظ مقام پر رکھیں۔</p>\n                        </div>\n                    </div>\n                </div>\n            </div>\n        </div>\n\n        <!-- Separator -->\n        <div class=\"w-full py-0.5 relative\">\n            <div class=\"absolute top-1/2 left-0 w-full border-t-[2px] border-dashed border-blue-400\"></div>\n            <div class=\"absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 bg-white px-3 text-blue-500 text-[9px] font-bold flex items-center gap-2 uppercase tracking-widest\">\n                <span class=\"text-base rotate-180\">✂</span> TEAR OFF HERE <span class=\"text-base\">✂</span>\n            </div>\n        </div>\n\n        <!-- Duplicate Slip -->\n        <div class=\"thick-section-border bg-blue-50/20 p-1 shadow-inner\">\n            <div class=\"flex justify-between items-start border-b border-blue-900 pb-0.5 mb-0.5 px-4\">\n                <div class=\"flex items-center gap-2\">\n                    <div class=\"h-3 w-1 bg-yellow-600\"></div>\n                    <div>\n                        <h2 class=\"text-[9px] font-black text-blue-900 uppercase tracking-wide leading-none\">Bank Copy / Office Copy</h2>\n                        <p class=\"text-[6.5px] text-blue-600 font-bold uppercase tracking-wider leading-none\">{{society_name}}</p>\n                    </div>\n                </div>\n                <div class=\"text-right leading-none\">\n                    <p class=\"text-[7.5px] font-black text-blue-900 uppercase leading-none\">{{billing_month}}</p>\n                    <p class=\"text-[6.5px] text-blue-600 font-bold leading-none\">Billing Month</p>\n                </div>\n            </div>\n\n            <div class=\"flex flex-col gap-1 px-4\">\n                <div class=\"grid grid-cols-4 gap-2 text-[10px]\">\n                    <div>\n                        <p class=\"text-blue-500 uppercase font-bold text-[6px]\">Bill No</p>\n                        <p class=\"font-black text-slate-900 border-b border-blue-200\">{{bill_no}}</p>\n                    </div>\n                    <div class=\"col-span-2\">\n                        <p class=\"text-blue-500 uppercase font-bold text-[6px]\">Consumer Name</p>\n                        <p class=\"font-black text-slate-900 border-b border-blue-200 truncate uppercase\">{{client_name}}</p>\n                    </div>\n                    <div>\n                        <p class=\"text-blue-500 uppercase font-bold text-[6px]\">Property</p>\n                        <p class=\"font-black text-slate-900 border-b border-blue-200 uppercase\">{{property_id}}</p>\n                    </div>\n                </div>\n\n                <div class=\"grid grid-cols-4 gap-2 text-[10px]\">\n                    <div>\n                         <p class=\"text-blue-500 uppercase font-bold text-[6px]\">Payable (Within)</p>\n                         <p class=\"font-black text-slate-900 border-b border-blue-100\">{{total_amount}}</p>\n                    </div>\n                    <div>\n                        <p class=\"text-blue-500 uppercase font-bold text-[6px]\">Due Date</p>\n                        <p class=\"font-black text-red-600 border-b border-red-100 uppercase\">{{due_date}}</p>\n                    </div>\n                    <div>\n                         <p class=\"text-blue-500 uppercase font-bold text-[6px]\">Late Fee</p>\n                         <p class=\"font-black text-slate-900 border-b border-blue-100\">{{late_fee}}</p>\n                    </div>\n                    <div class=\"bg-red-600 late-fee-highlight text-white p-0.5 rounded-sm\">\n                        <p class=\"text-white uppercase font-bold text-[6px]\">Payable (After)</p>\n                         <p class=\"font-black text-white border-b border-red-400\">{{payable_after_due}}</p>\n                    </div>\n                </div>\n            </div>\n        </div>\n\n        <!-- Footer Complaint & Contact Details -->\n        <div class=\"bg-blue-900 section-header-blue text-white p-1 border-t-2 border-blue-600 flex justify-between items-center text-[9px] mt-auto\">\n            <div class=\"font-black uppercase tracking-wider flex items-center gap-2 px-6\">\n                <span class=\"text-blue-400\">●</span> COMPLAINTS: <span class=\"font-mono bg-white text-blue-900 px-2 py-0.5 rounded font-black\">{{society_mobile}}</span>\n            </div>\n            <div class=\"flex gap-4 items-center px-6\">\n                <div class=\"font-bold text-blue-200 border-l border-blue-700 pl-3 uppercase text-[8px]\">\n                    HELPLINE: 24/7 SUPPORT\n                </div>\n            </div>\n        </div>\n\n    </div>\n\n</body>\n</html>', '', 1, '2026-08-30 21:27:47');
INSERT INTO `billing_templates` (`id`, `society_id`, `name`, `slug`, `template_type`, `html_content`, `css_content`, `is_default`, `created_at`) VALUES
(13, 1, 'TTP', 'ttp', 'print_bill', '<!DOCTYPE html>\r\n<html lang=\"en\">\r\n<head>\r\n    <meta charset=\"UTF-8\">\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n    <title>Utility Bill Template - A4 Seamless</title>\r\n    <!-- Tailwind CSS -->\r\n    <script src=\"https://cdn.tailwindcss.com\"></script>\r\n    <style>\r\n        @import url(\'https://fonts.googleapis.com/css2?family=Inter:wght@300;400;600;800;900&display=swap\');\r\n        @import url(\'https://fonts.googleapis.com/css2?family=Noto+Nastaliq+Urdu:wght@400;700&display=swap\');\r\n        \r\n        body {\r\n            font-family: \'Inter\', sans-serif;\r\n            background-color: #f3f4f6;\r\n            display: flex;\r\n            justify-content: center;\r\n            padding: 0;\r\n            margin: 0;\r\n        }\r\n\r\n        .urdu-font {\r\n            font-family: \'Jameel Noori Nastaleeq\', \'Noto Nastaliq Urdu\', serif;\r\n        }\r\n\r\n        /* Bold amounts in charges table */\r\n        .charges-table td:nth-child(2) {\r\n            font-weight: 800;\r\n        }\r\n\r\n        @media print {\r\n            @page {\r\n                size: A4;\r\n                margin: 0;\r\n            }\r\n            body {\r\n                margin: 0;\r\n                padding: 0;\r\n                background-color: white;\r\n                -webkit-print-color-adjust: exact;\r\n                print-color-adjust: exact;\r\n            }\r\n            .page {\r\n                border: 4px solid #1e3a8a !important;\r\n                margin: 0;\r\n                width: 210mm;\r\n                height: 297mm;\r\n                min-height: 297mm;\r\n                max-height: 297mm;\r\n                box-shadow: none;\r\n                overflow: hidden;\r\n                display: flex;\r\n                flex-direction: column;\r\n                box-sizing: border-box;\r\n            }\r\n            .no-print {\r\n                display: none;\r\n            }\r\n        }\r\n    \r\n/* subm-modern-dark-print-lines */\r\n.page table, .page th, .page td { border-color:#111827 !important; }\r\n.page .border-gray-100, .page .border-gray-200, .page .border-gray-300, .page .border-slate-300, .page .border-slate-700 { border-color:#111827 !important; }\r\n.page .divide-gray-200 > :not([hidden]) ~ :not([hidden]) { border-color:#111827 !important; }\r\n@media print { .page table, .page th, .page td { border-color:#000 !important; } .page .divide-gray-200 > :not([hidden]) ~ :not([hidden]) { border-color:#000 !important; } }\r\n\r\n/* subm-modern-a4-border-layout */\r\n@page { size:A4; margin:12.7mm; }\r\n.page { width:190mm !important; min-height:277mm !important; border:3px solid #0f172a !important; box-sizing:border-box !important; }\r\n@media print { .page { margin:0 auto !important; width:184mm !important; min-height:271mm !important; height:auto !important; box-shadow:none !important; overflow:visible !important; border:3px solid #0f172a !important; } }\r\n\r\n/* subm-modern-history-grid-fix */\r\n.subm-history-table{border-collapse:collapse !important;border-spacing:0 !important;table-layout:fixed !important;width:100% !important;}\r\n.subm-history-table th,.subm-history-table td{border-color:#111827 !important;}\r\n.subm-history-table th,.subm-history-table td{vertical-align:middle;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}\r\n.subm-history-table thead th{padding-top:2px !important;padding-bottom:2px !important;}\r\n.subm-history-table tbody td{padding-top:3px !important;padding-bottom:3px !important;line-height:1.15 !important;}\r\n.subm-history-table th:nth-child(1),.subm-history-table td:nth-child(1){width:22% !important;}\r\n.subm-history-table th:nth-child(2),.subm-history-table td:nth-child(2){width:13% !important;}\r\n.subm-history-table th:nth-child(3),.subm-history-table td:nth-child(3){width:17% !important;}\r\n.subm-history-table th:nth-child(4),.subm-history-table td:nth-child(4){width:17% !important;}\r\n.subm-history-table th:nth-child(5),.subm-history-table td:nth-child(5){width:13% !important;}\r\n.subm-history-table th:nth-child(6),.subm-history-table td:nth-child(6){width:18% !important;}\r\n.subm-history-table tbody td{border-right:1px solid #111827 !important;border-bottom:1px solid #111827 !important;}\r\n.subm-history-table tbody td:last-child{border-right:0 !important;}\r\n@media print{.subm-history-table th,.subm-history-table td{border-color:#000 !important;}.subm-history-table tbody td{border-right:1px solid #000 !important;border-bottom:1px solid #000 !important;}}\r\n\r\n/* subm-template-print-consistency */\r\n@media print { body { -webkit-print-color-adjust: exact; print-color-adjust: exact; } }\r\n</style>\r\n</head>\r\n<body>\r\n\r\n    <!-- Print Button -->\r\n    <button onclick=\"window.print()\" class=\"fixed top-6 right-6 bg-blue-900 text-white px-5 py-2.5 rounded-lg shadow-xl no-print z-50 hover:bg-blue-800 font-bold flex items-center gap-2 border-2 border-blue-400 transition-all\">\r\n        <svg xmlns=\"http://www.w3.org/2003/svg\" width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"6 9 6 2 18 2 18 9\"></polyline><path d=\"M6 18H4a2 2 0 0 1-2-2v-5a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2v5a2 2 0 0 1-2 2h-2\"></path><rect x=\"6\" y=\"14\" width=\"12\" height=\"8\"></rect></svg>\r\n        Print Bill\r\n    </button>\r\n\r\n    <!-- Page Container -->\r\n    <div class=\"page w-[210mm] min-h-[297mm] h-[297mm] bg-white border-[4px] border-blue-900 flex flex-col font-sans relative box-border text-slate-900 mx-auto overflow-hidden\">\r\n        \r\n        <!-- Header Section -->\r\n        <div class=\"bg-blue-900/80 text-white py-2 px-4 flex items-center border-b-4 border-blue-600 relative\">\r\n            <!-- Left: Logo -->\r\n            <div class=\"w-1/4\">\r\n                <img src=\"{{society_logo}}\" alt=\"Logo\" class=\"h-20 w-auto max-w-[150px] object-contain\">\r\n            </div>\r\n            \r\n            <!-- Center: Society Details -->\r\n            <div class=\"w-2/4 text-center\">\r\n                <h1 class=\"text-[21px] font-black uppercase tracking-wide text-white leading-tight whitespace-nowrap\" style=\"white-space:nowrap;letter-spacing:0.5px;\">{{society_name}}</h1>\r\n                <p class=\"text-[12px] font-medium text-gray-100 mt-1 leading-tight\">{{society_address}}</p>\r\n                <p class=\"text-[12px] font-bold text-blue-200\">Mobile: {{society_mobile}}</p>\r\n            </div>\r\n            \r\n            <!-- Right: Utility Invoice Tag -->\r\n            <div class=\"w-1/4 flex justify-end items-center\">\r\n                <span class=\"bg-blue-600 text-white px-3 py-1 rounded-sm text-[10px] uppercase tracking-widest font-black shadow-lg\">Utility Invoice</span>\r\n            </div>\r\n        </div>\r\n\r\n        <!-- Summary Grid -->\r\n        <div class=\"grid grid-cols-6 border-b-2 border-blue-300 text-center text-[10px] divide-x-2 divide-blue-300 bg-white\">\r\n            <div class=\"flex flex-col\">\r\n                <div class=\"py-1 bg-blue-50 font-bold text-blue-700 uppercase border-b border-blue-200\">Bill No</div>\r\n                <div class=\"py-1.5 font-mono font-black text-slate-900 text-[11px]\">{{bill_no}}</div>\r\n            </div>\r\n            <div class=\"flex flex-col\">\r\n                <div class=\"py-1 bg-blue-50 font-bold text-blue-700 uppercase border-b border-blue-200\">Consumer ID</div>\r\n                <div class=\"py-1.5 font-mono font-black text-slate-900 text-[11px]\">{{consumer_id}}</div>\r\n            </div>\r\n            <div class=\"flex flex-col\">\r\n                <div class=\"py-1 bg-blue-50 font-bold text-blue-700 uppercase border-b border-blue-200\">Property</div>\r\n                <div class=\"py-1.5 font-mono font-black text-slate-900 text-[11px]\">{{property_id}}</div>\r\n            </div>\r\n            <div class=\"flex flex-col\">\r\n                <div class=\"py-1 bg-blue-50 font-bold text-blue-700 uppercase border-b border-blue-200\">Billing Month</div>\r\n                <div class=\"py-1.5 font-mono font-black text-slate-900 text-[11px]\">{{billing_month}}</div>\r\n            </div>\r\n            <div class=\"flex flex-col\">\r\n                <div class=\"py-1 bg-blue-50 font-bold text-blue-700 uppercase border-b border-blue-200\">Issue Date</div>\r\n                <div class=\"py-1.5 font-mono font-black text-slate-900 text-[11px]\">{{issue_date}}</div>\r\n            </div>\r\n            <div class=\"flex flex-col bg-blue-50/50\">\r\n                <div class=\"py-1 bg-blue-100 font-bold text-blue-900 uppercase border-b border-blue-200\">Due Date</div>\r\n                <div class=\"py-1.5 text-red-600 font-black font-mono text-[11px]\">{{due_date}}</div>\r\n            </div>\r\n        </div>\r\n\r\n        <!-- Main Content Area -->\r\n        <div class=\"flex flex-grow overflow-hidden border-b-2 border-blue-300\">\r\n            \r\n            <!-- Left Column -->\r\n            <div class=\"flex-[7] flex flex-col border-r-2 border-blue-300\">\r\n                <section class=\"border-b-2 border-blue-300\">\r\n                    <h3 class=\"bg-blue-900 px-2 py-1 text-[10px] font-bold text-white uppercase tracking-wide flex justify-between items-center text-center\">\r\n                        Consumer Information\r\n                        <span class=\"text-blue-300\">RESIDENTIAL</span>\r\n                    </h3>\r\n                    <div class=\"p-2 bg-blue-50/10\">\r\n                        <p class=\"text-[10px] font-black text-slate-700 uppercase tracking-wide subm-modern-consumer-before-client\">Consumer ID: {{consumer_id}}</p><p class=\"text-[11px] font-black text-slate-900 uppercase\">{{client_name}}</p>\r\n                        <p class=\"text-[9px] font-semibold text-blue-600 uppercase\">Resident / Owner</p>\r\n                        <p class=\"text-[11px] text-slate-700 leading-tight\">{{client_address}}</p>\r\n                    </div>\r\n                </section>\r\n\r\n                <section class=\"border-b-2 border-blue-300\">\r\n                    <h3 class=\"bg-blue-100 px-2 py-1 text-[10px] font-black text-blue-800 border-l-4 border-blue-900 uppercase tracking-wide\">Meter Reading Details</h3>\r\n                    <div class=\"overflow-hidden\">\r\n                        <table class=\"w-full text-[11px]\">\r\n                            <thead class=\"bg-blue-50 text-blue-700 border-b-2 border-blue-300 uppercase font-bold text-[10px]\">\r\n                                <tr>\r\n                                    <th class=\"py-1 px-2 text-center border-r-2 border-blue-300\">Previous</th>\r\n                                    <th class=\"py-1 px-2 text-center border-r-2 border-blue-300\">Current</th>\r\n                                    <th class=\"py-1 px-2 text-center border-r-2 border-blue-300\">Units</th>\r\n                                    <th class=\"py-1 px-2 text-center\">Rate</th>\r\n                                </tr>\r\n                            </thead>\r\n                            <tbody class=\"text-slate-900 font-medium text-center divide-y-2 divide-blue-100\">\r\n                                <tr>\r\n                                    <!-- Bolder Reading Values -->\r\n                                    <td class=\"py-1.5 border-r-2 border-blue-300 font-bold text-slate-900\">{{prev_reading}}</td>\r\n                                    <td class=\"py-1.5 border-r-2 border-blue-300 font-black\">{{curr_reading}}</td>\r\n                                    <td class=\"py-1.5 border-r-2 border-blue-300 font-black bg-blue-50/30\">{{units_consumed}}</td>\r\n                                    <!-- Bolded Unit Price -->\r\n                                    <td class=\"py-1.5 font-bold\">{{unit_price}}</td>\r\n                                </tr>\r\n                                <tr class=\"bg-blue-50/20\">\r\n                                    <td colspan=\"4\" class=\"py-1 font-bold text-blue-800 text-[11px]\">\r\n                                        <span class=\"uppercase text-[9px] tracking-wide text-blue-600 mr-2\">Calculation:</span>\r\n                                        {{energy_calculation}}\r\n                                    </td>\r\n                                </tr>\r\n                            </tbody>\r\n                        </table>\r\n                    </div>\r\n                </section>\r\n\r\n                <div class=\"flex border-b-2 border-blue-300\">\r\n                    <div class=\"flex-[3] border-r-2 border-blue-300\">\r\n                        <h3 class=\"bg-blue-100 px-2 py-1 text-[10px] font-black text-blue-800 border-l-4 border-blue-900 uppercase tracking-wide\">Ref. Meter Image</h3>\r\n                        <div class=\"p-1.5 bg-white flex justify-center h-32\">\r\n                            <div class=\"w-full bg-blue-50 border border-blue-200 flex items-center justify-center relative overflow-hidden h-full\">\r\n                                {{meter_image}}\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                    <div class=\"flex-[2]\">\r\n                        <h3 class=\"bg-red-600 px-2 py-1 text-[15px] font-bold text-white text-center urdu-font border-b border-red-400 uppercase\">نوٹس</h3>\r\n                        <div class=\"bg-red-50/10 flex flex-col items-center justify-center text-center p-2 h-32 overflow-hidden text-[11px]\">\r\n                             {{advertisement_mini}}\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n\r\n                <section class=\"flex-grow flex flex-col overflow-hidden bg-white\">\r\n                    <h3 class=\"bg-blue-900 px-2 py-1 text-[10px] font-bold text-white uppercase tracking-wide text-center\">Payment History (Last 12 Months)</h3>\r\n                    <div class=\"overflow-hidden flex-grow bg-white\">\r\n                        <table  class=\"w-full text-[9px] border-collapse h-full subm-history-table\">\r\n                            <thead class=\"bg-blue-50 text-blue-700 border-b-2 border-blue-800 uppercase font-bold\">\r\n                                <tr>\r\n                                    <th class=\"py-1 px-1 text-center border-r-2 border-blue-800\">Month</th>\r\n                                    <th class=\"py-1 px-1 text-center border-r-2 border-blue-800\">Units</th>\r\n                                    <th class=\"py-1 px-1 text-center border-r-2 border-blue-800\">Bill AMT</th>\r\n                                    <th class=\"py-1 px-1 text-center border-r-2 border-blue-800\">Paid AMT</th>\r\n                                    <th class=\"py-1 px-1 text-center border-r-2 border-blue-800\">Adj.</th>\r\n                                    <th class=\"py-1 px-1 text-center\">Status</th>\r\n                                </tr>\r\n                            </thead>\r\n                            <tbody class=\"text-slate-800 font-medium leading-none\">{{history_rows}}</tbody>\r\n                        </table>\r\n                    </div>\r\n                </section>\r\n            </div>\r\n\r\n            <!-- Right Column -->\r\n            <div class=\"flex-[5] flex flex-col\">\r\n                <h3 class=\"bg-blue-900 px-2 py-1 text-[10px] font-bold text-white uppercase tracking-wide text-center\">Current Charges</h3>\r\n                <div class=\"border-b-2 border-blue-300 shadow-sm bg-white\">\r\n                    <table class=\"w-full text-[10px] border-collapse charges-table\">\r\n                        <thead class=\"bg-blue-50 border-b-2 border-blue-300\">\r\n                            <tr>\r\n                                <th class=\"p-1 text-left text-blue-700 font-bold uppercase border-r-2 border-blue-300\">Description</th>\r\n                                <th class=\"p-1 text-right text-blue-700 font-bold uppercase\">Amount</th>\r\n                            </tr>\r\n                        </thead>\r\n                        <tbody class=\"divide-y-2 divide-blue-300\">\r\n                            {{utility_rows}}\r\n                            {{maintenance_rows}}\r\n                            {{other_rows}}                            \r\n                            <tr class=\"bg-blue-50 text-slate-900 font-bold border-t-2 border-blue-300\">\r\n                                <td class=\"p-1 border-r-2 border-blue-300 font-bold\">Arrears / Previous</td>\r\n                                <td class=\"p-1 text-right text-[11px]\">{{arrears}}</td>\r\n                            </tr>\r\n                            <tr class=\"bg-blue-900 text-white font-black border-t-2 border-blue-500\">\r\n                                <td class=\"p-1.5 text-xs border-r border-blue-700 uppercase tracking-wide font-black\">Payable Within Due</td>\r\n                                <td class=\"p-1.5 text-right text-[11px] leading-none\">{{total_amount}}</td>\r\n                            </tr>\r\n                            <tr class=\"bg-white text-red-600 font-bold border-t-2 border-blue-300\">\r\n                                <td class=\"p-1 text-[9px] border-r-2 border-blue-300 text-right uppercase font-bold\">Late Fee</td>\r\n                                <td class=\"p-1 text-right text-[11px]\">{{late_fee}}</td>\r\n                            </tr>\r\n                            <tr class=\"bg-red-600 text-white font-bold border-t-2 border-blue-300\">\r\n                                <td class=\"p-1 text-[9px] border-r-2 border-blue-300 text-right uppercase font-black\">Payable After Due</td>\r\n                                <td class=\"p-1 text-right text-[11px] font-black leading-none\">{{payable_after_due}}</td>\r\n                            </tr>\r\n                        </tbody>\r\n                    </table>\r\n                </div>\r\n\r\n                <div class=\"flex border-b-2 border-blue-300\">\r\n                    <div class=\"flex-[2] border-r-2 border-blue-300 bg-white p-2 shadow-sm text-[11px] font-medium leading-tight text-slate-600\">\r\n                        {{bank_details}}\r\n                    </div>\r\n                    \r\n                </div>\r\n\r\n                <div class=\"bg-blue-50/20 p-2 text-center urdu-font text-blue-900 leading-snug border-b-2 border-blue-300\">\r\n                    <p class=\"font-bold text-[11px]\">گھر سے باہر جاتے وقت دروازے اور کھڑکیاں اچھی طرح بند کریں، اور حفاظتی اقدامات ضرور اختیار کریں۔ قیمتی اشیاء جیسے زیورات و نقدی کو محفوظ لاکر یا محفوظ مقام پر رکھیں۔</p>\r\n                    <p class=\"font-bold text-[11px] mt-1 text-red-700\">لیٹ پیمنٹ کی صورت میں جرمانہ عائد کیا جائے گا۔</p>\r\n                </div>\r\n                <div class=\"flex-grow bg-white\"></div>\r\n            </div>\r\n        </div>\r\n\r\n        <!-- Separator -->\r\n        <div class=\"w-full py-1 relative\">\r\n            <div class=\"absolute top-1/2 left-0 w-full border-t-[2px] border-dashed border-blue-400\"></div>\r\n            <div class=\"absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 bg-white px-3 text-blue-500 text-[10px] font-bold flex items-center gap-2\">\r\n                <span class=\"text-base rotate-180\">✂</span> TEAR OFF HERE FOR RECORD <span class=\"text-base\">✂</span>\r\n            </div>\r\n        </div>\r\n\r\n        <!-- Duplicate Slip (Bank Copy) - Seamless Stretch (Text size increased by ~15%) -->\r\n        <div class=\"mt-4 bg-blue-50/20 border-t-4 border-blue-900 border-b-2 border-blue-300 p-2 shadow-inner\">\r\n            <div class=\"flex justify-between items-start border-b border-blue-300 pb-1 mb-1 px-2\">\r\n                <div class=\"flex items-center gap-2\">\r\n                    <div class=\"h-4 w-1 bg-yellow-600\"></div>\r\n                    <div>\r\n                        <h2 class=\"text-[12px] font-black text-blue-900 uppercase tracking-wide leading-none\">Bank Copy / Office Copy</h2>\r\n                        <p class=\"text-[8px] text-blue-600 font-bold uppercase tracking-wider leading-none\">{{society_name}}</p>\r\n                    </div>\r\n                </div>\r\n                <div class=\"text-right leading-none\">\r\n                    <p class=\"text-[9.5px] font-black text-blue-900 uppercase leading-none\">{{billing_month}}</p>\r\n                    <p class=\"text-[8px] text-blue-600 font-bold leading-none\">Billing Month</p>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"flex flex-col gap-1.5 px-2\">\r\n                <div class=\"grid grid-cols-4 gap-2 text-[12.5px]\">\r\n                    <div>\r\n                        <p class=\"text-blue-500 uppercase font-bold text-[7px]\">Bill No</p>\r\n                        <p class=\"font-black text-slate-900 text-[12.5px] border-b border-blue-300\">{{bill_no}}</p>\r\n                    </div>\r\n                    <div class=\"col-span-2\">\r\n                        <p class=\"text-blue-500 uppercase font-bold text-[7px]\">Consumer Name</p>\r\n                        <p class=\"font-black text-slate-900 text-[12.5px] border-b border-blue-300 truncate\">{{client_name}}</p>\r\n                    </div>\r\n                    <div>\r\n                        <p class=\"text-blue-500 uppercase font-bold text-[7px]\">Unit/Property</p>\r\n                        <p class=\"font-black text-slate-900 text-[12.5px] border-b border-blue-300\">{{property_id}}</p>\r\n                    </div>\r\n                </div>\r\n\r\n                <div class=\"grid grid-cols-4 gap-2 text-[12.5px]\">\r\n                    <div>\r\n                         <p class=\"text-blue-500 uppercase font-bold text-[7px]\">Payable (Within)</p>\r\n                         <p class=\"font-black text-slate-900 text-[12.5px] border-b border-blue-300\">{{total_amount}}</p>\r\n                    </div>\r\n                    <div>\r\n                        <p class=\"text-blue-500 uppercase font-bold text-[7px]\">Due Date</p>\r\n                        <p class=\"font-black text-red-600 text-[12.5px] border-b border-blue-300\">{{due_date}}</p>\r\n                    </div>\r\n                    <div>\r\n                         <p class=\"text-blue-500 uppercase font-bold text-[7px]\">Late Fee</p>\r\n                         <p class=\"font-black text-slate-900 text-[12.5px] border-b border-blue-300\">{{late_fee}}</p>\r\n                    </div>\r\n                    <div class=\"bg-red-600 text-white p-0.5 rounded-sm\">\r\n                        <p class=\"text-white uppercase font-bold text-[7px]\">Payable (After)</p>\r\n                         <p class=\"font-black text-white text-[12.5px] border-b border-red-400\">{{payable_after_due}}</p>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n\r\n        <!-- Footer Complaint & Contact Details -->\r\n        <div class=\"bg-blue-900 text-white p-1.5 border-t-[4px] border-blue-600 flex justify-between items-center text-[11px] mt-auto\">\r\n            <div class=\"font-black uppercase tracking-wider flex items-center gap-2 px-2\">\r\n                <span class=\"text-blue-400\">●</span> COMPLAINTS & SUPPORT: <span class=\"font-mono bg-white text-blue-900 px-1.5 py-0.5 rounded font-black\">{{society_mobile}}</span>\r\n            </div>\r\n            <div class=\"flex gap-4 items-center px-2\">\r\n                <div class=\"font-bold text-blue-200 lowercase tracking-tight\">\r\n                    {{society_email}}\r\n                </div>\r\n                <div class=\"font-medium text-blue-200 border-l border-blue-700 pl-3 uppercase text-[10px]\">\r\n                    HELPLINE: AVAILABLE 24/7 FOR RESIDENTS\r\n                </div>\r\n            </div>\r\n        </div>\r\n\r\n    </div>\r\n\r\n</body>\r\n</html>', '', 0, '2026-08-30 21:27:47'),
(16, 1, 'Paid', 'paid', 'full_paid', '<!DOCTYPE html>\r\n<html lang=\"en\">\r\n<head>\r\n    <meta charset=\"UTF-8\">\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n    <title>{{document_type}} - {{bill_no}}</title>\r\n    <!-- Tailwind CSS CDN -->\r\n    <script src=\"https://cdn.tailwindcss.com\"></script>\r\n    <style>\r\n        @import url(\'https://fonts.googleapis.com/css2?family=Inter:wght@300;400;600;700;800;900&display=swap\');\r\n        @import url(\'https://fonts.googleapis.com/css2?family=Noto+Nastaliq+Urdu:wght@400;700&display=swap\');\r\n        \r\n        body {\r\n            font-family: \'Inter\', sans-serif;\r\n            margin: 0;\r\n            padding: 0;\r\n        }\r\n\r\n        .urdu-font {\r\n            font-family: \'Noto Nastaliq Urdu\', serif;\r\n        }\r\n\r\n        /* Print Settings for Half A4 (Landscape fit) */\r\n        @media print {\r\n            @page {\r\n                size: 210mm 148.5mm;\r\n                margin: 0;\r\n            }\r\n            body {\r\n                background-color: white;\r\n            }\r\n            .no-print {\r\n                display: none !important;\r\n            }\r\n            .page-container {\r\n                box-shadow: none !important;\r\n                border: 3px solid #1e3a8a !important;\r\n                margin: 0 !important;\r\n                width: 210mm !important;\r\n                height: 148.5mm !important;\r\n                min-height: 148.5mm !important;\r\n                max-height: 148.5mm !important;\r\n            }\r\n        }\r\n\r\n        /* Screen Preview Settings for Half A4 */\r\n        .page-container {\r\n            width: 210mm;\r\n            height: 148.5mm;\r\n            background: white;\r\n            box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.25);\r\n            margin: 10px auto;\r\n        }\r\n    \r\n        /* subm-template-print-consistency */\r\n        @media print { body { -webkit-print-color-adjust: exact; print-color-adjust: exact; } }\r\n    </style>\r\n</head>\r\n<body class=\"bg-slate-200 min-h-screen flex flex-col items-center\">\r\n\r\n    <!-- Preview Caution notification -->\r\n    <div class=\"no-print w-full max-w-[215.9mm] mt-4\">\r\n        {{preview_caution}}\r\n    </div>\r\n\r\n    <!-- Print Button (Visible only on screen) -->\r\n    <div class=\"no-print my-4\">\r\n        <button onclick=\"window.print()\" class=\"bg-blue-900 text-white px-6 py-2 rounded-lg font-bold flex items-center gap-2 hover:bg-blue-800 transition-all shadow-xl\">\r\n            <svg xmlns=\"http://www.w3.org/2003/svg\" width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"6 9 6 2 18 2 18 9\"></polyline><path d=\"M6 18H4a2 2 0 0 1-2-2v-5a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2v5a2 2 0 0 1-2 2h-2\"></path><rect x=\"6\" y=\"14\" width=\"12\" height=\"8\"></rect></svg>\r\n            Print {{template_type}}\r\n        </button>\r\n    </div>\r\n\r\n    <!-- Receipt Document Container -->\r\n    <div class=\"page-container flex flex-col border-[3px] border-blue-900 relative box-border text-slate-900 overflow-hidden\">\r\n        \r\n        <!-- Header Section - Tightened Padding -->\r\n        <div class=\"bg-white py-1.5 px-4 flex items-center border-b-[3px] border-blue-900 relative\">\r\n            <div class=\"w-1/4\">\r\n                <img src=\"{{society_logo}}\" alt=\"Logo\" class=\"h-8 w-auto object-contain rounded-md\">\r\n            </div>\r\n            <div class=\"w-2/4 text-center\">\r\n                <h1 class=\"text-[18px] font-black uppercase tracking-tight text-blue-900 leading-none\">{{society_name}}</h1>\r\n                <p class=\"text-[8px] font-medium text-slate-500 mt-0.5 leading-tight\">{{society_address}}</p>\r\n                <div class=\"text-[9px] font-bold text-green-600 mt-0.5 uppercase tracking-wide\">\r\n                    Mobile: {{society_mobile}}\r\n                </div>\r\n            </div>\r\n            <div class=\"w-1/4 flex justify-end\">\r\n                <span class=\"bg-[#1a8a5a] text-white px-2 py-1 rounded-sm text-[8px] uppercase tracking-widest font-black shadow-md\">{{document_type}}</span>\r\n            </div>\r\n        </div>\r\n\r\n        <!-- Quick Info Bar -->\r\n        <div class=\"grid grid-cols-6 border-b-2 border-blue-200 text-center text-[8px] divide-x-2 divide-blue-200 bg-white\">\r\n            <div class=\"flex flex-col\"><div class=\"py-0.5 bg-blue-50 font-bold text-blue-800 uppercase border-b border-blue-100\">Receipt No</div><div class=\"py-1 font-bold\">{{bill_no}}</div></div>\r\n            <div class=\"flex flex-col\"><div class=\"py-0.5 bg-blue-50 font-bold text-blue-800 uppercase border-b border-blue-100\">Date</div><div class=\"py-1 font-bold\">{{issue_date}}</div></div>\r\n            <div class=\"flex flex-col\"><div class=\"py-0.5 bg-blue-50 font-bold text-blue-800 uppercase border-b border-blue-100\">Consumer ID</div><div class=\"py-1 font-bold\">{{consumer_id}}</div></div>\r\n            <div class=\"flex flex-col\"><div class=\"py-0.5 bg-blue-50 font-bold text-blue-800 uppercase border-b border-blue-100\">Property</div><div class=\"py-1 font-bold\">{{property_id}}</div></div>\r\n            <div class=\"flex flex-col\"><div class=\"py-0.5 bg-blue-50 font-bold text-blue-800 uppercase border-b border-blue-100\">Bill Month</div><div class=\"py-1 font-bold uppercase\">{{billing_month}}</div></div>\r\n            <div class=\"flex flex-col\"><div class=\"py-0.5 bg-blue-50 font-bold text-blue-800 uppercase border-b border-blue-100\">Status</div><div class=\"py-1 font-black text-green-700 italic uppercase\">{{payment_status}}</div></div>\r\n        </div>\r\n\r\n        <!-- Main Body Content -->\r\n        <div class=\"flex flex-grow overflow-hidden relative\">\r\n            \r\n            <!-- PAID Stamp Overlay -->\r\n            <div class=\"absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 opacity-[0.25] pointer-events-none z-50 mix-blend-multiply flex items-center justify-center\">\r\n                <svg width=\"180\" height=\"180\" viewBox=\"0 0 300 300\" xmlns=\"http://www.w3.org/2000/svg\">\r\n                    <defs>\r\n                        <path id=\"arc-top\" d=\"M 38,150 A 112,112 0 0,1 262,150\" fill=\"none\" />\r\n                        <path id=\"arc-bot\" d=\"M 38,150 A 112,112 0 0,0 262,150\" fill=\"none\" />\r\n                    </defs>\r\n                    <circle cx=\"150\" cy=\"150\" r=\"142\" fill=\"none\" stroke=\"#15803d\" stroke-width=\"5\"/>\r\n                    <circle cx=\"150\" cy=\"150\" r=\"134\" fill=\"none\" stroke=\"#15803d\" stroke-width=\"2\"/>\r\n                    <circle cx=\"150\" cy=\"150\" r=\"90\" fill=\"none\" stroke=\"#15803d\" stroke-width=\"2\"/>\r\n                    <text fill=\"#15803d\" font-size=\"32\" font-weight=\"900\" font-family=\"Arial Black, Impact, sans-serif\" letter-spacing=\"3\" dominant-baseline=\"central\">\r\n                        <textPath href=\"#arc-top\" startOffset=\"50%\" text-anchor=\"middle\">THANK YOU</textPath>\r\n                    </text>\r\n                    <text fill=\"#15803d\" font-size=\"32\" font-weight=\"900\" font-family=\"Arial Black, Impact, sans-serif\" letter-spacing=\"3\" dominant-baseline=\"central\">\r\n                        <textPath href=\"#arc-bot\" startOffset=\"50%\" text-anchor=\"middle\">THANK YOU</textPath>\r\n                    </text>\r\n                    <text x=\"22\" y=\"161\" fill=\"#15803d\" font-size=\"28\" text-anchor=\"middle\">★</text>\r\n                    <text x=\"278\" y=\"161\" fill=\"#15803d\" font-size=\"28\" text-anchor=\"middle\">★</text>\r\n                    <text x=\"150\" y=\"115\" fill=\"#15803d\" font-size=\"18\" font-weight=\"bold\" font-family=\"Arial, sans-serif\" text-anchor=\"middle\" letter-spacing=\"4\">PAID</text>\r\n                    <text x=\"150\" y=\"196\" fill=\"#15803d\" font-size=\"18\" font-weight=\"bold\" font-family=\"Arial, sans-serif\" text-anchor=\"middle\" letter-spacing=\"4\">PAID</text>\r\n                    <g transform=\"rotate(-15 150 150)\">\r\n                        <rect x=\"5\" y=\"105\" width=\"290\" height=\"90\" rx=\"10\" fill=\"#15803d\" />\r\n                        <rect x=\"12\" y=\"112\" width=\"276\" height=\"76\" rx=\"6\" fill=\"none\" stroke=\"#ffffff\" stroke-width=\"2\" stroke-dasharray=\"4 3\"/>\r\n                        <text x=\"150\" y=\"176\" fill=\"#ffffff\" font-size=\"74\" font-weight=\"900\" font-family=\"Arial Black, Impact, sans-serif\" text-anchor=\"middle\" letter-spacing=\"4\">PAID</text>\r\n                        <text x=\"45\" y=\"166\" fill=\"#ffffff\" font-size=\"30\" text-anchor=\"middle\">★</text>\r\n                        <text x=\"255\" y=\"166\" fill=\"#ffffff\" font-size=\"30\" text-anchor=\"middle\">★</text>\r\n                    </g>\r\n                </svg>\r\n            </div>\r\n\r\n            <!-- Left Panel (7/12) -->\r\n            <div class=\"flex-[7] flex flex-col border-r-2 border-blue-900 z-10\">\r\n                <!-- Payer Info Section - Compact -->\r\n                <section class=\"p-2 px-4 bg-slate-50/10\">\r\n                    <h3 class=\"text-[8px] font-bold text-blue-800 uppercase tracking-wider mb-0.5\">Payer Information</h3>\r\n                    <p class=\"text-[12px] font-black uppercase text-slate-900\">{{client_name}}</p>\r\n                    <p class=\"text-[8px] font-bold text-blue-700 mb-0.5\">REGISTERED RESIDENT / OWNER</p>\r\n                    <p class=\"text-[9px] text-slate-600 font-medium max-w-sm leading-tight\">{{client_address}}</p>\r\n                </section>\r\n\r\n                <!-- Detailed Transaction Summary -->\r\n                <section class=\"border-t-2 border-b-2 border-blue-200\">\r\n                    <div class=\"bg-blue-50/50 px-3 py-0.5 text-[8px] font-black uppercase text-slate-800\">Summary of Totals</div>\r\n                    <table class=\"w-full text-[9px] text-center border-collapse\">\r\n                        <thead class=\"bg-white text-slate-500 uppercase font-bold text-[7px] border-b\">\r\n                            <tr>\r\n                                <th class=\"py-1 px-1 border-r\">Previous Arrears</th>\r\n                                <th class=\"py-1 px-1 border-r\">Current Charges</th>\r\n                                <th class=\"py-1 px-1 border-r\">Late Fee ({{late_fee_percent}}%)</th>\r\n                                <th class=\"py-1 px-1\">Total Payable</th>\r\n                            </tr>\r\n                        </thead>\r\n                        <tbody class=\"font-black text-slate-900\">\r\n                            <tr>\r\n                                <td class=\"py-1.5 border-r border-slate-100\">{{arrears}}</td>\r\n                                <td class=\"py-1.5 border-r border-slate-100\">{{total_amount}}</td>\r\n                                <td class=\"py-1.5 border-r border-slate-100 text-red-500\">{{late_fee}}</td>\r\n                                <td class=\"py-1.5 bg-blue-50/30 text-blue-900 text-[10px] font-black\">{{payable_after_due}}</td>\r\n                            </tr>\r\n                        </tbody>\r\n                    </table>\r\n                </section>\r\n\r\n                <!-- Itemized Billing Section (Maintenance & Other Charges) - Compacted -->\r\n                <section class=\"bg-white flex flex-col\">\r\n                    <div class=\"bg-slate-50 px-3 py-0.5 text-[8px] font-bold uppercase text-slate-600 border-b\">Itemized Billing Details</div>\r\n                    <div class=\"overflow-hidden\">\r\n                        <table class=\"w-full text-[8px] text-left border-collapse\">\r\n                            <thead class=\"text-slate-400 uppercase font-bold border-b text-[7px]\">\r\n                                <tr>\r\n                                    <th class=\"py-0.5 px-3\">Description</th>\r\n                                    <th class=\"py-0.5 px-3 text-right\">Amount</th>\r\n                                </tr>\r\n                            </thead>\r\n                            <tbody class=\"divide-y divide-slate-100\">\r\n                                {{maintenance_rows}}                   \r\n                                {{other_rows}}\r\n                            </tbody>\r\n                        </table>\r\n                    </div>\r\n                    <!-- Adjustment note section -->\r\n                    <div class=\"p-1 border-t border-slate-50\">\r\n                        <p class=\"text-[7px] text-slate-400 italic font-medium leading-tight\">{{adjustment_note}}</p>\r\n                    </div>\r\n                </section>\r\n\r\n                <!-- History Summary - Compacted to avoid Letter height overflow -->\r\n                <section class=\"bg-white border-t-2 border-blue-200\">\r\n                    <div class=\"bg-blue-900 text-white text-[8px] font-bold uppercase text-center py-0.5 tracking-widest\">Previous 6 Months Payment Summary</div>\r\n                    <table class=\"w-full text-[7px] text-center border-collapse\">\r\n                        <thead class=\"bg-slate-50 font-bold uppercase border-b border-slate-200\">\r\n                            <tr>\r\n                                <th class=\"py-0.5 border-r\">Billing Month</th>\r\n                                <th class=\"py-0.5 border-r\">Bill Amount</th>\r\n                                <th class=\"py-0.5 border-r\">Amount Paid</th>\r\n                                <th class=\"py-0.5\">Status</th>\r\n                            </tr>\r\n                        </thead>\r\n                        <tbody class=\"text-slate-600 divide-y divide-slate-50\">\r\n                            {{history_rows}}\r\n                        </tbody>\r\n                    </table>\r\n                </section>\r\n\r\n                <!-- Filler to push empty space to the bottom -->\r\n                <div class=\"flex-grow bg-white\"></div>\r\n            </div>\r\n\r\n            <!-- Right Column (5/12) -->\r\n            <div class=\"flex-[5] flex flex-col bg-slate-50/10 z-10\">\r\n                <!-- Final Settlement Title -->\r\n                <div class=\"bg-blue-900 text-white py-1 text-center text-[8px] font-black uppercase tracking-widest\">Final Settlement</div>\r\n                \r\n                <!-- Breakdown -->\r\n                <table class=\"w-full text-[10px] border-collapse bg-white\">\r\n                    <tbody class=\"divide-y divide-slate-100 font-bold text-slate-500\">\r\n                        <tr>\r\n                            <td class=\"p-1.5 px-4 text-[10px]\">Total Bill</td>\r\n                            <td class=\"p-1.5 px-4 text-right text-slate-900 text-[11px]\">{{total_amount}}</td>\r\n                        </tr>\r\n                        <tr>\r\n                            <td class=\"p-1.5 px-4 text-[10px]\">Surcharge</td>\r\n                            <td class=\"p-1.5 px-4 text-right text-red-500 text-[11px]\">{{late_fee}}</td>\r\n                        </tr>\r\n                        <!-- Total Amount Paid Box - Optimized padding -->\r\n                        <tr class=\"bg-blue-900 text-white border-t-2 border-blue-950\">\r\n                            <td class=\"p-2 px-4 font-black uppercase text-[9px] leading-tight\">Total Amount<br>Paid</td>\r\n                            <td class=\"p-2 px-4 text-right text-[18px] font-black tracking-tighter\">{{paid_amount}}</td>\r\n                        </tr>\r\n                        <!-- Adjustments row -->\r\n                        <tr class=\"bg-slate-50\">\r\n                            <td class=\"p-1.5 px-4 text-[8px] font-bold text-slate-500\">\r\n                                Adj: ({{adjustment_credit}} / {{adjustment_debit}})\r\n                            </td>\r\n                            <td class=\"p-1.5 px-4 text-right font-black text-slate-500 text-[9px] italic\">\r\n                                Bal: {{pending_amount}}\r\n                            </td>\r\n                        </tr>\r\n                    </tbody>\r\n                </table>\r\n\r\n                <!-- Confirmation Stamp - Scaled down -->\r\n                <div class=\"flex-grow flex flex-col items-center justify-center p-2 text-center bg-white border-y border-slate-100\">\r\n                    <div class=\"w-10 h-10 bg-green-50 rounded-full flex items-center justify-center text-[#1a8a5a] mb-1 border-2 border-green-100 shadow-sm\">\r\n                        <svg xmlns=\"http://www.w3.org/2003/svg\" width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"4\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"></polyline></svg>\r\n                    </div>\r\n                    <p class=\"text-[11px] font-black text-[#1a8a5a] uppercase tracking-[0.2em] leading-none mb-0.5\">Confirmed</p>\r\n                    <p class=\"text-[7px] text-slate-400 font-bold uppercase tracking-widest\">Office Copy Ref: {{payment_ref}}</p>\r\n                </div>\r\n\r\n                <!-- Urdu Payment and Society Message - Compacted padding -->\r\n                <div class=\"p-2 px-4 text-center urdu-font bg-blue-50/30 border-b border-slate-200\">\r\n                    <p class=\"text-[10px] font-bold text-blue-900 leading-snug\">آپ کی ادائیگی کامیابی کے ساتھ موصول ہوگئی ہے۔ شکریہ!</p>\r\n                    <p class=\"text-[8px] font-bold text-green-700 mt-1 leading-snug\">سوسائٹی کو صاف ستھرا اور خوبصورت رکھنے میں ہمارا ساتھ دیں۔</p>\r\n                </div>\r\n\r\n                <!-- Authorized Signature - Compacted -->\r\n                <div class=\"bg-white p-3 mt-auto text-center\">\r\n                    <div class=\"border-t border-slate-300 w-24 mx-auto mb-1\"></div>\r\n                    <p class=\"text-[7px] font-black uppercase tracking-[0.2em] text-slate-400\">Authorized Signature</p>\r\n                </div>\r\n            </div>\r\n        </div>\r\n\r\n        <!-- Footer - Optimized -->\r\n        <div class=\"bg-blue-900 text-white p-1.5 border-t-2 border-blue-400 flex justify-between items-center text-[8px] mt-auto\">\r\n            <div class=\"px-4 font-black uppercase tracking-widest\">Support: {{society_mobile}}</div>\r\n            <div class=\"px-4 flex gap-4 items-center\">\r\n                <span class=\"font-bold text-blue-200\">{{society_email}}</span>\r\n                <span class=\"font-black text-blue-300 border-l border-blue-700 pl-4 uppercase tracking-tighter italic opacity-80\">\r\n                    Verified Digital Record\r\n                </span>\r\n            </div>\r\n        </div>\r\n    </div>\r\n\r\n</body>\r\n</html>', '', 1, '2026-08-30 21:27:47');
INSERT INTO `billing_templates` (`id`, `society_id`, `name`, `slug`, `template_type`, `html_content`, `css_content`, `is_default`, `created_at`) VALUES
(17, 1, 'Full Paid', 'full-paid', 'full_paid', '<!DOCTYPE html>\r\n<html lang=\"en\">\r\n<head>\r\n    <meta charset=\"UTF-8\">\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n    <title>{{document_type}} - {{bill_no}}</title>\r\n    <!-- Tailwind CSS CDN -->\r\n    <script src=\"https://cdn.tailwindcss.com\"></script>\r\n    <style>\r\n        @import url(\'https://fonts.googleapis.com/css2?family=Inter:wght@300;400;600;700;800;900&display=swap\');\r\n        @import url(\'https://fonts.googleapis.com/css2?family=Noto+Nastaliq+Urdu:wght@400;700&display=swap\');\r\n        \r\n        body {\r\n            font-family: \'Inter\', sans-serif;\r\n            margin: 0;\r\n            padding: 0;\r\n        }\r\n\r\n        .urdu-font {\r\n            font-family: \'Noto Nastaliq Urdu\', serif;\r\n        }\r\n\r\n        /* Print Settings for US Letter */\r\n        @media print {\r\n            @page {\r\n                size: letter;\r\n                margin: 0;\r\n            }\r\n            body {\r\n                background-color: white;\r\n            }\r\n            .no-print {\r\n                display: none !important;\r\n            }\r\n            .page-container {\r\n                box-shadow: none !important;\r\n                border: 4px solid #1e3a8a !important;\r\n                margin: 0 !important;\r\n                width: 215.9mm !important;\r\n                height: 279.4mm !important;\r\n                min-height: 279.4mm !important;\r\n                max-height: 279.4mm !important;\r\n            }\r\n        }\r\n\r\n        /* Screen Preview Settings for US Letter */\r\n        .page-container {\r\n            width: 215.9mm;\r\n            height: 279.4mm;\r\n            background: white;\r\n            box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.25);\r\n            margin: 10px auto;\r\n        }\r\n    \r\n        /* subm-template-print-consistency */\r\n        @media print { body { -webkit-print-color-adjust: exact; print-color-adjust: exact; } }\r\n    </style>\r\n</head>\r\n<body class=\"bg-slate-200 min-h-screen flex flex-col items-center\">\r\n\r\n    <!-- Preview Caution notification -->\r\n    <div class=\"no-print w-full max-w-[215.9mm] mt-4\">\r\n       \r\n    </div>\r\n\r\n    <!-- Print Button (Visible only on screen) -->\r\n    <div class=\"no-print my-4\">\r\n        <button onclick=\"window.print()\" class=\"bg-blue-900 text-white px-6 py-2 rounded-lg font-bold flex items-center gap-2 hover:bg-blue-800 transition-all shadow-xl\">\r\n            <svg xmlns=\"http://www.w3.org/2003/svg\" width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"6 9 6 2 18 2 18 9\"></polyline><path d=\"M6 18H4a2 2 0 0 1-2-2v-5a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2v5a2 2 0 0 1-2 2h-2\"></path><rect x=\"6\" y=\"14\" width=\"12\" height=\"8\"></rect></svg>\r\n            Print {{template_type}}\r\n        </button>\r\n    </div>\r\n\r\n    <!-- Receipt Document Container -->\r\n    <div class=\"page-container flex flex-col border-[4px] border-blue-900 relative box-border text-slate-900 overflow-hidden\">\r\n        \r\n        <!-- Header Section - Tightened Padding -->\r\n        <div class=\"bg-white py-3 px-8 flex items-center border-b-4 border-blue-900 relative\">\r\n            <div class=\"w-1/4\">\r\n                <img src=\"{{society_logo}}\" alt=\"Logo\" class=\"h-14 w-auto object-contain rounded-md\">\r\n            </div>\r\n            <div class=\"w-2/4 text-center\">\r\n                <h1 class=\"text-[26px] font-black uppercase tracking-tight text-blue-900 leading-none\">{{society_name}}</h1>\r\n                <p class=\"text-[10px] font-medium text-slate-500 mt-1 leading-tight\">{{society_address}}</p>\r\n                <div class=\"text-[12px] font-bold text-green-600 mt-0.5 uppercase tracking-wide\">\r\n                    Mobile: {{society_mobile}}\r\n                </div>\r\n            </div>\r\n            <div class=\"w-1/4 flex justify-end\">\r\n                <span class=\"bg-[#1a8a5a] text-white px-4 py-1.5 rounded-sm text-[11px] uppercase tracking-widest font-black shadow-md\">{{document_type}}</span>\r\n            </div>\r\n        </div>\r\n\r\n        <!-- Quick Info Bar -->\r\n        <div class=\"grid grid-cols-6 border-b-2 border-blue-200 text-center text-[9px] divide-x-2 divide-blue-200 bg-white\">\r\n            <div class=\"flex flex-col\"><div class=\"py-0.5 bg-blue-50 font-bold text-blue-800 uppercase border-b border-blue-100\">Receipt No</div><div class=\"py-1.5 font-bold\">{{bill_no}}</div></div>\r\n            <div class=\"flex flex-col\"><div class=\"py-0.5 bg-blue-50 font-bold text-blue-800 uppercase border-b border-blue-100\">Date</div><div class=\"py-1.5 font-bold\">{{issue_date}}</div></div>\r\n            <div class=\"flex flex-col\"><div class=\"py-0.5 bg-blue-50 font-bold text-blue-800 uppercase border-b border-blue-100\">Consumer ID</div><div class=\"py-1.5 font-bold\">{{consumer_id}}</div></div>\r\n            <div class=\"flex flex-col\"><div class=\"py-0.5 bg-blue-50 font-bold text-blue-800 uppercase border-b border-blue-100\">Property</div><div class=\"py-1.5 font-bold\">{{property_id}}</div></div>\r\n            <div class=\"flex flex-col\"><div class=\"py-0.5 bg-blue-50 font-bold text-blue-800 uppercase border-b border-blue-100\">Bill Month</div><div class=\"py-1.5 font-bold uppercase\">{{billing_month}}</div></div>\r\n            <div class=\"flex flex-col\"><div class=\"py-0.5 bg-blue-50 font-bold text-blue-800 uppercase border-b border-blue-100\">Status</div><div class=\"py-1.5 font-black text-green-700 italic uppercase\">{{payment_status}}</div></div>\r\n        </div>\r\n\r\n        <!-- Main Body Content -->\r\n        <div class=\"flex flex-grow overflow-hidden relative\">\r\n            \r\n            <!-- PAID Stamp Overlay -->\r\n            <div class=\"absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 opacity-[0.25] pointer-events-none z-50 mix-blend-multiply flex items-center justify-center\">\r\n                <svg width=\"280\" height=\"280\" viewBox=\"0 0 300 300\" xmlns=\"http://www.w3.org/2000/svg\">\r\n                    <defs>\r\n                        <path id=\"arc-top\" d=\"M 38,150 A 112,112 0 0,1 262,150\" fill=\"none\" />\r\n                        <path id=\"arc-bot\" d=\"M 38,150 A 112,112 0 0,0 262,150\" fill=\"none\" />\r\n                    </defs>\r\n\r\n                    <!-- Outer Rings -->\r\n                    <circle cx=\"150\" cy=\"150\" r=\"142\" fill=\"none\" stroke=\"#15803d\" stroke-width=\"5\"/>\r\n                    <circle cx=\"150\" cy=\"150\" r=\"134\" fill=\"none\" stroke=\"#15803d\" stroke-width=\"2\"/>\r\n                    \r\n                    <!-- Inner Ring -->\r\n                    <circle cx=\"150\" cy=\"150\" r=\"90\" fill=\"none\" stroke=\"#15803d\" stroke-width=\"2\"/>\r\n\r\n                    <!-- Circular Text -->\r\n                    <text fill=\"#15803d\" font-size=\"32\" font-weight=\"900\" font-family=\"Arial Black, Impact, sans-serif\" letter-spacing=\"3\" dominant-baseline=\"central\">\r\n                        <textPath href=\"#arc-top\" startOffset=\"50%\" text-anchor=\"middle\">THANK YOU</textPath>\r\n                    </text>\r\n                    <text fill=\"#15803d\" font-size=\"32\" font-weight=\"900\" font-family=\"Arial Black, Impact, sans-serif\" letter-spacing=\"3\" dominant-baseline=\"central\">\r\n                        <textPath href=\"#arc-bot\" startOffset=\"50%\" text-anchor=\"middle\">THANK YOU</textPath>\r\n                    </text>\r\n\r\n                    <!-- Outer Stars -->\r\n                    <text x=\"22\" y=\"161\" fill=\"#15803d\" font-size=\"28\" text-anchor=\"middle\">★</text>\r\n                    <text x=\"278\" y=\"161\" fill=\"#15803d\" font-size=\"28\" text-anchor=\"middle\">★</text>\r\n\r\n                    <!-- Inner Top/Bottom PAID text -->\r\n                    <text x=\"150\" y=\"115\" fill=\"#15803d\" font-size=\"18\" font-weight=\"bold\" font-family=\"Arial, sans-serif\" text-anchor=\"middle\" letter-spacing=\"4\">PAID</text>\r\n                    <text x=\"150\" y=\"196\" fill=\"#15803d\" font-size=\"18\" font-weight=\"bold\" font-family=\"Arial, sans-serif\" text-anchor=\"middle\" letter-spacing=\"4\">PAID</text>\r\n\r\n                    <!-- Center Banner Group -->\r\n                    <g transform=\"rotate(-15 150 150)\">\r\n                        <!-- Banner Background -->\r\n                        <rect x=\"5\" y=\"105\" width=\"290\" height=\"90\" rx=\"10\" fill=\"#15803d\" />\r\n                        <!-- Inner dotted border for banner -->\r\n                        <rect x=\"12\" y=\"112\" width=\"276\" height=\"76\" rx=\"6\" fill=\"none\" stroke=\"#ffffff\" stroke-width=\"2\" stroke-dasharray=\"4 3\"/>\r\n                        \r\n                        <!-- Banner Text -->\r\n                        <text x=\"150\" y=\"176\" fill=\"#ffffff\" font-size=\"74\" font-weight=\"900\" font-family=\"Arial Black, Impact, sans-serif\" text-anchor=\"middle\" letter-spacing=\"4\">PAID</text>\r\n                        \r\n                        <!-- Banner Stars -->\r\n                        <text x=\"45\" y=\"166\" fill=\"#ffffff\" font-size=\"30\" text-anchor=\"middle\">★</text>\r\n                        <text x=\"255\" y=\"166\" fill=\"#ffffff\" font-size=\"30\" text-anchor=\"middle\">★</text>\r\n                    </g>\r\n                </svg>\r\n            </div>\r\n\r\n            <!-- Left Panel (7/12) -->\r\n            <div class=\"flex-[7] flex flex-col border-r-2 border-blue-900 z-10\">\r\n                <!-- Payer Info Section - Compact -->\r\n                <section class=\"p-4 px-6 bg-slate-50/10\">\r\n                    <h3 class=\"text-[9px] font-bold text-blue-800 uppercase tracking-wider mb-1\">Payer Information</h3>\r\n                    <p class=\"text-[16px] font-black uppercase text-slate-900\">{{client_name}}</p>\r\n                    <p class=\"text-[10px] font-bold text-blue-700 mb-0.5\">REGISTERED RESIDENT / OWNER</p>\r\n                    <p class=\"text-[11px] text-slate-600 font-medium max-w-sm leading-tight\">{{client_address}}</p>\r\n                </section>\r\n\r\n                <!-- Detailed Transaction Summary -->\r\n                <section class=\"border-t-2 border-b-2 border-blue-200\">\r\n                    <div class=\"bg-blue-50/50 px-4 py-1 text-[9px] font-black uppercase text-slate-800\">Summary of Totals</div>\r\n                    <table class=\"w-full text-[10px] text-center border-collapse\">\r\n                        <thead class=\"bg-white text-slate-500 uppercase font-bold text-[8px] border-b\">\r\n                            <tr>\r\n                                <th class=\"py-2 px-1 border-r\">Previous Arrears</th>\r\n                                <th class=\"py-2 px-1 border-r\">Current Charges</th>\r\n                                <th class=\"py-2 px-1 border-r\">Late Fee ({{late_fee_percent}}%)</th>\r\n                                <th class=\"py-3 px-1\">Total Payable</th>\r\n                            </tr>\r\n                        </thead>\r\n                        <tbody class=\"font-black text-slate-900\">\r\n                            <tr>\r\n                                <td class=\"py-3 border-r border-slate-100\">{{arrears}}</td>\r\n                                <td class=\"py-3 border-r border-slate-100\">{{total_amount}}</td>\r\n                                <td class=\"py-3 border-r border-slate-100 text-red-500\">{{late_fee}}</td>\r\n                                <td class=\"py-3 bg-blue-50/30 text-blue-900 text-sm font-black\">{{payable_after_due}}</td>\r\n                            </tr>\r\n                        </tbody>\r\n                    </table>\r\n                </section>\r\n\r\n                <!-- Itemized Billing Section (Maintenance & Other Charges) - Compacted -->\r\n                <section class=\"bg-white flex flex-col\">\r\n                    <div class=\"bg-slate-50 px-4 py-0.5 text-[9px] font-bold uppercase text-slate-600 border-b\">Itemized Billing Details</div>\r\n                    <div class=\"overflow-hidden\">\r\n                        <table class=\"w-full text-[9px] text-left border-collapse\">\r\n                            <thead class=\"text-slate-400 uppercase font-bold border-b text-[8px]\">\r\n                                <tr>\r\n                                    <th class=\"py-1 px-4\">Description</th>\r\n                                    <th class=\"py-1 px-4 text-right\">Amount</th>\r\n                                </tr>\r\n                            </thead>\r\n                            <tbody class=\"divide-y divide-slate-100\">\r\n                                {{maintenance_rows}}                   \r\n                                {{other_rows}}\r\n                            </tbody>\r\n                        </table>\r\n                    </div>\r\n                    <!-- Adjustment note section -->\r\n                    <div class=\"p-2 border-t border-slate-50\">\r\n                        <p class=\"text-[8px] text-slate-400 italic font-medium leading-tight\">{{adjustment_note}}</p>\r\n                    </div>\r\n                </section>\r\n\r\n                <!-- History Summary - Compacted to avoid Letter height overflow -->\r\n                <section class=\"bg-white border-t-2 border-blue-200\">\r\n                    <div class=\"bg-blue-900 text-white text-[9px] font-bold uppercase text-center py-1 tracking-widest\">Previous 12 Months Payment Summary</div>\r\n                    <table class=\"w-full text-[8px] text-center border-collapse\">\r\n                        <thead class=\"bg-slate-50 font-bold uppercase border-b border-slate-200\">\r\n                            <tr>\r\n                                <th class=\"py-1 border-r\">Billing Month</th>\r\n                                <th class=\"py-1 border-r\">Bill Amount</th>\r\n                                <th class=\"py-1 border-r\">Amount Paid</th>\r\n                                <th class=\"py-1\">Status</th>\r\n                            </tr>\r\n                        </thead>\r\n                        <tbody class=\"text-slate-600 divide-y divide-slate-50\">\r\n                            {{history_rows}}\r\n                        </tbody>\r\n                    </table>\r\n                </section>\r\n\r\n                <!-- Filler to push empty space to the bottom -->\r\n                <div class=\"flex-grow bg-white\"></div>\r\n            </div>\r\n\r\n            <!-- Right Column (5/12) -->\r\n            <div class=\"flex-[5] flex flex-col bg-slate-50/10 z-10\">\r\n                <!-- Final Settlement Title -->\r\n                <div class=\"bg-blue-900 text-white py-2 text-center text-[10px] font-black uppercase tracking-widest\">Final Settlement</div>\r\n                \r\n                <!-- Breakdown -->\r\n                <table class=\"w-full text-[12px] border-collapse bg-white\">\r\n                    <tbody class=\"divide-y divide-slate-100 font-bold text-slate-500\">\r\n                        <tr>\r\n                            <td class=\"p-3 px-6 text-[13px]\">Total Bill</td>\r\n                            <td class=\"p-3 px-6 text-right text-slate-900 text-[14px]\">{{total_amount}}</td>\r\n                        </tr>\r\n                        <tr>\r\n                            <td class=\"p-3 px-6 text-[13px]\">Surcharge</td>\r\n                            <td class=\"p-3 px-6 text-right text-red-500 text-[14px]\">{{late_fee}}</td>\r\n                        </tr>\r\n                        <!-- Total Amount Paid Box - Optimized padding -->\r\n                        <tr class=\"bg-blue-900 text-white border-t-2 border-blue-950\">\r\n                            <td class=\"p-4 px-6 font-black uppercase text-[11px] leading-tight\">Total Amount<br>Paid</td>\r\n                            <td class=\"p-4 px-6 text-right text-[28px] font-black tracking-tighter\">{{paid_amount}}</td>\r\n                        </tr>\r\n                        <!-- Adjustments row -->\r\n                        <tr class=\"bg-slate-50\">\r\n                            <td class=\"p-2.5 px-6 text-[9px] font-bold text-slate-500\">\r\n                                Adj: ({{adjustment_credit}} / {{adjustment_debit}})\r\n                            </td>\r\n                            <td class=\"p-2.5 px-6 text-right font-black text-slate-500 text-[11px] italic\">\r\n                                Bal: {{pending_amount}}\r\n                            </td>\r\n                        </tr>\r\n                    </tbody>\r\n                </table>\r\n\r\n                <!-- Confirmation Stamp - Scaled down -->\r\n                <div class=\"flex-grow flex flex-col items-center justify-center p-4 text-center bg-white border-y border-slate-100\">\r\n                    <div class=\"w-16 h-16 bg-green-50 rounded-full flex items-center justify-center text-[#1a8a5a] mb-2 border-2 border-green-100 shadow-sm\">\r\n                        <svg xmlns=\"http://www.w3.org/2003/svg\" width=\"36\" height=\"36\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"4\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"></polyline></svg>\r\n                    </div>\r\n                    <p class=\"text-[14px] font-black text-[#1a8a5a] uppercase tracking-[0.2em] leading-none mb-1\">Confirmed</p>\r\n                    <p class=\"text-[8px] text-slate-400 font-bold uppercase tracking-widest\">Office Copy Ref: {{payment_ref}}</p>\r\n                </div>\r\n\r\n                <!-- Urdu Payment and Society Message - Compacted padding -->\r\n                <div class=\"p-4 px-6 text-center urdu-font bg-blue-50/30 border-b border-slate-200\">\r\n                    <p class=\"text-[13px] font-bold text-blue-900 leading-snug\">آپ کی ادائیگی کامیابی کے ساتھ موصول ہوگئی ہے۔ شکریہ!</p>\r\n                    <p class=\"text-[10px] font-bold text-green-700 mt-1.5 leading-snug\">سوسائٹی کو صاف ستھرا اور خوبصورت رکھنے میں ہمارا ساتھ دیں۔</p>\r\n                </div>\r\n\r\n                <!-- Footer Advertisement/Message -->\r\n                <div class=\"p-4 text-center urdu-font bg-slate-50 text-[13px] font-bold text-blue-900 leading-relaxed border-b border-slate-200\">\r\n                    {{advertisement}}\r\n                </div>\r\n\r\n                <!-- Authorized Signature - Compacted -->\r\n                <div class=\"bg-white p-6 mt-auto text-center\">\r\n                    <div class=\"border-t border-slate-300 w-32 mx-auto mb-1.5\"></div>\r\n                    <p class=\"text-[8px] font-black uppercase tracking-[0.2em] text-slate-400\">Authorized Signature</p>\r\n                </div>\r\n            </div>\r\n        </div>\r\n\r\n        <!-- Footer - Optimized -->\r\n        <div class=\"bg-blue-900 text-white p-2 border-t-2 border-blue-400 flex justify-between items-center text-[9px] mt-auto\">\r\n            <div class=\"px-6 font-black uppercase tracking-widest\">Support: {{society_mobile}}</div>\r\n            <div class=\"px-6 flex gap-6 items-center\">\r\n                <span class=\"font-bold text-blue-200\">{{society_email}}</span>\r\n                <span class=\"font-black text-blue-300 border-l border-blue-700 pl-6 uppercase tracking-tighter italic opacity-80\">\r\n                    Verified Digital Record\r\n                </span>\r\n            </div>\r\n        </div>\r\n    </div>\r\n\r\n</body>\r\n</html>', '', 0, '2026-08-30 21:27:47'),
(18, 1, 'Full Bill', 'full-bill', 'print_bill', '<!DOCTYPE html>\r\n<html lang=\"en\">\r\n<head>\r\n    <meta charset=\"UTF-8\">\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n    <title>Professional Bill Generator</title>\r\n    <script src=\"https://cdn.tailwindcss.com\"></script>\r\n    <style>\r\n        @import url(\'https://fonts.googleapis.com/css2?family=Inter:wght@400;500;700;900&family=JetBrains+Mono:wght@400;700&display=swap\');\r\n\r\n        body {\r\n            font-family: \'Inter\', sans-serif;\r\n            background-color: #f1f5f9;\r\n        }\r\n\r\n        .font-mono {\r\n            font-family: \'JetBrains+Mono\', monospace;\r\n        }\r\n\r\n        /* A4 Constraints */\r\n        .page-container {\r\n            width: 210mm;\r\n            min-height: 297mm;\r\n            padding: 10mm;\r\n            margin: 0 auto;\r\n            background: white;\r\n            box-sizing: border-box;\r\n            position: relative;\r\n        }\r\n\r\n        @media print {\r\n            body { background: white !important; margin: 0; padding: 0; }\r\n            .no-print { display: none !important; }\r\n            .page-container { \r\n                border: none !important; \r\n                margin: 0 !important; \r\n                width: 210mm; \r\n                height: 297mm; \r\n                box-shadow: none !important;\r\n                padding: 10mm !important;\r\n            }\r\n            @page {\r\n                size: A4;\r\n                margin: 0;\r\n            }\r\n        }\r\n    \n/* subm-template-print-consistency */\n@media print { body { -webkit-print-color-adjust: exact; print-color-adjust: exact; } }\n</style>\r\n</head>\r\n<body class=\"flex justify-center min-h-screen p-4 md:p-12\">\r\n\r\n    <!-- Floating Print Button -->\r\n    <button onclick=\"window.print()\" class=\"no-print fixed top-6 right-6 bg-indigo-600 hover:bg-indigo-700 text-white px-6 py-3 rounded-full font-bold shadow-lg transition-all flex items-center gap-2 z-50\">\r\n        <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"6 9 6 2 18 2 18 9\"></polyline><path d=\"M6 18H4a2 2 0 0 1-2-2v-5a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2v5a2 2 0 0 1-2 2h-2\"></path><rect x=\"6\" y=\"14\" width=\"12\" height=\"8\"></rect></svg>\r\n        Print Bill\r\n    </button>\r\n\r\n    <!-- Main Bill Area -->\r\n    <div class=\"page-container shadow-2xl border border-slate-200\">\r\n        \r\n        <!-- Header -->\r\n        <div class=\"bg-slate-900 text-white p-6 flex items-center justify-between\">\r\n            <div>\r\n                <h1 id=\"out_society_name\" class=\"text-3xl font-black uppercase tracking-tighter leading-none\">---</h1>\r\n                <p id=\"out_society_address\" class=\"text-[11px] font-medium mt-2 opacity-80 uppercase tracking-wide\">---</p>\r\n            </div>\r\n            <div class=\"text-right flex flex-col items-end gap-1\">\r\n                <span class=\"bg-white text-black px-3 py-1 text-[10px] uppercase tracking-widest font-black\">Utility Invoice</span>\r\n                <span id=\"out_current_date\" class=\"text-[10px] opacity-60 font-mono\">---</span>\r\n            </div>\r\n        </div>\r\n\r\n        <!-- Top Summary Grid -->\r\n        <div class=\"grid grid-cols-6 border-x border-b border-black text-center text-[10px] divide-x divide-black mb-6 uppercase\">\r\n            <div class=\"flex flex-col\">\r\n                <div class=\"py-1.5 bg-slate-50 font-bold border-b border-black\">Bill No</div>\r\n                <div id=\"out_bill_no\" class=\"py-2 font-mono\">---</div>\r\n            </div>\r\n            <div class=\"flex flex-col\">\r\n                <div class=\"py-1.5 bg-slate-50 font-bold border-b border-black\">Consumer</div>\r\n                <div id=\"out_consumer_id\" class=\"py-2 font-mono\">---</div>\r\n            </div>\r\n            <div class=\"flex flex-col\">\r\n                <div class=\"py-1.5 bg-slate-50 font-bold border-b border-black\">Property</div>\r\n                <div id=\"out_property_id\" class=\"py-2 font-mono\">---</div>\r\n            </div>\r\n            <div class=\"flex flex-col\">\r\n                <div class=\"py-1.5 bg-slate-50 font-bold border-b border-black\">Month</div>\r\n                <div id=\"out_billing_month\" class=\"py-2 font-mono\">---</div>\r\n            </div>\r\n            <div class=\"flex flex-col\">\r\n                <div class=\"py-1.5 bg-slate-50 font-bold border-b border-black\">Issue</div>\r\n                <div id=\"out_issue_date\" class=\"py-2 font-mono\">---</div>\r\n            </div>\r\n            <div class=\"flex flex-col\">\r\n                <div class=\"py-1.5 bg-slate-50 font-black border-b border-black\">Due</div>\r\n                <div id=\"out_due_date\" class=\"py-2 font-black bg-yellow-50\">---</div>\r\n            </div>\r\n        </div>\r\n\r\n        <div class=\"flex gap-8 flex-grow\">\r\n            <!-- Left Col -->\r\n            <div class=\"flex-[7] flex flex-col gap-6\">\r\n                <section>\r\n                    <h3 class=\"bg-slate-100 px-3 py-1.5 text-[10px] font-black border border-black uppercase tracking-wide\">Consumer Information</h3>\r\n                    <div class=\"p-4 border border-t-0 border-black min-h-[80px]\">\r\n                        <p id=\"out_client_name\" class=\"text-xl font-black uppercase leading-none\">---</p>\r\n                        <p class=\"text-[12px] font-medium mt-2 opacity-80\">\r\n                            Property ID: <span id=\"out_property_id_2\">---</span><br>\r\n                            Registered Consumer ID: <span id=\"out_consumer_id_2\">---</span>\r\n                        </p>\r\n                    </div>\r\n                </section>\r\n\r\n                <section>\r\n                    <h3 class=\"bg-slate-100 px-3 py-1.5 text-[10px] font-black border border-black uppercase tracking-wide\">Reading & Consumption</h3>\r\n                    <div class=\"border border-t-0 border-black overflow-hidden\">\r\n                        <table class=\"w-full text-[11px] text-center\">\r\n                            <thead class=\"bg-slate-50 border-b border-black uppercase font-bold\">\r\n                                <tr>\r\n                                    <th class=\"py-2 border-r border-black\">Previous</th>\r\n                                    <th class=\"py-2 border-r border-black\">Current</th>\r\n                                    <th class=\"py-2 border-r border-black\">Consumed</th>\r\n                                    <th class=\"py-2\">Unit Price</th>\r\n                                </tr>\r\n                            </thead>\r\n                            <tbody class=\"font-mono\">\r\n                                <tr>\r\n                                    <td id=\"out_prev_reading\" class=\"py-2.5 border-r border-black\">0</td>\r\n                                    <td id=\"out_curr_reading\" class=\"py-2.5 border-r border-black\">0</td>\r\n                                    <td id=\"out_consumed\" class=\"py-2.5 border-r border-black font-black text-lg bg-yellow-50\">0</td>\r\n                                    <td id=\"out_unit_price\" class=\"py-2.5\">0.00</td>\r\n                                </tr>\r\n                            </tbody>\r\n                        </table>\r\n                    </div>\r\n                </section>\r\n\r\n                <!-- Placeholder History -->\r\n                <section>\r\n                    <h3 class=\"bg-slate-100 px-3 py-1.5 text-[10px] font-black border border-black uppercase tracking-wide\">Recent History</h3>\r\n                    <div class=\"border border-t-0 border-black overflow-hidden\">\r\n                        <table class=\"w-full text-[10px]\">\r\n                            <thead class=\"bg-slate-50 border-b border-black uppercase font-bold\">\r\n                                <tr>\r\n                                    <th class=\"py-2 px-3 text-left border-r border-black\">Month</th>\r\n                                    <th class=\"py-2 text-center border-r border-black\">Units</th>\r\n                                    <th class=\"py-2 px-3 text-right\">Bill Amount</th>\r\n                                </tr>\r\n                            </thead>\r\n                            <tbody class=\"divide-y divide-black/10\">\r\n                                <tr><td class=\"py-2 px-3 border-r border-black\">Previous Month</td><td class=\"text-center border-r border-black\">210</td><td class=\"px-3 text-right\">Paid</td></tr>\r\n                                <tr><td class=\"py-2 px-3 border-r border-black\">2nd Previous</td><td class=\"text-center border-r border-black\">195</td><td class=\"px-3 text-right\">Paid</td></tr>\r\n                            </tbody>\r\n                        </table>\r\n                    </div>\r\n                </section>\r\n\r\n                <div class=\"mt-auto border border-dashed border-black/30 p-4 text-center text-[10px] text-slate-400 italic\">\r\n                    Digital Signature Validated System Generated Bill. No Physical Signature Required.\r\n                </div>\r\n            </div>\r\n\r\n            <!-- Right Col -->\r\n            <div class=\"flex-[5] flex flex-col\">\r\n                <h3 class=\"bg-slate-100 px-3 py-1.5 text-[10px] font-black border border-black uppercase tracking-wide\">Financial Breakdown</h3>\r\n                <div class=\"border border-t-0 border-black flex flex-col h-full\">\r\n                    <table class=\"w-full text-[11px]\">\r\n                        <thead class=\"bg-slate-50 border-b border-black font-black uppercase\">\r\n                            <tr>\r\n                                <th class=\"p-2 text-left border-r border-black\">Details</th>\r\n                                <th class=\"p-2 text-right\">Amount</th>\r\n                            </tr>\r\n                        </thead>\r\n                        <tbody class=\"divide-y divide-black/10\">\r\n                            <tr class=\"bg-yellow-50/30\">\r\n                                <td class=\"p-2 border-r border-black font-bold\">Cons. Charges</td>\r\n                                <td id=\"out_cons_charge\" class=\"p-2 text-right font-mono\">0.00</td>\r\n                            </tr>\r\n                            <tr><td class=\"p-2 border-r border-black\">Fixed Charges</td><td class=\"p-2 text-right font-mono\">500.00</td></tr>\r\n                            <tr><td class=\"p-2 border-r border-black\">Maintenance</td><td class=\"p-2 text-right font-mono\">1500.00</td></tr>\r\n                            <tr class=\"bg-slate-50 font-bold border-t border-black\">\r\n                                <td class=\"p-2 border-r border-black\">Arrears</td>\r\n                                <td id=\"out_arrears\" class=\"p-2 text-right font-mono text-red-600\">0.00</td>\r\n                            </tr>\r\n                            <tr class=\"bg-black text-white font-black\">\r\n                                <td class=\"p-3 text-xs border-r border-white\">TOTAL PAYABLE</td>\r\n                                <td id=\"out_total\" class=\"p-3 text-right text-xl font-mono\">0.00</td>\r\n                            </tr>\r\n                            <tr class=\"bg-slate-50 italic font-bold border-t border-black\">\r\n                                <td class=\"p-2 border-r border-black text-[9px] uppercase\">If Paid Late</td>\r\n                                <td id=\"out_total_late\" class=\"p-2 text-right text-sm font-mono\">0.00</td>\r\n                            </tr>\r\n                        </tbody>\r\n                    </table>\r\n                    \r\n                    <div class=\"mt-auto border-t border-black p-4 bg-slate-50\">\r\n                        <p class=\"font-black text-[9px] uppercase border-b border-black/20 mb-2 pb-1\">Payment Instructions</p>\r\n                        <div id=\"out_bank_details\" class=\"whitespace-pre-wrap text-[10px] font-mono leading-tight tracking-tight text-slate-700\">---</div>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n\r\n        <!-- SEPARATOR -->\r\n        <div class=\"w-full py-6 relative\">\r\n            <div class=\"absolute top-1/2 left-0 w-full border-t border-dashed border-black/40\"></div>\r\n            <div class=\"absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 bg-white px-4 text-black text-[10px] font-black\">\r\n                ✂ DETACH & SUBMIT WITH PAYMENT\r\n            </div>\r\n        </div>\r\n\r\n        <!-- SLIP -->\r\n        <div class=\"bg-white border-2 border-black p-4\">\r\n            <div class=\"flex justify-between items-start border-b border-black pb-2 mb-3\">\r\n                <div class=\"flex items-center gap-2\">\r\n                    <div class=\"h-8 w-1.5 bg-black\"></div>\r\n                    <h2 class=\"text-xs font-black uppercase\">Payment Submission Slip</h2>\r\n                </div>\r\n                <div class=\"text-right\">\r\n                    <p id=\"out_society_name_slip\" class=\"text-[10px] font-black uppercase\">---</p>\r\n                </div>\r\n            </div>\r\n            <div class=\"grid grid-cols-4 gap-4 text-[10px] mb-4\">\r\n                <div class=\"col-span-1 border-b border-black pb-1\"><label class=\"block text-[8px] font-bold opacity-60\">Bill No</label><span id=\"out_bill_no_slip\">---</span></div>\r\n                <div class=\"col-span-2 border-b border-black pb-1\"><label class=\"block text-[8px] font-bold opacity-60\">Consumer Name</label><span id=\"out_client_name_slip\">---</span></div>\r\n                <div class=\"col-span-1 border-b border-black pb-1\"><label class=\"block text-[8px] font-bold opacity-60\">Consumer ID</label><span id=\"out_consumer_id_slip\">---</span></div>\r\n            </div>\r\n            <div class=\"flex justify-between items-end\">\r\n                <div class=\"bg-slate-100 border border-black p-3 text-center min-w-[150px]\">\r\n                    <p class=\"text-[8px] font-black opacity-60 uppercase\">Payable Amount</p>\r\n                    <p id=\"out_total_slip\" class=\"text-xl font-black font-mono mt-1\">0.00</p>\r\n                </div>\r\n                <div class=\"w-32 text-center pb-2\">\r\n                    <div class=\"border-b-2 border-black/20 h-10 mb-1\"></div>\r\n                    <p class=\"text-[8px] font-black uppercase\">Stamp & Sign</p>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n\r\n    <script>\r\n        // State Management\r\n        const state = {\r\n            society_name: \"Green Valley Residents Association\",\r\n            society_address: \"Plot 42, Sector B-1, Islamabad\",\r\n            client_name: \"John Q. Citizen\",\r\n            bill_no: \"GV-2024-05-001\",\r\n            consumer_id: \"CNS-882910\",\r\n            property_id: \"H-124/B\",\r\n            billing_month: \"May 2024\",\r\n            issue_date: \"05 Jun 2024\",\r\n            due_date: \"15 Jun 2024\",\r\n            prev_reading: 12450,\r\n            curr_reading: 12680,\r\n            unit_price: 24.50,\r\n            arrears: 120.00,\r\n            late_fee: 50.00,\r\n            bank_details: \"HBL - Green Valley Branch\\nAccount: 0042-79012345-03\\nIBAN: PK70HABB00427901234503\",\r\n            fixed_charges: 2000 // 500 fixed + 1500 maintenance as per static layout\r\n        };\r\n\r\n        // Initialize Form\r\n        function init() {\r\n            document.getElementById(\'out_current_date\').innerText = new Date().toISOString().split(\'T\')[0];\r\n            render();\r\n        }\r\n\r\n        // Calculation & DOM Update\r\n        function render() {\r\n            // Calculations\r\n            const consumed = Math.max(0, state.curr_reading - state.prev_reading);\r\n            const consCharge = consumed * state.unit_price;\r\n            const total = consCharge + state.fixed_charges + state.arrears;\r\n            const totalLate = total + state.late_fee;\r\n\r\n            const formatter = new Intl.NumberFormat(\'en-US\', { minimumFractionDigits: 2 });\r\n\r\n            // Update DOM Elements\r\n            const updates = {\r\n                \'out_society_name\': state.society_name,\r\n                \'out_society_name_slip\': state.society_name,\r\n                \'out_society_address\': state.society_address,\r\n                \'out_client_name\': state.client_name,\r\n                \'out_client_name_slip\': state.client_name,\r\n                \'out_bill_no\': state.bill_no,\r\n                \'out_bill_no_slip\': state.bill_no,\r\n                \'out_consumer_id\': state.consumer_id,\r\n                \'out_consumer_id_2\': state.consumer_id,\r\n                \'out_consumer_id_slip\': state.consumer_id,\r\n                \'out_property_id\': state.property_id,\r\n                \'out_property_id_2\': state.property_id,\r\n                \'out_billing_month\': state.billing_month,\r\n                \'out_issue_date\': state.issue_date,\r\n                \'out_due_date\': state.due_date,\r\n                \'out_prev_reading\': state.prev_reading.toLocaleString(),\r\n                \'out_curr_reading\': state.curr_reading.toLocaleString(),\r\n                \'out_consumed\': consumed,\r\n                \'out_unit_price\': state.unit_price.toFixed(2),\r\n                \'out_cons_charge\': formatter.format(consCharge),\r\n                \'out_arrears\': formatter.format(state.arrears),\r\n                \'out_total\': formatter.format(total),\r\n                \'out_total_slip\': formatter.format(total),\r\n                \'out_total_late\': formatter.format(totalLate),\r\n                \'out_bank_details\': state.bank_details\r\n            };\r\n\r\n            for (let id in updates) {\r\n                const el = document.getElementById(id);\r\n                if (el) el.innerText = updates[id];\r\n            }\r\n        }\r\n\r\n        window.onload = init;\r\n    </script>\r\n</body>\r\n</html><div style=\"margin-top:12px;\">{{bank_details}}</div>', '', 0, '2026-08-30 21:27:47');
INSERT INTO `billing_templates` (`id`, `society_id`, `name`, `slug`, `template_type`, `html_content`, `css_content`, `is_default`, `created_at`) VALUES
(19, 1, 'Partialy Paid', 'partialy-paid', 'partial_paid', '<!DOCTYPE html>\r\n<html lang=\"en\">\r\n<head>\r\n    <meta charset=\"UTF-8\">\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n    <title>{{document_type}} - {{bill_no}}</title>\r\n    <!-- Tailwind CSS CDN -->\r\n    <script src=\"https://cdn.tailwindcss.com\"></script>\r\n    <style>\r\n        @import url(\'https://fonts.googleapis.com/css2?family=Inter:wght@300;400;600;700;800;900&display=swap\');\r\n        @import url(\'https://fonts.googleapis.com/css2?family=Noto+Nastaliq+Urdu:wght@400;700&display=swap\');\r\n        \r\n        body {\r\n            font-family: \'Inter\', sans-serif;\r\n            margin: 0;\r\n            padding: 0;\r\n        }\r\n\r\n        .urdu-font {\r\n            font-family: \'Noto Nastaliq Urdu\', serif;\r\n        }\r\n\r\n        /* Print Settings for Half A4 (Landscape fit) */\r\n        @media print {\r\n            @page {\r\n                size: 210mm 148.5mm;\r\n                margin: 0;\r\n            }\r\n            body {\r\n                background-color: white;\r\n            }\r\n            .no-print {\r\n                display: none !important;\r\n            }\r\n            .page-container {\r\n                box-shadow: none !important;\r\n                border: 3px solid #1e3a8a !important;\r\n                margin: 0 !important;\r\n                width: 210mm !important;\r\n                height: 148.5mm !important;\r\n                min-height: 148.5mm !important;\r\n                max-height: 148.5mm !important;\r\n            }\r\n        }\r\n\r\n        /* Screen Preview Settings for Half A4 */\r\n        .page-container {\r\n            width: 210mm;\r\n            height: 148.5mm;\r\n            background: white;\r\n            box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.25);\r\n            margin: 10px auto;\r\n        }\r\n    \r\n        /* subm-template-print-consistency */\r\n        @media print { body { -webkit-print-color-adjust: exact; print-color-adjust: exact; } }\r\n    </style>\r\n</head>\r\n<body class=\"bg-slate-200 min-h-screen flex flex-col items-center\">\r\n\r\n    <!-- Print Button (Visible only on screen) -->\r\n    <div class=\"no-print my-4\">\r\n        <button onclick=\"window.print()\" class=\"bg-blue-900 text-white px-6 py-2 rounded-lg font-bold flex items-center gap-2 hover:bg-blue-800 transition-all shadow-xl\">\r\n            <svg xmlns=\"http://www.w3.org/2003/svg\" width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"6 9 6 2 18 2 18 9\"></polyline><path d=\"M6 18H4a2 2 0 0 1-2-2v-5a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2v5a2 2 0 0 1-2 2h-2\"></path><rect x=\"6\" y=\"14\" width=\"12\" height=\"8\"></rect></svg>\r\n            Print {{template_type}}\r\n        </button>\r\n    </div>\r\n\r\n    <!-- Receipt Document Container -->\r\n    <div class=\"page-container flex flex-col border-[3px] border-blue-900 relative box-border text-slate-900 overflow-hidden\">\r\n        \r\n        <!-- Header Section - Tightened Padding -->\r\n        <div class=\"bg-white py-1.5 px-4 flex items-center border-b-[3px] border-blue-900 relative\">\r\n            <div class=\"w-1/4\">\r\n                <img src=\"{{society_logo}}\" alt=\"Logo\" class=\"h-8 w-auto object-contain rounded-md\">\r\n            </div>\r\n            <div class=\"w-2/4 text-center\">\r\n                <h1 class=\"text-[18px] font-black uppercase tracking-tight text-blue-900 leading-none\">{{society_name}}</h1>\r\n                <p class=\"text-[8px] font-medium text-slate-500 mt-0.5 leading-tight\">{{society_address}}</p>\r\n                <div class=\"text-[9px] font-bold text-green-600 mt-0.5 uppercase tracking-wide\">\r\n                    Mobile: {{society_mobile}}\r\n                </div>\r\n            </div>\r\n            <div class=\"w-1/4 flex justify-end\">\r\n                <span class=\"bg-[#b91c1c] text-white px-2 py-1 rounded-sm text-[8px] uppercase tracking-widest font-black shadow-md\">{{document_type}}</span>\r\n            </div>\r\n        </div>\r\n\r\n        <!-- Quick Info Bar -->\r\n        <div class=\"grid grid-cols-6 border-b-2 border-blue-200 text-center text-[8px] divide-x-2 divide-blue-200 bg-white\">\r\n            <div class=\"flex flex-col\"><div class=\"py-0.5 bg-blue-50 font-bold text-blue-800 uppercase border-b border-blue-100\">Receipt No</div><div class=\"py-1 font-bold\">{{bill_no}}</div></div>\r\n            <div class=\"flex flex-col\"><div class=\"py-0.5 bg-blue-50 font-bold text-blue-800 uppercase border-b border-blue-100\">Date</div><div class=\"py-1 font-bold\">{{issue_date}}</div></div>\r\n            <div class=\"flex flex-col\"><div class=\"py-0.5 bg-blue-50 font-bold text-blue-800 uppercase border-b border-blue-100\">Consumer ID</div><div class=\"py-1 font-bold\">{{consumer_id}}</div></div>\r\n            <div class=\"flex flex-col\"><div class=\"py-0.5 bg-blue-50 font-bold text-blue-800 uppercase border-b border-blue-100\">Property</div><div class=\"py-1 font-bold\">{{property_id}}</div></div>\r\n            <div class=\"flex flex-col\"><div class=\"py-0.5 bg-blue-50 font-bold text-blue-800 uppercase border-b border-blue-100\">Bill Month</div><div class=\"py-1 font-bold uppercase\">{{billing_month}}</div></div>\r\n            <div class=\"flex flex-col\"><div class=\"py-0.5 bg-blue-50 font-bold text-blue-800 uppercase border-b border-blue-100\">Status</div><div class=\"py-1 font-black text-red-700 italic uppercase\">{{payment_status}}</div></div>\r\n        </div>\r\n\r\n        <!-- Main Body Content -->\r\n        <div class=\"flex flex-grow overflow-hidden relative\">\r\n            \r\n            <!-- PARTIAL PAID Stamp Overlay -->\r\n            <div class=\"absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 opacity-[0.25] pointer-events-none z-50 mix-blend-multiply flex items-center justify-center\">\r\n                <svg width=\"180\" height=\"180\" viewBox=\"0 0 300 300\" xmlns=\"http://www.w3.org/2000/svg\">\r\n                    <defs>\r\n                        <path id=\"arc-top\" d=\"M 38,150 A 112,112 0 0,1 262,150\" fill=\"none\" />\r\n                        <path id=\"arc-bot\" d=\"M 38,150 A 112,112 0 0,0 262,150\" fill=\"none\" />\r\n                    </defs>\r\n                    <circle cx=\"150\" cy=\"150\" r=\"142\" fill=\"none\" stroke=\"#b91c1c\" stroke-width=\"5\"/>\r\n                    <circle cx=\"150\" cy=\"150\" r=\"134\" fill=\"none\" stroke=\"#b91c1c\" stroke-width=\"2\"/>\r\n                    <circle cx=\"150\" cy=\"150\" r=\"90\" fill=\"none\" stroke=\"#b91c1c\" stroke-width=\"2\"/>\r\n                    <text fill=\"#b91c1c\" font-size=\"28\" font-weight=\"900\" font-family=\"Arial Black, Impact, sans-serif\" letter-spacing=\"2\" dominant-baseline=\"central\">\r\n                        <textPath href=\"#arc-top\" startOffset=\"50%\" text-anchor=\"middle\">PARTIAL PAYMENT</textPath>\r\n                    </text>\r\n                    <text fill=\"#b91c1c\" font-size=\"28\" font-weight=\"900\" font-family=\"Arial Black, Impact, sans-serif\" letter-spacing=\"2\" dominant-baseline=\"central\">\r\n                        <textPath href=\"#arc-bot\" startOffset=\"50%\" text-anchor=\"middle\">PARTIAL PAYMENT</textPath>\r\n                    </text>\r\n                    <text x=\"22\" y=\"161\" fill=\"#b91c1c\" font-size=\"28\" text-anchor=\"middle\">★</text>\r\n                    <text x=\"278\" y=\"161\" fill=\"#b91c1c\" font-size=\"28\" text-anchor=\"middle\">★</text>\r\n                    <text x=\"150\" y=\"115\" fill=\"#b91c1c\" font-size=\"14\" font-weight=\"bold\" font-family=\"Arial, sans-serif\" text-anchor=\"middle\" letter-spacing=\"4\">PARTIAL</text>\r\n                    <text x=\"150\" y=\"196\" fill=\"#b91c1c\" font-size=\"14\" font-weight=\"bold\" font-family=\"Arial, sans-serif\" text-anchor=\"middle\" letter-spacing=\"4\">PARTIAL</text>\r\n                    <g transform=\"rotate(-15 150 150)\">\r\n                        <rect x=\"5\" y=\"115\" width=\"290\" height=\"70\" rx=\"10\" fill=\"#b91c1c\" />\r\n                        <rect x=\"12\" y=\"122\" width=\"276\" height=\"56\" rx=\"6\" fill=\"none\" stroke=\"#ffffff\" stroke-width=\"2\" stroke-dasharray=\"4 3\"/>\r\n                        <text x=\"150\" y=\"158\" fill=\"#ffffff\" font-size=\"38\" font-weight=\"900\" font-family=\"Arial Black, Impact, sans-serif\" text-anchor=\"middle\" letter-spacing=\"1\">PARTIAL PAID</text>\r\n                    </g>\r\n                </svg>\r\n            </div>\r\n\r\n            <!-- Left Panel (7/12) -->\r\n            <div class=\"flex-[7] flex flex-col border-r-2 border-blue-900 z-10\">\r\n                <!-- Payer Info Section - Compact -->\r\n                <section class=\"p-2 px-4 bg-slate-50/10\">\r\n                    <h3 class=\"text-[8px] font-bold text-blue-800 uppercase tracking-wider mb-0.5\">Payer Information</h3>\r\n                    <p class=\"text-[12px] font-black uppercase text-slate-900\">{{client_name}}</p>\r\n                    <p class=\"text-[8px] font-bold text-blue-700 mb-0.5\">REGISTERED RESIDENT / OWNER</p>\r\n                    <p class=\"text-[9px] text-slate-600 font-medium max-w-sm leading-tight\">{{client_address}}</p>\r\n                </section>\r\n\r\n                <!-- Detailed Transaction Summary -->\r\n                <section class=\"border-t-2 border-b-2 border-blue-200\">\r\n                    <div class=\"bg-blue-50/50 px-3 py-0.5 text-[8px] font-black uppercase text-slate-800\">Summary of Totals</div>\r\n                    <table class=\"w-full text-[9px] text-center border-collapse\">\r\n                        <thead class=\"bg-white text-slate-500 uppercase font-bold text-[7px] border-b\">\r\n                            <tr>\r\n                                <th class=\"py-1 px-1 border-r\">Previous Arrears</th>\r\n                                <th class=\"py-1 px-1 border-r\">Current Charges</th>\r\n                                <th class=\"py-1 px-1 border-r\">Late Fee ({{late_fee_percent}}%)</th>\r\n                                <th class=\"py-1 px-1\">Total Payable</th>\r\n                            </tr>\r\n                        </thead>\r\n                        <tbody class=\"font-black text-slate-900\">\r\n                            <tr>\r\n                                <td class=\"py-1.5 border-r border-slate-100\">{{arrears}}</td>\r\n                                <td class=\"py-1.5 border-r border-slate-100\">{{total_amount}}</td>\r\n                                <td class=\"py-1.5 border-r border-slate-100 text-red-500\">{{late_fee}}</td>\r\n                                <td class=\"py-1.5 bg-blue-50/30 text-blue-900 text-[10px] font-black\">{{payable_after_due}}</td>\r\n                            </tr>\r\n                        </tbody>\r\n                    </table>\r\n                </section>\r\n\r\n                <!-- Itemized Billing Section (Maintenance & Other Charges) - Compacted -->\r\n                <section class=\"bg-white flex flex-col\">\r\n                    <div class=\"bg-slate-50 px-3 py-0.5 text-[8px] font-bold uppercase text-slate-600 border-b\">Itemized Billing Details</div>\r\n                    <div class=\"overflow-hidden\">\r\n                        <table class=\"w-full text-[8px] text-left border-collapse\">\r\n                            <thead class=\"text-slate-400 uppercase font-bold border-b text-[7px]\">\r\n                                <tr>\r\n                                    <th class=\"py-0.5 px-3\">Description</th>\r\n                                    <th class=\"py-0.5 px-3 text-right\">Amount</th>\r\n                                </tr>\r\n                            </thead>\r\n                            <tbody class=\"divide-y divide-slate-100\">\r\n                                {{maintenance_rows}}                   \r\n                                {{other_rows}}\r\n                            </tbody>\r\n                        </table>\r\n                    </div>\r\n                    <!-- Adjustment note section -->\r\n                    <div class=\"p-1 border-t border-slate-50\">\r\n                        <p class=\"text-[7px] text-slate-400 italic font-medium leading-tight\">{{adjustment_note}}</p>\r\n                    </div>\r\n                </section>\r\n\r\n                <!-- History Summary - Compacted to avoid Letter height overflow -->\r\n                <section class=\"bg-white border-t-2 border-blue-200\">\r\n                    <div class=\"bg-blue-900 text-white text-[8px] font-bold uppercase text-center py-0.5 tracking-widest\">Previous 6 Months Payment Summary</div>\r\n                    <table class=\"w-full text-[7px] text-center border-collapse\">\r\n                        <thead class=\"bg-slate-50 font-bold uppercase border-b border-slate-200\">\r\n                            <tr>\r\n                                <th class=\"py-0.5 border-r\">Billing Month</th>\r\n                                <th class=\"py-0.5 border-r\">Bill Amount</th>\r\n                                <th class=\"py-0.5 border-r\">Amount Paid</th>\r\n                                <th class=\"py-0.5\">Status</th>\r\n                            </tr>\r\n                        </thead>\r\n                        <tbody class=\"text-slate-600 divide-y divide-slate-50\">\r\n                            {{history_rows}}\r\n                        </tbody>\r\n                    </table>\r\n                </section>\r\n\r\n                <!-- Filler to push empty space to the bottom -->\r\n                <div class=\"flex-grow bg-white\"></div>\r\n            </div>\r\n\r\n            <!-- Right Column (5/12) -->\r\n            <div class=\"flex-[5] flex flex-col bg-slate-50/10 z-10\">\r\n                <!-- Final Settlement Title -->\r\n                <div class=\"bg-blue-900 text-white py-1 text-center text-[8px] font-black uppercase tracking-widest\">Final Settlement</div>\r\n                \r\n                <!-- Breakdown -->\r\n                <table class=\"w-full text-[10px] border-collapse bg-white\">\r\n                    <tbody class=\"divide-y divide-slate-100 font-bold text-slate-500\">\r\n                        <tr>\r\n                            <td class=\"p-1.5 px-4 text-[10px]\">Total Bill</td>\r\n                            <td class=\"p-1.5 px-4 text-right text-slate-900 text-[11px]\">{{total_amount}}</td>\r\n                        </tr>\r\n                        <tr>\r\n                            <td class=\"p-1.5 px-4 text-[10px]\">Surcharge</td>\r\n                            <td class=\"p-1.5 px-4 text-right text-red-500 text-[11px]\">{{late_fee}}</td>\r\n                        </tr>\r\n                        <!-- Total Amount Paid Box - GREEN BACKGROUND -->\r\n                        <tr class=\"bg-green-700 text-white border-t-2 border-green-900\">\r\n                            <td class=\"p-2 px-4 font-black uppercase text-[9px] leading-tight\">Partial Amount<br>Paid</td>\r\n                            <td class=\"p-2 px-4 text-right text-[18px] font-black tracking-tighter\">{{paid_amount}}</td>\r\n                        </tr>\r\n                        <!-- Adjustments (BLUE) & Pending Balance (RED) -->\r\n                        <tr class=\"border-t border-white\">\r\n                            <td class=\"p-1.5 px-4 text-[8px] font-bold bg-blue-600 text-white border-r border-white\">\r\n                                Adj: ({{adjustment_credit}} / {{adjustment_debit}})\r\n                            </td>\r\n                            <td class=\"p-1.5 px-4 text-right font-black bg-red-600 text-white text-[10px] italic\">\r\n                                Bal: {{pending_amount}}\r\n                            </td>\r\n                        </tr>\r\n                    </tbody>\r\n                </table>\r\n\r\n                <!-- Confirmation Stamp -->\r\n                <div class=\"flex-grow flex flex-col items-center justify-center p-2 text-center bg-white border-y border-slate-100\">\r\n                    <div class=\"w-10 h-10 bg-red-50 rounded-full flex items-center justify-center text-[#b91c1c] mb-1 border-2 border-red-100 shadow-sm\">\r\n                        <svg xmlns=\"http://www.w3.org/2003/svg\" width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"4\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"></circle><line x1=\"12\" y1=\"8\" x2=\"12\" y2=\"12\"></line><line x1=\"12\" y1=\"16\" x2=\"12.01\" y2=\"16\"></line></svg>\r\n                    </div>\r\n                    <p class=\"text-[11px] font-black text-[#b91c1c] uppercase tracking-[0.2em] leading-none mb-0.5\">Partial Pay</p>\r\n                    <p class=\"text-[7px] text-slate-400 font-bold uppercase tracking-widest\">Office Copy Ref: {{payment_ref}}</p>\r\n                </div>\r\n\r\n                <!-- Urdu Payment and Society Message -->\r\n                <div class=\"p-2 px-4 text-center urdu-font bg-blue-50/30 border-b border-slate-200\">\r\n                    <p class=\"text-[10px] font-bold text-blue-900 leading-snug\">آپ کی جزوی ادائیگی موصول ہو چکی ہے۔ بقیہ واجبات کی ادائیگی جلد یقینی بنائیں۔</p>\r\n                    <p class=\"text-[8px] font-bold text-green-700 mt-1 leading-snug\">سوسائٹی کو صاف ستھرا اور خوبصورت رکھنے میں ہمارا ساتھ دیں۔</p>\r\n                </div>\r\n\r\n                <!-- Authorized Signature -->\r\n                <div class=\"bg-white p-3 mt-auto text-center\">\r\n                    <div class=\"border-t border-slate-300 w-24 mx-auto mb-1\"></div>\r\n                    <p class=\"text-[7px] font-black uppercase tracking-[0.2em] text-slate-400\">Authorized Signature</p>\r\n                </div>\r\n            </div>\r\n        </div>\r\n\r\n        <!-- Footer - Optimized -->\r\n        <div class=\"bg-blue-900 text-white p-1.5 border-t-2 border-blue-400 flex justify-between items-center text-[8px] mt-auto\">\r\n            <div class=\"px-4 font-black uppercase tracking-widest\">Support: {{society_mobile}}</div>\r\n            <div class=\"px-4 flex gap-4 items-center\">\r\n                <span class=\"font-bold text-blue-200\">{{society_email}}</span>\r\n                <span class=\"font-black text-blue-300 border-l border-blue-700 pl-4 uppercase tracking-tighter italic opacity-80\">\r\n                    Verified Digital Record\r\n                </span>\r\n            </div>\r\n        </div>\r\n    </div>\r\n\r\n</body>\r\n</html>', '', 1, '2026-08-30 21:27:48');
