(1, 0, 'RA-', 1, 'RR-', 1, 'both', '7,10,8,11,12,6', 1, 'Dear {{tenant_name}}, your rental agreement {{agreement_no}} is created for {{property_name}}. Monthly rent {{monthly_rent}}.', 1, 'Rental Agreement {{agreement_no}}', '<p>Dear {{tenant_name}},</p><p>Your rental agreement <strong>{{agreement_no}}</strong> has been created for <strong>{{property_name}}</strong>.</p><p>Monthly Rent: <strong>{{monthly_rent}}</strong></p>', 1, 'Rental Agreement {{agreement_no}} for {{property_name}}. Monthly rent {{monthly_rent}}.', 3, 0, 'Percentage', 0.00, '2026-06-30 17:43:33', '2026-07-08 19:34:47'),
(2, 22, 'RA-', 6, 'RR-', 2, 'both', '', 0, 'Dear {{tenant_name}}, your rental agreement {{agreement_no}} is created for {{property_name}}. Monthly rent {{monthly_rent}}.', 0, 'Rental Agreement {{agreement_no}}', '<p>Dear {{tenant_name}},</p><p>Your rental agreement <strong>{{agreement_no}}</strong> has been created for <strong>{{property_name}}</strong>.</p><p>Monthly Rent: <strong>{{monthly_rent}}</strong></p>', 0, 'Rental Agreement {{agreement_no}} for {{property_name}}. Monthly rent {{monthly_rent}}.', 3, 0, 'Percentage', 0.00, '2026-07-08 19:38:15', '2026-07-16 13:14:18'),
(3, 20, 'RA-', 1, 'RR-', 1, 'both', '7,10,8,11,12,6', 1, 'Dear {{tenant_name}}, your rental agreement {{agreement_no}} is created for {{property_name}}. Monthly rent {{monthly_rent}}.', 1, 'Rental Agreement {{agreement_no}}', '<p>Dear {{tenant_name}},</p><p>Your rental agreement <strong>{{agreement_no}}</strong> has been created for <strong>{{property_name}}</strong>.</p><p>Monthly Rent: <strong>{{monthly_rent}}</strong></p>', 1, 'Rental Agreement {{agreement_no}} for {{property_name}}. Monthly rent {{monthly_rent}}.', 3, 0, 'Percentage', 0.00, '2026-06-30 17:43:33', '2026-07-08 19:34:47');
