INSERT INTO `emailtemplates` (`id`, `name`, `description`, `status`, `type`, `user_id`, `project_id`) VALUES
(1, 'Client Login Credentials', '<p>Dear $clientName,</p><p>Congratulations! Your $siteName account is now active.</p><p>Email Address : $email</p><p>Password: $password</p><p>If you need, you can reset your password at any time.</p><p>To get started, log on:<a href=\"$url\" target=\"_blank\">$url</a></p><p>If you have any questions or need assistance, please contact us.</p><p> </p><p>Best Regards,</p><p>$siteName</p><p>$contactNo</p>', 'Published', 'CLC', NULL, NULL),
(2, 'Client Forgot Password', '<p>Dear $clientName,</p><p>Please click the following link to finish forgot password:</p><p><a href=\"$url\" target=\"_blank\">$url</a></p><p><strong>Note: If the link does not open directly, please copy and paste the url into your internet browser.</strong></p><p>Verification Code: $code</p><p>Sincerely,</p><p>$siteName</p><p>$contactNo</p>', 'Published', 'CFP', NULL, NULL),
(3, 'Admin Forgot Password', '<p>Dear $name,</p><p>Please click the following link to finish forgot password:</p><p><a href=\"$url\" target=\"_blank\">$url</a></p><p><strong>Note: If the link does not open directly, please copy and paste the url into your internet browser.</strong></p><p>Verification Code: $code</p><p>Sincerely,</p><p>$siteName</p><p>$contactNo</p>', 'Published', 'AFP', NULL, NULL),
(4, 'Admin Forgot Username', '<p>Dear $name,</p><p>You have forgot User Name. your username is $userName</p><p>Sincerely,</p><p>$siteName</p><p>$contactNo</p>', 'Published', 'AFU', NULL, NULL),
(5, 'User Login Credentials', '<p>Dear $name,</p><p>Congratulations! Your $siteName account is now active.</p><p>Email Address : $email</p><p>Username : $userName</p><p>Password: $password</p><p>If you need, you can reset your password at any time.</p><p>To get started, log on:<a href=\"$url\" target=\"_blank\">$url</a></p><p>If you have any questions or need assistance, please contact us.</p><p> </p><p>Best Regards,</p><p>$siteName</p><p>$contactNo</p>', 'Published', 'ULC', NULL, NULL),
(6, 'Payment', '<p>Dear $clientName,</p>\n<p>Received $currency $amount ($amountWords) towards $paymentName paid on $date. The Recipt No. is <strong>$receiptNo</strong></p>\n<p><a href=\"$receiptUrl\" style=\"display:inline-block;background:#0b3d2e;color:#ffffff;text-decoration:none;padding:10px 16px;border-radius:5px;font-weight:bold;\">View / Print Receipt</a></p>\n<p>Sincerely,</p><p>$siteName</p><p>$contactNo</p>', 'Published', 'PAY', NULL, NULL),
(8, 'Inquiry', '<p>Dear $clientName,</p>\r\n<p>We have received your inquiry.</p>\r\n<p>If you want to activate your account in $siteName ,</p>\r\n<p>please go on to the link, <a href=\"http://192.168.1.100:88/order2006/admin/$url\" target=\"_blank\">$url</a>.</p>\r\n<p>Your email Id and password for $siteName is:</p>\r\n<p>Email Address : $email</p>\r\n<p>Password: $password</p>\r\n<p>Your  Verification Code: $code</p>\r\n<p>If you need, you can reset your password at any time.</p>\r\n<p>If you have any questions or need assistance, please contact us.</p>\r\n<p> </p>\r\n<p>Best Regards,</p>\r\n<p>$siteName</p>\r\n<p>$contactNo</p>', 'Published', 'INQ', NULL, NULL),
(9, 'Property not found.', '<p>While searching the below thing/s no property was found.</p>\r\n<p>Kindly have a look on it.</p>', 'Published', 'PNF', NULL, NULL),
(10, 'Client Registration', '<p>Hi, $memberName</p><p>Your signup email: $email</p><p>Your password: $password</p><p>Please click the following link to finish up registration:</p><p><a href=\"$url\" target=\"_blank\">$url</a></p><p><strong>Note: If the link does not open directly, please copy and paste the url into your internet browser.</strong></p><p>Verification Code: $code</p><p>Sincerely,</p><p>$siteName</p><p>$siteEmailContact</p>', 'Published', 'SRN', NULL, NULL),
(11, 'Re-send Verification', '<p>Hi, $memberName</p><p>Your signup email: $email</p><p>Please click the following link to finish up registration:</p><p><a href=\"$url\" target=\"_blank\">$url</a></p><p><strong>Note: If the link does not open directly, please copy and paste the url into your internet browser.</strong></p><p>Verification Code: $code</p><p>Sincerely,</p><p>$siteName</p><p>$siteEmailContact</p>', 'Published', 'RVN', NULL, NULL),
(12, 'Lead Default Email (LED)', '<p>Dear {{lead_name}},</p><p>Thank you for your interest in our project.</p><p><strong>Source:</strong> {{lead_source}}<br><strong>Follow-up:</strong> {{follow_up}}<br><strong>Remarks:</strong> {{remarks}}</p><p>Regards,<br>WHITE VILLAS</p>', 'Published', 'LED', NULL, NULL),
(13, 'Letter Issued Welcome Letter', '<p>Dear $clientName,</p><p>Your <strong>Welcome Letter</strong> has been issued.</p><p><strong>Reference No:</strong> $referenceNo<br><strong>Membership No:</strong> $invoiceNo<br><strong>Property:</strong> $propertyName<br><strong>Project:</strong> $projectName</p><p>You can view/print from: <a href=\"$url\" target=\"_blank\">$url</a></p><p>Regards,<br>$siteName<br>$contactNo</p>', 'Published', 'LWL', NULL, NULL),
(14, 'Letter Issued Booking Letter', '<p>Dear $clientName,</p><p>Your <strong>Booking Letter</strong> has been issued.</p><p><strong>Reference No:</strong> $referenceNo<br><strong>Membership No:</strong> $invoiceNo<br><strong>Property:</strong> $propertyName<br><strong>Project:</strong> $projectName</p><p>You can view/print from: <a href=\"$url\" target=\"_blank\">$url</a></p><p>Regards,<br>$siteName<br>$contactNo</p>', 'Published', 'LBK', NULL, NULL),
(15, 'Letter Issued Demarcation Letter', '<p>Dear $clientName,</p><p>Your <strong>Demarcation Letter</strong> has been issued.</p><p><strong>Reference No:</strong> $referenceNo<br><strong>Membership No:</strong> $invoiceNo<br><strong>Property:</strong> $propertyName<br><strong>Project:</strong> $projectName</p><p>You can view/print from: <a href=\"$url\" target=\"_blank\">$url</a></p><p>Regards,<br>$siteName<br>$contactNo</p>', 'Published', 'LDM', NULL, NULL),
(16, 'Letter Issued Design / Map Approval Letter', '<p>Dear $clientName,</p><p>Your <strong>Design / Map Approval Letter</strong> has been issued.</p><p><strong>Reference No:</strong> $referenceNo<br><strong>Membership No:</strong> $invoiceNo<br><strong>Property:</strong> $propertyName<br><strong>Project:</strong> $projectName</p><p>You can view/print from: <a href=\"$url\" target=\"_blank\">$url</a></p><p>Regards,<br>$siteName<br>$contactNo</p>', 'Published', 'LMP', NULL, NULL),
(17, 'Letter Issued NOC Letter', '<p>Dear $clientName,</p><p>Your <strong>NOC Letter</strong> has been issued.</p><p><strong>Reference No:</strong> $referenceNo<br><strong>Membership No:</strong> $invoiceNo<br><strong>Property:</strong> $propertyName<br><strong>Project:</strong> $projectName</p><p>You can view/print from: <a href=\"$url\" target=\"_blank\">$url</a></p><p>Regards,<br>$siteName<br>$contactNo</p>', 'Published', 'NOC', NULL, NULL),
(18, 'Letter Issued Allotment Letter', '<p>Dear $clientName,</p><p>Your <strong>Allotment Letter</strong> has been issued.</p><p><strong>Reference No:</strong> $referenceNo<br><strong>Membership No:</strong> $invoiceNo<br><strong>Property:</strong> $propertyName<br><strong>Project:</strong> $projectName</p><p>You can view/print from: <a href=\"$url\" target=\"_blank\">$url</a></p><p>Regards,<br>$siteName<br>$contactNo</p>', 'Published', 'LAT', NULL, NULL),
(19, 'Letter Issued Payment Demand Notice', '<p>Dear $clientName,</p><p>Your <strong>Payment Demand Notice</strong> has been issued.</p><p><strong>Reference No:</strong> $referenceNo<br><strong>Membership No:</strong> $invoiceNo<br><strong>Property:</strong> $propertyName<br><strong>Project:</strong> $projectName</p><p>You can view/print from: <a href=\"$url\" target=\"_blank\">$url</a></p><p>Regards,<br>$siteName<br>$contactNo</p>', 'Published', 'PDN', NULL, NULL),
(20, 'Letter Issued Payment Acknowledgement', '<p>Dear $clientName,</p><p>Your <strong>Payment Acknowledgement</strong> has been issued.</p><p><strong>Reference No:</strong> $referenceNo<br><strong>Membership No:</strong> $invoiceNo<br><strong>Property:</strong> $propertyName<br><strong>Project:</strong> $projectName</p><p>You can view/print from: <a href=\"$url\" target=\"_blank\">$url</a></p><p>Regards,<br>$siteName<br>$contactNo</p>', 'Published', 'PAC', NULL, NULL),
(21, 'Letter Issued Possession Letter', '<p>Dear $clientName,</p><p>Your <strong>Possession Letter</strong> has been issued.</p><p><strong>Reference No:</strong> $referenceNo<br><strong>Membership No:</strong> $invoiceNo<br><strong>Property:</strong> $propertyName<br><strong>Project:</strong> $projectName</p><p>You can view/print from: <a href=\"$url\" target=\"_blank\">$url</a></p><p>Regards,<br>$siteName<br>$contactNo</p>', 'Published', 'POS', NULL, NULL),
(22, 'Letter Issued Transfer / Mutation Letter', '<p>Dear $clientName,</p><p>Your <strong>Transfer / Mutation Letter</strong> has been issued.</p><p><strong>Reference No:</strong> $referenceNo<br><strong>Membership No:</strong> $invoiceNo<br><strong>Property:</strong> $propertyName<br><strong>Project:</strong> $projectName</p><p>You can view/print from: <a href=\"$url\" target=\"_blank\">$url</a></p><p>Regards,<br>$siteName<br>$contactNo</p>', 'Published', 'TRF', NULL, NULL),
(23, 'Letter Issued Cancellation Letter', '<p>Dear $clientName,</p><p>Your <strong>Cancellation Letter</strong> has been issued.</p><p><strong>Reference No:</strong> $referenceNo<br><strong>Membership No:</strong> $invoiceNo<br><strong>Property:</strong> $propertyName<br><strong>Project:</strong> $projectName</p><p>You can view/print from: <a href=\"$url\" target=\"_blank\">$url</a></p><p>Regards,<br>$siteName<br>$contactNo</p>', 'Published', 'CAN', NULL, NULL),
(24, 'Letter Issued Generic', '<p>Dear $clientName,</p><p>Your <strong>$letterType</strong> has been issued.</p><p><strong>Reference No:</strong> $referenceNo<br><strong>Membership No:</strong> $invoiceNo<br><strong>Property:</strong> $propertyName</p><p><a href=\"$url\" target=\"_blank\">View Letter</a></p><p>Regards,<br>$siteName</p>', 'Published', 'LIS', NULL, NULL),
(25, 'Letter Cancel Notification', '<p>Dear $clientName,</p><p>Your <strong>$letterType</strong> has been cancelled.</p><p><strong>Reference No:</strong> $referenceNo<br><strong>Membership No:</strong> $invoiceNo<br><strong>Property:</strong> $propertyName</p><p>For details please contact: $contactNo</p><p>Regards,<br>$siteName</p>', 'Published', 'LCN', NULL, NULL),
(26, 'Letter Issued Deal Charges Notice', '<p>Dear $clientName,</p><p>Your <strong>Deal Charges Notice</strong> has been issued.</p><p><strong>Reference No:</strong> $referenceNo<br><strong>Membership No:</strong> $invoiceNo<br><strong>Property:</strong> $propertyName<br><strong>Project:</strong> $projectName</p><p>You can view/print from: <a href=\"$url\" target=\"_blank\">$url</a></p><p>Regards,<br>$siteName<br>$contactNo</p>', 'Published', 'LCH', NULL, NULL),
(27, 'Overdue Payment Reminder Email', '<!DOCTYPE html>\n<html>\n<head>\n  <meta charset=\"UTF-8\">\n  <title>Overdue Payment Reminder</title>\n</head>\n<body style=\"margin:0; padding:0; background-color:#f4f6f8; font-family:Arial, Helvetica, sans-serif; color:#222;\">\n\n  <div style=\"max-width:700px; margin:0 auto; background-color:#ffffff; border-radius:10px; overflow:hidden; border:1px solid #e5e5e5;\">\n\n    <div style=\"background-color:#0b3d2e; color:#ffffff; text-align:center; padding:25px 20px;\">\n      <img src=\"{{AGENCY_LOGO_URL}}\" alt=\"{{AGENCY_NAME}} Logo\" style=\"width:90px; height:90px; object-fit:contain; background-color:#ffffff; border-radius:50%; padding:8px; margin-bottom:12px;\">\n      <h1 style=\"margin:0; font-size:28px;\">{{AGENCY_NAME}}</h1>\n      <p style=\"margin:8px 0 0; font-size:15px;\">{{AGENCY_TAGLINE}}</p>\n      <p style=\"margin:10px 0 0; font-size:13px; line-height:1.5; color:#e7f5ef;\">\n        ? {{AGENCY_ADDRESS}}<br>\n        ? {{AGENCY_CONTACT_NO}} &nbsp; | &nbsp; ✉️ {{AGENCY_EMAIL}}\n      </p>\n    </div>\n\n    <div style=\"padding:30px 25px;\">\n\n      <h2 style=\"color:#b00020; margin-top:0;\">? Overdue Payment Reminder</h2>\n\n      <p style=\"font-size:16px; line-height:1.6;\">Dear <strong>{{CLIENT_NAME}}</strong>,</p>\n\n      <p style=\"font-size:16px; line-height:1.6;\">We would like to remind you that your installment payment is currently overdue. Kindly clear the pending amount at your earliest convenience to avoid any further delay, penalties, or additional charges.</p>\n\n      <table width=\"100%\" cellpadding=\"10\" cellspacing=\"0\" style=\"border-collapse:collapse; margin-top:20px; font-size:15px;\">\n        <tr style=\"background-color:#f8f8f8;\">\n          <td style=\"border:1px solid #ddd;\"><strong>?️ Membership No:</strong></td>\n          <td style=\"border:1px solid #ddd;\">{{MEMBERSHIP_NO}}</td>\n        </tr>\n        <tr>\n          <td style=\"border:1px solid #ddd;\"><strong>? Property/File:</strong></td>\n          <td style=\"border:1px solid #ddd;\">{{PROPERTY_FILE_NO}}</td>\n        </tr>\n        <tr style=\"background-color:#f8f8f8;\">\n          <td style=\"border:1px solid #ddd;\"><strong>? Installment Status:</strong></td>\n          <td style=\"border:1px solid #ddd;\">{{INSTALLMENT_STATUS}}</td>\n        </tr>\n        <tr>\n          <td style=\"border:1px solid #ddd;\"><strong>? Due Date:</strong></td>\n          <td style=\"border:1px solid #ddd;\"><strong>{{DUE_DATE}}</strong></td>\n        </tr>\n        <tr style=\"background-color:#f8f8f8;\">\n          <td style=\"border:1px solid #ddd;\"><strong>? Installment Amount:</strong></td>\n          <td style=\"border:1px solid #ddd;\"><strong>{{INSTALLMENT_AMOUNT}}</strong></td>\n        </tr>\n      </table>\n\n      <div style=\"background-color:#fff8e1; border:2px solid #f0b429; border-radius:10px; padding:20px; margin-top:25px; text-align:center;\">\n        <h3 style=\"margin-top:0; color:#8a5a00;\">? Bank Account Details</h3>\n        <p style=\"font-size:15px; margin:8px 0;\"><strong>Bank Name:</strong> {{BANK_NAME}}</p>\n        <p style=\"font-size:15px; margin:8px 0;\"><strong>Account Title:</strong> {{ACCOUNT_TITLE}}</p>\n        <p style=\"font-size:22px; font-weight:bold; color:#0b3d2e; margin:15px 0;\">Account No: <span>{{ACCOUNT_NO}}</span></p>\n        <p style=\"font-size:15px; margin:8px 0;\"><strong>IBAN:</strong> {{IBAN}}</p>\n        <p style=\"font-size:13px; color:#666; margin-top:12px;\">After payment, please share your payment screenshot/receipt for confirmation.</p>\n      </div>\n\n      <div style=\"margin-top:25px; background-color:#f1f5f9; padding:18px; border-radius:8px;\">\n        <h3 style=\"margin-top:0;\">? Overdue Summary</h3>\n        <p style=\"margin:6px 0;\">• Total overdue installments: <strong>{{TOTAL_OVERDUE_INSTALLMENTS}}</strong></p>\n        <p style=\"margin:6px 0;\">• Total overdue amount: <strong>{{TOTAL_OVERDUE_AMOUNT}}</strong></p>\n        <p style=\"margin:6px 0;\">• Oldest overdue age: <strong>{{OLDEST_OVERDUE_AGE}}</strong></p>\n      </div>\n\n      <p style=\"font-size:15px; line-height:1.6; margin-top:25px;\">✅ If you have already made the payment, please ignore this message or share the payment proof for confirmation.</p>\n\n      <p style=\"font-size:15px; line-height:1.6;\">? <strong>Contact:</strong> {{AGENCY_CONTACT_NO}}</p>\n\n      <p style=\"font-size:16px; margin-top:25px;\">Regards,<br><strong>{{AGENCY_NAME}}</strong></p>\n\n    </div>\n\n    <div style=\"background-color:#0b3d2e; color:#ffffff; text-align:center; padding:20px; font-size:14px; line-height:1.6;\">\n      <strong>{{AGENCY_NAME}}</strong><br>\n      ? Office Address: {{AGENCY_ADDRESS}}<br>\n      ? Contact: {{AGENCY_CONTACT_NO}}<br>\n      ☎️ UAN: {{AGENCY_UAN}}<br>\n      ✉️ Email: {{AGENCY_EMAIL}}<br>\n      ? Website: {{AGENCY_WEBSITE}}\n    </div>\n\n  </div>\n\n</body>\n</html>', 'Published', 'PRE', NULL, NULL),
(28, 'Before Due Payment Reminder Email', '<!DOCTYPE html>\n<html>\n<head>\n  <meta charset=\"UTF-8\">\n  <title>Installment Payment Reminder</title>\n</head>\n<body style=\"margin:0; padding:0; background-color:#f4f6f8; font-family:Arial, Helvetica, sans-serif; color:#222;\">\n\n  <div style=\"max-width:700px; margin:0 auto; background-color:#ffffff; border-radius:10px; overflow:hidden; border:1px solid #e5e5e5;\">\n\n    <div style=\"background-color:#0b3d2e; color:#ffffff; text-align:center; padding:25px 20px;\">\n      <img src=\"{{AGENCY_LOGO_URL}}\" alt=\"{{AGENCY_NAME}} Logo\" style=\"width:90px; height:90px; object-fit:contain; background-color:#ffffff; border-radius:50%; padding:8px; margin-bottom:12px;\">\n      <h1 style=\"margin:0; font-size:28px;\">{{AGENCY_NAME}}</h1>\n      <p style=\"margin:8px 0 0; font-size:15px;\">{{AGENCY_TAGLINE}}</p>\n      <p style=\"margin:10px 0 0; font-size:13px; line-height:1.5; color:#e7f5ef;\">\n        ? {{AGENCY_ADDRESS}}<br>\n        ? {{AGENCY_CONTACT_NO}} &nbsp; | &nbsp; ✉️ {{AGENCY_EMAIL}}\n      </p>\n    </div>\n\n    <div style=\"padding:30px 25px;\">\n\n      <h2 style=\"color:#0b3d2e; margin-top:0;\">? Installment Payment Reminder</h2>\n\n      <p style=\"font-size:16px; line-height:1.6;\">Dear <strong>{{CLIENT_NAME}}</strong>,</p>\n\n      <p style=\"font-size:16px; line-height:1.6;\">We would like to remind you that your installment payment is coming due. Kindly arrange the payment before the due date to avoid any delay, penalties, or additional charges.</p>\n\n      <table width=\"100%\" cellpadding=\"10\" cellspacing=\"0\" style=\"border-collapse:collapse; margin-top:20px; font-size:15px;\">\n        <tr style=\"background-color:#f8f8f8;\">\n          <td style=\"border:1px solid #ddd;\"><strong>?️ Membership No:</strong></td>\n          <td style=\"border:1px solid #ddd;\">{{MEMBERSHIP_NO}}</td>\n        </tr>\n        <tr>\n          <td style=\"border:1px solid #ddd;\"><strong>? Property/File:</strong></td>\n          <td style=\"border:1px solid #ddd;\">{{PROPERTY_FILE_NO}}</td>\n        </tr>\n        <tr style=\"background-color:#f8f8f8;\">\n          <td style=\"border:1px solid #ddd;\"><strong>? Installment Status:</strong></td>\n          <td style=\"border:1px solid #ddd;\">{{INSTALLMENT_STATUS}}</td>\n        </tr>\n        <tr>\n          <td style=\"border:1px solid #ddd;\"><strong>? Due Date:</strong></td>\n          <td style=\"border:1px solid #ddd;\"><strong>{{DUE_DATE}}</strong></td>\n        </tr>\n        <tr style=\"background-color:#f8f8f8;\">\n          <td style=\"border:1px solid #ddd;\"><strong>? Installment Amount:</strong></td>\n          <td style=\"border:1px solid #ddd;\"><strong>{{INSTALLMENT_AMOUNT}}</strong></td>\n        </tr>\n      </table>\n\n      <div style=\"background-color:#fff8e1; border:2px solid #f0b429; border-radius:10px; padding:20px; margin-top:25px; text-align:center;\">\n        <h3 style=\"margin-top:0; color:#8a5a00;\">? Bank Account Details</h3>\n        <p style=\"font-size:15px; margin:8px 0;\"><strong>Bank Name:</strong> {{BANK_NAME}}</p>\n        <p style=\"font-size:15px; margin:8px 0;\"><strong>Account Title:</strong> {{ACCOUNT_TITLE}}</p>\n        <p style=\"font-size:22px; font-weight:bold; color:#0b3d2e; margin:15px 0;\">Account No: <span>{{ACCOUNT_NO}}</span></p>\n        <p style=\"font-size:15px; margin:8px 0;\"><strong>IBAN:</strong> {{IBAN}}</p>\n        <p style=\"font-size:13px; color:#666; margin-top:12px;\">After payment, please share your payment screenshot/receipt for confirmation.</p>\n      </div>\n\n\n\n      <p style=\"font-size:15px; line-height:1.6; margin-top:25px;\">✅ If you have already made the payment, please ignore this message or share the payment proof for confirmation.</p>\n\n      <p style=\"font-size:15px; line-height:1.6;\">? <strong>Contact:</strong> {{AGENCY_CONTACT_NO}}</p>\n\n      <p style=\"font-size:16px; margin-top:25px;\">Regards,<br><strong>{{AGENCY_NAME}}</strong></p>\n\n    </div>\n\n    <div style=\"background-color:#0b3d2e; color:#ffffff; text-align:center; padding:20px; font-size:14px; line-height:1.6;\">\n      <strong>{{AGENCY_NAME}}</strong><br>\n      ? Office Address: {{AGENCY_ADDRESS}}<br>\n      ? Contact: {{AGENCY_CONTACT_NO}}<br>\n      ☎️ UAN: {{AGENCY_UAN}}<br>\n      ✉️ Email: {{AGENCY_EMAIL}}<br>\n      ? Website: {{AGENCY_WEBSITE}}\n    </div>\n\n  </div>\n\n</body>\n</html>', 'Published', 'PDE', NULL, NULL),
(29, 'Letter Issued Final Cancellation', '<p>Dear $clientName,</p><p>Your <strong>Final Cancellation</strong> has been issued.</p><p><strong>Reference No:</strong> $referenceNo<br><strong>Membership No:</strong> $invoiceNo<br><strong>Property:</strong> $propertyName<br><strong>Project:</strong> $projectName</p><p>You can view/print from: <a href=\"$url\" target=\"_blank\">$url</a></p><p>Regards,<br>$siteName<br>$contactNo</p>', 'Published', 'FCL', NULL, NULL),
(30, 'Letter Issued Deal Agreement Ashtam', '<p>Dear $clientName,</p><p>Your <strong>Deal Agreement Ashtam</strong> has been issued.</p><p><strong>Reference No:</strong> $referenceNo<br><strong>Membership No:</strong> $invoiceNo<br><strong>Property:</strong> $propertyName<br><strong>Project:</strong> $projectName</p><p>You can view/print from: <a href=\"$url\" target=\"_blank\">$url</a></p><p>Regards,<br>$siteName<br>$contactNo</p>', 'Published', 'AGR', NULL, NULL),
(31, 'Expense Approval Required - $referenceNo', '<div style=\"font-family:Arial,sans-serif;color:#172033;max-width:820px;margin:0 auto\"><div style=\"background:#0b2344;color:#fff;padding:18px 22px\"><h2 style=\"margin:0;font-size:20px\">$emailHeading</h2><p style=\"margin:5px 0 0;color:#dbeafe\">$emailIntro</p></div><div style=\"padding:20px 22px;border:1px solid #dbe3ee;border-top:0\"><p>Dear <strong>$recipientName</strong>,</p><p>$emailMessage</p><p style=\"margin:18px 0\"><a href=\"$approvalUrl\" style=\"background:#2563eb;color:#fff;padding:11px 18px;text-decoration:none;font-weight:bold\">Open Approval Queue</a> <a href=\"$voucherUrl\" style=\"color:#2563eb;margin-left:12px\">Print Voucher</a></p>$voucherHtml<p style=\"color:#64748b;font-size:12px;margin-top:18px\">This is an automated approval notification from $siteName.</p></div></div>', 'Published', 'EAM', NULL, NULL),
(32, 'Final Expense Approval Required - $referenceNo', '<div style=\"font-family:Arial,sans-serif;color:#172033;max-width:820px;margin:0 auto\"><div style=\"background:#0b2344;color:#fff;padding:18px 22px\"><h2 style=\"margin:0;font-size:20px\">$emailHeading</h2><p style=\"margin:5px 0 0;color:#dbeafe\">$emailIntro</p></div><div style=\"padding:20px 22px;border:1px solid #dbe3ee;border-top:0\"><p>Dear <strong>$recipientName</strong>,</p><p>$emailMessage</p><p style=\"margin:18px 0\"><a href=\"$approvalUrl\" style=\"background:#2563eb;color:#fff;padding:11px 18px;text-decoration:none;font-weight:bold\">Open Approval Queue</a> <a href=\"$voucherUrl\" style=\"color:#2563eb;margin-left:12px\">Print Voucher</a></p>$voucherHtml<p style=\"color:#64748b;font-size:12px;margin-top:18px\">This is an automated approval notification from $siteName.</p></div></div>', 'Published', 'EAC', NULL, NULL);
