INSERT INTO `installment_sync_settings` (`id`, `project_id`, `calendar_sync_enabled`, `calendar_reminder_days`, `calendar_alarm_time`, `early_payment_calculator_enabled`, `early_payment_discount_mode`, `early_payment_discount_percent`, `early_payment_annual_rate`, `early_payment_min_installments`, `early_payment_terms_en`, `early_payment_terms_ur`, `created`, `modified`, `require_all_overdue`, `allow_overdue_discount_package`, `overdue_special_discount_percent`) VALUES
(1, 0, 1, '7,3,1', '09:00', 1, 'percentage', 2.00, 3.00, 6, 'Early payment discount is applicable on scheduled advance installments upon society management approval. Terms & conditions apply.', 'قبل از وقت پیشگی اقساط کی ادائیگی پر سوسائٹی کے مروجہ قوانین کے تحت خصوصی رعایت قابل اطلاق ہوگی۔', '2026-08-31 18:33:16', '2026-08-31 23:40:26', 1, 1, 0.00);
INSERT INTO `leadbot_event_settings` (`id`, `project_id`, `user_id`, `event_key`, `event_label`, `event_description`, `whatsapp_enabled`, `sms_enabled`, `whatsapp_template`, `sms_template`, `notify_agent`, `notify_client`, `notify_admin`, `created`, `modified`) VALUES
(1, 0, 0, 'lead_assignment', 'New Lead Assignment', 'Dispatched immediately when a lead is assigned or transferred to an agent', 1, 1, '? *New Lead Assigned!*\r\n\r\nHello {agent_name},\r\nA new lead has been assigned to you:\r\n? *Lead:* {client_name}\r\n? *Phone:* {phone}\r\n? *Project:* {project_name}\r\n\r\nPlease contact the client promptly.', 'New Lead: {client_name} ({phone}) assigned to you for {project_name}. Please follow up promptly.', 1, 0, 0, '2026-11-22 16:13:01', '2026-11-22 19:20:18'),
(2, 0, 0, 'facebook_sync', 'Facebook Lead Auto-Sync Alert', 'Alerts agents & CRM team when a new lead arrives from Facebook Ads Instant Forms', 1, 0, '⚡ *New Facebook Lead Synced!*\r\n\r\n? *Name:* {client_name}\r\n? *Phone:* {phone}\r\n? *Campaign:* {project_name}\r\n\r\nAssigned to: {agent_name}', 'FB Lead Synced: {client_name} ({phone}) assigned to {agent_name}.', 1, 0, 0, '2026-11-22 16:13:01', '2026-11-22 19:20:18'),
(3, 0, 0, 'followup_reminder', 'Upcoming Follow-up Reminder', 'Advance alert dispatched to consultant before scheduled client follow-up time', 1, 1, '⏰ *Follow-up Reminder*\r\n\r\nHi {agent_name},\r\nYou have an upcoming follow-up with:\r\n? *Client:* {client_name}\r\n? *Phone:* {phone}\r\n? *Scheduled Time:* {due_date}\r\n? *Remarks:* {remarks}', 'Follow-up Reminder: Call {client_name} ({phone}) at {due_date}. Remarks: {remarks}', 1, 0, 0, '2026-11-22 16:13:01', '2026-11-22 19:20:18'),
(4, 0, 0, 'overdue_alert', 'Overdue Follow-up Warning', 'Dispatched when a scheduled follow-up has passed without status remarks', 1, 0, '⚠️ *Overdue Follow-up Warning*\r\n\r\nDear {agent_name},\r\nA follow-up with {client_name} ({phone}) is past due.\r\nPlease update client remarks in White Villas CRM as soon as possible.', 'Overdue: Follow-up with {client_name} ({phone}) is pending remarks. Please update CRM.', 1, 0, 0, '2026-11-22 16:13:01', '2026-11-22 19:20:18'),
(5, 0, 0, 'deal_closed', 'Deal Closed / Booking Confirmed', 'Alerts management and agency leaders when a property deal or booking is confirmed', 1, 1, '? *Congratulations! Deal Closed!*\r\n\r\n? *Project:* {project_name}\r\n?️ *Deal:* {deal_title}\r\n? *Client:* {client_name}\r\n? *Agent:* {agent_name}\r\n? *Amount:* {amount}\r\n\r\nGreat work team!', 'Deal Confirmed: {deal_title} for {client_name} by {agent_name}. Amount: {amount}.', 1, 1, 0, '2026-11-22 16:13:01', '2026-11-22 19:20:18'),
(6, 0, 0, 'expense_approval', 'Expense Approval Request', 'Notifies approving managers when an expense voucher is submitted by accountants', 1, 0, '? *Expense Approval Request*\r\n\r\nAn expense voucher requires your review:\r\n? *Title:* {deal_title}\r\n? *Amount:* {amount}\r\n? *Submitted By:* {agent_name}\r\n\r\nPlease check CRM to approve or reject.', 'Expense Request: {deal_title} for {amount} submitted by {agent_name}.', 0, 0, 0, '2026-11-22 16:13:01', '2026-11-22 19:20:18'),
(7, 0, 0, 'payment_received', 'Payment Accounts & Installment Posting Notice', 'Alerts accountants and agency managers when deal receipts or vouchers are posted', 1, 1, '? *Payment Received Confirmation*\r\n\r\nDear {client_name},\r\nWe have received your payment:\r\n? *Amount:* {amount}\r\n? *Project:* {project_name}\r\n?️ *Deal:* {deal_title}\r\n? *Date:* {due_date}\r\n\r\nThank you for choosing White Villas!', 'White Villas: Payment of {amount} received for {project_name} ({deal_title}). Thank you!', 0, 1, 0, '2026-11-22 16:13:01', '2026-11-22 19:20:18'),
(8, 0, 0, 'broadcast', 'Custom Admin Broadcast Notice', 'Custom announcements dispatched by Super Admin or Agency Manager', 1, 1, '? *Official Announcement - White Villas*\r\n\r\n{remarks}\r\n\r\nSent by Administration.', 'White Villas Announcement: {remarks}', 0, 0, 0, '2026-11-22 16:13:01', '2026-11-22 19:20:19'),
(9, 0, 0, 'client_welcome', 'Client Welcome Message', 'Sent to newly registered leads or property inquiry clients upon registration', 1, 1, '? *Welcome to White Villas!*\r\n\r\nHello {client_name},\r\nThank you for your interest in {project_name}.\r\nYour dedicated property consultant is *{agent_name}* ({phone}).\r\nWe are here to assist you with complete details and property tours.', 'Welcome to White Villas! Your property consultant is {agent_name} ({phone}). We will contact you shortly.', 0, 1, 0, '2026-11-22 16:13:01', '2026-11-22 19:20:18'),
(10, 20, 0, 'lead_assignment', 'New Lead Assignment', 'Dispatched immediately when a lead is assigned or transferred to an agent', 1, 1, '???? *New Lead Assigned!*\nHello {agent_name}, {client_name} ({phone}) is assigned to you.', 'New Lead: {client_name} ({phone}) assigned to you for {project_name}.', 0, 0, 0, '2026-11-22 11:49:31', '2026-11-22 17:12:45'),
(11, 0, 0, 'site_visit_scheduled', 'Site Visit & Property Tour Confirmed', 'Dispatched to client & agent when a property tour / physical site visit is booked', 1, 1, '? *Property Tour & Site Visit Confirmed*\r\n\r\nHello {client_name},\r\nYour site visit for *{project_name}* has been confirmed:\r\n? *Scheduled Date:* {due_date} {time}\r\n? *Property Guide:* {agent_name} ({phone})\r\n? *Meeting Point:* White Villas Site Office\r\n\r\nWe look forward to welcoming you!', 'Site Visit Confirmed: {project_name} visit on {due_date} {time}. Guide: {agent_name} ({phone}). White Villas.', 1, 1, 0, '2026-11-22 17:12:45', '2026-11-22 19:20:18'),
(12, 0, 0, 'payment_posted', 'Deal Installment Payment Receipt Confirmation', 'Dispatched immediately when an installment or booking payment is posted by accounts', 1, 0, '? *Official Payment Receipt Confirmation*\r\n\r\nDear {client_name},\r\nWe have successfully received and verified your payment:\r\n? *Amount:* PKR {amount}\r\n? *Project:* {project_name}\r\n?️ *Deal / Unit:* {deal_title}\r\n? *Receipt Date:* {date}\r\n\r\nThank you for choosing White Villas!', 'White Villas Receipt: Payment of PKR {amount} received for {project_name} ({deal_title}) on {date}. Thank you!', 0, 1, 0, '2026-11-22 17:12:45', '2026-11-22 19:20:18'),
(13, 0, 0, 'installment_reminder', 'Upcoming Installment Due Reminder', 'Auto-reminder sent to client 3 to 7 days before an installment due date', 1, 0, '? *Upcoming Installment Due Reminder*\r\n\r\nDear {client_name},\r\nThis is a friendly reminder that your installment for *{project_name}* ({deal_title}) of *PKR {amount}* is due on *{due_date}*.\r\n\r\nPlease deposit to company official bank accounts to maintain prompt status.\r\nThank you!', 'White Villas Reminder: Dear {client_name}, installment of PKR {amount} for {deal_title} is due on {due_date}. Thank you.', 0, 1, 0, '2026-11-22 17:12:45', '2026-11-22 19:20:18'),
(14, 0, 0, 'installment_overdue', 'Overdue Installment Recovery Warning', 'Dispatched to clients when scheduled installments pass due date without payment', 1, 0, '⚠️ *Urgent: Overdue Installment Notice*\r\n\r\nDear {client_name},\r\nYour installment of *PKR {amount}* for *{project_name}* ({deal_title}) was due on *{due_date}* and is now overdue.\r\n\r\nPlease clear the outstanding dues immediately or contact your recovery manager to submit your promise to pay.', 'Overdue Notice: Dear {client_name}, installment of PKR {amount} for {deal_title} is past due ({due_date}). Please clear immediately. White Villas.', 0, 1, 0, '2026-11-22 17:12:45', '2026-11-22 19:20:18'),
(15, 0, 0, 'deal_transfer', 'Ownership Transfer Notification', 'Dispatched when property plot/villa ownership transfer is approved & processed', 1, 1, '? *Property Ownership Transfer Confirmation*\r\n\r\nDear {client_name},\r\nThe ownership transfer for *{deal_title}* in *{project_name}* has been successfully processed and verified.\r\n\r\nOfficial transfer documentation is now ready at the White Villas Transfer Office.', 'White Villas: Ownership transfer for {deal_title} in {project_name} has been completed successfully.', 0, 1, 0, '2026-11-22 17:12:45', '2026-11-22 19:20:18'),
(16, 0, 0, 'balloting_result', 'Plot Balloting & Allocation Alert', 'Notifies buyers when balloting results are finalized and plot numbers allotted', 1, 1, '? *Plot Balloting & Allotment Result*\r\n\r\nDear {client_name},\r\nCongratulations! Balloting for *{project_name}* has been conducted:\r\n?️ *Deal / File:* {deal_title}\r\n? *Allotted Unit / Plot:* {remarks}\r\n\r\nWelcome to your new address at White Villas!', 'Balloting Result: Dear {client_name}, your plot for {deal_title} in {project_name} is: {remarks}. Congratulations! White Villas.', 0, 1, 0, '2026-11-22 17:12:45', '2026-11-22 19:20:18'),
(17, 0, 0, 'letter_issued', 'Official Letter Issuance (Allotment / Possession / NOC)', 'Dispatched when an official Allotment, Possession, or NOC Letter is generated', 1, 1, '? *Official Real Estate Letter Ready*\r\n\r\nDear {client_name},\r\nYour official *{title}* for *{project_name}* ({deal_title}) has been issued and verified.\r\n\r\nPlease visit the head office or contact your consultant {agent_name} ({phone}) to collect your original letter.', 'White Villas: Your official {title} for {project_name} ({deal_title}) has been issued. Contact: {phone}.', 0, 1, 0, '2026-11-22 17:12:45', '2026-11-22 19:20:18'),
