INSERT INTO `smssettings` (`id`, `api`, `username`, `password`, `senderid`, `husername`, `hpassword`, `hsenderid`, `hmobile`, `hmessage`, `type`, `gateway_type`, `is_leadbot_default`) VALUES
(1, 'http://sms.alriazdevelopers.com/services/send.php', '1', '3bfccea8319461dd7f1d97d60f1fead9b3ade365', 'sms', 'option', 'key', 'type', 'number', 'message', 'Get', 'leadbot', 1);
INSERT INTO `smstemplates` (`id`, `name`, `description`, `status`, `type`, `user_id`, `project_id`) VALUES
(1, 'Client Login Credentials', 'Dear $clientName, Your $siteName customer account is now active. Email: $email Password: $password login at our Web portal :$url/Clients/login Best Regards, $siteName', 'Published', 'CLC', NULL, NULL),
(2, 'Client Forgot Password', 'Dear $clientName, Website: $url Verification Code: $code Sincerely, $siteName', 'Published', 'CFP', NULL, NULL),
(3, 'Admin Forgot Password', 'Dear $name, Website: $url Verification Code: $code Sincerely, $siteName', 'Published', 'AFP', NULL, NULL),
(4, 'Admin Forgot Username', 'Dear $name, You have forgot User Name. Your username is $userName Sincerely, $siteName', 'Published', 'AFU', NULL, NULL),
(5, 'User Login Credentials', 'Dear $name,\r\nWe are thrilled to have you as a new Agent at our prestigious community. Congratulations on securing your place in this vibrant and thriving city.\r\n Your $siteName account is now active. Email: $email Uername: $userName Password: $password Website:$url Best Regards, $siteName', 'Published', 'ULC', NULL, NULL),
(6, 'Invoice Demand Letter', 'Dear $clientName Your Payment is due on $dueDate. Please pay your amount of Rs. $amount Plus Service  & Tax amount if applicable. Transfer of funds favoring  Account Title:\" WHITE VILLAS\" UBL  Account# 0773-310485346\r\n IBAN: PK50UNIL0109000310485346\r\nSincerely,\r\n$siteName .\r\n', 'Published', 'IDL', NULL, NULL),
(7, 'Payment', 'Dear $clientName, Received $currency $amount ($amountWords) towards $paymentName paid on $date. The Recipt No. is $receiptNo\r\nFrom, White Villas Lahore', 'Published', 'PAY', NULL, NULL),
(8, 'Client Registration', 'Hi, $memberName Email: $email Password: $password Website: $url Verification Code: $code Sincerely, $siteName', 'Published', 'SRN', NULL, NULL),
(9, 'Re-send Verification', 'Hi, $memberName Email: $email Website: $url Verification Code: $code Sincerely, $siteName', 'Published', 'RVN', NULL, NULL),
(10, 'Inquiry', 'Dear $clientName, We have received your inquiry message about property:$propertyid Email: $email Password: $password Website: $url Verification Code: $code Sincerely, $siteName', 'Published', 'INQ', NULL, NULL),
(11, 'Leads SMS', 'A Salaam-O-Alikum Sir\r\nWe received your query for buying 4kanal Farmhouse land in Islamabad.we are here to assist your for further details.', 'Published', NULL, NULL, NULL),
(12, 'Brocker Message', 'اسلام علیکم کیپیٹل آئس لیڈ سٹی میں خوش آمدید $agentname\r\n آپ کو اطلاع دی جاتی ہے کہ آپ نو جو بھی فائلز کلوز کروائی ہیں اپنے کسٹمرز کو مطلع کریں کہ آپنی قسط ادا کریں۔', 'Published', NULL, NULL, NULL),
(13, 'White Villas sms', 'Aslam-O-Alikum  %name%.\r\nLahore Multan Road pr installments pay Villa Khridna chty hain 3 year Payement plan 10% pr Booking . wo bhi onground plots pr ,White Villas Lahore\r\n03394080002', 'Published', NULL, NULL, NULL),
(14, 'Client Installments allert', 'WVL Qist Yaddehani: Aziz $clientName, Aapki mahana Qist ki due date [$dueDate] hai. Required Amount: PKR [$installmentAmount]. Late fee se bachne ke liye waqt par pay karein. Payment ho chuki hai to ignore karein. Shukriya. $siteName. Call: 03391101156.', 'Published', NULL, NULL, NULL),
(15, 'Installment Reminder sms', 'محترم $clientName،\r\nآپ کی قسط/ادائیگی $dueDate تک واجب الادا ہے۔\r\nبراہِ کرم روپے $amount بمعہ سروس چارجز اور ٹیکس (اگر لاگو ہوں) بروقت ادا فرما دیں۔\r\n\r\nادائیگی کی تفصیل:\r\nاکاؤنٹ ٹائٹل: WHITE VILLAS\r\nبینک: UBL\r\nاکاؤنٹ نمبر: 0773-310485346\r\nIBAN: PK50UNIL0109000310485346\r\n\r\nاگر آپ ادائیگی پہلے ہی کر چکے ہیں تو براہِ کرم اس پیغام کو نظر انداز کریں۔\r\n\r\nشکریہ،\r\n$siteName انتظامیہ', 'Published', NULL, NULL, NULL),
(16, 'Payment Reminder', 'محترم خریدار،\r\nwhite villas\r\nلاہور کی جانب سے اطلاع دی جاتی ہے کہ  آپ کی ماہانہ قسط کی ادائیگی واجب الادا ہے۔\r\nآخری تاریخ 2025-12-15سے پہلے ادا کریں تاکہ فائل میں تاخیر یا جرمانہ نہ لگے۔\r\nادائیگی بینک، آن لائن یا دفتر میں کی جا سکتی ہے۔\r\nرابطہ: 03391101165\r\n03391101156-\r\nشکریہ\r\n', 'Published', NULL, NULL, NULL),
(17, 'Lead Default SMS (LED)', 'Dear {{lead_name}}, this is a follow-up from WHITE VILLAS. Source: {{lead_source}}. Follow-up: {{follow_up}}. Remarks: {{remarks}}', 'Published', 'LED', NULL, NULL),
