INSERT INTO `system_modules` (`id`, `slug`, `name`, `description`, `version`, `author`, `author_url`, `icon`, `status`, `is_system`, `menu_config`, `config_data`, `installed_at`, `updated_at`) VALUES
(2, 'RealEstateTheme', 'Real Estate Pro Theme', 'Luxury Frontend Theme inspired by Ramada & White Alpine Lodges with Hero Video, Top Header Toggle, Interactive Resort Showcases, and Complete Theme Options Manager.', '1.0.0', 'Engr Riaz Mushtaq - AL-Riaz Tech', 'https://www.alriazdevelopers.com', 'fa fa-paint-brush', 1, 0, '[{\"page_name\":\"Theme Options\",\"controller_name\":\"RealEstateThemes\",\"action_name\":\"settings\",\"icon\":\"fa fa-paint-brush\",\"is_root\":true},{\"page_name\":\"Theme Settings\",\"controller_name\":\"RealEstateThemes\",\"action_name\":\"settings\",\"icon\":\"fa fa-cogs\"},{\"page_name\":\"Theme Overview\",\"controller_name\":\"RealEstateThemes\",\"action_name\":\"index\",\"icon\":\"fa fa-eye\"}]', '{\"top_header_enabled\":1}', '2026-08-23 21:38:27', '2026-09-10 09:04:11'),
(3, 'BillingManager', 'Society Utility & Maintenance Billing System', 'Complete society utility billing manager with meter-wise billing (Electricity/Water/Gas/Maintenance), single & bulk automated bill generator, modern bill print templates, consumer ledger, frontend check-bill portal, mobile meter reader PWA, SMS/WhatsApp reminders, bank reconciliation, and audit log with rollback.', '20.1.0', 'Engr Riaz Mushtaq - AL-Riaz Tech', 'https://www.alriazdevelopers.com', 'fa fa-bolt', 1, 0, '[{\"page_name\":\"Billing Dashboard\",\"controller_name\":\"BillingDashboards\",\"action_name\":\"index\",\"icon\":\"fa fa-bolt\",\"is_root\":true},{\"page_name\":\"Bills & Payments\",\"controller_name\":\"BillingBills\",\"action_name\":\"index\",\"icon\":\"fa fa-file-text-o\"},{\"page_name\":\"Meter Readings\",\"controller_name\":\"BillingReadings\",\"action_name\":\"index\",\"icon\":\"fa fa-tachometer\"},{\"page_name\":\"Utility Meters\",\"controller_name\":\"BillingMeters\",\"action_name\":\"index\",\"icon\":\"fa fa-plug\"},{\"page_name\":\"Property Units\",\"controller_name\":\"BillingProperties\",\"action_name\":\"index\",\"icon\":\"fa fa-building-o\"},{\"page_name\":\"Billing Consumers\",\"controller_name\":\"BillingClients\",\"action_name\":\"index\",\"icon\":\"fa fa-users\"},{\"page_name\":\"Maintenance Charges\",\"controller_name\":\"BillingExtraCharges\",\"action_name\":\"index\",\"icon\":\"fa fa-list-alt\"},{\"page_name\":\"Print Templates\",\"controller_name\":\"BillingTemplates\",\"action_name\":\"index\",\"icon\":\"fa fa-print\"},{\"page_name\":\"Bank Reconciliation\",\"controller_name\":\"BillingBankReconciliations\",\"action_name\":\"index\",\"icon\":\"fa fa-university\"},{\"page_name\":\"SMS & WhatsApp\",\"controller_name\":\"BillingReminders\",\"action_name\":\"index\",\"icon\":\"fa fa-comments\"},{\"page_name\":\"Audit Log\",\"controller_name\":\"BillingAuditLogs\",\"action_name\":\"index\",\"icon\":\"fa fa-history\"},{\"page_name\":\"Billing Settings\",\"controller_name\":\"BillingSettings\",\"action_name\":\"index\",\"icon\":\"fa fa-cogs\"},{\"page_name\":\"Backup & Migration\",\"controller_name\":\"BillingMigrations\",\"action_name\":\"index\",\"icon\":\"fa fa-cloud-upload\"}]', '{}', '2026-08-30 21:42:22', '2026-09-10 09:04:11');
