(8, 'Cancellation Letter', '<style type=\"text/css\" id=\"wv-urdu-font-definitions\">\n@font-face {\n    font-family: \'Jameel Noori Nastaleeq\';\n    src: url(\'/whitevillas/fonts/JameelNooriNastaleeq.ttf\') format(\'truetype\'),\n         url(\'/fonts/JameelNooriNastaleeq.ttf\') format(\'truetype\'),\n         url(\'../fonts/JameelNooriNastaleeq.ttf\') format(\'truetype\');\n    font-weight: normal;\n    font-style: normal;\n    font-display: swap;\n}\n@font-face {\n    font-family: \'Jameel Noori Nastaleeq Kasheeda\';\n    src: url(\'/whitevillas/fonts/JameelNooriNastaleeqKasheeda.ttf\') format(\'truetype\'),\n         url(\'/fonts/JameelNooriNastaleeqKasheeda.ttf\') format(\'truetype\'),\n         url(\'../fonts/JameelNooriNastaleeqKasheeda.ttf\') format(\'truetype\');\n    font-weight: normal;\n    font-style: normal;\n    font-display: swap;\n}\n*, *:before, *:after {\n    -webkit-print-color-adjust: exact !important;\n    print-color-adjust: exact !important;\n    color-adjust: exact !important;\n}\n[lang=\"ur\"], [dir=\"rtl\"], .urdu-text, .ashtam-page, .letter-ur, .urdu-body, .urdu-legal {\n    font-family: \'Jameel Noori Nastaleeq\', \'Noto Nastaliq Urdu\', \'Nafees Nastaleeq\', serif !important;\n    line-height: 1.85 !important;\n    letter-spacing: 0 !important;\n    word-spacing: 0 !important;\n}\n[lang=\"ur\"] h1, [lang=\"ur\"] h2, [lang=\"ur\"] h3, [lang=\"ur\"] h4, [lang=\"ur\"] h5, [lang=\"ur\"] h6,\n[dir=\"rtl\"] h1, [dir=\"rtl\"] h2, [dir=\"rtl\"] h3, [dir=\"rtl\"] h4, [dir=\"rtl\"] h5, [dir=\"rtl\"] h6,\n.ashtam-page h1, .ashtam-page h2, .ashtam-page h3, .ashtam-page h4,\n.urdu-heading, .ashtam-heading, .document-title, .document-subtitle, .section-title, .sign-title, .bismillah {\n    font-family: \'Jameel Noori Nastaleeq Kasheeda\', \'Jameel Noori Nastaleeq\', \'Noto Nastaliq Urdu\', serif !important;\n    font-weight: normal !important;\n    line-height: 1.5 !important;\n}\n[lang=\"ur\"] p, [lang=\"ur\"] li, [lang=\"ur\"] td, [lang=\"ur\"] th, [lang=\"ur\"] span,\n[dir=\"rtl\"] p, [dir=\"rtl\"] li, [dir=\"rtl\"] td, [dir=\"rtl\"] th, [dir=\"rtl\"] span,\n.ashtam-page p, .ashtam-page li, .ashtam-page td, .ashtam-page th,\n.urdu-body p, .clause, .note-box, .amount-box {\n    font-family: \'Jameel Noori Nastaleeq\', \'Noto Nastaliq Urdu\', \'Nafees Nastaleeq\', serif !important;\n    line-height: 1.85 !important;\n}\n@media print {\n    @page { size: auto; margin: 0; }\n    html, body {\n        background: #ffffff !important;\n        color: #000000 !important;\n        margin: 0 !important;\n        padding: 0 !important;\n    }\n    .ashtam-page, .page, .form-container, .container, .letter-preview-print {\n        margin: 0 auto !important;\n        box-shadow: none !important;\n        -webkit-print-color-adjust: exact !important;\n        print-color-adjust: exact !important;\n        color-adjust: exact !important;\n    }\n}\n</style><p><strong>Date:</strong> {{letter_date}}<br><strong>Reference:</strong> {{letter_ref_no}}</p><p>Dear {{client_name}},</p><p>This is to confirm cancellation of booking for <strong>{{property_name}}</strong> (Membership {{deal_invoice_no}}) as per your request / company policy.</p><p>Regards,<br>{{site_organization}}</p><p><strong>Allotment No:</strong> {{ballot_allotment_no}}</p>', 'RLT_CANCEL', 'Published', 'No', '', 'letter_signatures', '', 'letter_signatures'),
(9, 'Temporary Possession Letter', '<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>{{letter_title}}</title>\n    <style>\n        /* WV_TEMPORARY_POSSESSION_TEMPLATE_V2 */\n        @page {\n            size: legal;\n            margin: 0.5in;\n        }\n        body {\n            margin: 0;\n            padding: 0;\n            background: #f3f4f6;\n            font-family: Arial, sans-serif;\n            color: #111;\n            -webkit-print-color-adjust: exact;\n            print-color-adjust: exact;\n        }\n        .legal-page {\n            width: 8.5in;\n            min-height: 14in;\n            margin: 24px auto;\n            background: #fff;\n            box-shadow: 0 10px 25px rgba(0,0,0,0.12);\n            box-sizing: border-box;\n            padding: 2in 0.5in 1in;\n            position: relative;\n        }\n        .floating-tools {\n            position: fixed;\n            right: 20px;\n            bottom: 24px;\n            z-index: 999;\n        }\n        .floating-tools button {\n            display: block;\n            margin-top: 10px;\n            border: 0;\n            border-radius: 999px;\n            color: #fff;\n            font-weight: 700;\n            padding: 11px 18px;\n            cursor: pointer;\n            box-shadow: 0 8px 24px rgba(0,0,0,0.2);\n        }\n        .btn-word { background: #15a8b4; }\n        .btn-pdf { background: #d12229; }\n        .top-header {\n            display: flex;\n            justify-content: space-between;\n            align-items: flex-start;\n            margin-bottom: 8px;\n        }\n        .meta-left {\n            flex: 1;\n            padding-right: 14px;\n        }\n        .meta-row {\n            display: flex;\n            justify-content: space-between;\n            align-items: flex-start;\n            margin-bottom: 10px;\n            font-size: 16px;\n            font-weight: 700;\n        }\n        .meta-right {\n            text-align: right;\n            line-height: 1.5;\n        }\n        .title-wrap {\n            display: flex;\n            align-items: center;\n            justify-content: space-between;\n            gap: 10px;\n            margin: 12px 0 18px;\n        }\n        .temp-possession-title-qr {\n            width: 76px;\n            min-width: 76px;\n            height: 76px;\n            border: 1px solid #000;\n            padding: 2px;\n            background: #fff;\n            box-sizing: border-box;\n            display: flex;\n            align-items: center;\n            justify-content: center;\n            overflow: hidden;\n        }\n        .temp-possession-title-qr img {\n            width: 100%;\n            height: 100%;\n            display: block;\n        }\n        .title-wrap-spacer {\n            width: 76px;\n            min-width: 76px;\n            height: 76px;\n        }\n        .title-wrap h1 {\n            margin: 0;\n            color: #d12229;\n            font-size: 34px;\n            font-style: italic;\n            text-transform: uppercase;\n            letter-spacing: 0.5px;\n            text-shadow: 1px 1px 0 #15a8b4;\n            text-align: center;\n            flex: 1 1 auto;\n        }\n        .photo-box {\n            width: 110px;\n            min-height: 140px;\n            border: 2px solid #000;\n            display: flex;\n            align-items: center;\n            justify-content: center;\n            padding: 4px;\n            box-sizing: border-box;\n            overflow: hidden;\n        }\n        .photo-box img {\n            max-width: 100%;\n            max-height: 130px;\n            display: block;\n        }\n        .editable {\n            border-bottom: 1px dashed #888;\n            display: inline-block;\n            min-width: 40px;\n            padding: 0 3px;\n        }\n        .intro {\n            text-align: center;\n            font-size: 14px;\n            font-weight: 700;\n            line-height: 1.5;\n            margin: 0 0 14px;\n        }\n        .thick-table {\n            width: 100%;\n            border-collapse: collapse;\n            border: 3px solid #000;\n            margin-bottom: 14px;\n            table-layout: fixed;\n        }\n        .thick-table th {\n            border: 3px solid #000;\n            background: #8c73a6;\n            color: #fff;\n            text-transform: uppercase;\n            text-align: left;\n            font-size: 16px;\n            padding: 8px;\n        }\n        .thick-table td {\n            border: 3px solid #000;\n            padding: 8px;\n            font-size: 14px;\n            font-weight: 700;\n            vertical-align: top;\n            word-wrap: break-word;\n        }\n        .id-media img {\n            max-width: 150px;\n            max-height: 90px;\n            margin-right: 8px;\n        }\n        .box {\n            border: 2px solid #000;\n            background: #f9fafb;\n            padding: 10px;\n            margin-bottom: 14px;\n        }\n        .box h3 {\n            margin: 0 0 8px;\n            color: #d12229;\n            text-transform: uppercase;\n            text-decoration: underline;\n            font-size: 14px;\n        }\n        .box ol {\n            margin: 0;\n            padding-left: 20px;\n            font-size: 14px;\n            font-weight: 700;\n            line-height: 1.85;\n        }\n        .box li { margin-bottom: 8px; }\n        .terms h3 {\n            margin: 0 0 8px;\n            font-size: 14px;\n            text-transform: uppercase;\n            text-decoration: underline;\n        }\n        .terms ol {\n            margin: 0;\n            padding-left: 20px;\n            font-size: 14px;\n            font-weight: 700;\n            line-height: 1.85;\n        }\n        .terms li { margin-bottom: 8px; }\n        .sign-row {\n            margin-top: 56px;\n            display: flex;\n            justify-content: space-between;\n            text-align: center;\n            font-size: 14px;\n            font-weight: 700;\n        }\n        .sign-col { width: 31%; }\n        .sign-line {\n            height: 24px;\n            border-bottom: 2px solid #000;\n            margin-bottom: 7px;\n        }\n        @media print {\n            body { background: #fff; }\n            .legal-page {\n                margin: 0;\n                box-shadow: none;\n                width: 100%;\n                min-height: auto;\n                padding-top: 2in !important;\n                padding-left: 0 !important;\n                padding-right: 0 !important;\n                padding-bottom: 1in !important;\n            }\n            .no-print { display: none !important; }\n            .editable { border-bottom: 0 !important; }\n        }\n    </style>\n<style type=\"text/css\" id=\"wv-urdu-font-definitions\">\n@font-face {\n    font-family: \'Jameel Noori Nastaleeq\';\n    src: url(\'/whitevillas/fonts/JameelNooriNastaleeq.ttf\') format(\'truetype\'),\n         url(\'/fonts/JameelNooriNastaleeq.ttf\') format(\'truetype\'),\n         url(\'../fonts/JameelNooriNastaleeq.ttf\') format(\'truetype\');\n    font-weight: normal;\n    font-style: normal;\n    font-display: swap;\n}\n@font-face {\n    font-family: \'Jameel Noori Nastaleeq Kasheeda\';\n    src: url(\'/whitevillas/fonts/JameelNooriNastaleeqKasheeda.ttf\') format(\'truetype\'),\n         url(\'/fonts/JameelNooriNastaleeqKasheeda.ttf\') format(\'truetype\'),\n         url(\'../fonts/JameelNooriNastaleeqKasheeda.ttf\') format(\'truetype\');\n    font-weight: normal;\n    font-style: normal;\n    font-display: swap;\n}\n*, *:before, *:after {\n    -webkit-print-color-adjust: exact !important;\n    print-color-adjust: exact !important;\n    color-adjust: exact !important;\n}\n[lang=\"ur\"], [dir=\"rtl\"], .urdu-text, .ashtam-page, .letter-ur, .urdu-body, .urdu-legal {\n    font-family: \'Jameel Noori Nastaleeq\', \'Noto Nastaliq Urdu\', \'Nafees Nastaleeq\', serif !important;\n    line-height: 1.85 !important;\n    letter-spacing: 0 !important;\n    word-spacing: 0 !important;\n}\n[lang=\"ur\"] h1, [lang=\"ur\"] h2, [lang=\"ur\"] h3, [lang=\"ur\"] h4, [lang=\"ur\"] h5, [lang=\"ur\"] h6,\n[dir=\"rtl\"] h1, [dir=\"rtl\"] h2, [dir=\"rtl\"] h3, [dir=\"rtl\"] h4, [dir=\"rtl\"] h5, [dir=\"rtl\"] h6,\n.ashtam-page h1, .ashtam-page h2, .ashtam-page h3, .ashtam-page h4,\n.urdu-heading, .ashtam-heading, .document-title, .document-subtitle, .section-title, .sign-title, .bismillah {\n    font-family: \'Jameel Noori Nastaleeq Kasheeda\', \'Jameel Noori Nastaleeq\', \'Noto Nastaliq Urdu\', serif !important;\n    font-weight: normal !important;\n    line-height: 1.5 !important;\n}\n[lang=\"ur\"] p, [lang=\"ur\"] li, [lang=\"ur\"] td, [lang=\"ur\"] th, [lang=\"ur\"] span,\n[dir=\"rtl\"] p, [dir=\"rtl\"] li, [dir=\"rtl\"] td, [dir=\"rtl\"] th, [dir=\"rtl\"] span,\n.ashtam-page p, .ashtam-page li, .ashtam-page td, .ashtam-page th,\n.urdu-body p, .clause, .note-box, .amount-box {\n    font-family: \'Jameel Noori Nastaleeq\', \'Noto Nastaliq Urdu\', \'Nafees Nastaleeq\', serif !important;\n    line-height: 1.85 !important;\n}\n@media print {\n    @page { size: auto; margin: 0; }\n    html, body {\n        background: #ffffff !important;\n        color: #000000 !important;\n        margin: 0 !important;\n        padding: 0 !important;\n    }\n    .ashtam-page, .page, .form-container, .container, .letter-preview-print {\n        margin: 0 auto !important;\n        box-shadow: none !important;\n        -webkit-print-color-adjust: exact !important;\n        print-color-adjust: exact !important;\n        color-adjust: exact !important;\n    }\n}\n</style></head>\n<body>\n    <div class=\"floating-tools no-print\">\n        <button class=\"btn-word\" onclick=\"downloadAsWord()\">Download as Word</button>\n        <button class=\"btn-pdf\" onclick=\"window.print()\">Download as PDF</button>\n    </div>\n\n    <div class=\"legal-page\" id=\"wv-letter-page\">\n        <div class=\"top-header\">\n            <div class=\"meta-left\">\n                <div class=\"meta-row\">\n                    <div>Ref: <span class=\"editable\">{{letter_ref_no}}</span></div>\n                    <div class=\"meta-right\">\n                        <div>Date: <span class=\"editable\">{{letter_date}}</span></div>\n                        <div>File No: <span class=\"editable\">{{deal_invoice_no}}</span></div>\n                    </div>\n                </div>\n                <div class=\"title-wrap\">\n                    <div class=\"temp-possession-title-qr\" title=\"Letter QR\">\n                        <img src=\"https://api.qrserver.com/v1/create-qr-code/?size=220x220&amp;ecc=M&amp;qzone=2&amp;margin=1&amp;data=Letter%20Type%3A%20{{letter_type_label}}%0AClient%20Name%3A%20{{client_name}}%0AAlloted%20Property%20Unit%20No%20%3A{{property_unit}}%0AIssue%20Date%3A%20{{letter_date}}\" alt=\"Temporary Possession QR\">\n                    </div>\n                    <h1>{{letter_title}}</h1>\n                    <div class=\"title-wrap-spacer\"></div>\n                </div>\n            </div>\n            <div class=\"photo-box\">\n                {{client_profile_photo}}\n            </div>\n        </div>\n\n        <p class=\"intro\">\n            This is to certify that <span class=\"editable\">{{letter_title}}</span> of Property ID\n            <span class=\"editable\">{{property_name}}</span>, Building <span class=\"editable\">{{project_name}}</span>,\n            Floor <span class=\"editable\">{{property_unit}}</span> is being handed over to the allottee detailed below.\n        </p>\n\n        <table class=\"thick-table\">\n            <thead>\n                <tr>\n                    <th>Applicant Detail</th>\n                    <th>{{letter_title}} Details</th>\n                </tr>\n            </thead>\n            <tbody>\n                <tr>\n                    <td>NAME: <span class=\"editable\">{{client_name}}</span></td>\n                    <td>Property ID: <span class=\"editable\">{{property_name}}</span></td>\n                </tr>\n                <tr>\n                    <td>S/O, W/O: <span class=\"editable\">{{client_father_name}}</span></td>\n                    <td>Building: <span class=\"editable\">{{project_name}}</span></td>\n                </tr>\n                <tr>\n                    <td>CNIC: <span class=\"editable\">{{client_cnic}}</span></td>\n                    <td>Floor: <span class=\"editable\">{{property_unit}}</span></td>\n                </tr>\n                <tr>\n                    <td>Address: <span class=\"editable\">{{client_address}}</span></td>\n                    <td>Cell No: <span class=\"editable\">{{client_mobile}}</span></td>\n                </tr>\n                <tr>\n                    <td class=\"id-media\">\n                        <strong>ID Front:</strong><br>{{client_id_front_image}}\n                    </td>\n                    <td class=\"id-media\">\n                        <strong>ID Back:</strong><br>{{client_id_back_image}}\n                    </td>\n                </tr>\n            </tbody>\n        </table>\n\n        <div class=\"box\">\n            <h3>Special Conditions Regarding Multiple Floors</h3>\n            <ol>\n                <li>The allottee is currently being granted <span class=\"editable\">{{letter_title}}</span> of the specific floor mentioned above for immediate use or construction.</li>\n                <li>It is acknowledged that the allottee has booked and owns a total of <span class=\"editable\">Three (3)</span> floors in the project.</li>\n                <li>At final possession, after completion, the allottee will be handed over all 3 floors floor-wise on one side of the newly constructed building.</li>\n            </ol>\n        </div>\n\n        <div class=\"terms\">\n            <h3>General Terms and Conditions</h3>\n            <ol>\n                <li>On personal inspection of the plot or floor, I am fully satisfied and certify that there is no encroachment.</li>\n                <li>I shall abide by the by-laws of TMA and construct the building as per approved plans.</li>\n                <li>Before applying for construction, I shall obtain a No Objection Certificate and submit it to the relevant department.</li>\n                <li>This <span class=\"editable\">{{letter_title}}</span> does not grant final ownership rights until all dues and conditions are fulfilled.</li>\n            </ol>\n        </div>\n\n        <div class=\"sign-row\">\n            <div class=\"sign-col\">\n                <div class=\"sign-line\"></div>\n                <div>Possession Department</div>\n            </div>\n            <div class=\"sign-col\">\n                <div class=\"sign-line\"></div>\n                <div>Design Wing</div>\n            </div>\n            <div class=\"sign-col\">\n                <div class=\"sign-line\"></div>\n                <div>Allottee</div>\n            </div>\n        </div>\n    </div>\n\n    <script>\n        function downloadAsWord() {\n            var sourceNode = document.getElementById(\'wv-letter-page\');\n            if (!sourceNode) {\n                return;\n            }\n            var clone = sourceNode.cloneNode(true);\n            var html = \'\'\n                + \"<html xmlns:o=\'urn:schemas-microsoft-com:office:office\' \"\n                + \"xmlns:w=\'urn:schemas-microsoft-com:office:word\' \"\n                + \"xmlns=\'http://www.w3.org/TR/REC-html40\'>\"\n                + \"<head><meta charset=\'utf-8\'><title>{{letter_title}}</title>\"\n                + \"<style>\"\n                + \"@page Section1{size:8.5in 14in;margin:2.1in 0.5in 1.2in 0.5in;}\"\n                + \"div.Section1{page:Section1;font-family:Arial,sans-serif;color:#111;}\"\n                + \"table{border-collapse:collapse;width:100%;}\"\n                + \"th,td{border:2px solid #000;padding:8px;vertical-align:top;}\"\n                + \".editable{border:0;}\"\n                + \"</style><style type=\"text/css\" id=\"wv-urdu-font-definitions\">\n@font-face {\n    font-family: \'Jameel Noori Nastaleeq\';\n    src: url(\'/whitevillas/fonts/JameelNooriNastaleeq.ttf\') format(\'truetype\'),\n         url(\'/fonts/JameelNooriNastaleeq.ttf\') format(\'truetype\'),\n         url(\'../fonts/JameelNooriNastaleeq.ttf\') format(\'truetype\');\n    font-weight: normal;\n    font-style: normal;\n    font-display: swap;\n}\n@font-face {\n    font-family: \'Jameel Noori Nastaleeq Kasheeda\';\n    src: url(\'/whitevillas/fonts/JameelNooriNastaleeqKasheeda.ttf\') format(\'truetype\'),\n         url(\'/fonts/JameelNooriNastaleeqKasheeda.ttf\') format(\'truetype\'),\n         url(\'../fonts/JameelNooriNastaleeqKasheeda.ttf\') format(\'truetype\');\n    font-weight: normal;\n    font-style: normal;\n    font-display: swap;\n}\n*, *:before, *:after {\n    -webkit-print-color-adjust: exact !important;\n    print-color-adjust: exact !important;\n    color-adjust: exact !important;\n}\n[lang=\"ur\"], [dir=\"rtl\"], .urdu-text, .ashtam-page, .letter-ur, .urdu-body, .urdu-legal {\n    font-family: \'Jameel Noori Nastaleeq\', \'Noto Nastaliq Urdu\', \'Nafees Nastaleeq\', serif !important;\n    line-height: 1.85 !important;\n    letter-spacing: 0 !important;\n    word-spacing: 0 !important;\n}\n[lang=\"ur\"] h1, [lang=\"ur\"] h2, [lang=\"ur\"] h3, [lang=\"ur\"] h4, [lang=\"ur\"] h5, [lang=\"ur\"] h6,\n[dir=\"rtl\"] h1, [dir=\"rtl\"] h2, [dir=\"rtl\"] h3, [dir=\"rtl\"] h4, [dir=\"rtl\"] h5, [dir=\"rtl\"] h6,\n.ashtam-page h1, .ashtam-page h2, .ashtam-page h3, .ashtam-page h4,\n.urdu-heading, .ashtam-heading, .document-title, .document-subtitle, .section-title, .sign-title, .bismillah {\n    font-family: \'Jameel Noori Nastaleeq Kasheeda\', \'Jameel Noori Nastaleeq\', \'Noto Nastaliq Urdu\', serif !important;\n    font-weight: normal !important;\n    line-height: 1.5 !important;\n}\n[lang=\"ur\"] p, [lang=\"ur\"] li, [lang=\"ur\"] td, [lang=\"ur\"] th, [lang=\"ur\"] span,\n[dir=\"rtl\"] p, [dir=\"rtl\"] li, [dir=\"rtl\"] td, [dir=\"rtl\"] th, [dir=\"rtl\"] span,\n.ashtam-page p, .ashtam-page li, .ashtam-page td, .ashtam-page th,\n.urdu-body p, .clause, .note-box, .amount-box {\n    font-family: \'Jameel Noori Nastaleeq\', \'Noto Nastaliq Urdu\', \'Nafees Nastaleeq\', serif !important;\n    line-height: 1.85 !important;\n}\n@media print {\n    @page { size: auto; margin: 0; }\n    html, body {\n        background: #ffffff !important;\n        color: #000000 !important;\n        margin: 0 !important;\n        padding: 0 !important;\n    }\n    .ashtam-page, .page, .form-container, .container, .letter-preview-print {\n        margin: 0 auto !important;\n        box-shadow: none !important;\n        -webkit-print-color-adjust: exact !important;\n        print-color-adjust: exact !important;\n        color-adjust: exact !important;\n    }\n}\n</style></head><body><div class=\'Section1\'>\"\n                + clone.outerHTML\n                + \"</div></body></html>\";\n            var blob = new Blob([\'\\ufeff\', html], { type: \'application/msword\' });\n            var url = URL.createObjectURL(blob);\n            var a = document.createElement(\'a\');\n            a.href = url;\n            a.download = \'{{letter_title}}.doc\';\n            document.body.appendChild(a);\n            a.click();\n            document.body.removeChild(a);\n            URL.revokeObjectURL(url);\n        }\n    </script>\n</body>\n</html>', 'RLT_POSSESSION', 'Published', 'No', '', 'letter_signatures', '', 'letter_signatures');
INSERT INTO `templates` (`id`, `name`, `description`, `type`, `status`, `is_new`, `ceo_signature`, `ceo_signature_dir`, `chairman_signature`, `chairman_signature_dir`) VALUES
(10, 'Welcome Letter', '<!DOCTYPE html>\r\n<html lang=\"en\">\r\n<head>\r\n    <meta charset=\"UTF-8\">\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n    <title>{{agency_name}} - Welcome Letter</title>\r\n    \r\n    <!-- Tailwind CSS -->\r\n    <script src=\"https://cdn.tailwindcss.com\"></script>\r\n    \r\n    <!-- Urdu Font Support -->\r\n    <link href=\"https://fonts.googleapis.com/css2?family=Noto+Nastaliq+Urdu:wght@400..700&display=swap\" rel=\"stylesheet\">\r\n    \r\n    <style>\r\n        .form-container {\r\n            max-width: 800px; \r\n            font-family: \'Times New Roman\', serif; \r\n            margin: 4px auto; \r\n            background-color: white;\r\n            padding: 1.25rem; \r\n            border-radius: 0.5rem;\r\n            box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1);\r\n            color: #1f2937;\r\n            \r\n            /* Custom double-line repeating floral frame border pattern matching image_1acdb4.png */\r\n            border: 24px solid transparent;\r\n            border-image-source: url(\"data:image/svg+xml;charset=utf-8,%3Csvg xmlns=\'http://www.w3.org/2000/svg\' width=\'72\' height=\'72\' viewBox=\'0 0 72 72\'%3E%3Cdefs%3E%3Cg id=\'flower\'%3E%3Ccircle cx=\'12\' cy=\'12\' r=\'3.5\' fill=\'%23064e3b\'/%3E%3Cpath d=\'M12,12 C10,9 10,4 12,4 C14,4 14,9 12,12 Z\' fill=\'%23064e3b\'/%3E%3Cpath d=\'M12,12 C10,15 10,20 12,20 C14,20 14,15 12,12 Z\' fill=\'%23064e3b\'/%3E%3Cpath d=\'M12,12 C9,10 4,10 4,12 C4,14 9,14 12,12 Z\' fill=\'%23064e3b\'/%3E%3Cpath d=\'M12,12 C15,10 20,10 20,12 C20,14 15,14 12,12 Z\' fill=\'%23064e3b\'/%3E%3Cpath d=\'M12,12 C10,11 6.5,7.5 7.5,6.5 C8.5,5.5 11,10 12,12 Z\' fill=\'%23064e3b\'/%3E%3Cpath d=\'M12,12 C11,10 14.5,6.5 15.5,7.5 C16.5,8.5 12,11 12,12 Z\' fill=\'%23064e3b\'/%3E%3Cpath d=\'M12,12 C11,14 7.5,15.5 6.5,14.5 C5.5,13.5 10,11 12,12 Z\' fill=\'%23064e3b\'/%3E%3Cpath d=\'M12,12 C13,14 16.5,14.5 15.5,15.5 C14.5,16.5 11,13 12,12 Z\' fill=\'%23064e3b\'/%3E%3C/g%3E%3C/defs%3E%3Cpath d=\'M24,2 L2,2 L2,24\' fill=\'none\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cpath d=\'M24,22 L22,22 L22,24\' fill=\'none\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cuse href=\'%23flower\' x=\'0\' y=\'0\'/%3E%3Cline x1=\'24\' y1=\'2\' x2=\'48\' y2=\'2\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cline x1=\'24\' y1=\'22\' x2=\'48\' y2=\'22\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cuse href=\'%23flower\' x=\'24\' y=\'0\'/%3E%3Cpath d=\'M48,2 L70,2 L70,24\' fill=\'none\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cpath d=\'M48,22 L50,22 L50,24\' fill=\'none\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cuse href=\'%23flower\' x=\'48\' y=\'0\'/%3E%3Cline x1=\'2\' y1=\'24\' x2=\'2\' y2=\'48\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cline x1=\'22\' y1=\'24\' x2=\'22\' y2=\'48\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cuse href=\'%23flower\' x=\'0\' y=\'24\'/%3E%3Cline x1=\'70\' y1=\'24\' x2=\'70\' y2=\'48\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cline x1=\'50\' y1=\'24\' x2=\'50\' y2=\'48\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cuse href=\'%23flower\' x=\'48\' y=\'24\'/%3E%3Cpath d=\'M2,48 L2,70 L24,70\' fill=\'none\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cpath d=\'M22,48 L22,50 L24,50\' fill=\'none\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cuse href=\'%23flower\' x=\'0\' y=\'48\'/%3E%3Cline x1=\'24\' y1=\'50\' x2=\'48\' y2=\'50\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cline x1=\'24\' y1=\'70\' x2=\'48\' y2=\'70\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cuse href=\'%23flower\' x=\'24\' y=\'48\'/%3E%3Cpath d=\'M70,48 L70,70 L48,70\' fill=\'none\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cpath d=\'M50,48 L50,50 L48,50\' fill=\'none\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cuse href=\'%23flower\' x=\'48\' y=\'48\'/%3E%3C/svg%3E\");\r\n            border-image-slice: 24;\r\n            border-image-repeat: repeat;\r\n            \r\n            position: relative;\r\n            overflow: hidden;\r\n        }\r\n        \r\n        /* Centered Background Watermark style */\r\n        .watermark {\r\n            position: absolute;\r\n            top: 50%;\r\n            left: 50%;\r\n            transform: translate(-50%, -50%);\r\n            width: 320px;\r\n            height: 320px;\r\n            opacity: 0.04; /* Subtle backdrop presence */\r\n            pointer-events: none;\r\n            z-index: 0;\r\n            user-select: none;\r\n        }\r\n\r\n        /* Form content wrapper to stay above watermark */\r\n        .form-content-wrapper {\r\n            position: relative;\r\n            z-index: 10;\r\n        }\r\n\r\n        .form-section-title {\r\n            background-color: #064e3b; /* Premium Forest Green background */\r\n            color: #ffffff; /* Crisp white text */\r\n            font-weight: 700;\r\n            font-size: 0.85rem;\r\n            padding: 0.25rem 0.75rem;\r\n            margin-bottom: 0.5rem;\r\n            border-left: 4px solid #d97706; /* Solid amber gold accent bar */\r\n            border-radius: 0 0.25rem 0.25rem 0;\r\n            letter-spacing: 0.05em;\r\n            display: inline-block;\r\n        }\r\n        \r\n        .info-label {\r\n            font-weight: 700;\r\n            color: #064e3b;\r\n        }\r\n\r\n        /* --- PRINT STYLING & COLOR PRESERVATION --- */\r\n        @media print {\r\n            @page {\r\n                size: A4 portrait;\r\n                margin: 0;\r\n            }\r\n            body { \r\n                margin: 0; \r\n                padding: 0; \r\n                background: none; \r\n            }\r\n            * {\r\n                -webkit-print-color-adjust: exact !important;\r\n                print-color-adjust: exact !important;\r\n            }\r\n            .form-container {\r\n                max-width: 100%;\r\n                width: 100%;\r\n                box-shadow: none;\r\n                border: 24px solid transparent !important;\r\n                border-image-source: url(\"data:image/svg+xml;charset=utf-8,%3Csvg xmlns=\'http://www.w3.org/2000/svg\' width=\'72\' height=\'72\' viewBox=\'0 0 72 72\'%3E%3Cdefs%3E%3Cg id=\'flower\'%3E%3Ccircle cx=\'12\' cy=\'12\' r=\'3.5\' fill=\'%23064e3b\'/%3E%3Cpath d=\'M12,12 C10,9 10,4 12,4 C14,4 14,9 12,12 Z\' fill=\'%23064e3b\'/%3E%3Cpath d=\'M12,12 C10,15 10,20 12,20 C14,20 14,15 12,12 Z\' fill=\'%23064e3b\'/%3E%3Cpath d=\'M12,12 C9,10 4,10 4,12 C4,14 9,14 12,12 Z\' fill=\'%23064e3b\'/%3E%3Cpath d=\'M12,12 C15,10 20,10 20,12 C20,14 15,14 12,12 Z\' fill=\'%23064e3b\'/%3E%3Cpath d=\'M12,12 C10,11 6.5,7.5 7.5,6.5 C8.5,5.5 11,10 12,12 Z\' fill=\'%23064e3b\'/%3E%3Cpath d=\'M12,12 C11,10 14.5,6.5 15.5,7.5 C16.5,8.5 12,11 12,12 Z\' fill=\'%23064e3b\'/%3E%3Cpath d=\'M12,12 C11,14 7.5,15.5 6.5,14.5 C5.5,13.5 10,11 12,12 Z\' fill=\'%23064e3b\'/%3E%3Cpath d=\'M12,12 C13,14 16.5,14.5 15.5,15.5 C14.5,16.5 11,13 12,12 Z\' fill=\'%23064e3b\'/%3E%3C/g%3E%3C/defs%3E%3Cpath d=\'M24,2 L2,2 L2,24\' fill=\'none\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cpath d=\'M24,22 L22,22 L22,24\' fill=\'none\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cuse href=\'%23flower\' x=\'0\' y=\'0\'/%3E%3Cline x1=\'24\' y1=\'2\' x2=\'48\' y2=\'2\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cline x1=\'24\' y1=\'22\' x2=\'48\' y2=\'22\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cuse href=\'%23flower\' x=\'24\' y=\'0\'/%3E%3Cpath d=\'M48,2 L70,2 L70,24\' fill=\'none\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cpath d=\'M48,22 L50,22 L50,24\' fill=\'none\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cuse href=\'%23flower\' x=\'48\' y=\'0\'/%3E%3Cline x1=\'2\' y1=\'24\' x2=\'2\' y2=\'48\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cline x1=\'22\' y1=\'24\' x2=\'22\' y2=\'48\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cuse href=\'%23flower\' x=\'0\' y=\'24\'/%3E%3Cline x1=\'70\' y1=\'24\' x2=\'70\' y2=\'48\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cline x1=\'50\' y1=\'24\' x2=\'50\' y2=\'48\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cuse href=\'%23flower\' x=\'48\' y=\'24\'/%3E%3Cpath d=\'M2,48 L2,70 L24,70\' fill=\'none\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cpath d=\'M22,48 L22,50 L24,50\' fill=\'none\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cuse href=\'%23flower\' x=\'0\' y=\'48\'/%3E%3Cline x1=\'24\' y1=\'50\' x2=\'48\' y2=\'50\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cline x1=\'24\' y1=\'70\' x2=\'48\' y2=\'70\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cuse href=\'%23flower\' x=\'24\' y=\'48\'/%3E%3Cpath d=\'M70,48 L70,70 L48,70\' fill=\'none\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cpath d=\'M50,48 L50,50 L48,50\' fill=\'none\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cuse href=\'%23flower\' x=\'48\' y=\'48\'/%3E%3C/svg%3E\") !important;\r\n                border-image-slice: 24 !important;\r\n                border-image-repeat: repeat !important;\r\n                padding: 0.5rem;\r\n                margin: 0;\r\n            }\r\n            .form-section-title {\r\n                background-color: #064e3b !important;\r\n                color: #ffffff !important;\r\n                border-left: 4px solid #d97706 !important;\r\n                display: inline-block !important;\r\n            }\r\n            .watermark {\r\n                opacity: 0.04 !important;\r\n            }\r\n        }\r\n    \n        /* White Villas compact A4 welcome letter print/PDF fit */ /* wv-welcome-a4-fit-css */\n        .wv-welcome-a4{width:210mm!important;max-width:210mm!important;margin:0 auto!important;padding:5mm!important;border-width:12px!important;border-image-slice:24!important;box-shadow:none!important;font-size:12px!important;line-height:1.85!important;}\n        .wv-welcome-a4 .watermark{width:220px!important;height:220px!important;}\n        .wv-welcome-a4 header{margin-bottom:.35rem!important;padding:.45rem!important;padding-bottom:.45rem!important;}\n        .wv-welcome-a4 header .w-28{width:5rem!important;}\n        .wv-welcome-a4 header .h-28{height:5rem!important;}\n        .wv-welcome-a4 header .w-24{width:4.1rem!important;}\n        .wv-welcome-a4 header .h-32{height:5.3rem!important;}\n        .wv-welcome-a4 h1{font-size:1.45rem!important;line-height:1.85!important;margin:0!important;}\n        .wv-welcome-a4 h2{font-size:.92rem!important;line-height:1.85!important;margin:0!important;}\n        .wv-welcome-a4 .text-center.mb-6{margin-bottom:.45rem!important;}\n        .wv-welcome-a4 .bg-stone-50\\/50{padding:.55rem!important;margin-bottom:.35rem!important;}\n        .wv-welcome-a4 .my-4{margin-top:.35rem!important;margin-bottom:.35rem!important;}\n        .wv-welcome-a4 .mb-6{margin-bottom:.45rem!important;}\n        .wv-welcome-a4 .mb-4{margin-bottom:.35rem!important;}\n        .wv-welcome-a4 .mt-2{margin-top:.25rem!important;}\n        .wv-welcome-a4 .mt-1\\.5{margin-top:.2rem!important;}\n        .wv-welcome-a4 .p-5{padding:.55rem!important;}\n        .wv-welcome-a4 .p-4{padding:.55rem!important;}\n        .wv-welcome-a4 .p-3\\.5{padding:.45rem!important;}\n        .wv-welcome-a4 .p-3{padding:.4rem!important;}\n        .wv-welcome-a4 .p-2\\.5{padding:.35rem!important;}\n        .wv-welcome-a4 .px-8{padding-left:1.2rem!important;padding-right:1.2rem!important;}\n        .wv-welcome-a4 .py-1\\.5{padding-top:.25rem!important;padding-bottom:.25rem!important;}\n        .wv-welcome-a4 .gap-3{gap:.35rem!important;}\n        .wv-welcome-a4 .gap-x-6{column-gap:.7rem!important;}\n        .wv-welcome-a4 .gap-y-2{row-gap:.25rem!important;}\n        .wv-welcome-a4 .space-y-2>:not([hidden])~:not([hidden]){margin-top:.25rem!important;}\n        .wv-welcome-a4 .space-y-3>:not([hidden])~:not([hidden]){margin-top:.28rem!important;}\n        .wv-welcome-a4 p{margin-top:0!important;margin-bottom:.25rem!important;line-height:1.85!important;}\n        .wv-welcome-a4 .text-base{font-size:.82rem!important;line-height:1.85!important;}\n        .wv-welcome-a4 .text-sm{font-size:.72rem!important;line-height:1.85!important;}\n        .wv-welcome-a4 .text-xs{font-size:.6rem!important;line-height:1.85!important;}\n        .wv-welcome-a4 .text-\\[10px\\]{font-size:.52rem!important;line-height:1.85!important;}\n        .wv-welcome-a4 .text-\\[9px\\]{font-size:.5rem!important;line-height:1.85!important;}\n        .wv-welcome-a4 .text-\\[7\\.5px\\],.wv-welcome-a4 .text-\\[7px\\]{font-size:.42rem!important;line-height:1.85!important;}\n        .wv-welcome-a4 footer{margin-top:.35rem!important;padding-bottom:0!important;}\n        .wv-welcome-a4 footer .grid{padding-top:.35rem!important;gap:.35rem!important;}\n        .wv-welcome-a4 footer .h-16{height:.28in!important;}\n        .wv-welcome-a4 footer .mt-6{margin-top:.22rem!important;}\n        .wv-welcome-a4 footer .mb-1{margin-bottom:.1rem!important;}\n        .wv-welcome-a4 #secure-barcode{height:10px!important;width:118px!important;}\n        .wv-welcome-a4 [style*=\"0.75in\"],.wv-welcome-a4 [style*=\"1.25in\"]{width:.75in!important;height:.75in!important;padding:2px!important;}\n        .wv-welcome-a4 [style*=\"0.75in\"] img,.wv-welcome-a4 [style*=\"1.25in\"] img{width:100%!important;height:100%!important;filter:contrast(1.45)!important;image-rendering:pixelated!important;}\n        @media print{\n            @page{size:A4 portrait;margin:0;}\n            html,body{width:210mm!important;height:297mm!important;margin:0!important;padding:0!important;background:#fff!important;overflow:hidden!important;}\n            .wv-welcome-a4{width:210mm!important;max-width:210mm!important;height:297mm!important;max-height:297mm!important;margin:0!important;padding:5mm!important;border-width:12px!important;border-image-slice:24!important;box-shadow:none!important;overflow:hidden!important;border-image-repeat:repeat!important;}\n            .form-section-title{padding:.18rem .5rem!important;margin-bottom:.25rem!important;}\n        }\r\n    \n        /* Center bank detail values only */ /* wv-bank-center-fix */\n        .wv-welcome-a4 .bank-detail-value{display:block!important;flex:1 1 auto!important;text-align:center!important;}\n        .wv-welcome-a4 .bank-detail-label{display:block!important;flex:0 0 7.5rem!important;white-space:nowrap!important;}\r\n    \n        /* Polished full-page print positioning */ /* wv-welcome-print-polish */\n        .wv-welcome-a4 .form-content-wrapper{height:100%!important;min-height:100%!important;display:flex!important;flex-direction:column!important;}\n        .wv-welcome-a4 header{flex:0 0 auto!important;}\n        .wv-welcome-a4 .form-content-wrapper>div:not(.watermark):not(header):not(footer){flex:0 0 auto!important;}\n        .wv-welcome-a4 footer{margin-top:auto!important;padding-top:7mm!important;padding-bottom:1.5mm!important;flex:0 0 auto!important;}\n        .wv-welcome-a4 footer .grid{padding-top:3mm!important;align-items:end!important;border-top:1px solid #a7f3d0!important;}\n        .wv-welcome-a4 footer .h-16{height:.34in!important;}\n        .wv-welcome-a4 footer .border-t{border-top-color:#064e3b!important;}\n        .wv-welcome-a4 footer #secure-barcode{margin-top:0!important;}\n        .wv-welcome-a4 footer .mt-6{margin-top:.15rem!important;}\n        .wv-welcome-a4 footer .mt-0\\.5{margin-top:.08rem!important;}\n        .wv-welcome-a4 footer .tracking-widest{letter-spacing:.08em!important;}\n        .wv-welcome-a4 .bg-stone-50\\/50{border-color:#d1fae5!important;box-shadow:0 1px 5px rgba(6,78,59,.08)!important;}\n        .wv-welcome-a4 .bg-gradient-to-r.from-emerald-900{background:#064e3b!important;}\n        .wv-welcome-a4 .bg-gradient-to-r.from-amber-600{background:#c76300!important;}\n        .wv-welcome-a4 .bg-white.p-2\\.5{min-height:38px!important;}\n        .wv-welcome-a4 .bank-detail-value{white-space:nowrap!important;overflow:hidden!important;text-overflow:ellipsis!important;}\n        @media print{\n            .wv-welcome-a4 .form-content-wrapper{height:100%!important;min-height:100%!important;display:flex!important;flex-direction:column!important;}\n            .wv-welcome-a4 footer{margin-top:auto!important;padding-top:7mm!important;padding-bottom:1.5mm!important;}\n        }\r\n    </style>\r\n<style type=\"text/css\" id=\"wv-urdu-font-definitions\">\n@font-face {\n    font-family: \'Jameel Noori Nastaleeq\';\n    src: url(\'/whitevillas/fonts/JameelNooriNastaleeq.ttf\') format(\'truetype\'),\n         url(\'/fonts/JameelNooriNastaleeq.ttf\') format(\'truetype\'),\n         url(\'../fonts/JameelNooriNastaleeq.ttf\') format(\'truetype\');\n    font-weight: normal;\n    font-style: normal;\n    font-display: swap;\n}\n@font-face {\n    font-family: \'Jameel Noori Nastaleeq Kasheeda\';\n    src: url(\'/whitevillas/fonts/JameelNooriNastaleeqKasheeda.ttf\') format(\'truetype\'),\n         url(\'/fonts/JameelNooriNastaleeqKasheeda.ttf\') format(\'truetype\'),\n         url(\'../fonts/JameelNooriNastaleeqKasheeda.ttf\') format(\'truetype\');\n    font-weight: normal;\n    font-style: normal;\n    font-display: swap;\n}\n*, *:before, *:after {\n    -webkit-print-color-adjust: exact !important;\n    print-color-adjust: exact !important;\n    color-adjust: exact !important;\n}\n[lang=\"ur\"], [dir=\"rtl\"], .urdu-text, .ashtam-page, .letter-ur, .urdu-body, .urdu-legal {\n    font-family: \'Jameel Noori Nastaleeq\', \'Noto Nastaliq Urdu\', \'Nafees Nastaleeq\', serif !important;\n    line-height: 1.85 !important;\n    letter-spacing: 0 !important;\n    word-spacing: 0 !important;\n}\n[lang=\"ur\"] h1, [lang=\"ur\"] h2, [lang=\"ur\"] h3, [lang=\"ur\"] h4, [lang=\"ur\"] h5, [lang=\"ur\"] h6,\n[dir=\"rtl\"] h1, [dir=\"rtl\"] h2, [dir=\"rtl\"] h3, [dir=\"rtl\"] h4, [dir=\"rtl\"] h5, [dir=\"rtl\"] h6,\n.ashtam-page h1, .ashtam-page h2, .ashtam-page h3, .ashtam-page h4,\n.urdu-heading, .ashtam-heading, .document-title, .document-subtitle, .section-title, .sign-title, .bismillah {\n    font-family: \'Jameel Noori Nastaleeq Kasheeda\', \'Jameel Noori Nastaleeq\', \'Noto Nastaliq Urdu\', serif !important;\n    font-weight: normal !important;\n    line-height: 1.5 !important;\n}\n[lang=\"ur\"] p, [lang=\"ur\"] li, [lang=\"ur\"] td, [lang=\"ur\"] th, [lang=\"ur\"] span,\n[dir=\"rtl\"] p, [dir=\"rtl\"] li, [dir=\"rtl\"] td, [dir=\"rtl\"] th, [dir=\"rtl\"] span,\n.ashtam-page p, .ashtam-page li, .ashtam-page td, .ashtam-page th,\n.urdu-body p, .clause, .note-box, .amount-box {\n    font-family: \'Jameel Noori Nastaleeq\', \'Noto Nastaliq Urdu\', \'Nafees Nastaleeq\', serif !important;\n    line-height: 1.85 !important;\n}\n@media print {\n    @page { size: auto; margin: 0; }\n    html, body {\n        background: #ffffff !important;\n        color: #000000 !important;\n        margin: 0 !important;\n        padding: 0 !important;\n    }\n    .ashtam-page, .page, .form-container, .container, .letter-preview-print {\n        margin: 0 auto !important;\n        box-shadow: none !important;\n        -webkit-print-color-adjust: exact !important;\n        print-color-adjust: exact !important;\n        color-adjust: exact !important;\n    }\n}\n</style></head>\r\n\r\n<body class=\"bg-gray-100 p-2 sm:p-6 flex justify-center\" style=\"margin:0!important;padding:0!important;background:#fff!important;display:block!important;\">\r\n\r\n    <div class=\"form-container w-full wv-welcome-a4\">\r\n        \r\n        <!-- Centered Background Watermark -->\r\n        <div class=\"watermark flex items-center justify-center\">\r\n            <img id=\"watermark-logo\" src=\"{{agency_logo_url}}\" \r\n                 alt=\"Watermark Logo\" class=\"w-full h-full object-contain\" onerror=\"handleWatermarkError(this)\">\r\n        </div>\r\n\r\n        <div class=\"form-content-wrapper\">\r\n            <header class=\"mb-3 flex flex-row items-center justify-between pb-3 relative overflow-hidden rounded-lg p-3 bg-emerald-50/10 border border-emerald-100/30\">\r\n                <!-- Panoramic Pakistani Monuments SVG Watermark Background -->\r\n                <div class=\"absolute inset-0 pointer-events-none opacity-[0.06] z-0 select-none flex items-end\">\r\n                    <svg class=\"w-full h-full\" viewBox=\"0 0 1000 120\" preserveAspectRatio=\"none\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\">\r\n                        <line x1=\"0\" y1=\"120\" x2=\"1000\" y2=\"120\" stroke=\"#064e3b\" stroke-width=\"2\" />\r\n                        <path d=\"M15,120 L25,108 L28,108 L31,105 L31,100 L34,100 L35,80 L32,80 L32,77 L38,77 L39,55 L35,55 L35,52 L41,52 L43,20 C43,15 47,15 47,20 L49,52 L55,52 L55,55 L51,55 L52,77 L58,77 L58,80 L55,80 L56,100 L59,100 L59,105 L62,108 L65,108 L75,120 Z\" fill=\"#064e3b\" />\r\n                        <path d=\"M100,120 L100,60 L112,60 L112,50 L108,50 L108,45 L124,45 L124,50 L120,50 L120,60 L135,60 L135,75 Q145,62 155,75 L155,120 L147,120 L147,85 Q145,76 138,85 L138,120 L130,120 L130,70 L125,70 L125,120 Z\" fill=\"#064e3b\" />\r\n                        <path d=\"M155,120 L155,75 Q165,62 175,75 L175,60 L190,60 L190,50 L186,50 L186,45 L202,45 L202,50 L198,50 L198,60 L210,60 L210,120 L185,120 L185,70 L180,70 L180,120 Z\" fill=\"#064e3b\" />\r\n                        <path d=\"M220,120 L220,30 L216,30 L211,30 L211,25 L219,25 L220,15 C220,10 226,10 226,15 L227,25 L235,25 L235,30 L231,30 L231,120 Z\" fill=\"#064e3b\" />\r\n                        <path d=\"M255,120 L255,90 Q280,65 305,90 L305,120 Z\" fill=\"#064e3b\" />\r\n                        <path d=\"M310,120 L310,85 C310,50 360,50 360,85 L360,120 Z\" fill=\"#064e3b\" />\r\n                        <path d=\"M365,120 L365,90 Q390,65 415,90 L415,120 Z\" fill=\"#064e3b\" />\r\n                        <path d=\"M430,120 L430,30 L426,30 L421,30 L421,25 L429,25 L430,15 C430,10 436,10 436,15 L437,25 L445,25 L445,30 L441,30 L441,120 Z\" fill=\"#064e3b\" />\r\n                        <path d=\"M480,120 L485,85 L500,85 L505,65 L525,65 L527,50 C527,45 533,45 533,50 L535,65 L555,65 L560,85 L575,85 L580,120 Z\" fill=\"#064e3b\" />\r\n                        <path d=\"M600,120 L615,70 L675,70 L690,120 Z\" fill=\"#064e3b\" />\r\n                        <path d=\"M622,70 C622,45 668,45 668,70 Z\" fill=\"#064e3b\" />\r\n                        <path d=\"M635,120 L635,95 C635,85 655,85 655,95 L655,120 Z\" fill=\"#ffffff\" opacity=\"0.6\" />\r\n                        <path d=\"M710,120 C710,95 725,80 740,85 C730,102 720,112 717,120 Z\" fill=\"#064e3b\" />\r\n                        <path d=\"M725,120 C730,75 755,60 767,70 C755,92 743,110 740,120 Z\" fill=\"#064e3b\" />\r\n                        <circle cx=\"765\" cy=\"100\" r=\"6\" fill=\"#064e3b\" />\r\n                        <path d=\"M800,120 C795,75 770,60 758,70 C770,92 782,110 785,120 Z\" fill=\"#064e3b\" />\r\n                        <path d=\"M815,120 C815,95 800,80 785,85 C795,102 805,112 808,120 Z\" fill=\"#064e3b\" />\r\n                        <path d=\"M845,120 L845,15 L848,15 L848,120 Z\" fill=\"#064e3b\" />\r\n                        <path d=\"M860,120 L910,55 L960,120 Z\" fill=\"#064e3b\" />\r\n                        <line x1=\"910\" y1=\"55\" x2=\"910\" y2=\"45\" stroke=\"#064e3b\" stroke-width=\"2\" />\r\n                        <path d=\"M975,120 L975,15 L978,15 L978,120 Z\" fill=\"#064e3b\" />\r\n                        <line x1=\"885\" y1=\"120\" x2=\"910\" y2=\"55\" stroke=\"#ffffff\" stroke-width=\"1.5\" opacity=\"0.3\" />\r\n                        <line x1=\"935\" y1=\"120\" x2=\"910\" y2=\"55\" stroke=\"#ffffff\" stroke-width=\"1.5\" opacity=\"0.3\" />\r\n                    </svg>\r\n                </div>\r\n\r\n                <!-- Left logo wrapper -->\r\n                <div class=\"w-28 flex-shrink-0 flex items-center justify-start z-10 relative\">\r\n                    <div class=\"w-28 h-28 flex-shrink-0 flex items-center justify-center bg-transparent\">\r\n                        <img id=\"agency-logo\" src=\"{{agency_logo_url}}\" \r\n                             alt=\"Agency Logo\" class=\"w-full h-full object-contain p-1.5\" onerror=\"handleLogoError(this)\">\r\n                    </div>\r\n                </div>\r\n\r\n                <!-- Center Header Texts -->\r\n                <div class=\"flex-1 flex flex-col items-center justify-center text-center px-4 z-10 relative\">\r\n                    <h1 class=\"text-3xl sm:text-4xl font-black tracking-wide text-emerald-950 border-b-2 border-amber-500/40 pb-1 leading-tight inline-block\">{{agency_name}}</h1> \r\n                    <p class=\"text-sm font-medium text-gray-700 mt-1.5 max-w-md\">{{agency_address}}</p>\r\n\r\n                    <div class=\"text-xs font-semibold text-gray-600 mt-2 gap-x-4 flex flex-wrap justify-center\">\r\n                        <div>\r\n                            <span class=\"font-extrabold text-emerald-800\">Email:</span> \r\n                            <span>{{agency_email}}</span>\r\n                        </div>\r\n                        <div>\r\n                            <span class=\"font-extrabold text-emerald-800\">Mobile:</span> \r\n                            <span>{{agency_phone}}</span>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n                \r\n                <!-- Right photo wrapper -->\r\n                <div class=\"w-28 flex-shrink-0 flex items-center justify-end z-10 relative\">\r\n                    <div class=\"w-24 h-32 border-2 border-emerald-800 flex items-center justify-center text-emerald-700/60 text-[10px] bg-emerald-50/20 overflow-hidden rounded shadow-md\">\r\n                        <img id=\"client-photo\" src=\"{{client_profile_photo_url}}\" alt=\"Applicant Photo\" class=\"w-full h-full object-cover\" onerror=\"handlePhotoError(this)\">\r\n                    </div>\r\n                </div>\r\n            </header>\r\n\r\n            <!-- Document Title & Reference ID -->\r\n            <div class=\"flex justify-between items-center text-xs font-extrabold mb-4 pb-1 border-b border-emerald-100\">\r\n                <div>\r\n                    <span class=\"text-emerald-700 font-extrabold\">Reference ID:</span> \r\n                    <span class=\"text-gray-800 ml-1 font-bold\">{{letter_ref_no}}</span>\r\n                </div>\r\n                <div>\r\n                    <span class=\"text-emerald-700 font-extrabold\">Project Name:</span> `n                    <span class=\"text-emerald-600 ml-1 font-bold\">{{project_name}}</span>\r\n                </div>\r\n            </div>\r\n\r\n            <!-- Welcome Letter Heading Banner (Centered Stylized Badge) -->\r\n            <div class=\"text-center mb-6\">\r\n                <div class=\"inline-block bg-emerald-900 text-white py-1.5 px-8 rounded-lg shadow-sm border-b-4 border-amber-500\">\r\n                    <h2 class=\"text-lg font-black uppercase tracking-widest text-amber-400 leading-normal\">WELCOME LETTER</h2>\r\n                </div>\r\n            </div>\r\n\r\n            <!-- Congratulatory Letter Content Section -->\r\n            <div class=\"bg-stone-50/50 rounded-lg p-5 border border-emerald-100/50 mb-6 relative\">\r\n                <!-- Secondary subtle background watermark logo on below text -->\r\n                <div class=\"absolute inset-0 flex items-center justify-center pointer-events-none opacity-[0.035] select-none z-0\">\r\n                    <img src=\"{{agency_logo_url}}\" class=\"w-80 h-80 object-contain\" onerror=\"this.style.display=\'none\'\">\r\n                </div>\r\n\r\n                <!-- Date and Salutation -->\r\n                <div class=\"flex justify-between items-center mb-4 text-sm font-semibold relative z-10\">\r\n                    <div class=\"text-emerald-950\">\r\n                        Date: <span id=\"display-date\" class=\"font-bold text-gray-800\">{{letter_date}}</span>\r\n                    </div>\r\n                    <div class=\"text-emerald-950\">\r\n                        File Ref No: <span class=\"font-bold text-gray-800\">{{property_file}}</span>\r\n                    </div>\r\n                </div>\r\n\r\n                <!-- Personal Information Header with Mobile added and Address below -->\r\n                <div class=\"mb-4 relative z-10\">\r\n                    <p class=\"text-base font-bold text-emerald-950\">Dear {{client_name}},</p>\r\n                    <p class=\"text-xs text-gray-500 font-semibold mt-0.5\">CNIC: {{client_cnic}} | Mobile: {{client_mobile}}</p>\r\n                    <p class=\"text-xs text-gray-500 font-semibold mt-0.5\">Address: {{client_address}}</p>\r\n                </div>\r\n\r\n                <!-- Letter Body -->\r\n                <div class=\"text-sm text-gray-800 leading-relaxed space-y-3 font-serif relative z-10\">\r\n                    <p>\r\n                        On behalf of the executive board and the entire management team of <strong>{{agency_name}}</strong>, we extend our warmest congratulations and a heartfelt welcome to you on becoming a valuable esteemed member of our premium housing development project, <strong>{{project_name}}</strong>.\r\n                    </p>\r\n                    <p>\r\n                        This letter serves as your formal acknowledgment and congratulations on the successful booking of your real estate investment. We have securely registered your property and generated your unique file ledger under our automated municipal portal. Your key properties and allotment metrics are specified below:\r\n                    </p>\r\n\r\n                    <!-- Refined & Highly Colorized standalone Property Allotment Card -->\r\n                    <div class=\"my-4 bg-white border border-emerald-600/30 rounded-lg shadow-md overflow-hidden\">\r\n                        <!-- Highly Prominent Colored Card Header -->\r\n                        <div class=\"bg-gradient-to-r from-emerald-900 to-emerald-950 text-white px-4 py-2 flex items-center justify-between\">\r\n                            <span class=\"text-xs font-black tracking-widest uppercase flex items-center\">\r\n                                <svg xmlns=\"http://www.w3.org/2000/svg\" class=\"h-4 w-4 text-amber-400 mr-2\" fill=\"none\" viewBox=\"0 0 24 24\" stroke=\"currentColor\">\r\n                                    <path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z\" />\r\n                                </svg>\r\n                                OFFICIAL PROPERTY ALLOTMENT RECORD\r\n                            </span>\r\n                            <span class=\"bg-amber-500 text-emerald-950 text-[10px] font-black px-2.5 py-0.5 rounded shadow-sm uppercase tracking-wider\">Status: {{deal_status}}</span>\r\n                        </div>\r\n                        \r\n                        <!-- Premium Inner Metric Grid -->\r\n                        <div class=\"grid grid-cols-4 gap-3 p-3.5 bg-gradient-to-br from-emerald-50/20 via-white to-stone-50 text-xs\">\r\n                            <div class=\"bg-white p-2.5 rounded border border-emerald-100 shadow-sm border-l-4 border-l-emerald-700\">\r\n                                <span class=\"block text-[9px] text-emerald-900/60 uppercase tracking-wider font-extrabold mb-0.5\">File Number</span>\r\n                                <span class=\"font-extrabold text-emerald-950 font-mono text-sm leading-normal\">{{property_file}}</span>\r\n                            </div>\r\n                            <div class=\"bg-white p-2.5 rounded border border-emerald-100 shadow-sm border-l-4 border-l-emerald-700\">\r\n                                <span class=\"block text-[9px] text-emerald-900/60 uppercase tracking-wider font-extrabold mb-0.5\">Area / Size</span>\r\n                                <span class=\"font-bold text-gray-800 text-sm leading-normal\">{{property_area}}</span>\r\n                            </div>\r\n                            <div class=\"bg-white p-2.5 rounded border border-emerald-100 shadow-sm border-l-4 border-l-emerald-700\">\r\n                                <span class=\"block text-[9px] text-emerald-900/60 uppercase tracking-wider font-extrabold mb-0.5\">Category</span>\r\n                                <span class=\"font-bold text-emerald-800 text-sm leading-normal\">{{property_type}}</span>\r\n                            </div>\r\n                            <div class=\"bg-white p-2.5 rounded border border-emerald-100 shadow-sm border-l-4 border-l-emerald-700\">\r\n                                <span class=\"block text-[9px] text-emerald-900/60 uppercase tracking-wider font-extrabold mb-0.5\">Block Name</span>\r\n                                <span class=\"font-bold text-gray-800 text-sm leading-normal\">{{ballot_block_name}}</span>\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n\r\n                    <!-- Prominent, Colorized & Refined Bank Details Card (Installment payments) -->\r\n                    <div class=\"my-4 bg-gradient-to-br from-amber-50/40 via-white to-amber-50/20 border-2 border-dashed border-amber-600/40 rounded-lg relative overflow-hidden shadow-md\">\r\n                        <!-- Golden Emblem Stamp Background decoration -->\r\n                        <div class=\"absolute right-3 top-2.5 opacity-[0.09] pointer-events-none text-amber-900\">\r\n                            <svg xmlns=\"http://www.w3.org/2000/svg\" class=\"h-16 w-16\" fill=\"none\" viewBox=\"0 0 24 24\" stroke=\"currentColor\">\r\n                                <path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"1.5\" d=\"M19 21V5a2 2 0 00-2-2H7a2 2 0 00-2 2v16m14 0h2m-2 0h-5m-9 0H3m2 0h5M9 7h1m-1 4h1m4-4h1m-1 4h1m-5 10v-5a1 1 0 011-1h2a1 1 0 011 1v5m-4 0h4\" />\r\n                            </svg>\r\n                        </div>\r\n                        \r\n                        <!-- Rich Colored Accent Header Block inside card -->\r\n                        <div class=\"bg-gradient-to-r from-amber-600 to-amber-700 text-white px-4 py-1.5 flex items-center justify-between text-[11px] font-extrabold uppercase tracking-widest\">\r\n                            <span class=\"flex items-center\">\r\n                                <span class=\"inline-block w-2 h-2 bg-white rounded-full mr-2\"></span>\r\n                                OFFICIAL INSTALMENT & PAYMENT ACCOUNT DETAILS\r\n                            </span>\r\n                        </div>\r\n                        \r\n                        <div class=\"grid grid-cols-2 gap-x-6 gap-y-2 p-4 text-xs\">\r\n                            <div class=\"space-y-2\">\r\n                                <div class=\"flex items-center border-b border-amber-100/50 pb-1\">\r\n                                    <span class=\"text-amber-900 font-bold w-28 flex-shrink-0 bank-detail-label\">Bank Name:</span>\r\n                                    <span class=\"font-extrabold text-gray-800 flex-1 text-center bank-detail-value\">{{bank_name}}</span>\r\n                                </div>\r\n                                <div class=\"flex items-center border-b border-amber-100/50 pb-1\">\r\n                                    <span class=\"text-amber-900 font-bold w-28 flex-shrink-0 bank-detail-label\">Account Title:</span>\r\n                                    <span class=\"font-extrabold text-gray-800 flex-1 text-center bank-detail-value\">{{bank_account_title}}</span>\r\n                                </div>\r\n                            </div>\r\n                            <div class=\"space-y-2 border-l border-amber-200/50 pl-6\">\r\n                                <div class=\"flex items-center border-b border-amber-100/50 pb-1\">\r\n                                    <span class=\"text-amber-900 font-bold w-32 flex-shrink-0 bank-detail-label\">Account Number:</span>\r\n                                    <span class=\"font-mono font-extrabold text-gray-800 flex-1 text-center bank-detail-value\">{{bank_account_no}}</span>\r\n                                </div>\r\n                                <div class=\"flex items-center border-b border-amber-100/50 pb-1\">\r\n                                    <span class=\"text-amber-900 font-bold w-32 flex-shrink-0 bank-detail-label\">IBAN Number:</span>\r\n                                    <span class=\"font-mono font-extrabold text-gray-800 flex-1 text-center bank-detail-value\">{{bank_iban}}</span>\r\n                                </div>\r\n                            </div>\r\n                        </div>\r\n\r\n                        <!-- Strict security alert warning note regarding official installment accounts -->\r\n                        <div class=\"mx-4 mb-3 p-3 bg-red-50 border border-red-200 rounded text-[10px] text-red-800 font-medium leading-relaxed\">\r\n                            <strong class=\"text-red-900 font-extrabold uppercase tracking-wider block mb-0.5\">⚠️ Security Payment Notice:</strong>\r\n                            Please make payments only to the given official bank account details listed above. Under no circumstances should payments be transferred or handed over to any personal, individual, or other unofficial third-party account. The agency will not accept any responsibility or liability for transactions conducted on unofficial payment channels.\r\n                        </div>\r\n                    </div>\r\n\r\n                    <p>\r\n                        We are fundamentally dedicated to maintaining the highest industry standards of construction pace, legal transparency, and community development. We assure you that our development milestones are progressing rapidly, and we are on track to bring this master-planned community to life.\r\n                    </p>\r\n                    <p>\r\n                        Should you have any inquiries regarding installment structures, development timelines, or future allotment ballots, please do not hesitate to reach our corporate customer care desk at <strong>{{agency_phone}}</strong> or write to us directly at <strong>{{agency_email}}</strong>.\r\n                    </p>\r\n                    <p class=\"pt-1\">\r\n                        We sincerely thank you for placing your trust in our organization. Welcome to your secure future.\r\n                    </p>\r\n                    <p class=\"font-bold text-emerald-950 pt-1 leading-tight\">\r\n                        Warm regards,\r\n                    </p>\r\n                    <p class=\"text-xs font-semibold text-emerald-800 leading-none\">\r\n                        The Executive Committee of {{agency_name}}\r\n                    </p>\r\n                </div>\r\n            </div>\r\n\r\n            <!-- Footer: Symmetrical Signatures & Large QR Block -->\r\n            <footer class=\"text-[10px] relative mt-16 pb-4\">\r\n                <div class=\"grid grid-cols-12 gap-3 items-end text-center border-t border-emerald-200 pt-4\">\r\n                    \r\n                    <!-- Left: Chairman Sign (Chief Executive Officer) -->\r\n                    <div class=\"col-span-4 flex flex-col items-center\">\r\n                        <div class=\"h-16\"></div> <!-- Space for Signature -->\r\n                        <span class=\"block border-t border-emerald-900/60 mt-0.5 w-full uppercase text-emerald-950 font-bold\">Chairman Sign</span>\r\n                        <span class=\"block text-gray-600 text-[9px] mt-0.5 font-semibold\" id=\"letter-display-chairman\">Chief Executive Officer</span>\r\n                    </div>\r\n                    \r\n                    <!-- Center: Symmetrical Security QR Block resized to exactly 0.75 x 0.75 inches -->\r\n                    <div class=\"col-span-4 flex flex-col items-center justify-center\">\r\n                        <div class=\"flex items-center justify-center space-x-3 mb-1\">\r\n                            <!-- Symmetrical centered QR Code wrapper configured strictly to 0.75 x 0.75 inches -->\r\n                            <div class=\"border border-emerald-900/20 p-1.5 bg-white flex items-center justify-center rounded shadow-sm flex-shrink-0\" style=\"width: 0.75in; height: 0.75in;\">{{letter_deal_qr}}</div>\r\n                        </div>\r\n                        <span class=\"text-[7.5px] text-gray-500 uppercase tracking-widest font-sans font-bold\">Scan to Verify</span>\r\n                    </div>\r\n\r\n                    <!-- Right: Date -->\r\n                    <div class=\"col-span-4 flex flex-col items-center\">\r\n                        <div class=\"h-16\"></div> <!-- Matching height for layout symmetry -->\r\n                        <span class=\"block border-t border-emerald-900/60 mt-0.5 w-full uppercase text-emerald-950 font-bold\">Date</span>\r\n                        <span class=\"block text-gray-600 text-[9px] mt-0.5\" id=\"letter-display-date\">{{letter_date}}</span>\r\n                    </div>\r\n                </div>\r\n\r\n                <!-- Footer Barcode Verification Line -->\r\n                <div class=\"mt-6 flex flex-col items-center justify-center opacity-85\">\r\n                    <svg id=\"secure-barcode\" class=\"h-5 w-44\" viewBox=\"0 0 100 20\" preserveAspectRatio=\"none\">\r\n                        <!-- Barcode patterns populated dynamically from {{deal_invoice_no}} -->\r\n                    </svg>\r\n                    <span class=\"text-[7px] text-gray-500 font-mono mt-0.5 tracking-widest\">ID-{{deal_invoice_no}}</span>\r\n                </div>\r\n            </footer>\r\n        </div>\r\n\r\n    </div>\r\n\r\n    <script>\r\n        /**\r\n         * Image Fallback Script Block to prevent unrendered template variables \r\n         * or blocked remote assets from hanging layout rendering.\r\n         */\r\n        function handleLogoError(img) {\r\n            img.onerror = null;\r\n            img.src = \"data:image/svg+xml;charset=utf-8,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22112%22%20height%3D%22112%22%20viewBox%3D%220%200%20112%20112%22%3E%3Crect%20width%3D%22100%25%22%20height%3D%22100%25%22%20fill%3D%22%23064e3b%22%2F%3E%3Ctext%20x%3D%2250%25%22%20y%3D%2250%25%22%20dominant-baseline%3D%22middle%22%20text-anchor%3D%22middle%22%20fill%3D%22%23ffffff%22%20font-family%3D%22sans-serif%22%20font-size%3D%2212%22%20font-weight%3D%22bold%22%3EAGENCY%20LOGO%3C%2Ftext%3E%3C%2Fsvg%3E\";\r\n        }\r\n\r\n        function handlePhotoError(img) {\r\n            img.onerror = null;\r\n            img.src = \"data:image/svg+xml;charset=utf-8,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%2296%22%20height%3D%22128%22%20viewBox%3D%220%200%2096%20128%22%3E%3Crect%20width%3D%22100%25%22%20height%3D%22100%25%22%20fill%3D%22%23e2e8f0%22%2F%3E%3Ccircle%20cx%3D%2248%22%20cy%3D%2245%22%20r%3D%2220%22%20fill%3D%22%2394a3b8%22%2F%3E%3Cpath%20d%3D%22M%2012%20110%20C%2012%2085%2C%2084%2085%2C%2084%20110%20Z%22%20fill%3D%22%2394a3b8%22%2F%3E%3Ctext%20x%3D%2250%25%22%20y%3D%2292%25%22%20dominant-baseline%3D%22middle%22%20text-anchor%3D%22middle%22%20fill%3D%22%23475569%22%20font-family%3D%22sans-serif%22%20font-size%3D%2210%22%20font-weight%3D%22bold%22%3EPHOTO%3C%2Ftext%3E%3C%2Fsvg%3E\";\r\n        }\r\n\r\n        function handleWatermarkError(img) {\r\n            img.onerror = null;\r\n            img.style.display = \'none\';\r\n        }\r\n\r\n        /**\r\n         * Helper parses the unformatted date and returns a \"DD-MMM-YYYY\" string (e.g., 06-Jan-2026)\r\n         */\r\n        function parseAndFormatDate(dateStr) {\r\n            if (!dateStr || dateStr.includes(\'{{\') || dateStr.includes(\'}}\')) {\r\n                return dateStr;\r\n            }\r\n            \r\n            let parsedDate = null;\r\n            let dateObj = new Date(dateStr);\r\n            if (!isNaN(dateObj.getTime())) {\r\n                parsedDate = dateObj;\r\n            } else {\r\n                const parts = dateStr.split(/[-/.]/);\r\n                if (parts.length === 3) {\r\n                    let day, month, year;\r\n                    if (parts[2].length === 4) {\r\n                        day = parseInt(parts[0], 10);\r\n                        month = parseInt(parts[1], 10) - 1;\r\n                        year = parseInt(parts[2], 10);\r\n                    } else if (parts[0].length === 4) {\r\n                        year = parseInt(parts[0], 10);\r\n                        month = parseInt(parts[1], 10) - 1;\r\n                        day = parseInt(parts[2], 10);\r\n                    }\r\n                    \r\n                    if (year && !isNaN(month) && month >= 0 && month < 12 && day && day > 0 && day <= 31) {\r\n                        parsedDate = new Date(year, month, day);\r\n                    }\r\n                }\r\n            }\r\n            \r\n            if (parsedDate && !isNaN(parsedDate.getTime())) {\r\n                const months = [\'Jan\', \'Feb\', \'Mar\', \'Apr\', \'May\', \'Jun\', \'Jul\', \'Aug\', \'Sep\', \'Oct\', \'Nov\', \'Dec\'];\r\n                const formattedDay = String(parsedDate.getDate()).padStart(2, \'0\');\r\n                const formattedMonth = months[parsedDate.getMonth()];\r\n                const formattedYear = parsedDate.getFullYear();\r\n                return `${formattedDay}-${formattedMonth}-${formattedYear}`;\r\n            }\r\n            \r\n            return dateStr;\r\n        }\r\n\r\n        /**\r\n         * Generates a unique secure pseudo-barcode matching the invoice ID sequence\r\n         */\r\n        function generateSecureBarcode() {\r\n            const barcodeSvg = document.getElementById(\'secure-barcode\');\r\n            if (!barcodeSvg) return;\r\n            \r\n            const rawId = \"{{deal_invoice_no}}\".trim();\r\n            const cleanId = rawId.includes(\'{{\') ? \'0100234001920\' : rawId.replace(/[^0-9]/g, \'\');\r\n            \r\n            let innerHtml = \'<rect width=\"100\" height=\"20\" fill=\"#ffffff\"/>\';\r\n            let cursor = 5;\r\n            \r\n            for (let i = 0; i < 30; i++) {\r\n                const charCodeVal = cleanId.charCodeAt(i % cleanId.length) || 103;\r\n                const barWidth = (charCodeVal % 2 === 0) ? 1.5 : 0.6;\r\n                const gapWidth = (charCodeVal % 3 === 0) ? 1.2 : 0.8;\r\n                \r\n                innerHtml += `<rect x=\"${cursor}\" y=\"0\" width=\"${barWidth}\" height=\"20\" fill=\"#111827\"/>`;\r\n                cursor += barWidth + gapWidth;\r\n                if (cursor > 95) break;\r\n            }\r\n            barcodeSvg.innerHTML = innerHtml;\r\n        }\r\n\r\n        function initWelcomeLetter() {\r\n            // Secure Barcode Generator\r\n            generateSecureBarcode();\r\n\r\n            // Date Format initializations\r\n            const dateElements = [\'display-date\', \'letter-display-date\'];\r\n            dateElements.forEach(function(id) {\r\n                const element = document.getElementById(id);\r\n                if (element) {\r\n                    const rawDate = element.textContent.trim();\r\n                    element.textContent = parseAndFormatDate(rawDate);\r\n                }\r\n            });\r\n        }\r\n\r\n        if (document.readyState !== \'loading\') {\r\n            initWelcomeLetter();\r\n        } else {\r\n            document.addEventListener(\'DOMContentLoaded\', initWelcomeLetter);\r\n        }\r\n    </script>\r\n</body>\r\n</html>', 'RLT_WELCOME', 'Unpublished', 'No', '', 'letter_signatures', '', 'letter_signatures');
INSERT INTO `templates` (`id`, `name`, `description`, `type`, `status`, `is_new`, `ceo_signature`, `ceo_signature_dir`, `chairman_signature`, `chairman_signature_dir`) VALUES
(11, 'Booking Letter', '<style type=\"text/css\" id=\"wv-urdu-font-definitions\">\n@font-face {\n    font-family: \'Jameel Noori Nastaleeq\';\n    src: url(\'/whitevillas/fonts/JameelNooriNastaleeq.ttf\') format(\'truetype\'),\n         url(\'/fonts/JameelNooriNastaleeq.ttf\') format(\'truetype\'),\n         url(\'../fonts/JameelNooriNastaleeq.ttf\') format(\'truetype\');\n    font-weight: normal;\n    font-style: normal;\n    font-display: swap;\n}\n@font-face {\n    font-family: \'Jameel Noori Nastaleeq Kasheeda\';\n    src: url(\'/whitevillas/fonts/JameelNooriNastaleeqKasheeda.ttf\') format(\'truetype\'),\n         url(\'/fonts/JameelNooriNastaleeqKasheeda.ttf\') format(\'truetype\'),\n         url(\'../fonts/JameelNooriNastaleeqKasheeda.ttf\') format(\'truetype\');\n    font-weight: normal;\n    font-style: normal;\n    font-display: swap;\n}\n*, *:before, *:after {\n    -webkit-print-color-adjust: exact !important;\n    print-color-adjust: exact !important;\n    color-adjust: exact !important;\n}\n[lang=\"ur\"], [dir=\"rtl\"], .urdu-text, .ashtam-page, .letter-ur, .urdu-body, .urdu-legal {\n    font-family: \'Jameel Noori Nastaleeq\', \'Noto Nastaliq Urdu\', \'Nafees Nastaleeq\', serif !important;\n    line-height: 1.85 !important;\n    letter-spacing: 0 !important;\n    word-spacing: 0 !important;\n}\n[lang=\"ur\"] h1, [lang=\"ur\"] h2, [lang=\"ur\"] h3, [lang=\"ur\"] h4, [lang=\"ur\"] h5, [lang=\"ur\"] h6,\n[dir=\"rtl\"] h1, [dir=\"rtl\"] h2, [dir=\"rtl\"] h3, [dir=\"rtl\"] h4, [dir=\"rtl\"] h5, [dir=\"rtl\"] h6,\n.ashtam-page h1, .ashtam-page h2, .ashtam-page h3, .ashtam-page h4,\n.urdu-heading, .ashtam-heading, .document-title, .document-subtitle, .section-title, .sign-title, .bismillah {\n    font-family: \'Jameel Noori Nastaleeq Kasheeda\', \'Jameel Noori Nastaleeq\', \'Noto Nastaliq Urdu\', serif !important;\n    font-weight: normal !important;\n    line-height: 1.5 !important;\n}\n[lang=\"ur\"] p, [lang=\"ur\"] li, [lang=\"ur\"] td, [lang=\"ur\"] th, [lang=\"ur\"] span,\n[dir=\"rtl\"] p, [dir=\"rtl\"] li, [dir=\"rtl\"] td, [dir=\"rtl\"] th, [dir=\"rtl\"] span,\n.ashtam-page p, .ashtam-page li, .ashtam-page td, .ashtam-page th,\n.urdu-body p, .clause, .note-box, .amount-box {\n    font-family: \'Jameel Noori Nastaleeq\', \'Noto Nastaliq Urdu\', \'Nafees Nastaleeq\', serif !important;\n    line-height: 1.85 !important;\n}\n@media print {\n    @page { size: auto; margin: 0; }\n    html, body {\n        background: #ffffff !important;\n        color: #000000 !important;\n        margin: 0 !important;\n        padding: 0 !important;\n    }\n    .ashtam-page, .page, .form-container, .container, .letter-preview-print {\n        margin: 0 auto !important;\n        box-shadow: none !important;\n        -webkit-print-color-adjust: exact !important;\n        print-color-adjust: exact !important;\n        color-adjust: exact !important;\n    }\n}\n</style><p><strong>Date:</strong> {{letter_date}}<br><strong>Reference:</strong> {{letter_ref_no}}</p><p>Dear {{client_name}},</p><p>This is to confirm your booking of <strong>{{property_name}}</strong> in {{project_name}}.</p><p><strong>Membership No:</strong> {{deal_invoice_no}}<br><strong>Booking Date:</strong> {{deal_date}}<br><strong>Total Amount:</strong> {{deal_total_amount}}<br><strong>Booking Amount:</strong> {{deal_booking_amount}}</p><p>Regards,<br>{{site_organization}}</p><p><strong>Allotment No:</strong> {{ballot_allotment_no}}</p>', 'RLT_BOOKING', 'Unpublished', 'No', '', 'letter_signatures', '', 'letter_signatures'),
(12, 'Demarcation Letter', '<style type=\"text/css\" id=\"wv-urdu-font-definitions\">\n@font-face {\n    font-family: \'Jameel Noori Nastaleeq\';\n    src: url(\'/whitevillas/fonts/JameelNooriNastaleeq.ttf\') format(\'truetype\'),\n         url(\'/fonts/JameelNooriNastaleeq.ttf\') format(\'truetype\'),\n         url(\'../fonts/JameelNooriNastaleeq.ttf\') format(\'truetype\');\n    font-weight: normal;\n    font-style: normal;\n    font-display: swap;\n}\n@font-face {\n    font-family: \'Jameel Noori Nastaleeq Kasheeda\';\n    src: url(\'/whitevillas/fonts/JameelNooriNastaleeqKasheeda.ttf\') format(\'truetype\'),\n         url(\'/fonts/JameelNooriNastaleeqKasheeda.ttf\') format(\'truetype\'),\n         url(\'../fonts/JameelNooriNastaleeqKasheeda.ttf\') format(\'truetype\');\n    font-weight: normal;\n    font-style: normal;\n    font-display: swap;\n}\n*, *:before, *:after {\n    -webkit-print-color-adjust: exact !important;\n    print-color-adjust: exact !important;\n    color-adjust: exact !important;\n}\n[lang=\"ur\"], [dir=\"rtl\"], .urdu-text, .ashtam-page, .letter-ur, .urdu-body, .urdu-legal {\n    font-family: \'Jameel Noori Nastaleeq\', \'Noto Nastaliq Urdu\', \'Nafees Nastaleeq\', serif !important;\n    line-height: 1.85 !important;\n    letter-spacing: 0 !important;\n    word-spacing: 0 !important;\n}\n[lang=\"ur\"] h1, [lang=\"ur\"] h2, [lang=\"ur\"] h3, [lang=\"ur\"] h4, [lang=\"ur\"] h5, [lang=\"ur\"] h6,\n[dir=\"rtl\"] h1, [dir=\"rtl\"] h2, [dir=\"rtl\"] h3, [dir=\"rtl\"] h4, [dir=\"rtl\"] h5, [dir=\"rtl\"] h6,\n.ashtam-page h1, .ashtam-page h2, .ashtam-page h3, .ashtam-page h4,\n.urdu-heading, .ashtam-heading, .document-title, .document-subtitle, .section-title, .sign-title, .bismillah {\n    font-family: \'Jameel Noori Nastaleeq Kasheeda\', \'Jameel Noori Nastaleeq\', \'Noto Nastaliq Urdu\', serif !important;\n    font-weight: normal !important;\n    line-height: 1.5 !important;\n}\n[lang=\"ur\"] p, [lang=\"ur\"] li, [lang=\"ur\"] td, [lang=\"ur\"] th, [lang=\"ur\"] span,\n[dir=\"rtl\"] p, [dir=\"rtl\"] li, [dir=\"rtl\"] td, [dir=\"rtl\"] th, [dir=\"rtl\"] span,\n.ashtam-page p, .ashtam-page li, .ashtam-page td, .ashtam-page th,\n.urdu-body p, .clause, .note-box, .amount-box {\n    font-family: \'Jameel Noori Nastaleeq\', \'Noto Nastaliq Urdu\', \'Nafees Nastaleeq\', serif !important;\n    line-height: 1.85 !important;\n}\n@media print {\n    @page { size: auto; margin: 0; }\n    html, body {\n        background: #ffffff !important;\n        color: #000000 !important;\n        margin: 0 !important;\n        padding: 0 !important;\n    }\n    .ashtam-page, .page, .form-container, .container, .letter-preview-print {\n        margin: 0 auto !important;\n        box-shadow: none !important;\n        -webkit-print-color-adjust: exact !important;\n        print-color-adjust: exact !important;\n        color-adjust: exact !important;\n    }\n}\n</style><p><strong>Date:</strong> {{letter_date}}<br><strong>Reference:</strong> {{letter_ref_no}}</p><p>Dear {{client_name}},</p><p>This letter confirms that demarcation has been completed for your allotted unit.</p><p><strong>Membership No:</strong> {{deal_invoice_no}}<br><strong>Allotment No:</strong> {{ballot_allotment_no}}<br><strong>Property Number:</strong> {{ballot_property_no}}<br><strong>Block:</strong> {{ballot_block_name}}<br><strong>Street Address:</strong> {{ballot_street_address}}<br><strong>Area:</strong> {{ballot_area_full}}</p><p>Regards,<br>{{site_organization}}</p>', 'RLT_DEMARCATION', 'Published', 'No', '', 'letter_signatures', '', 'letter_signatures'),
(13, 'Design / Map Approval Letter', '<style type=\"text/css\" id=\"wv-urdu-font-definitions\">\n@font-face {\n    font-family: \'Jameel Noori Nastaleeq\';\n    src: url(\'/whitevillas/fonts/JameelNooriNastaleeq.ttf\') format(\'truetype\'),\n         url(\'/fonts/JameelNooriNastaleeq.ttf\') format(\'truetype\'),\n         url(\'../fonts/JameelNooriNastaleeq.ttf\') format(\'truetype\');\n    font-weight: normal;\n    font-style: normal;\n    font-display: swap;\n}\n@font-face {\n    font-family: \'Jameel Noori Nastaleeq Kasheeda\';\n    src: url(\'/whitevillas/fonts/JameelNooriNastaleeqKasheeda.ttf\') format(\'truetype\'),\n         url(\'/fonts/JameelNooriNastaleeqKasheeda.ttf\') format(\'truetype\'),\n         url(\'../fonts/JameelNooriNastaleeqKasheeda.ttf\') format(\'truetype\');\n    font-weight: normal;\n    font-style: normal;\n    font-display: swap;\n}\n*, *:before, *:after {\n    -webkit-print-color-adjust: exact !important;\n    print-color-adjust: exact !important;\n    color-adjust: exact !important;\n}\n[lang=\"ur\"], [dir=\"rtl\"], .urdu-text, .ashtam-page, .letter-ur, .urdu-body, .urdu-legal {\n    font-family: \'Jameel Noori Nastaleeq\', \'Noto Nastaliq Urdu\', \'Nafees Nastaleeq\', serif !important;\n    line-height: 1.85 !important;\n    letter-spacing: 0 !important;\n    word-spacing: 0 !important;\n}\n[lang=\"ur\"] h1, [lang=\"ur\"] h2, [lang=\"ur\"] h3, [lang=\"ur\"] h4, [lang=\"ur\"] h5, [lang=\"ur\"] h6,\n[dir=\"rtl\"] h1, [dir=\"rtl\"] h2, [dir=\"rtl\"] h3, [dir=\"rtl\"] h4, [dir=\"rtl\"] h5, [dir=\"rtl\"] h6,\n.ashtam-page h1, .ashtam-page h2, .ashtam-page h3, .ashtam-page h4,\n.urdu-heading, .ashtam-heading, .document-title, .document-subtitle, .section-title, .sign-title, .bismillah {\n    font-family: \'Jameel Noori Nastaleeq Kasheeda\', \'Jameel Noori Nastaleeq\', \'Noto Nastaliq Urdu\', serif !important;\n    font-weight: normal !important;\n    line-height: 1.5 !important;\n}\n[lang=\"ur\"] p, [lang=\"ur\"] li, [lang=\"ur\"] td, [lang=\"ur\"] th, [lang=\"ur\"] span,\n[dir=\"rtl\"] p, [dir=\"rtl\"] li, [dir=\"rtl\"] td, [dir=\"rtl\"] th, [dir=\"rtl\"] span,\n.ashtam-page p, .ashtam-page li, .ashtam-page td, .ashtam-page th,\n.urdu-body p, .clause, .note-box, .amount-box {\n    font-family: \'Jameel Noori Nastaleeq\', \'Noto Nastaliq Urdu\', \'Nafees Nastaleeq\', serif !important;\n    line-height: 1.85 !important;\n}\n@media print {\n    @page { size: auto; margin: 0; }\n    html, body {\n        background: #ffffff !important;\n        color: #000000 !important;\n        margin: 0 !important;\n        padding: 0 !important;\n    }\n    .ashtam-page, .page, .form-container, .container, .letter-preview-print {\n        margin: 0 auto !important;\n        box-shadow: none !important;\n        -webkit-print-color-adjust: exact !important;\n        print-color-adjust: exact !important;\n        color-adjust: exact !important;\n    }\n}\n</style><p><strong>Date:</strong> {{letter_date}}<br><strong>Reference:</strong> {{letter_ref_no}}</p><p>Dear {{client_name}},</p><p>Your design/map submission for <strong>{{property_name}}</strong> has been approved subject to applicable by-laws and authority rules.</p><p><strong>Membership No:</strong> {{deal_invoice_no}}<br><strong>Project:</strong> {{project_name}}<br><strong>Property Type:</strong> {{property_type}}</p><p>Regards,<br>{{site_organization}}</p><p><strong>Allotment No:</strong> {{ballot_allotment_no}}<br><strong>Property Number:</strong> {{ballot_property_no}}<br><strong>Block:</strong> {{ballot_block_name}}<br><strong>Street Address:</strong> {{ballot_street_address}}<br><strong>Area:</strong> {{ballot_area_full}}</p>', 'RLT_DESIGN_MAP_APPROVAL', 'Published', 'No', '', 'letter_signatures', '', 'letter_signatures'),
(14, 'NOC Letter', '<style type=\"text/css\" id=\"wv-urdu-font-definitions\">\n@font-face {\n    font-family: \'Jameel Noori Nastaleeq\';\n    src: url(\'/whitevillas/fonts/JameelNooriNastaleeq.ttf\') format(\'truetype\'),\n         url(\'/fonts/JameelNooriNastaleeq.ttf\') format(\'truetype\'),\n         url(\'../fonts/JameelNooriNastaleeq.ttf\') format(\'truetype\');\n    font-weight: normal;\n    font-style: normal;\n    font-display: swap;\n}\n@font-face {\n    font-family: \'Jameel Noori Nastaleeq Kasheeda\';\n    src: url(\'/whitevillas/fonts/JameelNooriNastaleeqKasheeda.ttf\') format(\'truetype\'),\n         url(\'/fonts/JameelNooriNastaleeqKasheeda.ttf\') format(\'truetype\'),\n         url(\'../fonts/JameelNooriNastaleeqKasheeda.ttf\') format(\'truetype\');\n    font-weight: normal;\n    font-style: normal;\n    font-display: swap;\n}\n*, *:before, *:after {\n    -webkit-print-color-adjust: exact !important;\n    print-color-adjust: exact !important;\n    color-adjust: exact !important;\n}\n[lang=\"ur\"], [dir=\"rtl\"], .urdu-text, .ashtam-page, .letter-ur, .urdu-body, .urdu-legal {\n    font-family: \'Jameel Noori Nastaleeq\', \'Noto Nastaliq Urdu\', \'Nafees Nastaleeq\', serif !important;\n    line-height: 1.85 !important;\n    letter-spacing: 0 !important;\n    word-spacing: 0 !important;\n}\n[lang=\"ur\"] h1, [lang=\"ur\"] h2, [lang=\"ur\"] h3, [lang=\"ur\"] h4, [lang=\"ur\"] h5, [lang=\"ur\"] h6,\n[dir=\"rtl\"] h1, [dir=\"rtl\"] h2, [dir=\"rtl\"] h3, [dir=\"rtl\"] h4, [dir=\"rtl\"] h5, [dir=\"rtl\"] h6,\n.ashtam-page h1, .ashtam-page h2, .ashtam-page h3, .ashtam-page h4,\n.urdu-heading, .ashtam-heading, .document-title, .document-subtitle, .section-title, .sign-title, .bismillah {\n    font-family: \'Jameel Noori Nastaleeq Kasheeda\', \'Jameel Noori Nastaleeq\', \'Noto Nastaliq Urdu\', serif !important;\n    font-weight: normal !important;\n    line-height: 1.5 !important;\n}\n[lang=\"ur\"] p, [lang=\"ur\"] li, [lang=\"ur\"] td, [lang=\"ur\"] th, [lang=\"ur\"] span,\n[dir=\"rtl\"] p, [dir=\"rtl\"] li, [dir=\"rtl\"] td, [dir=\"rtl\"] th, [dir=\"rtl\"] span,\n.ashtam-page p, .ashtam-page li, .ashtam-page td, .ashtam-page th,\n.urdu-body p, .clause, .note-box, .amount-box {\n    font-family: \'Jameel Noori Nastaleeq\', \'Noto Nastaliq Urdu\', \'Nafees Nastaleeq\', serif !important;\n    line-height: 1.85 !important;\n}\n@media print {\n    @page { size: auto; margin: 0; }\n    html, body {\n        background: #ffffff !important;\n        color: #000000 !important;\n        margin: 0 !important;\n        padding: 0 !important;\n    }\n    .ashtam-page, .page, .form-container, .container, .letter-preview-print {\n        margin: 0 auto !important;\n        box-shadow: none !important;\n        -webkit-print-color-adjust: exact !important;\n        print-color-adjust: exact !important;\n        color-adjust: exact !important;\n    }\n}\n</style><p><strong>Date:</strong> {{letter_date}}<br><strong>Reference:</strong> {{letter_ref_no}}</p><p>Dear {{client_name}},</p><p>No Objection Certificate is hereby issued for <strong>{{property_name}}</strong> (Membership {{deal_invoice_no}}), subject to company policy and record verification.</p><p>Regards,<br>{{site_organization}}</p><p><strong>Allotment No:</strong> {{ballot_allotment_no}}<br><strong>Property Number:</strong> {{ballot_property_no}}<br><strong>Block:</strong> {{ballot_block_name}}<br><strong>Street Address:</strong> {{ballot_street_address}}</p>', 'RLT_NOC', 'Published', 'No', '', 'letter_signatures', '', 'letter_signatures'),
(15, 'Deal Charges Agreement', '<!DOCTYPE html>\n<html lang=\"ur\" dir=\"rtl\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>معاہدہ برائے اضافی کام / اضافی چارجز</title>\n    <style>\n        @font-face {\n            font-family: \'Jameel Noori Nastaleeq\';\n            src: url(\'/whitevillas/fonts/JameelNooriNastaleeq.ttf\') format(\'truetype\'),\n                 url(\'/fonts/JameelNooriNastaleeq.ttf\') format(\'truetype\'),\n                 url(\'../fonts/JameelNooriNastaleeq.ttf\') format(\'truetype\');\n            font-weight: normal;\n            font-style: normal;\n            font-display: swap;\n        }\n        @font-face {\n            font-family: \'Jameel Noori Nastaleeq Kasheeda\';\n            src: url(\'/whitevillas/fonts/JameelNooriNastaleeqKasheeda.ttf\') format(\'truetype\'),\n                 url(\'/fonts/JameelNooriNastaleeqKasheeda.ttf\') format(\'truetype\'),\n                 url(\'../fonts/JameelNooriNastaleeqKasheeda.ttf\') format(\'truetype\');\n            font-weight: normal;\n            font-style: normal;\n            font-display: swap;\n        }\n        @page { size: A4; margin: 7mm; }\n        * { box-sizing: border-box; }\n        html, body { margin: 0; padding: 0; background: #eef2f6; color: #000; }\n        body {\n            font-family: \"Jameel Noori Nastaleeq\", \"Noto Nastaliq Urdu\", \"Nafees Nastaleeq\", serif;\n            font-size: 13px;\n            line-height: 1.75;\n            direction: rtl;\n        }\n        .ashtam-page {\n            width: 196mm;\n            min-height: 283mm;\n            margin: 0 auto;\n            background: #fff;\n            border: 1px solid #111;\n            padding: 8mm 9mm;\n            position: relative;\n            overflow: hidden;\n        }\n        .ashtam-page:before {\n            content: \"اشٹام معاہدہ\";\n            position: absolute;\n            top: 49%;\n            left: 50%;\n            transform: translate(-50%,-50%) rotate(-35deg);\n            font-size: 54px;\n            font-weight: 900;\n            font-family: \"Jameel Noori Nastaleeq Kasheeda\", serif;\n            color: rgba(0,0,0,.035);\n            white-space: nowrap;\n            pointer-events: none;\n        }\n        .ashtam-page > * { position: relative; z-index: 2; }\n        .letterhead { display: grid; grid-template-columns: 82px minmax(0,1fr) 150px; gap: 12px; align-items: center; border-bottom: 2px solid #111; padding-bottom: 7px; margin-bottom: 7px; direction: ltr; }\n        .logo-box { width: 78px; height: 70px; display: flex; align-items: center; justify-content: center; direction: ltr; }\n        .agency-copy { text-align: center; direction: rtl; }\n        .agency-copy h1 { margin: 0; font-family: Arial, Helvetica, sans-serif; font-size: 22px; line-height: 1.15; text-transform: uppercase; font-weight: 900; letter-spacing: 0; color: #000; }\n        .agency-copy p { margin: 2px 0 0; font-family: \"Jameel Noori Nastaleeq\", serif; font-size: 12px; line-height: 1.35; color: #000; }\n        .meta-box { font-family: Arial, Helvetica, sans-serif; font-size: 10px; line-height: 1.6; text-align: left; direction: ltr; color: #000; }\n        .bismillah { text-align: center; font-family: \"Jameel Noori Nastaleeq Kasheeda\", serif; font-size: 20px; font-weight: 900; line-height: 1.4; margin: 4px 0 1px; }\n        .doc-title { text-align: center; border: 2px solid #111; padding: 5px 8px; margin: 4px 0 8px; background: #f7f7f7; }\n        .doc-title h2 { margin: 0; font-family: \"Jameel Noori Nastaleeq Kasheeda\", serif; font-size: 21px; line-height: 1.35; font-weight: 900; }\n        .doc-title p { margin: 0; font-family: \"Jameel Noori Nastaleeq Kasheeda\", serif; font-size: 13px; font-weight: 700; }\n        .section-title { font-family: \"Jameel Noori Nastaleeq Kasheeda\", serif; font-size: 15px; font-weight: 900; border-bottom: 1px solid #111; margin: 7px 0 4px; padding-bottom: 2px; }\n        p { margin: 0 0 5px; text-align: justify; }\n        .info-grid { width: 100%; border-collapse: collapse; margin: 5px 0 7px; font-size: 12.5px; line-height: 1.55; }\n        .info-grid th, .info-grid td { border: 1px solid #111; padding: 4px 6px; vertical-align: top; }\n        .info-grid th { width: 21%; background: #f6f6f6; font-weight: 900; white-space: nowrap; font-family: \"Jameel Noori Nastaleeq Kasheeda\", serif; }\n        .terms { counter-reset: term; margin-top: 4px; }\n        .term { display: grid; grid-template-columns: 24px minmax(0,1fr); gap: 5px; margin: 0 0 4px; break-inside: avoid; }\n        .term:before { counter-increment: term; content: counter(term) \"۔\"; font-weight: 900; text-align: center; }\n        .term strong { font-weight: 900; }\n        .charge-table { width: 100%; border-collapse: collapse; margin: 5px 0 7px; font-size: 11.5px; line-height: 1.45; }\n        .charge-table th, .charge-table td { border: 1px solid #111; padding: 4px 6px; text-align: center; vertical-align: top; }\n        .charge-table th { background: #f4f4f4; font-weight: 900; font-family: \"Jameel Noori Nastaleeq Kasheeda\", serif; }\n        .amount-highlight { font-weight: 900; text-decoration: underline; }\n        .signatures { width: 100%; border-collapse: collapse; margin-top: 8px; font-size: 12.5px; line-height: 1.55; }\n        .signatures td { border: 1px solid #111; padding: 5px 7px; vertical-align: top; width: 50%; }\n        .line { display: inline-block; border-bottom: 1px solid #111; min-width: 170px; height: 16px; vertical-align: bottom; }\n        .footer { border-top: 2px solid #111; margin-top: 7px; padding-top: 4px; text-align: center; font-family: Arial, Helvetica, sans-serif; font-size: 9px; line-height: 1.35; direction: ltr; }\n        @media print {\n            @page { size: A4; margin: 7mm; }\n            html, body { margin: 0 !important; padding: 0 !important; background: #eef2f6 !important; }\n            .ashtam-page { width: 196mm !important; min-height: 283mm !important; margin: 0 auto !important; background: #fff !important; border: 1px solid #111 !important; padding: 8mm 9mm !important; box-shadow: none !important; }\n            body, .ashtam-page, .ashtam-page * { color: #000 !important; }\n            .doc-title, .info-grid th, .charge-table th { -webkit-print-color-adjust: exact; print-color-adjust: exact; }\n        }\n    </style>\n</head>\n<body>\n<div class=\"ashtam-page\">\n    <div class=\"letterhead\">\n        <div class=\"logo-box\">{{agency_logo}}</div>\n        <div class=\"agency-copy\">\n            <h1>{{agency_name}}</h1>\n            <p>مجاز ڈیلر و تعمیراتی خدمات | وائٹ ولاز پراجیکٹ</p>\n        </div>\n        <div class=\"meta-box\">\n            <div><strong>Ref:</strong> {{charge_agreement_ref_no}}</div>\n            <div><strong>Date:</strong> {{charge_agreement_date}}</div>\n            <div><strong>File No:</strong> {{deal_invoice_no}}</div>\n        </div>\n    </div>\n    <div class=\"bismillah\">بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ</div>\n    <div class=\"doc-title\">\n        <h2>معاہدہ برائے اضافی کام و اضافی چارجز</h2>\n        <p>پراجیکٹ: {{project_name}} | یونٹ نمبر: {{property_name}}</p>\n    </div>\n    <p>یہ تحریر مورخہ <strong>{{charge_agreement_date}}</strong> بمقام <strong>{{agreement_place}}</strong>، فریق اوّل یعنی <strong>{{agency_name}}</strong> اور فریق دوم یعنی <strong>{{client_name}}</strong> ولد / زوجہ <strong>{{client_father_name}}</strong>، شناختی کارڈ نمبر <strong>{{client_cnic}}</strong>، موبائل نمبر <strong>{{client_mobile}}</strong> کے مابین بقائمی ہوش و حواس بلا جبر و اکراہ تحریر کی گئی۔</p>\n    <div class=\"section-title\">پراپرٹی و الاٹمنٹ تفصیل</div>\n    <table class=\"info-grid\">\n        <tr>\n            <th>پراجیکٹ / ایجنسی:</th>\n            <td>{{project_name}} ({{agency_name}})</td>\n            <th>پراپرٹی / یونٹ:</th>\n            <td>{{property_name}} &bull; {{property_unit}} ({{property_area}})</td>\n        </tr>\n        <tr>\n            <th>کلائنٹ نام:</th>\n            <td>{{client_name}} ولد / زوجہ {{client_father_name}}</td>\n            <th>شناختی کارڈ / فون:</th>\n            <td>{{client_cnic}} &bull; {{client_mobile}}</td>\n        </tr>\n    </table>\n    <div class=\"section-title\">اضافی چارجز و اخراجات کی تفصیل</div>\n    {{charge_rows_table}}\n    <table class=\"info-grid\" style=\"margin-top:4px;\">\n        <tr>\n            <th>کل منظور شدہ رقم:</th>\n            <td class=\"amount-highlight\">{{charge_grand_total}} ({{charge_grand_total_words_urdu}})</td>\n            <th>کام کی موجودہ حالت:</th>\n            <td><strong>{{charge_work_status}}</strong></td>\n        </tr>\n    </table>\n    <div class=\"section-title\">ضوابط و شرائطِ اضافی کام</div>\n    <div class=\"terms\">\n        <div class=\"term\">اضافی کام فریق دوم کی باقاعدہ منظوری و طے شدہ تفصیلات کے مطابق مکمل کیا جائے گا۔</div>\n        <div class=\"term\">طے شدہ اضافی چارجز کی بروقت ادائیگی شیڈول کے مطابق فریق دوم پر لازم ہوگی۔</div>\n        <div class=\"term\">مکمل ادائیگی اور سائٹ تصدیق کے بعد متعلقہ اضافی تعمیرات یا سروس فریق دوم کے حوالے کی جائے گی۔</div>\n    </div>\n    <table class=\"signatures\">\n        <tr>\n            <td>\n                <strong>دستخط فریق اوّل (مجاز نمائندہ):</strong><br>\n                نام: {{agency_representative_name}}<br>\n                دستخط / مہر: <span class=\"line\"></span>\n            </td>\n            <td>\n                <strong>دستخط فریق دوم (کلائنٹ / الاٹی):</strong><br>\n                نام: {{client_name}}<br>\n                دستخط / انگوٹھا: <span class=\"line\"></span>\n            </td>\n        </tr>\n    </table>\n    <div class=\"footer\">\n        {{agency_address}} &bull; Phone: {{agency_phone}} &bull; Email: {{agency_email}}\n    </div>\n</div>\n</body>\n</html>', 'RLT_CHARGE', 'Published', 'No', '', 'letter_signatures', '', 'letter_signatures'),
(16, 'Refund Agreement', '<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>REFUND REQUEST APPLICATION - {{agency_name}}</title>\n    <!-- Load Tailwind CSS -->\n    <script src=\"https://cdn.tailwindcss.com\"></script>\n    <link href=\"https://fonts.googleapis.com/css2?family=Noto+Nastaliq+Urdu:wght@400..700&display=swap\" rel=\"stylesheet\">\n    <style>\n        .form-container {\n            /* OPTIMIZED FOR A4 PREVIEW */\n            max-width: 800px; \n            font-family: \'Times New Roman\', serif; \n            margin: 8px auto 40px auto; \n            background-color: white;\n            padding: 1rem 2.5rem 2.5rem 2.5rem; \n            border-radius: 0.5rem;\n            box-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.1);\n            color: #333;\n            border-top: 12px solid #DC2626; \n            position: relative;\n            overflow: hidden;\n        }\n        .form-section-title {\n            background-color: #fef2f2;\n            color: #b91c1c;\n            font-weight: 700;\n            padding: 0.5rem 1rem;\n            margin-top: 0; \n            margin-bottom: 1rem;\n            border-left: 5px solid #DC2626;\n            text-transform: uppercase;\n            letter-spacing: 0.05em;\n        }\n        .input-line {\n            border-bottom: 1px solid #9ca3af;\n            padding-left: 0.5rem;\n            flex-grow: 1;\n        }\n        .input-group {\n            display: flex;\n            align-items: center; \n            margin-bottom: 0.5rem;\n            font-size: 0.875rem;\n        }\n        .section-box {\n            border: 1px solid #e5e7eb;\n            border-radius: 0.5rem;\n            padding: 0.5rem;\n            margin-bottom: 1.5rem;\n        }\n        .refund-calc-header {\n            font-size: 16px; \n            font-weight: 700; \n            color: #DC2626;\n            background-color: #fef2f2;\n            padding: 0.5rem;\n            border-radius: 0.25rem;\n            border-bottom: 2px solid #DC2626;\n            text-align: center;\n        }\n        /* Table Styles for the Disbursement Schedule */\n        .schedule-table-container table {\n            width: 100%;\n            text-align: left;\n            border-collapse: collapse;\n        }\n        .schedule-table-container th, .schedule-table-container td {\n            padding: 6px 10px;\n            border: 1px solid #e5e7eb;\n            font-size: 0.75rem;\n        }\n        .schedule-table-container thead {\n            background-color: #f3f4f6;\n            font-weight: bold;\n        }\n\n        /* Tailwind-lite utility fallbacks (for print/no CDN) */\n        .flex{display:flex;}\n        .items-start{align-items:flex-start;}\n        .items-center{align-items:center;}\n        .items-end{align-items:flex-end;}\n        .justify-between{justify-content:space-between;}\n        .flex-col{flex-direction:column;}\n        .flex-grow{flex:1 1 0%;}\n        .flex-1{flex:1 1 0%;}\n        .flex-[2]{flex:2 1 0%;}\n        .flex-shrink-0{flex-shrink:0;}\n        .space-x-6 > :not([hidden]) ~ :not([hidden]){margin-left:1.5rem;}\n        .space-y-4 > :not([hidden]) ~ :not([hidden]){margin-top:1rem;}\n        .space-y-1 > :not([hidden]) ~ :not([hidden]){margin-top:.25rem;}\n        .border{border:1px solid #e5e7eb;}\n        .border-2{border:2px solid #e5e7eb;}\n        .border-b-2{border-bottom:2px solid #dc2626;}\n        .border-b-4{border-bottom:4px solid #dc2626;}\n        .border-gray-200{border-color:#e5e7eb;}\n        .border-gray-300{border-color:#d1d5db;}\n        .border-red-600{border-color:#dc2626;}\n        .rounded{border-radius:.25rem;}\n        .rounded-lg{border-radius:.5rem;}\n        .bg-gray-50{background:#f9fafb;}\n        .bg-red-50{background:#fef2f2;}\n        .text-gray-900{color:#111827;}\n        .text-gray-800{color:#1f2937;}\n        .text-gray-700{color:#374151;}\n        .text-gray-600{color:#4b5563;}\n        .text-gray-500{color:#6b7280;}\n        .text-gray-400{color:#9ca3af;}\n        .text-red-600{color:#dc2626;}\n        .text-red-700{color:#b91c1c;}\n        .uppercase{text-transform:uppercase;}\n        .tracking-tighter{letter-spacing:-.02em;}\n        .tracking-widest{letter-spacing:.15em;}\n        .leading-none{line-height:1;}\n        .leading-tight{line-height:1.25;}\n        .text-xs{font-size:.75rem;}\n        .text-sm{font-size:.875rem;}\n        .text-lg{font-size:1.125rem;}\n        .text-2xl{font-size:1.5rem;}\n        .text-3xl{font-size:1.875rem;}\n        .font-bold{font-weight:700;}\n        .font-black{font-weight:900;}\n        .font-extrabold{font-weight:800;}\n        .p-1{padding:.25rem;}\n        .p-2{padding:.5rem;}\n        .p-4{padding:1rem;}\n        .pb-4{padding-bottom:1rem;}\n        .pb-1{padding-bottom:.25rem;}\n        .px-8{padding-left:2rem;padding-right:2rem;}\n        .pr-1{padding-right:.25rem;}\n        .mb-6{margin-bottom:1.5rem;}\n        .mb-4{margin-bottom:1rem;}\n        .mb-1{margin-bottom:.25rem;}\n        .mt-3{margin-top:.75rem;}\n        .mt-8{margin-top:2rem;}\n        .ml-1{margin-left:.25rem;}\n        .w-12{width:3rem;}\n        .w-24{width:6rem;}\n        .h-24{height:6rem;}\n        .w-28{width:7rem;}\n        .h-32{height:8rem;}\n        .text-right{text-align:right;}\n        .text-center{text-align:center;}\n        .overflow-hidden{overflow:hidden;}\n        .shadow-sm{box-shadow:0 1px 2px 0 rgba(0,0,0,.05);}\n        .grid{display:grid;}\n        .grid-cols-2{grid-template-columns:repeat(2,minmax(0,1fr));}\n        .grid-cols-4{grid-template-columns:repeat(4,minmax(0,1fr));}\n        .gap-4{gap:1rem;}\n        .gap-x-4{column-gap:1rem;}\n        .border-t{border-top:1px solid #9ca3af;}\n        .border-dashed{border-style:dashed;}\n        .min-h\\[80px\\]{min-height:80px;}\n        .min-h\\[2\\.5rem\\]{min-height:2.5rem;}\n        .tracking-wider{letter-spacing:.05em;}\n        .text-\\[10px\\]{font-size:10px;}\n        .text-\\[11px\\]{font-size:11px;}\n        .w-full{width:100%;}\n        .h-full{height:100%;}\n        .object-cover{object-fit:cover;}\n        .border-red-100{border-color:#fee2e2;}\n        .border-gray-300{border-color:#d1d5db;}\n        .border-r{border-right:1px solid #d1d5db;}\n        .border-l{border-left:1px solid #d1d5db;}\n        @media print {\n            @page {\n                size: A4 portrait;\n                margin: 1.2cm; \n            }\n            body {\n                margin: 0;\n                padding: 0;\n                background: none;\n                font-family: \'Times New Roman\', serif !important; \n            }\n            .form-container {\n                max-width: 100%;\n                width: 100%;\n                margin: 0 auto;\n                padding: 0;\n                box-shadow: none;\n                border-top: none;\n                border: none;\n            }\n            .text-red-600, .text-red-700 {\n                color: #000 !important;\n            }\n            .input-line {\n                border-bottom: 1px solid #000;\n                word-wrap: break-word;\n            }\n            .page-break-after-print {\n                page-break-after: always;\n            }\n            footer {\n                font-size: 10px; \n          }\n      }\n    </style>\n</head>\n\n<body class=\"bg-gray-50 p-4\">\n\n    <div class=\"form-container\">\n        \n        <!-- AGENCY HEADER DESIGN -->\n        <header class=\"mb-3 flex justify-between items-center border-b-2 border-red-600 pb-2 gap-4\" style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;\">\n            <div class=\"flex items-center space-x-4 flex-1 min-w-0\" style=\"display:grid;grid-template-columns:110px minmax(0,1fr);align-items:center;gap:14px;flex:1 1 auto;min-width:0;\">\n                <!-- Agency Logo Left Side -->\n                <div class=\"w-24 h-24 flex-shrink-0 flex items-center justify-center overflow-hidden wv-letter-logo-box\" style=\"width:100px;height:100px;display:flex;align-items:center;justify-content:center;background:transparent;border:0;padding:0;overflow:visible;\">\n                    {{agency_logo}}\n                </div>\n\n                <!-- Agency Letterhead Text -->\n                <div class=\"flex-grow wv-letter-agency-copy\" style=\"text-align:center;min-width:0;\">\n                    <h1 class=\"text-2xl font-black text-gray-900 uppercase leading-tight\" style=\"text-align:center;margin:0;color:#111827;font-size:24px;line-height:1.15;font-weight:900;text-transform:uppercase;\">{{agency_name}}</h1>\n                    <div class=\"mt-2 text-[11px] text-gray-600 leading-tight space-y-0.5\">\n                        <p class=\"wv-agency-address-line\" style=\"margin:0;text-align:center;font-weight:700;color:#374151;\">{{agency_address}}</p>\n                        <!-- Combined Phone and Email in one row -->\n                        <div class=\"flex items-center space-x-6 wv-letter-contact-row\" style=\"display:flex;align-items:center;justify-content:center;gap:24px;margin-top:2px;text-align:center;\">\n                            <p class=\"flex items-center\" style=\"margin:0;\"><span class=\"font-bold w-12\">Phone:</span> {{agency_phone}}</p>\n                            <p class=\"flex items-center\" style=\"margin:0;\"><span class=\"font-bold w-12 text-right pr-1\">Email:</span> {{agency_email}}</p>\n                        </div>\n                    </div>\n                    <div class=\"wv-letter-header-title\" style=\"margin-top:8px;text-align:center;\">\n                        <p style=\"margin:0 auto;padding:0 18px 4px 18px;border-bottom:3px solid #111827;display:inline-block;color:#111827;font-size:17px;font-weight:900;line-height:1.15;text-transform:uppercase;\">DEAL PAYMENT REFUND FORM</p>\n                    </div>\n                </div>\n            </div>\n            \n            <!-- Letter Meta and Applicant Photo -->\n            <div class=\"flex flex-col items-end space-y-2 flex-shrink-0\">\n                <div class=\"text-right text-xs font-bold text-gray-700\">\n                    <p>Ref: <span class=\"font-normal text-gray-900\">{{letter_ref_no}}</span></p>\n                    <p>Date: <span class=\"font-normal text-gray-900\">{{letter_date}}</span></p>\n                </div>\n                <div class=\"w-20 h-24 border-2 border-gray-300 overflow-hidden bg-gray-50 shadow-sm\">\n                    {{applicant_photo}}\n                </div>\n            </div>\n        </header>\n\n        <!-- PROPERTY IDENTIFIER BLOCK -->\n        <div class=\"flex justify-between items-center text-sm font-extrabold mb-6 pb-2 border-b border-gray-200\">\n            <div class=\"ml-1\">\n                <span class=\"text-gray-500 font-extrabold\">Project / Property:</span> \n                <span class=\"text-red-600 ml-1 font-semibold\">{{property_name}}</span>\n            </div>\n            \n            <div>\n                <span class=\"text-gray-500 font-extrabold\">Deal Invoice:</span> \n                <span class=\"text-gray-800 ml-1 font-semibold\">{{deal_invoice_no}}</span>\n            </div>\n        </div>\n\n        <!-- PERSONAL INFORMATION -->\n        <div class=\"section-box mt-0\">\n            <div class=\"form-section-title\">Personal Information</div>\n            <div class=\"space-y-3 p-2\">\n                <div class=\"input-group\">\n                    <label class=\"w-44 flex-shrink-0 font-bold\">Applicant Name:</label>\n                    <div class=\"input-line text-sm font-medium uppercase\">{{client_name}}</div>\n                    <label class=\"ml-4 flex-shrink-0 font-bold\">{{client_relation_type_label}}:</label>\n                    <div class=\"input-line text-sm\">{{client_father_name}}</div>\n                </div>\n                \n                <div class=\"input-group\">\n                    <label class=\"w-44 flex-shrink-0 font-bold\">CNIC / NICOP:</label>\n                    <div class=\"input-line text-sm\">{{client_cnic}}</div>\n                    <label class=\"ml-4 flex-shrink-0 font-bold\">Passport No:</label>\n                    <div class=\"input-line text-sm\">{{refund_passport_no}}</div>\n                </div>\n\n                <div class=\"input-group items-start\"> \n                    <label class=\"w-44 flex-shrink-0 font-bold pt-1\">Permanent Address:</label>\n                    <div class=\"input-line text-sm min-h-[2.5rem] leading-relaxed\">{{client_address}}</div>\n                </div>\n\n                <div class=\"grid grid-cols-2 gap-x-4\">\n                    <div class=\"input-group\">\n                        <label class=\"w-20 flex-shrink-0 font-bold\">Mobile:</label>\n                        <div class=\"input-line text-sm font-semibold\">{{client_mobile}}</div>\n                    </div>\n                    <div class=\"input-group\">\n                        <label class=\"w-20 flex-shrink-0 font-bold\">E-mail:</label>\n                        <div class=\"input-line text-sm\">{{client_email}}</div>\n                    </div>\n                </div>\n            </div>\n        </div>\n\n        <!-- ORIGINAL PROPERTY DETAILS & REFUND CALCULATION -->\n        <div class=\"section-box\">\n            <div class=\"form-section-title\">Deal & Financial Statement</div>\n            <div class=\"grid grid-cols-10 gap-4 p-2\">\n                <div class=\"col-span-4 space-y-4\"> \n                    <div class=\"font-bold text-xs mb-1 text-gray-500 uppercase tracking-widest\">Inventory Details</div>\n                    <div class=\"input-group\">\n                        <label class=\"w-28 flex-shrink-0 font-extrabold\">Property:</label>\n                        <div class=\"input-line text-sm font-medium\">{{property_name}}</div>\n                    </div>\n                    <div class=\"input-group\">\n                        <label class=\"w-28 flex-shrink-0 font-extrabold\">Type:</label>\n                        <div class=\"input-line text-sm font-medium\">{{property_type}}</div>\n                    </div>\n                    <div class=\"input-group\">\n                        <label class=\"w-28 flex-shrink-0 font-extrabold\">Block:</label>\n                        <div class=\"input-line text-sm font-medium\">{{ballot_block_name}}</div>\n                    </div>\n                </div>\n\n                <div class=\"col-span-6\"> \n                    <div class=\"w-full border-2 border-red-100 p-4 text-xs text-gray-800 bg-gray-50 rounded-lg\">\n                        <p class=\"refund-calc-header mb-3 uppercase tracking-tighter\">Refund Assessment</p>\n                        <div class=\"space-y-2\">\n                            <div class=\"flex justify-between border-b border-gray-200 pb-1\">\n                                <span class=\"font-bold\">Total Paid Amount:</span>\n                                <span class=\"font-black text-gray-900\">{{refund_total_paid}}</span>\n                            </div>\n                            <div class=\"flex justify-between border-b border-gray-200 pb-1\">\n                                <span class=\"font-bold\">{{refund_adjustment_label}} ({{refund_adjustment_percent}}):</span>\n                                <span class=\"font-bold {{refund_adjustment_color}}\">{{refund_adjustment_sign}} {{refund_adjustment_amount}}</span>\n                            </div>\n                            <div class=\"flex justify-between pt-1\">\n                                <span class=\"text-sm font-black text-gray-900\">Net Refundable Amount:</span>\n                                <span class=\"text-sm font-black text-red-700\">{{refund_net_refund}}</span>\n                            </div>\n                        </div>\n                    </div>\n                </div>\n            </div>\n        </div>\n\n        <!-- REASON FOR CANCELLATION -->\n        <div class=\"section-box page-break-after-print\">\n            <div class=\"form-section-title\">Reason for Cancellation</div>\n            <div class=\"p-2\">\n                <div class=\"min-h-[80px] border-b border-dashed border-gray-400 text-base font-medium leading-relaxed\">\n                    {{refund_reason}}\n                </div>\n                <p class=\"text-[10px] text-gray-400 mt-2 uppercase font-bold\">\n                    *Management approval required for processing based on the statement above.\n                </p>\n            </div>\n        </div>\n\n        <!-- REFUND DISBURSEMENT SCHEDULE -->\n        <div class=\"section-box\">\n            <div class=\"form-section-title\">Disbursement Schedule</div>\n            <div class=\"p-2\">\n                <div class=\"flex justify-between items-center mb-4 bg-gray-50 p-2 border border-gray-200 rounded\">\n                    <div class=\"text-center px-4 flex-1\">\n                        <p class=\"text-[10px] uppercase font-bold text-gray-500\">Total Cycles</p>\n                        <p class=\"text-lg font-black text-gray-900\">{{refund_cycle_count}}</p>\n                    </div>\n                    <!-- Frequency column widened with increased padding and flex-grow -->\n                    <div class=\"text-center px-12 border-l border-r border-gray-300 flex-[2]\">\n                        <p class=\"text-[10px] uppercase font-bold text-gray-500\">Frequency</p>\n                        <p class=\"text-lg font-black text-red-600 uppercase\">{{refund_cycle_frequency}}</p>\n                    </div>\n                    <div class=\"text-center px-4 flex-1\">\n                        <p class=\"text-[10px] uppercase font-bold text-gray-500\">Cycle Amount</p>\n                        <p class=\"text-lg font-black text-red-700\">{{refund_cycle_amount}}</p>\n                    </div>\n                </div>\n\n                <div class=\"schedule-table-container\">\n                    {{refund_schedule_table}}\n                </div>\n            </div>\n        </div>\n\n        <!-- BANKING DETAILS -->\n        <div class=\"section-box\">\n            <div class=\"form-section-title\">Bank Account Details</div>\n            <div class=\"space-y-3 p-2\">\n                <div class=\"input-group\">\n                    <label class=\"w-40 flex-shrink-0 font-bold\">Account Title:</label>\n                    <div class=\"input-line text-sm font-medium uppercase\">{{refund_account_title}}</div>\n                </div>\n                <div class=\"input-group items-start\"> \n                    <label class=\"w-40 flex-shrink-0 font-bold pt-1\">Account No / IBAN:</label>\n                    <div class=\"input-line text-lg font-black text-gray-900 min-h-[2.5rem] tracking-wider\">{{refund_account_no}}</div>\n                </div>\n                <div class=\"grid grid-cols-2 gap-x-4\">\n                    <div class=\"input-group\">\n                        <label class=\"w-32 flex-shrink-0 font-bold\">Bank Name:</label>\n                        <div class=\"input-line text-sm uppercase\">{{refund_bank_name}}</div>\n                    </div>\n                    <div class=\"input-group\">\n                        <label class=\"w-32 flex-shrink-0 font-bold\">Branch:</label>\n                        <div class=\"input-line text-sm\">{{refund_bank_branch}}</div>\n                    </div>\n                </div>\n            </div>\n        </div>\n\n        <!-- TERMS & CONDITIONS -->\n        <div class=\"section-box p-4 border-red-600 border-2 bg-red-50\">\n            <h4 class=\"font-black text-red-800 uppercase mb-2 text-sm\">Declaration & Terms</h4>\n            <div class=\"terms-text space-y-2\">\n                <ol class=\"list-decimal list-inside pl-4 font-medium\">\n                    <li>{{refund_adjustment_statement}}</li>\n                    <li>Refund cycle will commence as per management approval and schedule.</li>\n                    <li>No claims will be entertained against the property unit once the first cycle is disbursed.</li>\n                </ol>\n            </div>\n        </div>\n        \n        <!-- FOOTER / SIGNATURES -->\n        <footer class=\"mt-12 text-xs\">\n            <div class=\"grid grid-cols-4 gap-4 text-center border-t border-gray-400 pt-1\">\n                <div class=\"font-bold pt-2 flex flex-col items-center\">\n                    <div class=\"h-10 w-full\"></div> \n                    <span class=\"mt-1 uppercase\">Officer Signature</span>\n                </div>\n                <div class=\"font-bold pt-2 flex flex-col items-center\">\n                    <div class=\"h-10 w-full\"></div> \n                    <span class=\"mt-1 uppercase\">Management Sign</span>\n                </div>\n                <div class=\"font-bold pt-2 flex flex-col items-center\">\n                    <div class=\"h-10 w-full\"></div> \n                    <span class=\"mt-1 uppercase\">Applicant Sign</span>\n                </div>\n                <div class=\"font-bold pt-2 flex flex-col items-center\">\n                    <div class=\"h-10 w-full\"></div> \n                    <span class=\"mt-1 uppercase\">Thumb Impression</span>\n                </div>\n            </div>\n            <p class=\"text-center text-red-600 font-black mt-8 uppercase tracking-widest text-[11px]\">\n                Official {{agency_name}} Refund Authorization Document\n            </p>\n        </footer>\n\n    </div>\n</body>\n</html>', 'RLT_REFUND', 'Published', 'No', '', 'letter_signatures', '', 'letter_signatures');
INSERT INTO `templates` (`id`, `name`, `description`, `type`, `status`, `is_new`, `ceo_signature`, `ceo_signature_dir`, `chairman_signature`, `chairman_signature_dir`) VALUES
(18, 'Refund Agreement', '<!DOCTYPE html>\r\n<html lang=\"en\">\r\n<head>\r\n    <meta charset=\"UTF-8\">\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n    <title>REFUND REQUEST APPLICATION - {{agency_name}}</title>\r\n    <!-- Load Tailwind CSS -->\r\n    <script src=\"https://cdn.tailwindcss.com\"></script>\r\n    <link href=\"https://fonts.googleapis.com/css2?family=Noto+Nastaliq+Urdu:wght@400..700&display=swap\" rel=\"stylesheet\">\r\n    <style>\r\n        .form-container {\r\n            /* OPTIMIZED FOR A4 PREVIEW */\r\n            max-width: 800px; \r\n            font-family: \'Times New Roman\', serif; \r\n            margin: 8px auto 40px auto; \r\n            background-color: white;\r\n            padding: 2.5rem; \r\n            border-radius: 0.5rem;\r\n            box-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.1);\r\n            color: #333;\r\n            border-top: 12px solid #DC2626; \r\n            position: relative;\r\n            overflow: hidden;\r\n        }\r\n        .form-section-title {\r\n            background-color: #fef2f2;\r\n            color: #b91c1c;\r\n            font-weight: 700;\r\n            padding: 0.5rem 1rem;\r\n            margin-top: 0; \r\n            margin-bottom: 1rem;\r\n            border-left: 5px solid #DC2626;\r\n            text-transform: uppercase;\r\n            letter-spacing: 0.05em;\r\n        }\r\n        .input-line {\r\n            border-bottom: 1px solid #9ca3af;\r\n            padding-left: 0.5rem;\r\n            flex-grow: 1;\r\n        }\r\n        .input-group {\r\n            display: flex;\r\n            align-items: center; \r\n            margin-bottom: 0.5rem;\r\n            font-size: 0.875rem;\r\n        }\r\n        .section-box {\r\n            border: 1px solid #e5e7eb;\r\n            border-radius: 0.5rem;\r\n            padding: 0.5rem;\r\n            margin-bottom: 1.5rem;\r\n        }\r\n        .refund-calc-header {\r\n            font-size: 16px; \r\n            font-weight: 700; \r\n            color: #DC2626;\r\n            background-color: #fef2f2;\r\n            padding: 0.5rem;\r\n            border-radius: 0.25rem;\r\n            border-bottom: 2px solid #DC2626;\r\n            text-align: center;\r\n        }\r\n        /* Table Styles for the Disbursement Schedule */\r\n        .schedule-table-container table {\r\n            width: 100%;\r\n            text-align: left;\r\n            border-collapse: collapse;\r\n        }\r\n        .schedule-table-container th, .schedule-table-container td {\r\n            padding: 6px 10px;\r\n            border: 1px solid #e5e7eb;\r\n            font-size: 0.75rem;\r\n        }\r\n        .schedule-table-container thead {\r\n            background-color: #f3f4f6;\r\n            font-weight: bold;\r\n        }\r\n\r\n        @media print {\r\n            @page {\r\n                size: A4 portrait;\r\n                margin: 1.2cm; \r\n            }\r\n            body {\r\n                margin: 0;\r\n                padding: 0;\r\n                background: none;\r\n                font-family: \'Times New Roman\', serif !important; \r\n            }\r\n            .form-container {\r\n                max-width: 100%;\r\n                width: 100%;\r\n                margin: 0 auto;\r\n                padding: 0;\r\n                box-shadow: none;\r\n                border-top: none;\r\n                border: none;\r\n            }\r\n            .text-red-600, .text-red-700 {\r\n                color: #000 !important;\r\n            }\r\n            .input-line {\r\n                border-bottom: 1px solid #000;\r\n                word-wrap: break-word;\r\n            }\r\n            .page-break-after-print {\r\n                page-break-after: always;\r\n            }\r\n            footer {\r\n                font-size: 10px; \r\n            }\r\n        }\r\n    </style>\r\n<style type=\"text/css\" id=\"wv-urdu-font-definitions\">\n@font-face {\n    font-family: \'Jameel Noori Nastaleeq\';\n    src: url(\'/whitevillas/fonts/JameelNooriNastaleeq.ttf\') format(\'truetype\'),\n         url(\'/fonts/JameelNooriNastaleeq.ttf\') format(\'truetype\'),\n         url(\'../fonts/JameelNooriNastaleeq.ttf\') format(\'truetype\');\n    font-weight: normal;\n    font-style: normal;\n    font-display: swap;\n}\n@font-face {\n    font-family: \'Jameel Noori Nastaleeq Kasheeda\';\n    src: url(\'/whitevillas/fonts/JameelNooriNastaleeqKasheeda.ttf\') format(\'truetype\'),\n         url(\'/fonts/JameelNooriNastaleeqKasheeda.ttf\') format(\'truetype\'),\n         url(\'../fonts/JameelNooriNastaleeqKasheeda.ttf\') format(\'truetype\');\n    font-weight: normal;\n    font-style: normal;\n    font-display: swap;\n}\n*, *:before, *:after {\n    -webkit-print-color-adjust: exact !important;\n    print-color-adjust: exact !important;\n    color-adjust: exact !important;\n}\n[lang=\"ur\"], [dir=\"rtl\"], .urdu-text, .ashtam-page, .letter-ur, .urdu-body, .urdu-legal {\n    font-family: \'Jameel Noori Nastaleeq\', \'Noto Nastaliq Urdu\', \'Nafees Nastaleeq\', serif !important;\n    line-height: 1.85 !important;\n    letter-spacing: 0 !important;\n    word-spacing: 0 !important;\n}\n[lang=\"ur\"] h1, [lang=\"ur\"] h2, [lang=\"ur\"] h3, [lang=\"ur\"] h4, [lang=\"ur\"] h5, [lang=\"ur\"] h6,\n[dir=\"rtl\"] h1, [dir=\"rtl\"] h2, [dir=\"rtl\"] h3, [dir=\"rtl\"] h4, [dir=\"rtl\"] h5, [dir=\"rtl\"] h6,\n.ashtam-page h1, .ashtam-page h2, .ashtam-page h3, .ashtam-page h4,\n.urdu-heading, .ashtam-heading, .document-title, .document-subtitle, .section-title, .sign-title, .bismillah {\n    font-family: \'Jameel Noori Nastaleeq Kasheeda\', \'Jameel Noori Nastaleeq\', \'Noto Nastaliq Urdu\', serif !important;\n    font-weight: normal !important;\n    line-height: 1.5 !important;\n}\n[lang=\"ur\"] p, [lang=\"ur\"] li, [lang=\"ur\"] td, [lang=\"ur\"] th, [lang=\"ur\"] span,\n[dir=\"rtl\"] p, [dir=\"rtl\"] li, [dir=\"rtl\"] td, [dir=\"rtl\"] th, [dir=\"rtl\"] span,\n.ashtam-page p, .ashtam-page li, .ashtam-page td, .ashtam-page th,\n.urdu-body p, .clause, .note-box, .amount-box {\n    font-family: \'Jameel Noori Nastaleeq\', \'Noto Nastaliq Urdu\', \'Nafees Nastaleeq\', serif !important;\n    line-height: 1.85 !important;\n}\n@media print {\n    @page { size: auto; margin: 0; }\n    html, body {\n        background: #ffffff !important;\n        color: #000000 !important;\n        margin: 0 !important;\n        padding: 0 !important;\n    }\n    .ashtam-page, .page, .form-container, .container, .letter-preview-print {\n        margin: 0 auto !important;\n        box-shadow: none !important;\n        -webkit-print-color-adjust: exact !important;\n        print-color-adjust: exact !important;\n        color-adjust: exact !important;\n    }\n}\n</style></head>\r\n\r\n<body class=\"bg-gray-50 p-4\">\r\n\r\n    <div class=\"form-container\">\r\n        \r\n        <!-- AGENCY HEADER DESIGN -->\r\n        <header class=\"mb-6 flex justify-between items-start border-b-2 border-red-600 pb-4\">\r\n            <div class=\"flex items-start space-x-6\">\r\n                <!-- Agency Logo Left Side -->\r\n                <div class=\"w-24 h-24 flex-shrink-0 flex items-center justify-center bg-gray-50 border rounded p-1 overflow-hidden\">\r\n                    {{agency_logo}}\r\n                </div>\r\n\r\n                <!-- Agency Letterhead Text -->\r\n                <div class=\"flex-grow\">\r\n                    <h1 class=\"text-3xl font-black text-gray-900 uppercase leading-none\">{{agency_name}}</h1>\r\n                    <div class=\"mt-3 text-[11px] text-gray-600 leading-tight space-y-1\">\r\n                        <p class=\"flex items-center\"><span class=\"font-bold w-12\">Address:</span> {{agency_address}}</p>\r\n                        <!-- Combined Phone and Email in one row -->\r\n                        <div class=\"flex items-center space-x-6\">\r\n                            <p class=\"flex items-center\"><span class=\"font-bold w-12\">Phone:</span> {{agency_phone}}</p>\r\n                            <p class=\"flex items-center\"><span class=\"font-bold w-12 text-right pr-1\">Email:</span> {{agency_email}}</p>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n            \r\n            <!-- Letter Meta and Applicant Photo -->\r\n            <div class=\"flex flex-col items-end space-y-4\">\r\n                <div class=\"text-right text-xs font-bold text-gray-700\">\r\n                    <p>Ref: <span class=\"font-normal text-gray-900\">REF-2026-0045</span></p>\r\n                    <p>Date: <span class=\"font-normal text-gray-900\">April 10, 2026</span></p>\r\n                </div>\r\n                <div class=\"w-28 h-32 border-2 border-gray-300 overflow-hidden bg-gray-50 shadow-sm\">\r\n                    <img src=\"https://placehold.co/112x128/fef2f2/DC2626?text=CLIENT%0D%0APHOTO\" alt=\"Client Photo\" class=\"w-full h-full object-cover\">\r\n                </div>\r\n            </div>\r\n        </header>\r\n\r\n        <!-- TITLE & TYPE -->\r\n        <div class=\"flex flex-col items-center mb-6\">\r\n            <h2 class=\"text-2xl font-black uppercase text-gray-900 border-b-4 border-red-600 px-8 pb-1 mb-1\">REFUND REQUEST APPLICATION</h2>\r\n            <p class=\"text-xs font-bold text-gray-500 tracking-tighter uppercase\">CANCELLATION & REFUND FORM</p>\r\n        </div>\r\n\r\n        <!-- PROPERTY IDENTIFIER BLOCK -->\r\n        <div class=\"flex justify-between items-center text-sm font-extrabold mb-6 pb-2 border-b border-gray-200\">\r\n            <div class=\"ml-1\">\r\n                <span class=\"text-gray-500 font-extrabold\">Project / Property:</span> \r\n                <span class=\"text-red-600 ml-1 font-semibold\">{{property_name}}</span>\r\n            </div>\r\n            \r\n            <div>\r\n                <span class=\"text-gray-500 font-extrabold\">Deal Invoice:</span> \r\n                <span class=\"text-gray-800 ml-1 font-semibold\">{{deal_invoice_no}}</span>\r\n            </div>\r\n        </div>\r\n\r\n        <!-- PERSONAL INFORMATION -->\r\n        <div class=\"section-box mt-0\">\r\n            <div class=\"form-section-title\">Personal Information</div>\r\n            <div class=\"space-y-3 p-2\">\r\n                <div class=\"input-group\">\r\n                    <label class=\"w-44 flex-shrink-0 font-bold\">Applicant Name:</label>\r\n                    <div class=\"input-line text-sm font-medium uppercase\">MOHAMMAD ALI</div>\r\n                    <label class=\"ml-4 flex-shrink-0 font-bold\">{{client_relation_type_label}}:</label>\r\n                    <div class=\"input-line text-sm\">ABDUL REHMAN</div>\r\n                </div>\r\n                \r\n                <div class=\"input-group\">\r\n                    <label class=\"w-44 flex-shrink-0 font-bold\">CNIC / NICOP:</label>\r\n                    <div class=\"input-line text-sm\">35202-1234567-1</div>\r\n                    <label class=\"ml-4 flex-shrink-0 font-bold\">Passport No:</label>\r\n                    <div class=\"input-line text-sm\">AB123456</div>\r\n                </div>\r\n\r\n                <div class=\"input-group items-start\"> \r\n                    <label class=\"w-44 flex-shrink-0 font-bold pt-1\">Permanent Address:</label>\r\n                    <div class=\"input-line text-sm min-h-[2.5rem] leading-relaxed\">House #123, Street 5, Cavalry Ground, Lahore Cantt, Pakistan.</div>\r\n                </div>\r\n\r\n                <div class=\"grid grid-cols-2 gap-x-4\">\r\n                    <div class=\"input-group\">\r\n                        <label class=\"w-20 flex-shrink-0 font-bold\">Mobile:</label>\r\n                        <div class=\"input-line text-sm font-semibold\">0321-7654321</div>\r\n                    </div>\r\n                    <div class=\"input-group\">\r\n                        <label class=\"w-20 flex-shrink-0 font-bold\">E-mail:</label>\r\n                        <div class=\"input-line text-sm\">ali.mohammad@email.com</div>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n\r\n        <!-- ORIGINAL PROPERTY DETAILS & REFUND CALCULATION -->\r\n        <div class=\"section-box\">\r\n            <div class=\"form-section-title\">Deal & Financial Statement</div>\r\n            <div class=\"grid grid-cols-10 gap-4 p-2\">\r\n                <div class=\"col-span-4 space-y-4\"> \r\n                    <div class=\"font-bold text-xs mb-1 text-gray-500 uppercase tracking-widest\">Inventory Details</div>\r\n                    <div class=\"input-group\">\r\n                        <label class=\"w-28 flex-shrink-0 font-extrabold\">Property:</label>\r\n                        <div class=\"input-line text-sm font-medium\">{{property_name}}</div>\r\n                    </div>\r\n                    <div class=\"input-group\">\r\n                        <label class=\"w-28 flex-shrink-0 font-extrabold\">Type:</label>\r\n                        <div class=\"input-line text-sm font-medium\">{{property_type}}</div>\r\n                    </div>\r\n                    <div class=\"input-group\">\r\n                        <label class=\"w-28 flex-shrink-0 font-extrabold\">Block:</label>\r\n                        <div class=\"input-line text-sm font-medium\">{{ballot_block_name}}</div>\r\n                    </div>\r\n                </div>\r\n\r\n                <div class=\"col-span-6\"> \r\n                    <div class=\"w-full border-2 border-red-100 p-4 text-xs text-gray-800 bg-gray-50 rounded-lg\">\r\n                        <p class=\"refund-calc-header mb-3 uppercase tracking-tighter\">Refund Assessment</p>\r\n                        <div class=\"space-y-2\">\r\n                            <div class=\"flex justify-between border-b border-gray-200 pb-1\">\r\n                                <span class=\"font-bold\">Total Paid Amount:</span>\r\n                                <span class=\"font-black text-gray-900\">PKR 1,250,000/-</span>\r\n                            </div>\r\n                            <div class=\"flex justify-between border-b border-gray-200 pb-1\">\r\n                                <span class=\"font-bold\">Deduction (10%):</span>\r\n                                <span class=\"font-bold text-red-600\">(-) 125,000</span>\r\n                            </div>\r\n                            <div class=\"flex justify-between pt-1\">\r\n                                <span class=\"text-sm font-black text-gray-900\">Net Refundable Amount:</span>\r\n                                <span class=\"text-sm font-black text-red-700\">PKR 1,125,000/-</span>\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n\r\n        <!-- REASON FOR CANCELLATION -->\r\n        <div class=\"section-box page-break-after-print\">\r\n            <div class=\"form-section-title\">Reason for Cancellation</div>\r\n            <div class=\"p-2\">\r\n                <div class=\"min-h-[80px] border-b border-dashed border-gray-400 text-base font-medium leading-relaxed\">\r\n                    Personal financial circumstances requiring immediate liquidation of asset.\r\n                </div>\r\n                <p class=\"text-[10px] text-gray-400 mt-2 uppercase font-bold\">\r\n                    *Management approval required for processing based on the statement above.\r\n                </p>\r\n            </div>\r\n        </div>\r\n\r\n        <!-- REFUND DISBURSEMENT SCHEDULE -->\r\n        <div class=\"section-box\">\r\n            <div class=\"form-section-title\">Disbursement Schedule</div>\r\n            <div class=\"p-2\">\r\n                <div class=\"flex justify-between items-center mb-4 bg-gray-50 p-2 border border-gray-200 rounded\">\r\n                    <div class=\"text-center px-4 flex-1\">\r\n                        <p class=\"text-[10px] uppercase font-bold text-gray-500\">Total Cycles</p>\r\n                        <p class=\"text-lg font-black text-gray-900\">12</p>\r\n                    </div>\r\n                    <!-- Frequency column widened with increased padding and flex-grow -->\r\n                    <div class=\"text-center px-12 border-l border-r border-gray-300 flex-[2]\">\r\n                        <p class=\"text-[10px] uppercase font-bold text-gray-500\">Frequency</p>\r\n                        <p class=\"text-lg font-black text-red-600 uppercase\">Monthly</p>\r\n                    </div>\r\n                    <div class=\"text-center px-4 flex-1\">\r\n                        <p class=\"text-[10px] uppercase font-bold text-gray-500\">Cycle Amount</p>\r\n                        <p class=\"text-lg font-black text-red-700\">93,750/-</p>\r\n                    </div>\r\n                </div>\r\n\r\n                <div class=\"schedule-table-container\">\r\n                    <table>\r\n                        <thead>\r\n                            <tr>\r\n                                <th>Cycle</th>\r\n                                <th>Tentative Date</th>\r\n                                <th>Amount (PKR)</th>\r\n                                <th>Status</th>\r\n                            </tr>\r\n                        </thead>\r\n                        <tbody>\r\n                            <tr><td>Cycle 1</td><td>May 10, 2026</td><td>93,750</td><td>Pending</td></tr>\r\n                            <tr><td>Cycle 2</td><td>Jun 10, 2026</td><td>93,750</td><td>Pending</td></tr>\r\n                            <tr><td colspan=\"4\" class=\"text-center font-bold\">... Schedule continues ...</td></tr>\r\n                        </tbody>\r\n                    </table>\r\n                </div>\r\n            </div>\r\n        </div>\r\n\r\n        <!-- BANKING DETAILS -->\r\n        <div class=\"section-box\">\r\n            <div class=\"form-section-title\">Bank Account Details</div>\r\n            <div class=\"space-y-3 p-2\">\r\n                <div class=\"input-group\">\r\n                    <label class=\"w-40 flex-shrink-0 font-bold\">Account Title:</label>\r\n                    <div class=\"input-line text-sm font-medium uppercase\">MOHAMMAD ALI</div>\r\n                </div>\r\n                <div class=\"input-group items-start\"> \r\n                    <label class=\"w-40 flex-shrink-0 font-bold pt-1\">Account No / IBAN:</label>\r\n                    <div class=\"input-line text-lg font-black text-gray-900 min-h-[2.5rem] tracking-wider\">PK78 HABB 0012 3456 7890 1234</div>\r\n                </div>\r\n                <div class=\"grid grid-cols-2 gap-x-4\">\r\n                    <div class=\"input-group\">\r\n                        <label class=\"w-32 flex-shrink-0 font-bold\">Bank Name:</label>\r\n                        <div class=\"input-line text-sm uppercase\">HABIB BANK LIMITED</div>\r\n                    </div>\r\n                    <div class=\"input-group\">\r\n                        <label class=\"w-32 flex-shrink-0 font-bold\">Branch:</label>\r\n                        <div class=\"input-line text-sm\">Main Branch</div>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n\r\n        <!-- TERMS & CONDITIONS -->\r\n        <div class=\"section-box p-4 border-red-600 border-2 bg-red-50\">\r\n            <h4 class=\"font-black text-red-800 uppercase mb-2 text-sm\">Declaration & Terms</h4>\r\n            <div class=\"terms-text space-y-2\">\r\n                <ol class=\"list-decimal list-inside pl-4 font-medium\">\r\n                    <li>The deduction of 10% is final and non-reversible.</li>\r\n                    <li>Refund cycle will commence as per management approval and schedule.</li>\r\n                    <li>No claims will be entertained against the property unit once the first cycle is disbursed.</li>\r\n                </ol>\r\n            </div>\r\n        </div>\r\n        \r\n        <!-- FOOTER / SIGNATURES -->\r\n        <footer class=\"mt-12 text-xs\">\r\n            <div class=\"grid grid-cols-4 gap-4 text-center border-t border-gray-400 pt-1\">\r\n                <div class=\"font-bold pt-2 flex flex-col items-center\">\r\n                    <div class=\"h-10 w-full\"></div> \r\n                    <span class=\"mt-1 uppercase\">Officer Signature</span>\r\n                </div>\r\n                <div class=\"font-bold pt-2 flex flex-col items-center\">\r\n                    <div class=\"h-10 w-full\"></div> \r\n                    <span class=\"mt-1 uppercase\">Management Sign</span>\r\n                </div>\r\n                <div class=\"font-bold pt-2 flex flex-col items-center\">\r\n                    <div class=\"h-10 w-full\"></div> \r\n                    <span class=\"mt-1 uppercase\">Applicant Sign</span>\r\n                </div>\r\n                <div class=\"font-bold pt-2 flex flex-col items-center\">\r\n                    <div class=\"h-10 w-full\"></div> \r\n                    <span class=\"mt-1 uppercase\">Thumb Impression</span>\r\n                </div>\r\n            </div>\r\n            <p class=\"text-center text-red-600 font-black mt-8 uppercase tracking-widest text-[11px]\">\r\n                Official {{agency_name}} Refund Authorization Document\r\n            </p>\r\n        </footer>\r\n\r\n    </div>\r\n</body>\r\n</html>', 'RLT_REFUND', 'Unpublished', 'Yes', '', 'letter_signatures', '', 'letter_signatures'),
(21, 'Allotment wv', '<!DOCTYPE html>\r\n<html lang=\"en\">\r\n<head>\r\n    <meta charset=\"UTF-8\">\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n    <title>Provisional Allotment Letter - White Villas</title>\r\n    <!-- Importing premium Google Fonts for a highly professional corporate look -->\r\n    <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\r\n    <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\r\n    <link href=\"https://fonts.googleapis.com/css2?family=Playfair+Display:ital,wght@0,400;0,600;0,700;1,400&family=Roboto:wght@400;500;700&display=swap\" rel=\"stylesheet\">\r\n    \r\n    <style>\r\n        /* -------------------------------------------------------------\r\n           RESET & PAGE SETUP\r\n           ------------------------------------------------------------- */\r\n        * {\r\n            box-sizing: border-box;\r\n            -webkit-print-color-adjust: exact !important;\r\n            print-color-adjust: exact !important;\r\n        }\r\n\r\n        body {\r\n            margin: 0;\r\n            padding: 20px;\r\n            background-color: #e2e8f0;\r\n            display: flex;\r\n            justify-content: center;\r\n        }\r\n\r\n        /* -------------------------------------------------------------\r\n           A4 DOCUMENT CONTAINER\r\n           ------------------------------------------------------------- */\r\n        .a4-document {\r\n            width: 210mm;\r\n            min-height: 297mm;\r\n            background-color: #ffffff;\r\n            position: relative;\r\n            box-shadow: 0 15px 35px rgba(0,0,0,0.15);\r\n            padding: 12mm;\r\n        }\r\n\r\n        /* -------------------------------------------------------------\r\n           PREMIUM BORDERS (Navy & Gold)\r\n           ------------------------------------------------------------- */\r\n        .border-navy {\r\n            border: 8px solid #0A192F; /* Deep Corporate Navy */\r\n            height: 100%;\r\n            padding: 4px;\r\n            position: relative;\r\n        }\r\n\r\n        .border-gold {\r\n            border: 2px solid #C5A059; /* Elegant Gold */\r\n            height: 100%;\r\n            padding: 40px 45px;\r\n            position: relative;\r\n            overflow: hidden;\r\n        }\r\n\r\n        /* -------------------------------------------------------------\r\n           WATERMARK\r\n           ------------------------------------------------------------- */\r\n        .watermark {\r\n            position: absolute;\r\n            top: 50%;\r\n            left: 50%;\r\n            transform: translate(-50%, -50%) rotate(-35deg);\r\n            font-family: \'Playfair Display\', serif;\r\n            font-size: 85px;\r\n            font-weight: 700;\r\n            color: rgba(10, 25, 47, 0.04);\r\n            white-space: nowrap;\r\n            z-index: 1;\r\n            pointer-events: none;\r\n            letter-spacing: 5px;\r\n            text-transform: uppercase;\r\n        }\r\n\r\n        /* Document content sits above the watermark */\r\n        .content-layer {\r\n            position: relative;\r\n            z-index: 2;\r\n        }\r\n\r\n        /* -------------------------------------------------------------\r\n           HEADER SECTION\r\n           ------------------------------------------------------------- */\r\n        .header-section {\r\n            display: flex;\r\n            justify-content: space-between;\r\n            align-items: flex-start;\r\n            border-bottom: 2px solid #C5A059;\r\n            padding-bottom: 20px;\r\n            margin-bottom: 25px;\r\n        }\r\n\r\n        .logo-area {\r\n            width: 100px;\r\n            height: 100px;\r\n            background: #f8fafc;\r\n            border: 1px dashed #cbd5e1;\r\n            display: flex;\r\n            align-items: center;\r\n            justify-content: center;\r\n            color: #64748b;\r\n            font-family: \'Roboto\', sans-serif;\r\n            font-size: 12px;\r\n            font-weight: 500;\r\n            text-align: center;\r\n        }\r\n\r\n        .company-info {\r\n            text-align: right;\r\n        }\r\n\r\n        .company-info h1 {\r\n            font-family: \'Playfair Display\', serif;\r\n            font-size: 34px;\r\n            color: #0A192F;\r\n            margin: 0 0 5px 0;\r\n            text-transform: uppercase;\r\n            letter-spacing: 1.5px;\r\n            font-weight: 700;\r\n        }\r\n\r\n        .company-info p {\r\n            font-family: \'Roboto\', sans-serif;\r\n            font-size: 13px;\r\n            color: #475569;\r\n            margin: 3px 0;\r\n            letter-spacing: 0.5px;\r\n        }\r\n\r\n        /* -------------------------------------------------------------\r\n           REF NO & DATE\r\n           ------------------------------------------------------------- */\r\n        .meta-row {\r\n            display: flex;\r\n            justify-content: space-between;\r\n            font-family: \'Roboto\', sans-serif;\r\n            font-size: 14px;\r\n            margin-bottom: 30px;\r\n            font-weight: 500;\r\n            color: #334155;\r\n        }\r\n\r\n        .meta-value {\r\n            font-family: \'Courier New\', Courier, monospace;\r\n            font-size: 15px;\r\n            font-weight: 700;\r\n            color: #000;\r\n            border-bottom: 1px dotted #94a3b8;\r\n            padding: 0 5px;\r\n        }\r\n\r\n        /* -------------------------------------------------------------\r\n           DOCUMENT TITLE\r\n           ------------------------------------------------------------- */\r\n        .doc-title {\r\n            text-align: center;\r\n            font-family: \'Playfair Display\', serif;\r\n            font-size: 26px;\r\n            font-weight: 700;\r\n            color: #0A192F;\r\n            text-transform: uppercase;\r\n            letter-spacing: 2px;\r\n            margin: 0 0 35px 0;\r\n            padding: 10px;\r\n            background-color: #f8fafc;\r\n            border-top: 1px solid #cbd5e1;\r\n            border-bottom: 1px solid #cbd5e1;\r\n        }\r\n\r\n        /* -------------------------------------------------------------\r\n           TOP DETAILS GRID (Client Details)\r\n           ------------------------------------------------------------- */\r\n        .client-details-container {\r\n            display: flex;\r\n            gap: 30px;\r\n            margin-bottom: 35px;\r\n        }\r\n\r\n        .details-grid {\r\n            flex-grow: 1;\r\n            display: grid;\r\n            grid-template-columns: 1fr;\r\n            gap: 15px;\r\n        }\r\n\r\n        .input-row {\r\n            display: flex;\r\n            align-items: flex-end;\r\n            font-family: \'Roboto\', sans-serif;\r\n        }\r\n\r\n        .input-label {\r\n            font-size: 14px;\r\n            color: #475569;\r\n            font-weight: 500;\r\n            margin-right: 15px;\r\n            white-space: nowrap;\r\n        }\r\n\r\n        .input-value {\r\n            flex-grow: 1;\r\n            border-bottom: 1px solid #000;\r\n            font-family: \'Courier New\', Courier, monospace;\r\n            font-size: 16px;\r\n            font-weight: 700;\r\n            color: #000;\r\n            padding-bottom: 2px;\r\n        }\r\n\r\n        .passport-photo {\r\n            width: 120px;\r\n            height: 150px;\r\n            border: 2px solid #0A192F;\r\n            background-color: #f1f5f9;\r\n            display: flex;\r\n            align-items: center;\r\n            justify-content: center;\r\n            text-align: center;\r\n            font-family: \'Roboto\', sans-serif;\r\n            font-size: 12px;\r\n            color: #94a3b8;\r\n            flex-shrink: 0;\r\n        }\r\n\r\n        /* -------------------------------------------------------------\r\n           BODY TEXT\r\n           ------------------------------------------------------------- */\r\n        .body-text {\r\n            font-family: \'Playfair Display\', serif;\r\n            font-size: 16px;\r\n            line-height: 1.8;\r\n            color: #1e293b;\r\n            text-align: justify;\r\n            margin-bottom: 35px;\r\n        }\r\n\r\n        .body-text strong {\r\n            font-family: \'Roboto\', sans-serif;\r\n            font-size: 16px;\r\n            font-weight: 700;\r\n            color: #0A192F;\r\n            background-color: #f8fafc;\r\n            padding: 0 4px;\r\n            border-bottom: 1px solid #cbd5e1;\r\n        }\r\n\r\n        /* -------------------------------------------------------------\r\n           PROFESSIONAL TABLE\r\n           ------------------------------------------------------------- */\r\n        .professional-table-wrapper {\r\n            margin-bottom: 40px;\r\n            border-radius: 4px;\r\n            overflow: hidden;\r\n            box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);\r\n            border: 1px solid #0f172a;\r\n        }\r\n\r\n        .professional-table {\r\n            width: 100%;\r\n            border-collapse: collapse;\r\n            font-family: \'Roboto\', sans-serif;\r\n            background-color: #fff;\r\n        }\r\n\r\n        .professional-table th, \r\n        .professional-table td {\r\n            padding: 16px 20px;\r\n            border-bottom: 1px solid #e2e8f0;\r\n            vertical-align: middle;\r\n        }\r\n\r\n        .professional-table th {\r\n            background-color: #0f172a; /* Deep Navy Header matched to image */\r\n            color: #ffffff;\r\n            font-size: 13px;\r\n            font-weight: 700;\r\n            text-transform: uppercase;\r\n            letter-spacing: 0.5px;\r\n            text-align: left;\r\n            width: 18%;\r\n            line-height: 1.85;\r\n        }\r\n\r\n        .professional-table td {\r\n            font-family: \'Courier New\', Courier, monospace;\r\n            font-size: 16px;\r\n            font-weight: 700;\r\n            color: #1e293b;\r\n            width: 32%;\r\n            border-right: 1px solid #e2e8f0;\r\n        }\r\n\r\n        /* Remove right border on last columns */\r\n        .professional-table th:last-child,\r\n        .professional-table td:last-child {\r\n            border-right: none;\r\n        }\r\n\r\n        /* Remove bottom border on last row */\r\n        .professional-table tr:last-child th,\r\n        .professional-table tr:last-child td {\r\n            border-bottom: none;\r\n        }\r\n\r\n        /* -------------------------------------------------------------\r\n           FOOTER & REALISTIC STAMP\r\n           ------------------------------------------------------------- */\r\n        .footer-section {\r\n            display: flex;\r\n            justify-content: space-between;\r\n            align-items: flex-end;\r\n            margin-top: 60px;\r\n            position: relative;\r\n        }\r\n\r\n        /* Realistic Wet Ink Stamp (Pani Print) */\r\n        .ink-stamp {\r\n            width: 140px;\r\n            height: 140px;\r\n            border: 3px solid rgba(30, 64, 175, 0.85); /* Wet ink blue */\r\n            border-radius: 50%;\r\n            display: flex;\r\n            flex-direction: column;\r\n            align-items: center;\r\n            justify-content: center;\r\n            color: rgba(30, 64, 175, 0.9);\r\n            text-align: center;\r\n            position: absolute;\r\n            left: 30px;\r\n            bottom: -15px;\r\n            transform: rotate(-12deg);\r\n            mix-blend-mode: multiply; /* Crucial for realistic paper ink effect */\r\n            background-color: transparent;\r\n            font-family: \'Roboto\', sans-serif;\r\n            box-shadow: inset 0 0 10px rgba(30, 64, 175, 0.1);\r\n        }\r\n\r\n        .ink-stamp::before {\r\n            content: \'\';\r\n            position: absolute;\r\n            width: 126px;\r\n            height: 126px;\r\n            border: 2px dashed rgba(30, 64, 175, 0.7);\r\n            border-radius: 50%;\r\n            pointer-events: none;\r\n        }\r\n\r\n        .ink-stamp::after {\r\n            content: \'\';\r\n            position: absolute;\r\n            width: 100%;\r\n            height: 100%;\r\n            border-radius: 50%;\r\n            /* Simulates uneven ink pressure */\r\n            box-shadow: inset 0 3px 5px rgba(30, 64, 175, 0.2), inset 0 -2px 3px rgba(30, 64, 175, 0.1);\r\n        }\r\n\r\n        .ink-stamp span {\r\n            font-size: 11px;\r\n            text-transform: uppercase;\r\n            letter-spacing: 1.5px;\r\n            font-weight: 500;\r\n            z-index: 2;\r\n        }\r\n\r\n        .ink-stamp .seal-bold {\r\n            font-family: \'Playfair Display\', serif;\r\n            font-weight: 700;\r\n            font-size: 20px;\r\n            margin: 6px 0;\r\n            padding: 4px 0;\r\n            border-top: 1px solid rgba(30, 64, 175, 0.6);\r\n            border-bottom: 1px solid rgba(30, 64, 175, 0.6);\r\n            width: 85%;\r\n            z-index: 2;\r\n        }\r\n\r\n        /* Signatory Line */\r\n        .signatory-box {\r\n            text-align: center;\r\n            width: 260px;\r\n        }\r\n\r\n        .signature-line {\r\n            border-bottom: 1px solid #0A192F;\r\n            height: 40px;\r\n            margin-bottom: 8px;\r\n        }\r\n\r\n        .signatory-name {\r\n            font-family: \'Roboto\', sans-serif;\r\n            font-size: 14px;\r\n            font-weight: 700;\r\n            color: #0A192F;\r\n            text-transform: uppercase;\r\n        }\r\n\r\n        .signatory-title {\r\n            font-family: \'Roboto\', sans-serif;\r\n            font-size: 12px;\r\n            color: #64748b;\r\n            margin-top: 2px;\r\n        }\r\n\r\n        /* -------------------------------------------------------------\r\n           PRINT SPECIFIC STYLES\r\n           ------------------------------------------------------------- */\r\n        @media print {\r\n            body { \r\n                background: #fff; \r\n                padding: 0;\r\n                margin: 0;\r\n            }\r\n            .a4-document { \r\n                box-shadow: none; \r\n                margin: 0; \r\n                width: 100%;\r\n            }\r\n        }\r\n    </style>\r\n<style type=\"text/css\" id=\"wv-urdu-font-definitions\">\n@font-face {\n    font-family: \'Jameel Noori Nastaleeq\';\n    src: url(\'/whitevillas/fonts/JameelNooriNastaleeq.ttf\') format(\'truetype\'),\n         url(\'/fonts/JameelNooriNastaleeq.ttf\') format(\'truetype\'),\n         url(\'../fonts/JameelNooriNastaleeq.ttf\') format(\'truetype\');\n    font-weight: normal;\n    font-style: normal;\n    font-display: swap;\n}\n@font-face {\n    font-family: \'Jameel Noori Nastaleeq Kasheeda\';\n    src: url(\'/whitevillas/fonts/JameelNooriNastaleeqKasheeda.ttf\') format(\'truetype\'),\n         url(\'/fonts/JameelNooriNastaleeqKasheeda.ttf\') format(\'truetype\'),\n         url(\'../fonts/JameelNooriNastaleeqKasheeda.ttf\') format(\'truetype\');\n    font-weight: normal;\n    font-style: normal;\n    font-display: swap;\n}\n*, *:before, *:after {\n    -webkit-print-color-adjust: exact !important;\n    print-color-adjust: exact !important;\n    color-adjust: exact !important;\n}\n[lang=\"ur\"], [dir=\"rtl\"], .urdu-text, .ashtam-page, .letter-ur, .urdu-body, .urdu-legal {\n    font-family: \'Jameel Noori Nastaleeq\', \'Noto Nastaliq Urdu\', \'Nafees Nastaleeq\', serif !important;\n    line-height: 1.85 !important;\n    letter-spacing: 0 !important;\n    word-spacing: 0 !important;\n}\n[lang=\"ur\"] h1, [lang=\"ur\"] h2, [lang=\"ur\"] h3, [lang=\"ur\"] h4, [lang=\"ur\"] h5, [lang=\"ur\"] h6,\n[dir=\"rtl\"] h1, [dir=\"rtl\"] h2, [dir=\"rtl\"] h3, [dir=\"rtl\"] h4, [dir=\"rtl\"] h5, [dir=\"rtl\"] h6,\n.ashtam-page h1, .ashtam-page h2, .ashtam-page h3, .ashtam-page h4,\n.urdu-heading, .ashtam-heading, .document-title, .document-subtitle, .section-title, .sign-title, .bismillah {\n    font-family: \'Jameel Noori Nastaleeq Kasheeda\', \'Jameel Noori Nastaleeq\', \'Noto Nastaliq Urdu\', serif !important;\n    font-weight: normal !important;\n    line-height: 1.5 !important;\n}\n[lang=\"ur\"] p, [lang=\"ur\"] li, [lang=\"ur\"] td, [lang=\"ur\"] th, [lang=\"ur\"] span,\n[dir=\"rtl\"] p, [dir=\"rtl\"] li, [dir=\"rtl\"] td, [dir=\"rtl\"] th, [dir=\"rtl\"] span,\n.ashtam-page p, .ashtam-page li, .ashtam-page td, .ashtam-page th,\n.urdu-body p, .clause, .note-box, .amount-box {\n    font-family: \'Jameel Noori Nastaleeq\', \'Noto Nastaliq Urdu\', \'Nafees Nastaleeq\', serif !important;\n    line-height: 1.85 !important;\n}\n@media print {\n    @page { size: auto; margin: 0; }\n    html, body {\n        background: #ffffff !important;\n        color: #000000 !important;\n        margin: 0 !important;\n        padding: 0 !important;\n    }\n    .ashtam-page, .page, .form-container, .container, .letter-preview-print {\n        margin: 0 auto !important;\n        box-shadow: none !important;\n        -webkit-print-color-adjust: exact !important;\n        print-color-adjust: exact !important;\n        color-adjust: exact !important;\n    }\n}\n</style></head>\r\n<body>\r\n\r\n<div class=\"a4-document\">\r\n    <div class=\"border-navy\">\r\n        <div class=\"border-gold\">\r\n            \r\n            <!-- Faint Corporate Watermark -->\r\n            <div class=\"watermark\">WHITE VILLAS</div>\r\n\r\n            <div class=\"content-layer\">\r\n                \r\n                <!-- HEADER AREA -->\r\n                <div class=\"header-section\">\r\n                    <div class=\"logo-area\">\r\n                        [ Company<br>Logo ]\r\n                    </div>\r\n                    <div class=\"company-info\">\r\n                        <h1>White Villas Lahore</h1>\r\n                        <p>123 Premium Avenue, Main Boulevard, Lahore, Pakistan</p>\r\n                        <p>UAN: +92 42 111 222 333 | info@whitevillas.com.pk</p>\r\n                        <p><strong>www.whitevillas.com.pk</strong></p>\r\n                    </div>\r\n                </div>\r\n\r\n                <!-- REFERENCE & DATE -->\r\n                <div class=\"meta-row\">\r\n                    <div>Ref No: <span class=\"meta-value\">{{letter_ref_no}}</span></div>\r\n                    <div>Date: <span class=\"meta-value\">{{letter_date}}</span></div>\r\n                </div>\r\n\r\n                <!-- DOCUMENT TITLE -->\r\n                <h2 class=\"doc-title\">Provisional Allotment Letter (PAL)</h2>\r\n\r\n                <!-- TOP FORM DETAILS -->\r\n                <div class=\"client-details-container\">\r\n                    <div class=\"details-grid\">\r\n                        <div class=\"input-row\">\r\n                            <span class=\"input-label\">Name of Member:</span>\r\n                            <span class=\"input-value\">{{client_name}}</span>\r\n                        </div>\r\n                        <div class=\"input-row\">\r\n                            <span class=\"input-label\">Membership / Invoice No:</span>\r\n                            <span class=\"input-value\">{{deal_invoice_no}}</span>\r\n                        </div>\r\n                        <div class=\"input-row\">\r\n                            <span class=\"input-label\">Date of Booking:</span>\r\n                            <span class=\"input-value\">{{deal_date}}</span>\r\n                        </div>\r\n                        <div class=\"input-row\">\r\n                            <span class=\"input-label\">Total Deal Amount:</span>\r\n                            <span class=\"input-value\">{{deal_total_amount}}</span>\r\n                        </div>\r\n                    </div>\r\n                    \r\n                    <!-- Photograph Placeholder -->\r\n                    <div class=\"passport-photo\">\r\n                        Affix<br>Recent<br>Passport Size<br>Photograph\r\n                    </div>\r\n                </div>\r\n\r\n                <!-- FORMAL BODY TEXT -->\r\n                <div class=\"body-text\">\r\n                    <p style=\"font-family: \'Roboto\', sans-serif; font-weight: 500;\">Dear <strong>{{client_name}}</strong>,</p>\r\n                    <p>\r\n                        We are pleased to inform you that you have been provisionally allotted a <strong>{{property_area}}</strong> <strong>{{property_name}}</strong> (<strong>{{property_type}}</strong> / <strong>{{property_contract}}</strong>) at the esteemed <strong>{{project_name}}</strong>. This Provisional Allotment Letter (PAL) is officially transferrable subject to the payment of all applicable charges and the completion of standard transfer procedures at the White Villas Head Office.\r\n                    </p>\r\n                    <p>\r\n                        Please note that a formal Intimation Letter will be dispatched upon the finalization of town planning and balloting. The definitive Allotment Letter will be formally issued subsequent to the clearance of all developmental charges and outstanding dues.\r\n                    </p>\r\n                    <p style=\"font-size: 13px; font-family: \'Roboto\', sans-serif; color: #dc2626;\">\r\n                        <em>Note: Development charges and government taxes are applicable as per prevailing company policies.</em>\r\n                    </p>\r\n                </div>\r\n\r\n                <!-- PROFESSIONAL TABLE FOR BALLOT DETAILS -->\r\n                <div class=\"professional-table-wrapper\">\r\n                    <table class=\"professional-table\">\r\n                        <tr>\r\n                            <th>Allotment<br>No.</th>\r\n                            <td>{{ballot_allotment_no}}</td>\r\n                            <th>Property<br>No.</th>\r\n                            <td>{{ballot_property_no}}</td>\r\n                        </tr>\r\n                        <tr>\r\n                            <th>Block<br>Name</th>\r\n                            <td>{{ballot_block_name}}</td>\r\n                            <th>Total<br>Area</th>\r\n                            <td>{{ballot_area_full}}</td>\r\n                        </tr>\r\n                        <tr>\r\n                            <th>Street<br>Address</th>\r\n                            <td colspan=\"3\">{{ballot_street_address}}</td>\r\n                        </tr>\r\n                    </table>\r\n                </div>\r\n\r\n                <!-- FOOTER / SIGNATURES -->\r\n                <div class=\"footer-section\">\r\n                    \r\n                    <!-- Highly Realistic Wet Ink Stamp -->\r\n                    <div class=\"ink-stamp\">\r\n                        <span>White Villas</span>\r\n                        <div class=\"seal-bold\">OFFICIAL<br>SEAL</div>\r\n                        <span>Lahore</span>\r\n                    </div>\r\n\r\n                    <div class=\"signatory-box\">\r\n                        <div class=\"signature-line\"></div>\r\n                        <div class=\"signatory-name\">{{site_organization}}</div>\r\n                        <div class=\"signatory-title\">Authorized Signatory</div>\r\n                    </div>\r\n                </div>\r\n\r\n            </div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n</body>\r\n</html>\r\n```', 'RLT_ALLOT', 'Published', 'Yes', '', 'letter_signatures', '', 'letter_signatures');
INSERT INTO `templates` (`id`, `name`, `description`, `type`, `status`, `is_new`, `ceo_signature`, `ceo_signature_dir`, `chairman_signature`, `chairman_signature_dir`) VALUES
(22, 'Final Cancellation Notice', '<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>FINAL DEMAND: Deal Cancellation Warning</title>\n    <style>\n        @page{size:A4;margin:5mm;}\n        *{box-sizing:border-box;}\n        body{font-family:-apple-system,BlinkMacSystemFont,\"Segoe UI\",Roboto,Helvetica,Arial,sans-serif;color:#222;line-height:1.85;background:#f8fafc;margin:0;padding:12px 8px;-webkit-font-smoothing:antialiased;}\n        .container{width:198mm;max-width:100%;margin:0 auto;background:#fff;border:1px solid #e2e8f0;border-top:3px solid #8c1d1d;box-shadow:0 6px 14px rgba(0,0,0,.045);padding:15px 18px;box-sizing:border-box;position:relative;overflow:hidden;}\n        .container:before{content:\"FINAL NOTICE\";position:absolute;top:51%;left:50%;transform:translate(-50%,-50%) rotate(-45deg);font-size:62px;font-weight:900;color:rgba(140,29,29,.022);pointer-events:none;z-index:1;white-space:nowrap;letter-spacing:0;}\n        .container>*{position:relative;z-index:2;}\n        .header{display:table;width:100%;border-bottom:1px solid #d9e1ec;padding-bottom:7px;margin-bottom:7px;}\n        .logo-section{display:table-cell;vertical-align:middle;width:72px;}\n        .logo-placeholder{width:52px;height:auto;max-height:44px;object-fit:contain;}\n        .company-details{display:table-cell;vertical-align:middle;text-align:right;}\n        .company-name{font-size:16px;font-weight:800;text-transform:uppercase;color:#8c1d1d;margin:0 0 2px 0;letter-spacing:0;}\n        .company-info{font-size:8.8px;color:#555;margin:0;letter-spacing:0;line-height:1.85;}\n        .meta-section{display:table;width:100%;margin-bottom:7px;font-size:9.8px;border-bottom:1px dashed #e2e8f0;padding-bottom:4px;}\n        .meta-col-left{display:table-cell;text-align:left;color:#555;}\n        .meta-col-right{display:table-cell;text-align:right;color:#555;}\n        .meta-section strong{color:#222;}\n        .warning-banner{background:#fff5f5;border-left:3px solid #8c1d1d;padding:6px 8px;margin-bottom:7px;border-radius:0 2px 2px 0;}\n        .warning-title{color:#8c1d1d;font-size:14px;font-weight:800;margin:0 0 1px 0;letter-spacing:0;text-transform:uppercase;}\n        .warning-subtitle{font-size:9.2px;font-weight:bold;color:#5c1313;margin:0;letter-spacing:0;text-transform:uppercase;}\n        .client-info{background:#fbfcfd;border:1px solid #e2e8f0;border-radius:2px;padding:6px 8px;margin-bottom:7px;font-size:10.2px;}\n        .client-title{font-size:8px;text-transform:uppercase;color:#8c1d1d;margin:0 0 2px 0;letter-spacing:0;font-weight:800;}\n        .client-name{font-size:11.5px;font-weight:700;color:#000;margin:0 0 1px 0;}\n        .client-address{color:#555;line-height:1.85;}\n        .letter-body{font-family:Georgia,Cambria,\"Times New Roman\",Times,serif;font-size:10.7px;text-align:justify;color:#2c2c2c;margin-bottom:7px;}\n        .letter-body p{margin:0 0 4px 0;line-height:1.85;}\n        .highlight-text{font-family:-apple-system,BlinkMacSystemFont,\"Segoe UI\",sans-serif;font-weight:700;color:#000;padding:0 2px;text-decoration:underline;}\n        .table-container{margin:5px 0;border:1px solid #e2e8f0;border-radius:2px;overflow:hidden;}\n        .financial-summary{width:100%;border-collapse:collapse;font-family:-apple-system,BlinkMacSystemFont,\"Segoe UI\",sans-serif;font-size:9.6px;}\n        .financial-summary th{background:#f8fafc;border-bottom:1px solid #d9e1ec;color:#222;padding:4px 5px;text-align:left;font-weight:700;text-transform:uppercase;font-size:8.2px;letter-spacing:0;}\n        .financial-summary td{border-bottom:1px solid #e2e8f0;padding:4px 5px;color:#222;}\n        .financial-summary tr:last-child td{border-bottom:none;}\n        .alert-box{background:#fff5f5;border:1px solid rgba(140,29,29,.2);border-left:3px solid #8c1d1d;border-radius:2px;padding:6px 8px;margin:5px 0;}\n        .alert-box h4{color:#8c1d1d;margin:0 0 3px 0;font-size:9.8px;font-weight:800;text-transform:uppercase;letter-spacing:0;font-family:-apple-system,BlinkMacSystemFont,\"Segoe UI\",sans-serif;}\n        .alert-box p{margin:0 0 4px 0;font-size:9.8px;line-height:1.85;color:#3f3f3f;}\n        .alert-box p:last-child{margin-bottom:0;font-weight:bold;color:#5c1313;}\n        .delivery-note-box{background:#f1f5f9;border-left:2px solid #475569;padding:5px 7px;margin:5px 0;font-size:8.8px;color:#334155;line-height:1.85;border-radius:0 2px 2px 0;font-family:-apple-system,BlinkMacSystemFont,\"Segoe UI\",sans-serif;}\n        .delivery-note-box strong{color:#1e293b;display:inline;margin-right:5px;text-transform:uppercase;font-size:8.3px;letter-spacing:0;}\n        .bank-details-box{background:#fafbfd;border:1px solid #e2e8f0;border-radius:2px;padding:5px 7px;margin:5px 0;font-size:8.9px;font-family:-apple-system,BlinkMacSystemFont,\"Segoe UI\",sans-serif;line-height:1.85;}\n        .bank-title{display:inline;font-weight:800;font-size:8.7px;margin:0 7px 0 0;text-transform:uppercase;color:#222;letter-spacing:0;border:0;padding:0;}\n        .bank-line{display:inline;color:#333;white-space:nowrap;}\n        .bank-item{display:inline;margin-right:8px;white-space:nowrap;}\n        .bank-item strong{font-weight:700;color:#555;}\n        .signatures-section{display:table;width:100%;margin-top:10px;border-top:1px solid #e2e8f0;padding-top:7px;font-family:-apple-system,BlinkMacSystemFont,\"Segoe UI\",sans-serif;page-break-inside:avoid;}\n        .signature-block{display:table-cell;width:50%;text-align:center;vertical-align:bottom;}\n        .sig-image-container{height:72px;margin:0 auto 2px;text-align:center;display:flex;align-items:flex-end;justify-content:center;}\n        .sig-image{max-height:72px;max-width:270px;display:inline-block;}\n        .signature-line{width:190px;border-top:1px solid #222;margin:2px auto 3px;height:1px;}\n        .digital-stamp-mock{border:1px dashed #cbd5e1;padding:4px 8px;width:125px;margin:0 auto;color:#94a3b8;font-size:7.5px;font-style:italic;border-radius:2px;text-transform:uppercase;letter-spacing:0;line-height:1.85;}\n        .signer-title{font-weight:700;font-size:8.8px;color:#222;margin:0 0 1px 0;text-transform:uppercase;letter-spacing:0;}\n        .signer-subtitle{font-size:8px;color:#555;margin:0;letter-spacing:0;}\n        .footer{margin-top:7px;border-top:1px solid #8c1d1d;padding-top:4px;text-align:center;font-size:8px;color:#555;font-family:-apple-system,BlinkMacSystemFont,\"Segoe UI\",sans-serif;line-height:1.85;}\n        .footer strong{color:#8c1d1d;text-transform:uppercase;letter-spacing:0;}\n        @media print{\n            html,body{background:#fff;padding:0;margin:0;}\n            .container{border:none;box-shadow:none;padding:0;width:100%;max-width:100%;min-height:287mm;margin:0;display:flex;flex-direction:column;}\n            body,.container,.container *{color:#000!important;text-shadow:none!important;}\n            .container:before{color:rgba(0,0,0,.02);}\n            .warning-banner,.alert-box,.delivery-note-box,.financial-summary th{-webkit-print-color-adjust:exact;print-color-adjust:exact;}\n            .warning-banner{background:#f8fafc!important;border-left:3px solid #000!important;}\n            .alert-box{background:#f8fafc!important;border:1px solid #000!important;}\n            .delivery-note-box{background:#f8fafc!important;border-left:2px solid #000!important;}\n            .warning-title,.company-name,.signer-title{color:#000!important;}\n            .financial-summary th{background:#f1f5f9!important;border-bottom:1px solid #000!important;}\n            .letter-body{flex:1;display:flex;flex-direction:column;justify-content:space-between;font-size:11.2px;line-height:1.85;margin-bottom:6mm;}\n            .letter-body p{line-height:1.85;margin-bottom:0;}\n            .table-container,.alert-box,.bank-details-box,.delivery-note-box{margin:0;}\n            .financial-summary{font-size:10px;}\n            .financial-summary th{font-size:8.6px;padding:4px 5px;}\n            .financial-summary td{padding:4px 5px;}\n            .alert-box p{font-size:10.2px;line-height:1.85;margin-bottom:2px;}\n            .delivery-note-box{font-size:9.2px;line-height:1.85;}\n            .bank-details-box{font-size:9.2px;}\n            .signatures-section{page-break-inside:avoid;margin-top:0;}\n            .footer{page-break-inside:avoid;}\n        }\n    </style>\n<style type=\"text/css\" id=\"wv-urdu-font-definitions\">\n@font-face {\n    font-family: \'Jameel Noori Nastaleeq\';\n    src: url(\'/whitevillas/fonts/JameelNooriNastaleeq.ttf\') format(\'truetype\'),\n         url(\'/fonts/JameelNooriNastaleeq.ttf\') format(\'truetype\'),\n         url(\'../fonts/JameelNooriNastaleeq.ttf\') format(\'truetype\');\n    font-weight: normal;\n    font-style: normal;\n    font-display: swap;\n}\n@font-face {\n    font-family: \'Jameel Noori Nastaleeq Kasheeda\';\n    src: url(\'/whitevillas/fonts/JameelNooriNastaleeqKasheeda.ttf\') format(\'truetype\'),\n         url(\'/fonts/JameelNooriNastaleeqKasheeda.ttf\') format(\'truetype\'),\n         url(\'../fonts/JameelNooriNastaleeqKasheeda.ttf\') format(\'truetype\');\n    font-weight: normal;\n    font-style: normal;\n    font-display: swap;\n}\n*, *:before, *:after {\n    -webkit-print-color-adjust: exact !important;\n    print-color-adjust: exact !important;\n    color-adjust: exact !important;\n}\n[lang=\"ur\"], [dir=\"rtl\"], .urdu-text, .ashtam-page, .letter-ur, .urdu-body, .urdu-legal {\n    font-family: \'Jameel Noori Nastaleeq\', \'Noto Nastaliq Urdu\', \'Nafees Nastaleeq\', serif !important;\n    line-height: 1.85 !important;\n    letter-spacing: 0 !important;\n    word-spacing: 0 !important;\n}\n[lang=\"ur\"] h1, [lang=\"ur\"] h2, [lang=\"ur\"] h3, [lang=\"ur\"] h4, [lang=\"ur\"] h5, [lang=\"ur\"] h6,\n[dir=\"rtl\"] h1, [dir=\"rtl\"] h2, [dir=\"rtl\"] h3, [dir=\"rtl\"] h4, [dir=\"rtl\"] h5, [dir=\"rtl\"] h6,\n.ashtam-page h1, .ashtam-page h2, .ashtam-page h3, .ashtam-page h4,\n.urdu-heading, .ashtam-heading, .document-title, .document-subtitle, .section-title, .sign-title, .bismillah {\n    font-family: \'Jameel Noori Nastaleeq Kasheeda\', \'Jameel Noori Nastaleeq\', \'Noto Nastaliq Urdu\', serif !important;\n    font-weight: normal !important;\n    line-height: 1.5 !important;\n}\n[lang=\"ur\"] p, [lang=\"ur\"] li, [lang=\"ur\"] td, [lang=\"ur\"] th, [lang=\"ur\"] span,\n[dir=\"rtl\"] p, [dir=\"rtl\"] li, [dir=\"rtl\"] td, [dir=\"rtl\"] th, [dir=\"rtl\"] span,\n.ashtam-page p, .ashtam-page li, .ashtam-page td, .ashtam-page th,\n.urdu-body p, .clause, .note-box, .amount-box {\n    font-family: \'Jameel Noori Nastaleeq\', \'Noto Nastaliq Urdu\', \'Nafees Nastaleeq\', serif !important;\n    line-height: 1.85 !important;\n}\n@media print {\n    @page { size: auto; margin: 0; }\n    html, body {\n        background: #ffffff !important;\n        color: #000000 !important;\n        margin: 0 !important;\n        padding: 0 !important;\n    }\n    .ashtam-page, .page, .form-container, .container, .letter-preview-print {\n        margin: 0 auto !important;\n        box-shadow: none !important;\n        -webkit-print-color-adjust: exact !important;\n        print-color-adjust: exact !important;\n        color-adjust: exact !important;\n    }\n}\n</style></head>\n<body>\n<div class=\"container\">\n    <div class=\"header\">\n        <div class=\"logo-section\">\n            <div class=\"logo-placeholder\">{{agency_logo}}</div>\n        </div>\n        <div class=\"company-details\">\n            <h1 class=\"company-name\">{{agency_name}}</h1>\n            <p class=\"company-info\">{{agency_address}}</p>\n            <p class=\"company-info\">Phone: {{agency_phone}} | E-mail: {{agency_email}}</p>\n        </div>\n    </div>\n    <div class=\"meta-section\">\n        <div class=\"meta-col-left\">Ref. No: <strong>{{letter_ref_no}}</strong></div>\n        <div class=\"meta-col-right\">Date: <strong>{{letter_date}}</strong></div>\n    </div>\n    <div class=\"warning-banner\">\n        <h2 class=\"warning-title\">Final Deal Cancellation &amp; Revocation Warning</h2>\n        <p class=\"warning-subtitle\">Subject: Notice of Absolute Forfeiture &amp; Property Reallocation</p>\n    </div>\n    <div class=\"client-info\">\n        <div class=\"client-title\">Notice Addressee (Defaulter Client)</div>\n        <div class=\"client-name\">{{client_name}} S/O {{client_father_name}}</div>\n        <div class=\"client-address\">{{client_address}}</div>\n        <div style=\"margin-top:2px;font-size:10px;font-weight:bold;color:#222;\">Mobile Number: <span style=\"font-family:monospace;font-size:10px;\">{{client_mobile}}</span></div>\n    </div>\n    <div class=\"letter-body\">\n        <p>Dear Sir/Madam,</p>\n        <p>We refer to our previous notices and the Payment Demand Letter sent under Ref: <strong>{{letter_ref_no}}</strong>. Despite several administrative grace margins, your payments towards the purchase of your <span class=\"highlight-text\">{{property_type}}</span>, Property/File Code: <span class=\"highlight-text\">{{property_file}}</span>, situated at <span class=\"highlight-text\">{{project_name}}</span>, remain severely delinquent.</p>\n        <p>The total agreed consideration for the aforementioned property is <span class=\"highlight-text\">{{deal_total_amount}} ({{deal_total_amount_words}})</span>. You have defaulted on multiple consecutive monthly schedules, accumulating a major outstanding balance.</p>\n        <div class=\"table-container\">\n            <table class=\"financial-summary\">\n                <thead>\n                    <tr>\n                        <th>Overdue Installment Milestones</th>\n                        <th style=\"text-align:center;\">Total Default Count</th>\n                        <th style=\"text-align:right;\">Total Outstanding Overdue (PKR)</th>\n                    </tr>\n                </thead>\n                <tbody>\n                    <tr>\n                        <td style=\"font-weight:500;\">{{overdue_installments_label}}</td>\n                        <td style=\"text-align:center;color:#8c1d1d;font-weight:bold;\">{{overdue_installments_count}} Consecutive Installments</td>\n                        <td style=\"text-align:right;color:#8c1d1d;font-weight:bold;\">{{overdue_amount}}</td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"3\" style=\"font-size:11px;background:#fafbfd;border-top:1px solid #e2e8f0;color:#555;\">\n                            <strong>Amount in Words:</strong> <span style=\"color:#222;font-weight:600;text-transform:capitalize;\">{{overdue_amount_words}}</span>\n                        </td>\n                    </tr>\n                </tbody>\n            </table>\n        </div>\n        <p>Under the signed and agreed Terms &amp; Conditions of booking, failure to pay <strong>{{overdue_installments_count}}</strong> consecutive monthly installments triggers immediate revocation of allotment rights, leading directly to booking termination and the absolute forfeiture of initial deposit milestones.</p>\n        <div class=\"alert-box\">\n            <h4>&#128680; Formal Declaration of Impending Legal Action &amp; Allotment Revocation</h4>\n            <p><strong>FINAL REQUISITION:</strong> If the total outstanding overdue amount of <strong>{{overdue_amount}}</strong> is not cleared and credited in full within <strong>{{final_notice_deadline_days}} days</strong> of this notice, your booking, deal, and property allotment for <strong>{{property_file}}</strong> will stand <strong>permanently cancelled without further recourse.</strong></p>\n            <p>Following the cancellation, the company will exercise its complete legal rights to immediately revoke physical possession, purge the register records, and reallocate or sell this property to other prospective buyers on the waiting list. {{agency_name}} shall also initiate recovery litigation to claim any accrued default damages.</p>\n        </div>\n        <div class=\"bank-details-box\">\n            <div class=\"bank-title\">Authorized Bank Payment Channels</div>\n            <div class=\"bank-line\">\n                <span class=\"bank-item\"><strong>Title:</strong> {{bank_account_title}}</span>\n                <span class=\"bank-item\"><strong>Bank:</strong> {{bank_name}}</span>\n                <span class=\"bank-item\"><strong>A/C:</strong> {{bank_account_no}}</span>\n                <span class=\"bank-item\"><strong>IBAN:</strong> {{bank_iban}}</span>\n                <span class=\"bank-item\"><strong>Branch:</strong> {{bank_branch}}</span>\n            </div>\n        </div>\n        <div class=\"delivery-note-box\">\n            <strong>Proof of Delivery &amp; Legal Service Status</strong>\n            This is an officially dispatched and legally recognized <strong>FINAL NOTICE</strong>. It has been transmitted to you concurrently through multiple verified physical and electronic channels: (1) Hand-delivered/Posted physically to your registered residential home address, (2) Dispatched to your property\'s absolute physical possession address, (3) Electronically delivered to your registered email on record, and (4) Transmitted via WhatsApp messenger notification to your registered telephone line.\n            <br><span style=\"font-weight:bold;color:#8c1d1d;\">Delivery is legally deemed active and fully acknowledged upon dispatch. Counter-signature of receipt or returned postal receipt by the defaulting client is not required for this legal notice to take immediate, absolute effect.</span>\n        </div>\n        <p>We urge you to treat this notification with the highest priority to safeguard your property value and prevent immediate legal termination of your unit booking.</p>\n        <p>Yours Sincerely,</p>\n    </div>\n    <div class=\"signatures-section\">\n        <div class=\"signature-block\">\n            <div class=\"sig-image-container\">{{ceo_signature}}</div>\n            <div class=\"signature-line\"></div>\n            <p class=\"signer-title\">Chief Executive Officer</p>\n            <p class=\"signer-subtitle\">{{agency_name}}</p>\n        </div>\n        <div class=\"signature-block\">\n            <div class=\"sig-image-container\">{{chairman_signature}}</div>\n            <div class=\"signature-line\"></div>\n            <p class=\"signer-title\">Chairman of the Board</p>\n            <p class=\"signer-subtitle\">{{agency_name}}</p>\n        </div>\n    </div>\n    <div class=\"footer\">\n        <strong>{{agency_name}}</strong><br>\n        Office Address: {{agency_address}}<br>\n        Contact: {{agency_phone}} | Email: {{agency_email}}\n    </div>\n</div>\n</body>\n</html>', 'RLT_FINAL_CANCEL', 'Unpublished', 'No', 'ceo_signature_default_20260521.png', 'letter_signatures', 'chairman_signature_default_20260521.png', 'letter_signatures'),
(23, 'Final Cancellation Notice', '<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>FINAL DEMAND: Deal Cancellation Warning</title>\n    <style>\n        @page{size:A4;margin:5mm;}\n        *{box-sizing:border-box;}\n        body{font-family:-apple-system,BlinkMacSystemFont,\"Segoe UI\",Roboto,Helvetica,Arial,sans-serif;color:#222;line-height:1.85;background:#f8fafc;margin:0;padding:12px 8px;-webkit-font-smoothing:antialiased;}\n        .container{width:198mm;max-width:100%;margin:0 auto;background:#fff;border:1px solid #e2e8f0;border-top:3px solid #8c1d1d;box-shadow:0 6px 14px rgba(0,0,0,.045);padding:15px 18px;box-sizing:border-box;position:relative;overflow:hidden;}\n        .container:before{content:\"FINAL NOTICE\";position:absolute;top:51%;left:50%;transform:translate(-50%,-50%) rotate(-45deg);font-size:62px;font-weight:900;color:rgba(140,29,29,.022);pointer-events:none;z-index:1;white-space:nowrap;letter-spacing:0;}\n        .container>*{position:relative;z-index:2;}\n        .header{display:table;width:100%;border-bottom:1px solid #d9e1ec;padding-bottom:7px;margin-bottom:7px;}\n        .logo-section{display:table-cell;vertical-align:middle;width:72px;}\n        .logo-placeholder{width:52px;height:auto;max-height:44px;object-fit:contain;}\n        .company-details{display:table-cell;vertical-align:middle;text-align:right;}\n        .company-name{font-size:16px;font-weight:800;text-transform:uppercase;color:#8c1d1d;margin:0 0 2px 0;letter-spacing:0;}\n        .company-info{font-size:8.8px;color:#555;margin:0;letter-spacing:0;line-height:1.85;}\n        .meta-section{display:table;width:100%;margin-bottom:7px;font-size:9.8px;border-bottom:1px dashed #e2e8f0;padding-bottom:4px;}\n        .meta-col-left{display:table-cell;text-align:left;color:#555;}\n        .meta-col-right{display:table-cell;text-align:right;color:#555;}\n        .meta-section strong{color:#222;}\n        .warning-banner{background:#fff5f5;border-left:3px solid #8c1d1d;padding:6px 8px;margin-bottom:7px;border-radius:0 2px 2px 0;}\n        .warning-title{color:#8c1d1d;font-size:14px;font-weight:800;margin:0 0 1px 0;letter-spacing:0;text-transform:uppercase;}\n        .warning-subtitle{font-size:9.2px;font-weight:bold;color:#5c1313;margin:0;letter-spacing:0;text-transform:uppercase;}\n        .client-info{background:#fbfcfd;border:1px solid #e2e8f0;border-radius:2px;padding:6px 8px;margin-bottom:7px;font-size:10.2px;}\n        .client-title{font-size:8px;text-transform:uppercase;color:#8c1d1d;margin:0 0 2px 0;letter-spacing:0;font-weight:800;}\n        .client-name{font-size:11.5px;font-weight:700;color:#000;margin:0 0 1px 0;}\n        .client-address{color:#555;line-height:1.85;}\n        .letter-body{font-family:Georgia,Cambria,\"Times New Roman\",Times,serif;font-size:10.7px;text-align:justify;color:#2c2c2c;margin-bottom:7px;}\n        .letter-body p{margin:0 0 4px 0;line-height:1.85;}\n        .highlight-text{font-family:-apple-system,BlinkMacSystemFont,\"Segoe UI\",sans-serif;font-weight:700;color:#000;padding:0 2px;text-decoration:underline;}\n        .table-container{margin:5px 0;border:1px solid #e2e8f0;border-radius:2px;overflow:hidden;}\n        .financial-summary{width:100%;border-collapse:collapse;font-family:-apple-system,BlinkMacSystemFont,\"Segoe UI\",sans-serif;font-size:9.6px;}\n        .financial-summary th{background:#f8fafc;border-bottom:1px solid #d9e1ec;color:#222;padding:4px 5px;text-align:left;font-weight:700;text-transform:uppercase;font-size:8.2px;letter-spacing:0;}\n        .financial-summary td{border-bottom:1px solid #e2e8f0;padding:4px 5px;color:#222;}\n        .financial-summary tr:last-child td{border-bottom:none;}\n        .alert-box{background:#fff5f5;border:1px solid rgba(140,29,29,.2);border-left:3px solid #8c1d1d;border-radius:2px;padding:6px 8px;margin:5px 0;}\n        .alert-box h4{color:#8c1d1d;margin:0 0 3px 0;font-size:9.8px;font-weight:800;text-transform:uppercase;letter-spacing:0;font-family:-apple-system,BlinkMacSystemFont,\"Segoe UI\",sans-serif;}\n        .alert-box p{margin:0 0 4px 0;font-size:9.8px;line-height:1.85;color:#3f3f3f;}\n        .alert-box p:last-child{margin-bottom:0;font-weight:bold;color:#5c1313;}\n        .delivery-note-box{background:#f1f5f9;border-left:2px solid #475569;padding:5px 7px;margin:5px 0;font-size:8.8px;color:#334155;line-height:1.85;border-radius:0 2px 2px 0;font-family:-apple-system,BlinkMacSystemFont,\"Segoe UI\",sans-serif;}\n        .delivery-note-box strong{color:#1e293b;display:inline;margin-right:5px;text-transform:uppercase;font-size:8.3px;letter-spacing:0;}\n        .bank-details-box{background:#fafbfd;border:1px solid #e2e8f0;border-radius:2px;padding:5px 7px;margin:5px 0;font-size:8.9px;font-family:-apple-system,BlinkMacSystemFont,\"Segoe UI\",sans-serif;line-height:1.85;}\n        .bank-title{display:inline;font-weight:800;font-size:8.7px;margin:0 7px 0 0;text-transform:uppercase;color:#222;letter-spacing:0;border:0;padding:0;}\n        .bank-line{display:inline;color:#333;white-space:nowrap;}\n        .bank-item{display:inline;margin-right:8px;white-space:nowrap;}\n        .bank-item strong{font-weight:700;color:#555;}\n        .signatures-section{display:table;width:100%;margin-top:10px;border-top:1px solid #e2e8f0;padding-top:7px;font-family:-apple-system,BlinkMacSystemFont,\"Segoe UI\",sans-serif;page-break-inside:avoid;}\n        .signature-block{display:table-cell;width:50%;text-align:center;vertical-align:bottom;}\n        .sig-image-container{height:72px;margin:0 auto 2px;text-align:center;display:flex;align-items:flex-end;justify-content:center;}\n        .sig-image{max-height:72px;max-width:270px;display:inline-block;}\n        .signature-line{width:190px;border-top:1px solid #222;margin:2px auto 3px;height:1px;}\n        .digital-stamp-mock{border:1px dashed #cbd5e1;padding:4px 8px;width:125px;margin:0 auto;color:#94a3b8;font-size:7.5px;font-style:italic;border-radius:2px;text-transform:uppercase;letter-spacing:0;line-height:1.85;}\n        .signer-title{font-weight:700;font-size:8.8px;color:#222;margin:0 0 1px 0;text-transform:uppercase;letter-spacing:0;}\n        .signer-subtitle{font-size:8px;color:#555;margin:0;letter-spacing:0;}\n        .footer{margin-top:7px;border-top:1px solid #8c1d1d;padding-top:4px;text-align:center;font-size:8px;color:#555;font-family:-apple-system,BlinkMacSystemFont,\"Segoe UI\",sans-serif;line-height:1.85;}\n        .footer strong{color:#8c1d1d;text-transform:uppercase;letter-spacing:0;}\n        @media print{\n            html,body{background:#fff;padding:0;margin:0;}\n            .container{border:none;box-shadow:none;padding:0;width:100%;max-width:100%;min-height:287mm;margin:0;display:flex;flex-direction:column;}\n            body,.container,.container *{color:#000!important;text-shadow:none!important;}\n            .container:before{color:rgba(0,0,0,.02);}\n            .warning-banner,.alert-box,.delivery-note-box,.financial-summary th{-webkit-print-color-adjust:exact;print-color-adjust:exact;}\n            .warning-banner{background:#f8fafc!important;border-left:3px solid #000!important;}\n            .alert-box{background:#f8fafc!important;border:1px solid #000!important;}\n            .delivery-note-box{background:#f8fafc!important;border-left:2px solid #000!important;}\n            .warning-title,.company-name,.signer-title{color:#000!important;}\n            .financial-summary th{background:#f1f5f9!important;border-bottom:1px solid #000!important;}\n            .letter-body{flex:1;display:flex;flex-direction:column;justify-content:space-between;font-size:11.2px;line-height:1.85;margin-bottom:6mm;}\n            .letter-body p{line-height:1.85;margin-bottom:0;}\n            .table-container,.alert-box,.bank-details-box,.delivery-note-box{margin:0;}\n            .financial-summary{font-size:10px;}\n            .financial-summary th{font-size:8.6px;padding:4px 5px;}\n            .financial-summary td{padding:4px 5px;}\n            .alert-box p{font-size:10.2px;line-height:1.85;margin-bottom:2px;}\n            .delivery-note-box{font-size:9.2px;line-height:1.85;}\n            .bank-details-box{font-size:9.2px;}\n            .signatures-section{page-break-inside:avoid;margin-top:0;}\n            .footer{page-break-inside:avoid;}\n        }\n    </style>\n<style type=\"text/css\" id=\"wv-urdu-font-definitions\">\n@font-face {\n    font-family: \'Jameel Noori Nastaleeq\';\n    src: url(\'/whitevillas/fonts/JameelNooriNastaleeq.ttf\') format(\'truetype\'),\n         url(\'/fonts/JameelNooriNastaleeq.ttf\') format(\'truetype\'),\n         url(\'../fonts/JameelNooriNastaleeq.ttf\') format(\'truetype\');\n    font-weight: normal;\n    font-style: normal;\n    font-display: swap;\n}\n@font-face {\n    font-family: \'Jameel Noori Nastaleeq Kasheeda\';\n    src: url(\'/whitevillas/fonts/JameelNooriNastaleeqKasheeda.ttf\') format(\'truetype\'),\n         url(\'/fonts/JameelNooriNastaleeqKasheeda.ttf\') format(\'truetype\'),\n         url(\'../fonts/JameelNooriNastaleeqKasheeda.ttf\') format(\'truetype\');\n    font-weight: normal;\n    font-style: normal;\n    font-display: swap;\n}\n*, *:before, *:after {\n    -webkit-print-color-adjust: exact !important;\n    print-color-adjust: exact !important;\n    color-adjust: exact !important;\n}\n[lang=\"ur\"], [dir=\"rtl\"], .urdu-text, .ashtam-page, .letter-ur, .urdu-body, .urdu-legal {\n    font-family: \'Jameel Noori Nastaleeq\', \'Noto Nastaliq Urdu\', \'Nafees Nastaleeq\', serif !important;\n    line-height: 1.85 !important;\n    letter-spacing: 0 !important;\n    word-spacing: 0 !important;\n}\n[lang=\"ur\"] h1, [lang=\"ur\"] h2, [lang=\"ur\"] h3, [lang=\"ur\"] h4, [lang=\"ur\"] h5, [lang=\"ur\"] h6,\n[dir=\"rtl\"] h1, [dir=\"rtl\"] h2, [dir=\"rtl\"] h3, [dir=\"rtl\"] h4, [dir=\"rtl\"] h5, [dir=\"rtl\"] h6,\n.ashtam-page h1, .ashtam-page h2, .ashtam-page h3, .ashtam-page h4,\n.urdu-heading, .ashtam-heading, .document-title, .document-subtitle, .section-title, .sign-title, .bismillah {\n    font-family: \'Jameel Noori Nastaleeq Kasheeda\', \'Jameel Noori Nastaleeq\', \'Noto Nastaliq Urdu\', serif !important;\n    font-weight: normal !important;\n    line-height: 1.5 !important;\n}\n[lang=\"ur\"] p, [lang=\"ur\"] li, [lang=\"ur\"] td, [lang=\"ur\"] th, [lang=\"ur\"] span,\n[dir=\"rtl\"] p, [dir=\"rtl\"] li, [dir=\"rtl\"] td, [dir=\"rtl\"] th, [dir=\"rtl\"] span,\n.ashtam-page p, .ashtam-page li, .ashtam-page td, .ashtam-page th,\n.urdu-body p, .clause, .note-box, .amount-box {\n    font-family: \'Jameel Noori Nastaleeq\', \'Noto Nastaliq Urdu\', \'Nafees Nastaleeq\', serif !important;\n    line-height: 1.85 !important;\n}\n@media print {\n    @page { size: auto; margin: 0; }\n    html, body {\n        background: #ffffff !important;\n        color: #000000 !important;\n        margin: 0 !important;\n        padding: 0 !important;\n    }\n    .ashtam-page, .page, .form-container, .container, .letter-preview-print {\n        margin: 0 auto !important;\n        box-shadow: none !important;\n        -webkit-print-color-adjust: exact !important;\n        print-color-adjust: exact !important;\n        color-adjust: exact !important;\n    }\n}\n</style></head>\n<body>\n<div class=\"container\">\n    <div class=\"header\">\n        <div class=\"logo-section\">\n            <div class=\"logo-placeholder\">{{agency_logo}}</div>\n        </div>\n        <div class=\"company-details\">\n            <h1 class=\"company-name\">{{agency_name}}</h1>\n            <p class=\"company-info\">{{agency_address}}</p>\n            <p class=\"company-info\">Phone: {{agency_phone}} | E-mail: {{agency_email}}</p>\n        </div>\n    </div>\n    <div class=\"meta-section\">\n        <div class=\"meta-col-left\">Ref. No: <strong>{{letter_ref_no}}</strong></div>\n        <div class=\"meta-col-right\">Date: <strong>{{letter_date}}</strong></div>\n    </div>\n    <div class=\"warning-banner\">\n        <h2 class=\"warning-title\">Final Deal Cancellation &amp; Revocation Warning</h2>\n        <p class=\"warning-subtitle\">Subject: Notice of Absolute Forfeiture &amp; Property Reallocation</p>\n    </div>\n    <div class=\"client-info\">\n        <div class=\"client-title\">Notice Addressee (Defaulter Client)</div>\n        <div class=\"client-name\">{{client_name}} S/O {{client_father_name}}</div>\n        <div class=\"client-address\">{{client_address}}</div>\n        <div style=\"margin-top:2px;font-size:10px;font-weight:bold;color:#222;\">Mobile Number: <span style=\"font-family:monospace;font-size:10px;\">{{client_mobile}}</span></div>\n    </div>\n    <div class=\"letter-body\">\n        <p>Dear Sir/Madam,</p>\n        <p>We refer to our previous notices and the Payment Demand Letter sent under Ref: <strong>{{letter_ref_no}}</strong>. Despite several administrative grace margins, your payments towards the purchase of your <span class=\"highlight-text\">{{property_type}}</span>, Property/File Code: <span class=\"highlight-text\">{{property_file}}</span>, situated at <span class=\"highlight-text\">{{project_name}}</span>, remain severely delinquent.</p>\n        <p>The total agreed consideration for the aforementioned property is <span class=\"highlight-text\">{{deal_total_amount}} ({{deal_total_amount_words}})</span>. You have defaulted on multiple consecutive monthly schedules, accumulating a major outstanding balance.</p>\n        <div class=\"table-container\">\n            <table class=\"financial-summary\">\n                <thead>\n                    <tr>\n                        <th>Overdue Installment Milestones</th>\n                        <th style=\"text-align:center;\">Total Default Count</th>\n                        <th style=\"text-align:right;\">Total Outstanding Overdue (PKR)</th>\n                    </tr>\n                </thead>\n                <tbody>\n                    <tr>\n                        <td style=\"font-weight:500;\">{{overdue_installments_label}}</td>\n                        <td style=\"text-align:center;color:#8c1d1d;font-weight:bold;\">{{overdue_installments_count}} Consecutive Installments</td>\n                        <td style=\"text-align:right;color:#8c1d1d;font-weight:bold;\">{{overdue_amount}}</td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"3\" style=\"font-size:11px;background:#fafbfd;border-top:1px solid #e2e8f0;color:#555;\">\n                            <strong>Amount in Words:</strong> <span style=\"color:#222;font-weight:600;text-transform:capitalize;\">{{overdue_amount_words}}</span>\n                        </td>\n                    </tr>\n                </tbody>\n            </table>\n        </div>\n        <p>Under the signed and agreed Terms &amp; Conditions of booking, failure to pay <strong>{{overdue_installments_count}}</strong> consecutive monthly installments triggers immediate revocation of allotment rights, leading directly to booking termination and the absolute forfeiture of initial deposit milestones.</p>\n        <div class=\"alert-box\">\n            <h4>&#128680; Formal Declaration of Impending Legal Action &amp; Allotment Revocation</h4>\n            <p><strong>FINAL REQUISITION:</strong> If the total outstanding overdue amount of <strong>{{overdue_amount}}</strong> is not cleared and credited in full within <strong>{{final_notice_deadline_days}} days</strong> of this notice, your booking, deal, and property allotment for <strong>{{property_file}}</strong> will stand <strong>permanently cancelled without further recourse.</strong></p>\n            <p>Following the cancellation, the company will exercise its complete legal rights to immediately revoke physical possession, purge the register records, and reallocate or sell this property to other prospective buyers on the waiting list. {{agency_name}} shall also initiate recovery litigation to claim any accrued default damages.</p>\n        </div>\n        <div class=\"bank-details-box\">\n            <div class=\"bank-title\">Authorized Bank Payment Channels</div>\n            <div class=\"bank-line\">\n                <span class=\"bank-item\"><strong>Title:</strong> {{bank_account_title}}</span>\n                <span class=\"bank-item\"><strong>Bank:</strong> {{bank_name}}</span>\n                <span class=\"bank-item\"><strong>A/C:</strong> {{bank_account_no}}</span>\n                <span class=\"bank-item\"><strong>IBAN:</strong> {{bank_iban}}</span>\n                <span class=\"bank-item\"><strong>Branch:</strong> {{bank_branch}}</span>\n            </div>\n        </div>\n        <div class=\"delivery-note-box\">\n            <strong>Proof of Delivery &amp; Legal Service Status</strong>\n            This is an officially dispatched and legally recognized <strong>FINAL NOTICE</strong>. It has been transmitted to you concurrently through multiple verified physical and electronic channels: (1) Hand-delivered/Posted physically to your registered residential home address, (2) Dispatched to your property\'s absolute physical possession address, (3) Electronically delivered to your registered email on record, and (4) Transmitted via WhatsApp messenger notification to your registered telephone line.\n            <br><span style=\"font-weight:bold;color:#8c1d1d;\">Delivery is legally deemed active and fully acknowledged upon dispatch. Counter-signature of receipt or returned postal receipt by the defaulting client is not required for this legal notice to take immediate, absolute effect.</span>\n        </div>\n        <p>We urge you to treat this notification with the highest priority to safeguard your property value and prevent immediate legal termination of your unit booking.</p>\n        <p>Yours Sincerely,</p>\n    </div>\n    <div class=\"signatures-section\">\n        <div class=\"signature-block\">\n            <div class=\"sig-image-container\">{{ceo_signature}}</div>\n            <div class=\"signature-line\"></div>\n            <p class=\"signer-title\">Chief Executive Officer</p>\n            <p class=\"signer-subtitle\">{{agency_name}}</p>\n        </div>\n        <div class=\"signature-block\">\n            <div class=\"sig-image-container\">{{chairman_signature}}</div>\n            <div class=\"signature-line\"></div>\n            <p class=\"signer-title\">Chairman of the Board</p>\n            <p class=\"signer-subtitle\">{{agency_name}}</p>\n        </div>\n    </div>\n    <div class=\"footer\">\n        <strong>{{agency_name}}</strong><br>\n        Office Address: {{agency_address}}<br>\n        Contact: {{agency_phone}} | Email: {{agency_email}}\n    </div>\n</div>\n</body>\n</html>', 'RLT_FINAL_CANCEL', 'Unpublished', 'Yes', 'ceo_signature_default_20260521.png', 'letter_signatures', 'chairman_signature_default_20260521.png', 'letter_signatures');
INSERT INTO `templates` (`id`, `name`, `description`, `type`, `status`, `is_new`, `ceo_signature`, `ceo_signature_dir`, `chairman_signature`, `chairman_signature_dir`) VALUES
(24, 'Final Cancellation Notice', '<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>FINAL DEMAND: Deal Cancellation Warning</title>\n    <style>\n        @page{size:A4;margin:5mm;}\n        *{box-sizing:border-box;}\n        body{font-family:-apple-system,BlinkMacSystemFont,\"Segoe UI\",Roboto,Helvetica,Arial,sans-serif;color:#222;line-height:1.85;background:#f8fafc;margin:0;padding:12px 8px;-webkit-font-smoothing:antialiased;}\n        .container{width:198mm;max-width:100%;margin:0 auto;background:#fff;border:1px solid #e2e8f0;border-top:3px solid #8c1d1d;box-shadow:0 6px 14px rgba(0,0,0,.045);padding:15px 18px;box-sizing:border-box;position:relative;overflow:hidden;}\n        .container:before{content:\"FINAL NOTICE\";position:absolute;top:51%;left:50%;transform:translate(-50%,-50%) rotate(-45deg);font-size:62px;font-weight:900;color:rgba(140,29,29,.022);pointer-events:none;z-index:1;white-space:nowrap;letter-spacing:0;}\n        .container>*{position:relative;z-index:2;}\n        .header{display:table;width:100%;border-bottom:1px solid #d9e1ec;padding-bottom:7px;margin-bottom:7px;}\n        .logo-section{display:table-cell;vertical-align:middle;width:72px;}\n        .logo-placeholder{width:52px;height:auto;max-height:44px;object-fit:contain;}\n        .company-details{display:table-cell;vertical-align:middle;text-align:right;}\n        .company-name{font-size:16px;font-weight:800;text-transform:uppercase;color:#8c1d1d;margin:0 0 2px 0;letter-spacing:0;}\n        .company-info{font-size:8.8px;color:#555;margin:0;letter-spacing:0;line-height:1.85;}\n        .meta-section{display:table;width:100%;margin-bottom:7px;font-size:9.8px;border-bottom:1px dashed #e2e8f0;padding-bottom:4px;}\n        .meta-col-left{display:table-cell;text-align:left;color:#555;}\n        .meta-col-right{display:table-cell;text-align:right;color:#555;}\n        .meta-section strong{color:#222;}\n        .warning-banner{background:#fff5f5;border-left:3px solid #8c1d1d;padding:6px 8px;margin-bottom:7px;border-radius:0 2px 2px 0;}\n        .warning-title{color:#8c1d1d;font-size:14px;font-weight:800;margin:0 0 1px 0;letter-spacing:0;text-transform:uppercase;}\n        .warning-subtitle{font-size:9.2px;font-weight:bold;color:#5c1313;margin:0;letter-spacing:0;text-transform:uppercase;}\n        .client-info{background:#fbfcfd;border:1px solid #e2e8f0;border-radius:2px;padding:6px 8px;margin-bottom:7px;font-size:10.2px;}\n        .client-title{font-size:8px;text-transform:uppercase;color:#8c1d1d;margin:0 0 2px 0;letter-spacing:0;font-weight:800;}\n        .client-name{font-size:11.5px;font-weight:700;color:#000;margin:0 0 1px 0;}\n        .client-address{color:#555;line-height:1.85;}\n        .letter-body{font-family:Georgia,Cambria,\"Times New Roman\",Times,serif;font-size:10.7px;text-align:justify;color:#2c2c2c;margin-bottom:7px;}\n        .letter-body p{margin:0 0 4px 0;line-height:1.85;}\n        .highlight-text{font-family:-apple-system,BlinkMacSystemFont,\"Segoe UI\",sans-serif;font-weight:700;color:#000;padding:0 2px;text-decoration:underline;}\n        .table-container{margin:5px 0;border:1px solid #e2e8f0;border-radius:2px;overflow:hidden;}\n        .financial-summary{width:100%;border-collapse:collapse;font-family:-apple-system,BlinkMacSystemFont,\"Segoe UI\",sans-serif;font-size:9.6px;}\n        .financial-summary th{background:#f8fafc;border-bottom:1px solid #d9e1ec;color:#222;padding:4px 5px;text-align:left;font-weight:700;text-transform:uppercase;font-size:8.2px;letter-spacing:0;}\n        .financial-summary td{border-bottom:1px solid #e2e8f0;padding:4px 5px;color:#222;}\n        .financial-summary tr:last-child td{border-bottom:none;}\n        .alert-box{background:#fff5f5;border:1px solid rgba(140,29,29,.2);border-left:3px solid #8c1d1d;border-radius:2px;padding:6px 8px;margin:5px 0;}\n        .alert-box h4{color:#8c1d1d;margin:0 0 3px 0;font-size:9.8px;font-weight:800;text-transform:uppercase;letter-spacing:0;font-family:-apple-system,BlinkMacSystemFont,\"Segoe UI\",sans-serif;}\n        .alert-box p{margin:0 0 4px 0;font-size:9.8px;line-height:1.85;color:#3f3f3f;}\n        .alert-box p:last-child{margin-bottom:0;font-weight:bold;color:#5c1313;}\n        .delivery-note-box{background:#f1f5f9;border-left:2px solid #475569;padding:5px 7px;margin:5px 0;font-size:8.8px;color:#334155;line-height:1.85;border-radius:0 2px 2px 0;font-family:-apple-system,BlinkMacSystemFont,\"Segoe UI\",sans-serif;}\n        .delivery-note-box strong{color:#1e293b;display:inline;margin-right:5px;text-transform:uppercase;font-size:8.3px;letter-spacing:0;}\n        .bank-details-box{background:#fafbfd;border:1px solid #e2e8f0;border-radius:2px;padding:5px 7px;margin:5px 0;font-size:8.9px;font-family:-apple-system,BlinkMacSystemFont,\"Segoe UI\",sans-serif;line-height:1.85;}\n        .bank-title{display:inline;font-weight:800;font-size:8.7px;margin:0 7px 0 0;text-transform:uppercase;color:#222;letter-spacing:0;border:0;padding:0;}\n        .bank-line{display:inline;color:#333;white-space:nowrap;}\n        .bank-item{display:inline;margin-right:8px;white-space:nowrap;}\n        .bank-item strong{font-weight:700;color:#555;}\n        .signatures-section{display:table;width:100%;margin-top:10px;border-top:1px solid #e2e8f0;padding-top:7px;font-family:-apple-system,BlinkMacSystemFont,\"Segoe UI\",sans-serif;page-break-inside:avoid;}\n        .signature-block{display:table-cell;width:50%;text-align:center;vertical-align:bottom;}\n        .sig-image-container{height:72px;margin:0 auto 2px;text-align:center;display:flex;align-items:flex-end;justify-content:center;}\n        .sig-image{max-height:72px;max-width:270px;display:inline-block;}\n        .signature-line{width:190px;border-top:1px solid #222;margin:2px auto 3px;height:1px;}\n        .digital-stamp-mock{border:1px dashed #cbd5e1;padding:4px 8px;width:125px;margin:0 auto;color:#94a3b8;font-size:7.5px;font-style:italic;border-radius:2px;text-transform:uppercase;letter-spacing:0;line-height:1.85;}\n        .signer-title{font-weight:700;font-size:8.8px;color:#222;margin:0 0 1px 0;text-transform:uppercase;letter-spacing:0;}\n        .signer-subtitle{font-size:8px;color:#555;margin:0;letter-spacing:0;}\n        .footer{margin-top:7px;border-top:1px solid #8c1d1d;padding-top:4px;text-align:center;font-size:8px;color:#555;font-family:-apple-system,BlinkMacSystemFont,\"Segoe UI\",sans-serif;line-height:1.85;}\n        .footer strong{color:#8c1d1d;text-transform:uppercase;letter-spacing:0;}\n        @media print{\n            html,body{background:#fff;padding:0;margin:0;}\n            .container{border:none;box-shadow:none;padding:0;width:100%;max-width:100%;min-height:287mm;margin:0;display:flex;flex-direction:column;}\n            body,.container,.container *{color:#000!important;text-shadow:none!important;}\n            .container:before{color:rgba(0,0,0,.02);}\n            .warning-banner,.alert-box,.delivery-note-box,.financial-summary th{-webkit-print-color-adjust:exact;print-color-adjust:exact;}\n            .warning-banner{background:#f8fafc!important;border-left:3px solid #000!important;}\n            .alert-box{background:#f8fafc!important;border:1px solid #000!important;}\n            .delivery-note-box{background:#f8fafc!important;border-left:2px solid #000!important;}\n            .warning-title,.company-name,.signer-title{color:#000!important;}\n            .financial-summary th{background:#f1f5f9!important;border-bottom:1px solid #000!important;}\n            .letter-body{flex:1;display:flex;flex-direction:column;justify-content:space-between;font-size:11.2px;line-height:1.85;margin-bottom:6mm;}\n            .letter-body p{line-height:1.85;margin-bottom:0;}\n            .table-container,.alert-box,.bank-details-box,.delivery-note-box{margin:0;}\n            .financial-summary{font-size:10px;}\n            .financial-summary th{font-size:8.6px;padding:4px 5px;}\n            .financial-summary td{padding:4px 5px;}\n            .alert-box p{font-size:10.2px;line-height:1.85;margin-bottom:2px;}\n            .delivery-note-box{font-size:9.2px;line-height:1.85;}\n            .bank-details-box{font-size:9.2px;}\n            .signatures-section{page-break-inside:avoid;margin-top:0;}\n            .footer{page-break-inside:avoid;}\n        }\n    </style>\n<style type=\"text/css\" id=\"wv-urdu-font-definitions\">\n@font-face {\n    font-family: \'Jameel Noori Nastaleeq\';\n    src: url(\'/whitevillas/fonts/JameelNooriNastaleeq.ttf\') format(\'truetype\'),\n         url(\'/fonts/JameelNooriNastaleeq.ttf\') format(\'truetype\'),\n         url(\'../fonts/JameelNooriNastaleeq.ttf\') format(\'truetype\');\n    font-weight: normal;\n    font-style: normal;\n    font-display: swap;\n}\n@font-face {\n    font-family: \'Jameel Noori Nastaleeq Kasheeda\';\n    src: url(\'/whitevillas/fonts/JameelNooriNastaleeqKasheeda.ttf\') format(\'truetype\'),\n         url(\'/fonts/JameelNooriNastaleeqKasheeda.ttf\') format(\'truetype\'),\n         url(\'../fonts/JameelNooriNastaleeqKasheeda.ttf\') format(\'truetype\');\n    font-weight: normal;\n    font-style: normal;\n    font-display: swap;\n}\n*, *:before, *:after {\n    -webkit-print-color-adjust: exact !important;\n    print-color-adjust: exact !important;\n    color-adjust: exact !important;\n}\n[lang=\"ur\"], [dir=\"rtl\"], .urdu-text, .ashtam-page, .letter-ur, .urdu-body, .urdu-legal {\n    font-family: \'Jameel Noori Nastaleeq\', \'Noto Nastaliq Urdu\', \'Nafees Nastaleeq\', serif !important;\n    line-height: 1.85 !important;\n    letter-spacing: 0 !important;\n    word-spacing: 0 !important;\n}\n[lang=\"ur\"] h1, [lang=\"ur\"] h2, [lang=\"ur\"] h3, [lang=\"ur\"] h4, [lang=\"ur\"] h5, [lang=\"ur\"] h6,\n[dir=\"rtl\"] h1, [dir=\"rtl\"] h2, [dir=\"rtl\"] h3, [dir=\"rtl\"] h4, [dir=\"rtl\"] h5, [dir=\"rtl\"] h6,\n.ashtam-page h1, .ashtam-page h2, .ashtam-page h3, .ashtam-page h4,\n.urdu-heading, .ashtam-heading, .document-title, .document-subtitle, .section-title, .sign-title, .bismillah {\n    font-family: \'Jameel Noori Nastaleeq Kasheeda\', \'Jameel Noori Nastaleeq\', \'Noto Nastaliq Urdu\', serif !important;\n    font-weight: normal !important;\n    line-height: 1.5 !important;\n}\n[lang=\"ur\"] p, [lang=\"ur\"] li, [lang=\"ur\"] td, [lang=\"ur\"] th, [lang=\"ur\"] span,\n[dir=\"rtl\"] p, [dir=\"rtl\"] li, [dir=\"rtl\"] td, [dir=\"rtl\"] th, [dir=\"rtl\"] span,\n.ashtam-page p, .ashtam-page li, .ashtam-page td, .ashtam-page th,\n.urdu-body p, .clause, .note-box, .amount-box {\n    font-family: \'Jameel Noori Nastaleeq\', \'Noto Nastaliq Urdu\', \'Nafees Nastaleeq\', serif !important;\n    line-height: 1.85 !important;\n}\n@media print {\n    @page { size: auto; margin: 0; }\n    html, body {\n        background: #ffffff !important;\n        color: #000000 !important;\n        margin: 0 !important;\n        padding: 0 !important;\n    }\n    .ashtam-page, .page, .form-container, .container, .letter-preview-print {\n        margin: 0 auto !important;\n        box-shadow: none !important;\n        -webkit-print-color-adjust: exact !important;\n        print-color-adjust: exact !important;\n        color-adjust: exact !important;\n    }\n}\n</style></head>\n<body>\n<div class=\"container\">\n    <div class=\"header\">\n        <div class=\"logo-section\">\n            <div class=\"logo-placeholder\">{{agency_logo}}</div>\n        </div>\n        <div class=\"company-details\">\n            <h1 class=\"company-name\">{{agency_name}}</h1>\n            <p class=\"company-info\">{{agency_address}}</p>\n            <p class=\"company-info\">Phone: {{agency_phone}} | E-mail: {{agency_email}}</p>\n        </div>\n    </div>\n    <div class=\"meta-section\">\n        <div class=\"meta-col-left\">Ref. No: <strong>{{letter_ref_no}}</strong></div>\n        <div class=\"meta-col-right\">Date: <strong>{{letter_date}}</strong></div>\n    </div>\n    <div class=\"warning-banner\">\n        <h2 class=\"warning-title\">Final Deal Cancellation &amp; Revocation Warning</h2>\n        <p class=\"warning-subtitle\">Subject: Notice of Absolute Forfeiture &amp; Property Reallocation</p>\n    </div>\n    <div class=\"client-info\">\n        <div class=\"client-title\">Notice Addressee (Defaulter Client)</div>\n        <div class=\"client-name\">{{client_name}} S/O {{client_father_name}}</div>\n        <div class=\"client-address\">{{client_address}}</div>\n        <div style=\"margin-top:2px;font-size:10px;font-weight:bold;color:#222;\">Mobile Number: <span style=\"font-family:monospace;font-size:10px;\">{{client_mobile}}</span></div>\n    </div>\n    <div class=\"letter-body\">\n        <p>Dear Sir/Madam,</p>\n        <p>We refer to our previous notices and the Payment Demand Letter sent under Ref: <strong>{{letter_ref_no}}</strong>. Despite several administrative grace margins, your payments towards the purchase of your <span class=\"highlight-text\">{{property_type}}</span>, Property/File Code: <span class=\"highlight-text\">{{property_file}}</span>, situated at <span class=\"highlight-text\">{{project_name}}</span>, remain severely delinquent.</p>\n        <p>The total agreed consideration for the aforementioned property is <span class=\"highlight-text\">{{deal_total_amount}} ({{deal_total_amount_words}})</span>. You have defaulted on multiple consecutive monthly schedules, accumulating a major outstanding balance.</p>\n        <div class=\"table-container\">\n            <table class=\"financial-summary\">\n                <thead>\n                    <tr>\n                        <th>Overdue Installment Milestones</th>\n                        <th style=\"text-align:center;\">Total Default Count</th>\n                        <th style=\"text-align:right;\">Total Outstanding Overdue (PKR)</th>\n                    </tr>\n                </thead>\n                <tbody>\n                    <tr>\n                        <td style=\"font-weight:500;\">{{overdue_installments_label}}</td>\n                        <td style=\"text-align:center;color:#8c1d1d;font-weight:bold;\">{{overdue_installments_count}} Consecutive Installments</td>\n                        <td style=\"text-align:right;color:#8c1d1d;font-weight:bold;\">{{overdue_amount}}</td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"3\" style=\"font-size:11px;background:#fafbfd;border-top:1px solid #e2e8f0;color:#555;\">\n                            <strong>Amount in Words:</strong> <span style=\"color:#222;font-weight:600;text-transform:capitalize;\">{{overdue_amount_words}}</span>\n                        </td>\n                    </tr>\n                </tbody>\n            </table>\n        </div>\n        <p>Under the signed and agreed Terms &amp; Conditions of booking, failure to pay <strong>{{overdue_installments_count}}</strong> consecutive monthly installments triggers immediate revocation of allotment rights, leading directly to booking termination and the absolute forfeiture of initial deposit milestones.</p>\n        <div class=\"alert-box\">\n            <h4>&#128680; Formal Declaration of Impending Legal Action &amp; Allotment Revocation</h4>\n            <p><strong>FINAL REQUISITION:</strong> If the total outstanding overdue amount of <strong>{{overdue_amount}}</strong> is not cleared and credited in full within <strong>{{final_notice_deadline_days}} days</strong> of this notice, your booking, deal, and property allotment for <strong>{{property_file}}</strong> will stand <strong>permanently cancelled without further recourse.</strong></p>\n            <p>Following the cancellation, the company will exercise its complete legal rights to immediately revoke physical possession, purge the register records, and reallocate or sell this property to other prospective buyers on the waiting list. {{agency_name}} shall also initiate recovery litigation to claim any accrued default damages.</p>\n        </div>\n        <div class=\"bank-details-box\">\n            <div class=\"bank-title\">Authorized Bank Payment Channels</div>\n            <div class=\"bank-line\">\n                <span class=\"bank-item\"><strong>Title:</strong> {{bank_account_title}}</span>\n                <span class=\"bank-item\"><strong>Bank:</strong> {{bank_name}}</span>\n                <span class=\"bank-item\"><strong>A/C:</strong> {{bank_account_no}}</span>\n                <span class=\"bank-item\"><strong>IBAN:</strong> {{bank_iban}}</span>\n                <span class=\"bank-item\"><strong>Branch:</strong> {{bank_branch}}</span>\n            </div>\n        </div>\n        <div class=\"delivery-note-box\">\n            <strong>Proof of Delivery &amp; Legal Service Status</strong>\n            This is an officially dispatched and legally recognized <strong>FINAL NOTICE</strong>. It has been transmitted to you concurrently through multiple verified physical and electronic channels: (1) Hand-delivered/Posted physically to your registered residential home address, (2) Dispatched to your property\'s absolute physical possession address, (3) Electronically delivered to your registered email on record, and (4) Transmitted via WhatsApp messenger notification to your registered telephone line.\n            <br><span style=\"font-weight:bold;color:#8c1d1d;\">Delivery is legally deemed active and fully acknowledged upon dispatch. Counter-signature of receipt or returned postal receipt by the defaulting client is not required for this legal notice to take immediate, absolute effect.</span>\n        </div>\n        <p>We urge you to treat this notification with the highest priority to safeguard your property value and prevent immediate legal termination of your unit booking.</p>\n        <p>Yours Sincerely,</p>\n    </div>\n    <div class=\"signatures-section\">\n        <div class=\"signature-block\">\n            <div class=\"sig-image-container\">{{ceo_signature}}</div>\n            <div class=\"signature-line\"></div>\n            <p class=\"signer-title\">Chief Executive Officer</p>\n            <p class=\"signer-subtitle\">{{agency_name}}</p>\n        </div>\n        <div class=\"signature-block\">\n            <div class=\"sig-image-container\">{{chairman_signature}}</div>\n            <div class=\"signature-line\"></div>\n            <p class=\"signer-title\">Chairman of the Board</p>\n            <p class=\"signer-subtitle\">{{agency_name}}</p>\n        </div>\n    </div>\n    <div class=\"footer\">\n        <strong>{{agency_name}}</strong><br>\n        Office Address: {{agency_address}}<br>\n        Contact: {{agency_phone}} | Email: {{agency_email}}\n    </div>\n</div>\n</body>\n</html>', 'RLT_FINAL_CANCEL', 'Unpublished', 'Yes', 'ceo_signature_default_20260521.png', 'letter_signatures', 'chairman_signature_default_20260521.png', 'letter_signatures'),
(25, 'Final Cancellation Notice', '<!DOCTYPE html>\r\n<html lang=\"en\">\r\n<head>\r\n    <meta charset=\"UTF-8\">\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n    <title>FINAL DEMAND: Deal Cancellation Warning</title>\r\n    <style>\r\n        @page{size:A4;margin:5mm;}\r\n        *{box-sizing:border-box;}\r\n        body{font-family:\"Times New Roman\",Times,serif;color:#000;line-height:1.85;background:#f8fafc;margin:0;padding:12px 8px;-webkit-font-smoothing:antialiased;}\r\n        .container{width:198mm;max-width:100%;margin:0 auto;background:#fff;border:1px solid #222;border-top:3px solid #000;box-shadow:0 6px 14px rgba(0,0,0,.045);padding:15px 18px;box-sizing:border-box;position:relative;overflow:hidden;}\r\n        .container:before{content:\"FINAL NOTICE\";position:absolute;top:51%;left:50%;transform:translate(-50%,-50%) rotate(-45deg);font-size:62px;font-weight:900;color:rgba(140,29,29,.022);pointer-events:none;z-index:1;white-space:nowrap;letter-spacing:0;}\r\n        .container>*{position:relative;z-index:2;}\r\n        .header{display:table;width:100%;border-bottom:1px solid #111;padding-bottom:8px;margin-bottom:8px;text-align:left;}\r\n        .logo-section{display:table-cell;vertical-align:middle;width:92px;text-align:left;padding-right:18px;}\r\n        .logo-placeholder{width:58px;height:auto;max-height:50px;object-fit:contain;margin:0;display:block;text-align:left;}\r\n        .logo-placeholder img{max-width:58px;max-height:50px;width:auto;height:auto;object-fit:contain;display:block;margin:0;}\r\n        .company-details{display:table-cell;vertical-align:middle;text-align:left;padding-left:6px;}\r\n        .company-name{font-size:16px;font-weight:800;text-transform:uppercase;color:#000;margin:0 0 2px 0;letter-spacing:0;}\r\n        .company-info{font-size:9.2px;color:#111;margin:0;letter-spacing:0;line-height:1.85;}\r\n        .meta-section{display:table;width:100%;margin-bottom:7px;font-size:9.8px;border-bottom:1px dashed #222;padding-bottom:4px;}\r\n        .meta-col-left{display:table-cell;text-align:left;color:#111;}\r\n        .meta-col-right{display:table-cell;text-align:right;color:#111;}\r\n        .meta-section strong{color:#000;}\r\n        .warning-banner{background:#fff5f5;border-left:3px solid #000;padding:6px 8px;margin-bottom:7px;border-radius:0 2px 2px 0;}\r\n        .warning-title{color:#000;font-size:14px;font-weight:800;margin:0 0 1px 0;letter-spacing:0;text-transform:uppercase;}\r\n        .warning-subtitle{font-size:9.2px;font-weight:bold;color:#000;margin:0;letter-spacing:0;text-transform:uppercase;}\r\n        .client-info{background:#fbfcfd;border:1px solid #222;border-radius:2px;padding:6px 8px;margin-bottom:7px;font-size:10.2px;}\r\n        .client-title{font-size:8px;text-transform:uppercase;color:#000;margin:0 0 2px 0;letter-spacing:0;font-weight:800;}\r\n        .client-name{font-size:11.5px;font-weight:700;color:#000;margin:0 0 1px 0;}\r\n        .client-address{color:#111;line-height:1.85;}\r\n        .letter-body{font-family:\"Times New Roman\",Times,serif;font-size:11px;text-align:justify;color:#000;margin-bottom:8px;line-height:1.5;}\r\n        .letter-body p{margin:0 0 6px 0;line-height:1.5;}\r\n        .highlight-text{font-family:\"Times New Roman\",Times,serif;font-weight:700;color:#000;padding:0 2px;text-decoration:underline;}\r\n        .table-container{margin:5px 0;border:1px solid #222;border-radius:2px;overflow:hidden;}\r\n        .financial-summary{width:100%;border-collapse:collapse;font-family:\"Times New Roman\",Times,serif;font-size:9.6px;}\r\n        .financial-summary th{background:#f8fafc;border-bottom:1px solid #222;color:#000;padding:4px 5px;text-align:left;font-weight:700;text-transform:uppercase;font-size:8.2px;letter-spacing:0;}\r\n        .financial-summary td{border-bottom:1px solid #222;padding:4px 5px;color:#000;}\r\n        .financial-summary tr:last-child td{border-bottom:none;}\r\n        .alert-box{background:#fff5f5;border:1px solid #222;border-left:3px solid #000;border-radius:2px;padding:6px 8px;margin:5px 0;}\r\n        .alert-box h4{color:#000;margin:0 0 3px 0;font-size:9.8px;font-weight:800;text-transform:uppercase;letter-spacing:0;font-family:\"Times New Roman\",Times,serif;}\r\n        .alert-box p{margin:0 0 4px 0;font-size:9.8px;line-height:1.85;color:#000;}\r\n        .alert-box p:last-child{margin-bottom:0;font-weight:bold;color:#000;}\r\n        .delivery-note-box{background:#f1f5f9;border-left:2px solid #000;padding:5px 7px;margin:5px 0;font-size:9.1px;color:#000;line-height:1.85;border-radius:0 2px 2px 0;font-family:\"Times New Roman\",Times,serif;}\r\n        .delivery-note-box strong{color:#000;display:inline;margin-right:5px;text-transform:uppercase;font-size:8.3px;letter-spacing:0;}\r\n        .bank-details-box{background:#fafbfd;border:1px solid #222;border-radius:2px;padding:5px 7px;margin:5px 0;font-size:9.1px;font-family:\"Times New Roman\",Times,serif;line-height:1.85;}\r\n        .bank-title{display:inline;font-weight:800;font-size:8.7px;margin:0 7px 0 0;text-transform:uppercase;color:#000;letter-spacing:0;border:0;padding:0;}\r\n        .bank-line{display:inline;color:#000;white-space:nowrap;}\r\n        .bank-item{display:inline;margin-right:8px;white-space:nowrap;}\r\n        .bank-item strong{font-weight:700;color:#111;}\r\n        .signatures-section{display:table;width:100%;margin-top:10px;border-top:1px solid #222;padding-top:7px;font-family:\"Times New Roman\",Times,serif;page-break-inside:avoid;}\r\n        .signature-block{display:table-cell;width:50%;text-align:center;vertical-align:bottom;}\r\n        .sig-image-container{height:72px;margin:0 auto 2px;text-align:center;display:flex;align-items:flex-end;justify-content:center;}\r\n        .sig-image{max-height:72px;max-width:270px;display:inline-block;}\r\n        .signature-line{width:190px;border-top:1px solid #222;margin:2px auto 3px;height:1px;}\r\n        .digital-stamp-mock{border:1px dashed #cbd5e1;padding:4px 8px;width:125px;margin:0 auto;color:#000;font-size:7.5px;font-style:italic;border-radius:2px;text-transform:uppercase;letter-spacing:0;line-height:1.85;}\r\n        .signer-title{font-weight:700;font-size:8.8px;color:#000;margin:0 0 1px 0;text-transform:uppercase;letter-spacing:0;}\r\n        .signer-subtitle{font-size:8px;color:#111;margin:0;letter-spacing:0;}\r\n        .footer{margin-top:7px;border-top:1px solid #000;padding-top:4px;text-align:center;font-size:8.5px;color:#111;font-family:\"Times New Roman\",Times,serif;line-height:1.85;}\r\n        .footer strong{color:#000;text-transform:uppercase;letter-spacing:0;}\r\n        @media print{\r\n            html,body{background:#fff;padding:0;margin:0;}\r\n            .container{border:none;box-shadow:none;padding:0;width:100%;max-width:100%;min-height:287mm;margin:0;display:flex;flex-direction:column;}\r\n            body,.container,.container *{color:#000!important;text-shadow:none!important;}\r\n            .container:before{color:rgba(0,0,0,.02);}\r\n            .warning-banner,.alert-box,.delivery-note-box,.financial-summary th{-webkit-print-color-adjust:exact;print-color-adjust:exact;}\r\n            .warning-banner{background:#f8fafc!important;border-left:3px solid #000!important;}\r\n            .alert-box{background:#f8fafc!important;border:1px solid #000!important;}\r\n            .delivery-note-box{background:#f8fafc!important;border-left:2px solid #000!important;}\r\n            .warning-title,.company-name,.signer-title{color:#000!important;}\r\n            .financial-summary th{background:#f1f5f9!important;border-bottom:1px solid #000!important;}\r\n            .letter-body{flex:1;display:flex;flex-direction:column;justify-content:flex-start;font-size:11.3px;line-height:1.5;margin-bottom:6mm;}\r\n            .letter-body p{line-height:1.5;margin-bottom:5px;}\r\n            .table-container,.alert-box,.bank-details-box,.delivery-note-box{margin:0;}\r\n            .financial-summary{font-size:10px;}\r\n            .financial-summary th{font-size:8.6px;padding:4px 5px;}\r\n            .financial-summary td{padding:4px 5px;}\r\n            .alert-box p{font-size:10.2px;line-height:1.85;margin-bottom:3px;}\r\n            .delivery-note-box{font-size:9.2px;line-height:1.85;}\r\n            .bank-details-box{font-size:9.2px;}\r\n            .signatures-section{page-break-inside:avoid;margin-top:0;}\r\n            .footer{page-break-inside:avoid;}\r\n        }\r\n    </style>\r\n<style type=\"text/css\" id=\"wv-urdu-font-definitions\">\n@font-face {\n    font-family: \'Jameel Noori Nastaleeq\';\n    src: url(\'/whitevillas/fonts/JameelNooriNastaleeq.ttf\') format(\'truetype\'),\n         url(\'/fonts/JameelNooriNastaleeq.ttf\') format(\'truetype\'),\n         url(\'../fonts/JameelNooriNastaleeq.ttf\') format(\'truetype\');\n    font-weight: normal;\n    font-style: normal;\n    font-display: swap;\n}\n@font-face {\n    font-family: \'Jameel Noori Nastaleeq Kasheeda\';\n    src: url(\'/whitevillas/fonts/JameelNooriNastaleeqKasheeda.ttf\') format(\'truetype\'),\n         url(\'/fonts/JameelNooriNastaleeqKasheeda.ttf\') format(\'truetype\'),\n         url(\'../fonts/JameelNooriNastaleeqKasheeda.ttf\') format(\'truetype\');\n    font-weight: normal;\n    font-style: normal;\n    font-display: swap;\n}\n*, *:before, *:after {\n    -webkit-print-color-adjust: exact !important;\n    print-color-adjust: exact !important;\n    color-adjust: exact !important;\n}\n[lang=\"ur\"], [dir=\"rtl\"], .urdu-text, .ashtam-page, .letter-ur, .urdu-body, .urdu-legal {\n    font-family: \'Jameel Noori Nastaleeq\', \'Noto Nastaliq Urdu\', \'Nafees Nastaleeq\', serif !important;\n    line-height: 1.85 !important;\n    letter-spacing: 0 !important;\n    word-spacing: 0 !important;\n}\n[lang=\"ur\"] h1, [lang=\"ur\"] h2, [lang=\"ur\"] h3, [lang=\"ur\"] h4, [lang=\"ur\"] h5, [lang=\"ur\"] h6,\n[dir=\"rtl\"] h1, [dir=\"rtl\"] h2, [dir=\"rtl\"] h3, [dir=\"rtl\"] h4, [dir=\"rtl\"] h5, [dir=\"rtl\"] h6,\n.ashtam-page h1, .ashtam-page h2, .ashtam-page h3, .ashtam-page h4,\n.urdu-heading, .ashtam-heading, .document-title, .document-subtitle, .section-title, .sign-title, .bismillah {\n    font-family: \'Jameel Noori Nastaleeq Kasheeda\', \'Jameel Noori Nastaleeq\', \'Noto Nastaliq Urdu\', serif !important;\n    font-weight: normal !important;\n    line-height: 1.5 !important;\n}\n[lang=\"ur\"] p, [lang=\"ur\"] li, [lang=\"ur\"] td, [lang=\"ur\"] th, [lang=\"ur\"] span,\n[dir=\"rtl\"] p, [dir=\"rtl\"] li, [dir=\"rtl\"] td, [dir=\"rtl\"] th, [dir=\"rtl\"] span,\n.ashtam-page p, .ashtam-page li, .ashtam-page td, .ashtam-page th,\n.urdu-body p, .clause, .note-box, .amount-box {\n    font-family: \'Jameel Noori Nastaleeq\', \'Noto Nastaliq Urdu\', \'Nafees Nastaleeq\', serif !important;\n    line-height: 1.85 !important;\n}\n@media print {\n    @page { size: auto; margin: 0; }\n    html, body {\n        background: #ffffff !important;\n        color: #000000 !important;\n        margin: 0 !important;\n        padding: 0 !important;\n    }\n    .ashtam-page, .page, .form-container, .container, .letter-preview-print {\n        margin: 0 auto !important;\n        box-shadow: none !important;\n        -webkit-print-color-adjust: exact !important;\n        print-color-adjust: exact !important;\n        color-adjust: exact !important;\n    }\n}\n</style></head>\r\n<body>\r\n<div class=\"container\">\r\n    <div class=\"header\">\r\n        <div class=\"logo-section\">\r\n            <div class=\"logo-placeholder\">{{agency_logo}}</div>\r\n        </div>\r\n        <div class=\"company-details\">\r\n            <h1 class=\"company-name\">{{agency_name}}</h1>\r\n            <p class=\"company-info\">{{agency_address}}</p>\r\n            <p class=\"company-info\">Phone: {{agency_phone}} | E-mail: {{agency_email}}</p>\r\n        </div>\r\n    </div>\r\n    <div class=\"meta-section\">\r\n        <div class=\"meta-col-left\">Ref. No: <strong>{{letter_ref_no}}</strong></div>\r\n        <div class=\"meta-col-right\">Date: <strong>{{letter_date}}</strong></div>\r\n    </div>\r\n    <div class=\"warning-banner\">\r\n        <h2 class=\"warning-title\">Final Deal Cancellation &amp; Revocation Warning</h2>\r\n        <p class=\"warning-subtitle\">Subject: Final Notice for Payment Default, Possible Booking Cancellation &amp; Legal Recovery</p>\r\n    </div>\r\n    <div class=\"client-info\">\r\n        <div class=\"client-title\">Notice Addressee (Defaulter Client)</div>\r\n        <div class=\"client-name\">{{client_name}} S/O {{client_father_name}}</div>\r\n        <div class=\"client-address\">{{client_address}}</div>\r\n        <div style=\"margin-top:2px;font-size:10px;font-weight:bold;color:#000;\">Mobile Number: <span style=\"font-family:&quot;Times New Roman&quot;,Times,serif;font-size:10px;\">{{client_mobile}}</span></div>\r\n    </div>\r\n    <div class=\"letter-body\">\r\n        <p>Dear Sir/Madam,</p>\r\n        <p>We refer to our previous notices and the Payment Demand Letter sent under Ref: <strong>{{letter_ref_no}}</strong>. Despite several administrative grace margins, your payments towards the purchase of your <span class=\"highlight-text\">{{property_type}}</span>, Property/File Code: <span class=\"highlight-text\">{{property_file}}</span>, situated at <span class=\"highlight-text\">{{project_name}}</span>, remain severely delinquent.</p>\r\n        <p>The total agreed consideration for the aforementioned property is <span class=\"highlight-text\">{{deal_total_amount}} ({{deal_total_amount_words}})</span>. You have defaulted on multiple consecutive monthly schedules, accumulating a major outstanding balance.</p>\r\n        <div class=\"table-container\">\r\n            <table class=\"financial-summary\">\r\n                <thead>\r\n                    <tr>\r\n                        <th>Overdue Installment Milestones</th>\r\n                        <th style=\"text-align:center;\">Total Default Count</th>\r\n                        <th style=\"text-align:right;\">Total Outstanding Overdue (PKR)</th>\r\n                    </tr>\r\n                </thead>\r\n                <tbody>\r\n                    <tr>\r\n                        <td style=\"font-weight:500;\">{{overdue_installments_label}}</td>\r\n                        <td style=\"text-align:center;color:#000;font-weight:bold;\">{{overdue_installments_count}} Consecutive Installments</td>\r\n                        <td style=\"text-align:right;color:#000;font-weight:bold;\">{{overdue_amount}}</td>\r\n                    </tr>\r\n                    <tr>\r\n                        <td colspan=\"3\" style=\"font-size:11px;background:#fafbfd;border-top:1px solid #222;color:#111;\">\r\n                            <strong>Amount in Words:</strong> <span style=\"color:#000;font-weight:600;text-transform:capitalize;\">{{overdue_amount_words}}</span>\r\n                        </td>\r\n                    </tr>\r\n                </tbody>\r\n            </table>\r\n        </div>\r\n        <p>Under the signed and agreed Terms &amp; Conditions of booking, failure to pay <strong>{{overdue_installments_count}}</strong> consecutive monthly installments may lead to cancellation of booking/allotment and forfeiture of applicable amounts strictly as per the signed agreement and applicable laws of Pakistan.</p>\r\n        <div class=\"alert-box\">\r\n            <h4>&#128680; Formal Declaration of Possible Legal Action &amp; Allotment Cancellation</h4>\r\n            <p><strong>FINAL REQUISITION:</strong> If the total outstanding overdue amount of <strong>{{overdue_amount}}</strong> is not cleared and credited in full within <strong>{{final_notice_deadline_days}} days</strong> from receipt/dispatch of this notice, the company shall be constrained to proceed for cancellation of your booking/deal/property allotment for <strong>{{property_file}}</strong>, subject to the signed Terms &amp; Conditions and applicable laws of Pakistan.</p>\r\n            <p>Thereafter, {{agency_name}} reserves the right to initiate lawful proceedings for recovery of outstanding dues, damages/costs, cancellation of allotment, recovery/revocation of possession where applicable, correction of company records, and reallocation or sale of the property to another prospective buyer, all at your risk as to cost and consequences.</p>\r\n        </div>\r\n        <div class=\"bank-details-box\">\r\n            <div class=\"bank-title\">Authorized Bank Payment Channels</div>\r\n            <div class=\"bank-line\">\r\n                <span class=\"bank-item\"><strong>Title:</strong> {{bank_account_title}}</span>\r\n                <span class=\"bank-item\"><strong>Bank:</strong> {{bank_name}}</span>\r\n                <span class=\"bank-item\"><strong>A/C:</strong> {{bank_account_no}}</span>\r\n                <span class=\"bank-item\"><strong>IBAN:</strong> {{bank_iban}}</span>\r\n                <span class=\"bank-item\"><strong>Branch:</strong> {{bank_branch}}</span>\r\n            </div>\r\n        </div>\r\n        <div class=\"delivery-note-box\">\r\n            <strong>Proof of Delivery &amp; Legal Service Status</strong>\r\n            This is an officially dispatched <strong>FINAL NOTICE</strong>. It has been transmitted to you through available physical and electronic channels: (1) Hand-delivered/Posted physically to your registered residential home address, (2) Dispatched to your property/possession address where applicable, (3) Electronically delivered to your registered email on record, and (4) Transmitted via WhatsApp messenger notification to your registered telephone line.\r\n            <br><span style=\"font-weight:bold;color:#000;\">This notice shall be treated as duly served through the above available channels, subject to proof of dispatch, delivery record, postal record, electronic record, WhatsApp delivery record, or any other admissible evidence.</span>\r\n        </div>\r\n        <p>You are advised to clear the outstanding amount or contact the office within <strong>{{final_notice_deadline_days}} days</strong> for settlement/reconciliation of account. This notice is issued without prejudice to all rights and remedies available to {{agency_name}} under the booking agreement and applicable laws of Pakistan.</p>\r\n        <p>Yours Sincerely,</p>\r\n    </div>\r\n    <div class=\"signatures-section\">\r\n        <div class=\"signature-block\">\r\n            <div class=\"sig-image-container\">{{ceo_signature}}</div>\r\n            <div class=\"signature-line\"></div>\r\n            <p class=\"signer-title\">Chief Executive Officer</p>\r\n            <p class=\"signer-subtitle\">{{agency_name}}</p>\r\n        </div>\r\n        <div class=\"signature-block\">\r\n            <div class=\"sig-image-container\">{{chairman_signature}}</div>\r\n            <div class=\"signature-line\"></div>\r\n            <p class=\"signer-title\">Chairman of the Board</p>\r\n            <p class=\"signer-subtitle\">{{agency_name}}</p>\r\n        </div>\r\n    </div>\r\n    <div class=\"footer\">\r\n        <strong>{{agency_name}}</strong><br>\r\n        Office Address: {{agency_address}}<br>\r\n        Contact: {{agency_phone}} | Email: {{agency_email}}\r\n    </div>\r\n</div>\r\n</body>\r\n</html>', 'RLT_FINAL_CANCEL', 'Published', 'Yes', '', 'letter_signatures', '', 'letter_signatures');
INSERT INTO `templates` (`id`, `name`, `description`, `type`, `status`, `is_new`, `ceo_signature`, `ceo_signature_dir`, `chairman_signature`, `chairman_signature_dir`) VALUES
(26, 'Final Cancellation Notice', '<!DOCTYPE html>\r\n<html lang=\"en\">\r\n<head>\r\n    <meta charset=\"UTF-8\">\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n    <title>FINAL DEMAND: Deal Cancellation Warning</title>\r\n    <style>\r\n        @page{size:A4;margin:5mm;}\r\n        *{box-sizing:border-box;}\r\n        body{font-family:-apple-system,BlinkMacSystemFont,\"Segoe UI\",Roboto,Helvetica,Arial,sans-serif;color:#222;line-height:1.85;background:#f8fafc;margin:0;padding:12px 8px;-webkit-font-smoothing:antialiased;}\r\n        .container{width:198mm;max-width:100%;margin:0 auto;background:#fff;border:1px solid #e2e8f0;border-top:3px solid #8c1d1d;box-shadow:0 6px 14px rgba(0,0,0,.045);padding:15px 18px;box-sizing:border-box;position:relative;overflow:hidden;}\r\n        .container:before{content:\"FINAL NOTICE\";position:absolute;top:51%;left:50%;transform:translate(-50%,-50%) rotate(-45deg);font-size:62px;font-weight:900;color:rgba(140,29,29,.022);pointer-events:none;z-index:1;white-space:nowrap;letter-spacing:0;}\r\n        .container>*{position:relative;z-index:2;}\r\n        .header{display:table;width:100%;border-bottom:1px solid #d9e1ec;padding-bottom:7px;margin-bottom:7px;}\r\n        .logo-section{display:table-cell;vertical-align:middle;width:72px;}\r\n        .logo-placeholder{width:52px;height:auto;max-height:44px;object-fit:contain;}\r\n        .company-details{display:table-cell;vertical-align:middle;text-align:right;}\r\n        .company-name{font-size:16px;font-weight:800;text-transform:uppercase;color:#8c1d1d;margin:0 0 2px 0;letter-spacing:0;}\r\n        .company-info{font-size:8.8px;color:#555;margin:0;letter-spacing:0;line-height:1.85;}\r\n        .meta-section{display:table;width:100%;margin-bottom:7px;font-size:9.8px;border-bottom:1px dashed #e2e8f0;padding-bottom:4px;}\r\n        .meta-col-left{display:table-cell;text-align:left;color:#555;}\r\n        .meta-col-right{display:table-cell;text-align:right;color:#555;}\r\n        .meta-section strong{color:#222;}\r\n        .warning-banner{background:#fff5f5;border-left:3px solid #8c1d1d;padding:6px 8px;margin-bottom:7px;border-radius:0 2px 2px 0;}\r\n        .warning-title{color:#8c1d1d;font-size:14px;font-weight:800;margin:0 0 1px 0;letter-spacing:0;text-transform:uppercase;}\r\n        .warning-subtitle{font-size:9.2px;font-weight:bold;color:#5c1313;margin:0;letter-spacing:0;text-transform:uppercase;}\r\n        .client-info{background:#fbfcfd;border:1px solid #e2e8f0;border-radius:2px;padding:6px 8px;margin-bottom:7px;font-size:10.2px;}\r\n        .client-title{font-size:8px;text-transform:uppercase;color:#8c1d1d;margin:0 0 2px 0;letter-spacing:0;font-weight:800;}\r\n        .client-name{font-size:11.5px;font-weight:700;color:#000;margin:0 0 1px 0;}\r\n        .client-address{color:#555;line-height:1.85;}\r\n        .letter-body{font-family:Georgia,Cambria,\"Times New Roman\",Times,serif;font-size:10.7px;text-align:justify;color:#2c2c2c;margin-bottom:7px;}\r\n        .letter-body p{margin:0 0 4px 0;line-height:1.85;}\r\n        .highlight-text{font-family:-apple-system,BlinkMacSystemFont,\"Segoe UI\",sans-serif;font-weight:700;color:#000;padding:0 2px;text-decoration:underline;}\r\n        .table-container{margin:5px 0;border:1px solid #e2e8f0;border-radius:2px;overflow:hidden;}\r\n        .financial-summary{width:100%;border-collapse:collapse;font-family:-apple-system,BlinkMacSystemFont,\"Segoe UI\",sans-serif;font-size:9.6px;}\r\n        .financial-summary th{background:#f8fafc;border-bottom:1px solid #d9e1ec;color:#222;padding:4px 5px;text-align:left;font-weight:700;text-transform:uppercase;font-size:8.2px;letter-spacing:0;}\r\n        .financial-summary td{border-bottom:1px solid #e2e8f0;padding:4px 5px;color:#222;}\r\n        .financial-summary tr:last-child td{border-bottom:none;}\r\n        .alert-box{background:#fff5f5;border:1px solid rgba(140,29,29,.2);border-left:3px solid #8c1d1d;border-radius:2px;padding:6px 8px;margin:5px 0;}\r\n        .alert-box h4{color:#8c1d1d;margin:0 0 3px 0;font-size:9.8px;font-weight:800;text-transform:uppercase;letter-spacing:0;font-family:-apple-system,BlinkMacSystemFont,\"Segoe UI\",sans-serif;}\r\n        .alert-box p{margin:0 0 4px 0;font-size:9.8px;line-height:1.85;color:#3f3f3f;}\r\n        .alert-box p:last-child{margin-bottom:0;font-weight:bold;color:#5c1313;}\r\n        .delivery-note-box{background:#f1f5f9;border-left:2px solid #475569;padding:5px 7px;margin:5px 0;font-size:8.8px;color:#334155;line-height:1.85;border-radius:0 2px 2px 0;font-family:-apple-system,BlinkMacSystemFont,\"Segoe UI\",sans-serif;}\r\n        .delivery-note-box strong{color:#1e293b;display:inline;margin-right:5px;text-transform:uppercase;font-size:8.3px;letter-spacing:0;}\r\n        .bank-details-box{background:#fafbfd;border:1px solid #e2e8f0;border-radius:2px;padding:5px 7px;margin:5px 0;font-size:8.9px;font-family:-apple-system,BlinkMacSystemFont,\"Segoe UI\",sans-serif;line-height:1.85;}\r\n        .bank-title{display:inline;font-weight:800;font-size:8.7px;margin:0 7px 0 0;text-transform:uppercase;color:#222;letter-spacing:0;border:0;padding:0;}\r\n        .bank-line{display:inline;color:#333;white-space:nowrap;}\r\n        .bank-item{display:inline;margin-right:8px;white-space:nowrap;}\r\n        .bank-item strong{font-weight:700;color:#555;}\r\n        .signatures-section{display:table;width:100%;margin-top:10px;border-top:1px solid #e2e8f0;padding-top:7px;font-family:-apple-system,BlinkMacSystemFont,\"Segoe UI\",sans-serif;page-break-inside:avoid;}\r\n        .signature-block{display:table-cell;width:50%;text-align:center;vertical-align:bottom;}\r\n        .sig-image-container{height:72px;margin:0 auto 2px;text-align:center;display:flex;align-items:flex-end;justify-content:center;}\r\n        .sig-image{max-height:72px;max-width:270px;display:inline-block;}\r\n        .signature-line{width:190px;border-top:1px solid #222;margin:2px auto 3px;height:1px;}\r\n        .digital-stamp-mock{border:1px dashed #cbd5e1;padding:4px 8px;width:125px;margin:0 auto;color:#94a3b8;font-size:7.5px;font-style:italic;border-radius:2px;text-transform:uppercase;letter-spacing:0;line-height:1.85;}\r\n        .signer-title{font-weight:700;font-size:8.8px;color:#222;margin:0 0 1px 0;text-transform:uppercase;letter-spacing:0;}\r\n        .signer-subtitle{font-size:8px;color:#555;margin:0;letter-spacing:0;}\r\n        .footer{margin-top:7px;border-top:1px solid #8c1d1d;padding-top:4px;text-align:center;font-size:8px;color:#555;font-family:-apple-system,BlinkMacSystemFont,\"Segoe UI\",sans-serif;line-height:1.85;}\r\n        .footer strong{color:#8c1d1d;text-transform:uppercase;letter-spacing:0;}\r\n        @media print{\r\n            html,body{background:#fff;padding:0;margin:0;}\r\n            .container{border:none;box-shadow:none;padding:0;width:100%;max-width:100%;min-height:287mm;margin:0;display:flex;flex-direction:column;}\r\n            body,.container,.container *{color:#000!important;text-shadow:none!important;}\r\n            .container:before{color:rgba(0,0,0,.02);}\r\n            .warning-banner,.alert-box,.delivery-note-box,.financial-summary th{-webkit-print-color-adjust:exact;print-color-adjust:exact;}\r\n            .warning-banner{background:#f8fafc!important;border-left:3px solid #000!important;}\r\n            .alert-box{background:#f8fafc!important;border:1px solid #000!important;}\r\n            .delivery-note-box{background:#f8fafc!important;border-left:2px solid #000!important;}\r\n            .warning-title,.company-name,.signer-title{color:#000!important;}\r\n            .financial-summary th{background:#f1f5f9!important;border-bottom:1px solid #000!important;}\r\n            .letter-body{flex:1;display:flex;flex-direction:column;justify-content:space-between;font-size:11.2px;line-height:1.85;margin-bottom:6mm;}\r\n            .letter-body p{line-height:1.85;margin-bottom:0;}\r\n            .table-container,.alert-box,.bank-details-box,.delivery-note-box{margin:0;}\r\n            .financial-summary{font-size:10px;}\r\n            .financial-summary th{font-size:8.6px;padding:4px 5px;}\r\n            .financial-summary td{padding:4px 5px;}\r\n            .alert-box p{font-size:10.2px;line-height:1.85;margin-bottom:2px;}\r\n            .delivery-note-box{font-size:9.2px;line-height:1.85;}\r\n            .bank-details-box{font-size:9.2px;}\r\n            .signatures-section{page-break-inside:avoid;margin-top:0;}\r\n            .footer{page-break-inside:avoid;}\r\n        }\r\n    </style>\r\n<style type=\"text/css\" id=\"wv-urdu-font-definitions\">\n@font-face {\n    font-family: \'Jameel Noori Nastaleeq\';\n    src: url(\'/whitevillas/fonts/JameelNooriNastaleeq.ttf\') format(\'truetype\'),\n         url(\'/fonts/JameelNooriNastaleeq.ttf\') format(\'truetype\'),\n         url(\'../fonts/JameelNooriNastaleeq.ttf\') format(\'truetype\');\n    font-weight: normal;\n    font-style: normal;\n    font-display: swap;\n}\n@font-face {\n    font-family: \'Jameel Noori Nastaleeq Kasheeda\';\n    src: url(\'/whitevillas/fonts/JameelNooriNastaleeqKasheeda.ttf\') format(\'truetype\'),\n         url(\'/fonts/JameelNooriNastaleeqKasheeda.ttf\') format(\'truetype\'),\n         url(\'../fonts/JameelNooriNastaleeqKasheeda.ttf\') format(\'truetype\');\n    font-weight: normal;\n    font-style: normal;\n    font-display: swap;\n}\n*, *:before, *:after {\n    -webkit-print-color-adjust: exact !important;\n    print-color-adjust: exact !important;\n    color-adjust: exact !important;\n}\n[lang=\"ur\"], [dir=\"rtl\"], .urdu-text, .ashtam-page, .letter-ur, .urdu-body, .urdu-legal {\n    font-family: \'Jameel Noori Nastaleeq\', \'Noto Nastaliq Urdu\', \'Nafees Nastaleeq\', serif !important;\n    line-height: 1.85 !important;\n    letter-spacing: 0 !important;\n    word-spacing: 0 !important;\n}\n[lang=\"ur\"] h1, [lang=\"ur\"] h2, [lang=\"ur\"] h3, [lang=\"ur\"] h4, [lang=\"ur\"] h5, [lang=\"ur\"] h6,\n[dir=\"rtl\"] h1, [dir=\"rtl\"] h2, [dir=\"rtl\"] h3, [dir=\"rtl\"] h4, [dir=\"rtl\"] h5, [dir=\"rtl\"] h6,\n.ashtam-page h1, .ashtam-page h2, .ashtam-page h3, .ashtam-page h4,\n.urdu-heading, .ashtam-heading, .document-title, .document-subtitle, .section-title, .sign-title, .bismillah {\n    font-family: \'Jameel Noori Nastaleeq Kasheeda\', \'Jameel Noori Nastaleeq\', \'Noto Nastaliq Urdu\', serif !important;\n    font-weight: normal !important;\n    line-height: 1.5 !important;\n}\n[lang=\"ur\"] p, [lang=\"ur\"] li, [lang=\"ur\"] td, [lang=\"ur\"] th, [lang=\"ur\"] span,\n[dir=\"rtl\"] p, [dir=\"rtl\"] li, [dir=\"rtl\"] td, [dir=\"rtl\"] th, [dir=\"rtl\"] span,\n.ashtam-page p, .ashtam-page li, .ashtam-page td, .ashtam-page th,\n.urdu-body p, .clause, .note-box, .amount-box {\n    font-family: \'Jameel Noori Nastaleeq\', \'Noto Nastaliq Urdu\', \'Nafees Nastaleeq\', serif !important;\n    line-height: 1.85 !important;\n}\n@media print {\n    @page { size: auto; margin: 0; }\n    html, body {\n        background: #ffffff !important;\n        color: #000000 !important;\n        margin: 0 !important;\n        padding: 0 !important;\n    }\n    .ashtam-page, .page, .form-container, .container, .letter-preview-print {\n        margin: 0 auto !important;\n        box-shadow: none !important;\n        -webkit-print-color-adjust: exact !important;\n        print-color-adjust: exact !important;\n        color-adjust: exact !important;\n    }\n}\n</style></head>\r\n<body>\r\n<div class=\"container\">\r\n    <div class=\"header\">\r\n        <div class=\"logo-section\">\r\n            <div class=\"logo-placeholder\">{{agency_logo}}</div>\r\n        </div>\r\n        <div class=\"company-details\">\r\n            <h1 class=\"company-name\">{{agency_name}}</h1>\r\n            <p class=\"company-info\">{{agency_address}}</p>\r\n            <p class=\"company-info\">Phone: {{agency_phone}} | E-mail: {{agency_email}}</p>\r\n        </div>\r\n    </div>\r\n    <div class=\"meta-section\">\r\n        <div class=\"meta-col-left\">Ref. No: <strong>{{letter_ref_no}}</strong></div>\r\n        <div class=\"meta-col-right\">Date: <strong>{{letter_date}}</strong></div>\r\n    </div>\r\n    <div class=\"warning-banner\">\r\n        <h2 class=\"warning-title\">Final Deal Cancellation &amp; Revocation Warning</h2>\r\n        <p class=\"warning-subtitle\">Subject: Notice of Absolute Forfeiture &amp; Property Reallocation</p>\r\n    </div>\r\n    <div class=\"client-info\">\r\n        <div class=\"client-title\">Notice Addressee (Defaulter Client)</div>\r\n        <div class=\"client-name\">{{client_name}} S/O {{client_father_name}}</div>\r\n        <div class=\"client-address\">{{client_address}}</div>\r\n        <div style=\"margin-top:2px;font-size:10px;font-weight:bold;color:#222;\">Mobile Number: <span style=\"font-family:monospace;font-size:10px;\">{{client_mobile}}</span></div>\r\n    </div>\r\n    <div class=\"letter-body\">\r\n        <p>Dear Sir/Madam,</p>\r\n        <p>We refer to our previous notices and the Payment Demand Letter sent under Ref: <strong>{{letter_ref_no}}</strong>. Despite several administrative grace margins, your payments towards the purchase of your <span class=\"highlight-text\">{{property_type}}</span>, Property/File Code: <span class=\"highlight-text\">{{property_file}}</span>, situated at <span class=\"highlight-text\">{{project_name}}</span>, remain severely delinquent.</p>\r\n        <p>The total agreed consideration for the aforementioned property is <span class=\"highlight-text\">{{deal_total_amount}} ({{deal_total_amount_words}})</span>. You have defaulted on multiple consecutive monthly schedules, accumulating a major outstanding balance.</p>\r\n        <div class=\"table-container\">\r\n            <table class=\"financial-summary\">\r\n                <thead>\r\n                    <tr>\r\n                        <th>Overdue Installment Milestones</th>\r\n                        <th style=\"text-align:center;\">Total Default Count</th>\r\n                        <th style=\"text-align:right;\">Total Outstanding Overdue (PKR)</th>\r\n                    </tr>\r\n                </thead>\r\n                <tbody>\r\n                    <tr>\r\n                        <td style=\"font-weight:500;\">{{overdue_installments_label}}</td>\r\n                        <td style=\"text-align:center;color:#8c1d1d;font-weight:bold;\">{{overdue_installments_count}} Consecutive Installments</td>\r\n                        <td style=\"text-align:right;color:#8c1d1d;font-weight:bold;\">{{overdue_amount}}</td>\r\n                    </tr>\r\n                    <tr>\r\n                        <td colspan=\"3\" style=\"font-size:11px;background:#fafbfd;border-top:1px solid #e2e8f0;color:#555;\">\r\n                            <strong>Amount in Words:</strong> <span style=\"color:#222;font-weight:600;text-transform:capitalize;\">{{overdue_amount_words}}</span>\r\n                        </td>\r\n                    </tr>\r\n                </tbody>\r\n            </table>\r\n        </div>\r\n        <p>Under the signed and agreed Terms &amp; Conditions of booking, failure to pay <strong>{{overdue_installments_count}}</strong> consecutive monthly installments triggers immediate revocation of allotment rights, leading directly to booking termination and the absolute forfeiture of initial deposit milestones.</p>\r\n        <div class=\"alert-box\">\r\n            <h4>&#128680; Formal Declaration of Impending Legal Action &amp; Allotment Revocation</h4>\r\n            <p><strong>FINAL REQUISITION:</strong> If the total outstanding overdue amount of <strong>{{overdue_amount}}</strong> is not cleared and credited in full within <strong>{{final_notice_deadline_days}} days</strong> of this notice, your booking, deal, and property allotment for <strong>{{property_file}}</strong> will stand <strong>permanently cancelled without further recourse.</strong></p>\r\n            <p>Following the cancellation, the company will exercise its complete legal rights to immediately revoke physical possession, purge the register records, and reallocate or sell this property to other prospective buyers on the waiting list. {{agency_name}} shall also initiate recovery litigation to claim any accrued default damages.</p>\r\n        </div>\r\n        <div class=\"bank-details-box\">\r\n            <div class=\"bank-title\">Authorized Bank Payment Channels</div>\r\n            <div class=\"bank-line\">\r\n                <span class=\"bank-item\"><strong>Title:</strong> {{bank_account_title}}</span>\r\n                <span class=\"bank-item\"><strong>Bank:</strong> {{bank_name}}</span>\r\n                <span class=\"bank-item\"><strong>A/C:</strong> {{bank_account_no}}</span>\r\n                <span class=\"bank-item\"><strong>IBAN:</strong> {{bank_iban}}</span>\r\n                <span class=\"bank-item\"><strong>Branch:</strong> {{bank_branch}}</span>\r\n            </div>\r\n        </div>\r\n        <div class=\"delivery-note-box\">\r\n            <strong>Proof of Delivery &amp; Legal Service Status</strong>\r\n            This is an officially dispatched and legally recognized <strong>FINAL NOTICE</strong>. It has been transmitted to you concurrently through multiple verified physical and electronic channels: (1) Hand-delivered/Posted physically to your registered residential home address, (2) Dispatched to your property\'s absolute physical possession address, (3) Electronically delivered to your registered email on record, and (4) Transmitted via WhatsApp messenger notification to your registered telephone line.\r\n            <br><span style=\"font-weight:bold;color:#8c1d1d;\">Delivery is legally deemed active and fully acknowledged upon dispatch. Counter-signature of receipt or returned postal receipt by the defaulting client is not required for this legal notice to take immediate, absolute effect.</span>\r\n        </div>\r\n        <p>We urge you to treat this notification with the highest priority to safeguard your property value and prevent immediate legal termination of your unit booking.</p>\r\n        <p>Yours Sincerely,</p>\r\n    </div>\r\n    <div class=\"signatures-section\">\r\n        <div class=\"signature-block\">\r\n            <div class=\"sig-image-container\">{{ceo_signature}}</div>\r\n            <div class=\"signature-line\"></div>\r\n            <p class=\"signer-title\">Chief Executive Officer</p>\r\n            <p class=\"signer-subtitle\">{{agency_name}}</p>\r\n        </div>\r\n        <div class=\"signature-block\">\r\n            <div class=\"sig-image-container\">{{chairman_signature}}</div>\r\n            <div class=\"signature-line\"></div>\r\n            <p class=\"signer-title\">Chairman of the Board</p>\r\n            <p class=\"signer-subtitle\">{{agency_name}}</p>\r\n        </div>\r\n    </div>\r\n    <div class=\"footer\">\r\n        <strong>{{agency_name}}</strong><br>\r\n        Office Address: {{agency_address}}<br>\r\n        Contact: {{agency_phone}} | Email: {{agency_email}}\r\n    </div>\r\n</div>\r\n</body>\r\n</html>', 'RLT_FINAL_CANCEL', 'Unpublished', 'Yes', '', 'letter_signatures', '', 'letter_signatures'),
(27, 'Deal Agreement Ashtam', '<!DOCTYPE html>\n<html lang=\"ur\" dir=\"rtl\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>معاہدہ بیع / بکنگ / الاٹمنٹ فائل</title>\n    <style>\n        @font-face {\n            font-family: \'Jameel Noori Nastaleeq\';\n            src: url(\'/whitevillas/fonts/JameelNooriNastaleeq.ttf\') format(\'truetype\'),\n                 url(\'/fonts/JameelNooriNastaleeq.ttf\') format(\'truetype\'),\n                 url(\'../fonts/JameelNooriNastaleeq.ttf\') format(\'truetype\');\n            font-weight: normal;\n            font-style: normal;\n            font-display: swap;\n        }\n        @font-face {\n            font-family: \'Jameel Noori Nastaleeq Kasheeda\';\n            src: url(\'/whitevillas/fonts/JameelNooriNastaleeqKasheeda.ttf\') format(\'truetype\'),\n                 url(\'/fonts/JameelNooriNastaleeqKasheeda.ttf\') format(\'truetype\'),\n                 url(\'../fonts/JameelNooriNastaleeqKasheeda.ttf\') format(\'truetype\');\n            font-weight: normal;\n            font-style: normal;\n            font-display: swap;\n        }\n        @page { size: A4; margin: 0; }\n        * { box-sizing: border-box; }\n        body {\n            margin: 0;\n            padding: 0;\n            direction: rtl;\n            unicode-bidi: embed;\n            background: #0f172a;\n            color: #1e293b;\n            font-family: \"Jameel Noori Nastaleeq\", \"Noto Nastaliq Urdu\", \"Nafees Nastaleeq\", serif;\n            font-size: 13.4px;\n            line-height: 1.5;\n            word-spacing: 0;\n            letter-spacing: 0;\n            -webkit-font-smoothing: antialiased;\n        }\n        .page {\n            width: 210mm;\n            min-height: 297mm;\n            margin: 20px auto;\n            padding: 11mm 14mm;\n            background: #fff;\n            border: 1px solid #e2e8f0;\n            box-shadow: 0 10px 25px -5px rgba(0,0,0,.3);\n            position: relative;\n            border-radius: 4px;\n            overflow: visible;\n            display: flex;\n            flex-direction: column;\n        }\n        .watermark {\n            position: absolute;\n            top: 50%;\n            left: 50%;\n            transform: translate(-50%, -50%) rotate(-30deg);\n            font-size: 64px;\n            font-weight: 900;\n            color: rgba(16,185,129,.035);\n            font-family: \"Jameel Noori Nastaleeq Kasheeda\", Arial, sans-serif;\n            pointer-events: none;\n            user-select: none;\n            z-index: 1;\n            white-space: nowrap;\n            border: 7px double rgba(16,185,129,.035);\n            padding: 5px 26px;\n            border-radius: 15px;\n        }\n        .page > *:not(.watermark) { position: relative; z-index: 2; }\n        .letterhead { text-align: center; border-bottom: 2px solid #0f172a; padding-bottom: 7px; margin-bottom: 9px; }\n        .head-row { display: grid; grid-template-columns: 64px minmax(0,1fr) 64px; align-items: center; gap: 10px; }\n        .logo-box { width: 56px; height: 56px; border: 1px solid #0f172a; padding: 3px; display: flex; align-items: center; justify-content: center; overflow: hidden; direction: ltr; }\n        .agency-name { font-size: 22px; font-weight: 900; line-height: 1.2; color: #0f172a; font-family: Arial, Helvetica, sans-serif; text-transform: uppercase; }\n        .agency-sub { font-size: 12px; color: #475569; margin-top: 2px; font-family: \"Jameel Noori Nastaleeq\", serif; }\n        .agency-contact { font-size: 10px; color: #334155; margin-top: 3px; font-family: Arial, Helvetica, sans-serif; direction: ltr; }\n        .document-title {\n            text-align: center;\n            font-family: \"Jameel Noori Nastaleeq Kasheeda\", \"Jameel Noori Nastaleeq\", serif;\n            font-size: 24px;\n            font-weight: 900;\n            text-decoration: underline;\n            text-underline-offset: 6px;\n            margin: 8px 0 2px;\n            color: #0f172a;\n        }\n        .document-subtitle {\n            text-align: center;\n            font-family: \"Jameel Noori Nastaleeq Kasheeda\", \"Jameel Noori Nastaleeq\", serif;\n            font-size: 16px;\n            font-weight: 700;\n            color: #334155;\n            margin-bottom: 9px;\n        }\n        .meta-row {\n            display: flex;\n            justify-content: space-between;\n            align-items: center;\n            font-size: 12.5px;\n            font-weight: 800;\n            color: #1f2937;\n            margin-bottom: 8px;\n            background: #f8fafc;\n            padding: 4px 8px;\n            border: 1px solid #d7e0ea;\n            border-radius: 4px;\n        }\n        p {\n            margin: 0 0 5px;\n            text-align: justify;\n            line-height: 1.55;\n            font-size: 13.6px;\n            word-spacing: 0;\n            letter-spacing: 0;\n        }\n        .section-title {\n            font-family: \"Jameel Noori Nastaleeq Kasheeda\", \"Jameel Noori Nastaleeq\", serif;\n            font-size: 16px;\n            font-weight: 900;\n            text-decoration: underline;\n            text-underline-offset: 4px;\n            margin: 8px 0 4px;\n            color: #0f4c3a;\n            line-height: 1.35;\n            page-break-after: avoid;\n        }\n        .clause { font-size: 13.2px; line-height: 1.5; margin-bottom: 4px; text-align: justify; word-spacing: 0; letter-spacing: 0; }\n        .field { border-bottom: 1px solid #000; padding: 0 3px; font-weight: 900; color: #000; line-height: 1.2; word-spacing: 0; letter-spacing: 0; }\n        .amount-box {\n            border: 1.5px solid #065f46;\n            background: #f9fafb;\n            padding: 6px 12px;\n            margin: 6px 0;\n            text-align: center;\n            font-size: 14.5px;\n            font-weight: 900;\n            line-height: 1.5;\n            border-radius: 6px;\n        }\n        .note-box {\n            border: 1px solid #cbd5e1;\n            border-right: 4px solid #059669;\n            background: #f8fafc;\n            padding: 6px 10px;\n            margin: 5px 0;\n            font-size: 12.8px;\n            line-height: 1.48;\n            text-align: justify;\n            border-radius: 0 6px 6px 0;\n        }\n        .sign-area, .witness-area { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin-top: 10px; }\n        .sign-box { border: 1px solid #d7e0ea; background: #f8fafc; border-radius: 6px; padding: 8px 10px; min-height: 110px; line-height: 1.45; font-size: 12.5px; }\n        .sign-title { font-family: \"Jameel Noori Nastaleeq Kasheeda\", serif; font-weight: 900; color: #0f172a; border-bottom: 1px solid #d7e0ea; padding-bottom: 3px; margin-bottom: 5px; font-size: 13px; }\n        .sign-line { border-bottom: 1px solid #94a3b8; display: block; min-height: 22px; margin-top: 4px; margin-bottom: 4px; }\n        .thumb-box { height: 36px; border: 1px dashed #cbd5e1; background: #fff; border-radius: 4px; margin-top: 5px; display: flex; align-items: center; justify-content: center; font-size: 11px; color: #64748b; }\n        .footer { border-top: 1.5px solid #0f172a; padding-top: 4px; text-align: center; font-size: 9.5px; line-height: 1.25; color: #475569; font-family: Arial, Helvetica, sans-serif; margin-top: auto; }\n        .page-body { padding-bottom: 6mm; flex: 1 1 auto; }\n        @media print {\n            body { background: #fff !important; color: #000 !important; padding: 0 !important; }\n            .page { width: 210mm !important; height: auto !important; min-height: 297mm !important; margin: 0 auto !important; border: none !important; box-shadow: none !important; border-radius: 0 !important; page-break-after: always; page-break-inside: auto; overflow: visible !important; display: flex !important; flex-direction: column !important; }\n            .page:last-of-type { page-break-after: auto; }\n            .field { border-bottom: 1px solid #000 !important; background: transparent !important; color: #000 !important; padding: 0 !important; }\n            .amount-box { border-color: #000 !important; background: transparent !important; }\n            .note-box { border-color: #cbd5e1 !important; border-right-color: #000 !important; background: transparent !important; }\n            .watermark { color: rgba(0,0,0,.02) !important; border-color: rgba(0,0,0,.02) !important; }\n            .footer { color: #000 !important; }\n        }\n    </style>\n</head>\n<body>\n<main class=\"page\">\n    <div class=\"watermark\">{{agency_name}}</div>\n    <header class=\"letterhead\">\n        <div class=\"head-row\">\n            <div class=\"logo-box\">{{agency_logo}}</div>\n            <div>\n                <div class=\"agency-name\">{{agency_name}}</div>\n                <div class=\"agency-sub\">آفیشل سیلز، بکنگ اینڈ مارکیٹنگ ریکارڈ</div>\n            </div>\n            <div></div>\n        </div>\n        <div class=\"agency-contact\">Office: {{agency_address}} | Contact: {{agency_phone}} | Email: {{agency_email}}</div>\n    </header>\n    <div class=\"page-body\">\n        <div class=\"document-title\">معاہدہ بیع / بکنگ / الاٹمنٹ فائل</div>\n        <div class=\"document-subtitle\">پراجیکٹ: {{project_name}}</div>\n        <div class=\"meta-row\">\n            <div>معاہدہ نمبر: <span class=\"field\">{{letter_ref_no}}</span></div>\n            <div>تاریخِ معاہدہ: <span class=\"field\">{{letter_date}}</span></div>\n            <div>دفتری مقام: <span class=\"field\">{{agreement_place}}</span></div>\n        </div>\n        <p>یہ معاہدہ آج مورخہ <span class=\"field\">{{agreement_date_text_urdu}}</span> بروز <span class=\"field\">{{agreement_day_name_urdu}}</span> بمقام <span class=\"field\">{{agreement_place}}</span>، فریق اوّل یعنی <strong>{{agency_name}}</strong>، دفتر واقع <span class=\"field\">{{agency_address}}</span>، بذریعہ مجاز نمائندہ <span class=\"field\">{{agency_representative_name}}</span> ولد <span class=\"field\">{{agency_representative_father}}</span>، شناختی کارڈ نمبر <span class=\"field\">{{agency_representative_cnic}}</span>، عہدہ <span class=\"field\">{{agency_representative_designation}}</span>، جسے آئندہ عبارت میں <strong>فریق اوّل / ایجنسی / پراجیکٹ</strong> کہا جائے گا، اور فریق دوم یعنی کلائنٹ / خریدار <strong>{{client_name}}</strong> ولد / زوجہ <span class=\"field\">{{client_father_name}}</span>، شناختی کارڈ نمبر <span class=\"field\">{{client_cnic}}</span>، موبائل نمبر <span class=\"field\">{{client_mobile}}</span>، ساکن <span class=\"field\">{{client_address}}</span>، جسے آئندہ عبارت میں <strong>فریق دوم / کلائنٹ / خریدار</strong> کہا جائے گا، کے درمیان باہمی رضامندی، آزاد مرضی اور بغیر کسی دباؤ کے تحریر پایا۔</p>\n        <div class=\"section-title\">تمہید</div>\n        <p>چونکہ فریق اوّل ہاؤسنگ پروجیکٹ <strong>{{project_name}}</strong> میں جائیدادوں کی مارکیٹنگ، الاٹمنٹ، ریکارڈ اور متعلقہ تعمیراتی امور کی نگرانی کے جائز قانونی حقوق رکھتا ہے۔ فریق دوم نے اپنی مرضی، ذاتی تسلی، موقع ملاحظہ، سوسائٹی نقشہ، قیمت، سائز، قسط پلان اور شرائط کو تفصیلاً سمجھنے کے بعد درج ذیل جائیداد حاصل کرنے پر آمادگی کا اظہار کیا ہے۔</p>\n        <div class=\"section-title\">پراپرٹی / یونٹ کی تفصیل</div>\n        <p>پراجیکٹ کا نام: <span class=\"field\">{{project_name}}</span>، بلاک / سیکٹر: <span class=\"field\">{{agreement_property_block}}</span>، پراپرٹی قسم: <span class=\"field\">{{property_type}}</span>، یونٹ / ولا / فائل نمبر: <span class=\"field\">{{agreement_property_unit_no}}</span>، منزل / فلور: <span class=\"field\">{{agreement_property_floor}}</span>، سائز / رقبہ: <span class=\"field\">{{property_area}}</span>، کورڈ ایریا: <span class=\"field\">{{agreement_property_covered_area}}</span>، لوکیشن / سٹریٹ: <span class=\"field\">{{agreement_property_location}}</span>۔</p>\n        <div class=\"amount-box\">کل قیمتِ خرید: <span class=\"field\">{{deal_total_amount}}</span> &nbsp; | &nbsp; ڈاؤن پیمنٹ / بیعانہ: <span class=\"field\">{{deal_booking_amount}}</span><br>بقایا رقم: <span class=\"field\">{{deal_balance_amount}}</span> &nbsp; | &nbsp; ادائیگی پلان: <span class=\"field\">{{agreement_payment_plan}}</span></div>\n        <div class=\"section-title\">پراپرٹی کی نوعیت اور مخصوص شرائط</div>\n        {{property_agreement_terms}}\n        <div class=\"section-title\">عمومی ضوابط و شرائطِ معاہدہ</div>\n        <div class=\"clause\"><strong>1. اقساط کی بروقت ادائیگی:</strong> فریق دوم طے شدہ شیڈول کے مطابق اقساط کی ادائیگی کا پابند ہوگا۔ مسلسل 2 اقساط کی عدم ادائیگی پر سوسائٹی قواعد کے مطابق نوٹس جاری کیا جائے گا۔</div>\n        <div class=\"clause\"><strong>2. اضافی و ترقیاتی چارجز:</strong> گورنمنٹ ٹیکسز، یوٹیلیٹی کنکشن فیس، کارنر / پارک فیسنگ اور سوسائٹی رولز کے تحت منظور شدہ ڈیولپمنٹ چارجز علیحدہ لاگو ہوں گے۔</div>\n        <div class=\"clause\"><strong>3. انتقال و الاٹمنٹ حقوق:</strong> کل واجبات کی 100% مکمل ادائیگی اور کلیئرنس کے بعد فریق دوم کے نام باقاعدہ فائنل الاٹمنٹ / پوزیشن جاری کی جائے گی۔</div>\n        <div class=\"clause\"><strong>4. منسوخی و ری فنڈ پالیسی:</strong> اگر فریق دوم خود معاہدہ ختم کرنا چاہے تو منظور شدہ ضوابط و کٹوتی پالیسی کے تحت پروسیس کیا جائے گا۔</div>\n        <div class=\"section-title\">دستخط و تصدیق فریقین</div>\n        <div class=\"sign-area\">\n            <div class=\"sign-box\">\n                <div class=\"sign-title\">دستخط فریق اوّل (مجاز نمائندہ / ایجنسی)</div>\n                <div>نام: {{agency_representative_name}}</div>\n                <span class=\"sign-line\"></span>\n                <div class=\"thumb-box\">مہر و دستخط</div>\n            </div>\n            <div class=\"sign-box\">\n                <div class=\"sign-title\">دستخط فریق دوم (کلائنٹ / خریدار)</div>\n                <div>نام: {{client_name}}</div>\n                <span class=\"sign-line\"></span>\n                <div class=\"thumb-box\">انگوٹھا نشان / دستخط</div>\n            </div>\n        </div>\n        <div class=\"section-title\">گواہانِ معاہدہ</div>\n        <div class=\"witness-area\">\n            <div class=\"sign-box\">\n                <div class=\"sign-title\">گواہ نمبر 1</div>\n                <div>نام: <span class=\"field\">{{witness_one_name}}</span></div>\n                <div>شناختی کارڈ: <span class=\"field\">{{witness_one_cnic}}</span></div>\n                <span class=\"sign-line\"></span>\n            </div>\n            <div class=\"sign-box\">\n                <div class=\"sign-title\">گواہ نمبر 2</div>\n                <div>نام: <span class=\"field\">{{witness_two_name}}</span></div>\n                <div>شناختی کارڈ: <span class=\"field\">{{witness_two_cnic}}</span></div>\n                <span class=\"sign-line\"></span>\n            </div>\n        </div>\n    </div>\n    <footer class=\"footer\">\n        White Villas Real Estate Management &bull; Generated &amp; Verified Official Legal Agreement\n    </footer>\n</main>\n</body>\n</html>', 'RLT_DEAL_AGREEMENT', 'Published', 'No', '', 'letter_signatures', '', 'letter_signatures');
INSERT INTO `templates` (`id`, `name`, `description`, `type`, `status`, `is_new`, `ceo_signature`, `ceo_signature_dir`, `chairman_signature`, `chairman_signature_dir`) VALUES
(28, 'Deal Agreement Ashtam (Standard)', '<!DOCTYPE html>\n<html lang=\"ur\" dir=\"rtl\">\n<head><meta charset=\"UTF-8\"><title>معاہدہ بیع / اشٹام معاہدہ</title><style type=\"text/css\" id=\"wv-ashtam-a4-compact-css\">\n@font-face {\n    font-family: \'Jameel Noori Nastaleeq\';\n    src: url(\'/whitevillas/fonts/JameelNooriNastaleeq.ttf\') format(\'truetype\'),\n         url(\'/fonts/JameelNooriNastaleeq.ttf\') format(\'truetype\'),\n         url(\'../fonts/JameelNooriNastaleeq.ttf\') format(\'truetype\');\n    font-weight: normal;\n    font-style: normal;\n    font-display: swap;\n}\n@font-face {\n    font-family: \'Jameel Noori Nastaleeq Kasheeda\';\n    src: url(\'/whitevillas/fonts/JameelNooriNastaleeqKasheeda.ttf\') format(\'truetype\'),\n         url(\'/fonts/JameelNooriNastaleeqKasheeda.ttf\') format(\'truetype\'),\n         url(\'../fonts/JameelNooriNastaleeqKasheeda.ttf\') format(\'truetype\');\n    font-weight: normal;\n    font-style: normal;\n    font-display: swap;\n}\n\n@page {\n    size: A4 portrait;\n    margin: 0 !important;\n}\n\n*, *:before, *:after {\n    box-sizing: border-box !important;\n    -webkit-print-color-adjust: exact !important;\n    print-color-adjust: exact !important;\n    color-adjust: exact !important;\n}\n\nhtml, body {\n    margin: 0 !important;\n    padding: 0 !important;\n    width: 100% !important;\n    background: #fff;\n    color: #0f172a;\n    direction: rtl;\n    unicode-bidi: embed;\n    font-family: \'Jameel Noori Nastaleeq\', \'Noto Nastaliq Urdu\', serif;\n    -webkit-font-smoothing: antialiased;\n    text-align: center;\n}\n\n.page {\n    width: 196mm !important;\n    max-width: 196mm !important;\n    min-height: 275mm !important;\n    height: auto !important;\n    max-height: none !important;\n    box-sizing: border-box !important;\n    margin: 4mm auto !important;\n    padding: 4mm 8mm 3mm 8mm !important;\n    background: #ffffff !important;\n    border: 1px solid #cbd5e1;\n    box-shadow: 0 4px 14px rgba(0,0,0,0.18);\n    position: relative !important;\n    overflow: visible !important;\n    display: flex !important;\n    flex-direction: column !important;\n    justify-content: space-between !important;\n    page-break-after: always !important;\n    page-break-inside: avoid !important;\n    break-after: page !important;\n    break-inside: avoid !important;\n    text-align: right !important;\n}\n\n.page:last-of-type {\n    page-break-after: auto !important;\n    break-after: auto !important;\n}\n\n.watermark {\n    position: absolute !important;\n    top: 50% !important;\n    left: 50% !important;\n    transform: translate(-50%, -50%) rotate(-30deg) !important;\n    font-size: 52px !important;\n    font-weight: 900 !important;\n    color: rgba(0,0,0,0.025) !important;\n    font-family: Arial, Helvetica, sans-serif !important;\n    pointer-events: none !important;\n    user-select: none !important;\n    z-index: 1 !important;\n    white-space: nowrap !important;\n    border: 4px double rgba(0,0,0,0.025) !important;\n    padding: 4px 18px !important;\n    border-radius: 10px !important;\n}\n\n.page > *:not(.watermark) {\n    position: relative !important;\n    z-index: 2 !important;\n}\n\n.letterhead {\n    text-align: center !important;\n    border-bottom: 1.2px solid #0f172a !important;\n    padding-bottom: 2px !important;\n    margin-bottom: 2px !important;\n    flex: 0 0 auto !important;\n}\n\n.head-row {\n    display: grid !important;\n    grid-template-columns: 38px minmax(0, 1fr) 38px !important;\n    align-items: center !important;\n    gap: 4px !important;\n}\n\n.logo-box {\n    width: 36px !important;\n    height: 36px !important;\n    border: 1px solid #0f172a !important;\n    padding: 1px !important;\n    display: flex !align-items: center !important;\n    justify-content: center !important;\n    overflow: hidden !important;\n}\n\n.logo-box img {\n    max-width: 100% !important;\n    max-height: 100% !important;\n    object-fit: contain !important;\n}\n\n.agency-name {\n    font-size: 14px !important;\n    font-weight: 900 !important;\n    line-height: 1.15 !important;\n    color: #0f172a !important;\n    font-family: Arial, Helvetica, sans-serif !important;\n    text-transform: uppercase !important;\n}\n\n.agency-sub {\n    font-size: 9px !important;\n    color: #475569 !important;\n    margin-top: 1px !important;\n    line-height: 1.15 !important;\n}\n\n.agency-contact {\n    font-size: 7.8px !important;\n    color: #334155 !important;\n    margin-top: 1px !important;\n    font-family: Arial, Helvetica, sans-serif !important;\n    direction: ltr !important;\n}\n\n.document-title {\n    font-family: \'Jameel Noori Nastaleeq Kasheeda\', \'Jameel Noori Nastaleeq\', serif !important;\n    text-align: center !important;\n    font-size: 15px !important;\n    font-weight: 900 !important;\n    text-decoration: underline !important;\n    text-underline-offset: 3px !important;\n    margin: 1px 0 !important;\n    line-height: 1.15 !important;\n    color: #0f172a !important;\n}\n\n.document-subtitle {\n    font-family: \'Jameel Noori Nastaleeq Kasheeda\', \'Jameel Noori Nastaleeq\', serif !important;\n    text-align: center !important;\n    font-size: 11px !important;\n    font-weight: 700 !important;\n    color: #334155 !important;\n    margin-bottom: 2px !important;\n    line-height: 1.15 !important;\n}\n\n.meta-row {\n    display: flex !important;\n    justify-content: space-between !important;\n    align-items: center !important;\n    font-size: 9.8px !important;\n    font-weight: 800 !important;\n    color: #1f2937 !important;\n    margin-bottom: 2px !important;\n    background: #f8fafc !important;\n    padding: 1.5px 5px !important;\n    border: 1px solid #cbd5e1 !important;\n    border-radius: 3px !important;\n    line-height: 1.25 !important;\n}\n\n.page-body {\n    flex: 1 1 auto !important;\n    display: flex !important;\n    flex-direction: column !important;\n    justify-content: flex-start !important;\n    overflow: visible !important;\n}\n\np {\n    margin: 0 0 2px !important;\n    text-align: justify !important;\n    line-height: 1.4 !important;\n    font-size: 11px !important;\n    font-family: \'Jameel Noori Nastaleeq\', \'Noto Nastaliq Urdu\', serif !important;\n}\n\n.section-title {\n    font-family: \'Jameel Noori Nastaleeq Kasheeda\', \'Jameel Noori Nastaleeq\', serif !important;\n    font-size: 12px !important;\n    font-weight: 900 !important;\n    text-decoration: underline !important;\n    text-underline-offset: 2.5px !important;\n    margin: 2.5px 0 1px !important;\n    line-height: 1.15 !important;\n    color: #065f46 !important;\n    page-break-after: avoid !important;\n    break-after: avoid !important;\n}\n\n.clause {\n    font-size: 10.2px !important;\n    line-height: 1.36 !important;\n    margin-bottom: 1.5px !important;\n    text-align: justify !important;\n    font-family: \'Jameel Noori Nastaleeq\', \'Noto Nastaliq Urdu\', serif !important;\n    page-break-inside: avoid !important;\n    break-inside: avoid !important;\n}\n\n.field {\n    border-bottom: 1px solid #000 !important;\n    padding: 0 2px !important;\n    font-weight: 900 !important;\n    color: #000 !important;\n    display: inline !important;\n}\n\n.amount-box {\n    border: 1.2px solid #065f46 !important;\n    background: #f9fafb !important;\n    padding: 3px 6px !important;\n    margin: 2px 0 !important;\n    text-align: center !important;\n    font-size: 11px !important;\n    font-weight: 900 !important;\n    line-height: 1.35 !important;\n    border-radius: 3px !important;\n    page-break-inside: avoid !important;\n    break-inside: avoid !important;\n}\n\n.note-box {\n    border: 1px solid #cbd5e1 !important;\n    border-right: 3.5px solid #059669 !important;\n    background: #f8fafc !important;\n    padding: 2.5px 5px !important;\n    margin: 1.5px 0 !important;\n    font-size: 10px !important;\n    line-height: 1.35 !important;\n    border-radius: 0 3px 3px 0 !important;\n    page-break-inside: avoid !important;\n    break-inside: avoid !important;\n}\n\n.sign-area, .witness-area {\n    display: grid !important;\n    grid-template-columns: 1fr 1fr !important;\n    gap: 4px !important;\n    margin-top: 2px !important;\n    page-break-inside: avoid !important;\n    break-inside: avoid !important;\n}\n\n.sign-box {\n    border: 1px solid #cbd5e1 !important;\n    background: #f8fafc !important;\n    border-radius: 3px !important;\n    padding: 2px 5px !important;\n    min-height: 44px !important;\n    line-height: 1.2 !important;\n    font-size: 9.5px !important;\n    page-break-inside: avoid !important;\n    break-inside: avoid !important;\n}\n\n.sign-title {\n    font-family: \'Jameel Noori Nastaleeq Kasheeda\', \'Jameel Noori Nastaleeq\', serif !important;\n    font-weight: 900 !important;\n    color: #0f172a !important;\n    border-bottom: 1px solid #cbd5e1 !important;\n    padding-bottom: 1px !important;\n    margin-bottom: 1.5px !important;\n    font-size: 9.5px !important;\n    line-height: 1.15 !important;\n}\n\n.sign-line {\n    border-bottom: 1px solid #94a3b8 !important;\n    display: block !important;\n    min-height: 11px !important;\n    margin-top: 1px !important;\n    margin-bottom: 1px !important;\n}\n\n.thumb-box {\n    height: 18px !important;\n    border: 1px dashed #cbd5e1 !important;\n    background: #fff !important;\n    border-radius: 2px !important;\n    margin-top: 1px !important;\n    display: flex !important;\n    align-items: center !important;\n    justify-content: center !important;\n    font-size: 8px !important;\n    color: #64748b !important;\n}\n\n.footer {\n    border-top: 1px solid #0f172a !important;\n    padding-top: 1.5px !important;\n    text-align: center !important;\n    font-size: 7.8px !important;\n    line-height: 1.15 !important;\n    color: #475569 !important;\n    font-family: Arial, Helvetica, sans-serif !important;\n    margin-top: auto !important;\n    flex: 0 0 auto !important;\n}\n\n@media print {\n    html, body {\n        background: #ffffff !important;\n        color: #000000 !important;\n        margin: 0 !important;\n        padding: 0 !important;\n        text-align: center !important;\n    }\n    .page {\n        margin: 4mm auto !important;\n        border: none !important;\n        box-shadow: none !important;\n        text-align: right !important;\n        overflow: visible !important;\n        min-height: 275mm !important;\n        height: auto !important;\n        max-height: none !important;\n    }\n}\n</style></head>\n<body>\n<main class=\"page\">\n    <div class=\"watermark\">{{agency_name}}</div>\n    <header class=\"letterhead\">\n        <div class=\"head-row\">\n            <div class=\"logo-box\">{{agency_logo}}</div>\n            <div>\n                <div class=\"agency-name\">{{agency_name}}</div>\n                <div class=\"agency-sub\">آفیشل سیلز، بکنگ اینڈ مارکیٹنگ ریکارڈ</div>\n            </div>\n            <div></div>\n        </div>\n        <div class=\"agency-contact\">Office: {{agency_address}} | Contact: {{agency_phone}} | Email: {{agency_email}}</div>\n    </header>\n    <div class=\"page-body\">\n        <div class=\"document-title\">معاہدہ بیع / بکنگ / الاٹمنٹ فائل</div>\n        <div class=\"document-subtitle\">پراجیکٹ: {{project_name}}</div>\n        <div class=\"meta-row\">\n            <div>معاہدہ نمبر: <span class=\"field\">{{letter_ref_no}}</span></div>\n            <div>تاریخِ معاہدہ: <span class=\"field\">{{letter_date}}</span></div>\n            <div>دفتری مقام: <span class=\"field\">{{agreement_place}}</span></div>\n        </div>\n        <p>یہ معاہدہ آج مورخہ <span class=\"field\">{{agreement_date_text_urdu}}</span> بروز <span class=\"field\">{{agreement_day_name_urdu}}</span> بمقام <span class=\"field\">{{agreement_place}}</span>، فریق اوّل یعنی <strong>{{agency_name}}</strong>، دفتر واقع <span class=\"field\">{{agency_address}}</span>، بذریعہ مجاز نمائندہ <span class=\"field\">{{agency_representative_name}}</span> ولد <span class=\"field\">{{agency_representative_father}}</span>، شناختی کارڈ نمبر <span class=\"field\">{{agency_representative_cnic}}</span>، عہدہ <span class=\"field\">{{agency_representative_designation}}</span>، جسے آئندہ عبارت میں <strong>فریق اوّل / ایجنسی / پراجیکٹ</strong> کہا جائے گا، اور فریق دوم یعنی کلائنٹ / خریدار <strong>{{client_name}}</strong> ولد / زوجہ <span class=\"field\">{{client_father_name}}</span>، شناختی کارڈ نمبر <span class=\"field\">{{client_cnic}}</span>، موبائل نمبر <span class=\"field\">{{client_mobile}}</span>، ساکن <span class=\"field\">{{client_address}}</span>، جسے آئندہ عبارت میں <strong>فریق دوم / کلائنٹ / خریدار</strong> کہا جائے گا، کے درمیان باہمی رضامندی، آزاد مرضی اور بغیر کسی دباؤ کے تحریر پایا۔</p>\n        <div class=\"section-title\">تمہید</div>\n        <p>چونکہ فریق اوّل ہاؤسنگ پروجیکٹ <strong>{{project_name}}</strong> میں جائیدادوں کی مارکیٹنگ، الاٹمنٹ، ریکارڈ اور متعلقہ تعمیراتی امور کی نگرانی کے جائز قانونی حقوق رکھتا ہے۔ فریق دوم نے اپنی مرضی، ذاتی تسلی، موقع ملاحظہ، سوسائٹی نقشہ، قیمت، سائز، قسط پلان اور شرائط کو تفصیلاً سمجھنے کے بعد درج ذیل جائیداد حاصل کرنے پر آمادگی کا اظہار کیا ہے۔</p>\n        <div class=\"section-title\">پراپرٹی / یونٹ کی تفصیل</div>\n        <p>پراجیکٹ کا نام: <span class=\"field\">{{project_name}}</span>، بلاک / سیکٹر: <span class=\"field\">{{agreement_property_block}}</span>، پراپرٹی قسم: <span class=\"field\">{{property_type}}</span>، یونٹ / ولا / فائل نمبر: <span class=\"field\">{{agreement_property_unit_no}}</span>، منزل / فلور: <span class=\"field\">{{agreement_property_floor}}</span>، سائز / رقبہ: <span class=\"field\">{{property_area}}</span>، کورڈ ایریا: <span class=\"field\">{{agreement_property_covered_area}}</span>، لوکیشن / سٹریٹ: <span class=\"field\">{{agreement_property_location}}</span>۔</p>\n        <div class=\"amount-box\">کل قیمتِ خرید: <span class=\"field\">{{deal_total_amount}}</span> &nbsp; | &nbsp; ڈاؤن پیمنٹ / بیعانہ: <span class=\"field\">{{deal_booking_amount}}</span><br>بقایا رقم: <span class=\"field\">{{deal_balance_amount}}</span> &nbsp; | &nbsp; ادائیگی پلان: <span class=\"field\">{{agreement_payment_plan}}</span></div>\n        <div class=\"section-title\">پراپرٹی کی نوعیت اور مخصوص شرائط</div>\n        {{property_agreement_terms}}\n        <div class=\"section-title\">عمومی ضوابط و شرائطِ معاہدہ</div>\n        <div class=\"clause\"><strong>1. اقساط کی بروقت ادائیگی:</strong> فریق دوم طے شدہ شیڈول کے مطابق اقساط کی ادائیگی کا پابند ہوگا۔ مسلسل 2 اقساط کی عدم ادائیگی پر سوسائٹی قواعد کے مطابق نوٹس جاری کیا جائے گا۔</div>\n        <div class=\"clause\"><strong>2. اضافی و ترقیاقی چارجز:</strong> گورنمنٹ ٹیکسز، یوٹیلیٹی کنکشن فیس، کارنر / پارک فیسنگ اور سوسائٹی رولز کے تحت منظور شدہ ڈیولپمنٹ چارجز علیحدہ لاگو ہوں گے۔</div>\n        <div class=\"clause\"><strong>3. انتقال و الاٹمنٹ حقوق:</strong> کل واجبات کی 100% مکمل ادائیگی اور کلیئرنس کے بعد فریق دوم کے نام باقاعدہ فائنل الاٹمنٹ / پوزیشن جاری کی جائے گی۔</div>\n        <div class=\"clause\"><strong>4. منسوخی و ری فنڈ پالیسی:</strong> اگر فریق دوم خود معاہدہ ختم کرنا چاہے تو منظور شدہ ضوابط و کٹوتی پالیسی کے تحت پروسیس کیا جائے گا۔</div>\n        <div class=\"section-title\">دستخط و تصدیق فریقین</div>\n        <div class=\"sign-area\">\n            <div class=\"sign-box\">\n                <div class=\"sign-title\">دستخط فریق اوّل (مجاز نمائندہ / ایجنسی)</div>\n                <div>نام: {{agency_representative_name}}</div>\n                <span class=\"sign-line\"></span>\n                <div class=\"thumb-box\">مہر و دستخط</div>\n            </div>\n            <div class=\"sign-box\">\n                <div class=\"sign-title\">دستخط فریق دوم (کلائنٹ / خریدار)</div>\n                <div>نام: {{client_name}}</div>\n                <span class=\"sign-line\"></span>\n                <div class=\"thumb-box\">انگوٹھا نشان / دستخط</div>\n            </div>\n        </div>\n        <div class=\"section-title\">گواہانِ معاہدہ</div>\n        <div class=\"witness-area\">\n            <div class=\"sign-box\">\n                <div class=\"sign-title\">گواہ نمبر 1</div>\n                <div>نام: <span class=\"field\">{{witness_one_name}}</span></div>\n                <div>شناختی کارڈ: <span class=\"field\">{{witness_one_cnic}}</span></div>\n                <span class=\"sign-line\"></span>\n            </div>\n            <div class=\"sign-box\">\n                <div class=\"sign-title\">گواہ نمبر 2</div>\n                <div>نام: <span class=\"field\">{{witness_two_name}}</span></div>\n                <div>شناختی کارڈ: <span class=\"field\">{{witness_two_cnic}}</span></div>\n                <span class=\"sign-line\"></span>\n            </div>\n        </div>\n    </div>\n    <footer class=\"footer\">\n        White Villas Real Estate Management &bull; Generated &amp; Verified Official Legal Agreement\n    </footer>\n</main>\n</body>\n</html>', 'RLT_DEAL_AGREEMENT', 'Unpublished', 'Yes', '', 'letter_signatures', '', 'letter_signatures');
INSERT INTO `templates` (`id`, `name`, `description`, `type`, `status`, `is_new`, `ceo_signature`, `ceo_signature_dir`, `chairman_signature`, `chairman_signature_dir`) VALUES
(29, 'Booking Letter - Premium Booking Form', '<!DOCTYPE html>\r\n<html lang=\"en\">\r\n<head>\r\n    <meta charset=\"UTF-8\">\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n    <title>{{agency_name}} Booking Form</title>\r\n    \r\n    <!-- Tailwind CSS -->\r\n    <script src=\"https://cdn.tailwindcss.com\"></script>\r\n    \r\n    <!-- Urdu Font Support -->\r\n    <link href=\"https://fonts.googleapis.com/css2?family=Noto+Nastaliq+Urdu:wght@400..700&display=swap\" rel=\"stylesheet\">\r\n    \r\n    <style>\r\n        .form-container {\r\n            max-width: 800px; \r\n            font-family: \'Times New Roman\', serif; \r\n            margin: 4px auto; \r\n            background-color: white;\r\n            padding: 1.25rem; \r\n            border-radius: 0.5rem;\r\n            box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1);\r\n            color: #1f2937;\r\n            \r\n            /* Custom double-line repeating floral frame border pattern matching image_1acdb4.png */\r\n            border: 24px solid transparent;\r\n            border-image-source: url(\"data:image/svg+xml;charset=utf-8,%3Csvg xmlns=\'http://www.w3.org/2000/svg\' width=\'72\' height=\'72\' viewBox=\'0 0 72 72\'%3E%3Cdefs%3E%3Cg id=\'flower\'%3E%3Ccircle cx=\'12\' cy=\'12\' r=\'3.5\' fill=\'%23064e3b\'/%3E%3Cpath d=\'M12,12 C10,9 10,4 12,4 C14,4 14,9 12,12 Z\' fill=\'%23064e3b\'/%3E%3Cpath d=\'M12,12 C10,15 10,20 12,20 C14,20 14,15 12,12 Z\' fill=\'%23064e3b\'/%3E%3Cpath d=\'M12,12 C9,10 4,10 4,12 C4,14 9,14 12,12 Z\' fill=\'%23064e3b\'/%3E%3Cpath d=\'M12,12 C15,10 20,10 20,12 C20,14 15,14 12,12 Z\' fill=\'%23064e3b\'/%3E%3Cpath d=\'M12,12 C10,11 6.5,7.5 7.5,6.5 C8.5,5.5 11,10 12,12 Z\' fill=\'%23064e3b\'/%3E%3Cpath d=\'M12,12 C11,10 14.5,6.5 15.5,7.5 C16.5,8.5 12,11 12,12 Z\' fill=\'%23064e3b\'/%3E%3Cpath d=\'M12,12 C11,14 7.5,15.5 6.5,14.5 C5.5,13.5 10,11 12,12 Z\' fill=\'%23064e3b\'/%3E%3Cpath d=\'M12,12 C13,14 16.5,14.5 15.5,15.5 C14.5,16.5 11,13 12,12 Z\' fill=\'%23064e3b\'/%3E%3C/g%3E%3C/defs%3E%3Cpath d=\'M24,2 L2,2 L2,24\' fill=\'none\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cpath d=\'M24,22 L22,22 L22,24\' fill=\'none\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cuse href=\'%23flower\' x=\'0\' y=\'0\'/%3E%3Cline x1=\'24\' y1=\'2\' x2=\'48\' y2=\'2\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cline x1=\'24\' y1=\'22\' x2=\'48\' y2=\'22\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cuse href=\'%23flower\' x=\'24\' y=\'0\'/%3E%3Cpath d=\'M48,2 L70,2 L70,24\' fill=\'none\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cpath d=\'M48,22 L50,22 L50,24\' fill=\'none\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cuse href=\'%23flower\' x=\'48\' y=\'0\'/%3E%3Cline x1=\'2\' y1=\'24\' x2=\'2\' y2=\'48\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cline x1=\'22\' y1=\'24\' x2=\'22\' y2=\'48\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cuse href=\'%23flower\' x=\'0\' y=\'24\'/%3E%3Cline x1=\'70\' y1=\'24\' x2=\'70\' y2=\'48\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cline x1=\'50\' y1=\'24\' x2=\'50\' y2=\'48\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cuse href=\'%23flower\' x=\'48\' y=\'24\'/%3E%3Cpath d=\'M2,48 L2,70 L24,70\' fill=\'none\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cpath d=\'M22,48 L22,50 L24,50\' fill=\'none\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cuse href=\'%23flower\' x=\'0\' y=\'48\'/%3E%3Cline x1=\'24\' y1=\'50\' x2=\'48\' y2=\'50\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cline x1=\'24\' y1=\'70\' x2=\'48\' y2=\'70\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cuse href=\'%23flower\' x=\'24\' y=\'48\'/%3E%3Cpath d=\'M70,48 L70,70 L48,70\' fill=\'none\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cpath d=\'M50,48 L50,50 L48,50\' fill=\'none\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cuse href=\'%23flower\' x=\'48\' y=\'48\'/%3E%3C/svg%3E\");\r\n            border-image-slice: 24;\r\n            border-image-repeat: repeat;\r\n            \r\n            position: relative;\r\n            overflow: hidden;\r\n        }\r\n        \r\n        /* Centered Background Watermark style */\r\n        .watermark {\r\n            position: absolute;\r\n            top: 34%;\r\n            left: 50%;\r\n            transform: translate(-50%, -50%);\r\n            width: 340px;\r\n            height: 340px;\r\n            opacity: 0.045; /* Behind upper letter text without overpowering content */\r\n            pointer-events: none;\r\n            z-index: 0;\r\n            user-select: none;\r\n        }\r\n\r\n        /* Form content wrapper to stay above watermark */\r\n        .form-content-wrapper {\r\n            position: relative;\r\n            z-index: 10;\r\n        }\r\n\r\n        /* Standard view: Restricted to the exact length of heading text with background preserved */\r\n        .form-section-title {\r\n            background-color: #064e3b; /* Premium Forest Green background */\r\n            color: #ffffff; /* Crisp white text */\r\n            font-weight: 700;\r\n            font-size: 0.85rem;\r\n            padding: 0.25rem 0.75rem;\r\n            margin-bottom: 0.5rem;\r\n            border-left: 4px solid #d97706; /* Solid amber gold accent bar */\r\n            border-radius: 0 0.25rem 0.25rem 0;\r\n            letter-spacing: 0.05em;\r\n            display: inline-block; /* Fits exactly to text length, removing empty spacing */\r\n        }\r\n        \r\n        /* Premium layered fields - background made fully transparent to show underlying blueprint pattern */\r\n        .input-line {\r\n            border-bottom: 1px solid #9ca3af;\r\n            padding-left: 0.5rem;\r\n            flex-grow: 1;\r\n            min-height: 1.1rem;\r\n            color: #111827;\r\n            background-color: transparent; /* Made fully transparent to show structural background pattern */\r\n        }\r\n        .input-group {\r\n            display: flex;\r\n            align-items: center;\r\n            margin-bottom: 0.35rem;\r\n            font-size: 0.825rem;\r\n        }\r\n        \r\n        /* Enhanced section box with an elegant, ultra-subtle architectural/isometric real estate blueprint pattern */\r\n        .section-box {\r\n            border: 1px solid #d1fae5; /* Very subtle light emerald borders */\r\n            border-radius: 0.375rem;\r\n            padding: 0.45rem;\r\n            margin-bottom: 0.75rem;\r\n            /* Semi-transparent background color lets the centered watermark slide underneath */\r\n            background-color: rgba(250, 253, 251, 0.85); \r\n            background-image: \r\n                linear-gradient(30deg, rgba(6, 78, 59, 0.01) 12%, transparent 12.5%, transparent 87%, rgba(6, 78, 59, 0.01) 87.5%, rgba(6, 78, 59, 0.01)),\r\n                linear-gradient(150deg, rgba(6, 78, 59, 0.01) 12%, transparent 12.5%, transparent 87%, rgba(6, 78, 59, 0.01) 87.5%, rgba(6, 78, 59, 0.01)),\r\n                linear-gradient(30deg, rgba(6, 78, 59, 0.01) 12%, transparent 12.5%, transparent 87%, rgba(6, 78, 59, 0.01) 87.5%, rgba(6, 78, 59, 0.01)),\r\n                linear-gradient(150deg, rgba(6, 78, 59, 0.01) 12%, transparent 12.5%, transparent 87%, rgba(6, 78, 59, 0.01) 87.5%, rgba(6, 78, 59, 0.01)),\r\n                linear-gradient(60deg, rgba(6, 78, 59, 0.008) 25%, transparent 25.5%, transparent 75%, rgba(6, 78, 59, 0.008) 75.5%, rgba(6, 78, 59, 0.008)),\r\n                linear-gradient(60deg, rgba(6, 78, 59, 0.008) 25%, transparent 25.5%, transparent 75%, rgba(6, 78, 59, 0.008) 75.5%, rgba(6, 78, 59, 0.008));\r\n            background-size: 24px 41.5px;\r\n            background-position: 0 0, 0 0, 12px 20.75px, 12px 20.75px, 0 0, 12px 20.75px;\r\n        }\r\n        \r\n        .note-placeholder-text {\r\n            font-size: 16px; \r\n            font-weight: 700;\r\n            color: rgba(6, 78, 59, 0.18); /* Elegant brand-aligned opacity watermarking */\r\n            margin-top: 0.25rem;\r\n        }\r\n        .validation-note {\r\n            font-size: 0.7rem;\r\n            font-weight: 600;\r\n            color: #b45309; /* Warm gold/amber warnings */\r\n            background-color: #fffbeb; /* Soft amber highlight */\r\n            padding: 0.35rem;\r\n            border: 1px solid #fde68a;\r\n            border-radius: 0.25rem;\r\n            margin-bottom: 0.35rem;\r\n            line-height: 1.85; \r\n            text-align: center;\r\n        }\r\n        .urdu-nastaliq {\r\n            font-family: \'Noto Nastaliq Urdu\', \'Times New Roman\', serif;\r\n            direction: rtl;\r\n        }\r\n\r\n        /* Anti-Copy / Anti-Scan Microprint Rule: Too fine to scan clearly */\r\n        .microprint-security-line {\r\n            font-size: 4.5px;\r\n            color: rgba(6, 78, 59, 0.4);\r\n            letter-spacing: 0.04em;\r\n            line-height: 1;\r\n            text-transform: uppercase;\r\n            user-select: none;\r\n        }\r\n\r\n        /* --- PRINT STYLING & COLOR PRESERVATION --- */\r\n        @media print {\r\n            @page {\r\n                size: legal portrait;\r\n                margin: 0;\r\n            }\r\n            html, body {\r\n                width: 8.5in !important;\r\n                min-height: 14in !important;\r\n                margin: 0 !important;\r\n                padding: 0 !important;\r\n                background: #ffffff !important;\r\n            }\r\n            body {\r\n                display: block !important;\r\n                overflow: visible !important;\r\n            }\r\n            /* Crucial directive: Forces browser to preserve backgrounds, borders, blueprints and watermarks in color prints */\r\n            * {\r\n                -webkit-print-color-adjust: exact !important;\r\n                print-color-adjust: exact !important;\r\n            }\r\n            .form-container {\r\n                max-width: none !important;\r\n                width: 8.5in !important;\r\n                min-height: auto !important;\r\n                box-sizing: border-box !important;\r\n                margin: 0 !important;\r\n                border-radius: 0 !important;\r\n                box-shadow: none;\r\n                border: 24px solid transparent !important;\r\n                border-image-source: url(\"data:image/svg+xml;charset=utf-8,%3Csvg xmlns=\'http://www.w3.org/2000/svg\' width=\'72\' height=\'72\' viewBox=\'0 0 72 72\'%3E%3Cdefs%3E%3Cg id=\'flower\'%3E%3Ccircle cx=\'12\' cy=\'12\' r=\'3.5\' fill=\'%23064e3b\'/%3E%3Cpath d=\'M12,12 C10,9 10,4 12,4 C14,4 14,9 12,12 Z\' fill=\'%23064e3b\'/%3E%3Cpath d=\'M12,12 C10,15 10,20 12,20 C14,20 14,15 12,12 Z\' fill=\'%23064e3b\'/%3E%3Cpath d=\'M12,12 C9,10 4,10 4,12 C4,14 9,14 12,12 Z\' fill=\'%23064e3b\'/%3E%3Cpath d=\'M12,12 C15,10 20,10 20,12 C20,14 15,14 12,12 Z\' fill=\'%23064e3b\'/%3E%3Cpath d=\'M12,12 C10,11 6.5,7.5 7.5,6.5 C8.5,5.5 11,10 12,12 Z\' fill=\'%23064e3b\'/%3E%3Cpath d=\'M12,12 C11,10 14.5,6.5 15.5,7.5 C16.5,8.5 12,11 12,12 Z\' fill=\'%23064e3b\'/%3E%3Cpath d=\'M12,12 C11,14 7.5,15.5 6.5,14.5 C5.5,13.5 10,11 12,12 Z\' fill=\'%23064e3b\'/%3E%3Cpath d=\'M12,12 C13,14 16.5,14.5 15.5,15.5 C14.5,16.5 11,13 12,12 Z\' fill=\'%23064e3b\'/%3E%3C/g%3E%3C/defs%3E%3Cpath d=\'M24,2 L2,2 L2,24\' fill=\'none\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cpath d=\'M24,22 L22,22 L22,24\' fill=\'none\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cuse href=\'%23flower\' x=\'0\' y=\'0\'/%3E%3Cline x1=\'24\' y1=\'2\' x2=\'48\' y2=\'2\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cline x1=\'24\' y1=\'22\' x2=\'48\' y2=\'22\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cuse href=\'%23flower\' x=\'24\' y=\'0\'/%3E%3Cpath d=\'M48,2 L70,2 L70,24\' fill=\'none\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cpath d=\'M48,22 L50,22 L50,24\' fill=\'none\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cuse href=\'%23flower\' x=\'48\' y=\'0\'/%3E%3Cline x1=\'2\' y1=\'24\' x2=\'2\' y2=\'48\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cline x1=\'22\' y1=\'24\' x2=\'22\' y2=\'48\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cuse href=\'%23flower\' x=\'0\' y=\'24\'/%3E%3Cline x1=\'70\' y1=\'24\' x2=\'70\' y2=\'48\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cline x1=\'50\' y1=\'24\' x2=\'50\' y2=\'48\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cuse href=\'%23flower\' x=\'48\' y=\'24\'/%3E%3Cpath d=\'M2,48 L2,70 L24,70\' fill=\'none\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cpath d=\'M22,48 L22,50 L24,50\' fill=\'none\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cuse href=\'%23flower\' x=\'0\' y=\'48\'/%3E%3Cline x1=\'24\' y1=\'50\' x2=\'48\' y2=\'50\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cline x1=\'24\' y1=\'70\' x2=\'48\' y2=\'70\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cuse href=\'%23flower\' x=\'24\' y=\'48\'/%3E%3Cpath d=\'M70,48 L70,70 L48,70\' fill=\'none\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cpath d=\'M50,48 L50,50 L48,50\' fill=\'none\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cuse href=\'%23flower\' x=\'48\' y=\'48\'/%3E%3C/svg%3E\") !important;\r\n                border-image-slice: 24 !important;\r\n                border-image-repeat: repeat !important;\r\n                padding: 0.5rem;\r\n                margin: 0;\r\n            }\r\n            .text-blue-600 { \r\n                color: #064e3b !important; \r\n            }\r\n            .text-red-600 {\r\n                color: #dc2626 !important;\r\n            }\r\n            .form-section-title {\r\n                background-color: #064e3b !important; /* Preserves green background when printing */\r\n                color: #ffffff !important; /* Preserves white text color when printing */\r\n                border-left: 4px solid #d97706 !important; /* Preserves left gold border */\r\n                display: inline-block !important; /* Keep inline layout wrapper when printing */\r\n            }\r\n            .section-box {\r\n                border: 1px solid #d1fae5 !important;\r\n                background-color: rgba(250, 253, 251, 0.85) !important;\r\n                background-image: \r\n                    linear-gradient(30deg, rgba(6, 78, 59, 0.01) 12%, transparent 12.5%, transparent 87%, rgba(6, 78, 59, 0.01) 87.5%, rgba(6, 78, 59, 0.01)),\r\n                    linear-gradient(150deg, rgba(6, 78, 59, 0.01) 12%, transparent 12.5%, transparent 87%, rgba(6, 78, 59, 0.01) 87.5%, rgba(6, 78, 59, 0.01)),\r\n                    linear-gradient(30deg, rgba(6, 78, 59, 0.01) 12%, transparent 12.5%, transparent 87%, rgba(6, 78, 59, 0.01) 87.5%, rgba(6, 78, 59, 0.01)),\r\n                    linear-gradient(150deg, rgba(6, 78, 59, 0.01) 12%, transparent 12.5%, transparent 87%, rgba(6, 78, 59, 0.01) 87.5%, rgba(6, 78, 59, 0.01)),\r\n                    linear-gradient(60deg, rgba(6, 78, 59, 0.008) 25%, transparent 25.5%, transparent 75%, rgba(6, 78, 59, 0.008) 75.5%, rgba(6, 78, 59, 0.008)),\r\n                    linear-gradient(60deg, rgba(6, 78, 59, 0.008) 25%, transparent 25.5%, transparent 75%, rgba(6, 78, 59, 0.008) 75.5%, rgba(6, 78, 59, 0.008)) !important;\r\n                background-size: 24px 41.5px !important;\r\n                background-position: 0 0, 0 0, 12px 20.75px, 12px 20.75px, 0 0, 12px 20.75px !important;\r\n            }\r\n            .input-line {\r\n                background-color: transparent !important; /* Preserves transparency on print outputs */\r\n            }\r\n            .validation-note {\r\n                background-color: #fffbeb !important;\r\n                border: 1px solid #fde68a !important;\r\n                color: #b45309 !important;\r\n            }\r\n            .booking-header-banner {\r\n                background-color: #064e3b !important;\r\n            }\r\n            .booking-header-text {\r\n                color: #fbbf24 !important;\r\n            }\r\n            .watermark {\r\n                opacity: 0.04 !important; /* Retain visible watermark on print output */\r\n            }\r\n        }\r\n    </style>\r\n<style type=\"text/css\" id=\"wv-urdu-font-definitions\">\n@font-face {\n    font-family: \'Jameel Noori Nastaleeq\';\n    src: url(\'/whitevillas/fonts/JameelNooriNastaleeq.ttf\') format(\'truetype\'),\n         url(\'/fonts/JameelNooriNastaleeq.ttf\') format(\'truetype\'),\n         url(\'../fonts/JameelNooriNastaleeq.ttf\') format(\'truetype\');\n    font-weight: normal;\n    font-style: normal;\n    font-display: swap;\n}\n@font-face {\n    font-family: \'Jameel Noori Nastaleeq Kasheeda\';\n    src: url(\'/whitevillas/fonts/JameelNooriNastaleeqKasheeda.ttf\') format(\'truetype\'),\n         url(\'/fonts/JameelNooriNastaleeqKasheeda.ttf\') format(\'truetype\'),\n         url(\'../fonts/JameelNooriNastaleeqKasheeda.ttf\') format(\'truetype\');\n    font-weight: normal;\n    font-style: normal;\n    font-display: swap;\n}\n*, *:before, *:after {\n    -webkit-print-color-adjust: exact !important;\n    print-color-adjust: exact !important;\n    color-adjust: exact !important;\n}\n[lang=\"ur\"], [dir=\"rtl\"], .urdu-text, .ashtam-page, .letter-ur, .urdu-body, .urdu-legal {\n    font-family: \'Jameel Noori Nastaleeq\', \'Noto Nastaliq Urdu\', \'Nafees Nastaleeq\', serif !important;\n    line-height: 1.85 !important;\n    letter-spacing: 0 !important;\n    word-spacing: 0 !important;\n}\n[lang=\"ur\"] h1, [lang=\"ur\"] h2, [lang=\"ur\"] h3, [lang=\"ur\"] h4, [lang=\"ur\"] h5, [lang=\"ur\"] h6,\n[dir=\"rtl\"] h1, [dir=\"rtl\"] h2, [dir=\"rtl\"] h3, [dir=\"rtl\"] h4, [dir=\"rtl\"] h5, [dir=\"rtl\"] h6,\n.ashtam-page h1, .ashtam-page h2, .ashtam-page h3, .ashtam-page h4,\n.urdu-heading, .ashtam-heading, .document-title, .document-subtitle, .section-title, .sign-title, .bismillah {\n    font-family: \'Jameel Noori Nastaleeq Kasheeda\', \'Jameel Noori Nastaleeq\', \'Noto Nastaliq Urdu\', serif !important;\n    font-weight: normal !important;\n    line-height: 1.5 !important;\n}\n[lang=\"ur\"] p, [lang=\"ur\"] li, [lang=\"ur\"] td, [lang=\"ur\"] th, [lang=\"ur\"] span,\n[dir=\"rtl\"] p, [dir=\"rtl\"] li, [dir=\"rtl\"] td, [dir=\"rtl\"] th, [dir=\"rtl\"] span,\n.ashtam-page p, .ashtam-page li, .ashtam-page td, .ashtam-page th,\n.urdu-body p, .clause, .note-box, .amount-box {\n    font-family: \'Jameel Noori Nastaleeq\', \'Noto Nastaliq Urdu\', \'Nafees Nastaleeq\', serif !important;\n    line-height: 1.85 !important;\n}\n@media print {\n    @page { size: auto; margin: 0; }\n    html, body {\n        background: #ffffff !important;\n        color: #000000 !important;\n        margin: 0 !important;\n        padding: 0 !important;\n    }\n    .ashtam-page, .page, .form-container, .container, .letter-preview-print {\n        margin: 0 auto !important;\n        box-shadow: none !important;\n        -webkit-print-color-adjust: exact !important;\n        print-color-adjust: exact !important;\n        color-adjust: exact !important;\n    }\n}\n</style></head>\r\n\r\n<body class=\"bg-gray-100 p-2 sm:p-6 flex justify-center\">\r\n\r\n    <div class=\"form-container w-full\">\r\n        \r\n        <!-- Centered Background Watermark -->\r\n        <div class=\"watermark flex items-center justify-center\">\r\n            <img id=\"watermark-logo\" src=\"{{agency_logo_url}}\" \r\n                 alt=\"Watermark Logo\" class=\"w-full h-full object-contain\" onerror=\"handleWatermarkError(this)\">\r\n        </div>\r\n\r\n        <div class=\"form-content-wrapper\">\r\n            <header class=\"mb-3 flex flex-row items-center justify-between pb-3 relative overflow-hidden rounded-lg p-3 bg-emerald-50/10 border border-emerald-100/30\">\r\n                <!-- Panoramic Pakistani Monuments SVG Watermark Background (Covering the entire header from left to right) -->\r\n                <div class=\"absolute inset-0 pointer-events-none opacity-[0.06] z-0 select-none flex items-end\">\r\n                    <svg class=\"w-full h-full\" viewBox=\"0 0 1000 120\" preserveAspectRatio=\"none\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\">\r\n                        <!-- Horizontal baseline connector -->\r\n                        <line x1=\"0\" y1=\"120\" x2=\"1000\" y2=\"120\" stroke=\"#064e3b\" stroke-width=\"2\" />\r\n                        \r\n                        <!-- 1. Minar-e-Pakistan (x: 15 to 75) -->\r\n                        <path d=\"M15,120 L25,108 L28,108 L31,105 L31,100 L34,100 L35,80 L32,80 L32,77 L38,77 L39,55 L35,55 L35,52 L41,52 L43,20 C43,15 47,15 47,20 L49,52 L55,52 L55,55 L51,55 L52,77 L58,77 L58,80 L55,80 L56,100 L59,100 L59,105 L62,108 L65,108 L75,120 Z\" fill=\"#064e3b\" />\r\n                        \r\n                        <!-- 2. Khyber Gate (x: 100 to 200) -->\r\n                        <path d=\"M100,120 L100,60 L112,60 L112,50 L108,50 L108,45 L124,45 L124,50 L120,50 L120,60 L135,60 L135,75 Q145,62 155,75 L155,120 L147,120 L147,85 Q145,76 138,85 L138,120 L130,120 L130,70 L125,70 L125,120 Z\" fill=\"#064e3b\" />\r\n                        <path d=\"M155,120 L155,75 Q165,62 175,75 L175,60 L190,60 L190,50 L186,50 L186,45 L202,45 L202,50 L198,50 L198,60 L210,60 L210,120 L185,120 L185,70 L180,70 L180,120 Z\" fill=\"#064e3b\" />\r\n                        \r\n                        <!-- 3. Badshahi Mosque & Minarets (x: 220 to 450) -->\r\n                        <!-- Minaret Left -->\r\n                        <path d=\"M220,120 L220,30 L216,30 L211,30 L211,25 L219,25 L220,15 C220,10 226,10 226,15 L227,25 L235,25 L235,30 L231,30 L231,120 Z\" fill=\"#064e3b\" />\r\n                        <!-- Left Dome -->\r\n                        <path d=\"M255,120 L255,90 Q280,65 305,90 L305,120 Z\" fill=\"#064e3b\" />\r\n                        <!-- Central Grand Dome -->\r\n                        <path d=\"M310,120 L310,85 C310,50 360,50 360,85 L360,120 Z\" fill=\"#064e3b\" />\r\n                        <!-- Right Dome -->\r\n                        <path d=\"M365,120 L365,90 Q390,65 415,90 L415,120 Z\" fill=\"#064e3b\" />\r\n                        <!-- Minaret Right -->\r\n                        <path d=\"M430,120 L430,30 L426,30 L421,30 L421,25 L429,25 L430,15 C430,10 436,10 436,15 L437,25 L445,25 L445,30 L441,30 L441,120 Z\" fill=\"#064e3b\" />\r\n                        \r\n                        <!-- 4. Tomb of Shah Rukn-e-Alam (x: 475 to 570) -->\r\n                        <path d=\"M480,120 L485,85 L500,85 L505,65 L525,65 L527,50 C527,45 533,45 533,50 L535,65 L555,65 L560,85 L575,85 L580,120 Z\" fill=\"#064e3b\" />\r\n                        \r\n                        <!-- 5. Mazar-e-Quaid (Karachi) (x: 600 to 680) -->\r\n                        <!-- Base tapering walls -->\r\n                        <path d=\"M600,120 L615,70 L675,70 L690,120 Z\" fill=\"#064e3b\" />\r\n                        <!-- Hemisphere Dome -->\r\n                        <path d=\"M622,70 C622,45 668,45 668,70 Z\" fill=\"#064e3b\" />\r\n                        <!-- Arch Doorway -->\r\n                        <path d=\"M635,120 L635,95 C635,85 655,85 655,95 L655,120 Z\" fill=\"#ffffff\" opacity=\"0.6\" />\r\n                        \r\n                        <!-- 6. Pakistan Monument (x: 710 to 810) -->\r\n                        <!-- Petal Left 1 -->\r\n                        <path d=\"M710,120 C710,95 725,80 740,85 C730,102 720,112 717,120 Z\" fill=\"#064e3b\" />\r\n                        <!-- Petal Left 2 -->\r\n                        <path d=\"M725,120 C730,75 755,60 767,70 C755,92 743,110 740,120 Z\" fill=\"#064e3b\" />\r\n                        <!-- Center Crescent Star Orb -->\r\n                        <circle cx=\"765\" cy=\"100\" r=\"6\" fill=\"#064e3b\" />\r\n                        <!-- Petal Right 2 -->\r\n                        <path d=\"M800,120 C795,75 770,60 758,70 C770,92 782,110 785,120 Z\" fill=\"#064e3b\" />\r\n                        <!-- Petal Right 1 -->\r\n                        <path d=\"M815,120 C815,95 800,80 785,85 C795,102 805,112 808,120 Z\" fill=\"#064e3b\" />\r\n                        \r\n                        <!-- 7. Faisal Mosque (x: 840 to 980) -->\r\n                        <!-- Left Minaret -->\r\n                        <path d=\"M845,120 L845,15 L848,15 L848,120 Z\" fill=\"#064e3b\" />\r\n                        <!-- Center tent building -->\r\n                        <path d=\"M860,120 L910,55 L960,120 Z\" fill=\"#064e3b\" />\r\n                        <!-- Top crescent spire -->\r\n                        <line x1=\"910\" y1=\"55\" x2=\"910\" y2=\"45\" stroke=\"#064e3b\" stroke-width=\"2\" />\r\n                        <!-- Right Minaret -->\r\n                        <path d=\"M975,120 L975,15 L978,15 L978,120 Z\" fill=\"#064e3b\" />\r\n                        <!-- Internal Structural lines -->\r\n                        <line x1=\"885\" y1=\"120\" x2=\"910\" y2=\"55\" stroke=\"#ffffff\" stroke-width=\"1.5\" opacity=\"0.3\" />\r\n                        <line x1=\"935\" y1=\"120\" x2=\"910\" y2=\"55\" stroke=\"#ffffff\" stroke-width=\"1.5\" opacity=\"0.3\" />\r\n                    </svg>\r\n                </div>\r\n\r\n                <!-- Left side wrapper (w-28 width mirrors right photo box wrapper to guarantee perfect centering of text) -->\r\n                <div class=\"w-28 flex-shrink-0 flex items-center justify-start z-10 relative\">\r\n                    <!-- Sized Logo Box (w-28 h-28) with fully transparent background -->\r\n                    <div class=\"w-28 h-28 flex-shrink-0 flex items-center justify-center bg-transparent\">\r\n                        <!-- Direct high-contrast inline SVG base fallback avoids escaping issues -->\r\n                        <img id=\"agency-logo\" src=\"{{agency_logo_url}}\" \r\n                             alt=\"Agency Logo\" class=\"w-full h-full object-contain p-1.5\" onerror=\"handleLogoError(this)\">\r\n                    </div>\r\n                </div>\r\n\r\n                <!-- Center Header Texts: Perfectly centralized with increased, prominent font sizes -->\r\n                <div class=\"flex-1 flex flex-col items-center justify-center text-center px-4 z-10 relative\">\r\n                    <!-- Inline-block guarantees the elegant gold underline matches the exact width of the name text -->\r\n                    <h1 class=\"text-3xl sm:text-4xl font-black tracking-wide text-emerald-950 border-b-2 border-amber-500/40 pb-1 leading-tight inline-block\">{{agency_name}}</h1> \r\n                    <p class=\"text-sm font-medium text-gray-700 mt-1.5 max-w-md\">{{agency_address}}</p>\r\n\r\n                    <div class=\"text-xs font-semibold text-gray-600 mt-2 gap-x-4 flex flex-wrap justify-center\">\r\n                        <div>\r\n                            <span class=\"font-extrabold text-emerald-800\">Email:</span> \r\n                            <span>{{agency_email}}</span>\r\n                        </div>\r\n                        <div>\r\n                            <span class=\"font-extrabold text-emerald-800\">Mobile:</span> \r\n                            <span>{{agency_phone}}</span>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n                \r\n                <!-- Right side wrapper: Matches width of Left wrapper (w-28) to force true physical centering -->\r\n                <div class=\"w-28 flex-shrink-0 flex items-center justify-end z-10 relative\">\r\n                    <div class=\"w-24 h-32 border border-emerald-600/20 flex items-center justify-center text-emerald-700/60 text-[10px] bg-emerald-50/20 overflow-hidden rounded shadow-sm\">\r\n                        <img id=\"client-photo\" src=\"{{client_profile_photo_url}}\" alt=\"Applicant Photo\" class=\"w-full h-full object-cover\" onerror=\"handlePhotoError(this)\">\r\n                    </div>\r\n                </div>\r\n            </header>\r\n\r\n            <!-- ID and Property Name -->\r\n            <div class=\"flex justify-between items-center text-xs font-extrabold mb-4 pb-1 border-b border-emerald-100\">\r\n                <div class=\"ml-1\">\r\n                    <span class=\"text-emerald-700 font-extrabold\">Property Name:</span> \r\n                    <span class=\"text-emerald-600 ml-1 font-bold\">{{property_name}}</span>\r\n                </div>\r\n                \r\n                <div>\r\n                    <span class=\"text-emerald-700 font-extrabold\">ID. No:</span> \r\n                    <span class=\"text-gray-800 ml-1 font-bold\">{{deal_invoice_no}}</span>\r\n                </div>\r\n            </div>\r\n            \r\n            <!-- Elegant Colorized Header Banner for BOOKING FORM -->\r\n            <div class=\"booking-header-banner bg-emerald-900 text-white py-1.5 px-4 rounded-lg text-center mb-4 shadow-sm\">\r\n                <h2 class=\"booking-header-text text-lg font-black uppercase tracking-widest text-amber-400\">BOOKING FORM</h2>\r\n            </div>\r\n\r\n            <!-- Personal Information -->\r\n            <div class=\"section-box\">\r\n                <div class=\"form-section-title\">PERSONAL INFORMATION</div>\r\n                <div class=\"space-y-2 p-1\">\r\n                    <div class=\"input-group\">\r\n                        <label class=\"w-40 flex-shrink-0 font-bold text-emerald-950\">Name of Applicant:</label>\r\n                        <div class=\"input-line\">{{client_name_with_father}}</div>\r\n                    </div>\r\n                    \r\n                    <!-- CNIC & E-mail in the same line (Replaces CNIC & Passport line) -->\r\n                    <div class=\"grid grid-cols-2 gap-x-3\">\r\n                        <div class=\"input-group\">\r\n                            <label class=\"w-40 flex-shrink-0 font-bold text-emerald-950\">CNIC:</label>\r\n                            <div class=\"input-line\">{{client_cnic}}</div>\r\n                        </div>\r\n                        <div class=\"input-group\">\r\n                            <label class=\"w-16 flex-shrink-0 font-bold text-emerald-950\">E-mail:</label>\r\n                            <div class=\"input-line\">{{client_email}}</div>\r\n                        </div>\r\n                    </div>\r\n\r\n                    <div class=\"input-group\">\r\n                        <label class=\"w-40 flex-shrink-0 font-bold text-emerald-950\">Mailing Address Current:</label>\r\n                        <div class=\"input-line\">{{client_address}}</div>\r\n                    </div>\r\n\r\n                    <!-- Occupation, Office Phone, and Mobile in the same line -->\r\n                    <div class=\"grid grid-cols-3 gap-x-3\">\r\n                        <div class=\"input-group\">\r\n                            <label class=\"w-20 flex-shrink-0 font-bold text-emerald-950\">Occupation:</label>\r\n                            <div class=\"input-line\">{{deal_occupation}}</div>\r\n                        </div>\r\n                        <div class=\"input-group\">\r\n                            <label class=\"w-20 flex-shrink-0 font-bold text-emerald-950\">Office Phone:</label>\r\n                            <div class=\"input-line\">{{client_phone}}</div>\r\n                        </div>\r\n                        <div class=\"input-group\">\r\n                            <label class=\"w-14 flex-shrink-0 font-bold text-emerald-950\">Mobile:</label>\r\n                            <div class=\"input-line font-bold text-emerald-900\">{{client_mobile}}</div>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n            <!-- Nominee Information -->\r\n            <div class=\"section-box\">\r\n                <div class=\"form-section-title\">NOMINEE INFORMATION</div>\r\n                <div class=\"space-y-2 p-1\">\r\n                    <div class=\"grid grid-cols-12 gap-x-3\">\r\n                        <div class=\"col-span-8 input-group\">\r\n                            <label class=\"flex-shrink-0 font-bold text-emerald-950\">Nominee Name:</label>\r\n                            <div class=\"input-line ml-1\">{{nominee_name}}</div>\r\n                        </div>\r\n                        <div class=\"col-span-4 input-group justify-end\">\r\n                            <label class=\"flex-shrink-0 font-bold text-emerald-950\">CNIC:</label>\r\n                            <div class=\"input-line ml-1 max-w-[170px] text-center\">{{nominee_cnic}}</div>\r\n                        </div>\r\n                    </div>\r\n                    <div class=\"grid grid-cols-2 gap-x-3\">\r\n                        <div class=\"input-group\">\r\n                            <label class=\"flex-shrink-0 font-bold text-emerald-950\">Cell:</label>\r\n                            <div class=\"input-line ml-1\">{{nominee_mobile}}</div>\r\n                        </div>\r\n                        <div class=\"input-group\">\r\n                            <label class=\"flex-shrink-0 font-bold text-emerald-950\">Relation with Client:</label>\r\n                            <div class=\"input-line ml-1\">{{nominee_relation}}</div>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n            <!-- Property Details - Re-ordered Category before Block -->\r\n            <div class=\"section-box\">\r\n                <div class=\"form-section-title\">PROPERTY & REGISTRATION DETAILS</div>\r\n                <div class=\"grid grid-cols-10 gap-3 p-1\">\r\n                    <div class=\"col-span-4 space-y-3 flex flex-col justify-center\"> \r\n                        <div class=\"input-group\">\r\n                            <label class=\"w-16 flex-shrink-0 font-bold text-emerald-950\">File No:</label>\r\n                            <div class=\"input-line\">{{property_file}}</div>\r\n                        </div>\r\n                        <div class=\"input-group\">\r\n                            <label class=\"w-16 flex-shrink-0 font-bold text-emerald-950\">Size:</label>\r\n                            <div class=\"input-line\">{{property_area}}</div>\r\n                        </div>\r\n                        <!-- Category moved before Block -->\r\n                        <div class=\"input-group\">\r\n                            <label class=\"w-16 flex-shrink-0 font-bold text-emerald-950\">Category:</label>\r\n                            <div class=\"input-line font-bold text-emerald-800\">{{property_type}}</div>\r\n                        </div>\r\n                        <div class=\"input-group\">\r\n                            <label class=\"w-16 flex-shrink-0 font-bold text-emerald-950\">Block:</label>\r\n                            <div class=\"input-line\">{{ballot_block_name}}</div>\r\n                        </div>\r\n                    </div>\r\n\r\n                    <!-- Note Pasting Area - Added \"Currency Note #:\" label before property_name -->\r\n                    <div class=\"col-span-6 flex justify-center items-stretch p-1 pt-0\"> \r\n                        <div class=\"w-full h-44 border border-dashed border-emerald-400 p-3 text-center bg-emerald-50/10 rounded-lg flex flex-col justify-between\">\r\n                            <p class=\"validation-note urdu-nastaliq\">\r\n                                <span class=\"font-extrabold\">اہم نوٹ:</span> اگر نوٹ منسلک نہ ہو تو یہ فائل قابلِ قبول نہیں ہوگی۔\r\n                            </p>\r\n                            <div class=\"note-placeholder-text\">\r\n                                <span class=\"text-xs uppercase tracking-wider text-emerald-900/40 block font-bold mb-0.5\">Currency Note #:</span>\r\n                                <span>{{property_name}}</span>\r\n                            </div>\r\n                            <div class=\"border-b border-dashed border-emerald-300 w-3/4 mx-auto my-0.5\"></div>\r\n                            <div>\r\n                                <p class=\"text-[10px] text-gray-500 urdu-nastaliq leading-none\">(کرنسی نوٹ منسلک کرنے کی جگہ)</p>\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n            <!-- Payment Details with Auto Translation targets & Dynamic Security Badges -->\r\n            <div class=\"section-box relative overflow-hidden\">\r\n                <!-- Golden Hologram Seal Background (Faded Watermark) on Left to authenticate booking slip -->\r\n                <div class=\"absolute right-2 bottom-1 w-16 h-16 pointer-events-none opacity-20 print:opacity-40\">\r\n                    <svg viewBox=\"0 0 100 100\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\">\r\n                        <circle cx=\"50\" cy=\"50\" r=\"45\" stroke=\"#d97706\" stroke-width=\"2\" stroke-dasharray=\"2 2\" />\r\n                        <path d=\"M50,15 L62,40 L90,40 L68,55 L78,80 L50,65 L22,80 L32,55 L10,40 L38,40 Z\" fill=\"#d97706\" opacity=\"0.8\" />\r\n                        <text x=\"50\" y=\"53\" text-anchor=\"middle\" font-size=\"8\" font-weight=\"900\" fill=\"#064e3b\" font-family=\"sans-serif\">ORIGINAL</text>\r\n                    </svg>\r\n                </div>\r\n\r\n                <div class=\"form-section-title\">PAYMENT DETAILS</div>\r\n                <div class=\"space-y-2 p-1 relative z-10\">\r\n                    <!-- Row 1: Receipt/PO and Payment Method -->\r\n                    <div class=\"grid grid-cols-2 gap-x-3\">\r\n                        <div class=\"input-group\">\r\n                            <label class=\"w-28 flex-shrink-0 font-bold text-emerald-950\">Receipt/PO #:</label>\r\n                            <div id=\"receipt-po-line\" class=\"input-line\">{{deal_booking_receipt_no}}</div>\r\n                        </div>\r\n                        <div class=\"input-group\">\r\n                            <label class=\"w-28 flex-shrink-0 font-bold text-emerald-950\">Payment Method:</label>\r\n                            <div id=\"payment-method-line\" class=\"input-line\">{{deal_booking_payment_method}}</div>\r\n                        </div>\r\n                    </div>\r\n                    <!-- Row 2: Amount (PKR) and Amount in Words -->\r\n                    <div class=\"grid grid-cols-12 gap-x-3\">\r\n                        <div class=\"col-span-5 input-group\">\r\n                            <label class=\"w-28 flex-shrink-0 font-bold text-emerald-950\">Amount (PKR):</label>\r\n                            <div id=\"pkr-amount-numeric\" class=\"input-line font-bold text-emerald-900\">{{deal_booking_payment_amount}}</div>\r\n                        </div>\r\n                        <div class=\"col-span-7 input-group\">\r\n                            <label class=\"w-28 flex-shrink-0 font-bold text-emerald-950\">Amount in Words:</label>\r\n                            <div id=\"pkr-amount-words\" class=\"input-line font-medium text-xs text-gray-800 italic\">&nbsp;</div>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n            <!-- Anti-Forgery Microprint Security Line (Placed right above Signatures) -->\r\n            <div class=\"mt-2 mb-1 text-center select-none overflow-hidden h-3 flex items-center justify-center\">\r\n                <span class=\"microprint-security-line truncate w-full\">\r\n                    * SECURE DOCUMENT * ORIGINAL BOOKING COPY * ID: {{deal_invoice_no}} * VERIFY VIA SYSTEM QR CODE * NOT FOR RE-EXCHANGE * VALID STAMPED COPY * SECURE DOCUMENT * ORIGINAL BOOKING COPY * ID: {{deal_invoice_no}} * VERIFY VIA SYSTEM QR CODE * NOT FOR RE-EXCHANGE * VALID STAMPED COPY * SECURE DOCUMENT * ORIGINAL BOOKING COPY * ID: {{deal_invoice_no}} *\r\n                </span>\r\n            </div>\r\n\r\n            <!-- Signatures Section with Client, Manager, Officer and Compact Right-aligned Date details -->\r\n            <footer class=\"text-[10px] relative\">\r\n                <!-- Cryptographic Barcode / QR Section Embedded Symmetrically -->\n                <div class=\"booking-security-row\" style=\"display:flex;align-items:center;justify-content:center;gap:18px;margin:0 auto 8px auto;width:100%;height:auto;clear:both;position:relative;z-index:20;\">\n                    <!-- Dynamic Secure Code-128 Barcode Mockup -->\n                    <div class=\"flex flex-col items-center\" style=\"display:flex;flex-direction:column;align-items:center;justify-content:center;\">\n                        <svg id=\"secure-barcode\" class=\"h-6 w-44\" style=\"height:24px;width:176px;\" viewBox=\"0 0 100 20\" preserveAspectRatio=\"none\">\n                            <!-- Pattern gets populated dynamically via JS from {{deal_invoice_no}} -->\n                        </svg>\n                        <span class=\"text-[7px] text-gray-500 font-mono mt-0.5 tracking-widest\" style=\"font-size:7px;color:#6b7280;font-family:monospace;margin-top:2px;letter-spacing:.08em;\">ID-{{deal_invoice_no}}</span>\n                    </div>\n\n                    <!-- Secure Anti-Tamper Holographic stamp mock -->\n                    <div class=\"w-10 h-10 flex items-center justify-center border border-emerald-900/10 rounded-full bg-gradient-to-tr from-amber-50 to-emerald-50/50 p-0.5 shadow-sm\" style=\"width:40px;height:40px;display:flex;align-items:center;justify-content:center;border:1px solid rgba(6,78,59,.1);border-radius:999px;background:#fffdf0;padding:2px;box-shadow:0 1px 3px rgba(0,0,0,.08);\">\n                        <svg viewBox=\"0 0 100 100\" class=\"w-full h-full text-emerald-800\" style=\"width:100%;height:100%;color:#065f46;\">\n                            <circle cx=\"50\" cy=\"50\" r=\"48\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1\" stroke-dasharray=\"3 3\"/>\n                            <polygon points=\"50,15 58,40 85,40 63,55 73,80 50,65 27,80 37,55 15,40 42,40\" fill=\"currentColor\" opacity=\"0.15\" />\n                            <text x=\"50\" y=\"42\" text-anchor=\"middle\" font-size=\"10\" font-weight=\"900\" fill=\"currentColor\">SECURE</text>\n                            <text x=\"50\" y=\"55\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#d97706\">GOLD</text>\n                            <text x=\"50\" y=\"68\" text-anchor=\"middle\" font-size=\"9\" font-weight=\"900\" fill=\"currentColor\">ORIGINAL</text>\n                        </svg>\n                    </div>\n\n                    <!-- Dynamic Secure QR Verification Block -->\n                    <div class=\"deal-letter-qr-box\" style=\"display:inline-block;border:1px solid #dce3eb;border-radius:4px;background:#fff;padding:4px;box-sizing:border-box;width:calc(1in + 10px);height:calc(1in + 10px);flex:0 0 auto;line-height:1;\">\n                        <img src=\"{{letter_deal_qr_url}}\" alt=\"Deal QR Code\" style=\"display:block;width:1in;height:1in;object-fit:contain;image-rendering:-webkit-optimize-contrast;image-rendering:crisp-edges;\" />\n                    </div>\n                </div>\n\n                \r\n\r\n                <div class=\"grid grid-cols-12 gap-3 text-center border-t border-emerald-200 pt-2\">\r\n                    <!-- Manager Sign -->\r\n                    <div class=\"col-span-3 pt-1\">\r\n                        <div class=\"h-8\"></div>\r\n                        <span class=\"block border-t border-emerald-900/60 mt-0.5 uppercase text-emerald-950 font-bold\">Manager Sign</span>\r\n                    </div>\r\n                    <!-- Booking Officer -->\r\n                    <div class=\"col-span-3 pt-1\">\r\n                        <div class=\"h-8\"></div>\r\n                        <span class=\"block border-t border-emerald-900/60 mt-0.5 uppercase text-emerald-950 font-bold\">Booking Officer</span>\r\n                        <span class=\"block text-gray-600 text-[9px] mt-0.5 font-semibold\">{{agency_representative_name}}</span>\r\n                    </div>\r\n                    <!-- Applicant Sign -->\r\n                    <div class=\"col-span-2 pt-1\">\r\n                        <div class=\"h-8\"></div>\r\n                        <span class=\"block border-t border-emerald-900/60 mt-0.5 uppercase text-emerald-950 font-bold\">Applicant Signature</span>\r\n                        <span class=\"block text-gray-500 text-[9px] mt-0.5 font-semibold\">({{client_name}})</span>\r\n                    </div>\r\n                    <!-- Thumb Impression -->\r\n                    <div class=\"col-span-2 pt-1\">\r\n                        <div class=\"h-8\"></div>\r\n                        <span class=\"block border-t border-emerald-900/60 mt-0.5 uppercase text-emerald-950 font-bold\">Thumb Impression</span>\r\n                    </div>\r\n                    <!-- Date (Decreased Width and Moved Far Right) -->\r\n                    <div class=\"col-span-2 pt-1\">\r\n                        <div class=\"h-8\"></div>\r\n                        <span class=\"block border-t border-emerald-900/60 mt-0.5 uppercase text-emerald-950 font-bold\">Date</span>\r\n                        <span class=\"block text-gray-600 text-[9px] mt-0.5\" id=\"display-date\">{{letter_date}}</span>\r\n                    </div>\r\n                </div>\r\n            </footer>\r\n        </div>\r\n\r\n    </div>\r\n\r\n    <script>\r\n        /**\r\n         * Image Fallback Script Block to prevent unrendered template variables \r\n         * or blocked remote assets from hanging layout rendering.\r\n         */\r\n        function handleLogoError(img) {\r\n            img.onerror = null;\r\n            // High contrast elegant forest green standard URL-encoded vector mockup\r\n            img.src = \"data:image/svg+xml;charset=utf-8,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%20000%2Fsvg%22%20width%3D%22112%22%20height%3D%22112%22%20viewBox%3D%220%200%20112%20112%22%3E%3Crect%20width%3D%22100%25%22%20height%3D%22100%25%22%20fill%3D%22%23064e3b%22%2F%3E%3Ctext%20x%3D%2250%25%22%20y%3D%2250%25%22%20dominant-baseline%3D%22middle%22%20text-anchor%3D%22middle%22%20fill%3D%22%23ffffff%22%20font-family%3D%22sans-serif%22%20font-size%3D%2212%22%20font-weight%3D%22bold%22%3EAGENCY%20LOGO%3C%2Ftext%3E%3C%2Fsvg%3E\";\r\n        }\r\n\r\n        function handlePhotoError(img) {\r\n            img.onerror = null;\r\n            // Premium applicant avatar vector mockup\r\n            img.src = \"data:image/svg+xml;charset=utf-8,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%20000%2Fsvg%22%20width%3D%2296%22%20height%3D%22128%22%20viewBox%3D%220%200%2096%20128%22%3E%3Crect%20width%3D%22100%25%22%20height%3D%22100%25%22%20fill%3D%22%23e2e8f0%22%2F%3E%3Ccircle%20cx%3D%2248%22%20cy%3D%2245%22%20r%3D%2220%22%20fill%3D%22%2394a3b8%22%2F%3E%3Cpath%20d%3D%22M%2012%20110%20C%2012%2085%2C%2084%2085%2C%2084%20110%20Z%22%20fill%3D%22%2394a3b8%22%2F%3E%3Ctext%20x%3D%2250%25%22%20y%3D%2292%25%22%20dominant-baseline%3D%22middle%22%20text-anchor%3D%22middle%22%20fill%3D%22%23475569%22%20font-family%3D%22sans-serif%22%20font-size%3D%2210%22%20font-weight%3D%22bold%22%3EPHOTO%3C%2Ftext%3E%3C%2Fsvg%3E\";\r\n        }\r\n\r\n        function handleWatermarkError(img) {\r\n            img.onerror = null;\r\n            img.style.display = \'none\'; // Fade silently from backdrop\r\n        }\r\n\r\n        /**\r\n         * Dynamic Parser translating numeric strings into formal PKR numbering words.\r\n         */\r\n        function cleanAndParseValue(text) {\r\n            if (!text || text.includes(\'{{\') || text.includes(\'}}\')) {\r\n                return null; // Ignore template placeholders\r\n            }\r\n            const sanitized = text.replace(/[^0-9.]/g, \'\');\r\n            const parsed = parseFloat(sanitized);\r\n            return isNaN(parsed) ? null : Math.floor(parsed);\r\n        }\r\n\r\n        function translatePKRNumberToWords(num) {\r\n            if (num === null || num === 0) return \'\';\r\n            \r\n            const ones = [\'\', \'One\', \'Two\', \'Three\', \'Four\', \'Five\', \'Six\', \'Seven\', \'Eight\', \'Nine\', \'Ten\', \'Eleven\', \'Twelve\', \'Thirteen\', \'Fourteen\', \'Fifteen\', \'Sixteen\', \'Seventeen\', \'Eighteen\', \'Nineteen\'];\r\n            const tens = [\'\', \'\', \'Twenty\', \'Thirty\', \'Forty\', \'Fifty\', \'Sixty\', \'Seventy\', \'Eighty\', \'Ninety\'];\r\n            \r\n            function convertUnderThousand(n) {\r\n                let tempStr = \'\';\r\n                if (n >= 100) {\r\n                    tempStr += ones[Math.floor(n / 100)] + \' Hundred \';\r\n                    n %= 100;\r\n                }\r\n                if (n >= 20) {\r\n                    tempStr += tens[Math.floor(n / 10)] + \' \';\r\n                    n %= 10;\r\n                }\r\n                if (n > 0) {\r\n                    tempStr += ones[n] + \' \';\r\n                }\r\n                return tempStr.trim();\r\n            }\r\n\r\n            let resultWords = \'\';\r\n            \r\n            const crores = Math.floor(num / 10000000);\r\n            num %= 10000000;\r\n            \r\n            const lakhs = Math.floor(num / 100000);\r\n            num %= 100000;\r\n            \r\n            const thousands = Math.floor(num / 1000);\r\n            num %= 1000;\r\n            \r\n            const remaining = num;\r\n            \r\n            if (crores > 0) {\r\n                resultWords += convertUnderThousand(crores) + \' Crore \';\r\n            }\r\n            if (lakhs > 0) {\r\n                resultWords += convertUnderThousand(lakhs) + \' Lakh \';\r\n            }\r\n            if (thousands > 0) {\r\n                resultWords += convertUnderThousand(thousands) + \' Thousand \';\r\n            }\r\n            if (remaining > 0) {\r\n                resultWords += convertUnderThousand(remaining) + \' \';\r\n            }\r\n            \r\n            return resultWords.trim() + \' Rupees Only\';\r\n        }\r\n\r\n        /**\r\n         * Dynamic payment verification block.\r\n         */\r\n        function checkAndConfigurePaymentStatus() {\r\n            const receiptElement = document.getElementById(\'receipt-po-line\');\r\n            const methodElement = document.getElementById(\'payment-method-line\');\r\n\r\n            if (!receiptElement || !methodElement) return;\r\n\r\n            const rawReceipt = receiptElement.textContent.trim();\r\n            const lowerReceipt = rawReceipt.toLowerCase();\r\n\r\n            const isTemplate = rawReceipt.includes(\'{{\') && rawReceipt.includes(\'}}\');\r\n            \r\n            const isUnpaid = \r\n                rawReceipt === \"\" || \r\n                lowerReceipt === \"unpaid\" || \r\n                lowerReceipt === \"un-paid\" || \r\n                lowerReceipt === \"pending\" || \r\n                lowerReceipt === \"n/a\" || \r\n                lowerReceipt === \"none\" ||\r\n                lowerReceipt === \"nil\";\r\n\r\n            if (isUnpaid && !isTemplate) {\r\n                receiptElement.textContent = \"N/A\";\r\n                receiptElement.classList.add(\'text-red-600\', \'font-bold\');\r\n                methodElement.textContent = \"Un-Paid\";\r\n                methodElement.classList.add(\'text-red-600\', \'font-bold\');\r\n            } else if (!isTemplate) {\r\n                methodElement.textContent = \"Paid\";\r\n                methodElement.classList.add(\'text-emerald-800\', \'font-bold\');\r\n                receiptElement.classList.remove(\'text-red-600\');\r\n                methodElement.classList.remove(\'text-red-600\');\r\n            } else {\r\n                methodElement.textContent = \"Paid\";\r\n            }\r\n        }\r\n\r\n        /**\r\n         * Helper parses the unformatted date and returns a \"DD-MMM-YYYY\" string (e.g., 06-Jan-2026)\r\n         */\r\n        function parseAndFormatDate(dateStr) {\r\n            if (!dateStr || dateStr.includes(\'{{\') || dateStr.includes(\'}}\')) {\r\n                return dateStr;\r\n            }\r\n            \r\n            let parsedDate = null;\r\n            \r\n            // Attempt generic parser\r\n            let dateObj = new Date(dateStr);\r\n            if (!isNaN(dateObj.getTime())) {\r\n                parsedDate = dateObj;\r\n            } else {\r\n                // Manually parse common local formats like DD/MM/YYYY or DD-MM-YYYY\r\n                const parts = dateStr.split(/[-/.]/);\r\n                if (parts.length === 3) {\r\n                    let day, month, year;\r\n                    if (parts[2].length === 4) {\r\n                        day = parseInt(parts[0], 10);\r\n                        month = parseInt(parts[1], 10) - 1;\r\n                        year = parseInt(parts[2], 10);\r\n                    } else if (parts[0].length === 4) {\r\n                        year = parseInt(parts[0], 10);\r\n                        month = parseInt(parts[1], 10) - 1;\r\n                        day = parseInt(parts[2], 10);\r\n                    }\r\n                    \r\n                    if (year && !isNaN(month) && month >= 0 && month < 12 && day && day > 0 && day <= 31) {\r\n                        parsedDate = new Date(year, month, day);\r\n                    }\r\n                }\r\n            }\r\n            \r\n            if (parsedDate && !isNaN(parsedDate.getTime())) {\r\n                const months = [\'Jan\', \'Feb\', \'Mar\', \'Apr\', \'May\', \'Jun\', \'Jul\', \'Aug\', \'Sep\', \'Oct\', \'Nov\', \'Dec\'];\r\n                const formattedDay = String(parsedDate.getDate()).padStart(2, \'0\');\r\n                const formattedMonth = months[parsedDate.getMonth()];\r\n                const formattedYear = parsedDate.getFullYear();\r\n                return `${formattedDay}-${formattedMonth}-${formattedYear}`;\r\n            }\r\n            \r\n            return dateStr;\r\n        }\r\n\r\n        /**\r\n         * Generates a unique secure pseudo-barcode for verification matching invoice id\r\n         */\r\n        function generateSecureBarcode() {\r\n            const barcodeSvg = document.getElementById(\'secure-barcode\');\r\n            if (!barcodeSvg) return;\r\n            \r\n            const rawId = \"{{deal_invoice_no}}\".trim();\r\n            const cleanId = rawId.includes(\'{{\') ? \'0100234001920\' : rawId.replace(/[^0-9]/g, \'\');\r\n            \r\n            // Build pseudo Code-128 binary sequence matching invoice sequence safely\r\n            let innerHtml = \'<rect width=\"100\" height=\"20\" fill=\"#ffffff\"/>\';\r\n            let cursor = 5;\r\n            \r\n            // Seed base pseudo-lines\r\n            for (let i = 0; i < 30; i++) {\r\n                // Generate secure alternating pseudo-random bar widths derived mathematically from invoice id\r\n                const charCodeVal = cleanId.charCodeAt(i % cleanId.length) || 103;\r\n                const barWidth = (charCodeVal % 2 === 0) ? 1.5 : 0.6;\r\n                const gapWidth = (charCodeVal % 3 === 0) ? 1.2 : 0.8;\r\n                \r\n                innerHtml += `<rect x=\"${cursor}\" y=\"0\" width=\"${barWidth}\" height=\"20\" fill=\"#111827\"/>`;\r\n                cursor += barWidth + gapWidth;\r\n                if (cursor > 95) break;\r\n            }\r\n            barcodeSvg.innerHTML = innerHtml;\r\n        }\r\n\r\n        function initFormLogic() {\r\n            // PKR Numeric to Words Translation\r\n            const numericElement = document.getElementById(\'pkr-amount-numeric\');\r\n            const wordsTargetElement = document.getElementById(\'pkr-amount-words\');\r\n            \r\n            if (numericElement && wordsTargetElement) {\r\n                const rawContent = numericElement.textContent.trim();\r\n                const processedNum = cleanAndParseValue(rawContent);\r\n                \r\n                if (processedNum !== null && processedNum > 0) {\r\n                    wordsTargetElement.textContent = translatePKRNumberToWords(processedNum);\r\n                } else {\r\n                    wordsTargetElement.innerHTML = \'&nbsp;\';\r\n                }\r\n            }\r\n\r\n            // Payment verification status styling\r\n            checkAndConfigurePaymentStatus();\r\n\r\n            // Auto Date Format initialization\r\n            const dateElement = document.getElementById(\'display-date\');\r\n            if (dateElement) {\r\n                const rawDateStr = dateElement.textContent.trim();\r\n                dateElement.textContent = parseAndFormatDate(rawDateStr);\r\n            }\r\n\r\n            // Generate secure dynamic verification barcode\r\n            generateSecureBarcode();\r\n        }\r\n\r\n        if (document.readyState !== \'loading\') {\r\n            initFormLogic();\r\n        } else {\r\n            document.addEventListener(\'DOMContentLoaded\', initFormLogic);\r\n        }\r\n    </script>\r\n</body>\r\n</html>', 'RLT_BOOKING', 'Published', 'Yes', '', 'letter_signatures', '', 'letter_signatures');
INSERT INTO `templates` (`id`, `name`, `description`, `type`, `status`, `is_new`, `ceo_signature`, `ceo_signature_dir`, `chairman_signature`, `chairman_signature_dir`) VALUES
(32, 'Final Welcome Letter', '<!DOCTYPE html>\r\n<html lang=\"en\">\r\n<head>\r\n    <meta charset=\"UTF-8\">\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n    <title>{{agency_name}} - Welcome Letter</title>\r\n    \r\n    <!-- Tailwind CSS -->\r\n    <script src=\"https://cdn.tailwindcss.com\"></script>\r\n    \r\n    <!-- Urdu Font Support -->\r\n    <link href=\"https://fonts.googleapis.com/css2?family=Noto+Nastaliq+Urdu:wght@400..700&display=swap\" rel=\"stylesheet\">\r\n    \r\n    <style>\r\n        .form-container {\r\n            max-width: 800px; \r\n            font-family: \'Times New Roman\', serif; \r\n            margin: 4px auto; \r\n            background-color: white;\r\n            padding: 1.25rem; \r\n            border-radius: 0.5rem;\r\n            box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1);\r\n            color: #1f2937;\r\n            \r\n            /* Custom double-line repeating floral frame border pattern matching image_1acdb4.png */\r\n            border: 24px solid transparent;\r\n            border-image-source: url(\"data:image/svg+xml;charset=utf-8,%3Csvg xmlns=\'http://www.w3.org/2000/svg\' width=\'72\' height=\'72\' viewBox=\'0 0 72 72\'%3E%3Cdefs%3E%3Cg id=\'flower\'%3E%3Ccircle cx=\'12\' cy=\'12\' r=\'3.5\' fill=\'%23064e3b\'/%3E%3Cpath d=\'M12,12 C10,9 10,4 12,4 C14,4 14,9 12,12 Z\' fill=\'%23064e3b\'/%3E%3Cpath d=\'M12,12 C10,15 10,20 12,20 C14,20 14,15 12,12 Z\' fill=\'%23064e3b\'/%3E%3Cpath d=\'M12,12 C9,10 4,10 4,12 C4,14 9,14 12,12 Z\' fill=\'%23064e3b\'/%3E%3Cpath d=\'M12,12 C15,10 20,10 20,12 C20,14 15,14 12,12 Z\' fill=\'%23064e3b\'/%3E%3Cpath d=\'M12,12 C10,11 6.5,7.5 7.5,6.5 C8.5,5.5 11,10 12,12 Z\' fill=\'%23064e3b\'/%3E%3Cpath d=\'M12,12 C11,10 14.5,6.5 15.5,7.5 C16.5,8.5 12,11 12,12 Z\' fill=\'%23064e3b\'/%3E%3Cpath d=\'M12,12 C11,14 7.5,15.5 6.5,14.5 C5.5,13.5 10,11 12,12 Z\' fill=\'%23064e3b\'/%3E%3Cpath d=\'M12,12 C13,14 16.5,14.5 15.5,15.5 C14.5,16.5 11,13 12,12 Z\' fill=\'%23064e3b\'/%3E%3C/g%3E%3C/defs%3E%3Cpath d=\'M24,2 L2,2 L2,24\' fill=\'none\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cpath d=\'M24,22 L22,22 L22,24\' fill=\'none\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cuse href=\'%23flower\' x=\'0\' y=\'0\'/%3E%3Cline x1=\'24\' y1=\'2\' x2=\'48\' y2=\'2\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cline x1=\'24\' y1=\'22\' x2=\'48\' y2=\'22\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cuse href=\'%23flower\' x=\'24\' y=\'0\'/%3E%3Cpath d=\'M48,2 L70,2 L70,24\' fill=\'none\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cpath d=\'M48,22 L50,22 L50,24\' fill=\'none\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cuse href=\'%23flower\' x=\'48\' y=\'0\'/%3E%3Cline x1=\'2\' y1=\'24\' x2=\'2\' y2=\'48\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cline x1=\'22\' y1=\'24\' x2=\'22\' y2=\'48\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cuse href=\'%23flower\' x=\'0\' y=\'24\'/%3E%3Cline x1=\'70\' y1=\'24\' x2=\'70\' y2=\'48\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cline x1=\'50\' y1=\'24\' x2=\'50\' y2=\'48\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cuse href=\'%23flower\' x=\'48\' y=\'24\'/%3E%3Cpath d=\'M2,48 L2,70 L24,70\' fill=\'none\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cpath d=\'M22,48 L22,50 L24,50\' fill=\'none\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cuse href=\'%23flower\' x=\'0\' y=\'48\'/%3E%3Cline x1=\'24\' y1=\'50\' x2=\'48\' y2=\'50\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cline x1=\'24\' y1=\'70\' x2=\'48\' y2=\'70\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cuse href=\'%23flower\' x=\'24\' y=\'48\'/%3E%3Cpath d=\'M70,48 L70,70 L48,70\' fill=\'none\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cpath d=\'M50,48 L50,50 L48,50\' fill=\'none\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cuse href=\'%23flower\' x=\'48\' y=\'48\'/%3E%3C/svg%3E\");\r\n            border-image-slice: 24;\r\n            border-image-repeat: repeat;\r\n            \r\n            position: relative;\r\n            overflow: hidden;\r\n        }\r\n        \r\n        /* Centered Background Watermark style */\r\n        .watermark {\r\n            position: absolute;\r\n            top: 50%;\r\n            left: 50%;\r\n            transform: translate(-50%, -50%);\r\n            width: 320px;\r\n            height: 320px;\r\n            opacity: 0.04; /* Subtle backdrop presence */\r\n            pointer-events: none;\r\n            z-index: 0;\r\n            user-select: none;\r\n        }\r\n\r\n        /* Form content wrapper to stay above watermark */\r\n        .form-content-wrapper {\r\n            position: relative;\r\n            z-index: 10;\r\n        }\r\n\r\n        .form-section-title {\r\n            background-color: #064e3b; /* Premium Forest Green background */\r\n            color: #ffffff; /* Crisp white text */\r\n            font-weight: 700;\r\n            font-size: 0.85rem;\r\n            padding: 0.25rem 0.75rem;\r\n            margin-bottom: 0.5rem;\r\n            border-left: 4px solid #d97706; /* Solid amber gold accent bar */\r\n            border-radius: 0 0.25rem 0.25rem 0;\r\n            letter-spacing: 0.05em;\r\n            display: inline-block;\r\n        }\r\n        \r\n        .info-label {\r\n            font-weight: 700;\r\n            color: #064e3b;\r\n        }\r\n\r\n        /* --- PRINT STYLING & COLOR PRESERVATION --- */\r\n        @media print {\r\n            @page {\r\n                size: A4 portrait;\r\n                margin: 0;\r\n            }\r\n            body { \r\n                margin: 0; \r\n                padding: 0; \r\n                background: none; \r\n            }\r\n            * {\r\n                -webkit-print-color-adjust: exact !important;\r\n                print-color-adjust: exact !important;\r\n            }\r\n            .form-container {\r\n                max-width: 100%;\r\n                width: 100%;\r\n                box-shadow: none;\r\n                border: 24px solid transparent !important;\r\n                border-image-source: url(\"data:image/svg+xml;charset=utf-8,%3Csvg xmlns=\'http://www.w3.org/2000/svg\' width=\'72\' height=\'72\' viewBox=\'0 0 72 72\'%3E%3Cdefs%3E%3Cg id=\'flower\'%3E%3Ccircle cx=\'12\' cy=\'12\' r=\'3.5\' fill=\'%23064e3b\'/%3E%3Cpath d=\'M12,12 C10,9 10,4 12,4 C14,4 14,9 12,12 Z\' fill=\'%23064e3b\'/%3E%3Cpath d=\'M12,12 C10,15 10,20 12,20 C14,20 14,15 12,12 Z\' fill=\'%23064e3b\'/%3E%3Cpath d=\'M12,12 C9,10 4,10 4,12 C4,14 9,14 12,12 Z\' fill=\'%23064e3b\'/%3E%3Cpath d=\'M12,12 C15,10 20,10 20,12 C20,14 15,14 12,12 Z\' fill=\'%23064e3b\'/%3E%3Cpath d=\'M12,12 C10,11 6.5,7.5 7.5,6.5 C8.5,5.5 11,10 12,12 Z\' fill=\'%23064e3b\'/%3E%3Cpath d=\'M12,12 C11,10 14.5,6.5 15.5,7.5 C16.5,8.5 12,11 12,12 Z\' fill=\'%23064e3b\'/%3E%3Cpath d=\'M12,12 C11,14 7.5,15.5 6.5,14.5 C5.5,13.5 10,11 12,12 Z\' fill=\'%23064e3b\'/%3E%3Cpath d=\'M12,12 C13,14 16.5,14.5 15.5,15.5 C14.5,16.5 11,13 12,12 Z\' fill=\'%23064e3b\'/%3E%3C/g%3E%3C/defs%3E%3Cpath d=\'M24,2 L2,2 L2,24\' fill=\'none\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cpath d=\'M24,22 L22,22 L22,24\' fill=\'none\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cuse href=\'%23flower\' x=\'0\' y=\'0\'/%3E%3Cline x1=\'24\' y1=\'2\' x2=\'48\' y2=\'2\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cline x1=\'24\' y1=\'22\' x2=\'48\' y2=\'22\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cuse href=\'%23flower\' x=\'24\' y=\'0\'/%3E%3Cpath d=\'M48,2 L70,2 L70,24\' fill=\'none\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cpath d=\'M48,22 L50,22 L50,24\' fill=\'none\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cuse href=\'%23flower\' x=\'48\' y=\'0\'/%3E%3Cline x1=\'2\' y1=\'24\' x2=\'2\' y2=\'48\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cline x1=\'22\' y1=\'24\' x2=\'22\' y2=\'48\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cuse href=\'%23flower\' x=\'0\' y=\'24\'/%3E%3Cline x1=\'70\' y1=\'24\' x2=\'70\' y2=\'48\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cline x1=\'50\' y1=\'24\' x2=\'50\' y2=\'48\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cuse href=\'%23flower\' x=\'48\' y=\'24\'/%3E%3Cpath d=\'M2,48 L2,70 L24,70\' fill=\'none\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cpath d=\'M22,48 L22,50 L24,50\' fill=\'none\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cuse href=\'%23flower\' x=\'0\' y=\'48\'/%3E%3Cline x1=\'24\' y1=\'50\' x2=\'48\' y2=\'50\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cline x1=\'24\' y1=\'70\' x2=\'48\' y2=\'70\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cuse href=\'%23flower\' x=\'24\' y=\'48\'/%3E%3Cpath d=\'M70,48 L70,70 L48,70\' fill=\'none\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cpath d=\'M50,48 L50,50 L48,50\' fill=\'none\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cuse href=\'%23flower\' x=\'48\' y=\'48\'/%3E%3C/svg%3E\") !important;\r\n                border-image-slice: 24 !important;\r\n                border-image-repeat: repeat !important;\r\n                padding: 0.5rem;\r\n                margin: 0;\r\n            }\r\n            .form-section-title {\r\n                background-color: #064e3b !important;\r\n                color: #ffffff !important;\r\n                border-left: 4px solid #d97706 !important;\r\n                display: inline-block !important;\r\n            }\r\n            .watermark {\r\n                opacity: 0.04 !important;\r\n            }\r\n        }\r\n    \r\n        /* White Villas compact A4 welcome letter print/PDF fit */ /* wv-welcome-a4-fit-css */\r\n        .wv-welcome-a4{width:210mm!important;max-width:210mm!important;margin:0 auto!important;padding:5mm!important;border-width:12px!important;border-image-slice:24!important;box-shadow:none!important;font-size:12px!important;line-height:1.85!important;}\r\n        .wv-welcome-a4 .watermark{width:220px!important;height:220px!important;}\r\n        .wv-welcome-a4 header{margin-bottom:.35rem!important;padding:.45rem!important;padding-bottom:.45rem!important;}\r\n        .wv-welcome-a4 header .w-28{width:5rem!important;}\r\n        .wv-welcome-a4 header .h-28{height:5rem!important;}\r\n        .wv-welcome-a4 header .w-24{width:4.1rem!important;}\r\n        .wv-welcome-a4 header .h-32{height:5.3rem!important;}\r\n        .wv-welcome-a4 h1{font-size:1.45rem!important;line-height:1.85!important;margin:0!important;}\r\n        .wv-welcome-a4 h2{font-size:.92rem!important;line-height:1.85!important;margin:0!important;}\r\n        .wv-welcome-a4 .text-center.mb-6{margin-bottom:.45rem!important;}\r\n        .wv-welcome-a4 .bg-stone-50\\/50{padding:.55rem!important;margin-bottom:.35rem!important;}\r\n        .wv-welcome-a4 .my-4{margin-top:.35rem!important;margin-bottom:.35rem!important;}\r\n        .wv-welcome-a4 .mb-6{margin-bottom:.45rem!important;}\r\n        .wv-welcome-a4 .mb-4{margin-bottom:.35rem!important;}\r\n        .wv-welcome-a4 .mt-2{margin-top:.25rem!important;}\r\n        .wv-welcome-a4 .mt-1\\.5{margin-top:.2rem!important;}\r\n        .wv-welcome-a4 .p-5{padding:.55rem!important;}\r\n        .wv-welcome-a4 .p-4{padding:.55rem!important;}\r\n        .wv-welcome-a4 .p-3\\.5{padding:.45rem!important;}\r\n        .wv-welcome-a4 .p-3{padding:.4rem!important;}\r\n        .wv-welcome-a4 .p-2\\.5{padding:.35rem!important;}\r\n        .wv-welcome-a4 .px-8{padding-left:1.2rem!important;padding-right:1.2rem!important;}\r\n        .wv-welcome-a4 .py-1\\.5{padding-top:.25rem!important;padding-bottom:.25rem!important;}\r\n        .wv-welcome-a4 .gap-3{gap:.35rem!important;}\r\n        .wv-welcome-a4 .gap-x-6{column-gap:.7rem!important;}\r\n        .wv-welcome-a4 .gap-y-2{row-gap:.25rem!important;}\r\n        .wv-welcome-a4 .space-y-2>:not([hidden])~:not([hidden]){margin-top:.25rem!important;}\r\n        .wv-welcome-a4 .space-y-3>:not([hidden])~:not([hidden]){margin-top:.28rem!important;}\r\n        .wv-welcome-a4 p{margin-top:0!important;margin-bottom:.25rem!important;line-height:1.85!important;}\r\n        .wv-welcome-a4 .text-base{font-size:.82rem!important;line-height:1.85!important;}\r\n        .wv-welcome-a4 .text-sm{font-size:.72rem!important;line-height:1.85!important;}\r\n        .wv-welcome-a4 .text-xs{font-size:.6rem!important;line-height:1.85!important;}\r\n        .wv-welcome-a4 .text-\\[10px\\]{font-size:.52rem!important;line-height:1.85!important;}\r\n        .wv-welcome-a4 .text-\\[9px\\]{font-size:.5rem!important;line-height:1.85!important;}\r\n        .wv-welcome-a4 .text-\\[7\\.5px\\],.wv-welcome-a4 .text-\\[7px\\]{font-size:.42rem!important;line-height:1.85!important;}\r\n        .wv-welcome-a4 footer{margin-top:.35rem!important;padding-bottom:0!important;}\r\n        .wv-welcome-a4 footer .grid{padding-top:.35rem!important;gap:.35rem!important;}\r\n        .wv-welcome-a4 footer .h-16{height:.28in!important;}\r\n        .wv-welcome-a4 footer .mt-6{margin-top:.22rem!important;}\r\n        .wv-welcome-a4 footer .mb-1{margin-bottom:.1rem!important;}\r\n        .wv-welcome-a4 #secure-barcode{height:10px!important;width:118px!important;}\r\n        .wv-welcome-a4 [style*=\"0.75in\"],.wv-welcome-a4 [style*=\"1.25in\"]{width:.75in!important;height:.75in!important;padding:2px!important;}\r\n        .wv-welcome-a4 [style*=\"0.75in\"] img,.wv-welcome-a4 [style*=\"1.25in\"] img{width:100%!important;height:100%!important;filter:contrast(1.45)!important;image-rendering:pixelated!important;}\r\n        @media print{\r\n            @page{size:A4 portrait;margin:0;}\r\n            html,body{width:210mm!important;height:297mm!important;margin:0!important;padding:0!important;background:#fff!important;overflow:hidden!important;}\r\n            .wv-welcome-a4{width:210mm!important;max-width:210mm!important;height:297mm!important;max-height:297mm!important;margin:0!important;padding:5mm!important;border-width:12px!important;border-image-slice:24!important;box-shadow:none!important;overflow:hidden!important;border-image-repeat:repeat!important;}\r\n            .form-section-title{padding:.18rem .5rem!important;margin-bottom:.25rem!important;}\r\n        }\r\n    \r\n        /* Center bank detail values only */ /* wv-bank-center-fix */\r\n        .wv-welcome-a4 .bank-detail-value{display:block!important;flex:1 1 auto!important;text-align:center!important;}\r\n        .wv-welcome-a4 .bank-detail-label{display:block!important;flex:0 0 7.5rem!important;white-space:nowrap!important;}\r\n    \r\n        /* Polished full-page print positioning */ /* wv-welcome-print-polish */\r\n        .wv-welcome-a4 .form-content-wrapper{height:100%!important;min-height:100%!important;display:flex!important;flex-direction:column!important;}\r\n        .wv-welcome-a4 header{flex:0 0 auto!important;}\r\n        .wv-welcome-a4 .form-content-wrapper>div:not(.watermark):not(header):not(footer){flex:0 0 auto!important;}\r\n        .wv-welcome-a4 footer{margin-top:auto!important;padding-top:7mm!important;padding-bottom:1.5mm!important;flex:0 0 auto!important;}\r\n        .wv-welcome-a4 footer .grid{padding-top:3mm!important;align-items:end!important;border-top:1px solid #a7f3d0!important;}\r\n        .wv-welcome-a4 footer .h-16{height:.34in!important;}\r\n        .wv-welcome-a4 footer .border-t{border-top-color:#064e3b!important;}\r\n        .wv-welcome-a4 footer #secure-barcode{margin-top:0!important;}\r\n        .wv-welcome-a4 footer .mt-6{margin-top:.15rem!important;}\r\n        .wv-welcome-a4 footer .mt-0\\.5{margin-top:.08rem!important;}\r\n        .wv-welcome-a4 footer .tracking-widest{letter-spacing:.08em!important;}\r\n        .wv-welcome-a4 .bg-stone-50\\/50{border-color:#d1fae5!important;box-shadow:0 1px 5px rgba(6,78,59,.08)!important;}\r\n        .wv-welcome-a4 .bg-gradient-to-r.from-emerald-900{background:#064e3b!important;}\r\n        .wv-welcome-a4 .bg-gradient-to-r.from-amber-600{background:#c76300!important;}\r\n        .wv-welcome-a4 .bg-white.p-2\\.5{min-height:38px!important;}\r\n        .wv-welcome-a4 .bank-detail-value{white-space:nowrap!important;overflow:hidden!important;text-overflow:ellipsis!important;}\r\n        @media print{\r\n            .wv-welcome-a4 .form-content-wrapper{height:100%!important;min-height:100%!important;display:flex!important;flex-direction:column!important;}\r\n            .wv-welcome-a4 footer{margin-top:auto!important;padding-top:7mm!important;padding-bottom:1.5mm!important;}\r\n        }\r\n    </style>\r\n<style type=\"text/css\" id=\"wv-urdu-font-definitions\">\n@font-face {\n    font-family: \'Jameel Noori Nastaleeq\';\n    src: url(\'/whitevillas/fonts/JameelNooriNastaleeq.ttf\') format(\'truetype\'),\n         url(\'/fonts/JameelNooriNastaleeq.ttf\') format(\'truetype\'),\n         url(\'../fonts/JameelNooriNastaleeq.ttf\') format(\'truetype\');\n    font-weight: normal;\n    font-style: normal;\n    font-display: swap;\n}\n@font-face {\n    font-family: \'Jameel Noori Nastaleeq Kasheeda\';\n    src: url(\'/whitevillas/fonts/JameelNooriNastaleeqKasheeda.ttf\') format(\'truetype\'),\n         url(\'/fonts/JameelNooriNastaleeqKasheeda.ttf\') format(\'truetype\'),\n         url(\'../fonts/JameelNooriNastaleeqKasheeda.ttf\') format(\'truetype\');\n    font-weight: normal;\n    font-style: normal;\n    font-display: swap;\n}\n*, *:before, *:after {\n    -webkit-print-color-adjust: exact !important;\n    print-color-adjust: exact !important;\n    color-adjust: exact !important;\n}\n[lang=\"ur\"], [dir=\"rtl\"], .urdu-text, .ashtam-page, .letter-ur, .urdu-body, .urdu-legal {\n    font-family: \'Jameel Noori Nastaleeq\', \'Noto Nastaliq Urdu\', \'Nafees Nastaleeq\', serif !important;\n    line-height: 1.85 !important;\n    letter-spacing: 0 !important;\n    word-spacing: 0 !important;\n}\n[lang=\"ur\"] h1, [lang=\"ur\"] h2, [lang=\"ur\"] h3, [lang=\"ur\"] h4, [lang=\"ur\"] h5, [lang=\"ur\"] h6,\n[dir=\"rtl\"] h1, [dir=\"rtl\"] h2, [dir=\"rtl\"] h3, [dir=\"rtl\"] h4, [dir=\"rtl\"] h5, [dir=\"rtl\"] h6,\n.ashtam-page h1, .ashtam-page h2, .ashtam-page h3, .ashtam-page h4,\n.urdu-heading, .ashtam-heading, .document-title, .document-subtitle, .section-title, .sign-title, .bismillah {\n    font-family: \'Jameel Noori Nastaleeq Kasheeda\', \'Jameel Noori Nastaleeq\', \'Noto Nastaliq Urdu\', serif !important;\n    font-weight: normal !important;\n    line-height: 1.5 !important;\n}\n[lang=\"ur\"] p, [lang=\"ur\"] li, [lang=\"ur\"] td, [lang=\"ur\"] th, [lang=\"ur\"] span,\n[dir=\"rtl\"] p, [dir=\"rtl\"] li, [dir=\"rtl\"] td, [dir=\"rtl\"] th, [dir=\"rtl\"] span,\n.ashtam-page p, .ashtam-page li, .ashtam-page td, .ashtam-page th,\n.urdu-body p, .clause, .note-box, .amount-box {\n    font-family: \'Jameel Noori Nastaleeq\', \'Noto Nastaliq Urdu\', \'Nafees Nastaleeq\', serif !important;\n    line-height: 1.85 !important;\n}\n@media print {\n    @page { size: auto; margin: 0; }\n    html, body {\n        background: #ffffff !important;\n        color: #000000 !important;\n        margin: 0 !important;\n        padding: 0 !important;\n    }\n    .ashtam-page, .page, .form-container, .container, .letter-preview-print {\n        margin: 0 auto !important;\n        box-shadow: none !important;\n        -webkit-print-color-adjust: exact !important;\n        print-color-adjust: exact !important;\n        color-adjust: exact !important;\n    }\n}\n</style></head>\r\n\r\n<body class=\"bg-gray-100 p-2 sm:p-6 flex justify-center\" style=\"margin:0!important;padding:0!important;background:#fff!important;display:block!important;\">\r\n\r\n    <div class=\"form-container w-full wv-welcome-a4\">\r\n        \r\n        <!-- Centered Background Watermark -->\r\n        <div class=\"watermark flex items-center justify-center\">\r\n            <img id=\"watermark-logo\" src=\"{{agency_logo_url}}\" \r\n                 alt=\"Watermark Logo\" class=\"w-full h-full object-contain\" onerror=\"handleWatermarkError(this)\">\r\n        </div>\r\n\r\n        <div class=\"form-content-wrapper\">\r\n            <header class=\"mb-3 flex flex-row items-center justify-between pb-3 relative overflow-hidden rounded-lg p-3 bg-emerald-50/10 border border-emerald-100/30\">\r\n                <!-- Panoramic Pakistani Monuments SVG Watermark Background -->\r\n                <div class=\"absolute inset-0 pointer-events-none opacity-[0.06] z-0 select-none flex items-end\">\r\n                    <svg class=\"w-full h-full\" viewBox=\"0 0 1000 120\" preserveAspectRatio=\"none\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\">\r\n                        <line x1=\"0\" y1=\"120\" x2=\"1000\" y2=\"120\" stroke=\"#064e3b\" stroke-width=\"2\" />\r\n                        <path d=\"M15,120 L25,108 L28,108 L31,105 L31,100 L34,100 L35,80 L32,80 L32,77 L38,77 L39,55 L35,55 L35,52 L41,52 L43,20 C43,15 47,15 47,20 L49,52 L55,52 L55,55 L51,55 L52,77 L58,77 L58,80 L55,80 L56,100 L59,100 L59,105 L62,108 L65,108 L75,120 Z\" fill=\"#064e3b\" />\r\n                        <path d=\"M100,120 L100,60 L112,60 L112,50 L108,50 L108,45 L124,45 L124,50 L120,50 L120,60 L135,60 L135,75 Q145,62 155,75 L155,120 L147,120 L147,85 Q145,76 138,85 L138,120 L130,120 L130,70 L125,70 L125,120 Z\" fill=\"#064e3b\" />\r\n                        <path d=\"M155,120 L155,75 Q165,62 175,75 L175,60 L190,60 L190,50 L186,50 L186,45 L202,45 L202,50 L198,50 L198,60 L210,60 L210,120 L185,120 L185,70 L180,70 L180,120 Z\" fill=\"#064e3b\" />\r\n                        <path d=\"M220,120 L220,30 L216,30 L211,30 L211,25 L219,25 L220,15 C220,10 226,10 226,15 L227,25 L235,25 L235,30 L231,30 L231,120 Z\" fill=\"#064e3b\" />\r\n                        <path d=\"M255,120 L255,90 Q280,65 305,90 L305,120 Z\" fill=\"#064e3b\" />\r\n                        <path d=\"M310,120 L310,85 C310,50 360,50 360,85 L360,120 Z\" fill=\"#064e3b\" />\r\n                        <path d=\"M365,120 L365,90 Q390,65 415,90 L415,120 Z\" fill=\"#064e3b\" />\r\n                        <path d=\"M430,120 L430,30 L426,30 L421,30 L421,25 L429,25 L430,15 C430,10 436,10 436,15 L437,25 L445,25 L445,30 L441,30 L441,120 Z\" fill=\"#064e3b\" />\r\n                        <path d=\"M480,120 L485,85 L500,85 L505,65 L525,65 L527,50 C527,45 533,45 533,50 L535,65 L555,65 L560,85 L575,85 L580,120 Z\" fill=\"#064e3b\" />\r\n                        <path d=\"M600,120 L615,70 L675,70 L690,120 Z\" fill=\"#064e3b\" />\r\n                        <path d=\"M622,70 C622,45 668,45 668,70 Z\" fill=\"#064e3b\" />\r\n                        <path d=\"M635,120 L635,95 C635,85 655,85 655,95 L655,120 Z\" fill=\"#ffffff\" opacity=\"0.6\" />\r\n                        <path d=\"M710,120 C710,95 725,80 740,85 C730,102 720,112 717,120 Z\" fill=\"#064e3b\" />\r\n                        <path d=\"M725,120 C730,75 755,60 767,70 C755,92 743,110 740,120 Z\" fill=\"#064e3b\" />\r\n                        <circle cx=\"765\" cy=\"100\" r=\"6\" fill=\"#064e3b\" />\r\n                        <path d=\"M800,120 C795,75 770,60 758,70 C770,92 782,110 785,120 Z\" fill=\"#064e3b\" />\r\n                        <path d=\"M815,120 C815,95 800,80 785,85 C795,102 805,112 808,120 Z\" fill=\"#064e3b\" />\r\n                        <path d=\"M845,120 L845,15 L848,15 L848,120 Z\" fill=\"#064e3b\" />\r\n                        <path d=\"M860,120 L910,55 L960,120 Z\" fill=\"#064e3b\" />\r\n                        <line x1=\"910\" y1=\"55\" x2=\"910\" y2=\"45\" stroke=\"#064e3b\" stroke-width=\"2\" />\r\n                        <path d=\"M975,120 L975,15 L978,15 L978,120 Z\" fill=\"#064e3b\" />\r\n                        <line x1=\"885\" y1=\"120\" x2=\"910\" y2=\"55\" stroke=\"#ffffff\" stroke-width=\"1.5\" opacity=\"0.3\" />\r\n                        <line x1=\"935\" y1=\"120\" x2=\"910\" y2=\"55\" stroke=\"#ffffff\" stroke-width=\"1.5\" opacity=\"0.3\" />\r\n                    </svg>\r\n                </div>\r\n\r\n                <!-- Left logo wrapper -->\r\n                <div class=\"w-28 flex-shrink-0 flex items-center justify-start z-10 relative\">\r\n                    <div class=\"w-28 h-28 flex-shrink-0 flex items-center justify-center bg-transparent\">\r\n                        <img id=\"agency-logo\" src=\"{{agency_logo_url}}\" \r\n                             alt=\"Agency Logo\" class=\"w-full h-full object-contain p-1.5\" onerror=\"handleLogoError(this)\">\r\n                    </div>\r\n                </div>\r\n\r\n                <!-- Center Header Texts -->\r\n                <div class=\"flex-1 flex flex-col items-center justify-center text-center px-4 z-10 relative\">\r\n                    <h1 class=\"text-3xl sm:text-4xl font-black tracking-wide text-emerald-950 border-b-2 border-amber-500/40 pb-1 leading-tight inline-block\">{{agency_name}}</h1> \r\n                    <p class=\"text-sm font-medium text-gray-700 mt-1.5 max-w-md\">{{agency_address}}</p>\r\n\r\n                    <div class=\"text-xs font-semibold text-gray-600 mt-2 gap-x-4 flex flex-wrap justify-center\">\r\n                        <div>\r\n                            <span class=\"font-extrabold text-emerald-800\">Email:</span> \r\n                            <span>{{agency_email}}</span>\r\n                        </div>\r\n                        <div>\r\n                            <span class=\"font-extrabold text-emerald-800\">Mobile:</span> \r\n                            <span>{{agency_phone}}</span>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n                \r\n                <!-- Right photo wrapper -->\r\n                <div class=\"w-28 flex-shrink-0 flex items-center justify-end z-10 relative\">\r\n                    <div class=\"w-24 h-32 border-2 border-emerald-800 flex items-center justify-center text-emerald-700/60 text-[10px] bg-emerald-50/20 overflow-hidden rounded shadow-md\">\r\n                        <img id=\"client-photo\" src=\"{{client_profile_photo_url}}\" alt=\"Applicant Photo\" class=\"w-full h-full object-cover\" onerror=\"handlePhotoError(this)\">\r\n                    </div>\r\n                </div>\r\n            </header>\r\n\r\n            <!-- Document Title & Reference ID -->\r\n            <div class=\"flex justify-between items-center text-xs font-extrabold mb-4 pb-1 border-b border-emerald-100\">\r\n                <div>\r\n                    <span class=\"text-emerald-700 font-extrabold\">Reference ID:</span> \r\n                    <span class=\"text-gray-800 ml-1 font-bold\">{{letter_ref_no}}</span>\r\n                </div>\r\n                <div>\r\n                    <span class=\"text-emerald-700 font-extrabold\">Project Name:</span> \r\n                    <span class=\"text-emerald-600 ml-1 font-bold\">{{property_name}}</span>\r\n                </div>\r\n            </div>\r\n\r\n            <!-- Welcome Letter Heading Banner (Centered Stylized Badge) -->\r\n            <div class=\"text-center mb-6\">\r\n                <div class=\"inline-block bg-emerald-900 text-white py-1.5 px-8 rounded-lg shadow-sm border-b-4 border-amber-500\">\r\n                    <h2 class=\"text-lg font-black uppercase tracking-widest text-amber-400 leading-normal\">WELCOME LETTER</h2>\r\n                </div>\r\n            </div>\r\n\r\n            <!-- Congratulatory Letter Content Section -->\r\n            <div class=\"bg-stone-50/50 rounded-lg p-5 border border-emerald-100/50 mb-6 relative\">\r\n                <!-- Secondary subtle background watermark logo on below text -->\r\n                <div class=\"absolute inset-0 flex items-center justify-center pointer-events-none opacity-[0.035] select-none z-0\">\r\n                    <img src=\"{{agency_logo_url}}\" class=\"w-80 h-80 object-contain\" onerror=\"this.style.display=\'none\'\">\r\n                </div>\r\n\r\n                <!-- Date and Salutation -->\r\n                <div class=\"flex justify-between items-center mb-4 text-sm font-semibold relative z-10\">\r\n                    <div class=\"text-emerald-950\">\r\n                        Date: <span id=\"display-date\" class=\"font-bold text-gray-800\">{{letter_date}}</span>\r\n                    </div>\r\n                    <div class=\"text-emerald-950\">\r\n                        File Ref No: <span class=\"font-bold text-gray-800\">{{property_file}}</span>\r\n                    </div>\r\n                </div>\r\n\r\n                <!-- Personal Information Header with Mobile added and Address below -->\r\n                <div class=\"mb-4 relative z-10\">\r\n                    <p class=\"text-base font-bold text-emerald-950\">Dear {{client_name}},</p>\r\n                    <p class=\"text-xs text-gray-500 font-semibold mt-0.5\">CNIC: {{client_cnic}} | Mobile: {{client_mobile}}</p>\r\n                    <p class=\"text-xs text-gray-500 font-semibold mt-0.5\">Address: {{client_address}}</p>\r\n                </div>\r\n\r\n                <!-- Letter Body -->\r\n                <div class=\"text-sm text-gray-800 leading-relaxed space-y-3 font-serif relative z-10\">\r\n                    <p>\r\n                        On behalf of the executive board and the entire management team of <strong>{{agency_name}}</strong>, we extend our warmest congratulations and a heartfelt welcome to you on becoming a valuable esteemed member of our premium housing development project, <strong>{{property_name}}</strong>.\r\n                    </p>\r\n                    <p>\r\n                        This letter serves as your formal acknowledgment and congratulations on the successful booking of your real estate investment. We have securely registered your property and generated your unique file ledger under our automated municipal portal. Your key properties and allotment metrics are specified below:\r\n                    </p>\r\n\r\n                    <!-- Refined & Highly Colorized standalone Property Allotment Card -->\r\n                    <div class=\"my-4 bg-white border border-emerald-600/30 rounded-lg shadow-md overflow-hidden\">\r\n                        <!-- Highly Prominent Colored Card Header -->\r\n                        <div class=\"bg-gradient-to-r from-emerald-900 to-emerald-950 text-white px-4 py-2 flex items-center justify-between\">\r\n                            <span class=\"text-xs font-black tracking-widest uppercase flex items-center\">\r\n                                <svg xmlns=\"http://www.w3.org/2000/svg\" class=\"h-4 w-4 text-amber-400 mr-2\" fill=\"none\" viewBox=\"0 0 24 24\" stroke=\"currentColor\">\r\n                                    <path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z\" />\r\n                                </svg>\r\n                                OFFICIAL PROPERTY ALLOTMENT RECORD\r\n                            </span>\r\n                            <span class=\"bg-amber-500 text-emerald-950 text-[10px] font-black px-2.5 py-0.5 rounded shadow-sm uppercase tracking-wider\">Status: {{deal_status}}</span>\r\n                        </div>\r\n                        \r\n                        <!-- Premium Inner Metric Grid -->\r\n                        <div class=\"grid grid-cols-4 gap-3 p-3.5 bg-gradient-to-br from-emerald-50/20 via-white to-stone-50 text-xs\">\r\n                            <div class=\"bg-white p-2.5 rounded border border-emerald-100 shadow-sm border-l-4 border-l-emerald-700\">\r\n                                <span class=\"block text-[9px] text-emerald-900/60 uppercase tracking-wider font-extrabold mb-0.5\">File Number</span>\r\n                                <span class=\"font-extrabold text-emerald-950 font-mono text-sm leading-normal\">{{property_file}}</span>\r\n                            </div>\r\n                            <div class=\"bg-white p-2.5 rounded border border-emerald-100 shadow-sm border-l-4 border-l-emerald-700\">\r\n                                <span class=\"block text-[9px] text-emerald-900/60 uppercase tracking-wider font-extrabold mb-0.5\">Area / Size</span>\r\n                                <span class=\"font-bold text-gray-800 text-sm leading-normal\">{{property_area}}</span>\r\n                            </div>\r\n                            <div class=\"bg-white p-2.5 rounded border border-emerald-100 shadow-sm border-l-4 border-l-emerald-700\">\r\n                                <span class=\"block text-[9px] text-emerald-900/60 uppercase tracking-wider font-extrabold mb-0.5\">Category</span>\r\n                                <span class=\"font-bold text-emerald-800 text-sm leading-normal\">{{property_type}}</span>\r\n                            </div>\r\n                            <div class=\"bg-white p-2.5 rounded border border-emerald-100 shadow-sm border-l-4 border-l-emerald-700\">\r\n                                <span class=\"block text-[9px] text-emerald-900/60 uppercase tracking-wider font-extrabold mb-0.5\">Block Name</span>\r\n                                <span class=\"font-bold text-gray-800 text-sm leading-normal\">{{ballot_block_name}}</span>\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n\r\n                    <!-- Prominent, Colorized & Refined Bank Details Card (Installment payments) -->\r\n                    <div class=\"my-4 bg-gradient-to-br from-amber-50/40 via-white to-amber-50/20 border-2 border-dashed border-amber-600/40 rounded-lg relative overflow-hidden shadow-md\">\r\n                        <!-- Golden Emblem Stamp Background decoration -->\r\n                        <div class=\"absolute right-3 top-2.5 opacity-[0.09] pointer-events-none text-amber-900\">\r\n                            <svg xmlns=\"http://www.w3.org/2000/svg\" class=\"h-16 w-16\" fill=\"none\" viewBox=\"0 0 24 24\" stroke=\"currentColor\">\r\n                                <path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"1.5\" d=\"M19 21V5a2 2 0 00-2-2H7a2 2 0 00-2 2v16m14 0h2m-2 0h-5m-9 0H3m2 0h5M9 7h1m-1 4h1m4-4h1m-1 4h1m-5 10v-5a1 1 0 011-1h2a1 1 0 011 1v5m-4 0h4\" />\r\n                            </svg>\r\n                        </div>\r\n                        \r\n                        <!-- Rich Colored Accent Header Block inside card -->\r\n                        <div class=\"bg-gradient-to-r from-amber-600 to-amber-700 text-white px-4 py-1.5 flex items-center justify-between text-[11px] font-extrabold uppercase tracking-widest\">\r\n                            <span class=\"flex items-center\">\r\n                                <span class=\"inline-block w-2 h-2 bg-white rounded-full mr-2\"></span>\r\n                                OFFICIAL INSTALMENT & PAYMENT ACCOUNT DETAILS\r\n                            </span>\r\n                        </div>\r\n                        \r\n                        <div class=\"grid grid-cols-2 gap-x-6 gap-y-2 p-4 text-xs\">\r\n                            <div class=\"space-y-2\">\r\n                                <div class=\"flex items-center border-b border-amber-100/50 pb-1\">\r\n                                    <span class=\"text-amber-900 font-bold w-28 flex-shrink-0 bank-detail-label\">Bank Name:</span>\r\n                                    <span class=\"font-extrabold text-gray-800 flex-1 text-center bank-detail-value\">{{bank_name}}</span>\r\n                                </div>\r\n                                <div class=\"flex items-center border-b border-amber-100/50 pb-1\">\r\n                                    <span class=\"text-amber-900 font-bold w-28 flex-shrink-0 bank-detail-label\">Account Title:</span>\r\n                                    <span class=\"font-extrabold text-gray-800 flex-1 text-center bank-detail-value\">{{bank_account_title}}</span>\r\n                                </div>\r\n                            </div>\r\n                            <div class=\"space-y-2 border-l border-amber-200/50 pl-6\">\r\n                                <div class=\"flex items-center border-b border-amber-100/50 pb-1\">\r\n                                    <span class=\"text-amber-900 font-bold w-32 flex-shrink-0 bank-detail-label\">Account Number:</span>\r\n                                    <span class=\"font-mono font-extrabold text-gray-800 flex-1 text-center bank-detail-value\">{{bank_account_no}}</span>\r\n                                </div>\r\n                                <div class=\"flex items-center border-b border-amber-100/50 pb-1\">\r\n                                    <span class=\"text-amber-900 font-bold w-32 flex-shrink-0 bank-detail-label\">IBAN Number:</span>\r\n                                    <span class=\"font-mono font-extrabold text-gray-800 flex-1 text-center bank-detail-value\">{{bank_iban}}</span>\r\n                                </div>\r\n                            </div>\r\n                        </div>\r\n\r\n                        <!-- Strict security alert warning note regarding official installment accounts -->\r\n                        <div class=\"mx-4 mb-3 p-3 bg-red-50 border border-red-200 rounded text-[10px] text-red-800 font-medium leading-relaxed\">\r\n                            <strong class=\"text-red-900 font-extrabold uppercase tracking-wider block mb-0.5\">⚠️ Security Payment Notice:</strong>\r\n                            Please make payments only to the given official bank account details listed above. Under no circumstances should payments be transferred or handed over to any personal, individual, or other unofficial third-party account. The agency will not accept any responsibility or liability for transactions conducted on unofficial payment channels.\r\n                        </div>\r\n                    </div>\r\n\r\n                    <p>\r\n                        We are fundamentally dedicated to maintaining the highest industry standards of construction pace, legal transparency, and community development. We assure you that our development milestones are progressing rapidly, and we are on track to bring this master-planned community to life.\r\n                    </p>\r\n                    <p>\r\n                        Should you have any inquiries regarding installment structures, development timelines, or future allotment ballots, please do not hesitate to reach our corporate customer care desk at <strong>{{agency_phone}}</strong> or write to us directly at <strong>{{agency_email}}</strong>.\r\n                    </p>\r\n                    <p class=\"pt-1\">\r\n                        We sincerely thank you for placing your trust in our organization. Welcome to your secure future.\r\n                    </p>\r\n                    <p class=\"font-bold text-emerald-950 pt-1 leading-tight\">\r\n                        Warm regards,\r\n                    </p>\r\n                    <p class=\"text-xs font-semibold text-emerald-800 leading-none\">\r\n                        The Executive Committee of {{agency_name}}\r\n                    </p>\r\n                </div>\r\n            </div>\r\n\r\n            <!-- Footer: Symmetrical Signatures & Large QR Block -->\r\n            <footer class=\"text-[10px] relative mt-16 pb-4\">\r\n                <div class=\"grid grid-cols-12 gap-3 items-end text-center border-t border-emerald-200 pt-4\">\r\n                    \r\n                    <!-- Left: Chairman Sign (Chief Executive Officer) -->\r\n                    <div class=\"col-span-4 flex flex-col items-center\">\r\n                        <div class=\"h-16\"></div> <!-- Space for Signature -->\r\n                        <span class=\"block border-t border-emerald-900/60 mt-0.5 w-full uppercase text-emerald-950 font-bold\">Chairman Sign</span>\r\n                        <span class=\"block text-gray-600 text-[9px] mt-0.5 font-semibold\" id=\"letter-display-chairman\">Chief Executive Officer</span>\r\n                    </div>\r\n                    \r\n                    <!-- Center: Symmetrical Security QR Block resized to exactly 0.75 x 0.75 inches -->\r\n                    <div class=\"col-span-4 flex flex-col items-center justify-center\">\r\n                        <div class=\"flex items-center justify-center space-x-3 mb-1\">\r\n                            <!-- Symmetrical centered QR Code wrapper configured strictly to 0.75 x 0.75 inches -->\r\n                            <div class=\"border border-emerald-900/20 p-1.5 bg-white flex items-center justify-center rounded shadow-sm flex-shrink-0\" style=\"width: 0.75in; height: 0.75in;\">{{letter_deal_qr}}</div>\r\n                        </div>\r\n                        <span class=\"text-[7.5px] text-gray-500 uppercase tracking-widest font-sans font-bold\">Scan to Verify</span>\r\n                    </div>\r\n\r\n                    <!-- Right: Date -->\r\n                    <div class=\"col-span-4 flex flex-col items-center\">\r\n                        <div class=\"h-16\"></div> <!-- Matching height for layout symmetry -->\r\n                        <span class=\"block border-t border-emerald-900/60 mt-0.5 w-full uppercase text-emerald-950 font-bold\">Date</span>\r\n                        <span class=\"block text-gray-600 text-[9px] mt-0.5\" id=\"letter-display-date\">{{letter_date}}</span>\r\n                    </div>\r\n                </div>\r\n\r\n                <!-- Footer Barcode Verification Line -->\r\n                <div class=\"mt-6 flex flex-col items-center justify-center opacity-85\">\r\n                    <svg id=\"secure-barcode\" class=\"h-5 w-44\" viewBox=\"0 0 100 20\" preserveAspectRatio=\"none\">\r\n                        <!-- Barcode patterns populated dynamically from {{deal_invoice_no}} -->\r\n                    </svg>\r\n                    <span class=\"text-[7px] text-gray-500 font-mono mt-0.5 tracking-widest\">ID-{{deal_invoice_no}}</span>\r\n                </div>\r\n            </footer>\r\n        </div>\r\n\r\n    </div>\r\n\r\n    <script>\r\n        /**\r\n         * Image Fallback Script Block to prevent unrendered template variables \r\n         * or blocked remote assets from hanging layout rendering.\r\n         */\r\n        function handleLogoError(img) {\r\n            img.onerror = null;\r\n            img.src = \"data:image/svg+xml;charset=utf-8,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%20000%2Fsvg%22%20width%3D%22112%22%20height%3D%22112%22%20viewBox%3D%220%200%20112%20112%22%3E%3Crect%20width%3D%22100%25%22%20height%3D%22100%25%22%20fill%3D%22%23064e3b%22%2F%3E%3Ctext%20x%3D%2250%25%22%20y%3D%2250%25%22%20dominant-baseline%3D%22middle%22%20text-anchor%3D%22middle%22%20fill%3D%22%23ffffff%22%20font-family%3D%22sans-serif%22%20font-size%3D%2212%22%20font-weight%3D%22bold%22%3EAGENCY%20LOGO%3C%2Ftext%3E%3C%2Fsvg%3E\";\r\n        }\r\n\r\n        function handlePhotoError(img) {\r\n            img.onerror = null;\r\n            img.src = \"data:image/svg+xml;charset=utf-8,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%20000%2Fsvg%22%20width%3D%2296%22%20height%3D%22128%22%20viewBox%3D%220%200%2096%20128%22%3E%3Crect%20width%3D%22100%25%22%20height%3D%22100%25%22%20fill%3D%22%23e2e8f0%22%2F%3E%3Ccircle%20cx%3D%2248%22%20cy%3D%2245%22%20r%3D%2220%22%20fill%3D%22%2394a3b8%22%2F%3E%3Cpath%20d%3D%22M%2012%20110%20C%2012%2085%2C%2084%2085%2C%2084%20110%20Z%22%20fill%3D%22%2394a3b8%22%2F%3E%3Ctext%20x%3D%2250%25%22%20y%3D%2292%25%22%20dominant-baseline%3D%22middle%22%20text-anchor%3D%22middle%22%20fill%3D%22%23475569%22%20font-family%3D%22sans-serif%22%20font-size%3D%2210%22%20font-weight%3D%22bold%22%3EPHOTO%3C%2Ftext%3E%3C%2Fsvg%3E\";\r\n        }\r\n\r\n        function handleWatermarkError(img) {\r\n            img.onerror = null;\r\n            img.style.display = \'none\';\r\n        }\r\n\r\n        /**\r\n         * Helper parses the unformatted date and returns a \"DD-MMM-YYYY\" string (e.g., 06-Jan-2026)\r\n         */\r\n        function parseAndFormatDate(dateStr) {\r\n            if (!dateStr || dateStr.includes(\'{{\') || dateStr.includes(\'}}\')) {\r\n                return dateStr;\r\n            }\r\n            \r\n            let parsedDate = null;\r\n            let dateObj = new Date(dateStr);\r\n            if (!isNaN(dateObj.getTime())) {\r\n                parsedDate = dateObj;\r\n            } else {\r\n                const parts = dateStr.split(/[-/.]/);\r\n                if (parts.length === 3) {\r\n                    let day, month, year;\r\n                    if (parts[2].length === 4) {\r\n                        day = parseInt(parts[0], 10);\r\n                        month = parseInt(parts[1], 10) - 1;\r\n                        year = parseInt(parts[2], 10);\r\n                    } else if (parts[0].length === 4) {\r\n                        year = parseInt(parts[0], 10);\r\n                        month = parseInt(parts[1], 10) - 1;\r\n                        day = parseInt(parts[2], 10);\r\n                    }\r\n                    \r\n                    if (year && !isNaN(month) && month >= 0 && month < 12 && day && day > 0 && day <= 31) {\r\n                        parsedDate = new Date(year, month, day);\r\n                    }\r\n                }\r\n            }\r\n            \r\n            if (parsedDate && !isNaN(parsedDate.getTime())) {\r\n                const months = [\'Jan\', \'Feb\', \'Mar\', \'Apr\', \'May\', \'Jun\', \'Jul\', \'Aug\', \'Sep\', \'Oct\', \'Nov\', \'Dec\'];\r\n                const formattedDay = String(parsedDate.getDate()).padStart(2, \'0\');\r\n                const formattedMonth = months[parsedDate.getMonth()];\r\n                const formattedYear = parsedDate.getFullYear();\r\n                return `${formattedDay}-${formattedMonth}-${formattedYear}`;\r\n            }\r\n            \r\n            return dateStr;\r\n        }\r\n\r\n        /**\r\n         * Generates a unique secure pseudo-barcode matching the invoice ID sequence\r\n         */\r\n        function generateSecureBarcode() {\r\n            const barcodeSvg = document.getElementById(\'secure-barcode\');\r\n            if (!barcodeSvg) return;\r\n            \r\n            const rawId = \"{{deal_invoice_no}}\".trim();\r\n            const cleanId = rawId.includes(\'{{\') ? \'0100234001920\' : rawId.replace(/[^0-9]/g, \'\');\r\n            \r\n            let innerHtml = \'<rect width=\"100\" height=\"20\" fill=\"#ffffff\"/>\';\r\n            let cursor = 5;\r\n            \r\n            for (let i = 0; i < 30; i++) {\r\n                const charCodeVal = cleanId.charCodeAt(i % cleanId.length) || 103;\r\n                const barWidth = (charCodeVal % 2 === 0) ? 1.5 : 0.6;\r\n                const gapWidth = (charCodeVal % 3 === 0) ? 1.2 : 0.8;\r\n                \r\n                innerHtml += `<rect x=\"${cursor}\" y=\"0\" width=\"${barWidth}\" height=\"20\" fill=\"#111827\"/>`;\r\n                cursor += barWidth + gapWidth;\r\n                if (cursor > 95) break;\r\n            }\r\n            barcodeSvg.innerHTML = innerHtml;\r\n        }\r\n\r\n        function initWelcomeLetter() {\r\n            // Secure Barcode Generator\r\n            generateSecureBarcode();\r\n\r\n            // Date Format initializations\r\n            const dateElements = [\'display-date\', \'letter-display-date\'];\r\n            dateElements.forEach(function(id) {\r\n                const element = document.getElementById(id);\r\n                if (element) {\r\n                    const rawDate = element.textContent.trim();\r\n                    element.textContent = parseAndFormatDate(rawDate);\r\n                }\r\n            });\r\n        }\r\n\r\n        if (document.readyState !== \'loading\') {\r\n            initWelcomeLetter();\r\n        } else {\r\n            document.addEventListener(\'DOMContentLoaded\', initWelcomeLetter);\r\n        }\r\n    </script>\r\n</body>\r\n</html>', 'RLT_WELCOME', 'Unpublished', 'Yes', '', 'letter_signatures', '', 'letter_signatures');
INSERT INTO `templates` (`id`, `name`, `description`, `type`, `status`, `is_new`, `ceo_signature`, `ceo_signature_dir`, `chairman_signature`, `chairman_signature_dir`) VALUES
(33, 'Booking New', '<!DOCTYPE html>\r\n<html lang=\"en\">\r\n<head>\r\n    <meta charset=\"UTF-8\">\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n    <title>{{agency_name}} - Welcome Letter</title>\r\n    \r\n    <!-- Tailwind CSS -->\r\n    <script src=\"https://cdn.tailwindcss.com\"></script>\r\n    \r\n    <!-- Urdu Font Support -->\r\n    <link href=\"https://fonts.googleapis.com/css2?family=Noto+Nastaliq+Urdu:wght@400..700&display=swap\" rel=\"stylesheet\">\r\n    \r\n    <style>\r\n        .form-container {\r\n            max-width: 800px; \r\n            font-family: \'Times New Roman\', serif; \r\n            margin: 4px auto; \r\n            background-color: white;\r\n            padding: 1.25rem; \r\n            border-radius: 0.5rem;\r\n            box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1);\r\n            color: #1f2937;\r\n            \r\n            /* Custom double-line repeating floral frame border pattern matching image_1acdb4.png */\r\n            border: 24px solid transparent;\r\n            border-image-source: url(\"data:image/svg+xml;charset=utf-8,%3Csvg xmlns=\'http://www.w3.org/2000/svg\' width=\'72\' height=\'72\' viewBox=\'0 0 72 72\'%3E%3Cdefs%3E%3Cg id=\'flower\'%3E%3Ccircle cx=\'12\' cy=\'12\' r=\'3.5\' fill=\'%23064e3b\'/%3E%3Cpath d=\'M12,12 C10,9 10,4 12,4 C14,4 14,9 12,12 Z\' fill=\'%23064e3b\'/%3E%3Cpath d=\'M12,12 C10,15 10,20 12,20 C14,20 14,15 12,12 Z\' fill=\'%23064e3b\'/%3E%3Cpath d=\'M12,12 C9,10 4,10 4,12 C4,14 9,14 12,12 Z\' fill=\'%23064e3b\'/%3E%3Cpath d=\'M12,12 C15,10 20,10 20,12 C20,14 15,14 12,12 Z\' fill=\'%23064e3b\'/%3E%3Cpath d=\'M12,12 C10,11 6.5,7.5 7.5,6.5 C8.5,5.5 11,10 12,12 Z\' fill=\'%23064e3b\'/%3E%3Cpath d=\'M12,12 C11,10 14.5,6.5 15.5,7.5 C16.5,8.5 12,11 12,12 Z\' fill=\'%23064e3b\'/%3E%3Cpath d=\'M12,12 C11,14 7.5,15.5 6.5,14.5 C5.5,13.5 10,11 12,12 Z\' fill=\'%23064e3b\'/%3E%3Cpath d=\'M12,12 C13,14 16.5,14.5 15.5,15.5 C14.5,16.5 11,13 12,12 Z\' fill=\'%23064e3b\'/%3E%3C/g%3E%3C/defs%3E%3Cpath d=\'M24,2 L2,2 L2,24\' fill=\'none\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cpath d=\'M24,22 L22,22 L22,24\' fill=\'none\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cuse href=\'%23flower\' x=\'0\' y=\'0\'/%3E%3Cline x1=\'24\' y1=\'2\' x2=\'48\' y2=\'2\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cline x1=\'24\' y1=\'22\' x2=\'48\' y2=\'22\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cuse href=\'%23flower\' x=\'24\' y=\'0\'/%3E%3Cpath d=\'M48,2 L70,2 L70,24\' fill=\'none\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cpath d=\'M48,22 L50,22 L50,24\' fill=\'none\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cuse href=\'%23flower\' x=\'48\' y=\'0\'/%3E%3Cline x1=\'2\' y1=\'24\' x2=\'2\' y2=\'48\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cline x1=\'22\' y1=\'24\' x2=\'22\' y2=\'48\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cuse href=\'%23flower\' x=\'0\' y=\'24\'/%3E%3Cline x1=\'70\' y1=\'24\' x2=\'70\' y2=\'48\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cline x1=\'50\' y1=\'24\' x2=\'50\' y2=\'48\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cuse href=\'%23flower\' x=\'48\' y=\'24\'/%3E%3Cpath d=\'M2,48 L2,70 L24,70\' fill=\'none\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cpath d=\'M22,48 L22,50 L24,50\' fill=\'none\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cuse href=\'%23flower\' x=\'0\' y=\'48\'/%3E%3Cline x1=\'24\' y1=\'50\' x2=\'48\' y2=\'50\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cline x1=\'24\' y1=\'70\' x2=\'48\' y2=\'70\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cuse href=\'%23flower\' x=\'24\' y=\'48\'/%3E%3Cpath d=\'M70,48 L70,70 L48,70\' fill=\'none\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cpath d=\'M50,48 L50,50 L48,50\' fill=\'none\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cuse href=\'%23flower\' x=\'48\' y=\'48\'/%3E%3C/svg%3E\");\r\n            border-image-slice: 24;\r\n            border-image-repeat: repeat;\r\n            \r\n            position: relative;\r\n            overflow: hidden;\r\n        }\r\n        \r\n        /* Centered Background Watermark style */\r\n        .watermark {\r\n            position: absolute;\r\n            top: 50%;\r\n            left: 50%;\r\n            transform: translate(-50%, -50%);\r\n            width: 320px;\r\n            height: 320px;\r\n            opacity: 0.04; /* Subtle backdrop presence */\r\n            pointer-events: none;\r\n            z-index: 0;\r\n            user-select: none;\r\n        }\r\n\r\n        /* Form content wrapper to stay above watermark */\r\n        .form-content-wrapper {\r\n            position: relative;\r\n            z-index: 10;\r\n        }\r\n\r\n        .form-section-title {\r\n            background-color: #064e3b; /* Premium Forest Green background */\r\n            color: #ffffff; /* Crisp white text */\r\n            font-weight: 700;\r\n            font-size: 0.85rem;\r\n            padding: 0.25rem 0.75rem;\r\n            margin-bottom: 0.5rem;\r\n            border-left: 4px solid #d97706; /* Solid amber gold accent bar */\r\n            border-radius: 0 0.25rem 0.25rem 0;\r\n            letter-spacing: 0.05em;\r\n            display: inline-block;\r\n        }\r\n        \r\n        .info-label {\r\n            font-weight: 700;\r\n            color: #064e3b;\r\n        }\r\n\r\n        /* --- PRINT STYLING & COLOR PRESERVATION --- */\r\n        @media print {\r\n            @page {\r\n                size: A4 portrait;\r\n                margin: 0;\r\n            }\r\n            body { \r\n                margin: 0; \r\n                padding: 0; \r\n                background: none; \r\n            }\r\n            * {\r\n                -webkit-print-color-adjust: exact !important;\r\n                print-color-adjust: exact !important;\r\n            }\r\n            .form-container {\r\n                max-width: 100%;\r\n                width: 100%;\r\n                box-shadow: none;\r\n                border: 24px solid transparent !important;\r\n                border-image-source: url(\"data:image/svg+xml;charset=utf-8,%3Csvg xmlns=\'http://www.w3.org/2000/svg\' width=\'72\' height=\'72\' viewBox=\'0 0 72 72\'%3E%3Cdefs%3E%3Cg id=\'flower\'%3E%3Ccircle cx=\'12\' cy=\'12\' r=\'3.5\' fill=\'%23064e3b\'/%3E%3Cpath d=\'M12,12 C10,9 10,4 12,4 C14,4 14,9 12,12 Z\' fill=\'%23064e3b\'/%3E%3Cpath d=\'M12,12 C10,15 10,20 12,20 C14,20 14,15 12,12 Z\' fill=\'%23064e3b\'/%3E%3Cpath d=\'M12,12 C9,10 4,10 4,12 C4,14 9,14 12,12 Z\' fill=\'%23064e3b\'/%3E%3Cpath d=\'M12,12 C15,10 20,10 20,12 C20,14 15,14 12,12 Z\' fill=\'%23064e3b\'/%3E%3Cpath d=\'M12,12 C10,11 6.5,7.5 7.5,6.5 C8.5,5.5 11,10 12,12 Z\' fill=\'%23064e3b\'/%3E%3Cpath d=\'M12,12 C11,10 14.5,6.5 15.5,7.5 C16.5,8.5 12,11 12,12 Z\' fill=\'%23064e3b\'/%3E%3Cpath d=\'M12,12 C11,14 7.5,15.5 6.5,14.5 C5.5,13.5 10,11 12,12 Z\' fill=\'%23064e3b\'/%3E%3Cpath d=\'M12,12 C13,14 16.5,14.5 15.5,15.5 C14.5,16.5 11,13 12,12 Z\' fill=\'%23064e3b\'/%3E%3C/g%3E%3C/defs%3E%3Cpath d=\'M24,2 L2,2 L2,24\' fill=\'none\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cpath d=\'M24,22 L22,22 L22,24\' fill=\'none\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cuse href=\'%23flower\' x=\'0\' y=\'0\'/%3E%3Cline x1=\'24\' y1=\'2\' x2=\'48\' y2=\'2\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cline x1=\'24\' y1=\'22\' x2=\'48\' y2=\'22\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cuse href=\'%23flower\' x=\'24\' y=\'0\'/%3E%3Cpath d=\'M48,2 L70,2 L70,24\' fill=\'none\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cpath d=\'M48,22 L50,22 L50,24\' fill=\'none\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cuse href=\'%23flower\' x=\'48\' y=\'0\'/%3E%3Cline x1=\'2\' y1=\'24\' x2=\'2\' y2=\'48\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cline x1=\'22\' y1=\'24\' x2=\'22\' y2=\'48\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cuse href=\'%23flower\' x=\'0\' y=\'24\'/%3E%3Cline x1=\'70\' y1=\'24\' x2=\'70\' y2=\'48\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cline x1=\'50\' y1=\'24\' x2=\'50\' y2=\'48\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cuse href=\'%23flower\' x=\'48\' y=\'24\'/%3E%3Cpath d=\'M2,48 L2,70 L24,70\' fill=\'none\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cpath d=\'M22,48 L22,50 L24,50\' fill=\'none\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cuse href=\'%23flower\' x=\'0\' y=\'48\'/%3E%3Cline x1=\'24\' y1=\'50\' x2=\'48\' y2=\'50\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cline x1=\'24\' y1=\'70\' x2=\'48\' y2=\'70\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cuse href=\'%23flower\' x=\'24\' y=\'48\'/%3E%3Cpath d=\'M70,48 L70,70 L48,70\' fill=\'none\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cpath d=\'M50,48 L50,50 L48,50\' fill=\'none\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cuse href=\'%23flower\' x=\'48\' y=\'48\'/%3E%3C/svg%3E\") !important;\r\n                border-image-slice: 24 !important;\r\n                border-image-repeat: repeat !important;\r\n                padding: 0.5rem;\r\n                margin: 0;\r\n            }\r\n            .form-section-title {\r\n                background-color: #064e3b !important;\r\n                color: #ffffff !important;\r\n                border-left: 4px solid #d97706 !important;\r\n                display: inline-block !important;\r\n            }\r\n            .watermark {\r\n                opacity: 0.04 !important;\r\n            }\r\n        }\r\n    \r\n        /* White Villas compact A4 welcome letter print/PDF fit */ /* wv-welcome-a4-fit-css */\r\n        .wv-welcome-a4{width:210mm!important;max-width:210mm!important;margin:0 auto!important;padding:5mm!important;border-width:12px!important;border-image-slice:24!important;box-shadow:none!important;font-size:12px!important;line-height:1.85!important;}\r\n        .wv-welcome-a4 .watermark{width:220px!important;height:220px!important;}\r\n        .wv-welcome-a4 header{margin-bottom:.35rem!important;padding:.45rem!important;padding-bottom:.45rem!important;}\r\n        .wv-welcome-a4 header .w-28{width:5rem!important;}\r\n        .wv-welcome-a4 header .h-28{height:5rem!important;}\r\n        .wv-welcome-a4 header .w-24{width:4.1rem!important;}\r\n        .wv-welcome-a4 header .h-32{height:5.3rem!important;}\r\n        .wv-welcome-a4 h1{font-size:1.45rem!important;line-height:1.85!important;margin:0!important;}\r\n        .wv-welcome-a4 h2{font-size:.92rem!important;line-height:1.85!important;margin:0!important;}\r\n        .wv-welcome-a4 .text-center.mb-6{margin-bottom:.45rem!important;}\r\n        .wv-welcome-a4 .bg-stone-50\\/50{padding:.55rem!important;margin-bottom:.35rem!important;}\r\n        .wv-welcome-a4 .my-4{margin-top:.35rem!important;margin-bottom:.35rem!important;}\r\n        .wv-welcome-a4 .mb-6{margin-bottom:.45rem!important;}\r\n        .wv-welcome-a4 .mb-4{margin-bottom:.35rem!important;}\r\n        .wv-welcome-a4 .mt-2{margin-top:.25rem!important;}\r\n        .wv-welcome-a4 .mt-1\\.5{margin-top:.2rem!important;}\r\n        .wv-welcome-a4 .p-5{padding:.55rem!important;}\r\n        .wv-welcome-a4 .p-4{padding:.55rem!important;}\r\n        .wv-welcome-a4 .p-3.5{padding:.45rem!important;}\r\n        .wv-welcome-a4 .p-3{padding:.4rem!important;}\r\n        .wv-welcome-a4 .p-2\\.5{padding:.35rem!important;}\r\n        .wv-welcome-a4 .px-8{padding-left:1.2rem!important;padding-right:1.2rem!important;}\r\n        .wv-welcome-a4 .py-1\\.5{padding-top:.25rem!important;padding-bottom:.25rem!important;}\r\n        .wv-welcome-a4 .gap-3{gap:.35rem!important;}\r\n        .wv-welcome-a4 .gap-x-6{column-gap:.7rem!important;}\r\n        .wv-welcome-a4 .gap-y-2{row-gap:.25rem!important;}\r\n        .wv-welcome-a4 .space-y-2>:not([hidden])~:not([hidden]){margin-top:.25rem!important;}\r\n        .wv-welcome-a4 .space-y-3>:not([hidden])~:not([hidden]){margin-top:.28rem!important;}\r\n        .wv-welcome-a4 p{margin-top:0!important;margin-bottom:.25rem!important;line-height:1.85!important;}\r\n        .wv-welcome-a4 .text-base{font-size:.82rem!important;line-height:1.85!important;}\r\n        .wv-welcome-a4 .text-sm{font-size:.72rem!important;line-height:1.85!important;}\r\n        .wv-welcome-a4 .text-xs{font-size:.72rem!important;line-height:1.85!important;}\r\n        .wv-welcome-a4 .text-\\[10px\\]{font-size:.52rem!important;line-height:1.85!important;}\r\n        .wv-welcome-a4 .text-\\[9px\\]{font-size:.5rem!important;line-height:1.85!important;}\r\n        .wv-welcome-a4 .text-\\[7\\.5px\\],.wv-welcome-a4 .text-\\[7px\\]{font-size:.42rem!important;line-height:1.85!important;}\r\n        .wv-welcome-a4 footer{margin-top:.35rem!important;padding-bottom:0!important;}\r\n        .wv-welcome-a4 footer .grid{padding-top:.35rem!important;gap:.35rem!important;}\r\n        .wv-welcome-a4 footer .h-16{height:.28in!important;}\r\n        .wv-welcome-a4 footer .mt-6{margin-top:.22rem!important;}\r\n        .wv-welcome-a4 footer .mb-1{margin-bottom:.1rem!important;}\r\n        .wv-welcome-a4 #secure-barcode{height:10px!important;width:118px!important;}\r\n        .wv-welcome-a4 [style*=\"0.75in\"],.wv-welcome-a4 [style*=\"1.25in\"]{width:.75in!important;height:.75in!important;padding:2px!important;}\r\n        .wv-welcome-a4 [style*=\"0.75in\"] img,.wv-welcome-a4 [style*=\"1.25in\"] img{width:100%!important;height:100%!important;filter:contrast(1.45)!important;image-rendering:pixelated!important;}\r\n        @media print{\r\n            @page{size:A4 portrait;margin:0;}\r\n            html,body{width:210mm!important;height:297mm!important;margin:0!important;padding:0!important;background:#fff!important;overflow:hidden!important;}\r\n            .wv-welcome-a4{width:210mm!important;max-width:210mm!important;height:297mm!important;max-height:297mm!important;margin:0!important;padding:5mm!important;border-width:12px!important;border-image-slice:24!important;box-shadow:none!important;overflow:hidden!important;border-image-repeat:repeat!important;}\r\n            .form-section-title{padding:.18rem .5rem!important;margin-bottom:.25rem!important;}\r\n        }\r\n    \r\n        /* Center bank detail values only */ /* wv-bank-center-fix */\r\n        .wv-welcome-a4 .bank-detail-value{display:block!important;flex:1 1 auto!important;text-align:center!important;}\r\n        .wv-welcome-a4 .bank-detail-label{display:block!important;flex:0 0 7.5rem!important;white-space:nowrap!important;}\r\n    \r\n        /* Polished full-page print positioning */ /* wv-welcome-print-polish */\r\n        .wv-welcome-a4 .form-content-wrapper{height:100%!important;min-height:100%!important;display:flex!important;flex-direction:column!important;}\r\n        .wv-welcome-a4 header{flex:0 0 auto!important;}\r\n        .wv-welcome-a4 .form-content-wrapper>div:not(.watermark):not(header):not(footer){flex:0 0 auto!important;}\r\n        .wv-welcome-a4 footer{margin-top:auto!important;padding-top:7mm!important;padding-bottom:1.5mm!important;flex:0 0 auto!important;}\r\n        .wv-welcome-a4 footer .grid{padding-top:3mm!important;align-items:end!important;border-top:none!important;} /* Changed border-top to none!important to remove top line on footer/QR code section */\r\n        .wv-welcome-a4 footer .h-16{height:.34in!important;}\r\n        .wv-welcome-a4 footer .border-t{border-top-color:transparent!important;} /* Force border transparent */\r\n        .wv-welcome-a4 footer #secure-barcode{margin-top:0!important;}\r\n        .wv-welcome-a4 footer .mt-6{margin-top:.15rem!important;}\r\n        .wv-welcome-a4 footer .mt-0.5{margin-top:.08rem!important;}\r\n        .wv-welcome-a4 footer .tracking-widest{letter-spacing:.08em!important;}\r\n        .wv-welcome-a4 .bg-stone-50\\/50{border-color:#d1fae5!important;box-shadow:0 1px 5px rgba(6,78,59,.08)!important;}\r\n        .wv-welcome-a4 .bg-gradient-to-r.from-emerald-900{background:#064e3b!important;}\r\n        .wv-welcome-a4 .bg-gradient-to-r.from-amber-600{background:#c76300!important;}\r\n        .wv-welcome-a4 .bg-white.p-2\\.5{min-height:38px!important;}\r\n        .wv-welcome-a4 .bank-detail-value{white-space:nowrap!important;overflow:hidden!important;text-overflow:ellipsis!important;}\r\n        @media print{\r\n            .wv-welcome-a4 .form-content-wrapper{height:100%!important;min-height:100%!important;display:flex!important;flex-direction:column!important;}\r\n            .wv-welcome-a4 footer{margin-top:auto!important;padding-top:7mm!important;padding-bottom:1.5mm!important;}\r\n        }\r\n    </style>\r\n<style type=\"text/css\" id=\"wv-urdu-font-definitions\">\n@font-face {\n    font-family: \'Jameel Noori Nastaleeq\';\n    src: url(\'/whitevillas/fonts/JameelNooriNastaleeq.ttf\') format(\'truetype\'),\n         url(\'/fonts/JameelNooriNastaleeq.ttf\') format(\'truetype\'),\n         url(\'../fonts/JameelNooriNastaleeq.ttf\') format(\'truetype\');\n    font-weight: normal;\n    font-style: normal;\n    font-display: swap;\n}\n@font-face {\n    font-family: \'Jameel Noori Nastaleeq Kasheeda\';\n    src: url(\'/whitevillas/fonts/JameelNooriNastaleeqKasheeda.ttf\') format(\'truetype\'),\n         url(\'/fonts/JameelNooriNastaleeqKasheeda.ttf\') format(\'truetype\'),\n         url(\'../fonts/JameelNooriNastaleeqKasheeda.ttf\') format(\'truetype\');\n    font-weight: normal;\n    font-style: normal;\n    font-display: swap;\n}\n*, *:before, *:after {\n    -webkit-print-color-adjust: exact !important;\n    print-color-adjust: exact !important;\n    color-adjust: exact !important;\n}\n[lang=\"ur\"], [dir=\"rtl\"], .urdu-text, .ashtam-page, .letter-ur, .urdu-body, .urdu-legal {\n    font-family: \'Jameel Noori Nastaleeq\', \'Noto Nastaliq Urdu\', \'Nafees Nastaleeq\', serif !important;\n    line-height: 1.85 !important;\n    letter-spacing: 0 !important;\n    word-spacing: 0 !important;\n}\n[lang=\"ur\"] h1, [lang=\"ur\"] h2, [lang=\"ur\"] h3, [lang=\"ur\"] h4, [lang=\"ur\"] h5, [lang=\"ur\"] h6,\n[dir=\"rtl\"] h1, [dir=\"rtl\"] h2, [dir=\"rtl\"] h3, [dir=\"rtl\"] h4, [dir=\"rtl\"] h5, [dir=\"rtl\"] h6,\n.ashtam-page h1, .ashtam-page h2, .ashtam-page h3, .ashtam-page h4,\n.urdu-heading, .ashtam-heading, .document-title, .document-subtitle, .section-title, .sign-title, .bismillah {\n    font-family: \'Jameel Noori Nastaleeq Kasheeda\', \'Jameel Noori Nastaleeq\', \'Noto Nastaliq Urdu\', serif !important;\n    font-weight: normal !important;\n    line-height: 1.5 !important;\n}\n[lang=\"ur\"] p, [lang=\"ur\"] li, [lang=\"ur\"] td, [lang=\"ur\"] th, [lang=\"ur\"] span,\n[dir=\"rtl\"] p, [dir=\"rtl\"] li, [dir=\"rtl\"] td, [dir=\"rtl\"] th, [dir=\"rtl\"] span,\n.ashtam-page p, .ashtam-page li, .ashtam-page td, .ashtam-page th,\n.urdu-body p, .clause, .note-box, .amount-box {\n    font-family: \'Jameel Noori Nastaleeq\', \'Noto Nastaliq Urdu\', \'Nafees Nastaleeq\', serif !important;\n    line-height: 1.85 !important;\n}\n@media print {\n    @page { size: auto; margin: 0; }\n    html, body {\n        background: #ffffff !important;\n        color: #000000 !important;\n        margin: 0 !important;\n        padding: 0 !important;\n    }\n    .ashtam-page, .page, .form-container, .container, .letter-preview-print {\n        margin: 0 auto !important;\n        box-shadow: none !important;\n        -webkit-print-color-adjust: exact !important;\n        print-color-adjust: exact !important;\n        color-adjust: exact !important;\n    }\n}\n</style></head>\r\n\r\n<body class=\"bg-gray-100 p-2 sm:p-6 flex justify-center\" style=\"margin:0!important;padding:0!important;background:#fff!important;display:block!important;\">\r\n\r\n    <div class=\"form-container w-full wv-welcome-a4\">\r\n        \r\n        <!-- Centered Background Watermark -->\r\n        <div class=\"watermark flex items-center justify-center\">\r\n            <img id=\"watermark-logo\" src=\"{{agency_logo_url}}\" \r\n                 alt=\"Watermark Logo\" class=\"w-full h-full object-contain\" onerror=\"handleWatermarkError(this)\">\r\n        </div>\r\n\r\n        <div class=\"form-content-wrapper\">\r\n            <header class=\"mb-3 flex flex-row items-center justify-between pb-3 relative overflow-hidden rounded-lg p-3 bg-emerald-50/10 border border-emerald-100/30\">\r\n                <!-- Panoramic Pakistani Monuments SVG Watermark Background -->\r\n                <div class=\"absolute inset-0 pointer-events-none opacity-[0.06] z-0 select-none flex items-end\">\r\n                    <svg class=\"w-full h-full\" viewBox=\"0 0 1000 120\" preserveAspectRatio=\"none\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\">\r\n                        <line x1=\"0\" y1=\"120\" x2=\"1000\" y2=\"120\" stroke=\"#064e3b\" stroke-width=\"2\" />\r\n                        <path d=\"M15,120 L25,108 L28,108 L31,105 L31,100 L34,100 L35,80 L32,80 L32,77 L38,77 L39,55 L35,55 L35,52 L41,52 L43,20 C43,15 47,15 47,20 L49,52 L55,52 L55,55 L51,55 L52,77 L58,77 L58,80 L55,80 L56,100 L59,100 L59,105 L62,108 L65,108 L75,120 Z\" fill=\"#064e3b\" />\r\n                        <path d=\"M100,120 L100,60 L112,60 L112,50 L108,50 L108,45 L124,45 L124,50 L120,50 L120,60 L135,60 L135,75 Q145,62 155,75 L155,120 L147,120 L147,85 Q145,76 138,85 L138,120 L130,120 L130,70 L125,70 L125,120 Z\" fill=\"#064e3b\" />\r\n                        <path d=\"M155,120 L155,75 Q165,62 175,75 L175,60 L190,60 L190,50 L186,50 L186,45 L202,45 L202,50 L198,50 L198,60 L210,60 L210,120 L185,120 L185,70 L180,70 L180,120 Z\" fill=\"#064e3b\" />\r\n                        <path d=\"M220,120 L220,30 L216,30 L211,30 L211,25 L219,25 L220,15 C220,10 226,10 226,15 L227,25 L235,25 L235,30 L231,30 L231,120 Z\" fill=\"#064e3b\" />\r\n                        <path d=\"M255,120 L255,90 Q280,65 305,90 L305,120 Z\" fill=\"#064e3b\" />\r\n                        <path d=\"M310,120 L310,85 C310,50 360,50 360,85 L360,120 Z\" fill=\"#064e3b\" />\r\n                        <path d=\"M365,120 L365,90 Q390,65 415,90 L415,120 Z\" fill=\"#064e3b\" />\r\n                        <path d=\"M430,120 L430,30 L426,30 L421,30 L421,25 L429,25 L430,15 C430,10 436,10 436,15 L437,25 L445,25 L445,30 L441,30 L441,120 Z\" fill=\"#064e3b\" />\r\n                        <path d=\"M480,120 L485,85 L500,85 L505,65 L525,65 L527,50 C527,45 533,45 533,50 L535,65 L555,65 L560,85 L575,85 L580,120 Z\" fill=\"#064e3b\" />\r\n                        <path d=\"M600,120 L615,70 L675,70 L690,120 Z\" fill=\"#064e3b\" />\r\n                        <path d=\"M622,70 C622,45 668,45 668,70 Z\" fill=\"#064e3b\" />\r\n                        <path d=\"M635,120 L635,95 C635,85 655,85 655,95 L655,120 Z\" fill=\"#ffffff\" opacity=\"0.6\" />\r\n                        <path d=\"M710,120 C710,95 725,80 740,85 C730,102 720,112 717,120 Z\" fill=\"#064e3b\" />\r\n                        <path d=\"M725,120 C730,75 755,60 767,70 C755,92 743,110 740,120 Z\" fill=\"#064e3b\" />\r\n                        <circle cx=\"765\" cy=\"100\" r=\"6\" fill=\"#064e3b\" />\r\n                        <path d=\"M800,120 C795,75 770,60 758,70 C770,92 782,110 785,120 Z\" fill=\"#064e3b\" />\r\n                        <path d=\"M815,120 C815,95 800,80 785,85 C795,102 805,112 808,120 Z\" fill=\"#064e3b\" />\r\n                        <path d=\"M845,120 L845,15 L848,15 L848,120 Z\" fill=\"#064e3b\" />\r\n                        <path d=\"M860,120 L910,55 L960,120 Z\" fill=\"#064e3b\" />\r\n                        <line x1=\"910\" y1=\"55\" x2=\"910\" y2=\"45\" stroke=\"#064e3b\" stroke-width=\"2\" />\r\n                        <path d=\"M975,120 L975,15 L978,15 L978,120 Z\" fill=\"#064e3b\" />\r\n                        <line x1=\"885\" y1=\"120\" x2=\"910\" y2=\"55\" stroke=\"#ffffff\" stroke-width=\"1.5\" opacity=\"0.3\" />\r\n                        <line x1=\"935\" y1=\"120\" x2=\"910\" y2=\"55\" stroke=\"#ffffff\" stroke-width=\"1.5\" opacity=\"0.3\" />\r\n                    </svg>\r\n                </div>\r\n\r\n                <!-- Left logo wrapper -->\r\n                <div class=\"w-28 flex-shrink-0 flex items-center justify-start z-10 relative\">\r\n                    <div class=\"w-28 h-28 flex-shrink-0 flex items-center justify-center bg-transparent\">\r\n                        <img id=\"agency-logo\" src=\"{{agency_logo_url}}\" \r\n                             alt=\"Agency Logo\" class=\"w-full h-full object-contain p-1.5\" onerror=\"handleLogoError(this)\">\r\n                    </div>\r\n                </div>\r\n\r\n                <!-- Center Header Texts -->\r\n                <div class=\"flex-1 flex flex-col items-center justify-center text-center px-4 z-10 relative\">\r\n                    <h1 class=\"text-3xl sm:text-4xl font-black tracking-wide text-emerald-950 border-b-2 border-amber-500/40 pb-1 leading-tight inline-block\">{{agency_name}}</h1> \r\n                    <p class=\"text-sm font-medium text-gray-700 mt-1.5 max-w-md\">{{agency_address}}</p>\r\n\r\n                    <div class=\"text-xs font-semibold text-gray-600 mt-2 gap-x-4 flex flex-wrap justify-center\">\r\n                        <div>\r\n                            <span class=\"font-extrabold text-emerald-800\">Email:</span> \r\n                            <span>{{agency_email}}</span>\r\n                        </div>\r\n                        <div>\r\n                            <span class=\"font-extrabold text-emerald-800\">Mobile:</span> \r\n                            <span>{{agency_phone}}</span>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n                \r\n                <!-- Right photo wrapper -->\r\n                <div class=\"w-28 flex-shrink-0 flex items-center justify-end z-10 relative\">\r\n                    <div class=\"w-24 h-32 border-2 border-emerald-800 flex items-center justify-center text-emerald-700/60 text-[10px] bg-emerald-50/20 overflow-hidden rounded shadow-md\">\r\n                        <img id=\"client-photo\" src=\"{{client_profile_photo_url}}\" alt=\"Applicant Photo\" class=\"w-full h-full object-cover\" onerror=\"handlePhotoError(this)\">\r\n                    </div>\r\n                </div>\r\n            </header>\r\n\r\n            <!-- Document Title & Reference ID -->\r\n            <div class=\"flex justify-between items-center text-xs font-extrabold mb-4 pb-1 border-b border-emerald-100\">\r\n                <div>\r\n                    <span class=\"text-emerald-700 font-extrabold\">Reference ID:</span> \r\n                    <span class=\"text-gray-800 ml-1 font-bold\">{{letter_ref_no}}</span>\r\n                </div>\r\n                <div>\r\n                    <span class=\"text-emerald-700 font-extrabold\">File No:</span> \r\n                    <span class=\"text-emerald-600 ml-1 font-bold\">{{property_file}}</span>\r\n                </div>\r\n            </div>\r\n\r\n            <!-- Welcome Letter Heading Banner (Centered Stylized Badge) -->\r\n            <div class=\"text-center mb-6\">\r\n                <div class=\"inline-block bg-emerald-900 text-white py-1.5 px-8 rounded-lg shadow-sm border-b-4 border-amber-500\">\r\n                    <h2 class=\"text-lg font-black uppercase tracking-widest text-amber-400 leading-normal\">WELCOME LETTER</h2>\r\n                </div>\r\n            </div>\r\n\r\n            <!-- Congratulatory Letter Content Section -->\r\n            <div class=\"bg-stone-50/50 rounded-lg p-5 border border-emerald-100/50 mb-6 relative\">\r\n                <!-- Secondary subtle background watermark logo on below text -->\r\n                <div class=\"absolute inset-0 flex items-center justify-center pointer-events-none opacity-[0.035] select-none z-0\">\r\n                    <img src=\"{{agency_logo_url}}\" class=\"w-80 h-80 object-contain\" onerror=\"this.style.display=\'none\'\">\r\n                </div>\r\n\r\n                <!-- Date and Salutation -->\r\n                <div class=\"flex justify-between items-center mb-4 text-sm font-semibold relative z-10\">\r\n                    <div class=\"text-emerald-950\">\r\n                        Date: <span id=\"display-date\" class=\"font-bold text-gray-800\">{{letter_date}}</span>\r\n                    </div>\r\n                    <div class=\"text-emerald-950\">\r\n                        File Ref No: <span class=\"font-bold text-gray-800\">{{property_file}}</span>\r\n                    </div>\r\n                </div>\r\n\r\n                <!-- Highly Prominent Mailing & Addressee Block structured for clear preview and physical mailing -->\r\n                <div class=\"mb-6 relative z-10 p-4 bg-gradient-to-br from-emerald-50/30 via-white to-emerald-50/15 border border-emerald-100/70 rounded-lg shadow-sm\">\r\n                    <span class=\"block text-[9px] uppercase tracking-widest font-black text-emerald-800 mb-1.5\">RECIPIENT &amp; MAILING DETAILS</span>\r\n                    \r\n                    <h3 class=\"text-base font-bold text-emerald-950 mb-1.5\">Dear {{client_name}},</h3>\r\n                    \r\n                    <div class=\"space-y-1.5 text-xs text-gray-700 font-medium\">\r\n                        <p class=\"leading-relaxed\">\r\n                            <span class=\"text-emerald-800 font-extrabold uppercase text-[10px] tracking-wide mr-1\">Address:</span> \r\n                            <strong class=\"text-gray-900 font-semibold\">{{client_address}}</strong>\r\n                        </p>\r\n                        <div class=\"flex flex-wrap gap-x-6 gap-y-1\">\r\n                            <div>\r\n                                <span class=\"text-emerald-800 font-extrabold uppercase text-[10px] tracking-wide mr-1\">CNIC:</span> \r\n                                <strong class=\"text-gray-800 font-semibold font-mono\">{{client_cnic}}</strong>\r\n                            </div>\r\n                            <div>\r\n                                <span class=\"text-emerald-800 font-extrabold uppercase text-[10px] tracking-wide mr-1\">Mobile:</span> \r\n                                <strong class=\"text-gray-800 font-semibold font-mono\">{{client_mobile}}</strong>\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                    \r\n                    <!-- Added Urdu greeting with proper Urdu Jameel Noori Nastaliq / Noto font styling with margin gap -->\r\n                    <div class=\"mt-4 mb-1 text-left\" dir=\"rtl\">\r\n                        <span style=\"font-family: \'Jameel Noori Nastaleeq\', \'Noto Nastaliq Urdu\', serif;\" class=\"text-xl sm:text-2xl text-emerald-900 font-normal leading-normal\">وعلیکم السلام ورحمۃ اللہ وبرکاتہ!</span>\r\n                    </div>\r\n                </div>\r\n\r\n                <!-- Letter Body -->\r\n                <div class=\"text-sm text-gray-800 leading-relaxed space-y-4 font-serif relative z-10 mt-4\">\r\n                    <p>\r\n                        On behalf of the executive board and the entire management team of <strong>{{agency_name}}</strong>, we extend our warmest congratulations and a heartfelt welcome to you on becoming a valuable esteemed member of our premium housing development project, <strong>{{property_name}}</strong>.\r\n                    </p>\r\n                    <p>\r\n                        This letter serves as your formal acknowledgment and congratulations on the successful booking of your real estate investment. We have securely registered your property and generated your unique file ledger under our automated municipal portal. Your key properties and allotment metrics are specified below:\r\n                    </p>\r\n\r\n                    <!-- Refined & Highly Colorized standalone Property Allotment Card -->\r\n                    <div class=\"my-4 bg-white border border-emerald-600/30 rounded-lg shadow-md overflow-hidden\">\r\n                        <!-- Highly Prominent Colored Card Header -->\r\n                        <div class=\"bg-gradient-to-r from-emerald-900 to-emerald-950 text-white px-4 py-2 flex items-center justify-between\">\r\n                            <span class=\"text-xs font-black tracking-widest uppercase flex items-center\">\r\n                                <svg xmlns=\"http://www.w3.org/2000/svg\" class=\"h-4 w-4 text-amber-400 mr-2\" fill=\"none\" viewBox=\"0 0 24 24\" stroke=\"currentColor\">\r\n                                    <path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z\" />\r\n                                </svg>\r\n                                OFFICIAL PROPERTY ALLOTMENT RECORD\r\n                            </span>\r\n                            <span class=\"bg-amber-500 text-emerald-950 text-[10px] font-black px-2.5 py-0.5 rounded shadow-sm uppercase tracking-wider\">Status: {{deal_status}}</span>\r\n                        </div>\r\n                        \r\n                        <!-- Premium Inner Metric Grid -->\r\n                        <div class=\"grid grid-cols-4 gap-3 p-3.5 bg-gradient-to-br from-emerald-50/20 via-white to-stone-50 text-xs\">\r\n                            <div class=\"bg-white p-2.5 rounded border border-emerald-100 shadow-sm border-l-4 border-l-emerald-700\">\r\n                                <span class=\"block text-[9px] text-emerald-900/60 uppercase tracking-wider font-extrabold mb-0.5\">File Number</span>\r\n                                <span class=\"font-extrabold text-emerald-950 font-mono text-sm leading-normal\">{{property_file}}</span>\r\n                            </div>\r\n                            <div class=\"bg-white p-2.5 rounded border border-emerald-100 shadow-sm border-l-4 border-l-emerald-700\">\r\n                                <span class=\"block text-[9px] text-emerald-900/60 uppercase tracking-wider font-extrabold mb-0.5\">Area / Size</span>\r\n                                <span class=\"font-bold text-gray-800 text-sm leading-normal\">{{property_area}}</span>\r\n                            </div>\r\n                            <div class=\"bg-white p-2.5 rounded border border-emerald-100 shadow-sm border-l-4 border-l-emerald-700\">\r\n                                <span class=\"block text-[9px] text-emerald-900/60 uppercase tracking-wider font-extrabold mb-0.5\">Category</span>\r\n                                <span class=\"font-bold text-emerald-800 text-sm leading-normal\">{{property_type}}</span>\r\n                            </div>\r\n                            <div class=\"bg-white p-2.5 rounded border border-emerald-100 shadow-sm border-l-4 border-l-emerald-700\">\r\n                                <span class=\"block text-[9px] text-emerald-900/60 uppercase tracking-wider font-extrabold mb-0.5\">Block Name</span>\r\n                                <span class=\"font-bold text-gray-800 text-sm leading-normal\">{{ballot_block_name}}</span>\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n\r\n                    <!-- Prominent, Colorized & Refined Bank Details Card (Installment payments) -->\r\n                    <div class=\"my-4 bg-gradient-to-br from-amber-50/40 via-white to-amber-50/20 border-2 border-dashed border-amber-600/40 rounded-lg relative overflow-hidden shadow-md\">\r\n                        <!-- Golden Emblem Stamp Background decoration -->\r\n                        <div class=\"absolute right-3 top-2.5 opacity-[0.09] pointer-events-none text-amber-900\">\r\n                            <svg xmlns=\"http://www.w3.org/2000/svg\" class=\"h-16 w-16\" fill=\"none\" viewBox=\"0 0 24 24\" stroke=\"currentColor\">\r\n                                <path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"1.5\" d=\"M19 21V5a2 2 0 00-2-2H7a2 2 0 00-2 2v16m14 0h2m-2 0h-5m-9 0H3m2 0h5M9 7h1m-1 4h1m4-4h1m-1 4h1m-5 10v-5a1 1 0 011-1h2a1 1 0 011 1v5m-4 0h4\" />\r\n                            </svg>\r\n                        </div>\r\n                        \r\n                        <!-- Rich Colored Accent Header Block inside card -->\r\n                        <div class=\"bg-gradient-to-r from-amber-600 to-amber-700 text-white px-4 py-1.5 flex items-center justify-between text-[11px] font-extrabold uppercase tracking-widest\">\r\n                            <span class=\"flex items-center\">\r\n                                <span class=\"inline-block w-2 h-2 bg-white rounded-full mr-2\"></span>\r\n                                OFFICIAL INSTALMENT & PAYMENT ACCOUNT DETAILS\r\n                            </span>\r\n                        </div>\r\n                        \r\n                        <div class=\"grid grid-cols-2 gap-x-6 gap-y-2 p-4 text-xs\">\r\n                            <div class=\"space-y-2\">\r\n                                <div class=\"flex items-center border-b border-amber-100/50 pb-1\">\r\n                                    <span class=\"text-amber-900 font-bold w-28 flex-shrink-0 bank-detail-label\">Bank Name:</span>\r\n                                    <span class=\"font-extrabold text-gray-800 flex-1 text-center bank-detail-value\">{{bank_name}}</span>\r\n                                </div>\r\n                                <div class=\"flex items-center border-b border-amber-100/50 pb-1\">\r\n                                    <span class=\"text-amber-900 font-bold w-28 flex-shrink-0 bank-detail-label\">Account Title:</span>\r\n                                    <span class=\"font-extrabold text-gray-800 flex-1 text-center bank-detail-value\">{{bank_account_title}}</span>\r\n                                </div>\r\n                            </div>\r\n                            <div class=\"space-y-2 border-l border-amber-200/50 pl-6\">\r\n                                <div class=\"flex items-center border-b border-amber-100/50 pb-1\">\r\n                                    <span class=\"text-amber-900 font-bold w-32 flex-shrink-0 bank-detail-label\">Account Number:</span>\r\n                                    <span class=\"font-mono font-extrabold text-gray-800 flex-1 text-center bank-detail-value\">{{bank_account_no}}</span>\r\n                                </div>\r\n                                <div class=\"flex items-center border-b border-amber-100/50 pb-1\">\r\n                                    <span class=\"text-amber-900 font-bold w-32 flex-shrink-0 bank-detail-label\">IBAN Number:</span>\r\n                                    <span class=\"font-mono font-extrabold text-gray-800 flex-1 text-center bank-detail-value\">{{bank_iban}}</span>\r\n                                </div>\r\n                            </div>\r\n                        </div>\r\n\r\n                        <!-- Strict security alert warning note regarding official installment accounts -->\r\n                        <div class=\"mx-4 mb-3 p-3 bg-red-50 border border-red-200 rounded text-[10px] text-red-800 font-medium leading-relaxed\">\r\n                            <strong class=\"text-red-900 font-extrabold uppercase tracking-wider block mb-0.5\">⚠️ Security Payment Notice:</strong>\r\n                            Please make payments only to the given official bank account details listed above. Under no circumstances should payments be transferred or handed over to any personal, individual, or other unofficial third-party account. The agency will not accept any responsibility or liability for transactions conducted on unofficial payment channels.\r\n                        </div>\r\n                    </div>\r\n\r\n                    <!-- Gaps after the bank details card added using spacing margins -->\r\n                    <p class=\"pt-4\">\r\n                        We are fundamentally dedicated to maintaining the highest industry standards of construction pace, legal transparency, and community development. We assure you that our development milestones are progressing rapidly, and we are on track to bring this master-planned community to life.\r\n                    </p>\r\n                    <p class=\"pt-2\">\r\n                        Should you have any inquiries regarding installment structures, development timelines, or future allotment ballots, please do not hesitate to reach our corporate customer care desk at <strong>{{agency_phone}}</strong> or write to us directly at <strong>{{agency_email}}</strong>.\r\n                    </p>\r\n                    <p class=\"pt-2\">\r\n                        We sincerely thank you for placing your trust in our organization. Welcome to your secure future.\r\n                    </p>\r\n                    <p class=\"font-bold text-emerald-950 pt-3 leading-tight\">\r\n                        Warm regards,\r\n                    </p>\r\n                    <p class=\"text-xs font-semibold text-emerald-800 leading-none\">\r\n                        The Executive Committee of {{agency_name}}\r\n                    </p>\r\n                </div>\r\n            </div>\r\n\r\n            <!-- Footer: Symmetrical Signatures & Large QR Block -->\r\n            <!-- Removed standard upper lines / borders around QR and Signature sections as requested -->\r\n            <footer class=\"text-[10px] relative mt-16 pb-4\">\r\n                <div class=\"grid grid-cols-12 gap-3 items-end text-center pt-4\">\r\n                    \r\n                    <!-- Left: Chairman Sign (Chief Executive Officer) -->\r\n                    <div class=\"col-span-4 flex flex-col items-center\">\r\n                        <div class=\"h-16\"></div> <!-- Space for Signature -->\r\n                        <span class=\"block border-t border-emerald-900/60 mt-0.5 w-full uppercase text-emerald-950 font-bold\">Chairman Sign</span>\r\n                        <span class=\"block text-gray-600 text-[9px] mt-0.5 font-semibold\" id=\"letter-display-chairman\">Chief Executive Officer</span>\r\n                    </div>\r\n                    \r\n                    <!-- Center: Symmetrical Security QR Block resized to exactly 0.75 x 0.75 inches -->\r\n                    <div class=\"col-span-4 flex flex-col items-center justify-center\">\r\n                        <div class=\"flex items-center justify-center space-x-3 mb-1\">\r\n                            <!-- Symmetrical centered QR Code wrapper configured strictly to 0.75 x 0.75 inches -->\r\n                            <div class=\"border border-emerald-900/20 p-1.5 bg-white flex items-center justify-center rounded shadow-sm flex-shrink-0\" style=\"width: 0.75in; height: 0.75in;\">{{letter_deal_qr}}</div>\r\n                        </div>\r\n                        <span class=\"text-[7.5px] text-gray-500 uppercase tracking-widest font-sans font-bold\">Scan to Verify</span>\r\n                    </div>\r\n\r\n                    <!-- Right: Date -->\r\n                    <div class=\"col-span-4 flex flex-col items-center\">\r\n                        <div class=\"h-16\"></div> <!-- Matching height for layout symmetry -->\r\n                        <span class=\"block border-t border-emerald-900/60 mt-0.5 w-full uppercase text-emerald-950 font-bold\">Date</span>\r\n                        <span class=\"block text-gray-600 text-[9px] mt-0.5\" id=\"letter-display-date\">{{letter_date}}</span>\r\n                    </div>\r\n                </div>\r\n\r\n                <!-- Footer Barcode Verification Line -->\r\n                <div class=\"mt-6 flex flex-col items-center justify-center opacity-85\">\r\n                    <svg id=\"secure-barcode\" class=\"h-5 w-44\" viewBox=\"0 0 100 20\" preserveAspectRatio=\"none\">\r\n                        <!-- Barcode patterns populated dynamically from {{deal_invoice_no}} -->\r\n                    </svg>\r\n                    <span class=\"text-[7px] text-gray-500 font-mono mt-0.5 tracking-widest\">ID-{{deal_invoice_no}}</span>\r\n                </div>\r\n            </footer>\r\n        </div>\r\n\r\n    </div>\r\n\r\n    <script>\r\n        /**\r\n         * Image Fallback Script Block to prevent unrendered template variables \r\n         * or blocked remote assets from hanging layout rendering.\r\n         */\r\n        function handleLogoError(img) {\r\n            img.onerror = null;\r\n            img.src = \"data:image/svg+xml;charset=utf-8,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%20000%2Fsvg%22%20width%3D%22112%22%20height%3D%22112%22%20viewBox%3D%220%200%20112%20112%22%3E%3Crect%20width%3D%22100%25%22%20height%3D%22100%25%22%20fill%3D%22%23064e3b%22%2F%3E%3Ctext%20x%3D%2250%25%22%20y%3D%2250%25%22%20dominant-baseline%3D%22middle%22%20text-anchor%3D%22middle%22%20fill%3D%22%23ffffff%22%20font-family%3D%22sans-serif%22%20font-size%3D%2212%22%20font-weight%3D%22bold%22%3EAGENCY%20LOGO%3C%2Ftext%3E%3C%2Fsvg%3E\";\r\n        }\r\n\r\n        function handlePhotoError(img) {\r\n            img.onerror = null;\r\n            img.src = \"data:image/svg+xml;charset=utf-8,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%20000%2Fsvg%22%20width%3D%2296%22%20height%3D%22128%22%20viewBox%3D%220%200%2096%20128%22%3E%3Crect%20width%3D%22100%25%22%20height%3D%22100%25%22%20fill%3D%22%23e2e8f0%22%2F%3E%3Ccircle%20cx%3D%2248%22%20cy%3D%2245%22%20r%3D%2220%22%20fill%3D%22%2394a3b8%22%2F%3E%3Cpath%20d%3D%22M%2012%20110%20C%2012%2085%2C%2084%2085%2C%2084%20110%20Z%22%20fill%3D%22%2394a3b8%22%2F%3E%3Ctext%20x%3D%2250%25%22%20y%3D%2292%25%22%20dominant-baseline%3D%22middle%22%20text-anchor%3D%22middle%22%20fill%3D%22%23475569%22%20font-family%3D%22sans-serif%22%20font-size%3D%2210%22%20font-weight%3D%22bold%22%3EPHOTO%3C%2Ftext%3E%3C%2Fsvg%3E\";\r\n        }\r\n\r\n        function handleWatermarkError(img) {\r\n            img.onerror = null;\r\n            img.style.display = \'none\';\r\n        }\r\n\r\n        /**\r\n         * Helper parses the unformatted date and returns a \"DD-MMM-YYYY\" string (e.g., 06-Jan-2026)\r\n         */\r\n        function parseAndFormatDate(dateStr) {\r\n            if (!dateStr || dateStr.includes(\'{{\') || dateStr.includes(\'}}\')) {\r\n                return dateStr;\r\n            }\r\n            \r\n            let parsedDate = null;\r\n            let dateObj = new Date(dateStr);\r\n            if (!isNaN(dateObj.getTime())) {\r\n                parsedDate = dateObj;\r\n            } else {\r\n                const parts = dateStr.split(/[-/.]/);\r\n                if (parts.length === 3) {\r\n                    let day, month, year;\r\n                    if (parts[2].length === 4) {\r\n                        day = parseInt(parts[0], 10);\r\n                        month = parseInt(parts[1], 10) - 1;\r\n                        year = parseInt(parts[2], 10);\r\n                    } else if (parts[0].length === 4) {\r\n                        year = parseInt(parts[0], 10);\r\n                        month = parseInt(parts[1], 10) - 1;\r\n                        day = parseInt(parts[2], 10);\r\n                    }\r\n                    \r\n                    if (year && !isNaN(month) && month >= 0 && month < 12 && day && day > 0 && day <= 31) {\r\n                        parsedDate = new Date(year, month, day);\r\n                    }\r\n                }\r\n            }\r\n            \r\n            if (parsedDate && !isNaN(parsedDate.getTime())) {\r\n                const months = [\'Jan\', \'Feb\', \'Mar\', \'Apr\', \'May\', \'Jun\', \'Jul\', \'Aug\', \'Sep\', \'Oct\', \'Nov\', \'Dec\'];\r\n                const formattedDay = String(parsedDate.getDate()).padStart(2, \'0\');\r\n                const formattedMonth = months[parsedDate.getMonth()];\r\n                const formattedYear = parsedDate.getFullYear();\r\n                return `${formattedDay}-${formattedMonth}-${formattedYear}`;\r\n            }\r\n            \r\n            return dateStr;\r\n        }\r\n\r\n        /**\r\n         * Generates a unique secure pseudo-barcode matching the invoice ID sequence\r\n         */\r\n        function generateSecureBarcode() {\r\n            const barcodeSvg = document.getElementById(\'secure-barcode\');\r\n            if (!barcodeSvg) return;\r\n            \r\n            const rawId = \"{{deal_invoice_no}}\".trim();\r\n            const cleanId = rawId.includes(\'{{\') ? \'0100234001920\' : rawId.replace(/[^0-9]/g, \'\');\r\n            \r\n            let innerHtml = \'<rect width=\"100\" height=\"20\" fill=\"#ffffff\"/>\';\r\n            let cursor = 5;\r\n            \r\n            for (let i = 0; i < 30; i++) {\r\n                const charCodeVal = cleanId.charCodeAt(i % cleanId.length) || 103;\r\n                const barWidth = (charCodeVal % 2 === 0) ? 1.5 : 0.6;\r\n                const gapWidth = (charCodeVal % 3 === 0) ? 1.2 : 0.8;\r\n                \r\n                innerHtml += `<rect x=\"${cursor}\" y=\"0\" width=\"${barWidth}\" height=\"20\" fill=\"#111827\"/>`;\r\n                cursor += barWidth + gapWidth;\r\n                if (cursor > 95) break;\r\n            }\r\n            barcodeSvg.innerHTML = innerHtml;\r\n        }\r\n\r\n        function initWelcomeLetter() {\r\n            // Secure Barcode Generator\r\n            generateSecureBarcode();\r\n\r\n            // Date Format initializations\r\n            const dateElements = [\'display-date\', \'letter-display-date\'];\r\n            dateElements.forEach(function(id) {\r\n                const element = document.getElementById(id);\r\n                if (element) {\r\n                    const rawDate = element.textContent.trim();\r\n                    element.textContent = parseAndFormatDate(rawDate);\r\n                }\r\n            });\r\n        }\r\n\r\n        if (document.readyState !== \'loading\') {\r\n            initWelcomeLetter();\r\n        } else {\r\n            document.addEventListener(\'DOMContentLoaded\', initWelcomeLetter);\r\n        }\r\n    </script>\r\n</body>\r\n</html>', 'RLT_BOOKING', 'Published', 'Yes', '', 'letter_signatures', '', 'letter_signatures');
INSERT INTO `templates` (`id`, `name`, `description`, `type`, `status`, `is_new`, `ceo_signature`, `ceo_signature_dir`, `chairman_signature`, `chairman_signature_dir`) VALUES
(34, 'New Welcome Letter', '<!DOCTYPE html>\r\n<html lang=\"en\">\r\n<head>\r\n    <meta charset=\"UTF-8\">\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n    <title>{{agency_name}} - Welcome Letter</title>\r\n    \r\n    <!-- Tailwind CSS -->\r\n    <script src=\"https://cdn.tailwindcss.com\"></script>\r\n    \r\n    <!-- Urdu Font Support -->\r\n    <link href=\"https://fonts.googleapis.com/css2?family=Noto+Nastaliq+Urdu:wght@400..700&display=swap\" rel=\"stylesheet\">\r\n    \r\n    <style>\r\n        .form-container {\r\n            max-width: 800px; \r\n            font-family: \'Times New Roman\', serif; \r\n            margin: 4px auto; \r\n            background-color: white;\r\n            padding: 1.25rem; \r\n            border-radius: 0.5rem;\r\n            box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1);\r\n            color: #1f2937;\r\n            \r\n            /* Custom double-line repeating floral frame border pattern matching image_1acdb4.png */\r\n            border: 24px solid transparent;\r\n            border-image-source: url(\"data:image/svg+xml;charset=utf-8,%3Csvg xmlns=\'http://www.w3.org/2000/svg\' width=\'72\' height=\'72\' viewBox=\'0 0 72 72\'%3E%3Cdefs%3E%3Cg id=\'flower\'%3E%3Ccircle cx=\'12\' cy=\'12\' r=\'3.5\' fill=\'%23064e3b\'/%3E%3Cpath d=\'M12,12 C10,9 10,4 12,4 C14,4 14,9 12,12 Z\' fill=\'%23064e3b\'/%3E%3Cpath d=\'M12,12 C10,15 10,20 12,20 C14,20 14,15 12,12 Z\' fill=\'%23064e3b\'/%3E%3Cpath d=\'M12,12 C9,10 4,10 4,12 C4,14 9,14 12,12 Z\' fill=\'%23064e3b\'/%3E%3Cpath d=\'M12,12 C15,10 20,10 20,12 C20,14 15,14 12,12 Z\' fill=\'%23064e3b\'/%3E%3Cpath d=\'M12,12 C10,11 6.5,7.5 7.5,6.5 C8.5,5.5 11,10 12,12 Z\' fill=\'%23064e3b\'/%3E%3Cpath d=\'M12,12 C11,10 14.5,6.5 15.5,7.5 C16.5,8.5 12,11 12,12 Z\' fill=\'%23064e3b\'/%3E%3Cpath d=\'M12,12 C11,14 7.5,15.5 6.5,14.5 C5.5,13.5 10,11 12,12 Z\' fill=\'%23064e3b\'/%3E%3Cpath d=\'M12,12 C13,14 16.5,14.5 15.5,15.5 C14.5,16.5 11,13 12,12 Z\' fill=\'%23064e3b\'/%3E%3C/g%3E%3C/defs%3E%3Cpath d=\'M24,2 L2,2 L2,24\' fill=\'none\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cpath d=\'M24,22 L22,22 L22,24\' fill=\'none\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cuse href=\'%23flower\' x=\'0\' y=\'0\'/%3E%3Cline x1=\'24\' y1=\'2\' x2=\'48\' y2=\'2\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cline x1=\'24\' y1=\'22\' x2=\'48\' y2=\'22\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cuse href=\'%23flower\' x=\'24\' y=\'0\'/%3E%3Cpath d=\'M48,2 L70,2 L70,24\' fill=\'none\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cpath d=\'M48,22 L50,22 L50,24\' fill=\'none\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cuse href=\'%23flower\' x=\'48\' y=\'0\'/%3E%3Cline x1=\'2\' y1=\'24\' x2=\'2\' y2=\'48\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cline x1=\'22\' y1=\'24\' x2=\'22\' y2=\'48\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cuse href=\'%23flower\' x=\'0\' y=\'24\'/%3E%3Cline x1=\'70\' y1=\'24\' x2=\'70\' y2=\'48\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cline x1=\'50\' y1=\'24\' x2=\'50\' y2=\'48\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cuse href=\'%23flower\' x=\'48\' y=\'24\'/%3E%3Cpath d=\'M2,48 L2,70 L24,70\' fill=\'none\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cpath d=\'M22,48 L22,50 L24,50\' fill=\'none\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cuse href=\'%23flower\' x=\'0\' y=\'48\'/%3E%3Cline x1=\'24\' y1=\'50\' x2=\'48\' y2=\'50\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cline x1=\'24\' y1=\'70\' x2=\'48\' y2=\'70\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cuse href=\'%23flower\' x=\'24\' y=\'48\'/%3E%3Cpath d=\'M70,48 L70,70 L48,70\' fill=\'none\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cpath d=\'M50,48 L50,50 L48,50\' fill=\'none\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cuse href=\'%23flower\' x=\'48\' y=\'48\'/%3E%3C/svg%3E\");\r\n            border-image-slice: 24;\r\n            border-image-repeat: repeat;\r\n            \r\n            position: relative;\r\n            overflow: hidden;\r\n        }\r\n        \r\n        /* Centered Background Watermark style */\r\n        .watermark {\r\n            position: absolute;\r\n            top: 50%;\r\n            left: 50%;\r\n            transform: translate(-50%, -50%);\r\n            width: 320px;\r\n            height: 320px;\r\n            opacity: 0.04; /* Subtle backdrop presence */\r\n            pointer-events: none;\r\n            z-index: 0;\r\n            user-select: none;\r\n        }\r\n\r\n        /* Form content wrapper to stay above watermark */\r\n        .form-content-wrapper {\r\n            position: relative;\r\n            z-index: 10;\r\n        }\r\n\r\n        .form-section-title {\r\n            background-color: #064e3b; /* Premium Forest Green background */\r\n            color: #ffffff; /* Crisp white text */\r\n            font-weight: 700;\r\n            font-size: 0.85rem;\r\n            padding: 0.25rem 0.75rem;\r\n            margin-bottom: 0.5rem;\r\n            border-left: 4px solid #d97706; /* Solid amber gold accent bar */\r\n            border-radius: 0 0.25rem 0.25rem 0;\r\n            letter-spacing: 0.05em;\r\n            display: inline-block;\r\n        }\r\n        \r\n        .info-label {\r\n            font-weight: 700;\r\n            color: #064e3b;\r\n        }\r\n\r\n        /* --- PRINT STYLING & COLOR PRESERVATION --- */\r\n        @media print {\r\n            @page {\r\n                size: A4 portrait;\r\n                margin: 0;\r\n            }\r\n            body { \r\n                margin: 0; \r\n                padding: 0; \r\n                background: none; \r\n            }\r\n            * {\r\n                -webkit-print-color-adjust: exact !important;\r\n                print-color-adjust: exact !important;\r\n            }\r\n            .form-container {\r\n                max-width: 100%;\r\n                width: 100%;\r\n                box-shadow: none;\r\n                border: 24px solid transparent !important;\r\n                border-image-source: url(\"data:image/svg+xml;charset=utf-8,%3Csvg xmlns=\'http://www.w3.org/2000/svg\' width=\'72\' height=\'72\' viewBox=\'0 0 72 72\'%3E%3Cdefs%3E%3Cg id=\'flower\'%3E%3Ccircle cx=\'12\' cy=\'12\' r=\'3.5\' fill=\'%23064e3b\'/%3E%3Cpath d=\'M12,12 C10,9 10,4 12,4 C14,4 14,9 12,12 Z\' fill=\'%23064e3b\'/%3E%3Cpath d=\'M12,12 C10,15 10,20 12,20 C14,20 14,15 12,12 Z\' fill=\'%23064e3b\'/%3E%3Cpath d=\'M12,12 C9,10 4,10 4,12 C4,14 9,14 12,12 Z\' fill=\'%23064e3b\'/%3E%3Cpath d=\'M12,12 C15,10 20,10 20,12 C20,14 15,14 12,12 Z\' fill=\'%23064e3b\'/%3E%3Cpath d=\'M12,12 C10,11 6.5,7.5 7.5,6.5 C8.5,5.5 11,10 12,12 Z\' fill=\'%23064e3b\'/%3E%3Cpath d=\'M12,12 C11,10 14.5,6.5 15.5,7.5 C16.5,8.5 12,11 12,12 Z\' fill=\'%23064e3b\'/%3E%3Cpath d=\'M12,12 C11,14 7.5,15.5 6.5,14.5 C5.5,13.5 10,11 12,12 Z\' fill=\'%23064e3b\'/%3E%3Cpath d=\'M12,12 C13,14 16.5,14.5 15.5,15.5 C14.5,16.5 11,13 12,12 Z\' fill=\'%23064e3b\'/%3E%3C/g%3E%3C/defs%3E%3Cpath d=\'M24,2 L2,2 L2,24\' fill=\'none\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cpath d=\'M24,22 L22,22 L22,24\' fill=\'none\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cuse href=\'%23flower\' x=\'0\' y=\'0\'/%3E%3Cline x1=\'24\' y1=\'2\' x2=\'48\' y2=\'2\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cline x1=\'24\' y1=\'22\' x2=\'48\' y2=\'22\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cuse href=\'%23flower\' x=\'24\' y=\'0\'/%3E%3Cpath d=\'M48,2 L70,2 L70,24\' fill=\'none\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cpath d=\'M48,22 L50,22 L50,24\' fill=\'none\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cuse href=\'%23flower\' x=\'48\' y=\'0\'/%3E%3Cline x1=\'2\' y1=\'24\' x2=\'2\' y2=\'48\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cline x1=\'22\' y1=\'24\' x2=\'22\' y2=\'48\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cuse href=\'%23flower\' x=\'0\' y=\'24\'/%3E%3Cline x1=\'70\' y1=\'24\' x2=\'70\' y2=\'48\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cline x1=\'50\' y1=\'24\' x2=\'50\' y2=\'48\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cuse href=\'%23flower\' x=\'48\' y=\'24\'/%3E%3Cpath d=\'M2,48 L2,70 L24,70\' fill=\'none\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cpath d=\'M22,48 L22,50 L24,50\' fill=\'none\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cuse href=\'%23flower\' x=\'0\' y=\'48\'/%3E%3Cline x1=\'24\' y1=\'50\' x2=\'48\' y2=\'50\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cline x1=\'24\' y1=\'70\' x2=\'48\' y2=\'70\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cuse href=\'%23flower\' x=\'24\' y=\'48\'/%3E%3Cpath d=\'M70,48 L70,70 L48,70\' fill=\'none\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cpath d=\'M50,48 L50,50 L48,50\' fill=\'none\' stroke=\'%23064e3b\' stroke-width=\'1.5\'/%3E%3Cuse href=\'%23flower\' x=\'48\' y=\'48\'/%3E%3C/svg%3E\") !important;\r\n                border-image-slice: 24 !important;\r\n                border-image-repeat: repeat !important;\r\n                padding: 0.5rem;\r\n                margin: 0;\r\n            }\r\n            .form-section-title {\r\n                background-color: #064e3b !important;\r\n                color: #ffffff !important;\r\n                border-left: 4px solid #d97706 !important;\r\n                display: inline-block !important;\r\n            }\r\n            .watermark {\r\n                opacity: 0.04 !important;\r\n            }\r\n        }\r\n    \r\n        /* White Villas compact A4 welcome letter print/PDF fit */ /* wv-welcome-a4-fit-css */\r\n        .wv-welcome-a4{width:210mm!important;max-width:210mm!important;margin:0 auto!important;padding:5mm!important;border-width:12px!important;border-image-slice:24!important;box-shadow:none!important;font-size:12px!important;line-height:1.85!important;}\r\n        .wv-welcome-a4 .watermark{width:220px!important;height:220px!important;}\r\n        .wv-welcome-a4 header{margin-bottom:.35rem!important;padding:.45rem!important;padding-bottom:.45rem!important;}\r\n        .wv-welcome-a4 header .w-28{width:5rem!important;}\r\n        .wv-welcome-a4 header .h-28{height:5rem!important;}\r\n        .wv-welcome-a4 header .w-24{width:4.1rem!important;}\r\n        .wv-welcome-a4 header .h-32{height:5.3rem!important;}\r\n        .wv-welcome-a4 h1{font-size:1.45rem!important;line-height:1.85!important;margin:0!important;}\r\n        .wv-welcome-a4 h2{font-size:.92rem!important;line-height:1.85!important;margin:0!important;}\r\n        .wv-welcome-a4 .text-center.mb-6{margin-bottom:.45rem!important;}\r\n        .wv-welcome-a4 .bg-stone-50\\/50{padding:.55rem!important;margin-bottom:.35rem!important;}\r\n        .wv-welcome-a4 .my-4{margin-top:.35rem!important;margin-bottom:.35rem!important;}\r\n        .wv-welcome-a4 .mb-6{margin-bottom:.45rem!important;}\r\n        .wv-welcome-a4 .mb-4{margin-bottom:.35rem!important;}\r\n        .wv-welcome-a4 .mt-2{margin-top:.25rem!important;}\r\n        .wv-welcome-a4 .mt-1\\.5{margin-top:.2rem!important;}\r\n        .wv-welcome-a4 .p-5{padding:.55rem!important;}\r\n        .wv-welcome-a4 .p-4{padding:.55rem!important;}\r\n        .wv-welcome-a4 .p-3.5{padding:.45rem!important;}\r\n        .wv-welcome-a4 .p-3{padding:.4rem!important;}\r\n        .wv-welcome-a4 .p-2\\.5{padding:.35rem!important;}\r\n        .wv-welcome-a4 .px-8{padding-left:1.2rem!important;padding-right:1.2rem!important;}\r\n        .wv-welcome-a4 .py-1\\.5{padding-top:.25rem!important;padding-bottom:.25rem!important;}\r\n        .wv-welcome-a4 .gap-3{gap:.35rem!important;}\r\n        .wv-welcome-a4 .gap-x-6{column-gap:.7rem!important;}\r\n        .wv-welcome-a4 .gap-y-2{row-gap:.25rem!important;}\r\n        .wv-welcome-a4 .space-y-2>:not([hidden])~:not([hidden]){margin-top:.25rem!important;}\r\n        .wv-welcome-a4 .space-y-3>:not([hidden])~:not([hidden]){margin-top:.28rem!important;}\r\n        .wv-welcome-a4 p{margin-top:0!important;margin-bottom:.25rem!important;line-height:1.85!important;}\r\n        .wv-welcome-a4 .text-base{font-size:.82rem!important;line-height:1.85!important;}\r\n        .wv-welcome-a4 .text-sm{font-size:.72rem!important;line-height:1.85!important;}\r\n        .wv-welcome-a4 .text-xs{font-size:.72rem!important;line-height:1.85!important;}\r\n        .wv-welcome-a4 .text-\\[10px\\]{font-size:.52rem!important;line-height:1.85!important;}\r\n        .wv-welcome-a4 .text-\\[9px\\]{font-size:.5rem!important;line-height:1.85!important;}\r\n        .wv-welcome-a4 .text-\\[7\\.5px\\],.wv-welcome-a4 .text-\\[7px\\]{font-size:.42rem!important;line-height:1.85!important;}\r\n        .wv-welcome-a4 footer{margin-top:.35rem!important;padding-bottom:0!important;}\r\n        .wv-welcome-a4 footer .grid{padding-top:.35rem!important;gap:.35rem!important;}\r\n        .wv-welcome-a4 footer .h-16{height:.28in!important;}\r\n        .wv-welcome-a4 footer .mt-6{margin-top:.22rem!important;}\r\n        .wv-welcome-a4 footer .mb-1{margin-bottom:.1rem!important;}\r\n        .wv-welcome-a4 #secure-barcode{height:10px!important;width:118px!important;}\r\n        .wv-welcome-a4 [style*=\"0.75in\"],.wv-welcome-a4 [style*=\"1.25in\"]{width:.75in!important;height:.75in!important;padding:2px!important;}\r\n        .wv-welcome-a4 [style*=\"0.75in\"] img,.wv-welcome-a4 [style*=\"1.25in\"] img{width:100%!important;height:100%!important;filter:contrast(1.45)!important;image-rendering:pixelated!important;}\r\n        @media print{\r\n            @page{size:A4 portrait;margin:0;}\r\n            html,body{width:210mm!important;height:297mm!important;margin:0!important;padding:0!important;background:#fff!important;overflow:hidden!important;}\r\n            .wv-welcome-a4{width:210mm!important;max-width:210mm!important;height:297mm!important;max-height:297mm!important;margin:0!important;padding:5mm!important;border-width:12px!important;border-image-slice:24!important;box-shadow:none!important;overflow:hidden!important;border-image-repeat:repeat!important;}\r\n            .form-section-title{padding:.18rem .5rem!important;margin-bottom:.25rem!important;}\r\n        }\r\n    \r\n        /* Center bank detail values only */ /* wv-bank-center-fix */\r\n        .wv-welcome-a4 .bank-detail-value{display:block!important;flex:1 1 auto!important;text-align:center!important;}\r\n        .wv-welcome-a4 .bank-detail-label{display:block!important;flex:0 0 7.5rem!important;white-space:nowrap!important;}\r\n    \r\n        /* Polished full-page print positioning */ /* wv-welcome-print-polish */\r\n        .wv-welcome-a4 .form-content-wrapper{height:100%!important;min-height:100%!important;display:flex!important;flex-direction:column!important;}\r\n        .wv-welcome-a4 header{flex:0 0 auto!important;}\r\n        .wv-welcome-a4 .form-content-wrapper>div:not(.watermark):not(header):not(footer){flex:0 0 auto!important;}\r\n        .wv-welcome-a4 footer{margin-top:auto!important;padding-top:7mm!important;padding-bottom:1.5mm!important;flex:0 0 auto!important;}\r\n        .wv-welcome-a4 footer .grid{padding-top:3mm!important;align-items:end!important;border-top:none!important;} /* Changed border-top to none!important to remove top line on footer/QR code section */\r\n        .wv-welcome-a4 footer .h-16{height:.34in!important;}\r\n        .wv-welcome-a4 footer .border-t{border-top-color:transparent!important;} /* Force border transparent */\r\n        .wv-welcome-a4 footer #secure-barcode{margin-top:0!important;}\r\n        .wv-welcome-a4 footer .mt-6{margin-top:.15rem!important;}\r\n        .wv-welcome-a4 footer .mt-0.5{margin-top:.08rem!important;}\r\n        .wv-welcome-a4 footer .tracking-widest{letter-spacing:.08em!important;}\r\n        .wv-welcome-a4 .bg-stone-50\\/50{border-color:#d1fae5!important;box-shadow:0 1px 5px rgba(6,78,59,.08)!important;}\r\n        .wv-welcome-a4 .bg-gradient-to-r.from-emerald-900{background:#064e3b!important;}\r\n        .wv-welcome-a4 .bg-gradient-to-r.from-amber-600{background:#c76300!important;}\r\n        .wv-welcome-a4 .bg-white.p-2\\.5{min-height:38px!important;}\r\n        .wv-welcome-a4 .bank-detail-value{white-space:nowrap!important;overflow:hidden!important;text-overflow:ellipsis!important;}\r\n        @media print{\r\n            .wv-welcome-a4 .form-content-wrapper{height:100%!important;min-height:100%!important;display:flex!important;flex-direction:column!important;}\r\n            .wv-welcome-a4 footer{margin-top:auto!important;padding-top:7mm!important;padding-bottom:1.5mm!important;}\r\n        }\r\n    </style>\r\n<style type=\"text/css\" id=\"wv-urdu-font-definitions\">\n@font-face {\n    font-family: \'Jameel Noori Nastaleeq\';\n    src: url(\'/whitevillas/fonts/JameelNooriNastaleeq.ttf\') format(\'truetype\'),\n         url(\'/fonts/JameelNooriNastaleeq.ttf\') format(\'truetype\'),\n         url(\'../fonts/JameelNooriNastaleeq.ttf\') format(\'truetype\');\n    font-weight: normal;\n    font-style: normal;\n    font-display: swap;\n}\n@font-face {\n    font-family: \'Jameel Noori Nastaleeq Kasheeda\';\n    src: url(\'/whitevillas/fonts/JameelNooriNastaleeqKasheeda.ttf\') format(\'truetype\'),\n         url(\'/fonts/JameelNooriNastaleeqKasheeda.ttf\') format(\'truetype\'),\n         url(\'../fonts/JameelNooriNastaleeqKasheeda.ttf\') format(\'truetype\');\n    font-weight: normal;\n    font-style: normal;\n    font-display: swap;\n}\n*, *:before, *:after {\n    -webkit-print-color-adjust: exact !important;\n    print-color-adjust: exact !important;\n    color-adjust: exact !important;\n}\n[lang=\"ur\"], [dir=\"rtl\"], .urdu-text, .ashtam-page, .letter-ur, .urdu-body, .urdu-legal {\n    font-family: \'Jameel Noori Nastaleeq\', \'Noto Nastaliq Urdu\', \'Nafees Nastaleeq\', serif !important;\n    line-height: 1.85 !important;\n    letter-spacing: 0 !important;\n    word-spacing: 0 !important;\n}\n[lang=\"ur\"] h1, [lang=\"ur\"] h2, [lang=\"ur\"] h3, [lang=\"ur\"] h4, [lang=\"ur\"] h5, [lang=\"ur\"] h6,\n[dir=\"rtl\"] h1, [dir=\"rtl\"] h2, [dir=\"rtl\"] h3, [dir=\"rtl\"] h4, [dir=\"rtl\"] h5, [dir=\"rtl\"] h6,\n.ashtam-page h1, .ashtam-page h2, .ashtam-page h3, .ashtam-page h4,\n.urdu-heading, .ashtam-heading, .document-title, .document-subtitle, .section-title, .sign-title, .bismillah {\n    font-family: \'Jameel Noori Nastaleeq Kasheeda\', \'Jameel Noori Nastaleeq\', \'Noto Nastaliq Urdu\', serif !important;\n    font-weight: normal !important;\n    line-height: 1.5 !important;\n}\n[lang=\"ur\"] p, [lang=\"ur\"] li, [lang=\"ur\"] td, [lang=\"ur\"] th, [lang=\"ur\"] span,\n[dir=\"rtl\"] p, [dir=\"rtl\"] li, [dir=\"rtl\"] td, [dir=\"rtl\"] th, [dir=\"rtl\"] span,\n.ashtam-page p, .ashtam-page li, .ashtam-page td, .ashtam-page th,\n.urdu-body p, .clause, .note-box, .amount-box {\n    font-family: \'Jameel Noori Nastaleeq\', \'Noto Nastaliq Urdu\', \'Nafees Nastaleeq\', serif !important;\n    line-height: 1.85 !important;\n}\n@media print {\n    @page { size: auto; margin: 0; }\n    html, body {\n        background: #ffffff !important;\n        color: #000000 !important;\n        margin: 0 !important;\n        padding: 0 !important;\n    }\n    .ashtam-page, .page, .form-container, .container, .letter-preview-print {\n        margin: 0 auto !important;\n        box-shadow: none !important;\n        -webkit-print-color-adjust: exact !important;\n        print-color-adjust: exact !important;\n        color-adjust: exact !important;\n    }\n}\n</style></head>\r\n\r\n<body class=\"bg-gray-100 p-2 sm:p-6 flex justify-center\" style=\"margin:0!important;padding:0!important;background:#fff!important;display:block!important;\">\r\n\r\n    <div class=\"form-container w-full wv-welcome-a4\">\r\n        \r\n        <!-- Centered Background Watermark -->\r\n        <div class=\"watermark flex items-center justify-center\">\r\n            <img id=\"watermark-logo\" src=\"{{agency_logo_url}}\" \r\n                 alt=\"Watermark Logo\" class=\"w-full h-full object-contain\" onerror=\"handleWatermarkError(this)\">\r\n        </div>\r\n\r\n        <div class=\"form-content-wrapper\">\r\n            <header class=\"mb-3 flex flex-row items-center justify-between pb-3 relative overflow-hidden rounded-lg p-3 bg-emerald-50/10 border border-emerald-100/30\">\r\n                <!-- Panoramic Pakistani Monuments SVG Watermark Background -->\r\n                <div class=\"absolute inset-0 pointer-events-none opacity-[0.06] z-0 select-none flex items-end\">\r\n                    <svg class=\"w-full h-full\" viewBox=\"0 0 1000 120\" preserveAspectRatio=\"none\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\">\r\n                        <line x1=\"0\" y1=\"120\" x2=\"1000\" y2=\"120\" stroke=\"#064e3b\" stroke-width=\"2\" />\r\n                        <path d=\"M15,120 L25,108 L28,108 L31,105 L31,100 L34,100 L35,80 L32,80 L32,77 L38,77 L39,55 L35,55 L35,52 L41,52 L43,20 C43,15 47,15 47,20 L49,52 L55,52 L55,55 L51,55 L52,77 L58,77 L58,80 L55,80 L56,100 L59,100 L59,105 L62,108 L65,108 L75,120 Z\" fill=\"#064e3b\" />\r\n                        <path d=\"M100,120 L100,60 L112,60 L112,50 L108,50 L108,45 L124,45 L124,50 L120,50 L120,60 L135,60 L135,75 Q145,62 155,75 L155,120 L147,120 L147,85 Q145,76 138,85 L138,120 L130,120 L130,70 L125,70 L125,120 Z\" fill=\"#064e3b\" />\r\n                        <path d=\"M155,120 L155,75 Q165,62 175,75 L175,60 L190,60 L190,50 L186,50 L186,45 L202,45 L202,50 L198,50 L198,60 L210,60 L210,120 L185,120 L185,70 L180,70 L180,120 Z\" fill=\"#064e3b\" />\r\n                        <path d=\"M220,120 L220,30 L216,30 L211,30 L211,25 L219,25 L220,15 C220,10 226,10 226,15 L227,25 L235,25 L235,30 L231,30 L231,120 Z\" fill=\"#064e3b\" />\r\n                        <path d=\"M255,120 L255,90 Q280,65 305,90 L305,120 Z\" fill=\"#064e3b\" />\r\n                        <path d=\"M310,120 L310,85 C310,50 360,50 360,85 L360,120 Z\" fill=\"#064e3b\" />\r\n                        <path d=\"M365,120 L365,90 Q390,65 415,90 L415,120 Z\" fill=\"#064e3b\" />\r\n                        <path d=\"M430,120 L430,30 L426,30 L421,30 L421,25 L429,25 L430,15 C430,10 436,10 436,15 L437,25 L445,25 L445,30 L441,30 L441,120 Z\" fill=\"#064e3b\" />\r\n                        <path d=\"M480,120 L485,85 L500,85 L505,65 L525,65 L527,50 C527,45 533,45 533,50 L535,65 L555,65 L560,85 L575,85 L580,120 Z\" fill=\"#064e3b\" />\r\n                        <path d=\"M600,120 L615,70 L675,70 L690,120 Z\" fill=\"#064e3b\" />\r\n                        <path d=\"M622,70 C622,45 668,45 668,70 Z\" fill=\"#064e3b\" />\r\n                        <path d=\"M635,120 L635,95 C635,85 655,85 655,95 L655,120 Z\" fill=\"#ffffff\" opacity=\"0.6\" />\r\n                        <path d=\"M710,120 C710,95 725,80 740,85 C730,102 720,112 717,120 Z\" fill=\"#064e3b\" />\r\n                        <path d=\"M725,120 C730,75 755,60 767,70 C755,92 743,110 740,120 Z\" fill=\"#064e3b\" />\r\n                        <circle cx=\"765\" cy=\"100\" r=\"6\" fill=\"#064e3b\" />\r\n                        <path d=\"M800,120 C795,75 770,60 758,70 C770,92 782,110 785,120 Z\" fill=\"#064e3b\" />\r\n                        <path d=\"M815,120 C815,95 800,80 785,85 C795,102 805,112 808,120 Z\" fill=\"#064e3b\" />\r\n                        <path d=\"M845,120 L845,15 L848,15 L848,120 Z\" fill=\"#064e3b\" />\r\n                        <path d=\"M860,120 L910,55 L960,120 Z\" fill=\"#064e3b\" />\r\n                        <line x1=\"910\" y1=\"55\" x2=\"910\" y2=\"45\" stroke=\"#064e3b\" stroke-width=\"2\" />\r\n                        <path d=\"M975,120 L975,15 L978,15 L978,120 Z\" fill=\"#064e3b\" />\r\n                        <line x1=\"885\" y1=\"120\" x2=\"910\" y2=\"55\" stroke=\"#ffffff\" stroke-width=\"1.5\" opacity=\"0.3\" />\r\n                        <line x1=\"935\" y1=\"120\" x2=\"910\" y2=\"55\" stroke=\"#ffffff\" stroke-width=\"1.5\" opacity=\"0.3\" />\r\n                    </svg>\r\n                </div>\r\n\r\n                <!-- Left logo wrapper -->\r\n                <div class=\"w-28 flex-shrink-0 flex items-center justify-start z-10 relative\">\r\n                    <div class=\"w-28 h-28 flex-shrink-0 flex items-center justify-center bg-transparent\">\r\n                        <img id=\"agency-logo\" src=\"{{agency_logo_url}}\" \r\n                             alt=\"Agency Logo\" class=\"w-full h-full object-contain p-1.5\" onerror=\"handleLogoError(this)\">\r\n                    </div>\r\n                </div>\r\n\r\n                <!-- Center Header Texts -->\r\n                <div class=\"flex-1 flex flex-col items-center justify-center text-center px-4 z-10 relative\">\r\n                    <h1 class=\"text-3xl sm:text-4xl font-black tracking-wide text-emerald-950 border-b-2 border-amber-500/40 pb-1 leading-tight inline-block\">{{agency_name}}</h1> \r\n                    <p class=\"text-sm font-medium text-gray-700 mt-1.5 max-w-md\">{{agency_address}}</p>\r\n\r\n                    <div class=\"text-xs font-semibold text-gray-600 mt-2 gap-x-4 flex flex-wrap justify-center\">\r\n                        <div>\r\n                            <span class=\"font-extrabold text-emerald-800\">Email:</span> \r\n                            <span>{{agency_email}}</span>\r\n                        </div>\r\n                        <div>\r\n                            <span class=\"font-extrabold text-emerald-800\">Mobile:</span> \r\n                            <span>{{agency_phone}}</span>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n                \r\n                <!-- Right photo wrapper -->\r\n                <div class=\"w-28 flex-shrink-0 flex items-center justify-end z-10 relative\">\r\n                    <div class=\"w-24 h-32 border-2 border-emerald-800 flex items-center justify-center text-emerald-700/60 text-[10px] bg-emerald-50/20 overflow-hidden rounded shadow-md\">\r\n                        <img id=\"client-photo\" src=\"{{client_profile_photo_url}}\" alt=\"Applicant Photo\" class=\"w-full h-full object-cover\" onerror=\"handlePhotoError(this)\">\r\n                    </div>\r\n                </div>\r\n            </header>\r\n\r\n            <!-- Document Title & Reference ID -->\r\n            <div class=\"flex justify-between items-center text-xs font-extrabold mb-4 pb-1 border-b border-emerald-100\">\r\n                <div>\r\n                    <span class=\"text-emerald-700 font-extrabold\">Reference ID:</span> \r\n                    <span class=\"text-gray-800 ml-1 font-bold\">{{letter_ref_no}}</span>\r\n                </div>\r\n                <div>\r\n                    <span class=\"text-emerald-700 font-extrabold\">File No:</span> \r\n                    <span class=\"text-emerald-600 ml-1 font-bold\">{{property_file}}</span>\r\n                </div>\r\n            </div>\r\n\r\n            <!-- Welcome Letter Heading Banner (Centered Stylized Badge) -->\r\n            <div class=\"text-center mb-6\">\r\n                <div class=\"inline-block bg-emerald-900 text-white py-1.5 px-8 rounded-lg shadow-sm border-b-4 border-amber-500\">\r\n                    <h2 class=\"text-lg font-black uppercase tracking-widest text-amber-400 leading-normal\">WELCOME LETTER</h2>\r\n                </div>\r\n            </div>\r\n\r\n            <!-- Congratulatory Letter Content Section -->\r\n            <div class=\"bg-stone-50/50 rounded-lg p-5 border border-emerald-100/50 mb-6 relative\">\r\n                <!-- Secondary subtle background watermark logo on below text -->\r\n                <div class=\"absolute inset-0 flex items-center justify-center pointer-events-none opacity-[0.035] select-none z-0\">\r\n                    <img src=\"{{agency_logo_url}}\" class=\"w-80 h-80 object-contain\" onerror=\"this.style.display=\'none\'\">\r\n                </div>\r\n\r\n                <!-- Date and Salutation -->\r\n                <div class=\"flex justify-between items-center mb-4 text-sm font-semibold relative z-10\">\r\n                    <div class=\"text-emerald-950\">\r\n                        Date: <span id=\"display-date\" class=\"font-bold text-gray-800\">{{letter_date}}</span>\r\n                    </div>\r\n                    <div class=\"text-emerald-950\">\r\n                        File Ref No: <span class=\"font-bold text-gray-800\">{{property_file}}</span>\r\n                    </div>\r\n                </div>\r\n\r\n                <!-- Highly Prominent Mailing & Addressee Block structured for clear preview and physical mailing -->\r\n                <div class=\"mb-6 relative z-10 p-4 bg-gradient-to-br from-emerald-50/30 via-white to-emerald-50/15 border border-emerald-100/70 rounded-lg shadow-sm\">\r\n                    <span class=\"block text-[9px] uppercase tracking-widest font-black text-emerald-800 mb-1.5\">RECIPIENT &amp; MAILING DETAILS</span>\r\n                    \r\n                    <h3 class=\"text-base font-bold text-emerald-950 mb-1.5\">Dear {{client_name}},</h3>\r\n                    \r\n                    <div class=\"space-y-1.5 text-xs text-gray-700 font-medium\">\r\n                        <p class=\"leading-relaxed\">\r\n                            <span class=\"text-emerald-800 font-extrabold uppercase text-[10px] tracking-wide mr-1\">Address:</span> \r\n                            <strong class=\"text-gray-900 font-semibold\">{{client_address}}</strong>\r\n                        </p>\r\n                        <div class=\"flex flex-wrap gap-x-6 gap-y-1\">\r\n                            <div>\r\n                                <span class=\"text-emerald-800 font-extrabold uppercase text-[10px] tracking-wide mr-1\">CNIC:</span> \r\n                                <strong class=\"text-gray-800 font-semibold font-mono\">{{client_cnic}}</strong>\r\n                            </div>\r\n                            <div>\r\n                                <span class=\"text-emerald-800 font-extrabold uppercase text-[10px] tracking-wide mr-1\">Mobile:</span> \r\n                                <strong class=\"text-gray-800 font-semibold font-mono\">{{client_mobile}}</strong>\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                    \r\n                    <!-- Added Urdu greeting with proper Urdu Jameel Noori Nastaliq / Noto font styling with margin gap -->\r\n                    <div class=\"mt-4 mb-1 text-left\" dir=\"rtl\">\r\n                        <span style=\"font-family: \'Jameel Noori Nastaleeq\', \'Noto Nastaliq Urdu\', serif;\" class=\"text-xl sm:text-2xl text-emerald-900 font-normal leading-normal\">السلامُ علیکم ورحمۃ اللہ وبرکاتہ</span>\r\n                    </div>\r\n                </div>\r\n\r\n                <!-- Letter Body -->\r\n                <div class=\"text-sm text-gray-800 leading-relaxed space-y-4 font-serif relative z-10 mt-4\">\r\n                    <p>\r\n                        On behalf of the executive board and the entire management team of <strong>{{agency_name}}</strong>, we extend our warmest congratulations and a heartfelt welcome to you on becoming a valuable esteemed member of our premium housing development project, <strong>{{property_name}}</strong>.\r\n                    </p>\r\n                    <p>\r\n                        This letter serves as your formal acknowledgment and congratulations on the successful booking of your real estate investment. We have securely registered your property and generated your unique file ledger under our automated municipal portal. Your key properties and allotment metrics are specified below:\r\n                    </p>\r\n\r\n                    <!-- Refined & Highly Colorized standalone Property Allotment Card -->\r\n                    <div class=\"my-4 bg-white border border-emerald-600/30 rounded-lg shadow-md overflow-hidden\">\r\n                        <!-- Highly Prominent Colored Card Header -->\r\n                        <div class=\"bg-gradient-to-r from-emerald-900 to-emerald-950 text-white px-4 py-2 flex items-center justify-between\">\r\n                            <span class=\"text-xs font-black tracking-widest uppercase flex items-center\">\r\n                                <svg xmlns=\"http://www.w3.org/2000/svg\" class=\"h-4 w-4 text-amber-400 mr-2\" fill=\"none\" viewBox=\"0 0 24 24\" stroke=\"currentColor\">\r\n                                    <path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z\" />\r\n                                </svg>\r\n                                OFFICIAL PROPERTY ALLOTMENT RECORD\r\n                            </span>\r\n                            <span class=\"bg-amber-500 text-emerald-950 text-[10px] font-black px-2.5 py-0.5 rounded shadow-sm uppercase tracking-wider\">Status: {{deal_status}}</span>\r\n                        </div>\r\n                        \r\n                        <!-- Premium Inner Metric Grid -->\r\n                        <div class=\"grid grid-cols-4 gap-3 p-3.5 bg-gradient-to-br from-emerald-50/20 via-white to-stone-50 text-xs\">\r\n                            <div class=\"bg-white p-2.5 rounded border border-emerald-100 shadow-sm border-l-4 border-l-emerald-700\">\r\n                                <span class=\"block text-[9px] text-emerald-900/60 uppercase tracking-wider font-extrabold mb-0.5\">File Number</span>\r\n                                <span class=\"font-extrabold text-emerald-950 font-mono text-sm leading-normal\">{{property_file}}</span>\r\n                            </div>\r\n                            <div class=\"bg-white p-2.5 rounded border border-emerald-100 shadow-sm border-l-4 border-l-emerald-700\">\r\n                                <span class=\"block text-[9px] text-emerald-900/60 uppercase tracking-wider font-extrabold mb-0.5\">Area / Size</span>\r\n                                <span class=\"font-bold text-gray-800 text-sm leading-normal\">{{property_area}}</span>\r\n                            </div>\r\n                            <div class=\"bg-white p-2.5 rounded border border-emerald-100 shadow-sm border-l-4 border-l-emerald-700\">\r\n                                <span class=\"block text-[9px] text-emerald-900/60 uppercase tracking-wider font-extrabold mb-0.5\">Category</span>\r\n                                <span class=\"font-bold text-emerald-800 text-sm leading-normal\">{{property_type}}</span>\r\n                            </div>\r\n                            <div class=\"bg-white p-2.5 rounded border border-emerald-100 shadow-sm border-l-4 border-l-emerald-700\">\r\n                                <span class=\"block text-[9px] text-emerald-900/60 uppercase tracking-wider font-extrabold mb-0.5\">Block Name</span>\r\n                                <span class=\"font-bold text-gray-800 text-sm leading-normal\">{{ballot_block_name}}</span>\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n\r\n                    <!-- Prominent, Colorized & Refined Bank Details Card (Installment payments) -->\r\n                    <div class=\"my-4 bg-gradient-to-br from-amber-50/40 via-white to-amber-50/20 border-2 border-dashed border-amber-600/40 rounded-lg relative overflow-hidden shadow-md\">\r\n                        <!-- Golden Emblem Stamp Background decoration -->\r\n                        <div class=\"absolute right-3 top-2.5 opacity-[0.09] pointer-events-none text-amber-900\">\r\n                            <svg xmlns=\"http://www.w3.org/2000/svg\" class=\"h-16 w-16\" fill=\"none\" viewBox=\"0 0 24 24\" stroke=\"currentColor\">\r\n                                <path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"1.5\" d=\"M19 21V5a2 2 0 00-2-2H7a2 2 0 00-2 2v16m14 0h2m-2 0h-5m-9 0H3m2 0h5M9 7h1m-1 4h1m4-4h1m-1 4h1m-5 10v-5a1 1 0 011-1h2a1 1 0 011 1v5m-4 0h4\" />\r\n                            </svg>\r\n                        </div>\r\n                        \r\n                        <!-- Rich Colored Accent Header Block inside card -->\r\n                        <div class=\"bg-gradient-to-r from-amber-600 to-amber-700 text-white px-4 py-1.5 flex items-center justify-between text-[11px] font-extrabold uppercase tracking-widest\">\r\n                            <span class=\"flex items-center\">\r\n                                <span class=\"inline-block w-2 h-2 bg-white rounded-full mr-2\"></span>\r\n                                OFFICIAL INSTALMENT & PAYMENT ACCOUNT DETAILS\r\n                            </span>\r\n                        </div>\r\n                        \r\n                        <div class=\"grid grid-cols-2 gap-x-6 gap-y-2 p-4 text-xs\">\r\n                            <div class=\"space-y-2\">\r\n                                <div class=\"flex items-center border-b border-amber-100/50 pb-1\">\r\n                                    <span class=\"text-amber-900 font-bold w-28 flex-shrink-0 bank-detail-label\">Bank Name:</span>\r\n                                    <span class=\"font-extrabold text-gray-800 flex-1 text-center bank-detail-value\">{{bank_name}}</span>\r\n                                </div>\r\n                                <div class=\"flex items-center border-b border-amber-100/50 pb-1\">\r\n                                    <span class=\"text-amber-900 font-bold w-28 flex-shrink-0 bank-detail-label\">Account Title:</span>\r\n                                    <span class=\"font-extrabold text-gray-800 flex-1 text-center bank-detail-value\">{{bank_account_title}}</span>\r\n                                </div>\r\n                            </div>\r\n                            <div class=\"space-y-2 border-l border-amber-200/50 pl-6\">\r\n                                <div class=\"flex items-center border-b border-amber-100/50 pb-1\">\r\n                                    <span class=\"text-amber-900 font-bold w-32 flex-shrink-0 bank-detail-label\">Account Number:</span>\r\n                                    <span class=\"font-mono font-extrabold text-gray-800 flex-1 text-center bank-detail-value\">{{bank_account_no}}</span>\r\n                                </div>\r\n                                <div class=\"flex items-center border-b border-amber-100/50 pb-1\">\r\n                                    <span class=\"text-amber-900 font-bold w-32 flex-shrink-0 bank-detail-label\">IBAN Number:</span>\r\n                                    <span class=\"font-mono font-extrabold text-gray-800 flex-1 text-center bank-detail-value\">{{bank_iban}}</span>\r\n                                </div>\r\n                            </div>\r\n                        </div>\r\n\r\n                        <!-- Strict security alert warning note regarding official installment accounts -->\r\n                        <div class=\"mx-4 mb-3 p-3 bg-red-50 border border-red-200 rounded text-[10px] text-red-800 font-medium leading-relaxed\">\r\n                            <strong class=\"text-red-900 font-extrabold uppercase tracking-wider block mb-0.5\">⚠️ Security Payment Notice:</strong>\r\n                            Please make payments only to the given official bank account details listed above. Under no circumstances should payments be transferred or handed over to any personal, individual, or other unofficial third-party account. The agency will not accept any responsibility or liability for transactions conducted on unofficial payment channels.\r\n                        </div>\r\n                    </div>\r\n\r\n                    <!-- Gaps after the bank details card added using spacing margins -->\r\n                    <p class=\"pt-4\">\r\n                        We are fundamentally dedicated to maintaining the highest industry standards of construction pace, legal transparency, and community development. We assure you that our development milestones are progressing rapidly, and we are on track to bring this master-planned community to life.\r\n                    </p>\r\n                    <p class=\"pt-2\">\r\n                        Should you have any inquiries regarding installment structures, development timelines, or future allotment ballots, please do not hesitate to reach our corporate customer care desk at <strong>{{agency_phone}}</strong> or write to us directly at <strong>{{agency_email}}</strong>.\r\n                    </p>\r\n                    <p class=\"pt-2\">\r\n                        We sincerely thank you for placing your trust in our organization. Welcome to your secure future.\r\n                    </p>\r\n                    <p class=\"font-bold text-emerald-950 pt-3 leading-tight\">\r\n                        Warm regards,\r\n                    </p>\r\n                    <p class=\"text-xs font-semibold text-emerald-800 leading-none\">\r\n                        The Executive Committee of {{agency_name}}\r\n                    </p>\r\n                </div>\r\n            </div>\r\n\r\n            <!-- Footer: Symmetrical Signatures & Large QR Block -->\r\n            <!-- Removed standard upper lines / borders around QR and Signature sections as requested -->\r\n            <footer class=\"text-[10px] relative mt-16 pb-4\">\r\n                <div class=\"grid grid-cols-12 gap-3 items-end text-center pt-4\">\r\n                    \r\n                    <!-- Left: Chairman Sign (Chief Executive Officer) -->\r\n                    <div class=\"col-span-4 flex flex-col items-center\">\r\n                        <div class=\"h-16\"></div> <!-- Space for Signature -->\r\n                        <span class=\"block border-t border-emerald-900/60 mt-0.5 w-full uppercase text-emerald-950 font-bold\">Chairman Sign</span>\r\n                        <span class=\"block text-gray-600 text-[9px] mt-0.5 font-semibold\" id=\"letter-display-chairman\">Chief Executive Officer</span>\r\n                    </div>\r\n                    \r\n                    <!-- Center: Symmetrical Security QR Block resized to exactly 0.75 x 0.75 inches -->\r\n                    <div class=\"col-span-4 flex flex-col items-center justify-center\">\r\n                        <div class=\"flex items-center justify-center space-x-3 mb-1\">\r\n                            <!-- Symmetrical centered QR Code wrapper configured strictly to 0.75 x 0.75 inches -->\r\n                            <div class=\"border border-emerald-900/20 p-1.5 bg-white flex items-center justify-center rounded shadow-sm flex-shrink-0\" style=\"width: 0.75in; height: 0.75in;\">{{letter_deal_qr}}</div>\r\n                        </div>\r\n                        <span class=\"text-[7.5px] text-gray-500 uppercase tracking-widest font-sans font-bold\">Scan to Verify</span>\r\n                    </div>\r\n\r\n                    <!-- Right: Date -->\r\n                    <div class=\"col-span-4 flex flex-col items-center\">\r\n                        <div class=\"h-16\"></div> <!-- Matching height for layout symmetry -->\r\n                        <span class=\"block border-t border-emerald-900/60 mt-0.5 w-full uppercase text-emerald-950 font-bold\">Date</span>\r\n                        <span class=\"block text-gray-600 text-[9px] mt-0.5\" id=\"letter-display-date\">{{letter_date}}</span>\r\n                    </div>\r\n                </div>\r\n\r\n                <!-- Footer Barcode Verification Line -->\r\n                <div class=\"mt-6 flex flex-col items-center justify-center opacity-85\">\r\n                    <svg id=\"secure-barcode\" class=\"h-5 w-44\" viewBox=\"0 0 100 20\" preserveAspectRatio=\"none\">\r\n                        <!-- Barcode patterns populated dynamically from {{deal_invoice_no}} -->\r\n                    </svg>\r\n                    <span class=\"text-[7px] text-gray-500 font-mono mt-0.5 tracking-widest\">ID-{{deal_invoice_no}}</span>\r\n                </div>\r\n            </footer>\r\n        </div>\r\n\r\n    </div>\r\n\r\n    <script>\r\n        /**\r\n         * Image Fallback Script Block to prevent unrendered template variables \r\n         * or blocked remote assets from hanging layout rendering.\r\n         */\r\n        function handleLogoError(img) {\r\n            img.onerror = null;\r\n            img.src = \"data:image/svg+xml;charset=utf-8,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%20000%2Fsvg%22%20width%3D%22112%22%20height%3D%22112%22%20viewBox%3D%220%200%20112%20112%22%3E%3Crect%20width%3D%22100%25%22%20height%3D%22100%25%22%20fill%3D%22%23064e3b%22%2F%3E%3Ctext%20x%3D%2250%25%22%20y%3D%2250%25%22%20dominant-baseline%3D%22middle%22%20text-anchor%3D%22middle%22%20fill%3D%22%23ffffff%22%20font-family%3D%22sans-serif%22%20font-size%3D%2212%22%20font-weight%3D%22bold%22%3EAGENCY%20LOGO%3C%2Ftext%3E%3C%2Fsvg%3E\";\r\n        }\r\n\r\n        function handlePhotoError(img) {\r\n            img.onerror = null;\r\n            img.src = \"data:image/svg+xml;charset=utf-8,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%20000%2Fsvg%22%20width%3D%2296%22%20height%3D%22128%22%20viewBox%3D%220%200%2096%20128%22%3E%3Crect%20width%3D%22100%25%22%20height%3D%22100%25%22%20fill%3D%22%23e2e8f0%22%2F%3E%3Ccircle%20cx%3D%2248%22%20cy%3D%2245%22%20r%3D%2220%22%20fill%3D%22%2394a3b8%22%2F%3E%3Cpath%20d%3D%22M%2012%20110%20C%2012%2085%2C%2084%2085%2C%2084%20110%20Z%22%20fill%3D%22%2394a3b8%22%2F%3E%3Ctext%20x%3D%2250%25%22%20y%3D%2292%25%22%20dominant-baseline%3D%22middle%22%20text-anchor%3D%22middle%22%20fill%3D%22%23475569%22%20font-family%3D%22sans-serif%22%20font-size%3D%2210%22%20font-weight%3D%22bold%22%3EPHOTO%3C%2Ftext%3E%3C%2Fsvg%3E\";\r\n        }\r\n\r\n        function handleWatermarkError(img) {\r\n            img.onerror = null;\r\n            img.style.display = \'none\';\r\n        }\r\n\r\n        /**\r\n         * Helper parses the unformatted date and returns a \"DD-MMM-YYYY\" string (e.g., 06-Jan-2026)\r\n         */\r\n        function parseAndFormatDate(dateStr) {\r\n            if (!dateStr || dateStr.includes(\'{{\') || dateStr.includes(\'}}\')) {\r\n                return dateStr;\r\n            }\r\n            \r\n            let parsedDate = null;\r\n            let dateObj = new Date(dateStr);\r\n            if (!isNaN(dateObj.getTime())) {\r\n                parsedDate = dateObj;\r\n            } else {\r\n                const parts = dateStr.split(/[-/.]/);\r\n                if (parts.length === 3) {\r\n                    let day, month, year;\r\n                    if (parts[2].length === 4) {\r\n                        day = parseInt(parts[0], 10);\r\n                        month = parseInt(parts[1], 10) - 1;\r\n                        year = parseInt(parts[2], 10);\r\n                    } else if (parts[0].length === 4) {\r\n                        year = parseInt(parts[0], 10);\r\n                        month = parseInt(parts[1], 10) - 1;\r\n                        day = parseInt(parts[2], 10);\r\n                    }\r\n                    \r\n                    if (year && !isNaN(month) && month >= 0 && month < 12 && day && day > 0 && day <= 31) {\r\n                        parsedDate = new Date(year, month, day);\r\n                    }\r\n                }\r\n            }\r\n            \r\n            if (parsedDate && !isNaN(parsedDate.getTime())) {\r\n                const months = [\'Jan\', \'Feb\', \'Mar\', \'Apr\', \'May\', \'Jun\', \'Jul\', \'Aug\', \'Sep\', \'Oct\', \'Nov\', \'Dec\'];\r\n                const formattedDay = String(parsedDate.getDate()).padStart(2, \'0\');\r\n                const formattedMonth = months[parsedDate.getMonth()];\r\n                const formattedYear = parsedDate.getFullYear();\r\n                return `${formattedDay}-${formattedMonth}-${formattedYear}`;\r\n            }\r\n            \r\n            return dateStr;\r\n        }\r\n\r\n        /**\r\n         * Generates a unique secure pseudo-barcode matching the invoice ID sequence\r\n         */\r\n        function generateSecureBarcode() {\r\n            const barcodeSvg = document.getElementById(\'secure-barcode\');\r\n            if (!barcodeSvg) return;\r\n            \r\n            const rawId = \"{{deal_invoice_no}}\".trim();\r\n            const cleanId = rawId.includes(\'{{\') ? \'0100234001920\' : rawId.replace(/[^0-9]/g, \'\');\r\n            \r\n            let innerHtml = \'<rect width=\"100\" height=\"20\" fill=\"#ffffff\"/>\';\r\n            let cursor = 5;\r\n            \r\n            for (let i = 0; i < 30; i++) {\r\n                const charCodeVal = cleanId.charCodeAt(i % cleanId.length) || 103;\r\n                const barWidth = (charCodeVal % 2 === 0) ? 1.5 : 0.6;\r\n                const gapWidth = (charCodeVal % 3 === 0) ? 1.2 : 0.8;\r\n                \r\n                innerHtml += `<rect x=\"${cursor}\" y=\"0\" width=\"${barWidth}\" height=\"20\" fill=\"#111827\"/>`;\r\n                cursor += barWidth + gapWidth;\r\n                if (cursor > 95) break;\r\n            }\r\n            barcodeSvg.innerHTML = innerHtml;\r\n        }\r\n\r\n        function initWelcomeLetter() {\r\n            // Secure Barcode Generator\r\n            generateSecureBarcode();\r\n\r\n            // Date Format initializations\r\n            const dateElements = [\'display-date\', \'letter-display-date\'];\r\n            dateElements.forEach(function(id) {\r\n                const element = document.getElementById(id);\r\n                if (element) {\r\n                    const rawDate = element.textContent.trim();\r\n                    element.textContent = parseAndFormatDate(rawDate);\r\n                }\r\n            });\r\n        }\r\n\r\n        if (document.readyState !== \'loading\') {\r\n            initWelcomeLetter();\r\n        } else {\r\n            document.addEventListener(\'DOMContentLoaded\', initWelcomeLetter);\r\n        }\r\n    </script>\r\n</body>\r\n</html>', 'RLT_WELCOME', 'Published', 'Yes', '', 'letter_signatures', '', 'letter_signatures');
INSERT INTO `templates` (`id`, `name`, `description`, `type`, `status`, `is_new`, `ceo_signature`, `ceo_signature_dir`, `chairman_signature`, `chairman_signature_dir`) VALUES
(35, 'Refund Clearance / No Claim', '﻿<!DOCTYPE html>\r\n<html lang=\"ur\" dir=\"rtl\">\r\n<head>\r\n    <meta charset=\"UTF-8\">\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n    <title>وائٹ ولاز - لا دعویٰ اقرار نامہ براہِ راست پرنٹنگ سسٹم</title>\r\n    <!-- Tailwind CSS -->\r\n    <script src=\"https://cdn.tailwindcss.com\"></script>\r\n    <!-- Google Fonts for Urdu Noto Nastaliq & Inter -->\r\n    <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\r\n    <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\r\n    <link href=\"https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&family=Noto+Nastaliq+Urdu:wght@400;500;700&display=swap\" rel=\"stylesheet\">\r\n    <!-- QRCode.js Library for secure dynamic QR codes -->\r\n    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/qrcodejs/1.0.0/qrcode.min.js\"></script>\r\n    \r\n    <style>\r\n        @font-face {\r\n            font-family: \'Jameel Noori Nastaliq\';\r\n            src: url(\'https://cdn.jsdelivr.net/gh/nafeesl/jameel-noori-nastaliq-webfont@master/Jameel%20Noori%20Nastaliq.woff2\') format(\'woff2\'),\r\n                 url(\'https://cdn.jsdelivr.net/gh/nafeesl/jameel-noori-nastaliq-webfont@master/Jameel%20Noori%20Nastaliq.woff\') format(\'woff\');\r\n            font-weight: normal;\r\n            font-style: normal;\r\n        }\r\n\r\n        .urdu-legal {\r\n            font-family: \'Jameel Noori Nastaliq\', \'Noto Nastaliq Urdu\', \'Urdu Typesetting\', serif;\r\n            text-align: justify;\r\n            text-justify: inter-word;\r\n            font-size: 11px;\r\n            line-height: 2.0; \r\n            word-spacing: -2.5px; \r\n            letter-spacing: -0.3px;\r\n        }\r\n        \r\n        body {\r\n            font-family: \'Inter\', sans-serif;\r\n            background-color: #090d16;\r\n        }\r\n\r\n        /* 4 Inches Empty Space at the top of Page 1 for physical Stamp Papers */\r\n        .stamp-top-gap {\r\n            height: 4.0in; \r\n            position: relative;\r\n            background: transparent;\r\n        }\r\n\r\n        /* Classic Red Legal Border/Margins commonly used in Pakistani Court Documents */\r\n        .legal-frame {\r\n            border-right: 3px double #dc2626; \r\n            border-left: 1px solid #fee2e2; \r\n            padding-right: 1.8rem;\r\n            padding-left: 1.2rem;\r\n        }\r\n\r\n        /* Interactive screen canvas representation of standard 8.5 x 14 in Legal paper */\r\n        .legal-page-canvas {\n            width: 8.5in;\n            min-height: 14.0in;\n            height: auto;\n            background: #ffffff;\n            color: #000000;\n            box-sizing: border-box;\n            position: relative;\n            overflow: visible;\n            display: flex;\n            flex-direction: column;\n            justify-content: flex-start;\n            padding: 0.36in 0.5in 0.32in 0.5in;\n        }\n\r\n        /* Inline editable fields subtle indicator (screen only) */\r\n        [contenteditable=\"true\"] {\r\n            outline: none;\r\n            transition: all 0.2s ease;\r\n        }\r\n        [contenteditable=\"true\"]:hover {\r\n            background-color: #f0fdf4;\r\n            box-shadow: 0 0 0 2px #bbf7d0;\r\n            border-radius: 2px;\r\n        }\r\n        [contenteditable=\"true\"]:focus {\r\n            background-color: #f0fdf4;\r\n            box-shadow: 0 0 0 2px #22c55e;\r\n            border-radius: 2px;\r\n        }\r\n\r\n        /* QR code block size fixed to 2x2 inches */\r\n        .qr-container-fixed {\n            width: 2.0in;\n            height: 2.0in;\n            display: flex;\n            align-items: center;\n            justify-content: center;\r\n            background: #ffffff;\r\n            padding: 0.1in;\n            box-sizing: border-box;\n        }\n\n        .refund-clearance-footer {\n            display: flex;\n            align-items: center;\n            justify-content: space-between;\n            gap: 0.04in;\n            direction: ltr;\n            font-family: Arial, Helvetica, sans-serif !important;\n            font-size: 5.2px;\n            line-height: 1;\n            letter-spacing: 0;\n            white-space: nowrap;\n            overflow: hidden;\n            color: #94a3b8;\n        }\n        .refund-clearance-footer span {\n            display: inline-block;\n            white-space: nowrap;\n        }\n        .refund-clearance-footer .footer-title {\n            flex: 1 1 auto;\n            min-width: 0;\n            overflow: visible;\n            text-overflow: unset;\n            font-family: Arial, Helvetica, sans-serif !important;\n        }\n        .refund-clearance-footer .footer-ref {\n            flex: 0 0 auto;\n            direction: rtl;\n            text-align: right;\n            font-family: Arial, Helvetica, sans-serif !important;\n        }\n\n        @media print {\n            @page {\r\n                size: legal portrait;\r\n                margin: 0; \r\n            }\r\n            body {\r\n                background-color: #ffffff !important;\r\n                color: #000000 !important;\r\n                margin: 0 !important;\r\n                padding: 0 !important;\r\n            }\r\n            .no-print {\r\n                display: none !important;\r\n            }\r\n            .print-container {\r\n                width: 100% !important;\r\n                max-width: 100% !important;\r\n                margin: 0 !important;\r\n                padding: 0 !important;\r\n                box-shadow: none !important;\r\n                background-color: #ffffff !important;\r\n            }\r\n            .legal-page-canvas {\n                border: none !important;\n                box-shadow: none !important;\n                margin: 0 auto !important;\n                padding: 0.36in 0.5in 0.32in 0.5in !important;\n                width: 8.5in !important;\n                min-height: 14.0in !important;\n                height: auto !important;\n                box-sizing: border-box;\n                page-break-after: auto;\n                page-break-before: avoid;\n                overflow: visible;\n            }\n            .stamp-top-gap {\n                height: 3.65in !important; \n            }\n            [contenteditable=\"true\"]:hover, [contenteditable=\"true\"]:focus {\r\n                background-color: transparent !important;\r\n                box-shadow: none !important;\r\n            }\r\n            .qr-container-fixed {\n                border: none !important;\n            }\n            .refund-clearance-footer {\n                display: flex !important;\n                flex-wrap: nowrap !important;\n                align-items: center !important;\n                justify-content: space-between !important;\n                gap: 0.04in !important;\n                font-family: Arial, Helvetica, sans-serif !important;\n                font-size: 5.2px !important;\n                line-height: 1 !important;\n                white-space: nowrap !important;\n                overflow: hidden !important;\n                width: 100% !important;\n            }\n        }\n    </style>\r\n</head>\r\n<body class=\"text-slate-100 flex flex-col min-h-screen\">\r\n\r\n    <!-- Minimalist Top Bar containing only print and active typography sliders -->\r\n    <header class=\"bg-slate-900 border-b border-slate-800 text-white py-3 px-6 shadow-md flex flex-col md:flex-row justify-between items-center gap-4 no-print z-10\">\r\n        <div class=\"flex items-center space-x-4 space-x-reverse\">\r\n            <div class=\"p-2 bg-emerald-950 rounded-lg border border-emerald-800\">\r\n                <svg class=\"w-6 h-6 text-emerald-400\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" viewBox=\"0 0 24 24\">\r\n                    <path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z\"/>\r\n                </svg>\r\n            </div>\r\n            <div>\r\n                <h1 class=\"text-sm font-bold tracking-wide\">براہِ راست کینوس ایڈیٹر (DIRECT ON-CANVAS EDITOR)</h1>\r\n                <p class=\"text-[10px] text-slate-400\">کینوس پر لکھے کسی بھی لفظ پر کلک کر کے اپنی مرضی سے اردو یا 123 نمبرز تبدیل کریں</p>\r\n            </div>\r\n        </div>\r\n\r\n        <!-- Inline Spacing Adjusters -->\r\n        <div class=\"flex flex-wrap items-center gap-4 text-xs\">\r\n            <!-- Font Size -->\r\n            <div class=\"flex items-center space-x-2 space-x-reverse bg-slate-950 px-3 py-1.5 rounded border border-slate-800\">\r\n                <span class=\"text-slate-400 text-[10px]\">فونٹ سائز:</span>\r\n                <input type=\"range\" min=\"9\" max=\"15\" value=\"11\" id=\"range-font-size\" oninput=\"changeFontSize(this.value)\" class=\"w-16 accent-emerald-500 bg-slate-800 h-1 rounded\">\r\n                <span id=\"font-size-val\" class=\"font-bold text-emerald-400 font-mono text-[10px]\">11px</span>\r\n            </div>\r\n\r\n            <!-- Line Height -->\r\n            <div class=\"flex items-center space-x-2 space-x-reverse bg-slate-950 px-3 py-1.5 rounded border border-slate-800\">\r\n                <span class=\"text-slate-400 text-[10px]\">لائن سپیس:</span>\r\n                <input type=\"range\" min=\"1.6\" max=\"2.4\" step=\"0.1\" value=\"2.0\" id=\"range-line-height\" oninput=\"changeLineHeight(this.value)\" class=\"w-16 accent-emerald-500 bg-slate-800 h-1 rounded\">\r\n                <span id=\"line-height-val\" class=\"font-bold text-emerald-400 font-mono text-[10px]\">2.0</span>\r\n            </div>\r\n\r\n            <!-- Word Spacing -->\r\n            <div class=\"flex items-center space-x-2 space-x-reverse bg-slate-950 px-3 py-1.5 rounded border border-slate-800\">\n                <span class=\"text-slate-400 text-[10px]\">لفظوں کا فاصلہ:</span>\n                <input type=\"range\" min=\"-4.0\" max=\"0.0\" step=\"0.5\" value=\"-2.5\" id=\"range-word-spacing\" oninput=\"changeWordSpacing(this.value)\" class=\"w-16 accent-emerald-500 bg-slate-800 h-1 rounded\">\n                <span id=\"word-spacing-val\" class=\"font-bold text-emerald-400 font-mono text-[10px]\">-2.5px</span>\n            </div>\n\n            <!-- Letter Spacing -->\n            <div class=\"flex items-center space-x-2 space-x-reverse bg-slate-950 px-3 py-1.5 rounded border border-slate-800\">\n                <span class=\"text-slate-400 text-[10px]\">حروف کا فاصلہ:</span>\n                <input type=\"range\" min=\"-0.8\" max=\"0.4\" step=\"0.1\" value=\"-0.3\" id=\"range-letter-spacing\" oninput=\"changeLetterSpacing(this.value)\" class=\"w-16 accent-emerald-500 bg-slate-800 h-1 rounded\">\n                <span id=\"letter-spacing-val\" class=\"font-bold text-emerald-400 font-mono text-[10px]\">-0.3px</span>\n            </div>\n\n            <button onclick=\"window.print()\" class=\"bg-emerald-600 hover:bg-emerald-500 text-white font-bold px-5 py-2 rounded shadow transition flex items-center gap-1.5 text-xs\">\n                <svg class=\"w-3.5 h-3.5\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M17 17h2a2 2 0 002-2v-4a2 2 0 00-2-2H5a2 2 0 00-2 2v4a2 2 0 002 2h2m2 4h6a2 2 0 002-2v-4a2 2 0 00-2-2H9a2 2 0 00-2 2v4a2 2 0 002 2zm8-12V5a2 2 0 00-2-2H9a2 2 0 00-2 2v4h10z\"></path></svg>\r\n                پرنٹ اشٹام (Legal Print)\r\n            </button>\r\n        </div>\r\n    </header>\r\n\r\n    <!-- Full-screen Canvas Workspace -->\r\n    <main class=\"flex-1 flex justify-center items-center py-6 px-4 overflow-y-auto bg-slate-950\">\r\n        \r\n        <!-- Printable 8.5\" x 14\" Legal Sheet representation -->\r\n        <div id=\"ashtam-canvas-container\" class=\"legal-page-canvas shadow-2xl p-10 rounded relative overflow-hidden flex flex-col justify-between\">\r\n            \r\n            <div>\r\n                <!-- 4-Inch Blank Header Space (Completely clean, no visual borders/texts on screen or print) -->\r\n                <div id=\"physical-gap\" class=\"stamp-top-gap\"></div>\r\n\r\n                <!-- MAIN URDU LEGAL CONTENT FRAME -->\r\n                <div id=\"legal-content-area\" class=\"legal-frame text-right text-slate-950\">\r\n                    \r\n                    <!-- Main Legal Heading -->\r\n                    <div class=\"text-center mb-3\">\r\n                        <h2 class=\"urdu-legal text-sm font-extrabold text-slate-900 border-b-2 border-double border-slate-900 pb-1 inline-block\" contenteditable=\"true\">\r\n                            اقرار نامہ حتمی تصفیہ، مکمل وصولیابی رقم و لا دعویٰ (خلاصی نامہ)\r\n                        </h2>\r\n                    </div>\r\n\r\n                    <!-- Urdu Deed Body Paragraphs (Editable Inline) -->\r\n                    <div id=\"urdu-paragraphs\" class=\"urdu-legal text-[11px] text-justify space-y-2.5\">\r\n                        \r\n                        <p>\r\n                            یہ قانونی اقرار نامہ دستبرداری و خلاصی نامہ آج مورخہ <strong dir=\"ltr\" class=\"inline-block border-b border-dotted border-slate-950 px-1 font-sans text-[10px] text-slate-900\" contenteditable=\"true\">{{refund_completion_date}}</strong> کو بمقام لاہور، پاکستان میں فریقینِ ذیل کے مابین برضا و رغبتِ خود، بغیر کسی بیرونی دباؤ، جبر و اکراہ، اور ہوش و حواسِ خمسہ قائم رہنے کی حالت میں تحریر و تسلیم کیا گیا ہے:\r\n                        </p>\r\n\r\n                        <!-- Party Identification Block -->\r\n                        <div class=\"bg-slate-50 border border-slate-200 p-2 rounded my-1 space-y-1 text-[10px] leading-relaxed\">\r\n                            <p>\r\n                                <strong>۱۔ فریقِ اول (انتظامیہ/ادارہ):</strong> <span contenteditable=\"true\">وائٹ ولاز عوامی بلاک، خورد پور روڈ مارکہ، لاہور۔ بذریعہ مجاز افسر/انتظامیہ (جسے بعد میں \'کمپنی\' یا \'فریقِ اول\' پکارا جائے گا)۔</span>\r\n                            </p>\r\n                            <p>\r\n                                <strong>۲۔ فریقِ دوم (صارف/سابقہ الاٹی):</strong> مسمیٰ <strong class=\"border-b border-solid border-slate-950 px-1 font-bold text-slate-900\" contenteditable=\"true\">{{client_name}}</strong> ولد <strong class=\"border-b border-solid border-slate-950 px-1 font-bold text-slate-900\" contenteditable=\"true\">{{client_father_name}}</strong>، حامل شناختی کارڈ نمبر <strong dir=\"ltr\" class=\"inline-block border-b border-solid border-slate-950 px-1 font-sans text-[10px] text-slate-900\" contenteditable=\"true\">{{client_cnic}}</strong>، مستقل رہائشی پتہ <strong class=\"border-b border-solid border-slate-950 px-1 text-slate-900\" contenteditable=\"true\">{{client_address}}</strong>، فون رابطہ نمبر <strong dir=\"ltr\" class=\"inline-block border-b border-solid border-slate-950 px-1 font-sans text-[10px] text-slate-900\" contenteditable=\"true\">{{client_mobile}}</strong> (جسے بعد میں \'سابقہ الاٹی\' یا \'فریقِ دوم\' پکارا جائے گا)۔\r\n                            </p>\r\n                        </div>\r\n\r\n                        <p>\r\n                            <strong>۱۔ تمہید و فنڈز واپسی کا پسِ منظر (Historical Context):</strong><br>\r\n                            یہ کہ فریقِ دوم نے فریقِ اول کے ہاؤسنگ پروجیکٹ \'وائٹ ولاز\' میں ایک عدد رہائشی یونٹ برائے فائل کوڈ \r\n                            <strong dir=\"ltr\" class=\"inline-block border-b border-slate-950 px-1 font-sans font-bold text-[10px] bg-yellow-50 text-slate-900\" contenteditable=\"true\">{{property_file}}</strong> \r\n                            (ٹاؤن ہاؤس گراؤنڈ فلور) جو کہ انوائس نمبر <strong dir=\"ltr\" class=\"inline-block border-b border-slate-950 px-1 font-sans text-[10px] text-slate-900\" contenteditable=\"true\">{{deal_invoice_no}}</strong> کے تحت رجسٹرڈ تھی، بک کروائی تھی۔ بعد ازاں فریقِ دوم نے اپنی ذاتی مالی مجبوریوں اور شدید طبی معذوری کی بنا پر اس فائل کو منسوخ کرنے کی باقاعدہ تحریری درخواست دائر کی تھی جس کی مفصل دستاویزی فائل کا نام دفتری ریکارڈ میں <strong class=\"border-b border-slate-950 px-1 text-blue-900 font-bold\" contenteditable=\"true\">\"Refund Request - {{deal_invoice_no}}\"</strong> مورخہ {{refund_request_date}} محفوظ ہے۔ مذکورہ منسوخی کی فائنل منظوری کے بعد فریقِ دوم کی جمع شدہ کل رقم <strong dir=\"ltr\" class=\"inline-block font-sans font-bold text-slate-900\" contenteditable=\"true\">{{refund_total_paid}}</strong> میں سے محکمانہ پالیسی کے تحت طے شدہ کٹوتی <strong dir=\"ltr\" class=\"inline-block font-sans font-bold text-slate-900\" contenteditable=\"true\">{{refund_deduction_percent}}</strong> (بمطابق رقم کٹوتی <strong dir=\"ltr\" class=\"inline-block font-sans font-bold text-slate-900\" contenteditable=\"true\">{{refund_deduction_amount}}</strong>) لازمی منسوخی کٹوتی عمل میں لائی گئی تھی، جس کے بعد بقیہ واجب الادا خالص فنڈز کی مالیت کل رقم <strong dir=\"ltr\" class=\"inline-block bg-slate-100 border border-slate-300 font-sans font-bold px-1 rounded-sm text-emerald-950\" contenteditable=\"true\">{{refund_net_refund}}</strong> ({{refund_net_refund_words_urdu}}) تسلیم کی گئی تھی۔\r\n                        </p>\r\n\r\n                        <p>\r\n                            <strong>۲۔ حتمی وصولیابی رقم و تصفیہ (Absolute Payment Clearance):</strong><br>\r\n                            منکہ فریقِ دوم (سابقہ الاٹی) حلفاً و اقراراً یہ تصدیق کرتا ہوں کہ فریقِ اول نے میری فائنل تصفیہ شدہ رقم کل رقم <strong dir=\"ltr\" class=\"inline-block font-sans font-bold text-slate-900\" contenteditable=\"true\">{{refund_net_refund}}</strong> مقررہ {{refund_cycle_count}} {{refund_cycle_frequency}} سائیکلز کے شیڈول کے مطابق میرے نامزد کردہ بینک اکاؤنٹ (عنوانِ کھاتہ: <strong class=\"font-bold text-slate-900\" contenteditable=\"true\">{{refund_account_title}}</strong>، بینک: <strong class=\"text-slate-900\" contenteditable=\"true\">{{refund_bank_name}}</strong>، اکاؤنٹ نمبر/برانچ: <strong dir=\"ltr\" class=\"inline-block font-sans text-[10px] text-slate-900\" contenteditable=\"true\">{{refund_account_no}} {{refund_bank_branch}}</strong>) میں کلیئرنس کے ساتھ مکمل طور پر منتقل (Paid) کر دی ہے۔ میں حلفیہ اقرار کرتا ہوں کہ اس رقم کا آخری روپیہ تک میں وصول پا چکا ہوں، اب کمپنی کی طرف میرا کوئی بھی بقایا جات یا ریفنڈ کلیم موجود نہیں رہا ہے۔\r\n                        </p>\r\n\r\n                        <p>\r\n                            <strong>۳۔ حقِ ملکیت کی منسوخی و لا دعویٰ (Release of Title):</strong><br>\r\n                            یہ کہ اب فریقِ دوم کا فریقِ اول کے مذکورہ رہائشی پروجیکٹ، فائل کوڈ، یا مذکورہ ٹاؤن ہاؤس یونٹ نمبر <strong dir=\"ltr\" class=\"inline-block border-b border-slate-950 px-1 bg-yellow-50 font-sans font-bold text-[10px] text-slate-900\" contenteditable=\"true\">{{property_file}}</strong> پر کوئی مالکانہ حق، جزوی حق، منتقلی کا کلیم، یا کسی بھی نوعیت کا ڈیمانڈ باقی نہیں بچا ہے۔ یہ بکنگ باقاعدہ مستقل طور پر منسوخ تصور ہوگی اور کمپنی اس یونٹ کو کسی بھی دوسرے الاٹی کو دوبارہ فروخت کرنے کا قانونی طور پر کلی اختیار رکھتی ہے۔\r\n                        </p>\r\n\r\n                        <p>\r\n                            <strong>۴۔ قانونی کارروائی سے مکمل دستبرداری (Legal Immunity Guarantee):</strong><br>\r\n                            یہ کہ فریقِ دوم حلف اٹھاتا ہے کہ وہ اس حتمی ادائیگی کی وصولی کے بعد فریقِ اول یا اس کے مالکان کے خلاف پاکستان کے کسی بھی سول کورٹ، نیب، ایف آئی اے، لاہور ڈیولپمنٹ اتھارٹی، پولیس اسٹیشن، یا رئیل اسٹیٹ ریگولیٹری اتھارٹی میں کوئی دعویٰ یا ہتکِ عزت کی درخواست دائر کرنے کا حق نہیں رکھتا۔ اگر آئندہ فریقِ دوم کی طرف سے ایسا کوئی اقدام اٹھایا گیا، تو اسے متعلقہ فورمز پر باطل سمجھا جائے گا اور یہ اقرار نامہ عدالت میں کمپنی کا حتمی تصفیہ نامہ تسلیم ہوگا۔\r\n                        </p>\r\n\r\n                        <p class=\"pb-1\" contenteditable=\"true\">\r\n                            بنا بریں، یہ اقرار نامہ لا دعویٰ و حتمی تصفیہ نامہ تحریر کر دیا گیا ہے تاکہ بوقتِ ضرورت سند رہے اور کام آئے۔\r\n                        </p>\r\n\r\n                    </div>\r\n\r\n                </div>\r\n            </div>\r\n\r\n            <!-- Bottom Signature Block with centered QR -->\r\n            <div class=\"signature-block border-t border-slate-300 pt-3 mt-1\">\r\n                <!-- Primary Parties Signature -->\r\n                <div class=\"grid grid-cols-2 gap-8 text-center text-[10px] mb-2\">\r\n                    <div class=\"space-y-1\">\r\n                        <div class=\"h-10 border-b border-dashed border-slate-400 mx-auto w-3/4 flex items-end justify-center\">\r\n                            <span class=\"text-[8px] text-slate-400 font-sans\">[دستخط و مہرِ انتظامیہ]</span>\r\n                        </div>\r\n                        <p class=\"font-bold text-slate-950 text-[11px]\" contenteditable=\"true\">فریقِ اول (انتظامیہ وائٹ ولاز)</p>\r\n                    </div>\r\n                    <div class=\"space-y-1\">\r\n                        <div class=\"h-10 border-b border-dashed border-slate-400 mx-auto w-3/4 flex flex-col justify-end items-center\">\r\n                            <span class=\"text-[8px] text-slate-400 font-sans mb-0.5\">[انگوٹھے کا نشان و دستخط فریق دوم]</span>\r\n                        </div>\r\n                        <p id=\"label-client-sign-ur\" class=\"font-bold text-slate-950 text-[11px]\" contenteditable=\"true\">{{client_name}}</p>\r\n                    </div>\r\n                </div>\r\n\r\n                <!-- Witness Block with centered 2x2 Inch QR Code -->\r\n                <div class=\"grid grid-cols-3 gap-2 items-center text-center text-[10px] pt-1.5 border-t border-slate-100\">\r\n                    <!-- Witness 1 -->\r\n                    <div class=\"space-y-1\">\r\n                        <div class=\"h-8 border-b border-dashed border-slate-400 mx-auto w-11/12\"></div>\r\n                        <p class=\"font-bold text-slate-950 text-[10px]\" contenteditable=\"true\">گواہ نمبر ۱ (شہادت اول)</p>\r\n                        <p class=\"text-[8px] text-slate-500 font-sans\">Witness 1 CNIC & Sign</p>\r\n                    </div>\r\n\r\n                    <!-- 2x2 Inches Dynamic Verification QR Code Center -->\r\n                    <div class=\"flex flex-col items-center justify-center\">\r\n                        <div class=\"qr-container-fixed border border-slate-100 shadow-sm rounded\">\r\n                            <div id=\"ashtam-qrcode\">{{refund_completion_qr}}</div>\r\n                        </div>\r\n                        <p class=\"text-[7px] text-slate-400 font-sans mt-0.5\">تصدیق بذریعہ کیو آر کوڈ</p>\r\n                    </div>\r\n\r\n                    <!-- Witness 2 -->\r\n                    <div class=\"space-y-1\">\r\n                        <div class=\"h-8 border-b border-dashed border-slate-400 mx-auto w-11/12\"></div>\r\n                        <p class=\"font-bold text-slate-950 text-[10px]\" contenteditable=\"true\">گواہ نمبر ۲ (شہادت دوم)</p>\r\n                        <p class=\"text-[8px] text-slate-500 font-sans\">Witness 2 CNIC & Sign</p>\r\n                    </div>\r\n                </div>\r\n\r\n                <!-- Footer details of the page -->\r\n                <div class=\"refund-clearance-footer border-t border-slate-200 pt-1 mt-2\">\n                    <span class=\"footer-title\">WHITE VILLAS (AWAMI BLOCK) - DEED OF RELEASE & NO-CLAIMS</span>\n                    <span class=\"footer-ref\" contenteditable=\"true\">حوالہ نمبر: {{letter_ref_no}}</span>\n                </div>\n            </div>\r\n\r\n        </div>\r\n    </main>\r\n\r\n    <script>\n        const typographyStorageKey = \'wv_refund_clearance_typography_v1\';\n        const defaultTypographySettings = {\n            fontSize: \'11\',\n            lineHeight: \'2.0\',\n            wordSpacing: \'-2.5\',\n            letterSpacing: \'-0.3\'\n        };\n\n        // Set dynamic date and render default QR code\n        window.onload = function() {\n            setDates();\n            applySavedTypographySettings();\n            renderQRCode();\n            \n            // Re-render QR code dynamically whenever the user types or updates anything on the editable canvas\n            document.querySelectorAll(\'[contenteditable=\"true\"]\').forEach(element => {\n                element.addEventListener(\'input\', () => {\n                    renderQRCode();\r\n                });\r\n            });\n        };\n\n        window.addEventListener(\'beforeprint\', function() {\n            applySavedTypographySettings();\n        });\n\r\n        // Format dates dynamically inside the placeholder\r\n        function setDates() {\r\n            const today = new Date();\r\n            const day = today.getDate().toString().padStart(2, \'0\');\r\n            const month = (today.getMonth() + 1).toString().padStart(2, \'0\');\r\n            const year = today.getFullYear().toString();\r\n            \r\n            const formattedDate = `${day}-${month}-${year}`;\r\n            document.querySelectorAll(\".date-today-placeholder\").forEach(el => {\r\n                el.innerText = formattedDate;\r\n            });\r\n        }\r\n\r\n        function readTypographySettings() {\n            try {\n                const stored = window.localStorage ? JSON.parse(localStorage.getItem(typographyStorageKey) || \'{}\') : {};\n                return Object.assign({}, defaultTypographySettings, stored || {});\n            } catch (error) {\n                return Object.assign({}, defaultTypographySettings);\n            }\n        }\n\n        function saveTypographySettings(settings) {\n            if (!window.localStorage) { return; }\n            try {\n                localStorage.setItem(typographyStorageKey, JSON.stringify(settings));\n            } catch (error) {}\n        }\n\n        function applyTypographySettings(settings, shouldSave) {\n            const merged = Object.assign({}, defaultTypographySettings, settings || {});\n            const paragraphs = document.getElementById(\'urdu-paragraphs\');\n            if (paragraphs) {\n                paragraphs.style.setProperty(\'font-size\', merged.fontSize + \'px\', \'important\');\n                paragraphs.style.setProperty(\'line-height\', merged.lineHeight, \'important\');\n                paragraphs.style.setProperty(\'word-spacing\', merged.wordSpacing + \'px\', \'important\');\n                paragraphs.style.setProperty(\'letter-spacing\', merged.letterSpacing + \'px\', \'important\');\n            }\n            const fontInput = document.getElementById(\'range-font-size\');\n            const lineInput = document.getElementById(\'range-line-height\');\n            const spacingInput = document.getElementById(\'range-word-spacing\');\n            const letterInput = document.getElementById(\'range-letter-spacing\');\n            const fontLabel = document.getElementById(\'font-size-val\');\n            const lineLabel = document.getElementById(\'line-height-val\');\n            const spacingLabel = document.getElementById(\'word-spacing-val\');\n            const letterLabel = document.getElementById(\'letter-spacing-val\');\n            if (fontInput) { fontInput.value = merged.fontSize; }\n            if (lineInput) { lineInput.value = merged.lineHeight; }\n            if (spacingInput) { spacingInput.value = merged.wordSpacing; }\n            if (letterInput) { letterInput.value = merged.letterSpacing; }\n            if (fontLabel) { fontLabel.innerText = merged.fontSize + \'px\'; }\n            if (lineLabel) { lineLabel.innerText = merged.lineHeight; }\n            if (spacingLabel) { spacingLabel.innerText = merged.wordSpacing + \'px\'; }\n            if (letterLabel) { letterLabel.innerText = merged.letterSpacing + \'px\'; }\n            if (shouldSave) {\n                saveTypographySettings(merged);\n            }\n        }\n\n        function applySavedTypographySettings() {\n            applyTypographySettings(readTypographySettings(), false);\n        }\n\n        // Live typography custom spacing adjusters\n        function changeFontSize(value) {\n            const settings = readTypographySettings();\n            settings.fontSize = String(value);\n            applyTypographySettings(settings, true);\n        }\n\n        function changeLineHeight(value) {\n            const settings = readTypographySettings();\n            settings.lineHeight = String(value);\n            applyTypographySettings(settings, true);\n        }\n\n        function changeWordSpacing(value) {\n            const settings = readTypographySettings();\n            settings.wordSpacing = String(value);\n            applyTypographySettings(settings, true);\n        }\n\n        function changeLetterSpacing(value) {\n            const settings = readTypographySettings();\n            settings.letterSpacing = String(value);\n            applyTypographySettings(settings, true);\n        }\n\r\n        // Render high-fidelity QR Code inside the 2x2 inches container\r\n        function renderQRCode() {\r\n            const container = document.getElementById(\'ashtam-qrcode\');\r\n            if (!container) { return; }\r\n            if (container.innerHTML.replace(/\\s+/g, \"\") !== \"\") { return; }\r\n            container.innerHTML = \"\"; // Clean older instance\r\n            \r\n            // Calculate pixel dimensions for standard 1.7-inch inner dimension to fit 2\" box smoothly\r\n            const qrSizePixels = 120;\r\n            const textToEncode = {{refund_completion_qr_text_json}};\r\n\r\n            new QRCode(container, {\r\n                text: textToEncode,\r\n                width: qrSizePixels,\r\n                height: qrSizePixels,\r\n                colorDark: \"#000000\",\r\n                colorLight: \"#ffffff\",\r\n                correctLevel: QRCode.CorrectLevel.H\r\n            });\r\n        }\r\n    </script>\r\n</body>\r\n</html>\n', 'RLT_REFUND_CLEARANCE', 'Published', 'No', '', 'letter_signatures', '', 'letter_signatures'),
(36, 'Rental Agreement', '<!DOCTYPE html>\r\n<html lang=\"en\">\r\n<head>\r\n    <meta charset=\"UTF-8\">\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n    <title>Rental Agreement - {{agreement_no}}</title>\r\n    <style>\r\n        /* Color Palette & Variables */\r\n        :root {\r\n            --primary-dark: #0f172a;    /* Slate 900 */\r\n            --primary-blue: #1e3a8a;    /* Blue 900 */\r\n            --accent-blue: #eff6ff;     /* Blue 50 */\r\n            --border-color: #cbd5e1;    /* Slate 300 */\r\n            --text-dark: #334155;       /* Slate 700 */\r\n            --highlight-bg: #fffbeb;    /* Amber 50 */\r\n            --highlight-border: #f59e0b;/* Amber 500 */\r\n        }\r\n\r\n        /* Base and Print Styles for A4 */\r\n        * {\r\n            /* CRITICAL: This forces the printer to print background colors! */\r\n            -webkit-print-color-adjust: exact !important;\r\n            print-color-adjust: exact !important;\r\n            box-sizing: border-box;\r\n        }\r\n\r\n        body {\r\n            font-family: \'Segoe UI\', Tahoma, Geneva, Verdana, sans-serif;\r\n            line-height: 1.85;\r\n            color: var(--text-dark);\r\n            background: #e2e8f0;\r\n            margin: 0;\r\n            padding: 0;\r\n            display: flex;\r\n            justify-content: center;\r\n        }\r\n\r\n        .document-container {\r\n            width: 210mm; /* A4 Width */\r\n            min-height: 297mm; /* Changed to min-height to let it grow if needed on screen */\r\n            background: #fff;\r\n            padding: 12mm 15mm; /* Tightened padding to fit more content safely */\r\n            box-shadow: 0 10px 25px rgba(0,0,0,0.1);\r\n            margin: 20px 0;\r\n            display: flex; /* Flexbox prevents overlapping */\r\n            flex-direction: column;\r\n        }\r\n\r\n        @media print {\r\n            body { background: #fff; display: block; margin: 0; }\r\n            .document-container { \r\n                margin: 0; \r\n                box-shadow: none; \r\n                width: 100%; \r\n                min-height: 100vh;\r\n                padding: 10mm 15mm; \r\n                display: flex;\r\n                flex-direction: column;\r\n            }\r\n            @page { size: A4; margin: 0; }\r\n        }\r\n\r\n        /* Typography & Layout */\r\n        h1, h2, h3, p { margin: 0; }\r\n        .text-center { text-align: center; }\r\n        \r\n        /* Header - Colorized */\r\n        .header {\r\n            background: linear-gradient(to right, var(--primary-dark), var(--primary-blue));\r\n            color: white;\r\n            padding: 15px 20px;\r\n            border-radius: 6px;\r\n            display: flex;\r\n            justify-content: space-between;\r\n            align-items: center;\r\n            margin-bottom: 15px;\r\n        }\r\n        .header .agency-branding {\r\n            display: flex;\r\n            align-items: center;\r\n            gap: 15px;\r\n        }\r\n        .header .agency-logo {\r\n            max-height: 55px;\r\n            max-width: 120px;\r\n            object-fit: contain;\r\n            border-radius: 4px;\r\n        }\r\n        .header .agency-details h1 {\r\n            font-size: 24px;\r\n            text-transform: uppercase;\r\n            letter-spacing: 1px;\r\n            color: #fff;\r\n            margin: 0 0 3px 0;\r\n        }\r\n        .header .agency-details .agency-contact {\r\n            color: #93c5fd;\r\n            font-size: 11px;\r\n            letter-spacing: 0.3px;\r\n            line-height: 1.85;\r\n        }\r\n        .header .meta-details {\r\n            font-size: 12px;\r\n            text-align: right;\r\n            background: rgba(255,255,255,0.1);\r\n            padding: 8px 12px;\r\n            border-radius: 4px;\r\n        }\r\n\r\n        .doc-title {\r\n            color: var(--primary-blue);\r\n            font-size: 20px;\r\n            font-weight: bold;\r\n            text-transform: uppercase;\r\n            letter-spacing: 1px;\r\n            border-bottom: 2px solid var(--primary-blue);\r\n            display: inline-block;\r\n            padding-bottom: 4px;\r\n            margin: 5px 0 10px 0; /* Tighter margins */\r\n        }\r\n\r\n        /* Sections - Colorized */\r\n        .section-title {\r\n            background-color: var(--accent-blue);\r\n            color: var(--primary-blue);\r\n            padding: 5px 8px; /* Tighter padding */\r\n            font-size: 13px;\r\n            font-weight: bold;\r\n            border-left: 4px solid var(--primary-blue);\r\n            margin: 10px 0 5px 0; /* Tighter margins */\r\n            text-transform: uppercase;\r\n            border-radius: 0 4px 4px 0;\r\n        }\r\n\r\n        /* Tables for Data */\r\n        table {\r\n            width: 100%;\r\n            border-collapse: collapse;\r\n            font-size: 12px; /* Optimized for single page */\r\n            margin-bottom: 5px;\r\n        }\r\n        table th, table td {\r\n            border: 1px solid var(--border-color);\r\n            padding: 4px 6px; /* Tighter padding to save vertical space */\r\n            vertical-align: middle;\r\n        }\r\n        table th {\r\n            background-color: #f8fafc;\r\n            color: var(--primary-dark);\r\n            text-align: left;\r\n            width: 20%;\r\n            font-size: 11px;\r\n            text-transform: uppercase;\r\n        }\r\n        table td {\r\n            color: #000;\r\n        }\r\n\r\n        /* Highlight specific clauses */\r\n        .highlight-clause th, .highlight-clause td {\r\n            background-color: var(--highlight-bg);\r\n            border-color: var(--highlight-border);\r\n            color: #92400e;\r\n        }\r\n\r\n        /* Terms & Conditions */\r\n        .terms-list {\r\n            padding-left: 15px;\r\n            font-size: 11px;\r\n            text-align: justify;\r\n            margin: 0;\r\n            color: #000;\r\n        }\r\n        .terms-list li { margin-bottom: 4px; } /* Tighter margins */\r\n\r\n        /* Signatures */\r\n        .signature-section {\r\n            display: flex;\r\n            justify-content: space-between;\r\n            margin-top: 60px; /* Increased significantly for comfortable signing space */\r\n            margin-bottom: 20px;\r\n        }\r\n        .signature-box {\r\n            width: 30%;\r\n            text-align: center;\r\n        }\r\n        .signature-line {\r\n            border-top: 1.5px solid var(--primary-dark);\r\n            padding-top: 5px;\r\n            font-weight: bold;\r\n            font-size: 12px;\r\n            color: var(--primary-dark);\r\n        }\r\n        .signature-box p {\r\n            font-size: 10px;\r\n            color: var(--text-dark);\r\n            margin-top: 3px;\r\n        }\r\n\r\n        /* Footer */\r\n        .footer {\r\n            margin-top: auto; /* Pushes footer neatly to the very bottom */\r\n            padding-top: 10px;\r\n            border-top: 1px solid var(--border-color);\r\n            text-align: center;\r\n            font-size: 10px;\r\n            color: #64748b;\r\n        }\r\n    </style>\r\n<style type=\"text/css\" id=\"wv-urdu-font-definitions\">\n@font-face {\n    font-family: \'Jameel Noori Nastaleeq\';\n    src: url(\'/whitevillas/fonts/JameelNooriNastaleeq.ttf\') format(\'truetype\'),\n         url(\'/fonts/JameelNooriNastaleeq.ttf\') format(\'truetype\'),\n         url(\'../fonts/JameelNooriNastaleeq.ttf\') format(\'truetype\');\n    font-weight: normal;\n    font-style: normal;\n    font-display: swap;\n}\n@font-face {\n    font-family: \'Jameel Noori Nastaleeq Kasheeda\';\n    src: url(\'/whitevillas/fonts/JameelNooriNastaleeqKasheeda.ttf\') format(\'truetype\'),\n         url(\'/fonts/JameelNooriNastaleeqKasheeda.ttf\') format(\'truetype\'),\n         url(\'../fonts/JameelNooriNastaleeqKasheeda.ttf\') format(\'truetype\');\n    font-weight: normal;\n    font-style: normal;\n    font-display: swap;\n}\n*, *:before, *:after {\n    -webkit-print-color-adjust: exact !important;\n    print-color-adjust: exact !important;\n    color-adjust: exact !important;\n}\n[lang=\"ur\"], [dir=\"rtl\"], .urdu-text, .ashtam-page, .letter-ur, .urdu-body, .urdu-legal {\n    font-family: \'Jameel Noori Nastaleeq\', \'Noto Nastaliq Urdu\', \'Nafees Nastaleeq\', serif !important;\n    line-height: 1.85 !important;\n    letter-spacing: 0 !important;\n    word-spacing: 0 !important;\n}\n[lang=\"ur\"] h1, [lang=\"ur\"] h2, [lang=\"ur\"] h3, [lang=\"ur\"] h4, [lang=\"ur\"] h5, [lang=\"ur\"] h6,\n[dir=\"rtl\"] h1, [dir=\"rtl\"] h2, [dir=\"rtl\"] h3, [dir=\"rtl\"] h4, [dir=\"rtl\"] h5, [dir=\"rtl\"] h6,\n.ashtam-page h1, .ashtam-page h2, .ashtam-page h3, .ashtam-page h4,\n.urdu-heading, .ashtam-heading, .document-title, .document-subtitle, .section-title, .sign-title, .bismillah {\n    font-family: \'Jameel Noori Nastaleeq Kasheeda\', \'Jameel Noori Nastaleeq\', \'Noto Nastaliq Urdu\', serif !important;\n    font-weight: normal !important;\n    line-height: 1.5 !important;\n}\n[lang=\"ur\"] p, [lang=\"ur\"] li, [lang=\"ur\"] td, [lang=\"ur\"] th, [lang=\"ur\"] span,\n[dir=\"rtl\"] p, [dir=\"rtl\"] li, [dir=\"rtl\"] td, [dir=\"rtl\"] th, [dir=\"rtl\"] span,\n.ashtam-page p, .ashtam-page li, .ashtam-page td, .ashtam-page th,\n.urdu-body p, .clause, .note-box, .amount-box {\n    font-family: \'Jameel Noori Nastaleeq\', \'Noto Nastaliq Urdu\', \'Nafees Nastaleeq\', serif !important;\n    line-height: 1.85 !important;\n}\n@media print {\n    @page { size: auto; margin: 0; }\n    html, body {\n        background: #ffffff !important;\n        color: #000000 !important;\n        margin: 0 !important;\n        padding: 0 !important;\n    }\n    .ashtam-page, .page, .form-container, .container, .letter-preview-print {\n        margin: 0 auto !important;\n        box-shadow: none !important;\n        -webkit-print-color-adjust: exact !important;\n        print-color-adjust: exact !important;\n        color-adjust: exact !important;\n    }\n}\n</style></head>\r\n<body>\r\n\r\n<div class=\"document-container\">\r\n    \r\n    <!-- Agency Header -->\r\n    <div class=\"header\">\r\n        <div class=\"agency-branding\">\r\n            <!-- If the logo URL is empty or broken, it will automatically hide to keep the layout clean -->\r\n            <img src=\"{{agency_logo_url}}\" alt=\"Agency Logo\" class=\"agency-logo\" onerror=\"this.style.display=\'none\'\">\r\n            <div class=\"agency-details\">\r\n                <h1>{{agency_name}}</h1>\r\n                <div class=\"agency-contact\">\r\n                    {{agency_address}}<br>\r\n                    Ph: {{agency_phone}} | Email: {{agency_email}}\r\n                </div>\r\n            </div>\r\n        </div>\r\n        <div class=\"meta-details\">\r\n            <strong>Agreement:</strong> {{agreement_no}}<br>\r\n            <strong>Date:</strong> {{letter_date}}<br>\r\n            <strong>Deal Ref:</strong> {{deal_invoice_no}}\r\n        </div>\r\n    </div>\r\n\r\n    <div class=\"text-center\">\r\n        <div class=\"doc-title\">Tenancy Agreement</div>\r\n    </div>\r\n    \r\n    <p style=\"text-align: justify; font-size: 12px; margin-bottom: 10px; color: #000;\">\r\n        This Tenancy Agreement is executed on <strong>{{letter_date}}</strong> by and between the Property Owner and the Tenant named below, facilitated by <strong>{{agency_name}}</strong>.\r\n    </p>\r\n\r\n    <!-- Owner Details -->\r\n    <div class=\"section-title\">1. Property Owner Information</div>\r\n    <table>\r\n        <tr>\r\n            <th>Owner Name</th>\r\n            <td colspan=\"3\"><strong>{{client_name}}</strong></td>\r\n        </tr>\r\n        <tr>\r\n            <th>CNIC Number</th>\r\n            <td>{{client_cnic}}</td>\r\n            <th>Contact Mobile</th>\r\n            <td>{{client_mobile}} / {{client_phone}}</td>\r\n        </tr>\r\n        <tr>\r\n            <th>Email Address</th>\r\n            <td>{{client_email}}</td>\r\n            <th>Current Address</th>\r\n            <td>{{client_address}}</td>\r\n        </tr>\r\n    </table>\r\n\r\n    <!-- Tenant Details -->\r\n    <div class=\"section-title\">2. Tenant Information</div>\r\n    <table>\r\n        <tr>\r\n            <th>Tenant Name</th>\r\n            <td colspan=\"3\"><strong>{{tenant_name}}</strong></td>\r\n        </tr>\r\n        <tr>\r\n            <th>CNIC Number</th>\r\n            <td>{{tenant_cnic}}</td>\r\n            <th>Contact Mobile</th>\r\n            <td>{{tenant_mobile}}</td>\r\n        </tr>\r\n        <tr>\r\n            <th>Email Address</th>\r\n            <td>{{tenant_email}}</td>\r\n            <th>Current Address</th>\r\n            <td>{{tenant_address}}</td>\r\n        </tr>\r\n    </table>\r\n\r\n    <!-- Property Details -->\r\n    <div class=\"section-title\">3. Property Details</div>\r\n    <table>\r\n        <tr>\r\n            <th>Project Name</th>\r\n            <td colspan=\"3\"><strong>{{project_name}}</strong></td>\r\n        </tr>\r\n        <tr>\r\n            <th>Property Name</th>\r\n            <td>{{property_name}}</td>\r\n            <th>File No.</th>\r\n            <td>{{property_file}}</td>\r\n        </tr>\r\n        <tr>\r\n            <th>Property Type</th>\r\n            <td>{{property_type}}</td>\r\n            <th>Area / Unit</th>\r\n            <td>{{property_area}} {{property_unit}}</td>\r\n        </tr>\r\n        <tr>\r\n            <th>Contract Type</th>\r\n            <td>{{property_contract}}</td>\r\n            <th>Property Value</th>\r\n            <td>{{property_price}}</td>\r\n        </tr>\r\n    </table>\r\n\r\n    <!-- Financials & Term -->\r\n    <div class=\"section-title\">4. Tenancy Term & Financials</div>\r\n    <table>\r\n        <tr>\r\n            <th>Contract Period</th>\r\n            <td colspan=\"3\">From <strong>{{start_date}}</strong> to <strong>{{end_date}}</strong></td>\r\n        </tr>\r\n        <tr>\r\n            <th>Monthly Rent</th>\r\n            <td><strong>{{monthly_rent}}</strong></td>\r\n            <th>Due Date</th>\r\n            <td>The <strong>{{due_day}}</strong> of each month</td>\r\n        </tr>\r\n        <tr>\r\n            <th>Security Deposit</th>\r\n            <td colspan=\"3\"><strong>{{security_deposit}}</strong> (Refundable upon termination)</td>\r\n        </tr>\r\n        <tr class=\"highlight-clause\">\r\n            <th>Special Adjustment</th>\r\n            <td colspan=\"3\"><strong>It is mutually agreed that the monthly rent of {{monthly_rent}} shall be adjusted directly towards the Tenant\'s ongoing property installments managed by {{agency_name}}.</strong></td>\r\n        </tr>\r\n    </table>\r\n\r\n    <!-- Terms & Conditions Boilerplate -->\r\n    <div class=\"section-title\">5. Standard Terms & Conditions</div>\r\n    <ul class=\"terms-list\">\r\n        <li><strong>Rent Adjustment Clause:</strong> The Tenant agrees to a monthly rent of {{monthly_rent}}. This amount acts as a credit towards the Tenant\'s monthly property installments payable to {{agency_name}} and will not be collected in cash.</li>\r\n        <li><strong>Utility Bills:</strong> The Tenant shall be solely responsible for the timely payment of all utility bills (electricity, water, gas, maintenance) consumed during the tenancy.</li>\r\n        <li><strong>Maintenance:</strong> The Tenant shall keep the premises clean. Structural repairs are the Landlord\'s responsibility; minor repairs fall to the Tenant.</li>\r\n        <li><strong>Usage & Termination:</strong> The property shall be used exclusively for agreed purposes without subletting. Either party may terminate with a one-month prior written notice.</li>\r\n    </ul>\r\n\r\n    <!-- Signatures -->\r\n    <div class=\"signature-section\">\r\n        <div class=\"signature-box\">\r\n            <div class=\"signature-line\">Property Owner</div>\r\n            <p>{{client_name}}<br>CNIC: {{client_cnic}}</p>\r\n        </div>\r\n        <div class=\"signature-box\">\r\n            <div class=\"signature-line\">Tenant Signature</div>\r\n            <p>{{tenant_name}}<br>CNIC: {{tenant_cnic}}</p>\r\n        </div>\r\n        <div class=\"signature-box\">\r\n            <div class=\"signature-line\">Authorized Agency</div>\r\n            <p>For: {{agency_name}}</p>\r\n        </div>\r\n    </div>\r\n\r\n    <!-- Printable Footer -->\r\n    <div class=\"footer\">\r\n        Generated by {{agency_name}} Property Management System | Deal Ref: {{deal_invoice_no}} | Validated Document\r\n    </div>\r\n\r\n</div>\r\n\r\n</body>\r\n</html>', 'RLT_RENTAL_AGREEMENT', 'Published', 'Yes', '', 'letter_signatures', '', 'letter_signatures');
INSERT INTO `templates` (`id`, `name`, `description`, `type`, `status`, `is_new`, `ceo_signature`, `ceo_signature_dir`, `chairman_signature`, `chairman_signature_dir`) VALUES
(37, 'Rental Receipt', '<style type=\"text/css\" id=\"wv-urdu-font-definitions\">\n@font-face {\n    font-family: \'Jameel Noori Nastaleeq\';\n    src: url(\'/whitevillas/fonts/JameelNooriNastaleeq.ttf\') format(\'truetype\'),\n         url(\'/fonts/JameelNooriNastaleeq.ttf\') format(\'truetype\'),\n         url(\'../fonts/JameelNooriNastaleeq.ttf\') format(\'truetype\');\n    font-weight: normal;\n    font-style: normal;\n    font-display: swap;\n}\n@font-face {\n    font-family: \'Jameel Noori Nastaleeq Kasheeda\';\n    src: url(\'/whitevillas/fonts/JameelNooriNastaleeqKasheeda.ttf\') format(\'truetype\'),\n         url(\'/fonts/JameelNooriNastaleeqKasheeda.ttf\') format(\'truetype\'),\n         url(\'../fonts/JameelNooriNastaleeqKasheeda.ttf\') format(\'truetype\');\n    font-weight: normal;\n    font-style: normal;\n    font-display: swap;\n}\n*, *:before, *:after {\n    -webkit-print-color-adjust: exact !important;\n    print-color-adjust: exact !important;\n    color-adjust: exact !important;\n}\n[lang=\"ur\"], [dir=\"rtl\"], .urdu-text, .ashtam-page, .letter-ur, .urdu-body, .urdu-legal {\n    font-family: \'Jameel Noori Nastaleeq\', \'Noto Nastaliq Urdu\', \'Nafees Nastaleeq\', serif !important;\n    line-height: 1.85 !important;\n    letter-spacing: 0 !important;\n    word-spacing: 0 !important;\n}\n[lang=\"ur\"] h1, [lang=\"ur\"] h2, [lang=\"ur\"] h3, [lang=\"ur\"] h4, [lang=\"ur\"] h5, [lang=\"ur\"] h6,\n[dir=\"rtl\"] h1, [dir=\"rtl\"] h2, [dir=\"rtl\"] h3, [dir=\"rtl\"] h4, [dir=\"rtl\"] h5, [dir=\"rtl\"] h6,\n.ashtam-page h1, .ashtam-page h2, .ashtam-page h3, .ashtam-page h4,\n.urdu-heading, .ashtam-heading, .document-title, .document-subtitle, .section-title, .sign-title, .bismillah {\n    font-family: \'Jameel Noori Nastaleeq Kasheeda\', \'Jameel Noori Nastaleeq\', \'Noto Nastaliq Urdu\', serif !important;\n    font-weight: normal !important;\n    line-height: 1.5 !important;\n}\n[lang=\"ur\"] p, [lang=\"ur\"] li, [lang=\"ur\"] td, [lang=\"ur\"] th, [lang=\"ur\"] span,\n[dir=\"rtl\"] p, [dir=\"rtl\"] li, [dir=\"rtl\"] td, [dir=\"rtl\"] th, [dir=\"rtl\"] span,\n.ashtam-page p, .ashtam-page li, .ashtam-page td, .ashtam-page th,\n.urdu-body p, .clause, .note-box, .amount-box {\n    font-family: \'Jameel Noori Nastaleeq\', \'Noto Nastaliq Urdu\', \'Nafees Nastaleeq\', serif !important;\n    line-height: 1.85 !important;\n}\n@media print {\n    @page { size: auto; margin: 0; }\n    html, body {\n        background: #ffffff !important;\n        color: #000000 !important;\n        margin: 0 !important;\n        padding: 0 !important;\n    }\n    .ashtam-page, .page, .form-container, .container, .letter-preview-print {\n        margin: 0 auto !important;\n        box-shadow: none !important;\n        -webkit-print-color-adjust: exact !important;\n        print-color-adjust: exact !important;\n        color-adjust: exact !important;\n    }\n}\n</style><style>\n.rental-receipt{background:#fff;box-sizing:border-box;color:#111;font-family:Arial,Helvetica,sans-serif;margin:0 auto;max-width:190mm;min-height:265mm;padding:8mm;width:100%}\n.rental-receipt *{box-sizing:border-box}\n.rental-receipt-header{align-items:center;border-bottom:2px solid #111;display:grid;gap:14px;grid-template-columns:115px minmax(0,1fr) 115px;padding-bottom:12px}\n.rental-receipt-logo{text-align:left}.rental-receipt-logo img{height:100px;max-width:110px;object-fit:contain;width:110px}\n.rental-receipt-heading{text-align:center}.rental-receipt-heading h1{font-size:25px;letter-spacing:0;margin:0 0 5px}.rental-receipt-heading p{font-size:12px;line-height:1.85;margin:1px 0}\n.rental-receipt-qr{text-align:right}.rental-receipt-qr img{border:1px solid #333;height:105px;padding:3px;width:105px}\n.rental-receipt-title{border-bottom:1px solid #111;font-size:16px;font-weight:900;margin:12px 0 8px;padding:5px;text-align:center}\n.rental-receipt-meta{border-collapse:collapse;margin-bottom:8px;width:100%}.rental-receipt-meta td{font-size:14px;padding:5px 4px;vertical-align:top}.rental-receipt-meta td:last-child{text-align:right}\n.rental-receipt-grid{border-collapse:collapse;table-layout:fixed;width:100%}.rental-receipt-grid td{border:1px solid #777;font-size:14px;line-height:1.85;padding:8px;vertical-align:top}.rental-receipt-grid strong{display:block;font-size:11px;margin-bottom:3px;text-transform:uppercase}\n.rental-receipt-amount{background:#f2f5f8;border:2px solid #111!important;font-size:19px!important;font-weight:900;text-align:center}\n.rental-receipt-words{font-size:14px!important;font-weight:700}\n.rental-receipt-summary{border-collapse:collapse;margin-top:12px;table-layout:fixed;width:100%}.rental-receipt-summary td{border:1px solid #9aa7b5;padding:8px;text-align:center}.rental-receipt-summary strong{display:block;font-size:10px;text-transform:uppercase}.rental-receipt-summary span{display:block;font-size:14px;font-weight:900;margin-top:3px}\n.rental-receipt-note{border-top:1px solid #aeb8c4;font-size:11px;line-height:1.5;margin-top:14px;padding-top:8px;text-align:center}\n.rental-receipt-signatures{border-collapse:collapse;margin-top:65px;width:100%}.rental-receipt-signatures td{border-top:1px solid #111;font-size:12px;font-weight:800;padding-top:7px;text-align:center;width:33.333%}\n@media print{.rental-receipt{margin:0;max-width:none;min-height:0;padding:0;width:100%}}\n</style>\n<div class=\"rental-receipt\">\n    <div class=\"rental-receipt-header\">\n        <div class=\"rental-receipt-logo\">{{agency_logo}}</div>\n        <div class=\"rental-receipt-heading\">\n            <h1>{{agency_name}}</h1>\n            <p>{{agency_address}}</p>\n            <p>{{agency_contact}}</p>\n        </div>\n        <div class=\"rental-receipt-qr\">{{receipt_qr}}</div>\n    </div>\n\n    <div class=\"rental-receipt-title\">RENTAL PAYMENT RECEIPT</div>\n    <table class=\"rental-receipt-meta\">\n        <tr>\n            <td><strong>Receipt Number:</strong> {{receipt_no}}</td>\n            <td><strong>Payment Date:</strong> {{receipt_date}}</td>\n        </tr>\n        <tr>\n            <td><strong>Rental Agreement:</strong> {{agreement_no}}</td>\n            <td><strong>Rent Month:</strong> {{rent_month_label}}</td>\n        </tr>\n    </table>\n\n    <table class=\"rental-receipt-grid\">\n        <tr>\n            <td><strong>Received From</strong>{{tenant_name}}</td>\n            <td><strong>Client</strong>{{client_name}}</td>\n        </tr>\n        <tr>\n            <td><strong>Property</strong>{{property_name}}</td>\n            <td><strong>Membership Number</strong>{{deal_invoice_no}}</td>\n        </tr>\n        <tr>\n            <td><strong>Payment Through</strong>{{payment_mode}}</td>\n            <td><strong>Reference / Remarks</strong>{{payment_reference}}</td>\n        </tr>\n        <tr><td colspan=\"2\"><strong>Allocated Rent Months</strong>{{allocated_months}}</td></tr>\n        <tr><td colspan=\"2\" class=\"rental-receipt-amount\">Amount Received: {{rent_amount}}</td></tr>\n        <tr><td colspan=\"2\" class=\"rental-receipt-words\"><strong>Amount in Words</strong>{{rent_amount_words}}</td></tr>\n        <tr>\n            <td><strong>Rental Expense</strong>{{expense_amount}}</td>\n            <td><strong>Net Rental Income</strong>{{net_amount}}</td>\n        </tr>\n    </table>\n\n    <table class=\"rental-receipt-summary\">\n        <tr>\n            <td><strong>Total Rent Received</strong><span>{{total_rent_paid}}</span></td>\n            <td><strong>Outstanding Rent</strong><span>{{outstanding_rent}}</span></td>\n            <td><strong>Overdue Rent</strong><span>{{overdue_rent}}</span></td>\n            <td><strong>Advance Credit</strong><span>{{advance_credit}}</span></td>\n        </tr>\n    </table>\n\n    <div class=\"rental-receipt-note\">This is a system-generated rental payment receipt. Please retain it for your records.</div>\n    <table class=\"rental-receipt-signatures\"><tr><td>Received By</td><td>Tenant Signature</td><td>Authorized Signature</td></tr></table>\n</div>\n', 'RLT_RENTAL_RECEIPT', 'Published', 'No', '', 'letter_signatures', '', 'letter_signatures');
