(1, 1, NULL, 3, 'White Villas', 'admin', '$2y$10$OTrqE5VTtm8e5DnwXK7e3uoUcsoua0WRWky.l/GZuvVgh81oLVDlu', '03114432729', '03114432729', '49 AA Commercial', 'riazmushtaq.com@gmail.com', '', '', '', '', '', '', 'ac261196d2fe71ceb6e33168e1edab31.png', 'Active', 'Active', 'On', 0, '1955721092', NULL, '2014-04-01 21:08:06', '2026-09-10 11:13:19'),
(26, 4, 20, 6, 'White Villas Lahore', 'whitevillas', 'ad972dce50b0a0aead7b83c0ecdb8a268007dd1424a7da3d6dd5612ddc4358ac', '+923391101156', '+923391101156', 'Maraka Multan Road Lahore', 'info@whitevillas.com.pk', '', 'https://www.facebook.com/WhiteVillas.com.PK', 'whitevillas', '', 'White Villas Lahore - Luxurious Living at Its Best\r\n\r\nWhite Villas Lahore offers an exceptional blend of modern architecture, serene surroundings, and premium amenities, providing residents with a luxurious lifestyle in the heart of Lahore. Located in a prime area, White Villas stands out for its carefully designed homes, affordability, and high-quality infrastructure, catering to families who seek comfort and elegance.\r\n\r\nKey Features:\r\nPrime Location: Situated in an ideal area with easy access to major landmarks and highways of Lahore.\r\nModern Design: Each villa is thoughtfully designed, blending contemporary aesthetics with functional living spaces.\r\nGated Community: Provides a safe and secure environment with 24/7 surveillance, ensuring peace of mind for families.\r\nAffordable Luxury: High-end living spaces with flexible payment plans, making it accessible for a wide range of buyers.\r\nTop-Notch Amenities: Parks, playgrounds, commercial areas, and community centers ensure all your lifestyle needs are met within the project.\r\nEco-Friendly Environment: Beautifully landscaped surroundings with green spaces for a refreshing living experience.\r\nWhether you\'re looking for a peaceful retreat or a vibrant community, White Villas Lahore is your gateway to an upscale living experience in one of Lahore’s most sought-after residential projects.', '', '53be1588b81b27771e273fa58c9a2709.png', 'Active', 'Active', 'On', 0, NULL, NULL, '2023-05-22 22:54:48', '2026-06-07 11:06:01'),
(29, 2, 20, 6, 'Ch Riaz Ahmad', 'riazahmad', '4106aeda14a6e52138702367b9499a0202211ebed038a8420d8e6b599c93cec4', '+9233074432729', '+923114432729', '49 AA Commercial Sector D Bahria Town Lahore', 'chriazmushtaq@gmail.com', '', '', '', '', 'For all your Capital Island City real estate needs, don\'t hesitate to reach out. Let\'s embark on this exciting journey together as you discover the perfect property that embodies the essence of this remarkable city. Contact me today to schedule a consultation, and let\'s make your real estate aspirations come true.', '', '4733bbe645543a0e414b3c7ed6146591.jpg', 'Active', 'Active', 'On', 1, NULL, NULL, '2023-07-09 23:49:38', '2026-11-23 06:39:42'),
(36, 2, 20, 6, 'Nouman Tariq', 'NOUMAN', '4bf5a936912bf2bb53676373be4835831234339c3385d5c848799e28ab16eb04', '+923008148465', '+923008148465', 'BAHRIA TOWN LAHORE', '', '', '', '', '', '', NULL, NULL, 'Suspend', 'Active', 'Off', 17, NULL, NULL, '2023-12-07 00:28:47', '2026-07-08 18:55:10'),
(37, 2, 20, 6, 'Titanium Properties ', 'Titanium', '6b8bb1e56b4343a696b15c13a0f14d1b8669775a33bb0ca0121898aa6638f5b3', '+9203100004027', '+9203100004027', '92-B Commercial Sector E Bahria Town Lahore', 'info@titaniumproperties.pk', '', 'https://www.facebook.com/titaniumpropertiespk', 'https://twitter.com/Titanium_Prop', 'https://www.instagram.com/titaniumpropertiespk/', 'At Titanium Properties Private Limited, we provide premier property management services tailored to meet your needs. From tenant screening and lease administration to maintenance coordination and rent collection, we handle the complexities of property management while maximizing your returns.', NULL, '4069a8e7d92253c3cfe052dc0cce1a32.png', 'Active', 'Active', 'On', 9, NULL, NULL, '2023-12-20 19:50:55', '2026-07-08 18:55:23'),
(39, 2, 20, 6, 'Titanium Agency', 'absar', '962d35362e488c41cedf30b23ce8329c9a5552aca7b82fee5d116a5839b9ca89', '+923100001038', '+923100001038', '163/A Commercial zone Titanium Agency sector C bahria town lhr', 'Absarnisar007@gmail.com', '', 'https://www.facebook.com/titaniumagency.com.pk', 'https://twitter.com/TitaniumAgency', '', 'If you wish to buy or sell a property whether it be residential or commercial, then you have come to right place. Titanium agency is a group of seasoned professionals having vast experience in this field, we guide our customers in making right investment decisions keeping in view their budget.\r\n\r\nTitaniumAgency.com.pk\r\nTitaniumConsultancy.com\r\nTitaniumProperties.net', NULL, 'b0f97ce9daa685df23624208ca663fb7.png', 'Active', 'Active', 'On', 6, NULL, NULL, '2024-01-23 13:21:43', '2026-07-08 18:54:35'),
