INSERT INTO `whatsapp_settings` (`id`, `is_active`, `phone_number_id`, `waba_id`, `access_token`, `api_version`, `notify_fb_agent`, `notify_fb_client`, `notify_deals`, `notify_letters`, `notify_followups`, `template_fb_agent`, `template_fb_client`, `template_deals`, `template_letters`, `template_followups`, `total_sent`, `total_failed`, `created`, `modified`) VALUES
(1, 1, '', '', '', 'v19.0', 1, 1, 1, 1, 1, '🔔 *WV CRM: New Facebook Lead Assigned!*\n\n👤 *Client:* {lead_name}\n📞 *Mobile:* {lead_mobile}\n🏢 *Page / Brand:* {page_name}\n🏡 *Project:* {project_name}\n📋 *Form:* {form_name}\n💬 *Inquiry:* {lead_remarks}\n\n🔗 *Open in CRM:* {crm_link}\n⚡ *Please contact immediately!*', '✨ *Welcome to {agency_name}!* ✨\n\nDear *{lead_name}*,\n\nThank you for your inquiry on Facebook regarding *{project_name}*! We are delighted to assist you with complete project details, brochures, and flexible installment plans.\n\n🎖️ *Your Dedicated Property Advisor:*\n👤 *{agent_name}*\n📞 *Direct Call:* {agent_mobile}\n💬 *Direct WhatsApp:* {agent_whatsapp_link}\n\nOur team will connect with you shortly to assist with your booking and arrange an exclusive site visit.\n\n🌐 {agency_domain}\n📍 {agency_address}', '🎉 *WV CRM - Deal Booking Milestone Update!*\n\nDear *{client_name}*,\n\nCongratulations! Your deal booking for *{project_name}* (Unit / Plot: *{deal_unit}*) has progressed to: *{deal_stage}*.\n\n💰 *Deal Value:* {deal_amount}\n👤 *Sales Consultant:* {agent_name} ({agent_mobile})\n\nThank you for choosing {agency_name}!\n📞 {agency_phone} | 🌐 {agency_domain}', '📄 *WV CRM - Official Document / Receipt Issued*\n\nDear *{client_name}*,\n\nAn official document (*{letter_type}*) has been generated for your property in *{project_name}*.\n\n🧾 *Receipt / Ref No:* {receipt_no}\n📅 *Issue Date:* {date_time}\n\nPlease visit the customer portal or contact your advisor *{agent_name}* ({agent_mobile}) for assistance.\n\n📍 {agency_name} &bull; {agency_address}', '⏰ *WV CRM - Scheduled Follow-Up Reminder*\n\nHello *{agent_name}*,\n\nYou have a scheduled follow-up for client *{lead_name}* ({lead_mobile}) regarding *{project_name}*.\n\n📝 *Notes:* {lead_remarks}\n🔗 *Open Lead:* {crm_link}', 0, 0, '2026-09-02 17:46:00', '2026-09-02 17:46:00');
